Object.assign(window.__LB,{"25000": ["病机", "原文列举疟疾脉象：脉浮恶寒为邪在表，脉洪数长实为热盛，脉沉实为邪内结，脉细缓芤微为虚象，脉洪实如旧示病未退。此段讨论外感疟与内伤疟之别，脉象反映邪之深浅与正气盛衰，浮主表，洪数主热，沉实主里实，细缓芤微主正虚。", ["浮", "洪", "数", "沉"]], "25001": ["病机", "左脉浮紧主太阳寒湿，右脉浮大主阳明寒湿，寒湿内伏则脉沉紧，少阳受邪则脉弦紧。脉浮紧为寒湿在表，沉紧为寒湿内伏，弦紧为少阳寒湿之象，说明寒湿痢之病机与邪客部位相关。", ["浮", "紧", "大", "弦"]], "25002": ["治法", "身痛发热脉浮紧，为寒湿在表，宜败毒散辛温散表；呕吐饱闷脉长，为胃气不和，宜干葛平胃散和胃宽胸。脉浮紧主表寒，脉长主胃有壅滞，故寒湿痢必先表散，使邪从表出，不可早用寒凉。", ["浮", "紧", "长"]], "25003": ["病机", "湿热痢脉必数大，浮数主表热，沉数主里热，洪大伤气，细数伤血。数主热，大主邪盛，浮沉分表里，洪细辨气血，说明湿热痢之病机为热邪充斥，表里气血皆可受累。", ["数", "大", "浮", "沉"]], "25004": ["病机", "燥热痢脉必洪数，浮数伤表，沉数伤里，洪数伤气，细数伤血，浮沉皆数则气血皆伤。洪数主燥热炽盛，浮沉分表里，洪细辨气血，说明燥热之邪伤及表里气血，病机为燥热内盛。", ["洪", "数", "浮", "沉"]], "25005": ["病机", "寒湿所伤脉多濡散，或见微迟，或一手脉伏；脉若洪数，为湿热之邪；脉若躁疾，为燥火之诊。濡散微迟主寒湿，洪数主湿热，躁疾主燥火，说明疫痢脉象随病邪性质而异，病机有寒湿、湿热、燥火之别。", ["濡", "散", "伏", "洪"]], "25006": ["治法", "寒湿脉微者用人参败毒散，脉伏者用升麻葛根汤升阳发散，使脉自起；湿热脉洪用香连丸、六一散；燥火脉数用当归银花汤等。脉微主正虚寒湿，脉伏主邪遏阳气，洪数主湿热燥火，治法随脉而异。", ["微", "伏", "洪", "数"]], "25007": ["预后", "内伤痢身热脉大者死，外感痢身热脉大者吉，沉细虚小者凶；寸脉沉而迟主厥阴动而泻痢，手足厥逆。脉大主邪盛，内伤正虚故死，外感邪实故吉；沉细虚小为正虚，故凶；沉迟为阳郁，主表邪缩内。", ["大", "沉", "迟", "细"]], "25008": ["预后", "七情内伤致痢，脉必重虚，虚大则气伤，虚细则血亏，虚缓为胃气尚存故生，弦大则木贼土败故死。弦而有胃即弦中带缓，尚可挽回；弦多无胃则真脏脉见，必死不活，此以脉之胃气有无判预后。", ["虚", "大", "细", "缓"]], "25009": ["预后", "劳役伤脾致痢，脉必见虚损。虚数伤血，虚大伤气，皆虚损之象。虚缓者脾阳未败故生，数实者邪热内炽、正气已亏故死，以虚实并见之数实脉判其危候。", ["虚", "数", "大", "实"]], "25010": ["治法", "本段为随症加减用药之法，非论脉。筋脉痛加秦艽、续断以通络舒筋；中气弱加人参、白术以补脾益气；气满加陈皮、木香以理气宽中，皆据症施治，与脉象无涉。", []], "25011": ["病机", "饮食内伤致痢，脉多见滑大，或见弦紧。滑大主实积内停，弦紧主积滞不畅；若弦小而无力，则为虚滞，非实积可比。以脉之滑大与弦小辨积之虚实。", ["滑", "大", "弦", "紧"]], "25012": ["病机", "外感休息痢脉见涩，主气凝积滞；沉滑主食积未彻；沉数主内有积热；沉弦主脾伤气血。四脉皆沉，示病在里，涩、滑、数、弦各主气滞、食积、积热、脾伤之不同病机。", ["涩", "沉", "滑", "数"]], "25013": ["治法", "承上段脉象施治：脉涩滞者用和气四七汤行气，脉沉滑者用香连丸行积，脉沉数者用泼火散清积热，脉沉弦者用枳术汤合保和丸助脾消积。久痢下纯血者用家秘独圣散，皆据脉定方。", ["涩", "沉", "滑", "数"]], "25014": ["病机", "内伤休息痢脉见弦细，主思虑所伤；虚大主脾气亏损；细涩主脾血有伤；沉弦主食积伤脾；迟弦主寒凉伤损。诸脉皆内伤之象，以弦细、虚大、细涩、沉弦、迟弦分述思虑、气亏、血伤、食积、寒伤之病机。", ["弦", "细", "虚", "大"]], "25015": ["病机", "风泻之脉多浮而弦。左关浮弦为风木之邪犯肝，大肠脉浮乃肠风之诊，右关脉浮为胃风之候。浮主风邪在表，弦主风木劲急，以浮弦见于左关、大肠、右关分判风邪所犯脏腑。", ["浮", "弦"]], "25016": ["病机", "左关浮弦为风邪犯肝，右关脉弦为风邪入胃，大肠脉弦为风入阳明。弦主风动，浮主表邪，故风泻之治当先散表，表解后分利小便，使风散湿去而泻自止。此脉象揭示风邪挟湿、表里同病之机。", ["弦", "浮"]], "25017": ["病机", "右关沉迟为寒中太阴，左尺沉迟为寒中少阴，左关沉迟为寒中厥阴。身热脉浮紧为寒伤太阳，浮弦为寒伤少阳，脉长右寸关独大为寒伤阳明。沉迟主里寒，浮紧主表寒，弦主少阳，长主阳明，皆寒邪伤阳之象。", ["沉", "迟", "浮", "紧"]], "25018": ["病机", "虚细中暑，因暑伤气阴，脉道不充；洪滑中热，因热盛气分，脉体洪大；濡散暑湿，因湿阻气机，脉来濡软而散；促结郁热，因热郁气滞，脉来促结。四者皆暑热湿邪为患，脉象随邪之性质与深浅而异。", ["虚", "细", "洪", "滑"]], "25019": ["治法", "脉虚细者暑伤气阴，治以藿香参橘煎调六一散；脉洪滑热重者热盛气分，治以黄连香薷饮调六一散；热轻者木通汤调六一散；胸次不舒者平胃六一散。此段以脉象分暑湿之轻重，示清理暑湿、分利阴阳之法。", ["虚", "细", "洪", "滑"]], "25020": ["病机", "浮大而数主热中在表，因热邪外蒸，脉气浮盛；沉数主热中在里，因热邪内结，脉气沉实；数而实者为中热之重，数而不实者为中热之轻。此以浮沉分表里，以实与不实分轻重，皆热邪为患之脉象。", ["浮", "大", "数", "沉"]], "25021": ["病机", "湿泻之脉多见濡软，因湿性濡滞，脉道弛缓；或见细涩，因湿阻气机，脉道不利；或见浮缓，因湿邪在表，脉气浮缓。濡软、细涩、浮缓皆湿邪内盛、脾运失健之象，主湿泻之病机。", ["濡", "软", "细", "涩"]], "25022": ["治法", "湿泻之治宜燥湿利小便，用胃苓散、平胃散。身痛身热脉浮应汗者，为湿邪在表，用败毒散、羌活胜湿汤解表祛湿。小便不利者，用木通煎调五苓散或生姜汤调六一散，利小便则湿自去而泻自止。脉浮提示湿邪偏表，故治当汗解。", ["浮"]], "25023": ["病机", "脉必沉数，沉则为积，数则为热。右脉沉数主积热在气，左脉沉数主积热在血。积热内伏，脉乃促结，因热郁气滞，脉来促结不匀。沉数主里热积滞，促结主热郁气阻，皆积热泄泻之病机。", ["沉", "数", "促", "结"]], "25024": ["治法", "右脉数大，数主热、大主积，示肠胃积热壅盛，故以黄连枳壳汤加六一散清其肠胃；左关数属肝火，用龙胆泻肝汤；右关数属胃火，用清胃汤。兼腹痛欲便不得便者，为积热内结，用大黄枳壳汤通因通用。元气虚而积热甚者，清下之中加人参，示数大之脉须辨虚实。", ["数", "大"]], "25025": ["病机", "沉细而迟，沉主里、迟主寒、细主虚，合为里虚寒之象，故主积寒泄泻。或沉而弦，弦主寒饮内结；或沉而结，结主寒凝气滞。右关沉迟为肠胃积寒，右寸沉迟为寒饮伤肺，以寸关分部定寒积所在，皆从沉迟一脉推衍。", ["沉", "细", "迟", "弦"]], "25026": ["治法", "脉散为肺气耗散之象，故用生脉散为主方，取人参、麦冬、五味子敛散固肺，再加黄耆、当归、紫菀、甘草补气养血、润肺止咳。此段以脉散定肺虚气耗之机，治法重在收敛补益，非单纯治泻，体现脉散主气虚不敛之病机。", ["散"]], "25027": ["病机", "弦主寒饮，滑主痰结，故痰积泻之脉或见弦滑。弦滑而数，则痰兼积热，数脉为热象之征。此段以弦滑定痰饮内结之机，以数辨寒热转化，说明同一痰积泻可因兼脉不同而分寒痰、热痰，脉象为辨证关键。", ["弦", "滑", "数"]], "25028": ["治法", "脉滑实，滑主痰、实主邪盛，示痰积内结而正气未虚，故用导痰汤涤痰；有下症者加大黄、玄明粉通因通用，攻逐痰积。二陈平胃散为痰积泻之常法，滑实脉则提示痰结较甚，须用峻剂，体现凭脉定治法轻重。", ["滑", "实"]], "25029": ["病机", "右脉沉滑，沉主里、滑主食积，故主食积泻。或见沉数，数为热积；或见沉弦，弦为寒积。同一食积，凭兼脉之数、弦分寒热，说明沉滑为食积之本脉，数弦为辨寒热之兼象，脉象组合决定病机属性。", ["沉", "滑", "数", "弦"]], "25030": ["治法", "热积脉数，宜清，用栀连平胃散；寒积脉迟，宜温，用红丸子；寒积脉实，宜下，用煮黄丸。此段以数、迟、实三脉定食积之寒热虚实，分别施清、温、下三法，脉象直接指导治法选择，体现凭脉论治。", ["数", "迟", "实"]], "25031": ["预后", "脉多微弱，或迟而缓，或迟而涩，微弱为脾虚气弱之象，迟缓为虚寒，涩为血少气滞，故主脾虚泻。和缓易治，因胃气尚存；弦急为逆，因弦急主木克土、胃气衰败，预后不良。此段以脉之和缓与弦急辨脾虚泻之吉凶。", ["微", "弱", "迟", "缓"]], "25032": ["病机", "两尺浮大而按之细小，是肾气不足、虚阳外浮之象，浮大非实热，乃阳无所附而外越；右关弦大主脾气不足，弦为木乘土位；右尺虚软则真火不足。四诊合参，总归肾虚泻之脉，以尺部虚实并见辨肾气真火之衰。", ["浮", "大", "细", "弦"]], "25033": ["治法", "尺脉细小，为肾火衰微、不能生土之候，故以肾气丸温肾以培土；尺中皆软，则脾肾俱虚，软为不足之象，故用五味子丸双补脾肾。此段由脉定治，细软二字点出虚损本质，非实邪可比。", ["细", "小", "软"]], "25034": ["主病", "酒积之脉多见洪数，洪为热盛、数为热急，酒热内蕴故也；甚则脉见促结，是热邪壅滞、脉道不利。右脉洪数则酒热伤胃，左脉洪数则酒热入胆，以左右分脏腑，洪数总为酒热内积之征。", ["洪", "数", "促", "结"]], "25035": ["病机", "六脉皆迟，主寒无疑；迟而不弦，是中气虚寒、阳运无力；迟而弦紧，弦紧为寒凝收引，故沉积痼冷；迟而弦滑，滑主痰积，寒与积结于内。同为一迟，兼脉不同则寒之浅深、积之有无各异，此段以兼脉辨寒积之病机层次。", ["迟", "弦", "紧", "滑"]], "25036": ["治法", "脉迟和软，迟为寒、软为虚，是中气虚弱不能多食之候，故用理中汤温中健脾；寒伤太阴、腹冷如冰，则寒邪深入，通白四逆汤温阳散寒；若寒积实滞、凝结作患，则非温补所宜，煮黄丸下之。此段凭脉辨虚实，分列温补攻下三法。", ["迟", "软"]], "25037": ["主病", "右关候脾胃，沉滑为食积内停之征，滑主宿食、沉主里滞；若沉数则食积化热，沉紧则食积兼寒。同是右关沉脉，兼滑、兼数、兼紧，分别主食积、热积、寒积，此段以兼脉定积之性质，紧扣右关脾胃之位。", ["沉", "滑", "数", "紧"]], "25038": ["病机", "左关洪大，为肝火亢盛之诊；左脉弦长，弦为木象、长为有余，亦主肝实；数则为热，故右脉弦数，是木火乘土、肝病传脾之象。此段以左关左脉候肝、右脉候脾，洪大弦长数诸脉并见，说明肝火实热横逆乘土之病机。", ["洪", "大", "弦", "长"]], "25039": ["主病", "湿气霍乱之脉，或见沉伏，湿邪困遏、阳气不伸则脉沉伏；或见促止、代结，湿浊阻滞脉道、气血运行不畅故脉来止歇；或见濡软，濡软主湿、主虚。此段列举湿霍乱常见脉象，总以湿浊内阻、脉道不利为其病机。", ["沉", "伏", "促", "结"]], "25040": ["病机", "原文以浮紧主风寒、浮数主风热、浮濡主风湿，说明风气霍乱初起邪在表分，浮为邪客肌表之象，紧数濡各随所兼之邪而异。又分左关浮为风木之邪、右关浮为土受木贼，指出风邪乘脾、木旺克土是霍乱吐泻的脏腑病机，与风寒、风热、风湿外袭相应。", ["浮", "紧", "数", "濡"]], "25041": ["病机", "热气霍乱脉见洪数，洪为热盛气分、数为热性急迫之象；或沉数则热郁于里，或促止则热邪壅遏、脉气不续，或躁疾则热极躁动。诸脉虽形态不同，皆围绕“热”字，说明热邪内扰、气机逆乱而致霍乱吐泻，与身热烦躁、口渴等热证相应。", ["洪", "数", "沉", "促"]], "25042": ["病机", "寒气霍乱脉多沉迟，沉主里、迟主寒，寒邪内盛阳气不能鼓动血脉故也；或沉伏为寒凝气闭，或沉紧为寒邪收引。原文更言“寒重阳竭，六脉不至”，指出阴寒极盛、阳气衰竭则脉道不通，属寒霍乱重危之候，与畏寒肢冷、吐泻清稀相应。", ["沉", "迟", "伏", "紧"]], "25043": ["病机", "痰饮霍乱脉多滑大，滑主痰湿内壅、大主邪气盛实；沉滑为痰饮停蓄于里，滑数为痰热互结，沉弦为饮邪阻滞气机，伏结则痰饮闭遏脉道。诸脉皆从痰饮立论，说明痰浊水饮内干肠胃、气机升降失司而致霍乱，与胸脘痞闷、呕吐痰涎相应。", ["滑", "大", "沉", "弦"]], "25044": ["病机", "食气霍乱脉见滑大或沉实，滑大为食滞内盛、胃气壅实之象，沉实主宿食结于里。原文“填塞太仓，脉反沉伏”指出食积填塞胃脘、气机闭塞太甚时，脉反见沉伏，是实邪内闭而非虚候，与嗳腐吞酸、脘腹胀满相应，提示辨证当舍脉从症。", ["滑", "大", "沉", "实"]], "25045": ["预后", "转筋脉多微涩，微为气血不足、涩为津血不充、脉道不利；或代而散则脉气断续散乱，或隐而伏则脉沉匿难寻。原文特言“不可凶断”，说明此脉虽似危候，实因吐泻津液暴伤、筋脉失养所致，未必主死，提示当结合症情判断预后，不可遽断为凶。", ["微", "涩", "代", "散"]], "25046": ["治法", "本段论转筋之治，以祛风湿、清暑暍为法，分风胜、湿胜、暍气胜用药。原文“无汗脉伏”指出脉伏因外有风寒所束、表气闭郁所致，故忌用木瓜、秦艽酸收之味及寒凉抑遏，必用羌独败毒散发表，说明脉伏在此为表闭之征，治法当以辛散开表为先。", ["伏"]], "25047": ["病机", "本段未出脉名，专论转筋之因：吐泻太多致津液暴亡，筋脉失于荣养，故筋急而搐。其病机核心在津亏筋燥，而非外邪直中筋脉，与前述转筋脉微涩、代散之象互为印证，说明转筋之抽搐源于液脱失养，治当顾护津液。", []], "25048": ["病机", "转筋之脉多见细数，细为阴血不足、筋脉失养，数为热，示津液耗伤而内有郁热；或见空大，是阴亏阳浮、脉道不充；或见双弦，弦主筋急，双弦则见两筋挛缩之象。三者皆围绕转筋津亡筋失濡养、兼夹风热之机，故脉象随证而变，非一脉可尽。", ["细", "数", "空", "弦"]], "25049": ["病机", "外感烦渴脉多沉滑，沉为邪在里，滑主痰湿食滞内蕴；或见沉数，数示里有郁热；或见躁疾，躁疾为热盛急迫之象。外感而见沉滑，说明表邪入里、里热与痰滞相搏，故见烦渴，脉随邪热内盛而由滑转数转疾，反映病机由实热渐趋急迫。", ["沉", "滑", "数", "疾"]], "25050": ["病机", "内伤烦渴脉沉细而软，沉细为阴血亏虚、脉道不充，软为正气不足；或见躁疾，是虚热内扰；或沉细而数，示阴虚火旺；或浮大而空，为阴不敛阳、虚阳外浮。诸脉皆围绕内伤津亏、气阴两虚之机，与烦渴并见，说明虚火上炎、津不上承，脉象以虚细为本。", ["沉", "细", "软", "数"]], "25051": ["治法", "此段以脉定治：脉细软者，气阴两虚，用人参生脉散、人参竹沥汤益气养阴；脉细而数，阴虚火旺，用六味地黄丸滋补肾阴；脉浮大而空，虚阳浮越、气不敛阴，用独参汤大补元气。三脉三法，皆紧扣内伤烦渴虚损之本，示凭脉辨虚损层次而施补，非泛治烦渴。", ["细", "软", "数", "空"]], "25052": ["治法", "此段仅载脉散用人参生脉散。散脉主气散不收、正气耗散，津气外泄而脉道不敛，故见脉散。人参生脉散益气敛阴、固摄津气，正对脉散所主的气阴耗散之机，示见散脉当急敛浮散之气，属凭脉施治之例。", ["散"]], "25053": ["病机", "干霍乱脉多沉伏，沉伏为邪闭于里、气机不通，故见腹中绞痛、吐泻不得；或见洪数，洪数为热盛于内；或见滑大，滑大为痰食壅滞。诸脉围绕干霍乱邪闭气阻、寒热错杂之机，沉伏示闭，洪数滑大示内蕴实热痰滞，脉随邪之性质而变。", ["沉", "伏", "洪", "数"]], "25054": ["治法", "此段论干霍乱治法，上焦痛用冷盐汤探吐，中焦痛刺委中、少商及十指出血，煎藿香汤调益元散滑顺大肠；若脉沉伏，再用气药疏通经络。沉伏示邪闭气阻、经络不通，故于外治通闭之后，仍须以气药疏达，脉沉伏为用气药疏通之凭据，紧扣邪闭气滞之机。", ["沉", "伏"]], "25055": ["病机", "此段引诸家论转筋：陈无择谓阳明养宗筋，感邪伤食暴吐下致津液顿亡、宗筋失养而挛缩；刘宗厚谓冷热不调、阴阳相搏、风寒乘之而挛急；河间谓属火，郁火内伏外束风寒；丹溪谓血热外被风寒；准绳谓伏暑而作、阳明积热外有风寒。脉伏示邪郁于里、阳气不达，与转筋挛缩、厥冷之机相应。", ["伏"]], "25056": ["病机", "原文辨霍乱厥冷无脉，谓转筋厥冷属阳火抑遏，非阴寒。暑热内伏，误用寒凉则抑遏愈甚，手足何由得温、六脉何由得出，故脉伏。此伏非阴厥之伏，乃热深厥深、表邪内陷、外见假寒所致，故脉浮沉数并见，当升散表邪、疏通经络，不可误认脉伏为阴厥。", ["伏", "浮", "沉", "数"]], "25057": ["病机", "原文论风气腹痛之脉，浮缓不数乃风冷之象，风性轻扬故脉浮，冷则收引故缓而不数；或见沉缓，为风邪内伏。左关浮弦，风入肝胆；右关浮缓，风伤肠胃。以脉之浮沉弦缓分风气所伤之部位，说明风冷客于腹中、肠胃气机不和之病机。", ["浮", "缓", "数", "弦"]], "25058": ["治法", "原文以脉定风气腹痛之治：脉浮缓者祛风，脉沉弦者和里，寒热脉浮用防风汤，脉迟者建中汤加防风，左脉浮用柴胡汤，右脉浮用干葛汤。浮缓主风邪在表，故祛风；沉弦主邪郁于里，故和里。示人凭脉之浮沉迟弦分表里用药，非泛论病机。", ["浮", "缓", "沉", "弦"]], "25059": ["病机", "原文论寒气腹痛之脉，脉多沉伏，或见微弱，或见弦紧，或见迟弦。寒主收引凝滞，阳气被遏不能外达，故脉沉伏；寒伤中阳、气血不足则微弱；寒凝气机拘急则弦紧、迟弦。诸脉皆围绕寒邪内客、阳气不伸之病机，为下文分证施治立脉象依据。", ["沉", "伏", "微", "弱"]], "25060": ["治法", "原文承寒气腹痛之脉以定治法：左关弦紧者散寒用桂枝芍药汤，右关迟弦用《金匮》建中汤，六脉沉伏、四肢冷用四逆汤，六脉微弱、中气虚寒用理中汤。沉伏主寒闭阳郁，微弱主中气亏虚，故分别以温散、温中、回阳之剂，凭脉辨寒之深浅虚实。", ["沉", "伏", "微", "弱"]], "25061": ["病机", "原文论暑湿腹痛之脉：伤暑脉虚，暑伤气分故虚；腹痛脉大，邪气壅盛故大；虚大弦数属暑热之痛，滑大而数属暑食所伤。痛极则气机郁遏，脉反沉伏，乃邪闭不通之假象。以虚、大、弦、数、滑、沉伏诸脉辨暑热、食积与痛极郁遏之不同病机。", ["虚", "大", "弦", "数"]], "25062": ["治法", "原文以脉定暑湿腹痛之治：脉洪大者用黄连香薷散，脉弦数者用清热胜湿汤，寒热脉伏或脉浮大者皆宜发表用败毒散，大便结用厚朴三物汤，腹痛呕吐用藿香正气散。洪大主暑热炽盛，弦数主热兼湿，脉伏、浮大主邪郁表分，故分别清暑、清热、发表。", ["洪", "大", "弦", "数"]], "25063": ["病机", "原文论燥火腹痛之脉多见躁疾，并自释其义：躁则为燥，疾则为热，躁疾兼见则为燥热。躁疾指脉来急数不宁，燥火内扰、热盛伤津故尔。此以脉之躁疾直接推演燥热相合之病机，说明燥火腹痛属燥热内结、气机壅滞而痛，非寒非虚。", ["躁", "疾"]], "25064": ["治法", "本段以脉数作为燥火腹痛可下之征，数脉主热，燥火内结，故见腹痛、目黄便赤、口干、小便赤涩、大便结等症。脉数应下，说明热邪炽盛，非攻下不能除，故用芍药黄连汤等方清火通下。脉数为热，与燥火腹痛病机相应。", ["数"]], "25065": ["病机", "痧胀腹痛脉多数大，数主热，大主邪盛，痧毒内壅，气血不畅，故脉数大。痛极而结，脉反停歇，乃邪阻气机，脉道不利，非虚寒之结代。促结并见，说明痧胀疼痛剧烈，气血壅滞，脉行不畅，与腹痛极甚相应。", ["数", "大", "促", "结"]], "25066": ["兼症", "痧胀腹痛兼恶寒发热，脉浮大者，为痧毒挟表邪，浮主表，大主邪盛，正邪交争于外。故用败毒散解表透邪。若腹痛转筋抽搐、小腹闷痛，则刺络放痧。脉浮大与恶寒发热并见，说明表证未解，痧毒内蕴，表里同病。", ["浮", "大"]], "25067": ["病机", "右关滑数，主肠胃积热，滑为热壅，数为热盛；左关弦急，主肝胆有火。热积内伏，脉反沉伏，乃热邪深结，阳气不能外达，按之良久应指劈劈，说明沉伏非虚寒，而是实热内闭，与腹痛、便结等症相应。", ["滑", "数", "沉", "伏"]], "25068": ["病机", "寒积腹痛脉多沉迟，沉主里，迟主寒；或见沉紧、沉弦、沉涩，皆寒凝气滞之象。寒冷太甚，脉至沉伏，乃阴寒内盛，阳气不能鼓动。沉迟紧弦涩并见，说明寒邪积于内，气血凝滞，与腹痛喜温、畏寒等症相应。", ["沉", "迟", "紧", "弦"]], "25069": ["治法", "本段以脉象分治寒积腹痛：脉沉迟用理中汤温中，沉紧用豆蔻丸散寒，沉弦用建中汤缓急，沉涩宜宣通中气用治中汤。沉主里，迟紧弦涩皆主寒凝气滞，故治法总以温通为主，说明脉象直接指导方药选择。", ["沉", "迟", "紧", "弦"]], "25070": ["病机", "右关滑大或沉实，主食积腹痛。滑主痰食，大主积盛，沉实主内结。食填太仓，脉乃促结，乃食滞气阻，脉行不畅；食下肠胃，脉必数实，乃积热内结。迟缓主寒，实数主热，说明食积脉象随寒热属性而异，与腹痛、嗳腐等症相应。", ["滑", "大", "沉", "实"]], "25071": ["病机", "痰积腹痛脉多滑大，滑主痰，大主积，滑大兼见必是痰积。痰积内伏，脉反沉匿，乃痰浊深结，阻遏脉道，阳气不能外显。滑大与沉匿并见，说明痰积内实，与腹痛、痞满等症相应，沉匿非虚，而是痰伏之征。", ["滑", "大", "沉", "匿"]], "25072": ["病机", "酒积腹痛脉多见洪大，洪数主热，实大主积，滑大洪数乃酒湿之积。酒积内伏，脉反弦结，弦主饮主痛，结主积滞，说明湿热酒毒内蕴，气机阻滞，故脉象由洪数转为弦结，提示积滞日久，气血不畅。", ["洪", "数", "实", "弦"]], "25073": ["治法", "痛而欲利，脉沉数者，沉主里，数主热，为酒积化热，里实热结之象。故用枳壳大黄汤攻下积热。口苦舌干为热灼津伤，用干葛清胃汤；利下黄沫为湿热下注，用栀连平胃散加枳壳；小便赤涩为热结膀胱，用益元散清利湿热。", ["沉", "数"]], "25074": ["治法", "口干而脉大，大脉主热盛，热盛伤津故口干。脉大提示阳明热炽，故加石膏、知母以清阳明气分实热，生津止渴。此段以脉大定热盛之机，指导加味用药，体现凭脉辨证、随脉施治的原则。", ["大"]], "25075": ["病机", "虫积腹痛脉乍大乍小、乍数乍缓，或见沉滑、沉涩，虫积牢固则脉沉实。虫动则气机逆乱，故脉象变动不居；沉滑主虫积，沉涩主气滞血瘀；虫积牢固，脉转沉实，说明积久成实，气血壅滞，故脉应之。", ["大", "小", "数", "缓"]], "25076": ["病机", "血滞腹痛脉多见芤涩，或见沉细，血滞停瘀；或亦牢实，停蓄发热，脉亦数疾。芤主血虚，涩主血瘀，沉细主血滞；牢实主瘀积成形，数疾主瘀久化热。说明血滞腹痛有虚实夹杂之机，瘀血内停，新血不荣，故脉象多变。", ["芤", "涩", "细", "数"]], "25077": ["治法", "饮水作呃，脉见芤涩，为血瘀气滞，水饮内停，用桃仁当归汤活血化瘀。大便硬痛为瘀热互结，用桃仁承气汤逐瘀泻热。脉数疾者去桂枝，因数疾主热，桂枝辛温助热。血行后仍痛，用戊己汤加陈皮和其气，示脉症合参以定治法。", ["芤", "涩", "数", "疾"]], "25078": ["病机", "血虚腹痛脉多见细涩，或见虚微，细涩主血虚脉道不充，虚微主气血俱虚。阴虚阳旺则见细疾，细为阴血不足，疾为阳热亢盛。气离血散则弦细而极，弦细为血虚气滞，极细示气血衰败，说明血虚腹痛有轻重浅深之辨。", ["细", "涩", "虚", "微"]], "25079": ["治法", "痛引小腹、牵引肋梢，脉见细涩，为血虚肝郁，用戊己汤、补肝散、逍遥散养血疏肝。阴虚阳旺，脉见细数，细主阴亏，数主热，为阴虚内热，用知柏四物汤、归芍地黄丸滋阴清热。此段以脉细涩、细数分血虚与阴虚阳旺之治。", ["细", "涩", "数"]], "25080": ["病机", "原文以“下手脉沉，便知是气”总括气结腹痛脉象，沉主气机郁滞于里。进而分述：沉迟为气寒，沉数为气热，沉伏为气凝，沉涩为气结。诸脉皆从沉取所得，说明气结腹痛病位在里，病机为气机结聚不通，寒热凝涩各随兼脉而异。", ["沉", "迟", "数", "伏"]], "25081": ["治法", "本段列气结腹痛诸治法方药，末言“气结便实，脉数应下者，厚朴大黄汤；脉迟应下者，煮黄丸”。脉数主气郁化热，故用厚朴大黄汤下其结热；脉迟主气寒凝滞，故用煮黄丸温下寒结。脉象在此指导攻下法的寒热选择，体现凭脉施治。", ["数", "迟"]], "25082": ["治法", "原文直言“厚朴大黄汤治腹痛脉数应下之症”。脉数说明气结腹痛已化热成实，热结于里，故当用厚朴大黄汤攻下热结。此脉数非表热，而是里实热结之征，与“气结便实”相应，脉象直接决定可下之治。", ["数"]], "25083": ["治法", "原文载“煮黄丸治腹痛脉迟应下之症”。脉迟主寒，说明气结腹痛属寒凝内结，虽便实可下，然非热结，故不用苦寒攻下，而用煮黄丸温下寒积。脉迟在此标示寒结之病机，与热结脉数相对，指导温下法的选用。", ["迟"]], "25084": ["病机", "原文言气虚腹痛“多见微弱，或见空大，或见细涩”，此皆元气虚惫之脉。微弱主气虚，空大主虚阳外浮，细涩主气血不足。若“脉反动急”，则属虚劳脉象，为元气虚极而脉失柔和，反映气虚腹痛日久，正气亏虚，脉症不符之危候。", ["微", "弱", "空", "大"]], "25085": ["治法", "原文以脉定气虚腹痛之治：“气怯神倦，脉见微细”用四君子汤，微细主中气虚弱；“遇劳痛甚，脉大无力”用补中益气汤，大而无力为气虚下陷、虚阳浮越之象。脉微细与脉大无力皆提示气虚，故治以补气健脾、升阳举陷。", ["微", "细", "大"]], "25086": ["病机", "肠痈腹痛脉“多见滑数”，滑主痰湿，数主热，为湿热壅聚肠腑。脉小而数，热盛而正气渐伤，脓将成；洪大而数，热毒炽盛，脓已成；脉迟而小，热势未盛，脓未成；脉迟而涩，迟涩主血行不畅，为内蓄瘀血。诸脉反映肠痈不同阶段的病机变化。", ["滑", "数", "小", "洪"]], "25087": ["治法", "原文以脉象指导肠痈治法：“脉小数，将有脓者，四圣散”，小数示热毒初聚、脓未全成，故用四圣散托毒排脓；“脉洪而数，已有脓者，薏苡仁汤排之”，洪数示脓成热盛，故用薏苡仁汤排脓解毒。脉象在此判断脓成与否，决定治疗方向。", ["小", "数", "洪"]], "25088": ["病机", "右脉数大主阳明燥热，热灼津液故小便不利；左脉数大属少阴之别，热移膀胱。右脉濡缓为太阴湿淫，湿阻气化；左脉浮弦为厥阴风邪，风动水停。四脉分属四经，说明小便不利非一途，乃燥、湿、风、热交杂为患，脉象随经而异。", ["数", "大", "濡", "缓"]], "25089": ["主病", "太阳发汗后脉浮，为表邪未尽、热结膀胱，故小便不利、微热消渴；误下后头汗身黄、腹微满，属湿热内蕴；大下复汗则津液亡失；大便乍难乍易、时有微热为里热。原文以脉浮统摄热结膀胱一证，余症则示湿热、亡津、里热之变。", ["浮"]], "25090": ["病机", "身热脉浮为热结膀胱，表热入里；动数变迟乃太阳误下、邪陷之变。右脉洪数主阳明湿热，湿热下注故小便不利。六脉虚微为内亡津液，化源不足；六脉沉数主里热便结，热灼肠道。诸脉分示热结、湿热、亡津、里结四类病机。", ["浮", "洪", "数", "虚"]], "25091": ["治法", "本条列小便不利之治法：热结膀胱用五苓散，阳明湿热用茵陈汤、平胃四苓散、猪苓汤。脉虚亡津液者，以生脉散合当归补血汤益气生津，脉散亦主津气耗散，故用生脉散收敛。里热便结二便俱闭用八正散，温热病则宜清利。脉虚、脉散点明亡津液之机，治当补益。", ["虚", "散"]], "25092": ["治法", "此段仅列生脉散一方，承上文脉散合当归补血汤而来。脉散为津气耗散、脉道不敛之象，故用生脉散人参、麦冬、五味子益气敛阴生津。原文极简，以方映脉，说明脉散主气阴两伤、津液不固，治当敛补，非通利所宜。", ["散"]], "25093": ["病机", "阴寒小便不利脉必濡缓，甚则濡迟，濡缓主湿、迟主寒，寒湿内阻气化不行。右脉濡迟属太阴寒湿，脾阳不运；左脉濡迟属少阴寒湿，肾阳不振。两脉分属脾肾，说明阴寒小便不利乃寒湿困阻、阳气不化所致，与热结之数大脉截然不同。", ["濡", "缓", "迟"]], "25094": ["病机", "右寸洪数主肺经有热，肺失通调；寸数连尺为大肠之热，连关则肺胃皆热。左寸细数属心经之火，大数为小肠之热；左尺细数为肾火，大数为膀胱结热。诸脉以数为主，兼洪、细、大，分候肺、大肠、心、小肠、肾、膀胱，说明热结小便不利随脏腑而异。", ["洪", "数", "细", "大"]], "25095": ["病机", "右关弦大主胃家之病，弦为气机郁滞、大为邪盛，胃病则水液偏渗；右关弦细为脾气有损，细示不足，脾虚不能运化。左寸偏弦为小肠之诊，弦主气滞。本条以弦脉为主，兼大、细，说明偏渗小便不利责在胃、脾、小肠气机失调，水液不循常道。", ["弦", "大", "细"]], "25096": ["病机", "右寸脉弱主肺气不足，右关脉弱主中气不足，右尺脉细主膀胱气弱，左寸脉细主小肠气弱。脉弱为气虚推动无力，脉细为气弱不充脉道，故诸部脉弱细反映肺、中焦、膀胱、小肠之气虚，气化不行而小便不利。", ["弱", "细"]], "25097": ["治法", "本段为气虚小便不利之治法，非论脉象。肺气不足者用生脉散补肺气，中气不足者用补中益气汤升举中气，膀胱气弱不及州都者用人参车前汤益气利水。脉象描述为“脉散”系标题误置，正文无脉象内容，故脉象要素为空。", []], "25098": ["其他", "本段仅言“生脉散见前”，为方剂互见之文，无脉象论述，亦无病机分析。脉象写法“脉散见前”系标题误置，正文无脉象内容，故脉象要素为空，主旨归为其他。", []], "25099": ["病机", "脉多细数，细为阴血不足、脉道不充，数为阴虚内热、虚火躁动。右脉细数主肺阴不足，左脉细数主肝肾阴虚。阴虚则津液亏耗，无以化气行水，故见小便不利，此阴虚小便不利之脉机。", ["细", "数"]], "25100": ["治法", "本段为阴虚小便不利之治法，非论脉象。肺阴不足用生脉散、人参固本丸，肝阴不足用海藏四物汤，肾阴不足用知柏天地煎加玄武胶，肝肾俱虚用肝肾丸。脉象写法“脉散”系标题误置，正文无脉象内容，故脉象要素为空。", []], "25101": ["其他", "本段仅言“生脉散见前”，为方剂互见之文，无脉象论述，亦无病机分析。脉象写法“脉散见前”系标题误置，正文无脉象内容，故脉象要素为空，主旨归为其他。", []], "25102": ["病机", "左关沉迟主肝阳不足，两尺沉迟主肾阳不足，六脉沉迟主诸阳亏损。沉为阳气不能鼓动脉气外达，迟为阳气衰微、血行迟缓，故沉迟脉反映肝、肾及全身阳气亏虚，阳不化气则小便不利。", ["沉", "迟"]], "25103": ["治法", "本段论小便不利按脉用药之法。左关脉数加青黛、柴胡清肝胆火，左寸脉数加川连、木通清心火，右关脉数加干葛、石膏清阳明火，两尺脉数加车前子、黄柏清肾与膀胱火。脉数主热，故随部清火以利小便。", ["数"]], "25104": ["病机", "左脉浮数主太阳表热，右脉沉数主阳明里实，合为太阳阳明；左脉弦数属少阳，右脉沉数属阳明，合为少阳阳明；六脉沉数则纯属正阳阳明里热。沉细而数则热入三阴，阴分伏热。以脉之浮沉分表里、弦数分经腑，说明便结由热邪内结、经腑同病所致。", ["浮", "数", "沉", "弦"]], "25105": ["病机", "尺寸浮数，热在表属太阳阳明；尺寸洪数，热盛于里属正阳阳明；尺寸弦数，热郁少阳属少阳阳明。右关沉数，热在太阴；左寸洪数，热在少阴；左关沉数，热在厥阴。以浮洪弦沉数诸脉分定六经温热所在，说明便结乃温热内蕴、经腑受热、津液受灼之病机。", ["浮", "数", "洪", "弦"]], "25106": ["病机", "右寸细数，肺热下移大肠；右寸大数，大肠积热；右关细数，脾家蕴热；右心沉数，亦主大肠热。细数示热而阴伤，大数示热盛，沉数示热结于里。诸脉皆从右寸关候肺脾大肠，说明积热便结由肺脾积热下遗大肠、热灼津液而燥结不行。", ["细", "数", "大", "沉"]], "25107": ["病机", "气秘之脉，盛则沉实，虚则细微。右寸沉实为肺气郁结，右关沉实为脾气郁结，左关沉实为肝胆气结；右寸细微为肺气不足，右关微细为脾气不足。沉实主气壅不通，细微主气弱无力，说明便结有气郁与气虚两端，皆关乎肺脾肝胆气机升降失司。", ["沉", "实", "细", "微"]], "25108": ["治法", "本段为气秘便结之治，承上段气郁、气虚之脉而立方。肝气壅盛用枳桔泻白散，脾胃郁结用平胃二陈汤，肝胆气结用清肝饮，大肠气结用枳桔汤，元气不足用四君子汤，肺虚不能下达用生脉散合参橘煎。示气秘当分脏腑气结与气虚论治，以调气、补气为要。", []], "25109": ["其他", "本段仅言「生脉散见前」，为方剂出处之注，未载脉象与病机。承前段肺虚不能下达用生脉散合参橘煎之意，属治法方药之互见，非论脉之文，故脉象要素为空，主旨归入其他。", []], "25110": ["病机", "六脉沉数，主血液干枯，热灼阴血而燥结；细小而数，主阴血不足，脉道不充而热内生；滑大而数，主血中伏火，火灼血燥。沉数示热在里，细示血少，滑大示火盛。说明血枯便结由阴血亏耗、伏火内灼、津枯肠燥所致。", ["沉", "数", "细", "滑"]], "25111": ["治法", "久病伤阴，脉细而数者，用四物汤加麻仁、何首乌养血润肠；高年阴耗、血燥津竭者，用生脉散、天地煎益气生津；血中伏火者，用滋血润肠汤、脾约丸润燥泻火。承上段细数、滑大之脉，示血枯便结当养血润燥、滋阴清火，随脉证分途施治。", ["细", "数"]], "25112": ["主病", "原文仅言「脉散见前小便不利」，以散脉提示小便不利之病机。散脉主气散不收、气血耗散，脉道不敛，故见小便不利，属气化失司、水液不行之候。生脉散本为益气敛阴之方，此处借散脉点明气阴耗散、水道失调，与小便不利相应，非单纯实邪闭阻可比。", ["散"]], "25113": ["治法", "此段未出具体脉象，专论去病三条去路：毛窍与二便。以「伤寒身热不减，首重发汗解肌；里热不解，又重于清利二便」为纲，引《内经》「开鬼门，洁净府」分消肿胀。虽无脉可凭，然其旨在于据脉证以定汗、利二便之法，属治法总则，非专主一脉一病。", []], "25114": ["其他", "此段为序跋文字，述秦先生简易古朴、议论斩斩，为作者室人沉疴二载处方立效之事，全无脉象描述。文中「见之真」「信之专」言医者识证真切、病家信守专一，故投剂辄效，属医案序言类，不涉脉诊病机，故列其他。", []], "25115": ["其他", "此段自述编集《内经运气要旨论》《医方精要宣明论》之由，本三坟圣经兼众贤妙论，推运气造化之理以集伤寒杂病脉证方论。通篇言著述体例与学术源流，未及具体脉象与病机，故归其他，非主病、病机之属。", []], "25116": ["病机", "原文以饮酒为例，言「脉洪大而数，语涩谵妄……喜怒如狂」，洪大数皆阳热亢盛之象。火盛制金不能平木，肝木自甚而吐酸，故脉洪大数主心火炽盛、肝热上逆。热则五味皆厚，肝热口酸、心热口苦，诸证皆从火热立论，明吐酸属热非寒。", ["洪", "大", "数"]], "25117": ["病机", "此段辨吐下霍乱寒热。寒者「脉当沉细而迟」，沉细迟为阳气不足、寒湿内盛之象；热者「脉当实大而数」，实大数为邪热壅盛之征。又言损气亡液过极则「脉亦不能实数，而反弱缓」，然仍属热，示不可因脉弱缓误判为寒，须合烦渴亡液之症互参。", ["沉", "细", "迟", "实"]], "25118": ["病机", "原文以「脉迟细而微者，寒证也」定泻痢寒热。迟细微为阳气衰微、阴寒内盛之脉，与完谷不化、吐利腥秽、澄澈清冷、小便清白不涩、身凉不渴诸症相应，故主寒证。又提出「谷消化者，无问色及他证，便为热也」，以脉证合参别寒热，不徒凭痢色。", ["迟", "细", "微"]], "25119": ["病机", "此段驳「下痢白为寒」之误，未出具体脉象。以谷肉果菜湿热甚则腐烂化污水为喻，言下痢脓血乃湿热邪气溃发所致：热为赤属心火，湿为黄属脾土，燥郁为白属肺金。诸泻痢皆兼湿，湿热郁结肠胃致气液不得宣通而成燥，故烦渴不止，主湿热为痢之病机。", []], "25120": ["病机", "原文以带下比诸痢，明言「赤白与下痢义同，而无寒者也」，并举头目昏眩、口苦舌干、小便赤涩、大便秘滞等热证，断为「脉实而数者，皆热证也」。实为邪热内盛，数为热象急迫，故脉实而数主热郁任带、湿热下注之带下，非虚寒所致，与寒证之脉迟紧者迥别。", ["实", "数"]], "25121": ["病机", "原文论伤饮食致怫热郁结而成水肿，谓「怫热内作则脉必沉数而实」。沉主郁结在里，数主热，实主邪气壅盛，故脉沉数而实示热郁气液不能宣通、水气妄行之水肿腹胀，法当辛苦寒药下之，结散热退则气和，非脾土虚寒之证。", ["沉", "数", "实"]], "25122": ["病机", "原文辨鼻窒，明言「妄以鼻窒为寒者，误也」，指出「热客阳明，而鼻中䐜胀则窒塞」，又释侧卧上窍通下窍塞乃阳明之脉左右相交、风热郁结偏于一侧所致。本段无脉象描述，主旨为热郁阳明、鼻窍壅塞之病机，非寒主闭藏。", []], "25123": ["病机", "原文驳冬阳在内而热、夏阴在内而寒之误，谓一身之气随四时五运六气兴衰，夏月心火生而热，「则其脉滑数洪大而长，烦热多渴，岂为寒也」。滑数主热盛，洪大而长主心火亢盛、阳气外浮，故脉滑数洪大而长主夏月心火之热证，与烦热多渴相应。", ["滑", "数", "洪", "大"]], "25124": ["病机", "原文引《经》「阳并于阴，阴则实而阳明虚，阳虚故寒栗而鼓颔」，注谓阳气入于阴分，阳明胃脉不足则恶寒战栗鼓颔。本段无脉象，主旨为阳气并于阴、阳明经虚而寒栗鼓颔之病机，因阳明主肌肉而气并于里，故言阳明虚。", []], "25125": ["兼症", "原文论嚏由鼻痒火化、心火邪热干于阳明而发，又述风热上攻头鼻壅滞者「脉浮而无他证」，内药鼻中得嚏则壅滞开通而愈。浮主风热在表在上，无他证示邪浅病轻，故脉浮为风热壅滞鼻窍之嚏证，得嚏则气通而愈。", ["浮"]], "25126": ["病机", "原文论耳鸣为「水虚火实，而热气上甚，客其经络，冲于耳中，则鼓其听户，随其脉气微甚，而作诸音声」。脉气微甚指脉中气机之微盛，热甚则鸣声大，热微则鸣声细，故脉气微甚主肾水虚而心火实、热气上冲耳窍之耳鸣。", ["微"]], "25127": ["病机", "原文辨肾与命门，引杨上善注「左者为肾，右者为命门」，谓命门即小心，属手厥阴包络相火，并驳女子左肾为命门之误。本段无脉象，主旨为右肾命门相火之脏腑病机，说明下部冷非水虚，乃相火之原在右肾。", []], "25128": ["病机", "原文未出脉名，但以“阴虚阳实之热证”统摄老人头目昏眩、耳鸣聋、上气喘咳、便溺閟结等症，说明气衰之体可因阴液亏而阳热实，非皆虚冷。其病机为水不胜火、中外燥涩，故不可妄投热药温补，否则积温成热、变生热疾。", []], "25129": ["病机", "原文未出脉名，而言“水衰火实，热郁于上”，使听户玄府壅塞、神气不得通泄，故聋。以闭耳如鼓音验脉气流行，壅滞则天鼓微闻，闭绝则无所闻。病机在火热郁闭清窍、气液不通，非单纯肾虚，故用针砂酒、磁石导气通泄。", []], "25130": ["病机", "原文未出脉名，专论玄府为气出入升降之道路门户，谓“气化则物生，气变则物易，气乱即物病，气绝即物死”。其病机在气机升降失常、玄府闭塞，则脏腑皮毛皆病；气绝则神机化灭。此段为玄府气机病机总纲，非具体脉象主病。", []], "25131": ["病机", "原文以“夏热则脉洪大而长”说明火主动，洪大为火热亢盛、气血涌盛，长为气机有余而畅达，故应夏热之令。𥆧瘈为惕跳动，亦火动之象。脉为心火所养，故洪大而长主心火偏旺、热盛动惕之病机。", ["洪", "大", "长"]], "25132": ["预后", "原文以“微则但僵仆，气血流通，筋脉不挛，缓者发过如故”辨中风轻重：脉微则气血尚通、筋脉不挛，脉缓则发过后如常，皆预后较良；若热气太盛、郁结壅滞，气血不能宣通，阴气暴绝则阳气后竭而死。此段以脉微、缓判断病势与转归。", ["微", "缓"]], "25133": ["病机", "原文言中风口噤筋脉紧急，由“阳热暴甚于内”，津液涌溢聚于胸膈，热燥为痰涎；阳实阴虚、风热太甚胜水湿而成燥，肝主筋而风气自甚，燥热加之则筋太燥。燥金主收敛劲切紧涩，故脉紧急、劲强紧急而口噤，主燥热伤筋、风火内盛之病机。", ["紧", "急", "劲", "强"]], "25134": ["治法", "原文论破伤中风“风热燥甚，怫郁在表而里气尚平”，症见善伸数欠、筋脉拘急、恶寒或筋惕而搐，脉浮数而弦。浮主表，数主热，弦主风与筋急，故脉示风热燥郁于表。治宜辛热开冲结滞，但须佐寒药消息，防辛热转甚，此段重在发表治法与用药权衡。", ["浮", "数", "弦"]], "25135": ["病机", "原文言破伤中风表不已渐入于里，里势已甚则舌强口噤、项背反张、惊搐惕搦、涎唾稠黏、胸腹满塞、便溺秘结，脉洪数而弦。洪为热盛，数为热急，弦为风劲筋急，脉在肌肉示病已入里。此脉主风热燥盛、郁滞入里、筋脉劲急之病机。", ["洪", "数", "弦"]], "25136": ["治法", "原文以“筋脉稍得舒缓”言导引按摩之效，非论病脉。风热郁结于表，筋脉拘急，故以屈伸按摩“使筋脉稍得舒缓，而气得通行”，脉缓在此指筋脉拘急得解、气血通行之象，属治疗转归，非主病之脉。治风热结滞戒热药过盛，正与此舒缓之机相应。", ["缓"]], "25137": ["病机", "原文辨“筋缓不收而痿痹”，谓风热胜湿而为燥，燥甚则血液衰少、气血不能通畅，故筋脉挛缓。脉缓在此非虚寒，乃燥化伤血、筋失濡养之象。原文力斥“筋缓不收则为虚寒”“热主舒缓”之说为误，强调挛缓只分微甚，不论寒热虚实，筋缓者难以平复。", ["缓"]], "25138": ["病机", "原文以“干则涩滞”释涩脉，谓遍身中外涩滞皆属燥金之化，故秋脉涩。水液衰少而燥涩，气行壅滞不得滑泽通利，气强攻冲而为麻，故涩脉主燥、主液亏、主气行壅滞之麻。原文又言六气相兼，亡液为燥或风热胜湿为燥皆可致麻，当以脉证别之。", ["涩"]], "25139": ["病机", "原文以燥湿相反立论：燥金主紧敛，故秋脉紧细而微；湿土主纵缓，故六月脉缓大而长。紧细而微应燥金收敛、腠理闭密无汗而皴揭；缓大而长应湿土纵缓滑泽。皴揭由风胜湿而为燥，寒月甚而暑月衰，正与紧细微之脉相应，脉象即燥湿二化之征。", ["紧", "细", "微", "缓"]], "25140": ["病机", "原文论症“腹中坚硬，按之应手”，以水体柔顺反坚硬如地，释为“亢则害，承乃制”。风病过极则反燥，“筋脉劲急，反兼金化制之”，故脉劲急乃风极兼燥金收敛之象，非单纯风脉。治当泻其过甚之气为本，不可误治其兼化，劲急之脉正示亢害承制之机。", ["劲", "急"]], "25141": ["病机", "原文辨瘕“腹中虽硬，而忽聚忽散，无有常准”，引经注谓血不流而寒薄、血内凝而成瘕，又谓小肠移热大肠、两热相搏血溢为伏瘕，血涩不利则月事沉滞。末言阳气郁结、怫热壅滞而坚硬不消者非寒症瘕，宜以脉证别之，故本段无具体脉象，旨在示瘕有寒热之异。", []], "25142": ["病机", "原文论𤻊疝少腹控卵肿急绞痛，寒主拘缩，故《难经》言五脏疝“但脉急”。注谓脉急者寒之象，寒则脉当短少而迟；急非急数而洪，由紧脉主痛、急为痛甚，故痛而脉紧急，乃心神不宁、脉不得舒缓所致。当以紧急相兼之脉辨何气为痛。", ["急", "紧", "短", "迟"]], "25143": ["病机", "原文论坚痞腹满急痛，寒主拘缩故急痛，寒极则血脉凝冱反兼土化制之，故坚痞腹满。又指出热郁于内而腹满坚结痛者，不可言为寒。本段未出具体脉名，旨在辨坚痞腹满有寒凝与热郁两端，当以脉证分寒热，不得一概作寒治。", []], "25144": ["病机", "原文以冬脉沉短以敦为寒病之象，阴寒主清净，故四肢逆冷、屈伸不便。阴厥者身凉不渴，脉迟细而微，皆阴证脉候；阳厥则热极反厥而脉数，若热极深重反见脉微欲绝，是热极欲死之兆，非真阴病。此段辨阴厥阳厥之脉，脉沉短迟细主寒，脉数主热，脉微欲绝主热极危候。", ["沉", "短", "迟", "细"]], "25145": ["预后", "原文言阳实则脉当实数，身热烦渴，热甚则阳厥，至极则身冷脉微而似阴证，以致脉绝而死。脉实数主阳热实邪，脉微主热极阳衰、近乎脉绝。故阳病见阴脉者死，谓其脉近乎绝。此段以脉之实数与微绝辨阳病之轻重及死生预后。", ["实", "数", "微"]], "25146": ["误治", "原文述阳厥失下，身冷脉微而似阴证，医反误投热药，病势转甚，身冷脉微而欲绝，唯心胸微暖、昏冒不能言。此因热极失下又温补所致，若再以热药助阳，则阴气暴绝、阳气亦竭而死。脉微而欲绝主热极伤阴、阳气将竭之危候，非真寒阳虚，故温补为误治。", ["微"]], "25147": ["治法", "原文以凉膈散治阳厥，服后心胸温暖渐多而脉渐生，由身冷脉微转为脉沉数而实，身表复暖，继以调胃承气汤下之获汗而愈。脉微主阳实阴虚欲死之候，脉沉数而实主热邪内结、阳气来复。所谓寒药反能生脉令身暖者，由阳实阴虚，寒药养阴退阳而复不至于死，故为治法之验。", ["沉", "数", "实", "微"]], "25148": ["主病", "原文仅存“脉若五至以上洪大者”一句，五至以上为数脉，洪大主邪热亢盛、气血燔灼。脉数而洪大，为阳热实盛之象，多见于外感热病气分热盛或里热炽盛之证。此段以脉至数与形态并举，示数而洪大者主热盛实邪。", ["洪", "大", "数"]], "25149": ["平脉", "原文仅存“脉平和者”一句，指脉来从容和缓、不浮不沉、不快不慢、有力柔和，为气血调和、脏腑安和之象，即平人无病之脉。此段以平和之脉示无病之常，与病脉相对，属平脉范畴，非主病机之脉。", ["和平"]], "25150": ["治法", "原文仅存“脉洪大加大黄”一句，洪大之脉主邪热亢盛、气分热炽，故于主方中加大黄以泻热通腑、导热下行。此段以脉洪大为用大黄之凭据，示洪大脉主实热内盛，治当清热泻下，属据脉施治之法。", ["洪", "大"]], "25151": ["病机", "原文论天之邪气害人五脏、水谷寒热害人六腑、地之湿气害人皮肤筋脉，并指出脾胃不足为百病之始，形气两虚则不及天地之邪。此段未出具体脉象，主旨在于阐发内外伤及饮食劳倦伤脾胃之病机，强调脾胃不足为百病之始，世医不辨有余不足而误治。", []], "25152": ["病机", "此段论五脏藏精气而不泻、六腑传化物而不藏，胃气一虚则九窍不利。原文强调“五脏皆得胃气，乃能通利”，又引《通评虚实论》“头痛耳鸣，九窍不利，肠胃之所生也”，说明胃气虚弱可致耳目口鼻诸窍失养，病机在胃气不足、传化失职，非关具体脉象。", []], "25153": ["病机", "此段以“水谷之海”论胃，指出“水谷之海有余则腹满，不足则饥不受谷食”，并述胃出气血于经隧、宗气积胸中贯心肺行呼吸。全段无脉象描述，主旨阐发胃为水谷气血之海、经隧为五脏六腑大络，病机重在胃气盛衰影响气血化生与输布。", []], "25154": ["病机", "原文谓“胃病其脉缓，脾病其脉迟”，又“火乘土位，其脉洪缓”，兼身热心中不便。脉缓主胃病，迟主脾病，洪缓为火乘土位、湿热内蕴之象。总由“阳气衰弱，不能生发”，故脉象虽见洪缓，实非实火，乃土虚火乘、升降失司之病机。", ["缓", "迟", "洪"]], "25155": ["治法", "此段以脉定治：脉缓主湿胜，见怠惰嗜卧、四肢不收、大便泄泻，从平胃散；脉弦主气弱自汗、四肢发热，从黄耆建中汤；脉虚而血弱，于四物汤中加减；气短脉弱，从四君子汤。诸脉皆围绕脾胃气虚、湿胜、血弱之兼证，示人凭脉选方之治法。", ["缓", "弦", "虚", "弱"]], "25156": ["治法", "原文“腹中急缩，或脉弦，加防风，急甚加甘草”，以脉弦主腹中拘急，乃脾胃气机不和、筋脉失柔之象。又论腹中窄狭气短亦加之，腹满气不转者勿加，而脾胃中气不和者加厚朴破滞气，腹中夯闷加芍药收之，皆据脉症调治之法。", ["弦"]], "25157": ["病机", "此段自述调理脾胃虚弱，虽随证加减终不能完复，后悟“督、任、冲三脉为邪，皆胃气虚弱之所致”，并检讨《素问》等谓“脾胃不足之源，乃阳气不足，阴气有余”，当从六气不足、升降浮沉法随证用药。全段无脉象，主旨阐发脾胃虚弱之根本病机在阳气不足。", []], "25158": ["病机", "原文“脾胃脉中见浮大而弦”，谓心与小肠来乘脾胃，火热乘土位，湿热相合，故烦躁闷乱、四肢发热、口干舌干咽干。浮大而弦为心火乘脾、湿热内郁之象，非脾胃本脉。又因饮食劳役伤脾，血病津亏，医以五苓散反竭津液，当甘温补母。", ["浮", "大", "弦"]], "25159": ["病机", "此段释“所胜妄行”，谓心火旺令母实，肝木挟火势妄行，脾胃先受。症见身体沉重、走疰疼痛，为湿热相搏、风热郁不得伸；或多怒、目生内障、妄见妄闻、转筋等，皆“肝木火盛而为邪”，总由风热不得升长、木火遏于有形之中。全段无脉象。", []], "25160": ["病机", "原文未出脉名，专论“所不胜乘之”即水乘木妄行反侮土，肾水泛溢入心为汗、入肝为泣、入脾为涎、入肺为痰嗽涕嚏，皆水气妄行、肺金虚而寡于畏所致；下元土盛克水则督任冲三脉盛、火旺煎熬令水沸腾，上乘脾肺而痰涎唾出于口，下为阴汗、外肾冷、足不任身，总属水侮土、金虚失制之病机。", []], "25161": ["病机", "原文未出脉名，以“食入于胃，散精于肝，淫气于筋……浊气归心，淫精于脉”论谷气升浮布散之常；若饮食不节损其胃气，不能克化，食入则昏冒欲睡，是“升发之气不行”；饮入遽觉至脐下便欲小便，由精气不输于脾、不归于肺，心火上攻而口燥咽干，主脾胃虚弱、升降失司、精气不布之病机。", []], "25162": ["病机", "原文未出脉名，明言“肾水反来侮土，所胜者妄行也”，水寒妄行则作涎、清涕、唾多、溺多而恶寒；土火复之及三脉为邪，则足不任身、足下痛不能践地、骨无力、喜睡、两丸冷、腹阴阴而痛、妄闻妄见、腰脊背胛皆痛，皆水侮土、寒湿偏胜、阳气不充之候。", []], "25163": ["病机", "原文未出脉名，先述饮食入胃、阳气上行、津液贯肺充皮毛散百脉之常，继言“饮食损胃，劳倦伤脾，脾胃虚则火邪乘之，而生大热”，主张补脾之源兼泻脾胃中亢火；强调“百病皆由脾胃衰而生”，足阳明为十二经之海，诸经皆禀之，故脾胃一衰则诸经相并而为病，主脾胃虚弱、火邪乘之之病机。", []], "25164": ["治法", "原文未出脉名，属服药调护之法：大温服、减食美食、忌语话及酒面大料物，恐“大湿热之物复助火邪而愈损元气”；忌冷水寒凉淡渗诸果，恐“阳气不能生旺”；明言此法此药“欲令阳气升浮”，淡渗滋阴为大禁；惟肾火旺及督任冲三脉盛时从权用黄柏知母，不可久服，恐助阴气。", []], "25165": ["病机", "原文未出脉名，承“饮食损胃，劳倦伤脾，脾胃虚则火邪乘之而生大热”，指出“湿热相合，阳气日以虚”，阳虚不能上升则脾胃之气下流并于肾肝，“有秋冬而无春夏”；春升夏浮在人为肝心，弱则阴气盛而阳气不得经营，故主以味薄风药升发伸阳、泻阴中之火，使阳气生而阴气不病，属脾胃虚、阳气下陷、阴火亢盛之病机。", []], "25166": ["误治", "原文未出脉名，引《四气调神大论》“天明则日月不明，邪害空窍”喻胃虚火乘、阳气闭塞；劳倦伤脾则气耗，心火炽动、血脉沸腾而血病，阳气不治而“阴火乃独炎上”，走于空窍燎于周身；此时“反用热药以燥脾胃，则谬之谬也”，故本段主旨在于指斥误用热药燥脾之误治。", []], "25167": ["主病", "右关脉缓而弱为脾胃本脉本病，主不能食而肌肉削；脉中兼见弦，或四肢满闭、淋溲便难、转筋，为肝之脾胃病，当加风药泻之；兼见洪大，或肌热烦热面赤不能食、肌肉消，为心之脾胃病。原文以本部本证脉兼见他脉定五脏之脾胃病，示脾胃既虚则十二经之邪不一而出，缓弱为辨病之根基。", ["缓", "弱", "弦", "洪"]], "25168": ["治法", "原文于半夏条下注“此一味脉涩者宜用”，涩脉主血少气滞、津液不布，半夏辛温能燥湿化痰、宣通胃气，故脉涩而兼痰湿内阻者宜之。此段以方药加减示人：脉涩非一味补血，须辨痰湿阻滞，取半夏流通之性，使气机宣畅则涩滞可解，属因脉施治之例。", ["涩"]], "25169": ["病机", "原文引《伤寒论》“阳脉涩，阴脉弦，法当腹中急痛”，涩为阳气不足、营血虚滞，弦为阴寒内盛、木来克土；水挟木势侮土，故脉弦而腹痛。以芍药酸泻土中之木为君，肉桂辛热佐之退寒水，饴糖甘草补脾，姜枣发散阳气，说明涩弦并见主虚寒腹痛、木克土之病机。", ["涩", "弦"]], "25170": ["兼症", "本段未出脉名，专论随症加减：皮毛肌肉不伸加葛根，冲脉气逆里急加炒黄柏、知母，胸中结滞气涩有热加炒黄芩，食少小便少属津液不足，勿利之，益气补胃自行。所论“气涩”“津液不足”提示气机郁滞与津亏并存，治当升阳益气、不可妄利小便。", []], "25171": ["主病", "原文“恶热发热而燥渴，脉洪大，白虎汤主之”，洪大为阳明燥热亢盛、气分热炽之象，热盛迫津故燥渴，热壅气分故脉洪大。喘者加人参，渴不止加寒水石、石膏，皆清阳明气热、生津止渴之法，说明洪大脉在此主燥热内盛、气分大热之病机。", ["洪"]], "25172": ["治法", "原文“如脉弦，只加风药，不可用五苓散”，弦脉主风、主木郁，风药能升阳散郁，使肝木条达；五苓渗利，反伤津液。若小便行而病增，是内燥津液不能停，当致津液，加炒黄柏、赤葵花。此以弦脉辨风郁与内燥，示人不可见小便不利即妄投渗利。", ["弦"]], "25173": ["治法", "原文“如有大热，脉洪大，加苦寒剂而热不退者，加石膏”，洪大脉主热盛于气分，苦寒直折而热不退，是热邪壅遏阳明、非苦寒所能解，故加石膏辛甘大寒，清透阳明气分实热。脾胃中热则加炒黄连、甘草，说明洪大脉须辨热之所在，分经用药。", ["洪"]], "25174": ["治法", "原文“凡治此病脉数者，当用黄柏，或少加黄连”，数脉主热，热郁于内不得外达，故以柴胡、升麻升阳散火，苍术、黄耆、甘草补中，黄柏、黄连清下焦郁热，得汗出则脉必下，即“火郁则发之”之义。数脉在此主郁热内伏，治取升散透达而非纯用苦寒。", ["数"]], "25175": ["预后", "原文辨数脉之进退：证退而脉数不退、不洪大而疾有力者，减苦药加石膏；石膏善去脉数疾，病退脉数不退者不可治，是胃气已败、邪热独亢之危候。又云“脉弦而数者，此阴气也”，弦数并见为木火郁于阴分，风药升阳发火郁则脉数峻退，示数脉须辨虚实与可治不可治。", ["数", "疾", "弦"]], "25176": ["病机", "原文未出脉名，然述“风寒汗出，肩背痛，中风，小便数而欠”，病机为风热乘肺、肺气郁甚。风热外袭，肺失宣降，故汗出、肩背痛；肺气郁而水道不调，故小便频数而欠。治当泻风热、通气机，以通气防风汤主之，脉象虽未明言，其证候已示肺气壅郁之机。", []], "25177": ["兼症", "嗌痛颔肿而脉洪大、面赤，洪大为热盛之象，热邪上攻咽喉颔颊，故肿痛；面赤为热循阳明上炎。脉洪大与面赤、嗌痛颔肿相应，主热邪壅盛于上，故加黄芩、桔梗、甘草以清热利咽消肿。", ["洪", "大"]], "25178": ["病机", "耳鸣目黄、颊颔肿、颈肩臑肘臂外后廉痛而面赤，脉洪大，为风热壅盛、经气不通，故以羌活等通经血，芩连消肿，参芪益元气泻火邪。若脉紧者，紧主寒，故面白善嚏、面色恶皆寒象，当泻足太阳，少加附子通脉，甚加桂附。洪大主热，紧主寒，脉证相参以定治法。", ["洪", "大", "紧"]], "25179": ["治法", "原文论药禁，举“脉弦而服平胃散，脉缓而服黄耆建中汤”为例。弦脉主肝木乘脾，故以平胃散运脾；缓脉主脾虚，故以黄耆建中汤补中。此以脉弦、脉缓为据，说明用药须随脉象虚实而禁宜，非泛论病机，乃示临证选方之准则。", ["弦", "缓"]], "25180": ["病机", "原文未出脉名，论太阴阳明表里生病之异。阳道实、阴道虚，贼风虚邪阳受之入六腑，则身热不得卧、上为喘呼；食饮不节阴受之入五脏，则腹满闭塞、下为飧泄、久为肠澼。此以阴阳异位、更虚更实说明脾胃受病不同之机，脉象未及。", []], "25181": ["病机", "原文未出脉名，论脾病四肢不用之机。四肢禀气于胃，必因脾行津液乃得禀水谷气；脾病不能为胃行津液，四肢失禀，气日以衰，脉道不利，筋骨肌肉无气以生，故不用。此以“脉道不利”言气血不充之机，非指具体脉象。", []], "25182": ["病机", "原文未出脉名，论喜怒寒暑伤气伤形，暴怒伤阴、暴喜伤阳，厥气上行、满脉去形。又引《玉机真脏论》脾太过则四肢不举、不及则九窍不通，及《调经论》形有余腹胀经溲不利、不足四肢不用。此以“满脉”言气逆脉满之机，非具体脉象。", []], "25183": ["病机", "原文引《经脉别论》“太阴藏搏者，用心省真，五脉气少，胃气不平，三阴也”，搏指脉来搏击有力，为太阴脏气搏结、胃气不平之象，故五脉气少。治宜补阳泻阴，取下肢俞穴。后文论脾病愈甚之时及身重、足痿、腹满飧泄等症，皆脾病虚实之候。", ["搏"]], "25184": ["病机", "原文论食气入胃后散精于肝、浊气归心、淫精于脉，脉气流经归于肺，肺朝百脉输精皮毛，最终气归于权衡而气口成寸以决死生。此段无具体脉象，主旨在于阐明水谷精气化生营血、循经布散、汇于气口而成脉的生理过程，说明气口脉能反映全身脏腑气血盛衰，故可决死生，属脉学原理之论。", []], "25185": ["病机", "原文引仲景“安谷则昌，绝谷则亡”，指出水谷尽则神去，水去则营散，谷消则卫亡，营散卫亡则神无所依；又言水入于经其血乃成，谷入于胃脉道乃行。此段无具体脉象，从营卫化源立论，说明血不可不养、卫不可不温，血温卫和则营卫乃行，强调水谷为脉道充盈、营卫运行之本。", []], "25186": ["平脉", "原文言春夏地之体人亦应之，食罢后皮肉筋骨血脉皆滑利，屈伸柔和而骨刚力盛。此处“脉皆滑利”非病脉，乃饮食后气血充盈、血脉流畅之常态，与春夏阳气升发相应。滑利示营血充盛、经脉通利，故屈伸柔和、用力不乏，属平脉范畴，说明脉随四时与饮食而变的生理性滑利。", ["滑"]], "25187": ["病机", "原文论饮食失节、寒温不适及情志损耗致脾胃气衰、元气不足，心火独盛而为阴火，起于下焦乘其土位。症见气高而喘、身热而烦、头痛口渴、皮肤不任风寒。脉洪大而头痛、脉洪，乃阴火上冲、气高喘而烦热所致，洪大为火盛气浮之象；脾胃之气下流则谷气不升，无阳护营卫而生寒热，此皆脾证病机。", ["洪", "大"]], "25188": ["治法", "原文为补脾胃泻阴火升阳汤之方药组成与服法：当归身和血脉，橘皮导气益元气，升麻引胃气上腾行春升之令，柴胡引清气行少阳上升，白术降胃中热。此段无脉象，主旨为治法，说明针对脾胃气衰、阴火乘土、谷气不升之证，以升阳益气、和血导气为法，量气弱气盛斟酌服之。", []], "25189": ["病机", "原文引《调经论》论血并于阳、气并于阴为炅中，又论劳倦形气衰少、谷气不盛、上焦不行、下脘不通、胃气热熏胸中为内热；阴盛生内寒，寒气积胸中不泻则温气去、血凝泣、脉不通，故脉盛大以涩，名曰寒中。盛大示寒邪壅盛、气血郁积，涩示血凝泣而脉不通，故主寒中病机。", ["大", "涩"]], "25190": ["病机", "原文论热中证冲脉之火传督脉，与足太阳膀胱寒气相附，其盛如巨川之水、疾如奔马；太阳寒气逆上冲顶入额，手太阳热气与足膀胱寒气逆于胸中，故脉盛大；小肠热气不能交入膀胱，十一经盛气积于胸中亦令脉盛大；膀胱逆行盛极，子能令母实，大肠燥旺挟势，故脉涩而大便不通。盛大主热盛气壅，涩主燥结便闭。", ["大", "涩"]], "25191": ["治法", "原文论壬膀胱之寒绝于巳、癸肾水绝于午，又逢湿旺助热为邪，西方北方寒清绝矣。圣人立法夏月宜补者补天元真气，非补热火，令人夏食寒。为热伤元气，以人参、麦门冬、五味子生脉，并释“脉者，元气也”，人参补元气泻热火，麦冬补水清燥金，五味子泻火补肺金。此段无脉象，主旨为治法，阐明生脉散治热伤元气之理。", []], "25192": ["主病", "脉弦洪缓而沉按时一涩，弦主肝郁气滞，洪缓主湿热内蕴，涩为湿阻血滞。故见四肢满闷、肢节烦疼、身体沉重、便溏或涩、胸满短气等症，皆脾虚湿困、气机不畅、兼有郁热之象，故以调中益气汤主之。", ["弦", "洪", "缓", "涩"]], "25193": ["治法", "原文未识脉名，只言煎服法及“病在四肢血脉，空腹在旦是也”，强调宿食消尽后热服，宁心绝思，使药力达于四肢血脉。此属服药调摄之法，非论脉象主病，故脉象要素为空。", []], "25194": ["兼症", "原文未识脉名，列举大便虚坐、身体沉重、胃气不和、痰厥头痛等兼症及加减法。其中“其脉亦络于心中”言足太阴脾脉络心，故显湿热相合而烦乱，属随证加减，非专论脉象主病。", []], "25195": ["病机", "原文未识脉名，述秋冬胃脉为冲脉所逆、少阳脉反上行，病名厥逆。引《内经》“逆气上行，满脉去形”，谓气上冲咽、喘急不得卧，乃冲胃之气上逆、神昏将绝之危候，故加吴茱萸降逆。", []], "25196": ["治法", "原文未识脉名，言夏月见此证为大热，随四时为寒热温凉，治以酒黄连、酒黄柏、酒知母泻冲脉之邪；并指出饮食劳倦所得乃虚劳七损证，当用温平甘多辛少之药，属治法与病机兼论。", []], "25197": ["病机", "长夏湿热大胜，脉中得洪缓，洪为热盛，缓为湿蒸；若湿气相搏必加之以迟，迟主湿阻阳郁。故见四肢困倦、胸满气促、身热烦渴、便溏溺黄等湿热交蒸之候，宜清燥之剂治之。", ["洪", "缓", "迟"]], "25198": ["兼症", "原文举脉弦、脉涩，弦主肝郁气滞，涩主血少或气滞血瘀。故四肢满闭、便难而心下痞者加甘草、黄连、柴胡；腹中气上逆为冲脉逆，加柏、连泄之。皆随脉兼症加减，非专论主病。", ["弦", "涩"]], "25199": ["病机", "原文两言脉洪大，洪大为热盛之象。若腹中水声、小便不调，诊得洪大则泻火利小便以去水饮；若大渴肌热、脉洪大按之无力，则非白虎汤证，乃血虚发躁，当以黄耆、当归补血。同一洪大，虚实迥别。", ["洪", "大"]], "25200": ["治法", "原文述飧泄不禁，以风药升阳、苍术去湿；若脉实而见䐜胀闭塞不通，则从权以苦多甘少药泄之。脉实主邪气内结、腑气不通，故胀满闭塞；得通后仍以升阳汤助阳，示攻邪不忘扶正，脉实为可下之凭。", ["实"]], "25201": ["病机", "原文以气口三倍大于人迎断为食伤太阴，上部有脉、下部无脉则知木郁在下、塞道不行、肝气下绝，兼肺金主塞不降，故食塞胸咽，当吐。脉象描述虽无具体脉名，但凭脉位上下与气口人迎对比定病机，属因脉测证。", []], "25202": ["病机", "原文论阴火炽盛由心生凝滞、七情不安，心君不宁化而为火，火为七神之贼，致经营之气不能颐养于神，乃脉病也；神无所养则津液不行、不能生血脉。虽未出具体脉名，但以“脉中唯有火”言脉病之机，主心神失养、阴火内扰。", []], "25203": ["病机", "原文述清气在阴、浊气在阳，营气顺脉、卫气逆行，清浊相干乱于胸中为大悗；气乱于心则烦心密嘿，乱于肺则悗仰喘喝，乱于肠胃为霍乱，乱于臂胫为四厥，乱于头为厥逆眩仆。虽无脉名，然以气乱立论，明营卫逆乱、清浊相干之病机。", []], "25204": ["治法", "原文言气在于臂足，取之先去血脉，后取阳明、少阳之荥输（二间、三间、内庭、陷谷深取之）。此段专论针灸治法，未及脉象，故脉象要素为空；主旨为去血脉之瘀滞、调阳明少阳经气以治气乱于臂足。", []], "25205": ["病机", "原文论阴病在阳者，乃天外风寒之邪乘中外入，客于背上腑腧脏腧；中于阳则流于经，病始于外寒、络归外热。六淫湿暑燥火皆五脏所受，各有背上五脏腧以除之，皆泻在背之腑腧；病久传变有虚有实，补泻不定。虽无脉名，主外邪客经、六淫传变之机。", []], "25206": ["病机", "原文论上热下寒，阴病在阳当从阳引阴，先去络脉经隧之血；若阴中火旺上腾于天，致六阳反不衰而上充，先去五脏血络引而下行，天气降则下寒自去，慎勿独泻六阳。此病阳亢乃阴火之邪滋之，只去阴火、损血络经隧之邪。虽无脉名，主阴火上腾、阳亢下寒之病机。", []], "25207": ["病机", "原文论阳病在阴者，病从阴引阳，是水谷寒热感则害人六腑；饮食失节、劳役形质，阴火乘于坤土，致谷气、营气、清气、胃气、元气不得上升滋于六腑阳气，五阳之气先绝于外，下流伏于坤土阴火之中。皆先由七情所伤，胃气不行，元气乃伤，当从胃合三里推而扬之以伸元气。虽无脉名，主阴火乘土、元气下陷之机。", []], "25208": ["病机", "原文未出脉名，但明言“脉者，血之府也，血亡则七神何依，百脉皆从此中变来”。饮食劳役伤脾，阴火乘土位，清气不生，阳道不行，阴血伏火，加之自汗、小便数，津液两亡，中宫无以化血，故百脉皆变。此段以血亡立论，说明脉由血府失养而生变，主脾胃内伤、津血亏耗之病机。", []], "25209": ["病机", "原文以“脉皆弱”为据，论脾为阴土、主静不动，胃为阳土、主动不息，脾胃受病则五脏气争、九窍不通。脉弱正应脾胃气虚、阳气不能升发，故九窍不利、头痛耳鸣。此段借脉弱说明脾胃虚弱、清阳不升而致九窍闭塞的病机。", ["弱"]], "25210": ["病机", "原文未出脉名，论脾胃虚则湿土之气溜于脐下，肾与膀胱受邪，润泽之气不行；胃虚则大肠、小肠、胆、三焦皆失禀气，津液不濡而口燥咽干、皮毛不泽。此段以脾胃虚为核心，说明六腑受气于胃、胃虚则诸腑俱虚、温热生长之气不足而伏留血脉为热病中风的病机。", []], "25211": ["病机", "原文言“心火亢甚，乘其脾土曰热中，脉洪大而烦闷”，又言心火左迁入肝木之分，风湿相搏，一身尽痛，“其脉洪大而弦，时缓”。洪大为心火亢盛之象，弦为风木之应，缓为湿土之征，故主热中、风痹、眩运战摇、麻木不仁等症，说明火乘脾土、风湿相搏的病机。", ["洪", "大", "弦", "缓"]], "25212": ["病机", "原文未出脉名，论五脏外主皮毛、血脉、肌肉、筋骨及各空窍，内无所受盛；胃气一虚，脾无所禀受，则四脏经络皆病。此段强调脾胃为受气之源，胃虚则周身四脏失养、九窍不利、外邪易侮，说明脾胃虚而四脏经络俱病的病机。", []], "25213": ["病机", "原文言足阳明胃脉衰，冲脉并阳明上行，逆于阳分，“脉之火大旺”，血随火上冲则血上行，火退伏于下则血下行，故“血上下行”，俗谓忽肥忽瘦。脉火大旺为胃虚火胜、壮火食气之象，主少气、寒热、血上下行，说明脾胃虚而火胜、阴血亏耗的病机。", ["大"]], "25214": ["病机", "原文未出脉名，论五气入鼻藏于心肺，肺主鼻，鼻和则知香臭；三焦之窍开于喉、出于鼻，九窍之用皆禀长生。此段以心肺与鼻窍相通立论，说明嗅觉、听觉等九窍功能皆赖脏腑之气充养，属脏腑与官窍相应的生理病机阐述，非直接言脉。", []], "25215": ["病机", "原文未出脉名，以清阳为天、浊阴为地立论，清阳出上窍、发腠理、实四肢，浊阴出下窍、走五脏、坚强骨髓，清中清者清肺助天真，浊中清者荣养于神。此段阐明清浊升降出入的正常生理，说明水谷精气化生营血、维持神明与四肢百骸的病机基础。", []], "25216": ["病机", "原文谓“弦脉令虚，多言之过，皆阳气衰弱，不得舒伸，伏匿于阴中”，指出弦脉非实，乃阳气虚而郁滞之象。脾胃久衰，阴盛乘阳，故脉见弦而按之虚。主阳气衰弱、湿邪内盛之泄利、体重肢痛、小便闭塞，病机为阳不舒伸，伏匿于阴中。", ["弦", "虚"]], "25217": ["治法", "原文虽未明言脉散，但“火炽之极，金伏之际，而寒水绝体”提示热极耗气伤阴，脉气耗散。生脉散以人参、五味子、麦冬酸甘化阴，敛散收耗，佐黄柏苦寒滋水镇浮。所主病机为火热刑金、气阴两伤，脉散无力，治以酸收甘泻，敛其涣散。", ["散"]], "25218": ["病机", "原文“筋脉血络中大寒”致口㖞筋急，服讫“以火熨摩紧结处而愈”，紧结即脉象紧急结滞，主寒凝血络。寒性收引，血络凝涩，故筋急口㖞。药代燔针劫刺以破血去凝结，内泄冲脉之火炽，说明寒凝与火郁并见，脉紧结为寒凝血滞之征。", ["紧", "结"]], "25219": ["病机", "原文未出具体脉名，但言“脉以候地”“以脉气候之”，强调湿邪为阴寒下行之地气。汗多亡阳，阳去阴胜，甚为寒中，湿胜则音声如从瓮中出，壅塞不出。病机为湿胜阳衰，外寒与内湿相合，终传寒中痹寒，脉当沉迟或濡，以候地之阴阳。", []], "25220": ["主病", "以右关脉缓为脾胃本脉，弦为风邪所伤，洪为热邪所伤，缓为湿邪所伤，涩为燥热所伤，沉细为寒邪所伤。五脉各主一邪，紧扣“脾胃右关所主”，说明同一部位脉象变化反映不同病邪伤脾，脉症相应，治法方药各异。", ["缓", "弦", "洪", "涩"]], "25221": ["兼症", "原文以“脉弦细”伴嗽、饮食减少，主脾虚肝郁、气血不足，故加当归、黄耆；以“脉洪大缓”主脾胃湿热壅盛，故加黄芩、黄连。脉弦细为虚中夹郁，洪大缓为湿热内蒸，随脉加减，体现凭脉辨兼症、随症用药之法。", ["弦细", "洪大缓"]], "25222": ["病机", "原文未出脉名，详述脾胃虚极、心火乘之，冬寒水旺，子能令母实，肺金大肠来克心乘脾胃，大胜必大复。症见恶风寒、耳鸣、脑痛、痰唾沃沫、食入反出、腹中常痛、便泻肠鸣等，皆脾胃虚极、寒水反乘、元气绝于外之候，脉当沉细而虚。", []], "25223": ["其他", "原文未出脉名，自述“百脉沸腾而烦心，身如众派漂流”，乃年老神气衰、血气失和之象。主张淡薄寡欲、省语养气、不妄作劳以养形，使血气谐和，邪无所容。所论重在养生却病，脉象虽未明言，而百脉沸腾即脉气浮扰不宁之状。", []], "25224": ["病机", "此段无脉象描述，专论内伤脾胃病机。原文强调饮食失节、起居不时、妄作劳役及情志所伤，损伤胃之元气，使营运之气减削，不能输精于皮毛经络，故诸邪乘虚而入，痰动于体而成痼疾。核心病机为胃气亏虚、宗气不足、营运之气减削，属内伤不足之证，与东垣补脾胃之说相承。", []], "25225": ["其他", "此段仅为《金匮要略》篇题，标明所论为脏腑经络先后病脉证，无具体脉象与病机内容。原文未出现任何脉象描述或症候分析，故脉象要素为空，主旨归为其他，不作病机推断。", []], "25226": ["病机", "此段论杂病病因三条，无脉象。原文以风气生害为喻，指出五脏元真通畅则安和，客气邪风则中人多死。病因分经络受邪入脏腑为内所因、四肢九窍血脉壅塞为外皮肤所中、房室金刃虫兽所伤三类，强调养慎防邪、早治勿令九窍闭塞，属病因病机总论。", []], "25227": ["病机", "此段与上段前半相同，重申风气生万物亦害万物，五脏元真通畅则安和，客气邪风中人多死。千般疢难不越三条：经络受邪入脏腑为内因，四肢九窍血脉壅塞为外中，房室金刃虫兽所伤。全段无脉象，主旨为杂病病因分类与病机总纲。", []], "25228": ["病机", "原文言寸口脉动者，因其旺时而动，如肝旺色青，四时各随其色。脉动应时令旺气，色亦当随脏而变；若肝色青而反色白，则非其时色脉，色脉不符，皆当病。此以脉动与色相应否判断病机，脉动应时为正，色脉相失则主病。", ["动"]], "25229": ["主病", "原文以脉浮分部言病位：浮者在前，其病在表；浮者在后，其病在里。浮脉主表，见于寸部为邪在表；若浮见于尺部，则非表证，而主里病，见腰痛背强不能行、短气而极。此以浮脉出现部位不同辨表里，说明同一脉象所在部位异则所主病机亦异。", ["浮"]], "25230": ["预后", "原文寸脉沉大而滑，沉则为实，滑则为气，实气相搏，血气入脏即死，入腑即愈，此为卒厥。沉主实、滑主气，实气相搏致血气逆乱。入脏则唇口青、身冷，为死候；入腑则身和、汗自出，为愈候。此以脉象结合症候判断卒厥预后。", ["沉", "大", "滑"]], "25231": ["预后", "此段论脉脱入脏即死、入腑即愈，非独一病，百病皆然。以浸淫疮为喻：从口流向四肢者可治，从四肢流来入口者不可治。病在外者可治，入里者即死。全段无具体脉象，主旨为以病位浅深判断预后，入里则危，在外可治。", []], "25232": ["病机", "原文以“风令脉浮，寒令脉急”点明五邪中人的法度：风为阳邪，轻扬外散，故脉浮；寒主收引，凝滞经脉，故脉急。此段总论阳病、阴病及五邪所伤，脉浮主风邪中表，脉急主寒邪伤经，与头痛项腰脊臂脚掣痛、拘急等症相应，说明邪中部位与脉象变化相合。", ["浮", "急"]], "25233": ["病机", "此段重申“风令脉浮，寒令脉急”，以脉象言五邪中人之法度。风性轻扬，中于表则脉浮；寒性收引，中于暮则脉急。雾伤皮腠、湿流关节、食伤脾胃，各有所中。脉浮为风邪在表之征，脉急为寒邪凝滞之象，说明外邪中人各有法度，脉象随邪气性质而变。", ["浮", "急"]], "25234": ["其他", "此段为《痉湿暍病脉证并治》篇题，未出具体脉象与证治条文，仅标示篇章范围。原文无脉象描述，故不能据以分析病机；其主旨在于统摄痉、湿、暍三类病证的脉证并治，属篇目总纲，非具体脉象主病之文。", []], "25235": ["预后", "太阳病本应脉浮，今发热而脉沉细，是邪在表而脉不应，正气不足、无力抗邪外达之象。原文径称“名曰痉，为难治”，说明沉细之脉反映营卫虚滞、筋脉失养，痉病已成而正虚邪恋，故预后不良。脉沉细与发热并见，正虚邪陷，故为难治。", ["沉", "细"]], "25236": ["病机", "此段描述痉病典型症候：身热足寒、颈项强急、恶寒、头热面赤目赤、头动摇、口噤、背反张，皆邪郁筋脉、经气不利所致。原文未出具体脉名，仅言“发其汗已，其脉如蛇”，形容误汗后脉象曲折不利，反映津伤筋急、脉道失柔，属痉病误治后的脉象变化。", []], "25237": ["预后", "暴腹胀大为欲解，是气机暂通之兆；若“脉如故，反伏弦者，痉”，则脉象未随之缓和，反见伏弦。伏主邪郁深入，弦主筋脉拘急，说明痉病未解，邪仍郁滞筋脉。脉与症相参，腹胀虽减而脉象未和，故断为痉病仍在，属预后判断。", ["伏", "弦"]], "25238": ["病机", "原文言“痉脉，按之紧如弦，直上下行”，又引《脉经》“痉家其脉伏坚，直上下”。紧弦主筋脉拘急，伏坚主邪郁深伏、脉道坚劲，皆反映痉病筋脉强急、邪气内郁之机。脉来直上下行，失柔和之象，正与颈项强急、背反张等症相应，说明痉病脉象以劲急坚紧为特征。", ["紧", "弦", "伏", "坚"]], "25239": ["治法", "太阳病证备而身体强𠘧𠘧然，脉不浮反沉迟，是表证兼津液不足、筋脉失养之痉。沉迟非纯寒，乃营阴不足、脉道不利所致。原文以栝蒌桂枝汤主之，取桂枝解表、栝蒌根生津柔筋，说明此脉主津伤筋急之痉，治当解表生津，属脉证合参以定治法。", ["沉", "迟"]], "25240": ["病机", "太阳病证备而身体强𠘧𠘧然，脉不浮反沉迟，说明表邪未解而津液已伤，筋脉失养，成为痉病。沉为在里，迟为津亏，故脉反沉迟，主柔痉，与身体强急、汗出恶风相应，治以栝蒌桂枝汤解肌生津。", ["沉", "迟"]], "25241": ["病机", "太阳病关节疼痛而烦，脉沉而细，说明湿邪痹着，阳气不宣，故脉沉；湿性濡滞，气血运行不畅，故脉细。此名湿痹，主湿邪内阻，与小便不利、大便反快相应，治当利其小便，使湿从下泄。", ["沉", "细"]], "25242": ["病机", "湿家身疼发热、面黄而喘、头痛鼻塞而烦，其脉大，说明寒湿郁于头中，阳气上逆，故脉大。自能饮食、腹中和无病，表明病不在里而在头中寒湿，主鼻塞，与头痛、喘、烦相应，治以纳药鼻中取嚏。", ["大"]], "25243": ["病机", "风湿相搏，脉浮身重，汗出恶风，说明风邪在表故脉浮，湿邪留着肌腠故身重，表虚不固故汗出恶风。此脉浮主风湿在表，与身重、汗出恶风相应，治以防己黄耆汤益气固表、祛风除湿。", ["浮"]], "25244": ["病机", "风湿之邪客于肌表，脉浮身重，汗出恶风，说明风性轻扬故脉浮，湿性重着故身重，表气不固故汗出恶风。此脉浮主风湿在表，与身重、汗出恶风相应，治以防己黄耆汤固表祛湿。", ["浮"]], "25245": ["病机", "伤寒八九日，风湿相搏，身体疼烦，不能自转侧，脉浮虚而涩，说明风邪在表故浮，阳气不足故虚，湿滞血行不畅故涩。此脉主风湿表虚，与身体疼烦、不呕不渴相应，治以桂枝附子汤温经散寒、祛风除湿。", ["浮", "虚", "涩"]], "25246": ["病机", "伤寒八九日，风湿相搏，身体疼烦，不能自转侧，脉浮虚而涩，说明表邪未解而阳气已虚，湿邪痹阻而血行涩滞。浮为风，虚为阳虚，涩为湿滞，主风湿表虚证，与身体疼烦、不呕不渴相应，治以桂枝附子汤。", ["浮", "虚", "涩"]], "25247": ["病机", "太阳中暍，发热恶寒，身重疼痛，脉弦细芤迟，说明暑热伤气耗津，气阴两虚。弦细为津伤筋急，芤为血虚，迟为阳气不足。此脉主暑伤气阴，与洒洒然毛耸、手足逆冷、小有劳身即热、口开齿燥相应，禁汗、温针、下法。", ["弦", "细", "芤", "迟"]], "25248": ["病机", "脉微弱为阳气虚馁、水湿内停之象。太阳中暍本应脉虚，今身热疼重而脉反微弱，乃夏月贪凉饮冷，水湿之邪行于皮中，阻遏阳气，故脉气无力鼓动。水湿浸淫肌肤则身疼重，阳气被遏则身热不扬。此非暑热伤气之正证，而是水湿伤阳之变证，故以瓜蒂汤吐去水湿。", ["微", "弱"]], "25249": ["病机", "脉微弱主阳气不足、水湿内困。夏月伤冷水，水行皮中，阻遏卫阳，故身热疼重而脉微弱。微为阳虚，弱为湿滞，脉证合参，知非暑热炽盛，乃水湿伤阳。水湿浸渍肌表，阳气不能外达，故身热而疼重；脉气无力，故微弱。治以瓜蒂汤涌吐水湿，湿去则阳通。", ["微", "弱"]], "25250": ["其他", "此段为百合病、狐惑病、阴阳毒病脉证并治篇的篇题，未出具体脉象与证治。原文仅标篇名，提示该篇专论百合病、狐惑病、阴阳毒三类病证的脉证与治法，属篇章总纲，故无脉象可析，亦不主具体病机。", []], "25251": ["病机", "脉微数，微为阴虚内热，数为热象。百合病百脉一宗，悉致其病，心肺阴虚内热，故脉微数。意欲食复不能食、常默默、欲卧不能卧等，皆阴虚内热、神志不宁之候；口苦、小便赤为热郁之征。身形如和而脉微数，正合阴虚内热之病机。溺时头痛者，热随溺泄而上冲，故病程较长。", ["微", "数"]], "25252": ["病机", "脉微数主阴虚内热。百合病者，百脉一宗，悉致其病，心肺阴虚，虚热内生，故脉微数。微为阴液不足，数为虚热鼓动。意欲食复不能食、欲卧不能卧、欲行不能行，皆神志不宁之象；口苦、小便赤为热郁。身形如和而脉微数，说明病在百脉，非形质之伤，乃阴虚内热之病机。", ["微", "数"]], "25253": ["治法", "此段论狐惑病蚀于肛者之外治法，以雄黄熏之。原文未出脉象，故无脉可析。狐惑病由湿热虫毒内蕴，蚀于下焦则肛阴溃蚀，雄黄熏法取其燥湿杀虫解毒之功，直接作用于患处。所引《脉经》文补充说明蚀上为惑、蚀下为狐，猪苓散主之，属外治与内治结合之例。", []], "25254": ["治法", "此段与前段重复，述雄黄熏肛之外治法，未出脉象。狐惑病湿热虫毒蚀于肛阴，故用雄黄末烧烟熏患处，以燥湿杀虫。所引《脉经》辨蚀上为惑、蚀下为狐，猪苓散主之，提示狐惑病当分上下施治。原文无脉象描述，故脉象要素为空，主旨属治法。", []], "25255": ["病机", "脉数主热，无热而微烦、默默欲卧、汗出，乃热毒内蕴血分，酿脓之候。目赤如鸠眼、目四眦黑，为热毒瘀血内结之征。脉数而无表热，知热在里；能食者，胃气尚强，脓已成也。赤豆当归散清热利湿、活血排脓，正合热毒瘀结之病机。", ["数"]], "25256": ["病机", "脉数而身无热、微烦欲卧、汗出，是热伏血分、瘀热内蕴之象。热在血分故脉数而不外显为身热；目赤如鸠眼、四眦黑，为热毒瘀结于目、脓将成之征。能食则胃气尚和，脓已成，故以赤豆当归散渗湿清热、排脓活血。脉数在此主瘀热成脓，非表热或虚热。", ["数"]], "25257": ["其他", "此段为篇题「疟病脉证并治第四」，属篇章标目，非具体脉象描述，故脉象要素为空。其主旨在于统摄疟病脉证治法，提示下文将论疟脉自弦及数、迟、小紧、浮大等兼脉之辨，为全篇纲领，不涉单一病机。", []], "25258": ["病机", "「疟脉自弦」为总纲，弦属少阳，主疟邪伏于半表半里。弦数多热、弦迟多寒，以迟数分寒热；弦小紧者邪偏里实可下，弦紧者可发汗针灸，浮大者邪偏上可吐，弦数者风发，当以饮食消息止之。此段以弦为基，兼脉辨寒热表里与治法，示疟病脉证相应之机。", ["弦", "数", "迟", "紧"]], "25259": ["病机", "温疟「其脉如平」，即脉不显疟之典型弦象，而身无寒但热、骨节疼烦、时呕，是热盛于里、兼夹表邪之候。脉如平说明邪热未形于脉，或脉象平和而症候已显，故不可以脉平忽之。治以白虎加桂枝汤清热透表，服后汗出愈，示脉症合参、以症测机。", ["平"]], "25260": ["病机", "此段与上条重出，温疟脉如平而身无寒但热、骨节疼烦、时呕，为里热炽盛兼表邪未解。脉如平者，热邪内蕴而未鼓动脉象，故须凭症辨治。白虎加桂枝汤清里热、透表邪，使汗出而愈，说明温疟之机在热而不在脉形之弦，脉症合参方得其真。", ["平"]], "25261": ["其他", "此段为篇题「中风历节病脉证并治第五」，属篇章标目，无具体脉象描述，故脉象要素为空。其旨在统摄中风与历节两病之脉证治法，为下文论中风脉微而数、历节脉浮紧等张本，不主单一病机。", []], "25262": ["病机", "「脉微而数，中风使然」，微为正气虚，数因邪气扰，正虚邪中故脉微而数。风邪入中，气血痹阻，故半身不遂或但臂不遂，此为痹。脉微示络脉空虚，数示风邪为病，正虚与邪扰并见，说明中风之机在正虚邪中、气血不荣，非单纯外风。", ["微", "数"]], "25263": ["病机", "寸口脉浮而紧，紧则为寒，浮则为虚，寒虚相搏，邪在皮肤；浮者血虚，络脉空虚，贼邪不泻。邪气反缓、正气即急，正气引邪故㖞僻不遂。邪在络则肌肤不仁，在经则重不胜，入腑不识人，入脏舌难言、口吐涎。此段以浮紧虚空的脉象说明正虚寒中、邪留经络、由浅入深之病机。", ["浮", "紧", "虚", "空"]], "25264": ["病机", "寸口脉浮而紧，紧主寒、浮主虚，寒虚相搏则邪在皮肤。浮为血虚、络脉空虚，贼邪不泻而或左或右；邪气反缓、正气即急，正气引邪故见㖞僻不遂。此段以浮紧并见说明正虚寒客、络脉空虚而风邪中络之病机，非单纯表寒。", ["浮", "紧", "虚", "空"]], "25265": ["病机", "脉迟而缓，迟则为寒、缓则为虚。营缓则亡血，卫缓则为中风，是营卫俱不足而寒虚相兼。邪气中经则身痒而瘾疹；心气不足、邪气入中则胸满而短气。此段以迟缓说明虚寒之体易受风邪，营卫虚滞为瘾疹、胸满短气之病机。", ["迟", "缓"]], "25266": ["治法", "本条出防己地黄汤方，治病如狂状、妄行、独语不休而无寒热，其脉浮。脉浮在此非表邪，乃血虚生热、热扰神明而气浮于外之象，故以大量生地黄养血凉血，配防己、桂枝、防风、甘草通络祛风。脉浮与狂状独语相应，示血虚风热之病机及治法。", ["浮"]], "25267": ["病机", "病如狂状、妄行、独语不休而无寒热，其脉浮。无寒热说明非外感表证，脉浮当责之血虚阳浮、热扰心神。血虚则神失所养，风热上扰则妄行独语，脉浮为气血浮越于外之应。此段以脉浮与狂状独语相参，揭示血虚风热、神明被扰之病机。", ["浮"]], "25268": ["病机", "寸口脉沉而弱，沉主骨、主肾，弱主筋、主肝，是肝肾不足之象。汗出入水中，如水伤心，寒湿内侵，郁而历节黄汗出，故曰历节。脉沉弱说明肝肾亏虚、筋骨失养，复因汗出涉水感寒湿，正虚邪凑而致历节疼痛黄汗之病机。", ["沉", "弱"]], "25269": ["病机", "趺阳脉浮而滑，滑则谷气实，浮则汗自出。趺阳候胃，滑为谷气壅实、胃热内盛，浮为热蒸津液外泄而汗自出。此段以浮滑说明胃中谷气实、热迫汗出之病机，与汗自出症候相应，非表虚自汗。", ["浮", "滑"]], "25270": ["病机", "少阴脉浮而弱，弱则血不足，浮则为风，风血相搏即疼痛如掣。少阴候肾，弱为阴血亏虚，浮为风邪外袭，血虚不能濡养筋脉，风邪乘虚与血相搏，故疼痛如掣。此段以浮弱说明血虚受风、风血相搏而致掣痛之病机。", ["浮", "弱"]], "25271": ["病机", "盛人脉涩小，短气、自汗出、历节痛不可屈伸，皆饮酒汗出当风所致。形盛而脉涩小，示气血不畅、湿滞血涩；饮酒助湿、汗出腠理开，风邪乘入，湿风相合痹阻关节，故历节痛而不可屈伸。此段以涩小说明湿滞血涩、风邪痹阻之病机。", ["涩", "小"]], "25272": ["其他", "本段为篇题，未出具体脉象，故脉象要素为空。篇题「血痹虚劳病脉证并治」提示全篇讨论血痹与虚劳两类病证的脉象、证候及治法，属总纲性质，不涉具体病机分析。", []], "25273": ["病机", "脉微涩为阳气虚、营血涩滞，寸口关上小紧为外受微风、寒凝血脉。尊荣人骨弱肌肤盛，疲劳汗出卧动摇，风邪乘虚袭入，致血行痹阻，故脉见微涩而紧。针引阳气令脉和紧去，则痹可愈，说明此脉主血痹初起、阳气痹阻之病机。", ["微", "涩", "紧"]], "25274": ["主病", "脉大为劳，极虚亦为劳。大脉非实，乃精气外浮、虚劳内损之象；极虚则元气亏竭。两者皆反映虚劳病本虚之机，故以脉之大与极虚并提，示人虚劳脉象有外浮与内衰两端，皆主虚劳。", ["大", "虚"]], "25275": ["病机", "面色薄主渴及亡血，卒喘悸，脉浮为里虚。此浮脉非表邪，乃阴血亏虚、阳气浮越于外之象。亡血则面色薄，津亏则渴，气浮则喘悸，脉浮应之，故曰里虚，说明浮脉在此主虚劳亡血、气浮于外之病机。", ["浮"]], "25276": ["病机", "脉虚沉弦，无寒热，短气里急，小便不利，面色白，时目瞑兼衄，少腹满，此为劳使之然。虚为气血不足，沉弦为阳虚阴凝、气机不畅。无寒热排除外感，诸症皆由虚劳内伤、阳气不运所致，故脉虚沉弦主虚劳夹寒、气化不利之病机。", ["虚", "沉", "弦"]], "25277": ["病机", "劳之为病，脉浮大，手足烦，春夏剧，秋冬差，阴寒精自出，酸削不能行。浮大为阳气外浮、阴精内亏之象。春夏阳升则剧，秋冬阳藏则差，阴寒精出、酸削不能行，皆虚劳精亏、阳浮于外之候，故脉浮大主虚劳阴阳两虚、阳浮精亏之病机。", ["浮", "大"]], "25278": ["主病", "男子脉浮弱而涩，为无子，精气清冷。浮为阳虚外浮，弱为气血不足，涩为精血亏少、脉道不利。三者并见，反映肾精虚冷、气血不充，故主无子，说明此脉象主精气清冷、生殖之精亏乏之病机。", ["浮", "弱", "涩"]], "25279": ["病机", "失精家少腹弦急，阴头寒，目眩发落，脉极虚芤迟，为清谷亡血失精；脉得诸芤动微紧，男子失精，女子梦交。极虚芤迟为精血亏耗、阳气虚衰；芤动微紧为阴精亏而虚阳扰动。两脉皆主虚劳失精、阴阳两虚、虚阳不潜之病机，故以桂枝加龙骨牡蛎汤调阴阳、潜浮阳。", ["虚", "芤", "迟", "动"]], "25280": ["病机", "脉极虚芤迟，虚为精气亏，芤为血少，迟为阳衰，故主清谷亡血失精；芤动微紧，动紧相合，阴阳失交，故男子失精、女子梦交。少腹弦急、阴头寒、目眩发落，皆精血虚寒、不能温养之候，桂枝加龙骨牡蛎汤调和阴阳、固摄精气。", ["虚", "芤", "迟", "紧"]], "25281": ["主病", "平人而脉虚弱细微，虚为气不足，弱为血不充，细微为阴阳俱损。卫外之阳不固，营阴不能内守，故喜盗汗。此非外邪，乃内伤虚损之渐，脉象已露虚象，虽未见他症，盗汗为其征。", ["虚", "弱", "细", "微"]], "25282": ["病机", "年五六十而病脉大，大非实热，乃劳伤精气、虚阳外浮之象。痹侠背行、肠鸣、马刀侠瘿，皆劳损日久、气血瘀滞、痰凝络脉所致。脉大而病劳，说明正虚为本、邪结为标，非外感实邪可比。", ["大"]], "25283": ["病机", "脉沉小迟，名为脱气。沉为阳虚不能鼓动，小为气衰，迟为阳微。阳气虚脱，故疾行则喘喝；不能温煦四末，故手足逆寒；中阳不运，故腹满、溏泄、食不消化。此脾肾阳衰、气陷不升之候。", ["沉", "小", "迟"]], "25284": ["病机", "脉弦而大，弦则为减，大则为芤，减为寒，芤为虚，虚寒相搏，名曰革。革脉外急中空，主精血虚寒。妇人半产漏下，男子亡血失精，皆因虚寒不能固摄、精血外泄所致，与芤革之象相应。", ["弦", "大", "芤", "革"]], "25285": ["预后", "虚劳不足、汗出而闷，脉结悸，结为气血虚衰、脉道不利，悸为心阳不振。行动如常而脉已结，说明外似无恙、内实虚损，故不出百日危；危急者十一日死。炙甘草汤通阳复脉，正为此设。", ["结"]], "25286": ["预后", "本条与上条同文，重出。虚劳汗出而闷，脉结悸，结为气血虚涩、脉行断续，悸为心失所养。行动如常而脉结，是形安脉败，故预后不良，不出百日，危急者十一日死，示脉象为决死生之要。", ["结"]], "25287": ["其他", "本段仅标篇名「肺痿肺痈咳嗽上气病脉证治第七」，未出具体脉象文字，故脉象要素为空。此篇主旨为肺痿、肺痈、咳嗽上气之辨治，属篇目总纲，非论某一脉象所主，故归其他。", []], "25288": ["病机", "寸口脉数主热，热在上焦，肺失清肃，故咳而吐浊唾涎沫，为肺痿；脉数虚者，津液重亡，虚热灼肺，肺叶痿弱。若脉反滑数，滑主痰热，数主热盛，热壅血瘀，蓄结痈脓，故为肺痈，咳唾脓血。数实为邪实，数虚为正虚，虚实之辨系于肺痿、肺痈之别。", ["数", "滑", "虚", "实"]], "25289": ["主病", "寸口脉数，热在上焦，其人咳而口中反有浊唾涎沫，为肺痿。若口中辟辟燥，咳即胸中隐隐痛，脉反滑数，滑主痰热，数主热盛，热壅血瘀，蓄结痈脓，故为肺痈，咳唾脓血。脉数同而滑与不滑，辨肺痿、肺痈之异。", ["数", "滑"]], "25290": ["病机", "脉数虚者为肺痿，数实者为肺痈。数主热，虚为津液重亡，肺失濡养，虚热灼肺，故痿弱不用；实为邪热壅盛，热伤血脉，血为之凝滞，蓄结痈脓。同一数脉，虚实迥别，以脉之虚实定病之性质。", ["数", "虚", "实"]], "25291": ["病机", "寸口脉微而数，微则为风，数则为热。风中于卫，呼气不入；热过于营，吸而不出。风伤皮毛，热伤血脉，风舍于肺，其人则咳，口干喘满，咽燥不渴，多唾浊沫，时时振寒。热之所过，血为之凝滞，蓄结痈脓，吐如米粥。微数之脉，示风热相合，营卫俱伤，渐成肺痈。", ["微", "数"]], "25292": ["预后", "上气面浮肿，肩息，其脉浮大，不治，又加利尤甚。脉浮大者，正气浮越于外，水气太过，肾不纳气，肺失肃降，故上气肩息、面浮肿。浮大之脉见于虚喘，为真元涣散，阴阳离决之兆，故曰不治；若加下利，则中气更败，故尤甚。", ["浮", "大"]], "25293": ["治法", "咳而脉浮者，厚朴麻黄汤主之。脉浮为邪在表，风寒束肺，肺气上逆，故咳。厚朴麻黄汤中麻黄、细辛、干姜、半夏散寒化饮，石膏清郁热，杏仁、五味子、小麦降逆敛肺，厚朴宽胸下气。脉浮示病位偏表，故以宣散为主，佐以清降。", ["浮"]], "25294": ["治法", "咳而脉浮者，厚朴麻黄汤主之。脉浮主邪在表，风寒外束，肺气不降，故咳。厚朴麻黄汤以麻黄、细辛、干姜、半夏散寒化饮，石膏清郁热，杏仁、五味子、小麦降逆敛肺，厚朴宽胸下气。脉浮为病机关键，示邪偏表，故治以宣散为主。", ["浮"]], "25295": ["治法", "脉沉者，泽漆汤主之。脉沉主水气内停，饮邪犯肺，肺失肃降，故咳。泽漆汤中泽漆、半夏、生姜、前胡、桂枝通阳化饮，紫参、黄芩、甘草、人参益气清热。脉沉示病位偏里，水饮内结，故治以逐水通阳，与脉浮者之宣散迥异。", ["沉"]], "25296": ["主病", "脉沉主里，水气内停，故用泽漆汤逐水通阳。原文“脉沈者，泽漆汤主之”提示水饮内结，病位在里，当见咳逆、水肿等症。沉脉为水气内伏之征，治以攻逐水饮。", ["沉"]], "25297": ["主病", "脉数主热，热毒壅肺，腐肉成脓，故见咳而胸满、振寒、咽干不渴、浊唾腥臭，久久吐脓如米粥，为肺痈。数脉反映热毒炽盛，桔梗汤排脓解毒。", ["数"]], "25298": ["主病", "脉数主热，热毒壅肺，腐肉成脓，故见咳而胸满、振寒、咽干不渴、浊唾腥臭，久久吐脓如米粥，为肺痈。数脉反映热毒炽盛，桔梗汤排脓解毒。", ["数"]], "25299": ["主病", "脉浮大主风热壅肺，水气上逆，肺胀喘咳，目如脱状。浮为风邪在表，大为热盛，风水相搏，饮邪上迫，故用越婢加半夏汤宣肺泄热，化饮降逆。", ["浮", "大"]], "25300": ["主病", "脉浮大主风热壅肺，水气上逆，肺胀喘咳，目如脱状。浮为风邪在表，大为热盛，风水相搏，饮邪上迫，故用越婢加半夏汤宣肺泄热，化饮降逆。", ["浮", "大"]], "25301": ["病机", "脉浮主表，亦主水气在上。肺胀咳喘烦躁，心下有水，水饮郁热上迫，故脉浮。小青龙加石膏汤解表化饮，兼清郁热，浮脉提示水饮兼表邪。", ["浮"]], "25302": ["病机", "脉浮主表，亦主水气在上。肺胀咳喘烦躁，心下有水，水饮郁热上迫，故脉浮。小青龙加石膏汤解表化饮，兼清郁热，浮脉提示水饮兼表邪。", ["浮"]], "25303": ["主病", "脉数主热，热毒壅肺，腐肉成脓，故咳而胸满、振寒、咽干不渴、浊唾腥臭，久久吐脓如米粥，为肺痈。桔梗白散排脓解毒，数脉示热毒炽盛。", ["数"]], "25304": ["主病", "咳而胸满、振寒脉数，数主热，热壅肺络，腐化为痈，故咽干不渴、浊唾腥臭、吐脓如米粥，此肺痈已成之候。脉数在此非表热，乃热毒内蒸、血肉腐败之征，与胸满振寒并见，说明病位在肺、病性属热毒壅盛。", ["数"]], "25305": ["其他", "此段仅为奔豚气病脉证治篇题，原文未出具体脉象与证候，故脉象要素为空。篇题提示该篇专论奔豚气病之脉证并治，属篇章标目，非具体病机条文，不能据以推断脉象主病。", []], "25306": ["其他", "此段仅为胸痹心痛短气病脉证治篇题，原文未载具体脉象与证候，故脉象要素为空。篇题标明该篇讨论胸痹、心痛、短气三证的脉证与治法，属篇章标目，非具体脉象主病条文。", []], "25307": ["病机", "原文以「阳微阴弦」论胸痹心痛之机：阳微指寸口脉微，主上焦阳虚；阴弦指尺中脉弦，主阴寒内盛。极虚之阳不能温煦，阴寒之邪上乘阳位，痹阻胸阳，故胸痹而痛。此脉说明本虚标实、阴乘阳位之病机，与喘息咳唾、胸背痛、短气相应。", ["微", "弦"]], "25308": ["主病", "寸口脉沉而迟，沉主里、迟主寒，说明胸阳不振、寒饮内停；关上小紧数，紧主寒凝、数主阳郁，反映中焦寒饮上逆、阳气被遏。脉证合参，胸痹之喘息咳唾、胸背痛、短气，乃上焦阳虚、阴寒痰浊痹阻所致，故以栝蒌薤白白酒汤通阳散结。", ["沉", "迟", "紧", "数"]], "25309": ["主病", "此条与上条文字相同，重申胸痹主脉：寸口脉沉而迟，主胸阳不足、寒饮内停；关上小紧数，主寒饮上逆、阳郁化热之象。沉迟紧数并见，说明本虚标实、寒饮痹阻胸阳，故见喘息咳唾、胸背痛、短气，治以栝蒌薤白白酒汤宣痹通阳。", ["沉", "迟", "紧", "数"]], "25310": ["其他", "此段仅为腹满寒疝宿食病脉证治篇题，原文未出具体脉象与证候，故脉象要素为空。篇题标明该篇讨论腹满、寒疝、宿食三病的脉证与治法，属篇章标目，非具体脉象主病条文，不能据以分析病机。", []], "25311": ["病机", "趺阳脉微弦，微主阳虚，弦主寒、主痛。趺阳候脾胃，脉微为胃阳不足，弦为寒邪内盛，虚寒从下上逆，故法当腹满；若不满而便难、两胠疼痛，亦属虚寒凝滞、气机不通。原文明言「此虚寒从下上也」，当与温药，说明病机为下焦虚寒上逆。", ["微", "弦"]], "25312": ["病机", "脉弦主肝，肝脉布胁，弦为气机拘急之象。寸口脉弦，知肝气郁滞，经气不利，故胁下拘急而痛；卫阳被郁，失于温煦，则啬啬恶寒。此非外感表证，乃肝郁气滞、阳郁不达之病机，与《金匮》肝着、胁痛类证相应。", ["弦"]], "25313": ["治法", "腹满发热十日，脉浮而数，浮为邪在表，数为热盛；饮食如故，知里未成实，病偏于表而兼里滞。厚朴七物汤以桂枝、生姜解表，厚朴、枳实、大黄行气除满，表里双解。此脉示表热未罢、里气壅滞之机，故用表里同治之法。", ["浮", "数"]], "25314": ["主病", "脉浮而数，浮主表，数主热，合腹满发热十日，为表邪未解、里热已生之候。饮食如故，说明胃气尚和，里未燥结，故不用承气而用厚朴七物汤。此脉主腹满兼表热之病，与发热、腹满、饮食如故等症相应，示表里同病而以气滞为主。", ["浮", "数"]], "25315": ["病机", "脉紧弦，紧主寒，弦主痛，为寒实内结之象。胁下偏痛而发热，非表热，乃寒凝气滞、阳气被郁所致。寒实积于胁下，非温不散，非下不去，故以大黄附子汤温药下之。此脉示寒实内结、阳气不运之病机，与胁下偏痛、发热相应。", ["紧", "弦"]], "25316": ["主病", "胁下偏痛发热，脉紧弦，紧为寒，弦为痛，此寒实内结之脉。寒邪凝聚胁下，气血不通则偏痛；阳气郁遏则发热。脉证合参，主寒实内结之病，故用大黄附子汤温下寒积。此脉与胁下偏痛、发热相应，非表寒亦非虚寒。", ["紧", "弦"]], "25317": ["病机", "脉弦而紧，弦则卫气不行而恶寒，紧则不欲食，邪正相搏结于腹中，发为寒疝。绕脐痛、白汗出、手足厥冷，皆阴寒内盛、阳气衰微之象。其脉沉紧，沉主里，紧主寒，示寒邪深入、阳气不振之病机，故用大乌头煎峻逐沉寒。", ["弦", "紧", "沉"]], "25318": ["主病", "腹痛脉弦而紧，弦为卫气不行，紧为不欲食，邪正相搏则为寒疝。绕脐痛、白汗出、手足厥冷，其脉沉紧，沉紧主里寒痼结。此脉主寒疝之病，与绕脐剧痛、汗出肢冷相应，乃阴寒内盛、阳气欲脱之重证，故主以大乌头煎。", ["弦", "紧", "沉"]], "25319": ["病机", "腹痛脉弦而紧，弦则卫气不行而恶寒，紧则不欲食，邪正相搏即为寒疝。弦紧相合，示寒邪与正气相争于里，气机凝滞不通。此脉说明寒疝病机为阴寒内结、卫阳不布，与恶寒、不欲食、腹痛相应，故当温散寒邪。", ["弦", "紧"]], "25320": ["主病", "沉紧为寒实内结之脉。沉主里，紧主寒主痛，寒邪凝滞腹中，故绕脐痛；寒盛阳衰，卫外不固则发时白汗出，阳气不达四末则手足厥冷。脉证相合，示阴寒痼结、阳气被遏之机，故以大乌头煎峻逐沉寒。", ["沉", "紧"]], "25321": ["病机", "原文以“状如弓弦，按之不移”状紧弦之象，数而紧乃弦，示寒实内结、脉气劲急；紧大而迟者寒实阻于心下，故必心下坚；大而紧为阳中有阴，即热象中夹寒实。诸脉皆围绕寒实可下之机，故曰“当下其寒”“可下之”。", ["数", "紧", "弦", "大"]], "25322": ["主病", "寸口浮大似属外感，然按之反涩、尺中亦微而涩，知非表证。浮大乃谷气壅盛于外，涩为宿食阻滞、脉道不利，微涩见于尺中示里气不畅。脉证合参，断为宿食内停、实滞于中，故用大承气汤下其积滞。", ["浮", "大", "涩", "微"]], "25323": ["主病", "数主热，滑主实主食积。脉数而滑，为实热与宿食相搏、气血壅盛之象，故原文直断“实也，此有宿食”。实滞内结非下不去，故曰“下之愈，宜大承气汤”，示宿食化热成实之病机。", ["数", "滑"]], "25324": ["主病", "紧脉主寒主痛，亦主宿食。原文以“如转索无常”形容紧脉劲急而左右弹指、变动不居，正是宿食内停、气机壅滞、脉气搏击之象。故仅凭此紧脉即可辨为有宿食，示食积阻中、胃气不舒之病机。", ["紧"]], "25325": ["主病", "紧脉既主外寒，又主内积。原文以“脉紧”统言头痛风寒与腹中宿食不化，示寒邪外束则头痛，食积内停则脉亦紧。一脉兼主表寒与宿食，说明紧脉所反映的是寒凝气滞、食阻不化之病机，须结合症候分辨。", ["紧"]], "25326": ["其他", "此段为篇题“五脏风寒积聚病脉证并治第十一”，非具体脉象描述，故脉象要素为空。篇题标明所论为五脏中风、中寒及积聚之脉证与治法，属全篇纲领，提示后文诸条皆围绕五脏寒热虚实与积聚类病展开。", []], "25327": ["兼症", "此段未出脉名，专述肝中寒之症：两臂不举、舌本燥、喜太息、胸中痛、不得转侧、食则吐而汗出。肝受寒邪，筋脉拘急则臂不举、转侧不利；寒郁气滞则太息胸痛；木不疏土、胃气上逆则食吐。诸症共示肝寒犯胃、气机郁滞之机。", []], "25328": ["预后", "心中寒，症见心如噉蒜状，剧则心痛彻背、背痛彻心，如蛊注之状。脉浮说明寒邪有外达之势，非沉伏内闭，故可因势利导，得吐则寒邪从上越而愈。浮为阳脉，主邪在表、在上，此处提示病位偏上，正气尚能驱邪外出，故以吐为顺，属预后判断。", ["浮"]], "25329": ["病机", "心伤者劳倦则头面赤、下重、心中痛自烦、发热、当脐跳，脉弦。弦为肝脉，心伤而脉弦，说明心脏受损后肝木乘之，木火相煽，故见头面赤、烦热；脐跳为肾气不宁、冲脉动。脉弦紧扣心脏伤所致，揭示心伤而肝邪偏旺、虚风内动之病机。", ["弦"]], "25330": ["病机", "趺阳脉浮而涩，浮则胃气强，涩则小便数，浮涩相搏则大便坚，其脾为约。浮为胃热偏盛，涩为津液不足、脾阴受约，脾不能为胃行其津液，故小便数而大便坚。此段以脉释病机，说明脾约证由胃强脾弱、津亏肠燥所致，麻子仁丸润肠泄热以复其常。", ["浮", "涩"]], "25331": ["病机", "趺阳脉浮而涩，浮则胃气强，涩则小便数，浮涩相搏，大便则坚，其脾为约。浮主胃热气盛，涩主津液亏少，二者相合，脾受胃热约束而不能输布津液，偏渗膀胱则小便数，肠道失润则大便坚。此段专以脉象阐发脾约病机，为麻子仁丸证之脉理依据。", ["浮", "涩"]], "25332": ["病机", "诸积大法，脉来细而附骨者乃积也。积为脏病，终不移，病位深痼，故脉细而附骨，细主气血衰少，附骨即沉伏着骨，说明邪结深沉、正气内困。原文又以寸口、关上、尺中及左右脉出部位定积之所在，示脉象部位与病位相应，是积病脉诊定位之总纲。", ["细", "沉"]], "25333": ["其他", "此段仅为篇题「痰饮咳嗽病脉证并治第十二」，无具体脉象描述与证治条文，故脉象要素为空。篇题标明该篇专论痰饮咳嗽之脉证并治，属篇章分类标题，不构成独立病机分析，故归入其他类，不作脉理推断。", []], "25334": ["病机", "胸中有留饮，症见短气而渴，四肢历节痛，脉沉者有留饮。饮邪留聚胸中，阻遏气机则短气，津不上承则渴；饮溢四肢、痹阻关节则历节痛。脉沉主病在里、水饮内停，沉脉与留饮内踞之病位相应，说明饮邪深留而非表邪，故以沉脉断其有留饮。", ["沉"]], "25335": ["病机", "饮水多则暴喘满，食少饮多则水停心下，甚者悸、微者短气。脉双弦者寒也，皆大下后善虚；脉偏弦者饮也。双弦为虚寒内盛，偏弦为饮邪偏着一处。弦脉主饮、主寒、主痛，此段以双弦、偏弦辨寒与饮，说明水饮内停、阳气不布之病机。", ["弦"]], "25336": ["病机", "脉双弦者，两手皆弦，弦为寒饮内盛，又因大下后中阳受损，虚寒内生，故主寒；脉偏弦者，一手独弦，饮邪偏注一处，故主饮。原文以双弦、偏弦分言寒与饮，紧扣“大下后善虚”点明虚寒之由，脉弦应寒饮之邪。", ["弦"]], "25337": ["病机", "支饮喘而不能卧、短气，症候明显，而脉反平，说明饮邪深伏，未形于脉，或正气尚能抗邪，脉象未显异常。原文以“其脉平也”点出脉症不符，提示辨饮当重证候，不可仅凭脉断，此脉平非无病，乃饮伏之特殊表现。", ["平"]], "25338": ["病机", "脉伏为饮邪内结、阳气被遏之象。其人欲自利，利反快，是留饮有欲去之势；虽利而心下续坚满，说明饮邪未尽，伏结心下。原文“此为留饮欲去故也”点明病机，脉伏正合饮结阳郁，故以甘遂半夏汤攻逐留饮。", ["伏"]], "25339": ["病机", "脉伏主饮邪深结、阳气不伸。欲自利而利反快，为留饮欲去之机；虽利心下续坚满，是饮邪根结未除。原文“此为留饮欲去故也”直指病机，脉伏与留饮内结相应，故用甘遂半夏汤因势利导，攻逐水饮。", ["伏"]], "25340": ["主病", "脉浮而细滑，浮主饮邪在表或上，细滑主饮湿内蕴。原文直断“伤饮”，即饮邪伤中。浮细滑并见，说明饮邪初伤，未至沉结，脉象尚带浮滑，与暴饮伤中之病机相应，故以脉测证，主伤饮。", ["浮", "细", "滑"]], "25341": ["预后", "脉弦主饮，数主热，弦数并见为寒饮内郁而兼热象。原文谓“有寒饮，冬夏难治”，因冬寒助饮、夏热助数，寒热错杂，饮热相搏，故冬夏皆难调治。脉弦数揭示寒饮兼热之病机，预后判断紧扣时序与脉象。", ["弦", "数"]], "25342": ["主病", "脉沉主里主水，弦主饮主痛。沉弦并见，为饮邪深结于里，悬饮内停，气机不通，故内痛。原文“悬饮内痛”直指病所，脉沉弦与饮结胸胁、络脉不和之病机相应，故以此脉主悬饮内痛之证。", ["沉", "弦"]], "25343": ["病机", "脉沉紧，沉主里，紧主寒主饮。膈间支饮，喘满、心下痞坚、面色黧黑，皆饮邪内结、阳气不布之象。得之数十日，医吐下不愈，说明饮结深固。脉沉紧正合支饮内结、寒饮相搏之病机，故主木防己汤证。", ["沉", "紧"]], "25344": ["病机", "脉沉紧主膈间支饮。沉为水饮内停，紧为寒饮搏结，饮邪支撑胸膈，故喘满、心下痞坚；水气上泛，营卫不布，面色黧黑。吐下不愈者，饮邪胶结，非攻逐可解，故以木防己汤行水散结。", ["沉", "紧"]], "25345": ["病机", "咳家脉弦，弦为水饮内停之象。饮邪射肺则咳，故曰“为有水”。此以脉弦断其病本在水，非单纯肺气上逆，故用十枣汤峻逐水饮，饮去则咳自止。", ["弦"]], "25346": ["预后", "久咳数岁，脉弱为正虚尚能抗邪，故“可治”；实大数则邪盛正衰，故主死。脉虚者必苦冒，因支饮在胸中，清阳不升。此以脉之强弱虚实辨久咳之预后，并明冒之由饮。", ["弱", "实", "大", "数"]], "25347": ["病机", "寸脉沉、尺脉微，下后阳伤，饮动冲气。寸沉主饮停上焦，尺微主下焦阳虚，冲气上逆则气从小腹上冲胸咽，手足厥逆、痹；虚阳浮越则面翕热如醉。治以桂苓五味甘草汤平冲降逆。", ["沉", "微"]], "25348": ["病机", "寸脉沉、尺脉微，下后阳伤，饮动冲气。寸沉主饮停上焦，尺微主下焦阳虚，冲气上逆则气从小腹上冲胸咽，手足厥逆、痹；虚阳浮越则面翕热如醉。治以桂苓五味甘草汤平冲降逆。", ["沉", "微"]], "25349": ["其他", "此段为消渴、小便利、淋病脉证并治篇题，未出具体脉象，故脉象要素为空。篇题统摄消渴、小便不利、淋证三类病证，提示下文将围绕津液代谢失常、肾与膀胱气化不利等病机展开辨治。", []], "25350": ["病机", "寸口脉浮迟，浮为卫气虚，迟为营气竭，主营卫不足；趺阳脉浮数，浮为胃气盛，数为消谷，气盛溲数，溲数则坚，坚数相搏，津液耗伤，发为消渴。此以寸口、趺阳合诊，辨消渴营卫虚与胃热盛之机。", ["浮", "迟", "数"]], "25351": ["病机", "寸口脉浮而迟，浮即为虚，迟即为劳。浮为卫气不足于外，迟为营气竭于内，营卫俱虚，故脉浮迟并见。此以脉释虚劳之机，非独主一病，乃示上焦营卫虚损之病理。", ["浮", "迟"]], "25352": ["病机", "趺阳脉浮为胃气偏盛，数为胃热消谷，故“浮即为气，数即消谷而大坚”。气盛则水液偏渗，溲数而津伤，肠失濡润故大便坚。坚与数相搏，燥热内炽，津液耗损，发为消渴。此脉主胃热气盛、津亏燥结之消渴病机。", ["浮", "数"]], "25353": ["治法", "脉浮为邪在表，小便不利为水停不化，微热消渴乃水蓄而津不上承。此非真热消渴，乃太阳表邪与水饮互结。故治宜利小便发汗，通阳化气，使水去津布，以五苓散主之。脉浮在此提示病位偏表、气化不利。", ["浮"]], "25354": ["病机", "趺阳脉数，主胃中有热。胃热炽盛则消谷引食，即“消谷引食”；热灼津液，肠道失润，故“大便必坚”；热盛水液偏渗，故“小便即数”。此脉数说明胃热内盛、津液耗伤，主消渴之中焦燥热病机。", ["数"]], "25355": ["治法", "脉浮发热为表热，渴欲饮水为热伤津液，小便不利为水热互结、气化不行。此属水热蓄结下焦，兼阴伤。猪苓汤以猪苓、茯苓、泽泻利水，滑石清热，阿胶养阴，使水去热清而阴不伤。脉浮提示热势偏表，然病本在水热互结。", ["浮"]], "25356": ["治法", "脉浮发热，渴欲饮水，小便不利，为水热互结下焦、气化失司之证。脉浮示热邪偏表，渴与小便不利示水蓄津伤。猪苓汤利水清热养阴，使水热从小便去，津液得复。此条与上条同文，重申水热互结之治法。", ["浮"]], "25357": ["其他", "此段为“水气病脉证并治第十四”篇题，非具体脉证条文，故无脉象可辨。篇题提示该篇专论水气病之脉证与治法，下文风水、皮水、正水、石水、黄汗诸条皆属此范畴。本条仅标示篇章主旨，不涉具体病机。", []], "25358": ["病机", "风水脉浮，邪在表，故骨节疼痛恶风；皮水脉亦浮，水溢肌肤，按之没指，腹如鼓而不渴；正水脉沉迟，水停于里，气逆故喘；石水脉自沉，水结下焦，腹满不喘；黄汗脉沉迟，湿热郁蒸，身热胸满，四肢头面肿，久则腐溃成痈脓。诸脉分主水气病不同病位与病机。", ["浮", "沉", "迟"]], "25359": ["病机", "脉浮为风邪在表，洪为气盛。风气相搏，风强则外发瘾疹，身体瘙痒，久为痂癞；气强则水气泛溢，难以俯仰，身体洪肿。风气相击，汗出乃愈。恶风者属风水表虚；不恶风而小便通利、口多涎者，为上焦有寒之黄汗。此脉主风气相搏、水气泛溢之病机。", ["浮", "洪"]], "25360": ["主病", "寸口脉沉滑，沉主水气内停，滑主水湿壅盛，故曰「中有水气」。水气上泛则面目肿大、目窠微拥如蚕新卧起状；水溢肌肤则按之陷而不起；水气凌肺则时时咳；颈脉动为水气上冲之征。脉沉滑与风水诸症相应，示水湿内盛而兼有热。", ["沉", "滑", "动"]], "25361": ["兼症", "脉浮而紧本主太阳伤寒骨节疼痛，今反不痛而身体重酸、不渴，是风水之邪偏重于表而湿胜，故汗出即愈。原文又辨恶寒者为极虚发汗所致，渴而不恶寒者为皮水，身肿而冷如周痹者为黄汗，咳喘不渴者为脾胀，并告诫渴而下利、小便数者不可发汗，皆以脉浮紧为纲辨析水气诸证。", ["浮", "紧"]], "25362": ["病机", "太阳病脉浮而紧，浮为邪在表，紧为寒束，法当骨节疼痛；今反不痛而身体重酸、不渴，是风水之湿偏胜，故汗出即愈。若见恶寒，则非单纯风水，乃极虚之人发汗太过所致，脉浮紧在此提示表虚寒束、营卫不和之病机。", ["浮", "紧"]], "25363": ["主病", "里水者一身面目黄肿，其脉沉，沉主水气内停、病在里。小便不利则水无出路，故令病水；若小便自利而渴，则为亡津液所致，非水气内停。脉沉与一身面目黄肿、小便不利相应，示水湿内盛、气化不利，故以越婢加术汤主之。", ["沉"]], "25364": ["误治", "趺阳脉当伏，今反紧，紧主寒，故本自有寒、疝瘕、腹中痛。医反下之，下之虚其里气，寒邪上逆，即胸满短气。脉紧在此示本有寒积，误下后变生胸满短气之坏证，说明脉证合参以禁下。", ["紧"]], "25365": ["病机", "趺阳脉当伏，今反数，数主热，故本自有热、消谷、小便数。今小便反不利，是热与水结、气化不行，水湿内停，此欲作水。脉数在此示里有热而水气将成，热与水搏，故小便不利而病水。", ["数"]], "25366": ["病机", "寸口脉浮而迟，浮则为热，迟则为潜，热潜相搏名曰沉；趺阳脉浮而数，浮即为热，数即为止，热止相搏名曰伏。沉伏相搏名曰水。沉则脉络虚，伏则小便难，虚难相搏，水走皮肤即为水。脉浮迟浮数在此示热与水气搏结、气化不利而成水病之机。", ["浮", "迟", "数"]], "25367": ["病机", "寸口脉弦而紧，弦则卫气不行，即恶寒，水不沾流，走于肠间；少阴脉紧而沉，紧则为痛，沉则为水，小便即难。弦紧主卫气不行、寒水内停，沉主水气在里，故恶寒、腹痛、小便难，水走肠间。脉弦紧沉相应，示寒水内盛、气化不利之病机。", ["弦", "紧", "沉"]], "25368": ["预后", "脉沉主里主水，水气内停故身体肿重，此沉脉为水病正脉。然若水病而脉暴出，是阴寒水气未退而阳气外越，脉证相反，故断为死候，说明水病脉出提示正气脱散、预后不良。", ["沉"]], "25369": ["病机", "目下卧蚕、面目鲜泽为水气上溢之征，脉伏则水湿壅遏、阳气不达。消渴者水停不化津。腹大小便不利而脉沉绝，是水结于里、脉气被遏，故曰有水可下之，示水邪内实可攻。", ["伏", "沉"]], "25370": ["病机", "寸口沉迟，沉为水、迟为寒，寒水相搏；趺阳脉伏则脾胃衰，故鹜溏身肿；少阳脉卑、少阴脉细，男子小便不利、妇人经水不通。经血不利化为水，名曰血分，明水病由血分而致。", ["沉", "迟", "伏", "细"]], "25371": ["病机", "寸口沉紧，沉为水、紧为寒，沉紧相搏结在关元。阳衰阴盛，结寒微动，肾气上冲，故胸痛气冲咽如炙肉、咳喘。医误下误吐，胃虚水停，肿复如奔豚，示水寒结聚、冲气上逆之机。", ["沉", "紧"]], "25372": ["其他", "此段为设问之辞，述病者苦水、面目身体四肢皆肿、小便不利，而脉之不言水反言胸中痛、气上冲咽如炙肉、微咳喘，问其脉当属何类。原文未出具体脉象，故脉象要素为空，主旨在于引出下文沉紧之脉。", []], "25373": ["病机", "寸口沉紧，沉为水、紧为寒，寒水相搏结在关元。年盛不觉，阳衰后营卫相干、阳损阴盛，结寒微动，肾气上冲，故咽塞胁痛。误下误吐伤胃，水谷不化，肿复如奔豚，示水寒结聚、冲气上逆，治当先攻冲气。", ["沉", "紧"]], "25374": ["治法", "风水脉浮，是风邪袭表、水气在皮；身重为水湿泛溢，汗出恶风为表虚卫弱。脉浮主病在表，故用防己黄耆汤益气固表、利水除湿，腹痛加芍药以和营缓急，示风水表虚之治法。", ["浮"]], "25375": ["治法", "风水恶风、一身悉肿，脉浮为风邪在表、水气外溢；不渴、续自汗出、无大热，是风热郁表而里无大热。脉浮主表，故用越婢汤发越水气、兼清郁热，恶风加附子，风水加术，示风水表实之治法。", ["浮"]], "25376": ["主病", "脉浮为风水在表，风邪袭表，肺失通调，水气泛溢，故一身悉肿、恶风；续自汗出而口不渴、无大热，说明表有风邪而里无热结，水气偏于肌表。脉浮与恶风、身肿并见，正是风水初起、病位在表之征，故以越婢汤宣肺散水。", ["浮"]], "25377": ["病机", "脉沉小属少阴，说明水病本在少阴肾阳不足，水气不化而内停；浮者为风，属表。原文以脉沉小与浮对举，辨水病之在里在表：沉小者当温经发汗，故宜麻黄附子汤；浮者属风，宜杏子汤。此以脉象定病位与治法。", ["沉", "小"]], "25378": ["病机", "本条重申水病脉沉小属少阴，浮者为风。脉沉小反映少阴阳虚、水寒内盛，故水气病当从少阴论治；浮脉则示风邪在表。原文以“水，发其汗即已”总括治法，又分脉沉用麻黄附子汤、脉浮用杏子汤，体现凭脉辨少阴水气与风水表证之异。", ["沉", "小"]], "25379": ["病机", "黄汗病身体肿、发热汗出而渴，状如风水，但汗色正黄如柏汁，脉不浮而自沉。脉沉说明水湿内郁、营卫壅滞，非单纯表证；由汗出入水浴，水从汗孔侵入，湿郁肌腠所致。脉沉与汗黄、身肿并见，故用耆芍桂酒汤调和营卫、祛水湿。", ["沉"]], "25380": ["病机", "黄汗证见身体肿、发热汗出而渴，类似风水，但汗沾衣色正黄如柏汁，脉自沉。脉沉表明水湿内侵、营卫郁滞，病不在表；得之汗出入水中浴，水从汗孔入。脉沉与黄汗、身肿相应，故以耆芍桂酒汤主之，通阳化湿、调和营卫。", ["沉"]], "25381": ["病机", "寸口脉迟而涩，迟为寒、涩为血不足；趺阳脉微而迟，微为气不足、迟为寒。脉象反映寒气不足、营卫不利，故手足逆冷、腹满胁鸣、身冷骨疼、痹不仁，甚则失气遗尿。此段以脉迟涩微论气分病之寒与气血不足病机，非主一病。", ["迟", "涩", "微"]], "25382": ["主病", "风水脉浮为在表，风邪袭表，水气停聚。其人头汗出而表无他病，但下重、腰以下肿及阴、难以屈伸，说明水湿偏注下焦、经络壅滞。脉浮与腰以下肿并见，主风水表虚、水湿下注之证，故用防己黄耆汤益气固表、利水除湿。", ["浮"]], "25383": ["主病", "本条与上条重出，言风水脉浮为在表。风邪在表，水湿下注，故头汗出、下重、腰以下肿及阴、难以屈伸。脉浮提示病位在表，与腰以下肿并见，主风水表虚、水湿偏渗下焦，治以防己黄耆汤固表利水。", ["浮"]], "25384": ["其他", "原文未识别出脉名，仅标目为「黄疸病脉证并治第十五」，无具体脉象描述，故脉象要素为空。此段为篇题，提示该篇讨论黄疸病的脉象与证治，但本段本身不涉及具体病机分析，无法据脉论病，仅作篇章归类。", []], "25385": ["病机", "寸口脉浮而缓，浮为风邪外袭，缓为湿邪痹阻。原文「痹非中风」明非单纯外中风邪，乃风湿相搏、脾土受困。四肢苦烦者，湿郁化热；脾色外现必黄，瘀热以行，故发黄疸。此脉浮缓主风湿痹郁、瘀热发黄之病机。", ["浮", "缓"]], "25386": ["病机", "趺阳脉紧而数，数为热则消谷，紧为寒则食满，脾胃寒热错杂。尺脉浮为伤肾，趺阳紧为伤脾，风寒相搏，谷气不消，浊气下流，小便不通，热流膀胱，身体尽黄，名曰谷疸。此段以脉紧数、尺浮论谷疸及女劳疸、酒疸之病机。", ["紧", "数", "浮"]], "25387": ["病机", "趺阳脉紧而数，数则为热，热则消谷；紧则为寒，食即为满。尺脉浮为伤肾，趺阳脉紧为伤脾。风寒相搏，食谷即眩，谷气不消，胃中苦浊，浊气下流，小便不通，阴被其寒，热流膀胱，身体尽黄，名曰谷疸。此脉紧数尺浮主脾胃寒热错杂、谷疸之病机。", ["紧", "数", "浮"]], "25388": ["病机", "阳明病脉迟，迟为寒，胃中虚冷，故食难用饱，饱则发烦头眩，小便必难。此欲作谷疸，虽下之腹满如故，因脉迟故也。脉迟主胃寒不化、谷气壅滞，湿郁发黄之病机，非实热可下之证。", ["迟"]], "25389": ["治法", "酒黄疸者，或无热，靖言了了，腹满欲吐，鼻燥。其脉浮者，病位在上，先吐之；沉弦者，病位在下，先下之。此段以脉浮沉弦定病位上下，示因势利导之治法，浮主上焦、沉弦主下焦，故分别用吐、下之法。", ["浮", "沉", "弦"]], "25390": ["预后", "酒疸误下，久久为黑疸，目青面黑，心中如噉蒜虀状，大便正黑，皮肤爪之不仁。其脉浮弱，虽黑微黄，故知之。脉浮弱主正虚邪陷、血瘀湿滞，为酒疸误下后转为黑疸之预后判断，示病深难治。", ["浮", "弱"]], "25391": ["病机", "脉沉，渴欲饮水，小便不利者，皆发黄。脉沉主里，水湿内停，气化不利，故小便不利；渴欲饮水而水不得下，湿郁化热，熏蒸肌肤，发为黄疸。此脉沉主水湿内郁、气化失司之发黄病机。", ["沉"]], "25392": ["治法", "原文论黄疸治法，谓“诸病黄家，但利其小便”，然“假令脉浮”，则示病势偏表，当因势利导，“以汗解之”，故用桂枝加黄耆汤。脉浮为邪在表之征，与小便不利之里证相对，说明此黄家兼表虚，故治法从利小便转为解表，体现同病异治。", ["浮"]], "25393": ["其他", "此段为篇题，标明所论为惊悸、吐衄、下血、胸满、瘀血诸病之脉证并治，未出具体脉象与病机，故脉象要素为空。篇题统摄诸血证与神志病，提示后文各段脉证皆围绕此类病证展开，本条本身不主具体病机。", []], "25394": ["病机", "原文“寸口脉动而弱，动即为惊，弱则为悸”，以脉动主惊、脉弱主悸。动为阳搏于阴，气乱不宁，故惊；弱为血虚气少，心失所养，故悸。一脉兼见动弱，示惊悸并作，病机在气血虚而神动，与心悸易惊、心神不安之症相应。", ["动", "弱"]], "25395": ["预后", "原文以“脉浮”合“目睛晕黄”判断衄血未止，晕黄去、目睛慧了则知衄止。脉浮为阳热上浮，血热未宁，故衄未止；目睛晕黄为血热熏蒸之候，晕黄退而目睛清明，示热泄血止。此以脉症合参辨衄血预后，非专主病机。", ["浮"]], "25396": ["误治", "原文戒“衄家不可汗”，汗出则“额上陷，脉紧急，直视不能眴，不得眠”。衄家阴血已亏，误汗更伤津血，筋脉失养，故脉紧急；额上陷、直视、不眠皆阴血枯竭、筋脉拘急之危候。脉紧急在此示误汗后阴血亏耗、筋脉失濡之变。", ["紧", "急"]], "25397": ["主病", "原文“病人面无色，无寒热”，以脉别病：脉沉弦者主衄，沉为在里，弦为血结；浮弱、手按之绝者主下血，浮弱为血虚气浮，按之绝为血脱；烦咳者必吐血，因咳伤肺络。同见面色无华，凭脉辨衄、下血、吐血之异，示血证脉机。", ["沉", "弦", "浮", "弱"]], "25398": ["死脉", "原文“吐血，咳逆上气，其脉数而有热，不得卧者，死”。吐血阴亏，咳逆上气肺失肃降，脉数而热为阴虚火旺，不得卧则阴竭阳浮，正虚邪盛，故主死。脉数在此非单纯热象，而是阴血耗竭、虚阳外越之危候，与咳逆、不得卧并见，示预后不良。", ["数"]], "25399": ["病机", "原文“寸口脉弦而大，弦则为减，大则为芤，减则为寒，芤则为虚，寒虚相击，此名曰革”。弦而大，按之减而中空，即革脉。弦为寒，大而芤为虚，寒虚相搏，故妇人半产漏下，男子亡血。脉革主虚寒失血，与亡血、漏下之症相应。", ["弦", "大", "芤"]], "25400": ["病机", "脉微大来迟，微为阳虚，大为邪实，迟为血行不畅，合之示瘀血内阻、阳气不宣。原文以胸满、唇痿舌青、口燥但欲漱水不欲咽、无寒热为据，指出腹虽不满而自言满，乃瘀血内停、气机壅滞所致，脉象与症候互证，故断为有瘀血。", ["微", "大", "迟"]], "25401": ["病机", "原文未出脉名，仅言“其脉反无热”，谓病者如热状、烦满、口干燥而渴，脉却不见热象，说明热非真热，乃阴血瘀阻、阳气郁伏于内，故称“阴伏”。瘀血内结，津不上承则燥渴，气机壅塞则烦满，治当下瘀血，脉症合参以辨瘀血之实。", []], "25402": ["其他", "此段仅为篇题“呕吐哕下利病脉证治第十七”，无具体脉象与症候可析，故脉象要素为空。其主旨在于标示该篇论述呕吐、哕、下利诸病的脉证与治法，属篇章分类标题，不能据以推断具体病机，故归入其他类。", []], "25403": ["病机", "脉数本主热，当消谷引食，今反吐，师释为发汗令阳微、膈气虚，数乃客热，不能消谷，胃中虚冷。脉弦者虚也，胃气无余，朝食暮吐为胃反；寒在于上而误下，脉反弦，故名曰虚。此段以数、弦二脉辨胃反之虚寒病机。", ["数", "弦"]], "25404": ["病机", "病人脉数，似为热象，然不能消谷而反吐，师指出因发其汗，令阳微、膈气虚，脉乃数，数为客热，非真热也。胃中虚冷，故不能消谷而呕吐。此脉数主虚寒客热，与胃中虚冷、膈气不足之症相应，说明数脉不可一概论热。", ["数"]], "25405": ["病机", "脉弦者，虚也，谓胃气无余，故朝食暮吐，变为胃反。寒在于上，医反下之，更伤胃气，今脉反弦，故名曰虚。弦脉本主痛、主饮，此则因胃气虚寒、脉气紧张而见弦，与胃反呕吐、宿谷不化相应，示虚寒之病机。", ["弦"]], "25406": ["病机", "寸口脉微而数，微则无气，无气则营虚，营虚则血不足，血不足则胸中冷。此以微脉主阳气虚衰，数脉非实热，乃营血不足、虚阳浮动之象。脉微数相合，说明气血俱虚、胸阳不振，故见胸中冷，属虚寒病机。", ["微", "数"]], "25407": ["预后", "趺阳脉浮而涩，浮则为虚，涩则伤脾，脾伤不磨，故朝食暮吐、暮食朝吐、宿谷不化，名曰胃反。脉紧而涩，紧为寒、涩为脾伤血少，正虚邪结，故其病难治。此段以浮涩辨胃反之成，以紧涩判其预后不良。", ["浮", "涩", "紧"]], "25408": ["主病", "呕而脉弱，弱为胃气虚弱、阳气不足之象；小便复利则津液下夺，身有微热非实热，乃虚阳外浮；更见厥者，阳虚欲脱，故曰难治。脉弱与呕、利、厥并见，说明中阳衰败、阴寒内盛，主病在少阴、太阴，以四逆汤回阳救逆。", ["弱"]], "25409": ["主病", "本条与上条同文，脉弱为胃阳虚衰之征。呕伤胃气，小便复利则下焦不固，身微热而厥，是阴盛格阳、阳气将败之候。脉弱无力，正虚不能胜邪，故断为难治，主以四逆汤温中回阳，说明脉弱在此主阳气虚衰、病势危重。", ["弱"]], "25410": ["治法", "本条未出脉名，以胃反吐而渴欲饮水为主症。吐后津伤则渴，饮入复吐，是胃中停饮、气化不利。茯苓泽泻汤以茯苓、泽泻、白术、桂枝、生姜、甘草化气行水、和胃降逆，说明病机为水饮内停、胃失和降，属治法条文，脉象从略。", []], "25411": ["其他", "此段为茯苓泽泻汤方注，引《外台》云治消渴脉绝、胃反吐食。脉绝指脉气一时不能接续，非真脏脉绝，乃津液暴伤、水饮阻隔、脉道不利所致。方中加小麦以养心液。原文未出具体脉名，故脉象要素为空，主旨属方剂主治的补充说明。", []], "25412": ["兼症", "吐后渴欲得水而贪饮，是吐伤津液、胃中干燥，饮水过多则水停。文蛤汤兼主微风、脉紧、头痛，脉紧主外寒束表、卫气不利，与微风头痛相应，说明本证兼有表邪。脉紧在此不主里寒，而主外感风寒、经脉拘急，故以文蛤汤清热生津兼解表邪。", ["紧"]], "25413": ["兼症", "本条与上条同文，重申吐后贪饮而兼微风、脉紧、头痛。脉紧为寒邪外束、营卫凝滞之象，与头痛并见，说明表证未解。文蛤汤以文蛤、石膏清热止渴，麻黄、杏仁、生姜、甘草、大枣解表和中，脉紧在此提示兼挟外寒，属兼症范畴。", ["紧"]], "25414": ["预后", "下利脉沉弦者，沉主里、弦主气滞，故见下重；脉大者邪气尚盛，故为未止；脉微弱数者，微弱为正气渐复、邪气渐衰，数为阳气来复，故为欲自止，虽发热亦不死。本条以脉象判断下利进退，沉弦、大主病进，微弱数主向愈，属预后判断。", ["沉", "弦", "大", "微弱"]], "25415": ["死脉", "下利手足厥冷而无脉，是阳气衰绝、脉道不通，灸之而手足不温、脉不还，反见微喘，为阳气上脱、肺气欲绝，故死。少阴负趺阳者，指少阴脉弱于趺阳脉，胃气尚存，为顺。原文未出具体脉名，以无脉、脉不还言死候，属死脉范畴。", []], "25416": ["预后", "下利而见微热、口渴，若脉象不数不紧而反弱，说明邪热已衰，胃气渐复，正气虽弱但能胜邪，故可自愈。脉弱在此非虚脱之候，而是邪退正复、脉道和缓的表现，与微热口渴并见，提示津液渐回，病情向愈。", ["弱"]], "25417": ["预后", "下利脉数、微热汗出，为阳热得以外越，邪有出路，故可自愈；若脉紧，则紧主寒主痛，说明表邪未解或里寒未散，阳热不能透达，故为未解。脉数示热，脉紧示邪束，二者并见，提示正邪交争，病势未衰。", ["数", "紧"]], "25418": ["预后", "下利脉数而渴，为热邪内盛，若正能胜邪，热从外解，则可自愈；若不愈，热邪深陷下焦，灼伤血络，必圊脓血。脉数主热，渴示津伤，热盛不解则腐肉为脓，故原文以'有热故也'明其病机。", ["数"]], "25419": ["预后", "下利本属里虚，脉反弦，弦为少阳之脉，主邪在半表半里；今见发热身汗，是邪从少阳转出太阳，得汗而解，故自愈。脉弦在此非主痛主饮，而是邪气外达之象，与发热汗出并见，提示表里气和，病将自解。", ["弦"]], "25420": ["病机", "下利而寸脉反浮数，浮数为阳热上盛，热迫于上；尺中自涩，涩主血少，为下焦阴血不足。阳热上浮而阴血下涩，热邪不得外解，必内陷下焦，灼伤血络，故必圊脓血。脉浮数示热盛，脉涩示血伤，二者并见，提示热伤血络之机。", ["浮", "数", "涩"]], "25421": ["病机", "下利脉沉而迟，沉迟为里寒，下利清谷为脾肾阳虚；面少赤、身微热，是虚阳上浮，即'戴阳'。其面戴阳，下虚故也，说明下焦虚寒，阳气不能潜藏，浮越于上。必郁冒汗出而解者，是阳气暂通，邪从汗解，但病人必微热，示虚阳未全内敛。", ["沉", "迟"]], "25422": ["死脉", "下利后脉绝，手足厥冷，为阳气暴脱，脉道不通；若晬时脉还，手足转温，是阳气渐复，生机尚存，故生；若脉不还，则阳气已绝，故死。此段以脉之还与不还、手足温与不温，判断阳气存亡，脉绝为危候，脉还为生机。", []], "25423": ["治法", "下利而三部脉皆平，脉象平和，说明正气未伤，非虚寒下利；按之心下坚，为实邪内结，燥屎内停。脉平而心下坚，是邪实而正不虚，故宜急下之，用大承气汤攻下实邪。脉平在此非无病，而是正能抗邪，提示可峻下。", ["平"]], "25424": ["病机", "下利而脉迟，迟为寒为滞，滑为实为积，迟滑并见，是寒实内结、积滞未去之象。原文断为「实也、利未欲止」，说明肠中宿垢壅阻，气机不畅，故虽下利而利不能自止，当急下以去实，宜大承气汤。脉迟非虚寒，乃实邪阻滞、脉道不利所致。", ["迟", "滑"]], "25425": ["病机", "下利本应脉虚，今脉反滑，滑主实主积，说明肠中有可去之实邪。原文「当有所去，下乃愈」，指出宿滞内停，非攻下不去，故宜大承气汤。脉滑为实邪内结之征，与下利并见，属通因通用之机。", ["滑"]], "25426": ["治法", "下利清谷、里寒外热、汗出而厥，是阴寒内盛、格阳于外之危候。原文未出脉名，然以「里寒外热」「汗出而厥」点明真寒假热、阳气欲脱。通脉四逆汤用大附子、干姜、甘草，回阳救逆、通达内外，使浮越之阳复归其宅。", []], "25427": ["治法", "本条与前方同文，下利清谷为脾肾阳衰、完谷不化，里寒外热为阴盛格阳，汗出而厥为阳脱于外。原文未言脉，而症候已具少阴亡阳之机。通脉四逆汤大辛大热，破阴回阳，通脉救逆，正对此阴寒内盛、格阳于外之病机。", []], "25428": ["其他", "本条仅列通脉四逆汤方药组成与煎服法，无脉象、无症候论述，属方剂条文。方用大附子一枚生用、干姜三两、甘草二两炙，三味水煎分温再服，体现回阳救逆之配伍，与前条下利清谷、里寒外热、汗出而厥之证相应。", []], "25429": ["其他", "本条为篇题「疮痈肠痈浸淫病脉证并治第十八」，标明该篇专论疮痈、肠痈、浸淫疮等外科病证的脉象与证治，非具体脉证条文，故无脉象可录，主旨在于统摄全篇论治范围。", []], "25430": ["病机", "浮数脉一般主表热，当见发热；今反洒淅恶寒，是热毒壅聚于肌肤，营卫不畅，故恶寒而非外感。原文「若有痛处，当发其痈」，指出浮数之脉与局部痛处相合，为热毒结聚、将发痈肿之机，脉数应热，浮应于表，毒聚于外故也。", ["浮", "数"]], "25431": ["病机", "肠痈患者身甲错、腹皮急而按之濡、如肿状、腹无积聚、身无热，独脉数，是热毒内蕴肠中、血肉腐败成脓之征。脉数主热，身无热而脉数，说明热毒郁结于里、未外扬。原文断为「肠内有痈脓」，主以薏苡附子败酱散排脓消痈。", ["数"]], "25432": ["病机", "肠痈已成，热毒内腐，血肉败坏而酿脓。身甲错、腹皮急而按之濡如肿状，是脓成于里而外无积聚、身无热，说明热毒已聚于肠内而非外散。脉数正是内热腐脓之征，数而无力更示正气已伤、脓毒未溃，故以薏苡附子败酱散排脓解毒、温阳扶正。", ["数"]], "25433": ["病机", "同是肠痈，脉迟紧为寒凝瘀阻、脓未成，邪尚在气分血分之间，故可下之而当有血；脉洪数为热毒炽盛、血肉已腐，脓已成，下之反伤正气，故不可下。以脉之迟紧与洪数辨脓成未成，是本段辨证关键，大黄牡丹汤即针对脓成热实而设。", ["迟", "紧", "洪", "数"]], "25434": ["病机", "本条与上条重出，仍以脉辨肠痈脓成与否。脉迟紧主寒凝血瘀、脓未成，可下；脉洪数主热盛肉腐、脓已成，不可下。少腹肿痞、按之即痛如淋而小便自调，说明病在肠而不在膀胱。脉象由迟紧转洪数，即邪从凝滞化热腐脓之过程，故治法随之而异。", ["迟", "紧", "洪", "数"]], "25435": ["病机", "寸口脉浮微而涩，浮为气虚外浮，微为阳衰，涩为血少行滞，合而主亡血、汗出。若未见汗出而脉仍如此，则必因身有疮疡、刀斧所伤而亡血，血去则脉道不充故涩，气随血耗故微浮。本条以脉推因，说明浮微而涩是阴血亏虚、气不内守之象。", ["浮", "微", "涩"]], "25436": ["其他", "此段为篇题，列趺蹶、手指臂肿、转筋、阴狐疝、蚘虫等病脉证治，未出具体脉象，故脉象要素为空。篇题统摄诸杂病，提示这些病证须结合脉证辨识，非单论某一脉所主，故归入其他而不作病机分析。", []], "25437": ["病机", "转筋以臂脚强直为苦，脉上下行而微弦。弦为筋脉拘急之象，微则示邪不甚而筋失柔养；上下行者，言脉气上下劲急不宁，与四肢拘挛相应。转筋入腹则邪深犯中，故用鸡屎白散以通利缓急。脉微弦正是筋脉挛急、津血不濡之病机反映。", ["弦", "微"]], "25438": ["病机", "本条与上条重出，述转筋臂脚直、脉上下行而微弦。弦主筋急，微示病势不剧而筋脉失养，上下行形容脉来劲急不柔，恰合四肢拘挛牵引之状。转筋入腹为邪气内攻，故以鸡屎白散通利缓急。脉象与臂脚强直之症互为印证，示筋脉挛急之机。", ["弦", "微"]], "25439": ["病机", "腹痛辨虫，以脉为别。沉主在里，弦主痛、主气机郁滞，故腹痛脉当沉若弦；若反见洪大，则非单纯里寒腹痛，而是虫动气逆、扰乱中焦所致。洪大为虫扰气盛之象，与沉弦之常脉相对，故曰反洪大而有蚘虫。本条以脉之常变推断虫痛，示脉证合参之法。", ["沉", "弦", "洪", "大"]], "25440": ["其他", "此段仅为篇题「妇人妊娠病脉证并治第二十」，未出具体脉象与证治文字，故无从论其脉理病机。篇题标示本篇专论妊娠诸病之脉证并治，属篇章分类标题，非脉诊条文，脉象要素与所主病机均不可附会。", []], "25441": ["妇人", "「妇人得平脉，阴脉小弱」，平脉示无外邪，阴脉（尺部）小弱乃血养胎元、胞宫气血一时不足之象；故见渴、不能食而无寒热，断为妊娠。小弱非病脉，是胎气初结、阴血偏聚于下之常，故以桂枝汤调其营卫，非攻邪也。", ["平", "小", "弱"]], "25442": ["病机", "「脉弦发热」而胎愈胀、腹痛恶寒、少腹如扇，弦为阴寒内盛、阳气被遏之象；子脏开则寒邪乘虚而入，阳虚不能温煦，故腹痛恶寒而少腹冷如扇风。脉弦在此非少阳之弦，乃寒凝胞宫、阳虚阴盛之征，故以附子汤温脏散寒。", ["弦"]], "25443": ["其他", "此段仅为篇题「妇人产后病脉证治第二十一」，无具体脉象与证候文字，故不能析其脉理。篇题标明本篇专论产后诸病之脉证治法，属篇章标题，非诊脉条文，脉象要素与所主病机皆无从谈起，不可臆测附会。", []], "25444": ["病机", "「其脉微弱」主产后亡阴血虚，阳气独盛而上出，故但头汗出；血虚而厥，厥而必冒，呕不能食、大便反坚皆由血虚津少、胃气不和。微弱为气血两虚之脉，非实邪，故以小柴胡汤和解枢机、扶正达邪，使阴阳乃复。", ["微", "弱"]], "25445": ["主病", "「切脉微实」，微示产后正虚，实主里有结热；恶露不尽、少腹坚痛、不大便、烦躁发热、日晡益甚、食则谵语，皆热结膀胱、瘀热内实之候。脉微实正是虚中挟实、热在里结之征，故宜大承气汤攻其里实，热去则诸症自解。", ["微", "实"]], "25446": ["其他", "此段仅为篇题「妇人杂病脉证并治第二十二」，未列具体脉象与证治原文，故不能论其脉理所主。篇题标示本篇专论妇人杂病之脉证并治，属篇章分类标题，非诊脉条文，脉象要素与病机分析均无依据，不可凭空推演。", []], "25447": ["病机", "「热除脉迟，身凉和」，迟为热退阳复、邪去正安之象，然胸胁满如结胸状、讝语，乃经水适来、热入血室，血结于冲任而瘀热上扰神明。脉迟非虚寒，是热除而血分瘀结未散，故刺期门以泻其实，随其血室之实而取之。", ["迟"]], "25448": ["病机", "本条总论妇人因虚、积冷、结气致经水断绝、血寒积结胞门。文中\"脉数无疮\"示热结于中而外无疮疡，肌若鱼鳞为瘀热外现；\"脉虚多寒\"则久病羸瘦、阳气虚衰。数脉主热结关元，虚脉主血气虚寒，二脉并见说明寒热虚实错杂、病位有上下之别，故须\"审脉阴阳，虚实紧弦\"以辨源。", ["数", "虚"]], "25449": ["病机", "本段承上文论结热在中，痛在关元而\"脉数无疮\"。数脉主热，热结于内故脉数；然外无疮疡可征，热郁血分，肌肤失养则\"肌若鱼鳞\"。此数脉非表热、非痈脓，乃瘀热内结之象，故病在关元少腹，并可时著男子，说明同一脉数须结合症候辨其热结所在。", ["数"]], "25450": ["病机", "本段言妇人病久则羸瘦，\"脉虚多寒\"，虚脉主气血亏少，故多寒；又提出\"审脉阴阳，虚实紧弦\"，紧弦主寒主痛、主积结。脉虚与紧弦并见，说明正虚而寒邪积结未去，三十六病千变万端皆当据脉之虚实紧弦辨其源，不可执同病而一律治之。", ["虚", "紧", "弦"]], "25451": ["病机", "寸口脉弦而大，文中自释\"弦则为减，大则为芤，减则为寒，芤则为虚\"，寒虚相搏，其脉中空如按鼓皮，故名曰革。革脉主虚寒相搏、精血失守，在妇人则半产漏下，因冲任虚寒不能固摄。此以弦大之象层层析为减、芤，再由寒虚相搏定革脉，示脉形与病机相应。", ["弦", "大", "芤", "革"]], "25452": ["病机", "少阴脉候前阴，滑主湿浊，数主热，湿热下注前阴，故\"阴中即生疮\"，甚则蚀疮糜烂。本段以少阴脉滑而数直断阴疮，并出狼牙汤外洗以清湿热、杀虫止痒，是脉象定位定性指导治法之例。", ["滑", "数"]], "25453": ["病机", "本条与上条同文，少阴脉滑而数者，滑为湿浊内蕴，数为热邪偏盛，湿热蕴结下焦前阴，故阴中生疮、蚀烂。脉象见于少阴部位，说明病位在前阴，与阴疮症候相应，故以狼牙汤洗之清利湿热。", ["滑", "数"]], "25454": ["病机", "尸蹶者，脉动而无气，谓脉虽搏动而呼吸之气闭不通，故静如死状。脉动说明生机未绝，气闭不通则是病机关键，非真死也。文中以菖蒲屑吹鼻、桂屑著舌下，取开窍通闭、辛温宣气之意，示脉动可凭以辨其可治。", ["动"]], "25455": ["病机", "本条重申尸蹶\"脉动而无气，气闭不通，故静而死也\"。脉动为气血尚存之征，无气则气息闭塞，故外形安静若死。病机在气闭不通而非脉绝，故取菖蒲吹鼻开窍、桂屑著舌下通阳，凭脉动以别于真死，是脉诊判断预后的体现。", ["动"]], "25456": ["治法", "原文未出脉名，仅言“或已无脉”，指卒忤鬼击飞尸致气绝无觉、脉不可及之危候。无脉非血竭，乃气机骤闭、阳气暴绝，故以还魂汤麻黄杏仁甘草宣通肺气、开闭还魂，去齿下汤、捉帱引之皆助药力通行。此段主旨为救卒死之治法，非论脉象本身。", []], "25457": ["治法", "此段与上条重出，仍言“或已无脉”，强调卒忤暴绝时脉不可按得，属气闭阳亡之危。还魂汤以麻黄开肺、杏仁降气、甘草和中，通治诸感忤；汤下口不开者，分发捉肩引之，助气机宣通。原文无具体脉象，主旨落在急救治法与服药法，故脉象要素为空。", []], "25458": ["病机", "原文直言“林檎不可多食，令人百脉弱”。林檎多食伤脾，脾为气血生化之源，脾伤则气血不充，百脉失养而见弱脉。弱为虚软无力之象，主气血不足、脉道不充。此段以食忌说明过食林檎可致脉弱，属饮食伤脾、气血亏虚之病机，非外邪所致。", ["弱"]], "25459": ["病机", "原文“十月勿食椒，损人心，伤心脉”，未出具体脉名。椒性辛热，十月阳气内藏，过食辛热则耗伤心阴心血，心脉受损。心主血脉，心伤则脉失所养，虽未言脉形，其病机为辛热伤及心脉。此段以食忌言伤心脉之理，属病机范畴，脉象要素无可取。", []], "25460": ["误治", "原文述张元素诊完素，言“某味性寒下降，走太阴，阳亡汗不能出。今脉如此”，未录具体脉象。前医误用寒降之品，伤太阴阳气，阳亡则汗不能出，脉必现阳衰之象。元素断为误治，改服温阳之药而愈。此段主旨为辨误治、纠药误，脉象仅以“如此”带过，故不取脉字。", []], "25461": ["主病", "原文治飧泄，风冷入中，泄利不止，“脉虚而细，日夜数行，口干，腹痛不已”。虚为正气不足，细为脉道不充，风冷入中伤脾，脾失健运则飧泄不止、日夜数行；久泄伤阴耗气，故脉虚细、口干、腹痛。此脉主脾虚风冷、气血两伤之飧泄证，白术汤健脾温中即针对此病机。", ["虚", "细"]], "25462": ["病机", "原文论“四肢肿，四肢热盛则肿”，谓四肢为诸阳之本，阳结则不行于阴脉阳脉，留结而肿。未出具体脉名，然“阳结”“不行于阴脉阳脉”提示阳气郁结、脉道不通之病机。四肢肿由阳热郁结、气血留滞所致，非单纯水湿。此段主旨在阐发四肢肿之病机，脉象要素无可取字。", []], "25463": ["病机", "原文“脉至大虚，积气腹中，隐而难见，阴沉，使脾弱，寒于肢膜，气厥逆也”。脉大虚为正气亏虚，阴沉、隐而难见示阴寒内盛、阳气不振；脾弱则运化失职，积气腹中，寒及肢膜，气机厥逆。此脉主脾阳虚弱、阴寒内积、气厥逆之病机，虚与沉相合，正虚而阴寒内盛之象。", ["虚", "沉"]], "25464": ["病机", "冬脉本应沉而太过反见缓涩，缓为胃气有余之象，涩则精血不运。原文谓「肾实，精不运」，肾主藏精，脉缓涩示精气壅滞不能输布，故成解㑊之病，症见懈怠困倦、寒热类作，皆由肾实精滞、气机不畅所致。", ["缓", "涩"]], "25465": ["病机", "春脉当弦而见动脉，动主气机躁扰。原文谓「气痛气乏，不欲言，此为肾元有余」，肾元有余则气逆上扰，故脉动而症见气痛、气乏、懒言。利肾汤主之，正为泻肾有余之气，使气机平复而脉动自安。", ["动"]], "25466": ["病机", "原文言「胃热能消谷」故食已如饥，又谓「阳明脉终，心火上行」，阳明经气竭而胃火循经上炎，扰动心神则心憎烦，湿热郁蒸则身黄、小便赤涩。此段以胃热消谷与阳明脉终并见，说明胃火炽盛而津液受灼、湿热内蕴之病机。", []], "25467": ["病机", "原文谓「肾传心，觔脉相引而急，精液少，觔脉不荣而引急」，精液亏少则筋脉失养，故脉见相引而急。蛊腹痛由肾病传心，精亏筋急，脉急正是筋脉不荣、拘挛牵引之象，与腹痛并见，示精血耗损、筋脉失濡之机。", ["急"]], "25468": ["病机", "原文谓「胆受胃热，循脉而上于脑，阳络溢，血妄行」，胃热传胆，胆火循经上冲，阳络受损则血溢妄行，症见鼻衄、目瞑。此段虽未明言脉象，然由胆胃热盛、阳络溢血可推脉当数而有力，主热迫血行之病机。", []], "25469": ["病机", "此段仅标「主肾虚」，出自《素问·脉解论》，原文未出具体脉象。肾虚则脉当沉弱无力，其病机为肾气不足、封藏失职，可致腰膝酸软、眩晕耳鸣等症。因原文简略，仅据「主肾虚」三字定其病机归属，不增衍脉象描述。", []], "25470": ["病机", "原文谓「肾脉虚弱，其气厥不至，舌不仁」，肾脉虚弱则精气不能上承，厥气不至舌本，故舌喑不能言、二足废不为用，成喑俳之证。脉虚弱正示肾气亏虚、精气厥逆不至之病机，与舌喑足废症候相应。", ["虚", "弱"]], "25471": ["病机", "此段仅标「主风」，出自《素问·脉要精微论》，原文未列具体脉象。风邪为病，脉多浮弦，其病机为风邪外袭或肝风内动。因原文简略，仅据「主风」二字定其病机归属，说明本段主旨在于标示风病之脉，不增衍原文所无的脉象与症候。", []], "25472": ["病机", "原文未出脉名，仅言风气与阳明入胃后循脉上至目眦，津液所生为泣。其病机在于风邪循阳明经脉上扰目窍，影响津液输布，使液溢为泪。此段重在说明风气入胃循脉上行的路径与泣泪生成的机理，非以脉象主病，故脉象要素为空。", []], "25473": ["病机", "原文未出脉名，述风热与阳明入胃，循脉上至目眦；肥人风气不外泄，郁而化热，成为热中目黄之病。病机为风热循阳明经脉上扰，兼肥人腠理致密、风气不得外泄，热郁于中而发目黄。全段以经脉循行与体质因素说明病机，未涉脉象。", []], "25474": ["病机", "原文未出脉名，言风入系头则血脉凝滞，不能上下通流于目，风寒客之而成目风眼寒。病机关键在于风邪客于头部脉络，致血脉凝滞、气血不能上通于目，目失温养而畏寒。此段从血脉凝滞立论，说明目风眼寒的成因，未以脉象为据。", []], "25475": ["病机", "原文未出脉名，引《黄帝针经》言邪在血脉之中，随上下而行，本痹不痛而今能上下周身，故以名之。病机为邪客血脉，随脉上下流走，故痹痛不固定而遍及周身。此段说明病位在血脉、病性属流动之邪，未涉及具体脉象，故脉象要素为空。", []], "25476": ["病机", "原文言胃脉沉细，阳气不得下通，寒痈，阳热聚于胃口，腐坏成脓。脉沉细主阳气郁滞不能通达，沉为病在里，细为阳衰血少；阳气不下通而寒凝，阳热反聚胃口，腐肉成脓而为胃脘痈。此脉象揭示寒热错杂、阳气不通之病机。", ["沉", "细"]], "25477": ["病机", "原文未出脉名，述射干汤治胃脘痈，人迎脉逆而甚，嗽脓血，营卫不流，热聚胃口成痈。人迎脉逆甚反映阳明热盛上逆，营卫运行不畅，热毒聚于胃口，腐坏成痈而咳吐脓血。此段以人迎脉逆说明热聚营卫不流之病机，非一般脉象主病。", []], "25478": ["病机", "原文言羚羊角汤治阳厥，气逆多怒，而颈脉复动。颈脉复动即人迎脉动甚，为阳气厥逆、肝气上冲之象；多怒则气逆于上，故颈脉搏动明显。已食阴养于阳，平其气，示以方药平降逆气。脉动在此主阳厥气逆之病机。", ["动"]], "25479": ["病机", "原文言尺脉数甚，觔急而见，腹必急，数亦为虚，觔见以名耳。尺脉数甚主下焦有热，然数亦主虚，热灼筋脉则拘急，腹壁随之紧急。此段指出数脉虽主热，亦可因虚而数，筋急腹急为虚热内扰、筋脉失养之候，脉症合参以辨虚实。", ["数"]], "25480": ["病机", "脉数劲急，数主热，劲急为肝虚生寒、寒热错杂之象。原文谓“肝虚生寒，脉数劲急”，肝虚则疏泄失常，寒郁化热，故脉数而劲急；腹胁痞闷、觔见于外，皆肝经气血壅滞、筋脉失养所致。此脉非纯实热，乃虚寒夹热之机。", ["数", "劲", "急"]], "25481": ["病机", "原文未明言脉象，但述“胃脉同肾脉厥逆”，可知胃肾二脉气逆上冲。厥逆头痛、齿痛骨寒，乃肾阳虚衰、寒邪循经上逆，胃脉亦随之厥逆，故头痛不可忍。病机在胃肾虚寒、厥气上逆，非外感表邪。", []], "25482": ["治法", "原文未及具体脉象，但言“调顺三焦气脉，消痞滞，利胸膈，治风，通大小便”。三焦约者，气脉壅塞不通，故以枳壳丸调畅气机、消痞利膈。病机为三焦气滞、风邪内扰，致升降失司、二便不利。", []], "25483": ["病机", "原文未出脉名，但言“血凝脉重”。胃热则消谷善饥，肠寒则血凝不行，脉道重滞。小腹疼痛而胀，乃寒凝血滞、气机不通所致。病机为胃热肠寒、寒热错杂，血凝脉重是其关键。", []], "25484": ["病机", "原文未明脉象，述足厥阴之脉环阴器、抵小腹，小腹痛或肿，因肾虚寒、水涸竭。病机为肾阳虚寒、水液枯竭，肝脉失养，寒凝气滞于小腹。治以泻邪补脉，即泻寒邪、补虚脉。", []], "25485": ["主病", "原文仅注“主心痛。出《素问·脉要精微论》”，未录具体脉象。据《脉要精微论》相关条文，心痛之脉多现异常，此段主旨为脉象主心痛，属主病范畴，提示脉诊可辨心痛之证。", []], "25486": ["病机", "心脉急，急为拘急之象。原文谓“心脉急，小腹有形”，心不受邪，传于府，故小腹有形；心气逆不顺，当痛不已。病机为心气逆乱、寒邪所中，脉急反映心脉拘急、气血不畅，治当兼心气。", ["急"]], "25487": ["病机", "原文未出具体脉名，但言“气道涩而不利”。风邪善行数变，与卫气相抟于分肉之间，致气道涩滞，风热内郁，肌肉𪱥䐜而生疡；卫气凝而不行，则肉不仁如木石。病机为风邪郁遏卫气、气道涩滞。", ["涩"]], "25488": ["病机", "原文虽未明言脉象，但论“风寒热”为诸疾始生，强调“风热怫郁”“热为本而风为标”，风气壅滞致筋脉拘卷、肢体焦痿、头目昏眩等。其病机为风热郁结、气血壅滞，故脉当见数或弦，主风热诸证。", []], "25489": ["预后", "原文引经“汗出脉躁盛，一死”，又言“脉不与汗相应，其病二死”，皆因怫热郁结不能解散，热盛伤津，脉躁盛而汗出，阴阳离决，故主危殆。脉躁盛为热极，与汗出并见，预后不良。", ["躁", "盛"]], "25490": ["病机", "原文述肾水真阴本虚，心火狂阳积热，致风热壅滞，出现头面昏眩、肢体麻痹、筋脉拘卷、口舌生疮等。虽未言脉，但病机为阴虚火旺、风热燥郁，脉当细数或弦数，主虚中夹实之候。", []], "25491": ["治法", "原文指出“中寒脉迟者”不宜服此方，因脉迟主寒，与风热杂病之热证相悖。此方清散风热，故脉迟之中寒者忌之，从反面说明脉迟主寒凝，当温而非清。", ["迟"]], "25492": ["病机", "原文论柴胡饮子治积热寒热往来，注云“表之阳和，正气与邪热并蓄于里，脉道不行，故身冷脉绝，寒战而反烦渴”。虽未出具体脉名，但脉绝因邪热壅遏、脉道不行，主热郁于里、阴阳不接之病机。", []], "25493": ["主病", "原文列木香万安丸所治诸症，如风热怫郁、气血壅滞、头目昏眩、筋脉拘卷、肠胃燥涩等，虽未言脉，但病机为风热湿浊壅滞气血，脉当见弦滑或数，主风热壅盛、积滞内结之病。", []], "25494": ["兼症", "原文以“脉拘急”描述筋脉拘急之症，非脉象本身，但反映风热怫郁、筋脉失养之病机。风热壅滞，气血不畅，故筋脉拘急，肢体疼倦，主风壅气滞之候。", ["拘", "急"]], "25495": ["病机", "原文述肾水阴虚，风热蕴积，致惊悸、筋惕搐搦、筋脉拘奇、肢体痿弱等。虽未言脉，但病机为阴虚火旺、风热内动，脉当细数或弦急，主虚风内动、营卫壅滞之证。", []], "25496": ["病机", "原文列脉虚浮、脉虚弱、脉沉、脉不能实、脉弱气虚、脉虽疾数、脉沉细而欲绝、脉微等，皆示正气不足、表里虚实错杂之象。虚浮为表虚不固，沉细欲绝为里气衰微，疾数而弱为虚热外浮。故汗下吐和诸法须辨表里虚实，不可妄攻，正合“表证当汗而不可下，里证当下而不可汗”之戒。", ["虚", "浮", "沉", "弱"]], "25497": ["病机", "原文以“脉迟者是也”定诸寒，寒邪伤中则水液澄澈清冷、谷不化、小便清白、身凉不渴，皆阴胜阳衰之征。脉迟主阳气不振、阴寒内盛，故为中寒。然原文又言“冷热相并”可致阳气怫郁而成热证，及亡液气虚反见阴脉，提示须标本兼辨，不可一见迟脉即断为冷。", ["迟"]], "25498": ["主病", "脉浮数而紧，浮主邪在表，数主热，紧主寒束，合为风寒外束、邪热在表之象。原文见头项痛、腰脊强、身体拘急、表热恶寒、无汗、鼻干、胸满而喘、手足指末微厥，皆邪热在表、卫阳被遏所致，故断为“邪热在表”，属麻黄汤发汗之证。", ["浮", "数", "紧"]], "25499": ["病机", "原文以脉浮沉分表里：身疼拘急、表热恶寒而脉浮者，为热在表；引饮谵妄、腹满实痛、发热而脉沉者，为热在里；脉在肌肉者，为邪半在表半在里。浮脉应表，沉脉应里，故脉之浮沉直接对应邪热所在层次，为汗下和解立法之依据。", ["浮", "沉"]], "25500": ["病机", "始得病脉便沉而里病表和者，为内伤；脉浮而表病里和者，为外伤。沉脉主里，浮脉主表，故以脉之浮沉判病位在表在里。原文又明“病在身体头面四肢为表病，在胸腹之内为里病”，脉象与病位相合，示内伤外伤之辨。", ["沉", "浮"]], "25501": ["治法", "原文论非时邪气传经，虽以日数言汗下，然“以脉分别”为要：三四日脉沉伏，示邪已入里，虽日数未满亦可下；六七日脉浮滑，示邪仍在表，虽日数已满亦可汗。沉伏主里实，浮滑主表热未解，故汗下不可拘日数，当以脉象定表里而施治。", ["沉", "伏", "浮", "滑"]], "25502": ["主病", "脉浮紧为太阳伤寒表实证之典型脉象：浮主邪在表，紧主寒邪束表、卫阳被遏。原文见头痛发热、体痛恶风、无汗而喘，皆寒邪闭表、肺气不宣所致。八九日不解而表证仍在，仍当发汗；发烦目瞑、必衄者，为阳气重、邪郁求伸之象，故主麻黄汤证。", ["浮", "紧"]], "25503": ["主病", "桂枝汤本治太阳中风、阳浮阴弱之解肌证，原文见发热恶寒、干呕头痛。而“脉浮紧，鼻鸣者”则示寒邪束表较甚、肺气不利，浮紧为伤寒表实之脉，鼻鸣为风寒壅肺、鼻窍不利。此段以脉浮紧与鼻鸣并见，提示桂枝汤证中兼见表寒郁闭之象，须与麻黄汤证相鉴别。", ["浮", "紧"]], "25504": ["病机", "脉乍紧者，紧主邪结、主痛、主实。伤寒表证已罢，邪热内陷，与痰水互结于胸中，气机壅遏，故脉乍紧而非持续之紧，反映结聚之势时作时止。胸中结邪则腹满不能食，阳气不达四末则四肢微厥。脉紧与胸中痞结、欲吐之症相应，故宜因势利导，用瓜蒂散吐之。", ["紧"]], "25505": ["主病", "脉浮在此非表邪未解，而是大汗后胃中干、水热互结之象。汗出过多伤津，胃燥则烦躁不得眠；气化不利，水停下焦则小便不利；水津不布则微热烦渴，饮水反吐。脉浮反映水热之气上浮外达，与小便不利、烦渴并见，正是五苓散化气行水、通阳利湿之的证。", ["浮"]], "25506": ["病机", "脉浮而兼自利不止，是表邪未解、里气已伤之候。当汗反下，攻表不解，误下伤中，水饮内停，留饮不散，水停心下，气化失司，故下利不止而脉仍浮，说明表气未和、水气上逆。水逆之证以脉浮、自利、吐水为特征，脉浮提示病势仍偏于外与上，与霍乱吐泻、昏躁等水湿内盛之症相应。", ["浮"]], "25507": ["病机", "脉微沉者，蓄热下焦、瘀血内结，气血不畅故沉而微；小腹胀硬、小便自和，正是瘀血之征。若发热日深而脉虽浮，说明表证已罢、热郁于里，故亦可下。已下后脉数，胃热消谷善饥、数日不大便，为瘀血兼胃燥之候。数脉主热，沉微主里结，诸脉随证而变，皆围绕蓄血与里热立论。", ["微", "沉", "浮", "数"]], "25508": ["病机", "阳明脉迟非寒，乃里热燥结、气血壅滞，脉道不利所致，故汗出不恶寒、身重、谵妄如见鬼状。脉沉实、实数而沉，皆里热燥实之征，与日晡潮热、腹满实痛、烦渴谵妄相应。燥屎内结、肠胃怫郁，故脉实而沉；热势鸱张则脉数。诸脉俱指向阳明腑实，故以大承气汤峻下热结。", ["迟", "沉", "实", "数"]], "25509": ["病机", "脉滑主热主实，阳明多汗、津液外出，肠胃燥热，大便硬而谵语，脉滑正是燥热内结之应。脉弱则见于病二三日、无太阳柴胡证而心下结者，弱为正气不足、邪结未深，故不可峻攻，只宜少少与小承气汤和之。滑与弱对举，示燥实与正虚之别，皆须以转失气、腹满等症为凭再定攻下。", ["滑", "弱"]], "25510": ["病机", "脉滑数而实，为里热炽盛、燥实内结之象，与腹满实痛、烦渴谵妄、小便赤、大便硬相应。误用银粉巴豆燥毒攻下，真阴受损，邪热转甚，协热下利不止，脉仍滑数而实，说明热结未去。脉滑实紧者，紧主痛主实，与腹满实痛相合。诸脉皆示燥热内实，故以调胃承气汤缓下和胃。", ["滑", "数", "实", "紧"]], "25511": ["病机", "脉沉可下，示热结在里；脉数沉实，为里热壅盛、积滞内结之候，与腹满咽干、烦渴谵妄、大便结滞相应。若脉反沉细欲绝、微而绝，则属阳热独甚、肾水阴虚、正气衰败之危象，与僵仆卒中、暴音不语并见。同一三一承气汤证，脉由沉实数转为沉细欲绝，提示热盛伤阴、正虚邪实之变。", ["沉", "数", "实", "细"]], "25512": ["病机", "原文述十枣汤证兼表邪入里，阳厥极深时“脉微而绝”。热极似阴，反见寒战，表气入里，阳郁不达，故脉微而绝，非真阳虚脱，乃实热内结、阳气不伸之象，主热深厥深、大小便不通等症。", ["微", "绝"]], "25513": ["主病", "大陷胸汤证因汗下后热结在里，故脉当沉紧滑数，沉主里，紧主痛，滑数主热实；若但胸结无大段热而脉沉涩者，为水结，涩主水饮凝滞，与舌干而渴、日晡潮热、胀满痛不可近相应。", ["沉", "紧", "滑", "数"]], "25514": ["主病", "小结胸证心下按之痛而脉浮滑，浮为表未罢，滑为痰热内结；原文强调“无大段热，表未罢，不可下之，下之即死”，说明此脉示热未全入里，误下则伤正引邪，故主小结胸而兼表。", ["浮", "滑"]], "25515": ["主病", "大黄黄连泻心汤治伤寒成痞不已，心腹实热烦满，或谵妄而脉沉。沉脉主里，实热内结心下，气机壅滞成痞，故脉沉而伴烦满谵妄，原文谓“无他证者”，示病机纯属里热痞结。", ["沉"]], "25516": ["兼症", "白虎汤加减治中暑自汗脉虚弱，暑热伤气耗津故脉弱；伤寒自汗脉滑数而实，表里俱热，滑数主热盛，实主邪实；原文并列两脉，示同一方证因兼症不同而脉有虚实之异，主热盛津伤或表里俱热。", ["虚", "弱", "滑", "数"]], "25517": ["治法", "伤寒发汗不解脉浮者，加苍术名苍术白虎汤，浮示表邪未尽；汗吐下后烦渴口干脉洪大，加人参名人参白虎汤，洪大示热盛津伤、气分热炽。原文以脉定加减，示白虎汤证兼表或兼气津两伤之治法。", ["浮", "洪", "大"]], "25518": ["主病", "少阴病脉沉，下利厥逆，烦渴呕吐，沉主里，少阴阳衰阴盛，故下利厥逆；烦渴呕吐为阴寒内盛、虚阳上扰之象，脉沉与厥逆下利相应，主少阴寒化、阳气衰微之证。", ["沉"]], "25519": ["病机", "原文论瘕病由血不流而滞、血内凝所致，小肠移热于大肠或大肠移热于小肠，两热相抟则血溢为伏瘕，血涩不利、月事沉滞不行。强调瘕病有热，不可概作寒症，当以脉辨阴阳寒热，热郁壅滞可致坚硬腹满急痛。", []], "25520": ["病机", "原文论五脏传其所胜，脏气虚而内外诸邪留稽不行，遂成积聚。脉沉细而微，沉主里、细主虚、微主阳衰，正合脏气虚衰、邪气内结之积聚病机。脉象与积聚相应，示正气已虚而邪实内着，故属难治之候。", ["沉", "细", "微"]], "25521": ["主病", "原文述除湿丹所治诸湿客抟，见腰膝重痛、足胫浮肿、筋脉紧急、津液凝涩、便溺不利。湿邪客于筋脉，气血受阻，筋脉失养而拘急，故脉见紧急。紧主寒主痛，亦主湿邪搏结、筋脉挛急，与浮肿、重痛、便溺不利诸症相应。", ["紧"]], "25522": ["主病", "原文为开结妙功丸主治，述怫热内盛、痃癖坚积、症瘕积聚、三焦壅滞、二肠闭结，及风湿肿胀、筋脉拘痪、肢体麻痹、上实下虚等。全段未出脉象，主旨在于宣通气血以治积热壅滞、气血不行之诸症，故归主病，脉象要素从缺。", []], "25523": ["主病", "原文述人参半夏丸化痰坠涎、止嗽定喘，治诸痰及呕吐痰逆、痰厥头痛、风壅头目昏眩、筋脉拘卷、肢体麻痹、中风偏枯、咳唾稠黏等。段中未载脉象，主旨为痰涎壅盛、风痰阻络之证治，故归主病，脉象要素从缺。", []], "25524": ["病机", "原文治劳，体热心寒，脉滑短，咳嗽，妇人多有此疾，并言皆因肠胃燥滞、营卫不能开发、玄府闭塞、热郁内余。滑主痰热内壅，短主气机不畅，合体热心寒、咳嗽、口干眼涩、骨痿短气，正示燥滞热郁、营卫闭塞之劳病病机。", ["滑", "短"]], "25525": ["病机", "原文列妇人血气虚劳诸症，如头目昏眩、言语謇涩、虚汗、喘咳、骨节疼痛、尫羸瘦弱，末引经曰脉大为劳。大脉见于虚劳，乃气血虚而脉气外张、虚阳浮越之象，与羸瘦、虚汗、烦渴并见，正合血气虚劳、虚热内扰之病机。", ["大"]], "25526": ["主病", "原文为益元散主治，述身热吐痢、泄泻肠癖、下痢赤白、癃闭淋痛、石淋，及荡胃中积聚寒热、消蓄水、除烦热、补五劳七伤等。全段未出脉象，主旨为宣积气、通六腑、利小便以治湿热积滞诸病，故归主病，脉象要素从缺。", []], "25527": ["预后", "原文治一切泻痢不已，指出胃脉浮洪者反多日不已，泻小者立止。泻痢日久，胃脉当弱，今反浮洪，是胃气外浮、虚阳上越而中气已伤，故病久不已，属预后不良之象；泻小者脉证相应，故易止。浮洪在此示胃虚阳浮之预后判断。", ["浮", "洪"]], "25528": ["病机", "原文未出脉名，论妇人以血为本，病在太阳少阴、冲任带脉。月水不来因风热伤经血，或脾胃虚损致营卫凝涩、肌肤黄燥；大肠虚下利流入关元则绝子嗣，子藏虚冷劳损而病带下。全段以经络藏府阐述带下与经闭病机，非凭脉断证。", []], "25529": ["病机", "原文未出脉名，辨带下赤白非实有寒。举头目昏眩、口苦舌干、小便赤、大便滞涩皆热证，白带下亦多有之，斥“病寒岂能”。引《素问》“亢则害，承乃制”，以火炼金、热极反化为水为喻，说明任脉湿热津溢而成带下，主热郁病机。", []], "25530": ["误治", "原文未出脉名，以煎汤沸溢、热气蒸物生津为喻，明下部任脉湿热甚则津溢涌而为带下。俗医见白带下但依方论用辛热之药，致郁结热聚不能宣通，旧病转加，世传误久。全段主旨为纠辛热误治之弊，非脉诊条文。", []], "25531": ["治法", "原文未出脉名，为当归川芎散方治。风壅头目则昏眩痛闷，筋脉拘卷、肢体麻痹为风邪壅滞之症；保护胎气、调和营卫示其治兼安胎和营。全段属治法方药，以风壅与胎气并列为治，无脉象可据。", []], "25532": ["病机", "原文未出脉名，引《素问》“诸寒收引，皆属于肾”。少阴属水主冬，为寒为归藏周密，寒中收引拘缩即寒之用。所生水液澄澈冷清不浊、气寒冷、水谷不化、吐利清冷，皆如天气寒而水自清，说明寒邪伤肾、阳气不化之病机。", []], "25533": ["病机", "原文以“脉急而寒之象”立论，急主于痛故紧急；又引“迟则为寒”，寒毒内郁脉当迟缓，诊其脉沉伏而迟为病之证。寒胜火衰则吐利腥秽、四肢逆冷、坚痞腹满、蜷卧恶闻人声，皆阴证。脉急、迟、沉伏正合寒凝收引、阳衰不通之机。", ["急", "迟", "沉", "伏"]], "25534": ["治法", "原文仅以“脉拘急”点出脉象，属防风当归饮子证。脾肾真阴损虚、肝心风热郁甚，阳胜阴衰、上实下虚，故见表热恶寒、里热躁渴、寒热往来，甚则阳极似阴而寒战腹满。脉拘急应风热郁甚、筋脉失柔，全段以方论治法为主，脉象为兼及之笔。", ["急"]], "25535": ["主病", "原文以“其脉迟者是也”断中寒。痞闷急痛、寒湿相搏、吐泻腹痛、水液澄澈清冷、谷不化、小便清白、身凉不渴，皆阴胜阳衰之候，脉迟正应寒证。又告诫冷热相击可怫热内作，湿热吐泻常见阳脉，亡液气虚亦能反见阴脉，当以脉证标本相别。", ["迟"]], "25536": ["病机", "原文论痛之病机，谓“寒气入经而稽迟，血泣凝而不行”，客于脉外则血少，客于脉中则气不通，故卒然而痛。虽未出脉名，然痛之诸形皆由寒凝气血、经脉不通所致，痛甚不可按者属实，按之痛止者属虚，喘动应手者寒搏脉急，痛死不知人者阳气暂绝。", []], "25537": ["病机", "原文谓“脉寒则蜷缩，蜷缩则脉绌急”，绌急即脉拘紧细急，因寒气客于脉外，卫气不得流通，故卒然而痛，得热则止。若寒气与炅气相薄则脉满，血气乱而痛不可按。绌急之脉正示寒凝收引、气血壅滞之病机，痛死不知人者乃阴气竭、阳气未入之危候。", ["绌", "急"]], "25538": ["治法", "趁痛丸治一切走注疼痛，兼疗妇人经脉住滞、水肿腹胀。走注疼痛多由风寒湿邪流窜经络、气血痹阻所致，妇人经脉住滞则血行不畅，水肿腹胀则气化不利。此方以通利为法，虽未言脉，然所主之证皆属邪阻气滞、血瘀水停之实，脉当见沉弦或涩滞。", []], "25539": ["病机", "原文论肠风痔病由“肠气虚而玄府疏，风邪乘而热自生”，风温邪热攻于肠中，大便涩而燥热郁，血热散而流溢冲浸肠里，故先血后便。热在下则先血后便，热在上则先便后血。此示肠风痔病以肠虚为本、风热为标，热伤血络、血溢肠间之病机。", []], "25540": ["病机", "原文引《素问》“因而饱食，筋脉横解，房室劳伤，肠癖为痔”，谓风热不散，谷气流溢传于下部，故肛门肿满结如梅李核，甚则成瘘。此明痔病由饱食伤脾、房劳伤肾，湿热风毒下注肛门，筋脉横解弛纵而成，病机重在湿热下注、血瘀结聚。", []], "25541": ["病机", "原文辨小儿脾疳利泻之寒热，谓“脉迟细而微者，寒证也”，并见利色青白不涩、水谷不化、吐利腥秽、澄澈清冷、身凉不渴。迟细微之脉主阳气虚衰、寒湿内盛，故虽泻利而色不变、无烦渴，与热证之脉数、小便赤黄而涩者迥别，警示不可概以利白为寒。", ["迟", "细", "微"]], "25542": ["其他", "原文为药物主治记载，谓其“主利血脉，治妇人带下十二病，除气癃，明耳目”，久服轻身长年。所主带下、气癃皆与血脉不利、气化不畅相关，药能利血脉、通癃闭，故妇人带下及气癃之病机多属血滞气阻，然原文未及脉象，仅示药效所主。", []], "25543": ["其他", "原文载药“主通血脉，止烦满、消渴，益精神，悦泽人面，除中恶、腹痛、毒气、疥瘘、诸疮”，作末名真朱。所治烦满消渴、中恶腹痛、疮瘘等，病机多涉血脉不通、热毒内扰，药能通血脉、解热毒，故主之。原文未言脉象，属药物主治范围。", []], "25544": ["其他", "此段为《本经》空青条文，属本草主治，非脉学内容。原文述空青味甘寒，主青盲耳聋、明目、利九窍、通血脉、养精神，全在药性功效，未及脉象。所谓“通血脉”指药能通利血脉，非据脉辨证。故无脉象要素可录，主旨归其他，不作病机推断。", []], "25545": ["其他", "原文“脉中百二十疾”指五脏十二经脉所生病候众多，非脉象描述，故脉象要素为空。此段为药性主治，言其治暴伤寒、腹中大热、烦满消渴、利小便及瘘蚀疮，属本草功效，非凭脉言病机。主旨归其他，不据“脉”字强解为脉诊。", []], "25546": ["其他", "此段为药物主治条文，述其治五脏积聚、久热胃闭、破留血、通经脉、利大小便及月水、破五淋、推陈致新。文中“通经脉”指药效通利经脉，非脉象。全段无脉象描述，故脉象要素为空，主旨归其他，不作脉诊病机分析。", []], "25547": ["其他", "此段为麦门冬《本经》原文，述其主心腹结气、伤中伤饱、胃络脉绝、羸瘦短气。“胃络脉绝”言胃络脉气断绝之病候，非脉象写法，故脉象要素为空。全段属本草主治，主旨归其他，不据“脉绝”二字作脉诊病机推断。", []], "25548": ["其他", "此段为药物主治，言治男子五劳七伤、女子伤中胞漏下血、破恶血溺血、利大小肠、去胃中宿食、补五脏内伤不足、通血脉、益气力、利耳目。文中“通血脉”为药效，非脉象。全段无脉象描述，脉象要素为空，主旨归其他。", []], "25549": ["妇人", "此段为地黄类药主治，专述妇人崩中血不止、产后血上薄心闷绝、胎动下血、胎不落及堕坠踠折瘀血留血、衄鼻吐血等，皆捣饮之。全段以妇人胎产崩漏及诸出血为主，故主旨归妇人；文中无脉象描述，脉象要素为空，不凭脉立论。", []], "25550": ["其他", "此段为药物主治及别名产地，述其治腰痛去来陶陶、除胸中烦热、安肠胃、利五脉、调四肢。“利五脉”指药利五脏脉气，非脉象描述，故脉象要素为空。全段属本草内容，主旨归其他，不作脉诊病机分析。", []], "25551": ["其他", "此段为甘草类药主治，述温中下气、烦满短气、伤脏咳嗽、止渴、通经脉、利血气、解百药毒等。“通经脉、利血气”为药效表述，非脉象，故脉象要素为空。全段属本草功效主治，主旨归其他，不据以推断脉象病机。", []], "25552": ["其他", "此段为药物主治条文，未涉及脉象。原文述人参「主治肠胃中冷，心腹鼓痛，胸胁逆满，霍乱吐逆」，其病机为脾胃虚寒、气机逆乱，故见鼓痛、逆满、吐逆；「通血脉，破坚积」则示虚中夹滞、气血不畅。全段以药测证，非脉学内容，故脉象要素为空。", []], "25553": ["其他", "此段述药物主治，无脉象记载。原文「主治心痛，胁风，胁痛，温筋通脉，止烦，出汗」，提示该药所对病机为寒凝筋脉、气血痹阻，故心痛胁痛并见；「温筋通脉」点明寒邪客于筋脉、脉道不利。全段属药性主治，未及诊脉，故脉象要素为空。", []], "25554": ["其他", "此段为桂皮类药的主治，未载脉象。原文「主温中，利肝肺气，心腹寒热，冷疾，霍乱，转筋」，其病机为寒邪内侵、阳气不布，故见冷疾、转筋；「通血脉，理疏不足」示阳虚脉道不充。全段以药测证，属药性主治，非脉诊内容，故脉象要素为空。", []], "25555": ["其他", "此段述药物主治，无脉象。原文「主治中风汗出，逐水，利小便，破积血，复血脉，乳妇产后余疾」，提示病机为水气内停、瘀血阻络，故需逐水破积血以复血脉；产后余疾亦多因瘀滞。全段为药性主治条文，未涉及脉象，故脉象要素为空。", []], "25556": ["其他", "此段引《本经》长石主治，未言脉。原文「主身热四肢寒厥，利小便，通血脉」，其病机为热郁于内、阳气不达四末，故身热而四肢寒厥；「通血脉」示热壅血滞。全段属药性主治，无脉象描述，故脉象要素为空。", []], "25557": ["其他", "此段为芍药类药的主治，未载脉象。原文「主通顺血脉，缓中，散恶血，逐贼血，去水气，利膀胱、大小肠」，其病机为瘀血内阻、水气不化，故需散恶血、逐贼血、去水气；「消痈肿，时行寒热」示气血壅滞。全段以药测证，非脉学内容，故脉象要素为空。", []], "25558": ["其他", "此段引《本经》桑根白皮主治，未言脉。原文「主伤中，五劳六极，羸瘦，崩中脉绝，补虚益气」，其病机为虚劳内伤、气血亏耗，故见羸瘦、崩中；「脉绝」指血脉虚竭，非脉象描述，乃言崩中失血致脉道空虚。全段属药性主治，故脉象要素为空。", []], "25559": ["其他", "此段引《本经》通草主治，无脉象。原文「主去恶虫，除脾胃寒热，通利九窍血脉关节，令人不忘」，其病机为湿热虫积内扰、九窍血脉关节壅滞，故需通利；「令人不忘」示痰湿蒙蔽清窍得除。全段为药性主治条文，未及诊脉，故脉象要素为空。", []], "25560": ["病机", "原文未出脉名，仅言药性\"主充肌肤，益气，令人暴肥，血脉满盛\"。此从药后效应反推病机：药力充养肌肤、益气太过，致血脉满盛，故诫\"不可久服\"。血脉满盛即营血壅实之象，与脉象无直接对应，属药性致病的病机描述，非脉诊原文。", []], "25561": ["病机", "原文未识脉名，仅载药\"主治气脉溢\"。气脉溢指气机逆乱、脉道充盈外溢之病机，与气逆、血壅相关。此段以主治反证病机为气脉壅溢，非直接描述脉象形态，故脉象要素为空，归入病机类。", []], "25562": ["病机", "原文未出脉名，述药\"主治百节中结气，风头痛及蛊毒、吐血，妇人产后余痛\"，又言羊髓\"利血脉，益经气\"。百节结气为邪气痹阻关节、气血不畅之病机；吐血、产后余痛皆与血脉瘀滞相关。全段以主治证候示病机，无脉象描述。", []], "25563": ["病机", "原文未识脉名，载白马茎\"主伤中脉绝，阴不起\"。脉绝指血脉虚竭、阳气衰微之病机，故阴器不举、志弱。悬蹄主惊邪瘛疭，属风动之候。此段以\"脉绝\"言病机之血脉虚极，非脉形描述，脉象要素从缺。", []], "25564": ["病机", "原文未出脉名，言药\"治丈夫女子伤中脉绝，筋急，咳逆\"。脉绝为血脉虚竭、营气不续之病机，筋急由血不养筋，咳逆为气机上逆。肾\"主治肾气\"，肉\"补中，强五脏\"，皆从补虚立论。全段以主治示血脉虚绝之病机，无脉象形态记载。", []], "25565": ["兼症", "原文未识脉名，述外治法\"点目中胬肉赤脉贯瞳子上者，即消\"。赤脉贯瞳子指目中血络瘀滞、胬肉攀睛之兼症，属眼疾血脉病变，非脉诊之脉。此段主旨为治法兼述症候，脉象要素为空。", []], "25566": ["治法", "原文未出脉名，载烧灰酒服\"治诸恶疽、附骨痈，根在脏腑，历节肿出，丁肿恶脉诸毒皆瘥\"。恶脉指毒邪壅滞血脉、肿毒沿脉而发之症，属外科毒邪入脉之候。此段以治法为主，兼述恶脉诸毒症候，无脉象描述。", []], "25567": ["病机", "原文未识脉名，言梅实\"利筋脉，去痹\"，梅根\"疗风痹\"。风痹为风邪痹阻筋脉、气血不通之病机，故以利筋脉、去痹为治。此段从药效反证筋脉痹阻之病机，非脉象形态记载，脉象要素为空。", []], "25568": ["其他", "此段为药性主治文，非脉诊内容，未及脉象。原文述药\"大寒\"，主\"胸中留热、结气\"，以寒药清胸中郁热、散结气，并治黄疸、通血脉、去蛊毒。其\"通血脉\"之功与热结血脉、瘀滞相关，然全段无脉象描述，故不能据脉论病机，只可视为药性主治记载。", []], "25569": ["其他", "此段为药物主治，未言脉象。原文称药\"味甘，无毒\"，主\"带下百病，产难，胞衣不出，堕胎，养血气，除五脏血脉中热，血痹血瘀\"，并治惊气入腹、阴痿。所述病机涉及血气不足、血脉瘀热及妇人产难，然无脉象可凭，不能作脉学病机分析。", []], "25570": ["其他", "此段为药性主治文，无脉象记载。原文谓药\"大热，有毒\"，主\"除五脏六腑寒冷\"，治伤寒、温疟、大风汗不出、心腹留饮宿食，止肠澼下利、泄精，散风邪、瘕结、水肿、黄疸，并杀虫毒。所主多属寒凝、留饮、风邪、瘕结之病机，然全段未涉脉象，不能以脉论病。", []], "25571": ["其他", "此段为药物主治，未及脉象。原文称药\"生温熟寒，有大毒\"，主治\"女子月闭，烂胎，金创脓血\"，不利丈夫阴，杀斑蝥毒，并可\"益血脉，令人色好\"。所涉月闭、烂胎、金创脓血等，提示瘀血、胎产及疮疡病机，然段中无脉象描述，不能据脉分析。", []], "25572": ["其他", "此段为药性主治文，无脉象。原文谓药\"味甘，微温，冷利，有小毒\"，消\"胸上痰结唾如胶漆\"、心胁痰水、膀胱留饮，治风气湿痹、皮间死肉、目中眵䁾，利大肠，通血脉，益色泽。所主痰结、留饮、湿痹等病机明确，然全段未言脉象，不能作脉学病机推断。", []], "25573": ["其他", "此段为猪各部位药用记载，未涉脉象。原文述猪四足治伤挞败疮、下乳汁，心主惊邪忧恚，肾理肾气、通膀胱，胆治伤寒热渴，齿治小儿惊痫，肪膏解斑蝥、芫青毒；又谓\"凡猪肉，味苦，主闭血脉，弱筋骨，虚人肌\"，病人金创者尤甚。虽言\"闭血脉\"，乃药食之性，非脉象，不能据以论脉。", []], "25574": ["其他", "此段为《本经》蜚虻条文，未言脉象。原文称蜚虻\"味苦，微寒\"，主\"逐瘀血，破下血积，坚痞症瘕，寒热，通利血脉及九窍\"。所主瘀血、下血积、坚痞症瘕，皆属血瘀积结病机，通利血脉九窍亦针对瘀阻，然全段无脉象描述，不能作脉学病机分析。", []], "25575": ["其他", "此段极简，仅言药物\"有毒\"，\"通利血脉\"，生晋阳及人家屋间，立秋采。全段未及脉象，亦未详述病症，只载通利血脉之功。既无脉象可辨，又无具体症候可参，只能视为药性记载，不能据以推断病机或主病。", []], "25576": ["其他", "本段为《本经》水斳（水英）的性味主治条文，未涉及脉象。原文称其“主女子赤沃，止血养精，保血脉，益气”，是从药物功用角度说明水斳能清利湿热、凉血止血、滋养精血，故适用于女子赤沃（湿热血带）及血脉不固之出血，并能益气肥健。全段无脉诊内容，不能据以推断病机脉象。", []], "25577": ["其他", "本段为狗青（萆薢）的别名、性味及形态产地记载，属本草内容，未言脉象。文中“皮白有赤脉”指药材外皮白色、内有赤色纹理，是描述药物形态的“脉”字，非诊脉之脉。全段主旨在于辨识药材、记录采制时月，与病机脉象无关，故脉象要素为空。", []], "25578": ["其他", "本段为某药（苦寒入厥阴血分）的性味归经与主治配伍，未涉脉象。原文“除血脉之热”“疗崩带，止反胃吐衄”说明其能清血分热、凉血止血，故治崩带吐衄、惊痫疳疾；末言“气不足、津液燥者禁用”，提示苦寒伤气耗津之戒。全段属药性治法范畴，无脉象可录。", []], "25579": ["其他", "本段记咸寒药物（如朴硝类）的主治与配伍，未言脉象。原文“治暑火热泻，疗伤寒壮热”“治目中赤脉”中“赤脉”指目络充血，非脉诊；配硫黄、硝石“治上盛下虚，救阴助阳，有扶危拯逆之功”，说明其能清热泻火、交通阴阳。全段为药性配伍内容，脉象要素从缺。", []], "25580": ["病机", "本段论黄耆补气有内外之分，未直接言脉，但所析为气虚病机。原文强调“气之卫于脉外者，在内之卫气”“肌表之气，补宜黄耆；五内之气，补宜人参”，指出内气虚乏而误用黄耆升提于表，则“外气日见有余，而内气愈使不足”，久则血无所摄、营气消散而成虚损，说明补气须辨内外，混治则误。", []], "25581": ["误治", "本段以“脉息虚微之误”立论，言阴虚火炎者脉本虚微，医者不察，疑养阴力缓而投人参，致“升气助火”，精液枯涸者尤忌，犹如“天干地燥，溪水断流”，进参则燥烈而死。又言外感邪窒脉络，脉按之非空虚，若误认虚微而用参，亦助邪为害。故虚微之脉须辨内伤阴虚与外感邪塞，不可径作气虚施补。", ["虚", "微"]], "25582": ["其他", "本段为辛温入厥阴气分药物的功用记载，未涉脉象。原文“止风虚眩晕，通血脉九窍，治痫定惊，治风疏痰，有自内达外之功”，说明该药能疏风痰、通血脉、定惊痫，故配川芎治肝虚头痛，配白术去湿。全段属药性主治与配伍，无脉诊内容，脉象要素为空。", []], "25583": ["其他", "本段为微苦微寒入足少阴经药物的主治配伍，未言脉象。原文“清上焦氤氲之热，滋下焦少阴之水”“退无根浮游之火，为清肃枢机之剂”，说明其能滋阴降火、清肃上焦，故治伤寒沉昏身热、温疟寒热及阴虚火动；方中“赤脉贯瞳”指目赤血络，非脉诊。全段属药性治法，脉象从缺。", []], "25584": ["病机", "原文虽以药效为主，但提及脉劲急、沉急，劲急为血瘀化热、经脉拘急之象，沉急为热郁血分、瘀阻脉道所致。丹参养血活血，能去宿血、生新血，故治风邪留热、产后烦热、心腹结气、女人经脉不调，皆因血瘀血虚、郁热内扰。脉劲急沉急反映瘀热内结，与所主养血活血、清血瘀之效相应。", ["劲", "急", "沉"]], "25585": ["病机", "原文未识脉名，主述药性苦寒入血分，主血中郁热，去心腹邪气，利二便，解黄疸，消肿胀，托痘疹，化紫斑。血中郁热则脉多数或涩，热郁血分故见黄疸、肿胀、斑疹。药能利九窍、通脉络、达皮毛，使郁热从二便解，血热清则斑化痘透。脾虚便滑者禁用，示寒凉伤脾之戒。", []], "25586": ["病机", "原文未识脉名，述药辛苦温，入阳明气分，去风湿寒痹，疗黄疸酒毒，舒筋养血。风湿寒痹阻于经脉，气血不畅，故脉多弦紧或濡缓。药祛湿为主，湿去则筋舒血养。得肉桂治产后中风，配阿胶艾治胎动，佐柴胡治风湿骨蒸，皆从祛湿通痹、调营卫取效。", []], "25587": ["病机", "原文未识脉名，述药辛苦温，气雄而散，入太阳气分理游风。风湿相搏，本经头痛，骨节酸疼，一身尽痛，失音不语，口眼歪斜，目赤肤痒，疽痈血癞，皆风邪湿浊痹阻太阳经脉所致，脉当浮弦或紧。药能散风胜湿，通利关节，故配独活松节治历节风痛，君川芎当归治头痛脊强而厥。", []], "25588": ["病机", "原文载脉之急，指带脉拘急之象。风邪客于阳明，阳气陷于至阴，非升不散不举，故脉见急。升麻辛微苦微温，入阳明太阴气分，能升散风邪、升举阳气，消疮痈解百毒。得葱白白芷缓带脉之急，佐葛根石膏治胃火齿痛，同葛根治脾土火郁，皆从升散郁火、舒缓筋脉取效。", ["急"]], "25589": ["其他", "原文未识脉名，主述贝母炮制及鉴别。去时感火痰，去心糯米拌炒；胃寒者姜汁炒。贝母中独颗不作两片无皱者号丹龙精，不入药，误服令人筋脉不收，惟黄精小蓝汁可解。此段强调药物真伪鉴别及炮制对筋脉之害，非论脉象病机，故归其他。", []], "25590": ["病机", "原文载脉不长实，指血虚发热症似白虎，但脉不长实，误服白虎汤即死。血虚发热，脉当细弱或虚数，不长实，示非阳明实热。川芎辛温，入血分，行血和血，养营调气，去风散寒，治疟痢痘疹、痈疽疮疡、诸痛。君黄耆治血虚发热，佐荆芥治产后中风，皆从养血活血、调营卫取效。", ["长", "实"]], "25591": ["病机", "原文未识脉名，述川芎辛温，入厥阴气分，血中气药，上行头目，下行血海。散风寒，疗头痛，破瘀蓄，调经脉，治寒痹筋挛，目泪多涕，痘疮不发，血痢滞痛，心胁诸痛。寒凝血滞则脉多弦紧或涩，药能活血行气，散寒通滞，故配地黄止崩漏，配参耆补元阳，佐犀角牛黄去痰火清目疾。", []], "25592": ["治法", "原文未言脉，专述某药酸苦微甘微寒，入太阴厥阴血分，功能泻木中之火、固腠理、和血脉、退虚热。所主病机为肝火犯土、血虚有热，故治脾热易饥、泻痢后重、血虚腹痛、胎热不安；配干姜治久带，配犀角治衄咯，皆从清肝凉血、缓中止痛立法，非凭脉断病。", []], "25593": ["治法", "原文未及脉象，述药辛苦寒入少阴厥阴，凉心散郁、破血下气。所主病机为心肝郁热、血随气逆，故治血气心腹诸痛、妇人经脉逆行、吐血衄血、产后血败冲心、痰迷心窍。末言阴虚火炎、气虚胀滞、吐血不关气郁者禁用，正恐寒凉破气更伤虚体，是从病机反证用药界限。", []], "25594": ["病机", "原文未出脉，论药辛微苦入厥阴少阳气分，通行十二经及奇经八脉。所主病机为气滞则血不生、气滞则郁结不通，故曰疏之即所以生之。治一切血凝气滞之症，得夏枯草治睛痛，得栀连降郁火，得藿香甘草治妊娠恶阻，皆以疏气通滞为枢，气行则血自生、郁解则诸症自平。", []], "25595": ["病机", "原文未言脉，列柴胡、川芎、香附、木贼、天麻、薄荷、紫草七药，分治肝经风热、血气、郁结、寒邪、血脉、风火、热毒。所主病机为肝经为病，风、热、气、血、寒、毒各有所偏，故治之各有攸当。末戒勿得杂投以伤肝气，强调辨明肝病性质而分途施治，非一概疏肝。", []], "25596": ["病机", "原文未出脉，述药辛苦温入厥阴气分兼血分，散瘀破结、通利血脉、祛风邪。所主病机为血中之风，故治中风口噤、身直项强、口面㖞斜及吐衄崩中、肠风血痢、产风血晕。称其最能祛血中之风，为风病血病疮病产后要药；配童便治产后中风，配灵脂炭止恶露不止，皆从血分搜风立论。", []], "25597": ["治法", "原文未及脉，言药辛苦温走足三阴、通十二经兼入奇经，理气血、辟诸疫、除寒湿不时之痢。所主病机为寒湿凝滞、气血不和，故得生姜治男女下血，得干姜驱冷气，佐阿胶安胎兼治虚痢。又指出热在阴分而汗者不宜用、虚热而胎不安者不宜用，是从寒温属性反定禁忌，非据脉辨证。", []], "25598": ["病机", "原文未言脉，述药微辛微苦气寒入厥阴气分，解阴中郁结之热、通血脉凝滞之气。所主病机为阴分郁热、血脉凝滞，故合香附贝母治头疮瘰疬，调茶清香附甘草治目珠热痛。末言气虚者禁用，正因寒凉通散易伤正气，是从病机推断用药宜忌，全段未涉脉象。", []], "25599": ["病机", "原文未出脉，言药苦辛微温微涩入厥阴气分，通血脉、理筋骨、疏肝气、利关节。所主病机为血气凝滞不畅，故一切崩漏、金疮折跌、痈毒血痢，惟此治之则血气流畅而自疗。配杜仲治漏胎，佐人参扶脾气；又戒初痢勿用、怒气郁者禁用，是从疏而兼补、性温之偏反推禁忌。", []], "25600": ["病机", "原文以「脉不浮紧有力」作为禁用麻黄的条件，反证浮紧有力为寒邪在表之脉。今脉不浮紧有力，说明表寒不实，或素体真阴内虚、卫气不足，虽有伤风有汗、血症、春时瘟疫发热恶寒，亦无头疼身痛拘急，故不可用麻黄发汗，以免更伤卫气阴液。", ["浮", "紧"]], "25601": ["主病", "原文言「惟身首拘急而痛，六脉浮紧有力，可用」麻黄。浮紧有力为寒邪束表、卫阳奋起抗邪之象，故见身首拘急而痛，属真正伤寒邪在太阳经，宜麻黄升散寒气。若感冒寒湿或时邪疫症，虽恶寒发热而脉不浮紧有力，用之则卫气大伤，津液干燥。", ["浮", "紧"]], "25602": ["病机", "本段未言脉，主述药性入手足少阴、厥阴及手太阳血分，生血以清阴火，生气以行阳分。所治惊悸经枯、掌中热、劳劣痿厥、吐衄崩漏便秘等，皆阴血不足、阴火内扰之候；「麦冬为佐，复脉内之阴」，说明其功在复脉内阴血，使血足气得所归。", []], "25603": ["病机", "本段未识脉名，言药入少阴、厥阴血分，通血脉，治诸淋、下乳汁、催生产、疗疮疡、除风痹。原文自注「血气不行，则风毒不去，营卫逆于肉里则生痈」，点明诸症病机在血气不行、营卫逆滞，故以通血脉为治；孕妇、失血、崩漏禁用，亦因破血之故。", []], "25604": ["病机", "本段未识脉名，述药治风、清肺、治目中赤脉、通月水，并言「肝虚，受孕，二者禁用」，自注「以破血故也」。可知其病机在于血行不畅、目赤脉滞、月水不通，药以破血通经为功；肝虚及受孕者禁用，正恐破血伤正、动胎。", []], "25605": ["主病", "原文标「两尺脉沉微者可用」。两尺候肾与命门，沉微为真阳衰微、沉寒内伏之象，故药主六腑沉寒、回三阴厥逆，非大寒直中阴经及真阳虚散几脱不宜轻用。其引补气药追复失散元阳，引温暖药祛除在里冷湿，皆针对尺脉沉微所反映的阳衰寒盛病机。", ["沉", "微"]], "25606": ["病机", "本段未识脉名，言药入太阳经兼达十二经络，宣五脏、通经脉、去腹中冷滞、行胸中痰水，治疟疾肠风、症积、周身风注酸疼。其病机为冷滞痰水阻遏、经脉气血不通，故以宣通为治；末言「气虚血弱者禁用」，自注「疏脏腑真气」，示其疏泄太过恐伤正气。", []], "25607": ["主病", "原文言「治水肿浮大」，浮大为水气泛溢、邪热壅盛之脉。药入厥阴、手足太阳气分，泄三焦邪热而归小肠，通九窍血脉而利关节，故治水肿浮大、君火上炎、喉痹、脾疸、鼻齆耳聋、痈肿，皆三焦邪热与水气壅滞所致，以泄热通脉为功。", ["浮", "大"]], "25608": ["治法", "本段未言脉，专述药物性味功效与配伍用法。药性甘平微寒，入足阳明、太阴经，能去风火、除气胀、解热痢、消肿毒；得黄耆当归甘草则托痈疽，得粉草则解热毒下痢。所治五种尸疰，皆因风火痰瘀流窜脏腑血脉所致，故以清热祛风、行气消肿为治，属治法范畴。", []], "25609": ["治法", "本段未识脉名，述药性甘寒，能去燥热、利小便、止消渴、和血脉。所主妊娠劳热、胎动血崩，皆由燥热伤血、血不循经而致；热毒痢则因热毒蕴结肠道。配粟米煮食，取甘寒清润以和胃气，属以药测证之治法，非脉象主病。", []], "25610": ["治法", "本段未言脉，述药甘平滑利，入足太阴兼手阳明血分。理女子经脉、催生下乳，治汗多胃燥、里结后重、皮肤顽痹，皆取其滑利润燥、通利血脉之功。合苏子研汁治虚风便秘，同紫菀杏仁治大便不利，明言肺气润则便自利，属润肠通便之治法。", []], "25611": ["治法", "本段未识脉名，述药甘平，得天地中和之气，和五脏、通血脉、壮筋骨、长肌肉。晚收色白者性凉入肺，清热除烦、解渴凉血利便；早米粉扑小儿初生无皮，粳米粉扑自汗不止。全段以药性平和、调补五脏为旨，属平补调养之治法，无脉象可据。", []], "25612": ["治法", "本段未言脉，述药甘寒，入手少阴、足阳明气分。解热毒、除烦渴、利小便、厚肠胃、消肿胀、散风火，能调和五脏、行十二经脉，解一切药草牛马金石诸毒。得大麻仁消血痢，配赤小豆解痘毒，皆取甘寒清热解毒、通利经脉之功，属治法范畴。", []], "25613": ["治法", "本段未识脉名，述药辛甘大热，行十二经络，通血脉、利筋骨、温肠胃、润皮肤、引药势上行。少饮和血行气、壮神御寒，过饮则伤神耗血、损胃烁精。配生地汁治产后血秘，取辛热行血与甘寒润燥相配。全段论药性利弊及配伍，属治法。", []], "25614": ["病机", "原文载「右脉涩，关脉沉」，为血留胃脘作痛之脉。涩主血行不畅、瘀血内停，沉主病在里、气机郁滞；右脉候气，关部候中焦脾胃，涩沉并见，说明瘀血留着胃脘、气机阻遏不通，故见胃痛。药辛温入厥阴血中行气、入少阴壮阳助肾，散瘀逐痰宽胸，正合此病机。", ["涩", "沉"]], "25615": ["其他", "本段未识脉名，记怪症「脉溢」：毛窍出血不止、皮胀如鼓、目鼻口被气胀合，乃气逆血溢、脉络胀满之危候，故急饮生姜汁和水以辛散降逆。又载产时用力太过致育膜受伤、肉线脱出，先服失笑散，再以姜麻油炒热熏熨，属杂症外治急救，归其他。", []], "25616": ["其他", "此段为药性主治及禁忌，未及脉象。言辛温入足阳明，能利肠胃、通血脉、除膈中臭气，属温通阳明之品；然泄泻者禁用，因辛温耗散，泻者中气已虚，再投温散则肠胃更伤，故以泄泻为禁，非凭脉断病。", []], "25617": ["其他", "此段述药性甘冷而滑，入手太阳、阳明，通肠胃、利脏腑、行血脉、解酒毒，为滑利清凉之品。多食令人脚软，腹冷者禁食，正因滑冷伤中阳、下趋耗气。全段论药效与宜忌，未涉脉象，故脉象要素为空。", []], "25618": ["其他", "此段言药甘平冷，入手太阴，凉血解毒、化痰消肿，治肠风崩漏、通脏腑脉络、利大小肠秘，皆血热妄行、肠燥之候。得灯心葱白治小儿浮肿，配棕榈炭治血崩，入凉血药治吐衄，均示凉血止血之功，原文未及脉象。", []], "25619": ["其他", "此段述辛热有毒之药，入手足太阴兼命门气分，通君火、达命门、开腠理、行血脉、散寒湿、化症癖、止泄泻、杀蛔虫，主寒湿沉寒之证。配乌梅伐肝气，配茴香治久泻，炒热包阴囊治疼闷，皆取温通散寒，原文未出脉象。", []], "25620": ["病机", "此段辨析附子与肉桂救阳之别：附子救阴中之阳，肉桂救阳中之阳。桂性轻扬，能横行达表、走窜百脉，故所救在阳中之阳，其病机为阳气衰于表、百脉失于温通。原文以药性轻扬走窜说明桂之作用层次，未直接描述脉象。", []], "25621": ["其他", "此段论桂枝辛甘微热，入足太阳兼手太阴气分，通血脉、达营卫、去风寒、发邪汗，为内热外寒之圣剂。得茯苓御水气上犯以保心，配黄芩转少阳之枢，佐人参发阴经之阳。末列阴血虚、素有血症、外无寒邪、阳气内盛四禁，阳盛下咽则毙，原文未及脉象。", []], "25622": ["病机", "原文以「尺脉细弱」为禁例。尺候下焦肾与脾胃，细弱示气血不足、中阳不振，故脾胃虚泻者禁用此药，恐其制炙之法更伤中气。脉细弱在此标示脾胃虚泻之病机根本，属虚证禁药之凭据，与泄泻症候相应。", ["细", "弱"]], "25623": ["其他", "此段言药甘凉，入足少阴经血分，补水生津、和血脉、利五脏、通关窍、解酒毒，入糯米酿酒治水肿胀满，得生熟地治阴虚火动。所主为阴虚水亏、血分有热之候，全段论药性与配伍主治，未述脉象，故脉象要素为空。", []], "25624": ["其他", "本段为药性主治，未及脉象。述药甘平微寒入足厥阴肝经，能去肝家燥热、消风眼赤脉，治青盲疳气攻目。其病机在肝经燥热上攻目窍，故以清肝润燥之品施治，配川柏根治障翳，酒浸蜜蒸以缓其性。全段无脉诊内容，不可附会脉象。", []], "25625": ["其他", "本段述药苦平入足厥阴肝经，去风湿、益血脉，主崩漏、散疮疡、安胎下乳。病机为肝经风湿与血分失调，故配阿胶治胎动腹痛，配芎、防治下痢脓血。原文未言脉象，仅列药性与配伍主治，属本草主治范畴，不得臆断脉象。", []], "25626": ["其他", "本段言药甘温，补中益血、通经脉、除风湿，以血滴耳鼻治耳聋鼻衄、痘后目翳，和葱汁涂赤游风，和麝香涂口眼㖞邪。病机重在血虚风湿、经脉不通，故取补血通脉之法。原文通篇为药性与外治用法，未涉脉象，故脉象要素为空。", []], "25627": ["其他", "本段述药咸微温入足厥阴、少阴经，通血脉、去寒湿，治血痢痰疟、赤白带下、阴蚀肿痛、惊气入腹、腹痛环脐。病机为寒湿阻于血脉、肝肾二经失和。所列配伍如鹿茸阿胶治崩中带下、生地黄治血淋，皆从通血脉去寒湿立法。原文无脉象描述。", []], "25628": ["其他", "本段言药甘微咸平，入足少阴经血分，通血脉、疗蒸热，治腰脚血结及疟邪成痞。病机为少阴血分瘀结、虚热内蒸，故配妇人头发、芎、归治难产，配枳壳开产门，配杜仲止泻痢。全段为药性配伍，未及脉诊，脉象要素从缺。", []], "25629": ["其他", "本段述药甘微温入胃，健脾利水、通血脉，配北五味煮食养胎气，配胡蒜丸治水泻不止。病机为脾胃虚弱、水湿不化兼血脉不畅，故以健脾利水立法。原文仅言药性主治与配伍，未出现脉象描述，故脉象要素为空，不可强解。", []], "25630": ["其他", "本段极简，言药甘热，补肾、通督脉，治腰痛下痢。病机为肾阳不足、督脉不通，故取甘热之品温补肾督。腰痛下痢皆肾督虚寒之候。原文未述脉象，仅列药性与主治，属本草内容，脉象要素无从取字。", []], "25631": ["其他", "本段言药甘温，通十二经脉、填骨髓、平三焦、止泄痢，配地黄汁治羸瘦，和羊脂白蜜姜汁煎膏治劳损风湿。病机为虚损风湿、经脉骨髓失养，故以温补通脉立法。原文通篇为药性与配伍，未及脉象，脉象要素为空。", []], "25632": ["其他", "此段论药性禁忌，非脉诊内容。文中「磨指透甲者真」为药材鉴别描述，非脉象；「风中血脉及腑者，用之引风入骨」说明该药能引风邪深入，故风邪在血脉及腑者用之反引邪入里；「脾胃虚寒者，易于作泻」指出虚寒之体用之易伤脾阳致泻，故并禁用。全段主旨为药物禁忌与鉴别，与脉象病机无关。", []], "25633": ["其他", "此段为药性论述，非脉诊段落。文中「通督脉之气舍，达奇经之阳道」言该药能温通督脉阳气；「一切阳虚，以致耳聋目暗，眩运虚痢等症，得此自治」说明其主治阳虚诸症；「配苁蓉、麝香，治酒泄骨立」等为配伍应用。全段未涉及脉象，主旨为药物性味归经与主治，故不列脉象要素。", []], "25634": ["其他", "此段为药性论述，非脉诊内容。文中「助相火，通督脉」言该药温助相火、通督脉；「生用：行血消肿，辟邪祟。熟用：强阳活血，除梦交」说明生熟异治；「得人参、生姜，治产后喜呕」等为配伍主治。全段未言脉象，主旨为药物性味、归经与功用，故脉象要素为空。", []], "25635": ["其他", "此段为药性论述，非脉诊段落。文中「补阴中之阳道，通督脉之血舍」言该药能补阴中阳气、通督脉血分；「壮筋骨，疗崩带，妇人虚冷，胎寒腹痛，此为要药」说明其主妇人虚冷胎寒诸症；「得龙骨，治盗汗遗精」为配伍应用。全段未涉及脉象，主旨为药物功用与主治，故不列脉象。", []], "25636": ["其他", "此段为药性论述，非脉诊内容。文中「消瘀血，止吐衄，下胞胎，疗血运」言该药消瘀止血；「能引肺火下行，从膀胱而出」说明其引火下行之功；「加猪胆汁，入姜附汤，治伤寒少阴症厥逆无脉，下利不止，干呕欲饮水者」为配伍治少阴厥逆无脉之症，此处「无脉」为症状描述而非脉象要素。全段主旨为药物功用与配伍，故脉象为空。", []], "25637": ["其他", "此段仅「入冲脉」三字，为药物归经论述，言该药入冲脉，非脉诊内容。文中未出现任何脉象描述，亦未论及病机、主病或症候，故脉象要素为空，主旨归为其他。因原文过简，无法展开病机分析，仅能确认其属归经记载。", []], "25638": ["其他", "此段仅「入冲脉」三字，与上段同类，为药物归经记载，言该药入冲脉。原文无脉象描述，无病机、主病或症候论述，故脉象要素为空，主旨归为其他。因原文极简，不能引申为脉学病机内容，仅如实反映其归经属性。", []], "25639": ["其他", "此段仅「行冲脉」三字，为药物归经论述，言行冲脉，非脉诊内容。原文未出现脉象描述，亦未论及病机、主病或症候，故脉象要素为空，主旨归为其他。与「入冲脉」诸条同类，属药性归经记载，不能作为脉象病机分析之依据。", []], "25640": ["其他", "原文仅言“行冲脉”，未及具体脉象与主症，属冲脉循行或诊冲脉部位的记述。冲脉为十二经之海，起于胞中，上行脊里，其“行”字提示讨论经脉走向而非脉象主病，故无从据脉论病机，只能归为其他类，不可强解为某病之脉。", []], "25641": ["其他", "此段亦仅作“行冲脉”，与上条相类，重在冲脉循行路径的交代，未出现脉形描述，也无主病、主症之文。冲脉上行主渗诸阳、下行主渗诸阴，然原文未涉病机，故脉象要素为空，不宜附会弦、急等字，归入其他。", []], "25642": ["病机", "原文“主冲脉为病，逆气里急”，点明冲脉病机核心在于气逆。冲脉起于胞中，挟脐上行，气逆则上冲，故见逆气；里急为腹内拘急不舒，是冲脉之气失于和降、内迫腹中所致。此段以证候言病机，未出脉形，故脉象要素为空。", []], "25643": ["病机", "此段兼言冲、带二脉为病。冲脉病则“逆气里急”，气从少腹上冲；带脉环腰一周，带脉病则“腹满腰溶溶如坐水中”，形容腰部弛缓无力、如坐水中之状，是带脉约束失职、水湿停滞之象。原文以症释机，未及脉形，故脉象要素为空。", []], "25644": ["病机", "原文“主冲脉逆气”，承冲脉为病之旨，突出气逆一端。冲脉为病，气机上逆而不降，故称逆气，可伴胸腹气冲、里急等症。此段文字简略，未描述脉象，只言病机所属，故脉象要素为空，归为病机类，不可臆补弦、紧等脉。", []], "25645": ["病机", "此段言冲脉为病，见“逆气里急，脐腹痛”。冲脉挟脐上行，其气逆则上冲，里急为腹中拘急，脐腹痛正冲脉所过之处气机壅逆所致。原文以脐腹疼痛定位冲脉病，说明逆气里急的具体症候，未出脉形，故脉象要素为空。", []], "25646": ["病机", "原文“主冲脉为病，逆气里急”，与前列诸条同旨，重申冲脉病机在于气逆内急。冲脉为病，气逆上冲则逆气，内迫腹中则里急，二者相因为患。此段未描述脉象，仅以证候明病机，故脉象要素为空，归病机类，不附会具体脉名。", []], "25647": ["病机", "原文作“主冲脉逆气里急”，虽标注“脉逆气里急”，实为冲脉病之证候而非脉形描述，故脉象要素为空。冲脉之气上逆则逆气，内迫则里急，是冲脉为病的典型病机。此段与诸条互见，强调气逆里急，未出具体脉象，不可据“脉”字强解为某脉。", []], "25648": ["病机", "原文以“脉逆气里急”言冲脉为病，脉气逆上而腹里拘急，说明冲脉失其下行之常，气机逆乱。冲为血海，隶于阳明，其气逆则里急不舒，故主冲脉逆气里急之病机，与少腹气上冲、腹中拘急等症相应。", []], "25649": ["病机", "原文仅言“走督脉”，未出具体脉名，指脉气循行归于督脉。督脉总督诸阳，行于脊背，脉气走注于此，说明阳气循督上行之机，故归入病机类，提示病变与督脉经气相关，而非专主某脉某病。", []], "25650": ["主病", "原文“主督脉为病，脊强而厥”，未识脉名而直指所主。督脉循脊属肾，阳气不通则脊强，阳失温煦则厥冷，故脉应于此主督脉为病，与脊背强直、四肢厥逆等症相应，是据脉断病之论。", []], "25651": ["主病", "此段重申“主督脉脊强而厥”，脉象未识而主旨明确：脉气应于督脉，督阳痹阻则脊强，阳气不达则厥。说明该脉所主在督脉病变，与脊强、厥逆之候相应，属据脉定位主病之文。", []], "25652": ["病机", "原文“通督脉”，未出脉名，言脉气通达督脉。督脉为阳脉之海，脉通于此，说明阳气循督运行之机畅达，故归病机类，提示该脉与督脉经气相通，为后文辨督脉病证作铺垫。", []], "25653": ["病机", "此段亦言“通督脉”，与上条同意，指脉气与督脉相通。督脉总督一身之阳，脉通督脉则阳气升降有路，说明病机关乎督脉经气之通塞，非专主一病，故列病机，提示从督脉论治之依据。", []], "25654": ["病机", "原文“通督脉之气舍”，气舍指督脉经气留止之处。脉气通于此，说明督脉气机汇聚之所相通，病机重在督脉之气舍通塞，与脊背阳气运行相关，故归病机类，提示该脉可察督脉气舍之病变。", []], "25655": ["病机", "原文“通督脉之精室”，精室指督脉深部藏精之处。脉气通于精室，说明督脉不仅行阳气，亦与精血相关，病机涉及督脉精室之通塞，故归病机类，提示该脉可反映督脉精室病变，与脊强、厥逆之外更及精亏之候。", []], "25656": ["治法", "原文仅言「温督脉之血」，未出脉象，故脉素为空。此条属治法，指督脉血寒或血虚致脉道失温，治当温养督脉之血。脉象虽未明，然血寒则脉多沉迟而涩，血虚则脉细弱，温之则血行脉通。与脊强、厥冷等督脉失温之症相应。", []], "25657": ["治法", "原文仅言「通任脉」，未载脉象，脉素为空。此属治法，任脉主一身之阴，若任脉不通，多见脉沉涩或细弦。通任脉即调畅阴经气血，使脉道通利。与任脉为病所见少腹结块、月经不调等症相应，原文未及具体脉症，故只就治法立论。", []], "25658": ["主病", "原文「主督脉脊强而厥」，未出脉象，脉素为空。督脉循脊属肾，阳气不足或经气痹阻则脊强而厥。此条主病，指督脉为病以脊强、厥冷为主症。脉虽未言，按督脉病多现沉紧或弦细，反映阳气不达、经气拘急，与脊强厥逆之候相应。", []], "25659": ["主病", "原文「主阳维为病苦寒热。督脉为病。逆气里急」，未载脉象，脉素为空。阳维维系诸阳，病则卫外失司而寒热；督脉病则气逆里急。此条主病，说明阳维、督脉受病各见寒热与逆气里急。脉虽未出，阳维病脉多浮弦，督脉病脉多沉紧，与寒热、逆气里急相应。", []], "25660": ["主病", "原文「主阳维寒热。带脉腹痛」，未出脉象，脉素为空。阳维为病则恶寒发热，带脉环腰，病则腹痛。此条主病，分述阳维与带脉见症。脉虽未载，阳维病脉多浮，带脉病脉多弦紧或沉滞，反映卫阳不固与腰腹经气阻滞，与寒热、腹痛之候相应。", []], "25661": ["治法", "原文仅言「通阴𫏋督脉」，未识别脉名，脉素为空。此属治法，阴𫏋主一身左右之阴，督脉总督诸阳，二脉不通则阴阳失交。通之使阴𫏋、督脉气血畅达。脉象未出，按阴𫏋病多脉沉细，督脉病多脉沉紧，与失眠、脊强等症相应，原文未详，只就治法言之。", []], "25662": ["主病", "原文「主带脉为病」，未出脉象，脉素为空。带脉环腰一周，约束诸经，病则腰腹拘急、腹痛或带下。此条主病，指出带脉受病。脉虽未言，带脉病脉多弦紧或沉滞，反映经气约束失司、腰腹气血不畅，与腹满、腰腹疼痛等症相应。", []], "25663": ["主病", "原文「治带脉病腹满。腰溶溶如坐水中」，未出脉象，脉素为空。带脉病则约束失职，水湿停聚，故腹满、腰溶溶如坐水中。此条主病，说明带脉为病的水湿证候。脉虽未载，按此证脉多沉缓或濡，反映水湿内停、阳气不运，与腹满、腰冷重着之候相应。", []], "25664": ["治法", "原文仅言「治带脉为病」，未出脉象，故脉素为空。带脉环腰一周，约束诸经，其为病多因寒湿或劳伤致约束失职，症见腰腹纵缓或拘急。此条属治法范畴，提示治带脉病当从温通或固束入手，非凭脉断病，故不列脉象。", []], "25665": ["治法", "原文「王不留行通冲任二脉」，未载脉象。冲为血海，任主胞胎，二脉以通为用；王不留行善行血通经，故能通之。此条属治法，示冲任瘀滞者可借此通脉，非据脉辨证，故脉素从缺。", []], "25666": ["治法", "原文「调病伤八脉」，未出脉象。八脉指奇经八脉，病伤八脉者多因久病劳损致奇经失养，治当调补。此条属治法，强调调治奇经损伤，非以脉断证，故脉素为空。", []], "25667": ["病机", "原文「缓带脉之缩急」，缩急即拘紧之象，脉之缩急当属紧脉。带脉环腰，寒凝或筋脉失养则拘急而缩，故见紧象。此条言治当缓其缩急，病机在带脉拘紧，与腰腹拘急相应，属病机范畴。", ["紧"]], "25668": ["病机", "原文「和冲脉之逆，缓带脉之急」，脉之急即拘紧不和，当属紧脉。冲脉逆则气上，带脉急则拘挛，皆由气血失和、筋脉拘紧所致。此条言治当和冲缓带，病机在冲逆带急，与气逆拘急之症相应。", ["紧"]], "25669": ["预后", "原文「血脉未乱，精神未散，食药必活」，以血脉未乱为可治之候，未出具体脉名，故脉素为空。此条论预后：五脏未虚、六腑未竭、血脉未乱者药食可活；病已成则半愈，病势已过则难全，强调早期诊察与脉候判断预后的意义。", []], "25670": ["病机", "原文「听声察色，至乎诊脉，孰能知未病之病」，泛论诊脉知未病，未出具体脉象，故脉素为空。此条阐发病之所由来皆关于邪，风寒暑湿饥饱劳佚皆能为邪，邪伤经络传入脏腑，随虚实冷热结以成病，属病机总论。", []], "25671": ["治法", "原文论服药先后与病位关系：胸膈以上先食后药，心腹以下先药后食，四肢血脉宜空腹旦服，骨髓宜饱满夜服。未出脉象，故脉素为空。此条属服药治法，示因位施治、择时服药，非凭脉断病。", []], "25672": ["其他", "此段论医方本草源流，非脉诊专文。文中仅言张仲景『善诊脉、明气候以意消息之』，强调据脉测候、随证配伍，脉象本身未具体描述，故无从定脉。主旨在于说明方药须以病性为根宗、配合诸证，脉诊只是『消息』病候的一环，不构成独立病机判断。", []], "25673": ["其他", "此段为玉石类药物的性味主治，通篇未及脉象。所谓『利血脉』『疗妇人带下十二病』是药效描述，非脉象所主。原文以『味甘，平，无毒』统摄五脏百病、柔筋强骨、安魂魄，属本草主治范畴，不能据以推断脉象病机，故脉象要素为空。", []], "25674": ["其他", "此段述丹砂性味功用，『通血脉』『止烦满消渴』皆言药能，非言脉候。原文未出现任何脉象描述，仅有『养精神，安魂魄，益气，明目』等药效语。既无脉象可辨，则不能归入主病或病机，只能作本草主治观，脉象要素从缺。", []], "25675": ["其他", "此段记空青性味主治，『利九窍，通血脉，养精神，益肝气』及疗目赤、下乳汁、破坚积等，均属药物功用，未涉脉象。原文无脉名、无脉形描述，故不能以脉论病机；其『通血脉』是药效而非脉象所主，脉象要素为空。", []], "25676": ["其他", "此段述芒硝主治，文中『疗五脏十二经脉中百二十疾』之『百二十疾』指经脉病证数目，非脉象写法，不能误作脉名。全段言药性大寒、涤蓄结、推陈致新，属本草主治，未描述脉形脉势，故脉象要素为空，不作脉诊病机分析。", []], "25677": ["其他", "此段为朴硝所生药物之性味主治，『通经脉，利大小便及月水，破五淋，推陈致新』皆药效语，非脉象。原文未出现浮沉迟数等脉形描述，亦无脉候与病机对应之论，故脉象要素为空，只能归入本草主治一类，不涉脉诊。", []], "25678": ["其他", "此段辨石之真伪形色，『如石脉』『作针理文』是形容石夹两石间纹理如脉，非诊脉之脉象。原文言酒浸服疗癖、令人肥悦，属药物鉴别与主治，未及脉候，故脉象要素为空，不能据『石脉』二字误认脉名。", []], "25679": ["其他", "此段述方解石类药性味主治，『通血脉，明目，去翳眇』及止消渴、下气、除胁肋肺间邪气，均属药效。原文『理如马齿，方而润泽』是状石之形色，非脉象描述。全段无脉名脉形，故脉象要素为空，不作脉诊病机推断。", []], "25680": ["其他", "此段为药物主治条文，未及脉象。原文述其味苦辛大寒，主胸中留热、结气、黄疸，通血脉、去蛊毒。所主病机为热邪留结胸中、气机壅滞，兼及湿热发黄与血脉瘀阻。因无脉象可据，不能以脉推病，仅录其药性主治，属本草内容而非脉学。", []], "25681": ["其他", "此段亦为药物主治，未载脉象。原文主鬼疰、贼风、蛊毒、腹中毒邪气，及女子赤沃漏下、带下、产难、胞衣不出、堕胎，养血气、除五脏血脉中热、血痹血瘀。所主病机为邪毒内结、血分热瘀与胎产诸疾，全凭药性立论，无脉可参。", []], "25682": ["治法", "此段述外治与酒服之法，未言脉象。先刺腋下脉去血，再以醋和药封之攻腋臭；又熬热投酒服，主贼风反折；烧赤铜入酒服，亦主贼风。所主病机为腋下血络郁滞及风邪入中、筋脉反折，属治法内容，脉象无从取证。", []], "25683": ["其他", "此段为药物形态描述，未涉脉象。原文言其根皮肉汁与天门冬同，惟无心脉，去根五六寸有十余子卫，似芋，实似苦楝子，核作五六棱，中肉如面，得根即生啖。全段辨药形、别真伪，与脉诊病机无关，故列其他。", []], "25684": ["其他", "此段为药物主治，未载脉象。原文主心腹结气、伤中伤饱、胃络脉绝、羸瘦短气，身重目黄、心下支满、虚劳客热、口干燥渴，止呕吐、愈痿蹶、强阴益精。所主病机为胃络虚绝、气结中焦、津亏虚劳，皆从药性推治，无脉可凭。", []], "25685": ["其他", "此段为地黄主治条文，未言脉象。原文主折跌绝筋、伤中、逐血痹、填骨髓、长肌肉，除寒热积聚，主男子五劳七伤、女子伤中胞漏下血，破恶血溺血，通血脉益气力。所主病机为血痹瘀阻、骨髓空虚、劳伤出血，属本草主治，非脉学。", []], "25686": ["其他", "此段为菊花主治，未载脉象。原文主风头眩、肿痛、目欲脱、泪出、皮肤死肌、恶风、湿痹，疗腰痛去来陶陶，除胸中烦热，安肠胃，利五脉，调四肢。所主病机为风邪上扰头目、湿痹阻络、胸中烦热，全凭药性论述，无脉象可据。", []], "25687": ["其他", "此段为甘草主治，未言脉象。原文主五脏六腑寒热邪气，坚筋骨、长肌肉、倍力，金疮肿解毒，温中下气，烦满短气、伤脏咳嗽，止渴，通经脉、利血气，解百药毒。所主病机为脏腑寒热错杂、中气不足、血脉不利，属本草内容，无脉可参。", []], "25688": ["其他", "此段为药性主治文，未及脉象。原文述人参味甘微寒微温，主补五脏、安精神、定魂魄、止惊悸、除邪气，又疗肠胃中冷、心腹鼓痛、胸胁逆满、霍乱吐逆，通血脉、破坚积。其病机为五脏虚损、正气不足，故以甘味补益、微寒清热、温通血脉，使神安悸止、逆满消除，属补虚扶正之品，非论脉也。", []], "25689": ["其他", "此段为药物品种考证，未涉脉象。原文辨漏芦有两种：生平泽者与生山岗者，后者叶相似而无疏缺、多毛、茎无羽、根直下无旁枝，肉白皮黑、中有黑脉，晒干黑如玄参。用叶茎及根疗疳蚀杀虫俱验，并辨俗以马蓟似苦芺为漏芦之误。全段重在形态鉴别与功效验证，非脉学内容。", []], "25690": ["其他", "此段为芍药药性主治，未言脉象。原文称味苦酸平微寒有小毒，主邪气腹痛、除血痹、破坚积、寒热疝瘕，止痛利小便益气，通顺血脉、缓中、散恶血、逐贼血、去水气、利膀胱大小肠、消痈肿。其病机核心在血脉瘀滞与水气内停，故以酸苦通顺血脉、散恶逐贼、缓中止痛，属活血利水之品。", []], "25691": ["其他", "此段述干姜（或姜）药性，未及脉象。原文味辛温大热无毒，主胸满咳逆上气，温中止血出汗，逐风湿痹、肠澼下痢、寒冷腹痛、中恶霍乱胀满、风邪诸毒、皮肤间结气、止唾血，生者尤良，疗风下气、止血、宣诸络脉、微汗，久服令眼暗。病机为寒邪内盛、阳气不振，故以辛热温中散寒、宣通络脉。", []], "25692": ["其他", "此段为药物形态描述，未涉脉象。原文言山野处处有，与菝葜相似而小异：茎叶小肥、节疏、茎大直、上有刺、叶圆有赤脉，根凹凸巃嵸如羊角细强者是。全段纯为植物性状鉴别，以叶脉赤色、根形如羊角为特征，无病机脉象可论，故列其他。", []], "25693": ["其他", "此段为通草（或木通）药性主治，未言脉象。原文味辛甘平无毒，主去恶虫、除脾胃寒热、通利九窍血脉关节、令人不忘，疗脾疸常欲眠、心烦、哕出音声、耳聋，散痈肿诸结不消及金疮恶疮、鼠瘘、踒折、齆鼻息肉、堕胎、去三虫。病机为湿热壅结、血脉关节不通，故以辛甘通利九窍血脉、散结消痈。", []], "25694": ["其他", "此段仅存“百脉根”三字，为药名条目，无脉象、无病机、无主治内容可析。既未述脉，亦未言证，无法据以推断所主病机，故脉象要素为空，归类其他，谨照原文存目，不作臆测。", []], "25695": ["其他", "此段为旋覆花药性主治，未及脉象。原文味咸甘温微温冷利有小毒，主结气胁下满、惊悸、除水、去五脏间寒热、补中下气，消胸上痰结、唾如胶漆、心胁淡水、膀胱留饮、风气湿痹、皮间死肉、目中眵䁾，利大肠、通血脉、益色泽，根主风温。病机为痰饮结气、水湿内停，故以咸甘消痰逐饮、通血脉。", []], "25696": ["其他", "本段为牡桂的性味主治，非脉学内容。原文'温筋通脉'指药物温通筋脉之功，非脉象描述；'主上气咳逆，结气，喉痹'等为桂主治症候，与脉象无关。故不取脉象要素，归为其他类。", []], "25697": ["其他", "本段述桂（肉桂）性味功效，'通血脉'为药物宣通血脉之效，非脉象。'主温中，利肝肺气，心腹寒热'等皆药治症候，无脉象描述，故脉象要素为空，归其他类。", []], "25698": ["其他", "本段为桑耳、木耳类药物的性味主治。'脉绝'指伤中五劳六极所致血脉虚绝之症，非脉象；'补虚，益气'为药效。全段无脉象描述，故脉象要素为空，归其他类。", []], "25699": ["其他", "本段述巴椒（巴豆类）性味主治，'破症瘕，结坚积聚，留饮痰澼'等为药治症候，'益血脉'为药效，非脉象描述。全段无脉象要素，归其他类。", []], "25700": ["其他", "本段为蜀椒（巴椒）性味功效，'通血脉'指药物开腠理、通血脉之效，非脉象；'主邪气咳逆，温中'等皆药治症候。无脉象描述，脉象要素为空，归其他类。", []], "25701": ["其他", "本段述某药（槐类）主治痔、血痢等，'取脉灸用之'指取该药之脉（茎脉）灸用，非诊脉之脉象。全段无脉象描述，脉象要素为空，归其他类。", []], "25702": ["其他", "本段述羊髓、青羊胆等性味主治，'利血脉，益经气'为药效，非脉象；'主男女伤中、阴气不足'为症候。无脉象描述，脉象要素为空，归其他类。", []], "25703": ["其他", "本段述马类诸药主治，'主伤中，脉绝'指伤中致血脉虚绝之症，非脉象；'强志益气，长肌肉'为药效。全段无脉象描述，脉象要素为空，归其他类。", []], "25704": ["其他", "本段为鹿茸、鹿角、鹿髓等药物的性味主治记载，虽标题标注脉象写法为“屋漏”，但原文并无脉诊内容，仅述鹿茸“破之火干”、鹿髓“主丈夫女子伤中脉绝”等药理。所谓“脉绝”指伤中致血脉虚竭之证，非论脉象本身，故不能据以推断病机脉象，只能归入其他类。", []], "25705": ["其他", "本段罗列猪各部位的性味主治，如猪心“主惊邪、忧恚”、猪齿“主小儿惊痫”、猪屎“主寒热、黄疸、湿痹”等，通篇为药物功用记载，未涉及任何脉象描述。原文无脉诊信息，不能凭空推断脉象要素，故脉象要素为空，主旨归入其他。", []], "25706": ["其他", "本段引《别录》述雀屎和乳点目消胬肉赤脉、蜜丸酒服主症癖久痼冷病等，属药物外用内服方治记载。“赤脉贯瞳子”指目中赤色脉络，为眼疾症状描述，非脉诊之脉，原文亦无脉象论述，故不能提取脉象要素，归入其他类。", []], "25707": ["其他", "本段论露蜂房之形态、用法与主治，如烧灰酒服主恶疽附骨痈、水煮服下乳石、疗上气赤白痢遗尿失禁等，皆为方药治疗内容。原文虽提及“恶脉诸毒”，但“恶脉”指恶疮毒肿之类病名，非脉象描述，全段无论脉之文，故脉象要素为空。", []], "25708": ["其他", "本段述某药（当为虻虫类）味苦微寒有毒，主逐瘀血、破血积坚痞症瘕、通利血脉九窍、女子月水不通等，为活血破瘀药物之主治记载。“通利血脉”指药物功效在于通畅血脉，非论脉象形态，原文无脉诊内容，故脉象要素为空，归入其他。", []], "25709": ["其他", "本段载某药味咸寒有毒，主血瘀症坚、寒热、破积聚、喉咽闭、内寒无子、通利血脉，属破血消症类药物功用。“通利血脉”言药效通血脉，非脉象；全段未涉脉诊，不能提取脉象要素，主旨为药物主治，归入其他类。", []], "25710": ["其他", "本段引《别录》述梅根疗风痹、出土者杀人，梅实利筋脉去痹，为梅类药性主治简记。“利筋脉”指梅实能舒利筋脉，属功效描述，非脉象；原文无脉诊内容，脉象要素无从提取，故归入其他类。", []], "25711": ["其他", "本段载水英味甘平无毒，主疗女子赤沃、止血、养精、保血脉、益气、令人肥健嗜食，为药物性味功用记载。“保血脉”言其能护养血脉，属药效而非脉象描述；全段无论脉之文，脉象要素为空，主旨归入其他。", []], "25712": ["主病", "原文仅言芹花「主脉溢」，未出具体脉名。脉溢指血溢于脉外或脉气满溢之候，芹花味苦能泄，故以之主治。此条属药性主病，非脉象描述，故脉象要素为空，病机为苦味泄降以制脉中气血之溢。", []], "25713": ["主病", "此段述麻勃、麻子药性主治，未及脉象。麻勃辛平有毒，主五劳七伤、破积散脓；麻子甘平，补中益气、逐水破积血、复血脉，兼疗乳妇产后余疾。全段以药论病，脉象无载，故脉象要素为空，主旨归主病。", []], "25714": ["主病", "原文「主气脉溢」，与芹花条「主脉溢」相类，皆言苦味药能制脉气之满溢。气脉溢指脉中气机壅满外溢之病机，苦能泄降，故主治之。此条未出脉名，属药性主病，脉象要素为空。", []], "25715": ["主病", "原文谓其味苦温，主充肌肤、益气，令人暴肥、血脉满盛，且「不可久服」。血脉满盛即脉道充盈太过之象，苦温助阳，久服则气血壅盛，故戒之。此条论药性致血脉满盛之弊，未出脉名，脉象要素为空。", []], "25716": ["其他", "此段为邹澍先生小传，叙其家世、孝行与勤学，末言其于天文地理、江淮河汉之脉络条理皆能洞悉。文中「脉络条理」指地理水道，非诊脉之脉，全段与脉学无关，故脉象要素为空，主旨归其他。", []], "25717": ["主病", "此段述丹沙药性：味甘微寒无毒，主身体五脏百病，养精神、安魂魄、益气、明目、通血脉，止烦满消渴，杀精魅邪恶鬼，除中恶腹痛毒气疥瘘诸疮。全为药性主治，未涉脉象，故脉象要素为空，主旨归主病。", []], "25718": ["病机", "此段阐发丹沙主治之理：以气寒非温煦生生之具，故仅于身体五脏百病中养精神、安魂魄、益气、明目。又释「血脉不通」为水中之火不继续，「烦满消渴」为火中之水失滋泽，「中恶腹痛」为阴阳不相保抱、邪得乘间而入。全段论药性所对之病机，未出脉名，脉象要素为空。", []], "25719": ["病机", "此段引《素问》「地气上为云，天气下为雨」，论云母生成兼天气地气：非天气不得晶莹，非地气不得坚韧，地气不应则云母生。全段以天地气交喻药性生成之理，未涉脉象与诊病，故脉象要素为空，主旨归病机。", []], "25720": ["其他", "此段为消石本草主治，非论脉。原文虽言「疗五脏十二经脉中百二十疾」，乃指药能通行十二经脉、涤除蓄结积热，非谓脉见百二十疾。其病机为五脏积热、胃胀闭、饮食蓄结，故以苦辛大寒之品推陈致新、除邪气，与脉象无涉。", []], "25721": ["其他", "此段述朴消、芒消主治，未及脉象。原文「逐六腑积聚、结固、留癖」及「破留血闭绝、停痰痞满」，明其病机为热结、血闭、痰痞，故用咸苦大寒以软坚散结、推陈致新。所云「能滑能濇」乃言药性变化，非脉象描述。", []], "25722": ["病机", "此段以水火分消，论药性病机而非脉。原文「水消治热之结」「火消治热之郁」，结多属血分，郁多属气分；「阴不降，阳不化」「阳不升，阴不畅」为寒热结郁之机。以咸辛气味升降归原，说明二消虽同治热，而气血分途、阴阳升降各异。", []], "25723": ["病机", "此段借滑石洁白腻滑之性，论其通六腑九窍津液。原文「胃中积污」「利小便，荡胃中积聚寒热」，指出病机为胃中积污、津液不利，外见身热、内见泄澼。以熨斗烙油污为喻，说明滑石能浥污从下窍出，非论脉象。", []], "25724": ["病机", "此段引仲景「阳明病，脉浮，发热，渴欲饮水」，猪苓汤用滑石。脉浮为热在阳明之表，然渴欲饮水、小便不利，则里热已结、水气不化。原文以「胃中积聚，寒热，身热，口渴，小便不利」括其证，说明脉浮与里热并见，主热结水停之机。", ["浮"]], "25725": ["其他", "此段为菊花本草主治，未言脉象。原文「主风，头眩，肿痛，目欲脱，泪出，皮肉死肌，恶风，湿痹」，其病机为风邪上扰、湿痹肌表，故以甘苦平之品疏风除湿、利五脉、调四肢。所云「利五脉」指药效通利血脉，非脉诊之脉。", []], "25726": ["其他", "此段述人薓主治，未及脉象。原文「主补五脏，安精神，定魂魄，止惊悸，除邪气」，其病机为五脏虚损、神魂魄不安，兼肠胃中冷、心腹鼓痛、胸胁逆满、霍乱吐逆。以甘微寒微温之品补虚安神、调中通脉，非论脉诊。", []], "25727": ["其他", "此段以《别录》「除邪气」一语，列举仲景方治以证人薓之用。原文分述「肠胃中冷」「心腹鼓痛」「胸胁逆满」「霍乱」「吐逆」「调中」「消渴」诸证，皆属虚寒或虚实夹杂之病机，故以人薓补虚调中。全段论方证，未涉脉象。", []], "25728": ["病机", "原文以「发汗后，身疼痛，脉沉迟」论邪正分合。脉沉迟者，沉主里、迟主虚寒，是汗后营气受损、邪因虚陷之象，故身疼痛而脉不浮紧。徐氏借此说明「虚处宜补」，当用人参以扶正，与「外有微热」之尚合未分相对，示人辨邪正离合而施攻补。", ["沉", "迟"]], "25729": ["病机", "原文引「伤寒，脉浮，发热，无汗，其表不解者，不可与白虎汤」，以脉浮发热无汗定表邪未解，故禁白虎。又言「渴欲饮水，无表证者，白虎加人参汤主之」，是脉浮去而渴见，则风寒已化、邪正已分。浮脉在此为表证之凭，用以判表解与否，非主里热。", ["浮"]], "25730": ["病机", "本段论诸方用人参轻重，以虚多于邪者反少用，申「少用壅滞，多用宣通」之说。所举炙甘草汤证脉结代、心动悸，为气血虚衰、脉道不续；附子汤证脉微，为阳气式微。结代与微皆虚象，故诸虚证用人参以驾驭邪药、宣通气血，非徒壅补。", ["结", "代", "微"]], "25731": ["病机", "原文论人参治呕有专长，凡呕而胸满、肠鸣心下痞、发热、胃反呕吐皆用之。所引脉洪大者，为里热正盛之象；脉沉者，为里实之候。二者皆呕家不用人参之例，因邪实方盛，误补则壅滞。洪大与沉在此标示邪实当禁，与虚呕宜参相对照。", ["洪", "大", "沉"]], "25732": ["其他", "本段为《本经》甘草条文，述其气味主治：主五脏六腑寒热邪气，坚筋骨、长肌肉、倍力，金疮肿解毒，温中下气，止渴通经脉，解百药毒。全段纯论药性功用与采制畏恶，未及脉象，故脉象要素为空，主旨归入其他。", []], "25733": ["病机", "本段以甘草得四气之全、协土德和众气，释「主五脏六腑寒热邪气」及解百药毒之理。谓人之气「急疾者其媸恶」，甘草性缓能化急疾为和顺，使经脉通调、血气滑利，于是肌骨坚、肌肉长、气力倍。全段论药性缓急与血气通调之机，未涉脉象。", []], "25734": ["病机", "本段释甘草泻火之说，举栀子甘草豉汤治虚烦少气、甘草汤治少阴咽痛二端。引东垣「心火急而乘脾」之说，谓少气虽不得为实亦不可谓虚，如饥极胸中热烦、欲动作不得。用甘草缓心火之急、补少气之虚，兼利咽止痛，全段未及脉象。", []], "25735": ["病机", "本段论甘草宜于金创之理。金创既伤则血出不止，既合则肿壅为脓；暴病心火急疾赴之，未合迫血妄行，既合壅结无所泄，自肿而脓、自脓而溃，火势郁结甚于痈疽。故王不留行散中甘草独用十八分，取其解毒缓急。全段论疮肿火郁之机，未涉脉象。", []], "25736": ["病机", "原文述炙甘草复脉汤治「脉结悸」，又言「脉之动而中止」「脉数而止」「脉促」，皆脉来中止、节律不齐之象。结、促、数而止，主气血虚衰、脉道不利，心失所养，故见悸动、烦满短气，行动如常而脉已病，属虚劳不足之机。", ["结", "悸", "数", "促"]], "25737": ["病机", "原文未出脉名，以「便厥，咽中干，烦躁，吐逆，两胫拘急」言阳明内结、阴阳气不相顺接之候。甘草干姜汤和脾安中宫阳气之怫乱，芍药甘草汤和肝通木脏阴气之凝结，说明中焦为上下之枢，阳结则厥、阴结则拘，主中焦虚寒、阴阳失调之病机。", []], "25738": ["病机", "原文言血痹「阴阳俱微，寸口关上微，尺中小紧」，微为虚之所在，紧为病之所在，主阳气阴血俱虚而风寒湿邪痹阻血络，故外证身体不仁如风痹状。又言「脉和紧去则愈」，紧去则邪退，脉和则正复，示血痹以虚为本、以痹为标之病机。", ["微", "紧"]], "25739": ["其他", "此段为干地黄、生地黄之本草主治，未涉脉象。原文列「主折跌，绝筋，伤中，逐血痹，填骨髓，长肌肉」「通血脉，益气力」及妇人崩中、下血、胎动等，说明地黄能养血脉、续绝伤，所主为血虚血痹、伤中绝筋之证，非以脉言病机。", []], "25740": ["病机", "原文未出脉名，以「痹者，闭而不通也，随其血之不通而为病」立论，列目赤、齿痛、痈肿、昏烦、咳血、吐衄崩漏等，皆血痹所生。又言「血中有痹，则骨髓不满，肌肉不长，筋脉断绝，均谓伤中」，说明地黄逐血痹、填骨髓、长肌肉，主血痹不通、伤中枯耗之病机。", []], "25741": ["病机", "原文言仲景治「脉结代」，又述「脉道泣涩」「脉结代与心动悸并称」「脉结悸与汗出而闷并述」。结代、涩，主血脉虚衰、脉道不利，营血不能荣养筋骸血络，故见心动悸、汗出而闷。地黄脂液能润泽干枯、续断养脉，说明炙甘草汤所主重在复脉，为血虚脉涩之病机。", ["结", "代", "涩"]], "25742": ["病机", "原文出「脉浮虚而濇者」，浮为表，虚为正气不足，涩为血少或水湿阻滞。此脉主表虚而水饮内停，故有中风发热、渴欲饮水、水入则吐之水逆证，及先渴却呕、水停心下之饮家。说明五苓散、猪苓散、茯苓泽藛汤诸证，皆属水饮内停、气化不利之病机。", ["浮", "虚", "涩"]], "25743": ["病机", "原文出「脉沉紧」，沉主里、主水，紧主寒、主饮。此脉说明水寒内盛、饮邪上逆，故见心下逆满、气上冲胸、起则头眩，或心下悸、头眩、身𥆧动、振振欲擗地。白术治眩非治眩，治痰与水，说明眩由水盛心神摇曳，主水饮上泛之病机。", ["沉", "紧"]], "25744": ["病机", "原文以脉微言霍乱吐利之机，谓吐多者胃病、下多者脾病。脉微示中阳不振、脾气下陷，故用术以举脾之陷、使脾气散精上归于肺、通调水道下输膀胱。吐则胃不能游溢精气上输于脾，下则脾陷不能上朝，皆由中气微弱、枢机不转所致，故脉微主中虚湿乱之病机。", ["微"]], "25745": ["病机", "此段未出脉名，论风火、风痰、风热阻经阻窍阻络之机。谓阴为泄泽骨节之物，遭中风暴热则阳与俱化而阴倚势为梗，阴阳两不相通、均不相下，近骱短络遂痹、机械废弛而失动摇。所主在阴阻助热、阳留戕阴、络痹不通之病机，非以脉言。", []], "25746": ["病机", "此段未识脉名，借脏腑藏泻论胆居阳位而禀阴体，为阳之少、倡率五腑，其用在藏而不泻，恰象春生之气奋决而出，出乎阳未离乎阴，故为半表半里。茈胡随阳气始生而萌，正合胆之升发之性。所主为少阳枢机之病机，说明柴胡入半表半里、根阴达阳之理。", []], "25747": ["病机", "此段未出脉名，论肝胆阳升阴随之升降气化。三阴经脉上行、三阳经脉下行，固有先导者。若升降不前如有窒之，当细参阴阳虚实：导阳而下者必阳实阴虚，导阴而上者必阴实阳虚；下阴不足纳阳、上阳不足化阴，则升降之原已戾。所主为阴阳升降失序、气化窒阻之病机。", []], "25748": ["病机", "原文脉弦细、脉弦，主小柴胡证之上焦不通。上焦不通则气阻，气阻则饮停，饮停则生火，火炎则呕吐；痰凝气滞，升降之机始阻，当升不升则阳怫怒为热，当降不降则阴鸱张为寒，故往来寒热。脉弦细正合少阳枢机不利、痰凝气滞之病机，柴胡通上焦、彻热蠲饮以拔其本。", ["弦", "细"]], "25749": ["病机", "原文引仲景「男子平人，脉大为劳，极虚亦为劳」，明言脉大属阴虚、极虚属阳虚，劳分两途尽于阴虚阳虚。脉大者阴不敛阳、虚阳外浮，故不可径用柴胡升散；然薯蓣丸中亦有柴胡，是虚劳兼风气百疾者又当别论。此段以脉大辨虚劳阴虚之病机，纠世人以柴胡治劳之偏。", ["大"]], "25750": ["病机", "此段未出脉名，论胃多气多血、有变动每患其实而不比于虚。胃气偏盛则所纳遂多，转输不循其序则气壅结，故有「心腹结气、伤中、伤饱」；胃络脉绝则以「胃气生热，其阳则绝」为解，结气既成则输送之机更滞。所主为胃实气壅、络脉阻绝之病机。", []], "25751": ["病机", "此段未识脉名，以麦虋冬质柔韧、色兼黄白、脉络贯心，恰合胃之形象；其根四旁横出似脏腑脉络贯注，叶隆冬愈茂能吸土中精气上滋。味甘带苦合从胃至心之妙，故胃得之输精上行、肺得之敷布四脏，结气消镕、脉络联续。所主为胃络枯绝、结气不散之病机，借药性明养胃通络之理。", []], "25752": ["病机", "原文以炙甘草汤证说明“阳中阴虚，脉道泣涩”，阴精亏虚则脉道不充、血行滞涩；又言“脉非结代，微而欲绝者，不可用也”，指出若脉微欲绝而非结代，是阳气衰微、阴精难续之候，麦冬提曳阴精之力反非所宜，故禁之。", ["涩", "微"]], "25753": ["病机", "原文未出脉名，而论麦冬“由胃至心，使脉气流经，经气归于肺，肺朝百脉”，其功在润泽心肺、通利脉道。虚劳为下焦阴虚生热，客热为上焦阴虚为热，皆可使脉失濡养而现虚数之象，故以麦冬为要药。", []], "25754": ["病机", "原文未出脉名，而言“金疮痛者，经脉以血去而濇”，血去则脉道不充而涩；“四肢挛者，经脉以湿酿而拘”，湿滞经脉则拘急。又谓湿郁化风、真阳不畅，致脊痛项强、腰似折，皆经脉不利之病机。", []], "25755": ["病机", "原文未出脉名，而论薯蓣丸为脾肺之剂。风气百疾由心肝脾之气懈于朝肺，肺不能输精于皮毛，外邪乘客；少腹有故、小便不调，则肺气怠输精，毛脉不能合精行气于腑，清浊泛源塞流，皆属肺脾失职、脉气不充之机。", []], "25756": ["病机", "原文以“腹无积聚，身无热”而“其脉为数”，说明湿气瘀血盘踞肠内，势将酿热成痈，内热将甚而外寒相格，故脉数。数脉在此主内热壅聚，与身甲错、腹皮急、按之濡等肠痈症候相应。", ["数"]], "25757": ["病机", "原文引“少阴病，始得之，反发热，脉沉者”，指出沉为在里，病已决在少阴。少阴寒邪初袭，外有发热而脉沉，是里阳不足、寒邪内伏之机；若不早治，必至吐利、手足厥冷，故用麻黄附子细辛汤内外兼治。", ["沉"]], "25758": ["病机", "原文言气分寒证“其脉，在寸口，曰迟濇；在趺阳，曰微迟”，迟涩微迟皆阳气不振、寒与胸腹津液相搏之象。上则心阳不纾，下则肾阳难达，故见心下坚大如盘、手足逆冷、腹满胁鸣、身冷骨疼等症。", ["迟", "涩", "微"]], "25759": ["病机", "原文引“风湿，脉浮，身重，汗出，恶风”，浮为风湿在表、卫阳不固；又引“手足厥寒，脉细欲绝者”，细为血虚寒凝、脉道不充。两条对举，说明寒邪有在上在外与在内在下之别，脉浮主表，脉细主里虚寒。", ["浮", "细"]], "25760": ["病机", "原文以“血不至之处，气亦不至”立论，说明阳气不至则客气乘之，导致“中风入脑，头痛，脑中冷动，面上游风去来，目泪出，多涕唾，忽忽如醉”等症。虽未言脉，但病机为气血不相辅而行，阳气虚馁，清窍失养，客邪上扰。", []], "25761": ["病机", "原文述五脏六腑精气上注于目，目疾非一经之病。黄连所主目痛必兼眦伤泣出，因热气所为；若痛因瞳子、黑睛、白眼，或泣出因风、寒、虚者，则非黄连所宜。虽未言脉，但示目病需辨脏腑阴阳，脉象当随证而异。", []], "25762": ["病机", "原文以黄芪根茎独上独下、三层界画分明，味甘气微温，直入中土而行三焦，故能内补中气、中行营气、下行卫气。所主虚损、痈疽、恶血、五痔等，皆因中气不足、营卫不和、血泣不通。虽未言脉，但脉当见虚软或涩滞。", []], "25763": ["病机", "原文引《素问》“阴不胜阳，则脉流薄疾并乃狂”，脉流薄疾指脉象急迫快速，因阴不制阳，阳热亢盛，扰及心神则狂。黄芪利阴气，通过行营气、逐恶血，使浊阴降而卫阳升，恢复阴阳平衡，故能治此。", ["疾"]], "25764": ["病机", "原文比较湿、饮、水三者，湿为弥漫雾气，水饮有质。风湿与风水均见“脉浮，身重，汗出，恶风”，脉浮主病在表，风邪激水或从风颓土，虽病不同而受病无异，故均用防己黄芪汤。脉浮在此提示邪在肌表营卫。", ["浮"]], "25765": ["病机", "原文指出风湿、风水脉浮，身重汗出恶风，用防己黄芪汤；皮水四肢肿、聂聂动，用防己茯苓汤。脉浮为病在营卫肌表，黄芪行营卫中气，使邪无所干而汗自止。防己茯苓汤去术、姜、枣加桂枝、茯苓，意在使水气从小便解。", ["浮"]], "25766": ["病机", "原文强调黄芪非止汗亦非发汗。脉浮为病在营卫，桂枝汤和营卫，加黄芪益营卫中气、濬营卫之源。防己茯苓汤证水气在皮肤中，桂枝加黄芪汤证如有物在皮中状，皆皮肤中病，黄芪治之，通过行营卫中气而取效。", ["浮"]], "25767": ["病机", "原文论五味子所治，伤寒仅言欬逆，金匮兼言上气。关键在“欬而脉浮，厚朴麻黄汤主之”，脉浮主邪在表、病偏上；若脉沉则非五味子所宜，因五味子只能收阳中之阴气。故脉浮沉决定能否用五味子，体现辨脉用药之精。", ["浮", "沉"]], "25768": ["病机", "原文虽未直接论脉，但结合〈千金〉用五味子诸方及「胃虚，客气上逆」之论，脉浮在此提示胃气虚而客气上逆，气逆伤及肺金，致肺降之力与客气相争，伤气兼伤血，故见噫止后唾血。脉浮为虚阳上浮、气逆不降之象，主胃虚气逆、肺失肃降之病机。", ["浮"]], "25769": ["主病", "原文列黄疸兼证诸方，其中「桂枝加黄芪汤证，脉浮」，脉浮为表邪未解、卫气不和之象。黄疸病见脉浮，说明新感风湿寒热之邪与素有之热相结，邪偏于表，故主表虚黄汗之证，治当调和营卫、解表祛邪，与茵陈蒿汤证之里热腹满者不同。", ["浮"]], "25770": ["病机", "此段论王不留行药性，未及脉象。原文谓「人身周流无滞者，血也」，王不留行能使「诸血不旁流逆出」，又「顺流而下者，使之无所留滞」。其病机在于血行不畅、脉络瘀滞，或血不循经而旁流逆出，故主金疮血出、鼻衄、妇人难产及痈疽恶疮等，皆血行失其常道之候。", []], "25771": ["其他", "此段为《本经》牡桂条文，未涉脉象。原文载牡桂「主上气，欬逆，结气，喉痹，吐吸，心痛，胁风，胁痛，温筋通脉」，其病机在于寒邪闭阻、阳气不通，致气机上逆而为欬逆上气，或寒凝经脉而为胁痛、心痛。桂枝辛温通阳，故能温筋通脉、散结下气，所主皆寒凝气逆之候。", []], "25772": ["病机", "此段论桂枝体用，未直接言脉。原文谓桂枝「色赤，条理纵横，宛如经脉系络」，能「利关节、温经通脉」，其用有六：「和营、通阳、利水、下气、行瘀、补中」。所主病机为风伤于外，壅遏卫气，卫强营弱，营卫不和。故以桂枝汤调和营气，使散阳气，此即「和营」为首功之义。", []], "25773": ["病机", "原文辨析桂枝与白虎兼用之理，指出「脉浮，发热，无汗」为麻黄证，禁用白虎；「白虎证者，脉大也，汗出也，烦渴欲饮水也」；而「其脉即平，身无寒，但热，时呕」非白虎证。脉浮主表邪未解，脉大主里热炽盛，脉平则邪不盛。此段以脉象鉴别表里寒热，说明不同脉象各主不同病机，不可混治。", ["浮", "大", "平"]], "25774": ["病机", "此段论柏木药性，未及脉象。原文谓「肝合乎肺而化，则阴生而血之化源裕」，「肺合乎肝而化，则阳生而气之化源裕」，其升降有穷「皆由于不相合以为化」。柏能「阳合阴而化」，故于逆顺之血类能治之。所主病机为肝肺升降失合、气血化源不足，致血不归经而逆上，非苦寒直折所宜。", []], "25775": ["病机", "此段论柏叶治血之理，未涉脉象。原文谓「肺，则主朝百脉，行治节者也。凡血得归经，自不溢为吐、衄与利」，柏叶「欲血受肺之节制，分布诸经，俾不溢耳」。所主病机为肺失治节、血不归经，故血溢而为吐血、衄血、利血。柏叶使血受肺之节制，复归常道，则血自不溢。", []], "25776": ["病机", "脉沉紧主水气内停，沉为水蓄于里，紧为寒凝气机。原文虽未直言脉象，然以四逆散证、理中丸证加茯苓，及小柴胡汤、小青龙汤去芩、麻加茯苓为例，说明水不下行则上壅，茯苓直濬其源。沉紧之脉反映水寒内结，气化不利，故见心下悸、小便不利等症，治当利水化气。", ["沉", "紧"]], "25777": ["病机", "脉沉紧主水寒内动，寸沉尺微示上焦气郁、下焦阳弱。原文论贲豚、冲气有挟水与不挟水之别，发汗后脐下悸欲作贲豚者用茯苓桂枝甘草大枣汤，烧针后发贲豚者不用茯苓，说明水气动与不动是关键。沉紧为水寒相搏，尺微为下焦阳虚，故水气上冲而为悸为贲。", ["沉", "紧", "微"]], "25778": ["病机", "脉大数主热盛，原文虽以黄疸、下利辨表里寒热错杂，但举属表属热者，如麻黄连轺赤小豆汤证、小柴胡汤证，其脉当大数。大数为热邪内盛、气血涌沸之象，故见身黄发热、热利下重等症。檗皮用于此类证，正取清热燥湿之功，非必拘于发热一症。", ["大", "数"]], "25779": ["病机", "原文未出脉名，然「脉络之空」指脉道空虚之象。发为血余，血由火成，心主血而华在发。小儿惊责心气怯，大人痓责脉络空，咳嗽为心失养而火上炎。脉络空则血不荣经，故见痓病、咳嗽等，反映心血亏虚、脉络失充之病机。", []], "25780": ["病机", "脉微主阳气衰微。原文引白通汤证「脉微，下利」，应利止脉旺，反厥逆无脉、干呕而烦，说明上有浮阳、下阳愈虚。脉微为下焦阳虚、阴寒内盛之象，浮阳上扰则头痛、温气。人尿加白通汤导水下行，即降火下泄，治头痛温气类，紧扣脉微所主之阳衰阴逆。", ["微"]], "25781": ["病机", "原文未出脉名，论阿胶「濬血之源，洁水之流」。不因经产、非关六淫，而生血之所气溃败不继、血奔溢难止，内则五脏气不凝，外则经络血不荣，见心腹内崩、劳极洒洒如疟状。此属血源亏竭、水血不调之病机，阿胶取肺皮肾水，火熬成胶，导源畅流以充脏腑行脉络。", []], "25782": ["病机", "脉浮主表热，原文阳明病脉浮发热、渴欲饮水、小便不利，用猪苓汤。浮为热邪在表，渴与小便不利为水热互结。然阿胶确证不在渴，而在「不得眠」——津液有水湿不能化，故心烦不得眠。脉浮反映水热郁于外，阿胶育阴利水，使津液化而眠安。", ["浮"]], "25783": ["病机", "原文未出脉名，论血水同源异流。血病多在泄，泄则不流而化源竭；水病多在停，停则不泽反生火。水停生火则猪苓汤、黄连阿胶汤等治之；血不流而化源竭则芎归胶艾汤、鳖甲煎丸等治之。此段从血水关系阐发病机，脉象当随证而见，或涩或细，反映血水失调。", []], "25784": ["病机", "原文论石淋与转筋，谓淋者小腹弦急、痛引脐中，转筋者臂脚直、脉上下行微弦。弦为筋急之象，微弦则筋脉拘急而不甚，故主转筋；小腹弦急则气结下焦，主石淋。二者皆消渴、伤寒寒热之流，非一物可治，明其病机各异。", ["弦", "微"]], "25785": ["治法", "此段论蜜之用法，虽标脉紧而弦，实借脉以明寒凝筋急之候。紧主寒、弦主痛，寒邪收引则脉紧弦，故用乌头汤、大乌头煎化药入蜜，以润制燥、以缓制急，使药过燥者化为润，过健者化为缓，正合紧弦之寒凝筋急。", ["紧", "弦"]], "25786": ["病机", "原文以牡蛎盐水结成、潮涨则开潮落则合为喻，论天地阴阳升降、水火相承之理。脉不行动者，言其块然不动之象，非真脉也。借牡蛎之无情而有信，明阴精水气随月盈虚、潮汐起伏之机，以喻人身阴阳消息、水气承制之道。", []], "25787": ["病机", "原文引伤寒脉浮、医以火迫劫之而亡阳，又及脉芤动微紧。浮为邪在表，火迫则津伤而脉芤，动主惊，微紧主虚寒。惊怖火邪皆从惊发，致心无所依、神无所归，故脉浮而芤动微紧，主亡阳惊狂之机，治以救逆。", ["浮", "芤", "动", "微紧"]], "25788": ["病机", "此段借雀入海为蛤，喻火伏于水。引伤寒病在阳、以冷水噀灌，热被劫不得去，弥更益烦、肉上粟起，脉紧者，寒水外束、火热内郁之象。紧主寒束，火厄于水则阳郁不伸，故主水气遏阳、热不得越之病机。", ["紧"]], "25789": ["病机", "原文论橘皮从脾胃大络外达肌肉毛孔，中宫浊气留聚则假气成形为瘕热逆气，脾不散精则水谷壅滞。橘皮芳香辛苦，通达胃络，使留聚自通、水谷自利。此段无脉象，主在阐发橘皮利水谷、通络散滞之病机。", []], "25790": ["病机", "原文标脉紧腹中痛之寒疝瘕，紧主寒、主痛，寒凝气滞则腹中痛而成疝瘕。橘皮气温味苦辛，能行滞气、利水谷，无间寒热升降补泻皆可合之。水谷气畅则真气受益，故紧痛之寒滞，得橘皮通利而解。", ["紧"]], "25791": ["病机", "原文论大枣禀火德而生土，味甘性缓臭香，以火气运用其间，故能补中托邪、安中行气。脉结代者，中气不足、心脉不畅之象，炙甘草汤用枣以补中焦、资脉气，使结代得通。此段借枣之性能，明中虚脉结代之病机。", ["结", "代"]], "25792": ["病机", "原文虽以姜枣配伍论营卫，但脉沉迟提示邪陷于里，营卫不和。沉为病在阴，迟为阳不胜阴，故营气虽和而卫气不共谐，见常自汗出。此脉象说明表邪已内涉，营卫运行迟滞，主病机为营卫不调，与自汗、发热等症相应。", ["沉", "迟"]], "25793": ["其他", "本段为麻子仁性味功用记载，未涉脉象。原文述其「主补中益气」，能「逐水，利小便，破积血，复血脉」，主乳妇产后余疾。所论为药性主治，非脉诊病机，故脉象要素为空，主旨归为其他。", []], "25794": ["病机", "本段引刘潜江论麻子仁，谓其生于木火正旺、成于金水方饶，能「于木火焦杀中生金水柔滋之化」，使「中土升清降浊之机栝不愆」。所论为药性所以能补中益气、久服肥健之理，属病机层面之药性阐释，未及具体脉象。", []], "25795": ["病机", "本段比较麻仁与地黄之性能，谓麻仁「善宣阴津于阳分」「善行阳滞，布阴气」，与芍药同用则破阴结、布阳气。所论为药物入阴入阳、破结行滞之能事，以复脉、通便为效，属病机与治法范畴，原文未出脉象。", []], "25796": ["病机", "本段论酒与糖之性，酒「酿久方成」而性反迅，糖「片时便就」而性反缓，故酒为缓物之报使，糖为急剂之柔佐。又辨虚烦、虚痞、虚肿、虚满与虚劳、虚损、虚羸、虚弱之别，属病机辨析，未涉脉象。", []], "25797": ["病机", "原文引「伤寒，阳脉濇，阴脉弦，法当腹中急痛」，以脉弦主急痛，涩主营血滞涩。小建中汤所治之「里急」「腹中急痛」，正是弦脉主痛、涩脉主营虚血滞之病机。故本段脉象说明虚劳里急、营卫不和之腹痛病机，与悸、衄、梦失精等症相应。", ["弦", "涩"]], "25798": ["病机", "原文辨悸之来源，谓「有心中自动者，心液虚也；有他处动而连及心者，水饮也」。脉结代主心液虚而脉道不续，故悸由心液虚所致；水饮上冲亦能致悸，然其脉当别有所见。本段以结代脉说明心液虚、脉气不续之病机，主心悸，与虚劳诸症相应。", ["结", "代"]], "25799": ["病机", "原文列瓜蒂散诸证：寸脉微浮主胸中寒实、气上冲；脉乍紧主邪结胸中；脉微弱主夏月伤冷水、水行皮中；脉弦迟主胸中实。诸脉皆说明邪实结于胸中或水饮停聚之病机，主胸中痞鞕、气上冲、手足厥冷等症，治当因势吐之或温之。", ["微", "浮", "紧", "弦"]], "25800": ["病机", "原文以雄黄「刚土、性寒」论治土中湿热酝酿之火，谓其「辛生皮毛，故仅能主其在外者」，即土中实结之火非所能治。借《金匮》阳毒「面赤斑斑如锦文」用之、阴毒「面目青」去之，证阳毒阴毒皆由土中湿热酝酿而成。全段论药性所主病机，非脉象，故脉象要素为空。", []], "25801": ["病机", "原文举「心下有水气，肺胀，咳，上气而喘，脉浮」为小青龙汤证，多烦躁则加石膏。脉浮主水气在表、肺气胀逆，故咳喘上气。段中又辨石膏为烦设，谓「阴气偏少，阳气暴胜，外有所挟，内有所亏」乃为烦，化暴胜之阳、解在胃之聚，非专治烦，说明脉浮所主水气与烦之病机。", ["浮"]], "25802": ["病机", "原文辨麻黄配石膏「发散不猛」，以麻杏甘膏汤汗出而喘、越婢汤续自汗出为据。谓麻黄从阴通阳，阳厄于阴有因寒凝、因热壅之异，佐桂枝则经络并通，佐石膏则有纵无横。因热者「阳猖而阴不与交」，须泄热使阴交于阳。脉反微弱正示阳郁不伸、阴不与交之机，故取泄热通阳。", ["微弱"]], "25803": ["病机", "原文论水饮与热「本同而末异」，水本属太阳原能盛热，热去而水尚在，故用麻黄兼去水。举「风水，恶风，一身悉肿，脉浮，不渴，续自汗出，无大热，越婢汤主之」，脉浮主风水在表、水气溢于肌腠，故一身悉肿、恶风、续自汗，治当通阳去水兼泄热。", ["浮"]], "25804": ["病机", "原文以姜之生长论气味禀受：中夏发生感火气故性温，交湿令根株横溢感土气故色黄，交燥令气全用具故味辛，统之「火者其禀，土者其体，金者其用」。全段借物性阐药性生成之理，未涉脉象与诊病，故脉象要素为空，主旨归病机。", []], "25805": ["病机", "原文设问仲景用干姜于四逆辈至少、于大建中等至多，答以病根深浅、用法机势。谓人伤于寒则病热，本阴伤局，因治法紊乱致「阳越阴搏」，故见「脉微」「下利」「烦躁」「头眩身𥆧」，其阳衰也骤、阴横也飘忽。脉微主阳气骤衰、阴寒横逆，非阳虚无阴盛之常。", ["微"]], "25806": ["病机", "原文列太阳脉浮紧失汗致衄、吐血不止、下利便脓血、金疮、陷经漏下诸证，辨失治养痈贻患、误治无益有损，谓血「遇寒则凝」。引《脉要精微论》「脉搏坚而长」「脉微急为肺寒热」，浮紧主表寒郁闭，坚长、微急示邪搏血分，故失汗则血妄动，说明血证由寒凝与邪激之病机。", ["浮", "紧", "坚", "急"]], "25807": ["病机", "原文辨生姜、干姜去皮留皮之别，谓生姜刮皮暴干「但存其筋」，姜非在地极老不足为干姜，须去皮、渍水、盦酿乃得暴干而肉如故。结论「生姜之走，干姜之守，系于老与嫩，不系于去皮、留皮」。全段论药材质地与走守之性，未及脉诊，故脉象要素为空。", []], "25808": ["病机", "原文虽未直接论脉，但以“脉细欲绝”提示血分虚寒之机。寒邪挟饮逼迫气分则病在上，见胸中似喘不喘、似呕不呕；寒邪乘虚逼迫血分则病在下，见寒疝腹痛、胁痛里急、产后腹中㽲痛。脉细欲绝正是阴血亏虚、寒邪内侵之象，故以生姜类方温散寒邪、调和气血。", ["细"]], "25809": ["病机", "本段未涉脉象，专论葛根与栝蒌、土瓜之药性异同。葛根辛甘发散属阳，入肺开皮毛，故能散发腠理之邪而“起阴气”；栝蒌、土瓜酸苦涌泄属阴，入心通血脉，故有滑泽径道之功。三物皆自下而上，然葛根偏于外散阳邪，二物偏于内润枯槁，其主治“消渴”皆因能启阴气上滋。", []], "25810": ["病机", "脉促见于“太阳被下，利遂不止，喘汗者”，为阳盛于外、不与阴交，阴遂不固而下溜。葛根芩连汤用葛根起阴气，使阴阳相浃，曳以上行，则利止而阳之遏于外者随胃阳鼓荡而散。此脉促非虚寒所致，乃阳郁不伸、表邪内迫之象，故以葛根兼擅升阳与浥阴之长。", ["促"]], "25811": ["病机", "本段未及脉象，借栝蒌根与实之形态论药性。根能启阴气上滋，实能导痰腻下降。栝蒌根浸捣后肉尽成粉，余存筋脉，谓之“散质簇为聚质”，故能散阴津以上行；栝蒌实外皮成壳、内结重蒌，脂液附聚，故能导痰浊以下降。此即根升实降、上下分治之理。", []], "25812": ["病机", "本段未涉脉象，论栝蒌根味苦性寒，合于脾脏之德。其止渴乃“脾气散精，上归于肺”之效；脾阴效用则肠胃痼热可除，黄疸因脾津被热约而蒸盦者亦解。短气为肺阴虚，小便过利为肺火盛，冲脉隶于阳明，血涸或热结者得凉润之剂则涸者滋、结者解，月水自通。", []], "25813": ["病机", "小陷胸汤证脉“浮滑”，栝蒌薤白白酒汤证脉“寸口沉迟，关上小紧数”，皆阴中有阳且踞于阳位。气与饮相阻，寒与热相纠：热甚于寒者束缚急而为结，故脉浮滑；寒甚于热者蔽塞盛而为痹，故脉沉迟。结胸病伏宜开，胸痹病散宜通，脉象正反映寒热纠葛之深浅。", ["浮", "滑", "沉", "迟"]], "25814": ["病机", "“太阳病证备，脉反沉迟”为阳证见阴脉，因误治发汗太多致痓，津液耗伤，脉道泣涩不前，故脉沉迟。此非小青龙、小茈胡未经误治者所有。阳证见阴脉其病已危，然用桂枝汤从容解外，互文见意，示人知误治致虚、津亏脉涩之机，不可峻汗再伤。", ["沉", "迟", "涩"]], "25815": ["病机", "百合病“口苦，小便赤，其脉微数”，微为阴虚，数为有热，乃伤中上之阴、虚热内扰之象。病非五脏菀热实候，只在病人意中辗转不适，一月不解变成渴，则阴伤益著。脉微数正合虚热轻浅之机，故用栝蒌牡蛎散润养阴液、清泄虚热。", ["微", "数"]], "25816": ["病机", "原文以苦薓为喻，论脾土不能防水，致血、津、液、湿被火结而成症瘕、积聚、痈肿、黄疸。其病机核心在“土之不能防水”，苦薓味苦气寒，正除火之结，使水摄归脾土输泄之道，体现“以收摄为流通”之理。此段无脉象描述，故脉象要素为空，主旨属病机阐发。", []], "25817": ["病机", "原文以当归发芽于仲春、开花于仲秋，论其功始于肝、终于肺，体滑润故不能升，气厚味薄，阴挠阳，用不能违体，故上至于肺、外达皮毛。专入血分，因肝藏血、脾统血、心主血皆在所部。全段以药性推演气血运行之理，无脉象描述，主旨属病机。", []], "25818": ["病机", "刘潜江论当归味甘次苦次辛复甘，苦属心归血所主，辛为金火相合以孕水，火因金和于水则气化，金孕水亲于火则血生。始甘者谷入于胃传肺，终甘者泌糟粕津液化精微上注于肺化为血。故能养血、和血、行血，随所引各归其所。全段无脉象，主旨属病机。", []], "25819": ["病机", "原文以麻黄实中黑外赤、茎似脉络骨节，论其先天由肾及心、后天由心及脾肺，分布心阳外至骨节肌肉皮毛，使留滞倾囊出。又论天寒地水凝冰，人身精血津液亦然，精被寒凝则阳气沸腾为伤寒温疟。全段以药性及寒凝之理阐发，无脉象，主旨属病机。", []], "25820": ["病机", "原文引《伤寒》脉法“脉浮而紧”及柯韵伯“太阳中风脉浮紧”“阳明中风脉弦浮大”等，辨风寒伤营卫不可截然分割。脉浮紧主寒邪外束、营卫俱伤；脉弦浮大主阳明中风、气机郁滞不得汗。诸脉并见，说明风寒二气一而二、二而一，营卫同病，非可拘泥“寒必伤营、风仅中卫”之说。", ["浮", "紧", "弦", "大"]], "25821": ["病机", "原文论有汗亦可用麻黄，如麻杏甘石汤、越婢汤证。脉浮主邪在表，浮大主阳热犹盛。其病机为寒邪外著、热气腾沸，阴气痹阻不与阳交，故阳逼阴外为汗、逐阴上为喘、郁不宣为风水、阻气上为肺胀。脉浮大正示阳盛不与阴和，故虽汗出仍可借麻黄使阴交于阳。", ["浮", "大"]], "25822": ["病机", "原文辨“风寒两伤营卫”之说无据，论大青龙扼要为寒水之化聚于上。风性急疾，故脉紧急绞转、脉数急；寒性凝重，故脉宛转不畅而浮紧、浮缓。风甚者内侵甚则不汗出而烦躁，寒甚者障蔽甚则身不疼但重。诸脉反映风急寒凝、寒水聚上之病机，治当急治。", ["紧", "数", "浮", "缓"]], "25823": ["病机", "原文论麻黄非特治表，凡里病可使从表分消者皆用之。脉浮主表证，脉紧主寒邪。有表证者用麻黄发汗去邪热除寒热；无表证而用麻黄，则取止欬逆上气、破症坚积聚之功。脉浮紧示寒邪束表或里病有从表分消之势，故广用麻黄于风、寒、湿、黄、寒热、水、欬诸证。", ["浮", "紧"]], "25824": ["病机", "原文引《千金》「心脉厥大，寸口小肠热，齿龋，嗌痛」，脉厥大指心脉气逆而大，主心热满烦闷、惊恐，热邪循经上炎则齿龋嗌痛，下移小肠则寸口应之。此脉大因热盛气逆，非虚大之比，故以麻黄汤调心泄热，开泄郁热之结。", ["大"]], "25825": ["病机", "原文「脉微而恶寒」「脉微弱者」，微为阳虚，弱为气弱，主太阳病日久，邪郁不解而阳气已伤，故恶寒、面有热色、身痒，热多寒少如疟状。脉微弱示正虚邪微，宜桂枝二越婢一汤小发其汗，与柴胡证往来寒热、休作有时者不同。", ["微", "弱"]], "25826": ["其他", "此段为通草本草主治，未涉脉象。通草味辛甘平，主去恶虫、除脾胃寒热、通利九窍血脉关节，疗脾疸、耳聋、痈肿诸结不消。其病机在脾胃寒热壅结、血脉关节不通，故以通利为用，非脉诊所主。", []], "25827": ["病机", "原文「脉为血之府」「经脉所以行血气」，虽未出具体脉象，然论木通通水道即通血脉之理。水为血母，血为水精，源同派别，故治水即能治血，治血即能治水。脉为血府，营卫通调则水血俱行，此以脉之生理阐药效病机。", []], "25828": ["病机", "原文「手足厥寒，脉细欲绝」，细为血虚，欲绝为阳衰，主血虚寒厥，阴邪水饮阻隔阳气，气血不能温煦四末。脉细欲绝示气息之微，非气不煦而由血不濡，故当归四逆汤通血脉、散寒邪，而非助阳壮气之剂。", ["细"]], "25829": ["其他", "此段为芍药本草主治，未涉脉象。芍药味苦酸平微寒，主邪气腹痛、除血痹、破坚积、寒热疝瘕，通顺血脉、散恶血、去水气。其病机在血痹坚积、水气不化，故以破结行血利水为功，非脉诊所主。", []], "25830": ["病机", "原文「脉促」「脉弦涩」，促为阳结，弦涩为阴结气滞。小建中汤证见烦悸里急腹满痛，为阴气结；小便自利而发黄，是水气化而谷气不化，阴结阳不布。芍药入脾开结，通顺血脉，故脉促弦涩主阴阳互结、谷气郁滞之病机。", ["促", "弦", "涩"]], "25831": ["病机", "原文「脉伏，其人利反快」，伏为留饮内结、阳气不布，利反快示饮欲去而心下续坚满，故用甘遂半夏汤开结行水。又「脉弱，其人续自便利」，弱为太阴脾虚，便利而腹痛不止者，芍药尚在必用，以开阴结。二脉均主结与虚之病机。", ["伏", "弱"]], "25832": ["病机", "原文以「脉得诸芤动微紧」与「脉极虚芤迟」并举，芤主亡血，动主阴阳相搏，微紧主虚寒收引。芤动微紧并见，说明阴不交阳、阳气四射逼血外出，故男子失精、女子梦交；极虚芤迟则清谷亡血失精。其同在亡血，其异在少腹弦急，芍药所主正在此阴结弦急之处。", ["芤", "动", "微", "紧"]], "25833": ["治法", "原文「太阴病，脉弱，其人续自便利」，脉弱示胃气弱，故虽当行大黄、芍药亦宜减之，以「胃气弱，易动故也」。此段借脉弱申明用药须顾胃气：芍药开阴结、大黄开阳结，品物迥殊而开胃和中则同，寒热虚实之机全在脉弱与否上别之。", ["弱"]], "25834": ["病机", "原文三证均「脉浮」而小便不利、渴，作者据脉浮知水气在表、气化不行：五苓散证自太阳发汗后胃干求水，水不行而为患；猪苓汤证上有「阳明病，脉浮紧」，是热与水结。脉浮为水气动而不化，紧则水停不行，故猪苓、泽泻治动水，瞿麦治停水，用药殊异而利水则同。", ["浮", "紧"]], "25835": ["病机", "本段未出脉名，借百合根「味甘色白」「十百相攒而内抱」论其土金合德、金水相生之性。小便化于肺而出于膀胱，为金水相接；大便化于胃而出于大肠，为土金相接。若阳不化阴则大小便不利，非百合所主；阴不济阳虽化而不畅，方是百合补中益气、通利中寓补之病机所在。", []], "25836": ["病机", "原文标「脉微数」，微为气伤，数为热。百合病发于汗吐下后，邪搏气分则消渴热中，搏血分则血脉中热，扰心则烦懊不寐。脉微数正示汗吐下后阴伤而邪热未净、气血两伤之机，故治法辗转不离百合，以百合甘润清气分、凉血分，随所伤而调之。", ["微", "数"]], "25837": ["病机", "原文标「脉浮数者」，浮为热越于外，数为火用不宣。作者辨知母能下水，正因火用不宣则水停为患，甚有火盛水反不流、因热而渴、因渴引饮、饮多水不化而肿者。脉浮数示热与水搏之机，故用知母益阴清热，使火宣而水行，非以水济水、增其泛滥。", ["浮", "数"]], "25838": ["其他", "本段为《图经》记𦮷母形色产地，纯属药物描述，未及脉象与病机，故脉象要素为空。文中「上有红脉」指花上红色纹理，非诊脉之脉；「内心外瓣」「四方连累相著而有分解」状其根瓣聚散之形，为下文论药性主治张本，本身不主病。", []], "25839": ["病机", "本段亦无脉名，刘潜江以「叶随苗出」「但有直透，更无濡留」体𦮷母之性：直透能开热之结，无濡留能达肺之郁，与「善疗郁结之疾」合。作者则辨阳开发、阴凝聚，若阳为阴聚、结热而成郁，则药性苦合微寒、白象金，正从二阴至肺处开其郁结，非泛论脉候。", []], "25840": ["主病", "原文虽提脉迟、脉浮洪，但此段主论黄芩汤证治，非专论脉。其证身热、下痢或呕、腹不痛，脉浮洪为热盛于外，迟或因热壅气滞。芍药甘草大枣和营，黄芩清热，因不恶风故不用姜桂，不往来寒热故不用柴胡，常热故不用人参。脉象在此提示热邪为患，而非虚寒。", ["迟", "浮", "洪"]], "25841": ["病机", "原文未识脉名，主论宗气积于胸中，贯心脉行呼吸，根于肾主于心。肺虚则欬逆上气，火刑金则喘欬唾脓血，虚而成劳。紫菀色紫质柔，为水火合，故能治肺虚咳逆。此段从气化论病机，非以脉断，故脉象要素缺如。", []], "25842": ["其他", "原文仅提脉沉，但全段主旨批评近人疏笺《本经》以意见附会经文，如“苦能降，复能通”等，反晦经旨。紫薓主治心腹积聚、寒热邪气，非仅利大小便可解。脉沉在此或指病位在里，但非论述重点，故归为其他。", ["沉"]], "25843": ["误治", "原文引“脉浮，热盛，反灸之，此为实，实以虚治，必咽燥唾血”及“微数之脉，慎不可灸”，说明脉浮热盛或微数属阳热实证，误用灸法（藉阳通阴）则追虚逐实，火邪内攻，血散脉中，致烦逆、咽燥唾血。散脉示气血耗散，为误治变证。", ["浮", "散"]], "25844": ["病机", "原文未识脉名，论消渴饮水一斗小便一斗，因内痹不纳，水不四布；又引“血凝于肤为痹，凝于脉为泣，凝于足为厥”，热烁血濇则太冲脉不通。此段从津血运行论消渴、痹厥病机，未及具体脉象。", []], "25845": ["其他", "原文未识脉名，以水草（藻、蒲荷等）生长形态比喻人身经脉：水象血及津液，石象骨，泥象肉；能出水者象血津出清空，不能出水者仅行血液涕唾中；两两相对、节节相连、柔韧碎整，喻经脉循行。全段为比类取象，非论脉诊。", []], "25846": ["主病", "原文提脉浮者、脉沉者，论防己主风寒温疟热气、诸痫除邪、利大小便。防己味辛主通，气平主降，根白象肺，肉黄象脾，纹黑象肾，故治肾病外抵肌肉之证。脉浮沉示病位浅深，浮为在表，沉为在里，防己通降，使邪从大小便出。", ["浮", "沉"]], "25847": ["病机", "原文“脉沉紧，面色黧黑，即病根于下之征；口舌干燥，乃病及于上之验”。沉紧主水寒内结，病根在下；水气上泛则口舌干燥。支饮心下痞坚、肠间水气腹满，皆水侵于脾，治其中。防己黑纹贯黄肉，治水侵脾，脉沉紧正合水寒内盛之机。", ["沉", "紧"]], "25848": ["病机", "原文强调「其脉浮」而「无寒热」，恐人误作外感。此浮脉非表邪，乃因大恐精却、上焦闭而气还下焦，气机乍动上下所致。气乱于内，脉应之而浮，故主病机为气机逆乱、精却气闭，与「病如狂状，妄行，独语不休」相应，属内伤而非外感。", ["浮"]], "25849": ["病机", "原文虽未明言脉象，但论「血脉中热结」与「血脉中寒滞」对举。牡丹气寒，通血脉中热结；桂枝气温，通血脉中寒滞。血不宣则气壅，阳与阴争、气与血薄而为寒热。故本条主旨为病机：热结血脉、气血壅滞，与寒热症候相应，非单纯脉象描述。", []], "25850": ["病机", "原文引「心脉满大，痫瘛筋挛；肝脉小急，痫瘛疭挛」，并释为惊则气血乱：气乱入经脉则心气满大，血乱出 血室则肝气小急。满大与小急虽殊，实相连不可分。故本条主病机：惊乱气血、心盛肝衰，与痫瘛筋挛、瘛疭相应。", ["满", "大", "小", "急"]], "25851": ["病机", "原文论白前治「胸胁逆气」「欬嗽上气」，因阴阳升降相随，升多降少则病。真阴不足无以召上阳、真阳不足不能生下阴，皆令气不降。脉沉主气机不降、病在于里，与痰热上壅、贲豚上冲之「上实下虚」相应，属后天外邪所致之病机。", ["沉"]], "25852": ["主病", "本条为桑根白皮主治条文，未识别脉名。原文列「伤中，五劳，六极，羸瘦，崩中，脉绝，补虚，益气」，又去肺中水气、唾血、热渴、水肿、腹满、胪胀、利水道。所主以虚损与水气为要，脉绝示气血虚极，故归主病，非论具体脉象。", []], "25853": ["病机", "原文设问桑根白皮主「脉绝，补虚，益气」，而後贤视其功甚狭。答以《千金》五脏之劳由逆四时之气、辗转虚实致关格生劳；六极则分列风、痹诸论，于筋、脉、肉、气、骨五极下缀五脏虚实见象。脉绝之候，正是虚劳关格、五脏精气竭绝之病机。", ["绝"]], "25854": ["病机", "原文以竹取象震卦，阳在下奋迅振动、阴在上飘零解散，喻阳出阴散、天气清明。论「欬逆上气」如阴为阳击飘飏于上，「溢筋急、恶疡」如木石相激。虽未明言脉，然「脉不为湿热所攘而拘急」点出病机：阳郁阴壅、湿热相激，与欬逆上气、筋急恶疡相应。", []], "25855": ["病机", "原文论吴茱萸所治皆「阴壅阳为患」，壅处多在中宫。上则干呕、吐涎沫、头痛、食谷欲呕，阴壅阳于上不得下达；中则吐利、手足逆冷、烦躁欲死、手足厥寒、脉细欲绝，阴壅阳于中不得上下外达。脉细欲绝正是阴寒内壅、阳气不能外达之候，主病机为阴壅阳郁。", ["细", "绝"]], "25856": ["病机", "原文虽标脉浮数，但全段主旨在于鉴别栀子所治之烦与诸方所治之烦。脉浮数提示表热或里热，然栀子所治之烦乃发汗吐下后虚烦不得眠，甚则反复颠倒、心中懊𢙐，属余热内扰胸膈。浮数之脉在此说明热邪未清而兼表，故须与白虎、黄连阿胶等证之烦相鉴别，非单纯表证之烦热。", ["浮", "数"]], "25857": ["病机", "原文论枳、朴所泄为气，上焦气分病必兼停饮宿水。脉浮而数反映上焦不化阴，氤氲之气壅遏为痰为水，故仲景治上焦多用杏仁、桔梗、葶苈、甘遂等。浮数之脉说明邪在上焦气分，水饮与热相搏，气机壅滞，非单纯表证，故不可仅以枳、朴泄气，须辨水饮痰浊之兼夹。", ["浮", "数"]], "25858": ["病机", "原文以脉浮为在表，论枳、朴与表药连属者多，与里药连属者少。脉浮提示表证方盛，里复不和，故用大柴胡汤、四逆散、枳实栀子豉汤等，恃枳、朴降泄其里而表亦和。浮脉在此说明病起由表、反复由里，气机阻于上不得升降，故须表里兼治，非单纯解表或攻里。", ["浮"]], "25859": ["其他", "原文未识别出脉名，全段考辨猪苓产地及《本经》主治，涉及松下有茯苓、竹下有雷丸、枫下有猪苓等，并论“主痎疟，解毒蛊疰、不祥”偏于鬼神感应。此段属药物考证，非脉学病机论述，故脉象要素为空，主旨归为其他，不涉主病、病机或预后。", []], "25860": ["病机", "原文未识别出脉名，论马通治血因寒而停、遇隙以溢者，引《别录》微温及仲景柏叶汤为证。血因火迫溢出者必不用性温之品，而马通性温能养，可行散因寒因伤而停之血，故吐衄、崩漏均能治之。此段虽无脉象，但病机为寒凝血停、血不循经，与脉象之涩或迟相应。", []], "25861": ["小儿", "原文引巢氏论小儿壮热，血气盛、五脏生热熏发于外，或挟伏热宿寒，不歇则变惊痫，见口眼相引、目睛上摇、手足掣纵等。脉相引而急、脉满大、脉小急，反映热盛动风、筋脉收引弛纵。急脉主筋急，大小不一示气血失调，故小儿瘛疭掣纵由热甚风动，脉象与之相应。", ["急", "大", "小"]], "25862": ["其他", "原文未识别出脉名，论露蜂房之用有会意、象形两端：一使病从外入仍从内出，治恶疽附骨痈等；一除病客于排历之处，治牙齿风虫痛、鼻中渣瘤。仲景鳖甲煎丸兼两者之用。此段属药义阐释，非脉诊病机，故脉象要素为空，主旨归为其他。", []], "25863": ["其他", "原文未识别出脉名，为蜚蝱药性主治条文，味苦微寒有毒，主逐瘀血、破下血积、坚痞症瘕、寒热，通利血脉及九窍，治女子月水不通、积聚、贼血在胸腹五脏及喉痹结塞。此段属本草主治，非脉学病机，故脉象要素为空，主旨归为其他，不涉具体脉象与症候对应。", []], "25864": ["病机", "原文论䗪虫治跌扑损伤，谓“血若凝滞，则经络不通，阴阳之用互乖，寒热洗洗生焉”，说明血瘀致经络不通、阴阳失调而寒热并作；又言“咸寒能入血輭坚”，故主心腹血积、症瘕、血闭，血和则营卫通畅、寒热自除、月事时至。全段未及脉象，故脉象要素为空。", []], "25865": ["病机", "原文以乌梅治厥治蚘，引“脉微而厥、肤冷、其人躁，无暂安时”为非所宜，脉微主阳气衰微，不能温煦四末故厥冷；躁无暂安时乃阴寒内盛、虚阳外扰之象。乌梅酸收，能从肝媾心肾，故适用于本静时烦之蚘厥，而非纯阴无阳之脏厥。", ["微"]], "25866": ["病机", "原文辨渴之虚实，以“脉浮数”为水停生热而渴之凭。浮主水气在表，数主热，水热相搏，水不化津，火反耗液，故渴而小便不利，或水入即吐、自汗出。此实渴之机，治当利水，使水化则热孤，津液自生。", ["浮", "数"]], "25867": ["病机", "原文论酒“行药势”“杀百邪恶毒气”，谓其能劫沉痼积冷，使“郁而激之，变濡迟为迅烈”。虽未明言脉象，然“濡迟”二字暗指气血郁滞、阳气不伸之脉，酒性迅烈，能行气散结，故借以行药势、攻沉痼。脉象要素据原文未出，故空。", []], "25868": ["病机", "原文辨麦之性，谓“感金气而生，其性清凉收肃；得木气而长，其用条达舒和；及火气通明，遂尔成熟”，故其功能归心，除烦止渴收汗利溲止血皆治心病。全段未及脉象，所论为药性归经与病机，故脉象要素为空。", []], "25869": ["病机", "原文论栀豉汤证，谓汗吐下后“烦躁则非实，满闷则非虚”，惟虚实之间宜发越泄降。所引脉洪、数、紧、大，皆热郁于上、气机壅滞之象，洪大为热盛，数主热，紧主郁结，故豆豉能开发上焦郁抑、宣导阴浊逗遛。", ["洪", "数", "紧", "大"]], "25870": ["病机", "原文辨阴经烦躁，引“脉微，手足厥冷，烦躁”及“脉弦迟”“脉紧”等，谓“有脉微、四逆而无满闷”知非阳经证。脉微主阳衰，弦迟紧主阴寒内盛，阴阳相逐，阳败阴追，故烦躁属阴经，不得治以豆豉。", ["微", "弦", "迟", "紧"]], "25871": ["病机", "原文论豆豉驱散阴翳、伸阳气，瓜蒂栀子引越或抑下，谓“胸中实”与“虚烦”用豆豉可并行不背。脉实热极，指邪热内结、阳气被阻之候，阴翳所在即阳气所阻，故当驱散阴翳，阳气自伸，实者引而越之。", ["实"]], "25872": ["病机", "原文以葱「死阴中得一线生阳」为喻，释通脉四逆汤、白通汤用葱之义。所举「下利圊谷，里寒外热，手足厥逆，脉微欲绝，身反不恶寒，面赤色」，脉微欲绝为阴寒内盛、阳气衰微欲脱之象；「下利，厥逆，无脉，干呕而烦」则阴寒下盛、逼阳上越。脉弱、微欲绝正示阳离根而浮于外，故主阴盛格阳、阳气将竭之危候。", ["微", "弱"]], "25873": ["其他", "此段考辨葱白名实及旋覆花汤用药，辨「葱」当为葱白而非葱管。文中引「脉革」「脉弦而大之革」为说，革脉主虚劳亡血、妇人半产漏下，弦大而革示正气虚而脉失柔和。然本段主旨在于药物考订与方证辨析，脉象仅作引证，非专论病机，故归其他。", ["革", "弦", "大"]], "25874": ["病机", "原文论薤「温中散结」为用之主脑，辛温以开、滑泽以行，故治金疮、疮败因风寒而溃败者。所引「脉沉而迟」示寒凝于里、阳气不布，正合薤辛温行散之治。沉迟为里寒之脉，与疮败由风寒、气血凝滞之机相应，故取薤温中行滞以散结。", ["沉", "迟"]], "25875": ["病机", "原文引栝蒌薤白白酒汤证「喘息，欬唾，胸背痛，短气」及「泄利、下重」，以「寸口沉迟，关上小紧数」之脉断为「阳壅于脾而不布，阴凝于肺而不宣」。沉迟主阳郁不布，关上小紧数示阴寒凝滞、气机壅塞，故用栝蒌踞脾流动、薤白宣通，以开胸痹。", ["沉", "迟", "小", "紧"]], "25876": ["其他", "此段述紫苏叶朝挺暮垂、色紫赤而枝叶空通，谓其能发汗、通血脉、通十二经关窍，治胸膈饱闷、反胃膈食、吐血下血。以「血脉疏通，则食饮自化」「通其脉络，使血有所归」立论，全段未及脉象，属药性功用与治法之论，故脉象要素为空，归其他。", []], "25877": ["其他", "原文以灶具五行、烹饪水火为喻，论灶中黄土（伏龙肝）禀土气而攒簇五行、交媾水火，故能治妇人崩中、吐血、止欬逆止血。全段借物性推药性，未涉脉象，主旨为药性功用与所主证候，故脉象要素为空，归其他。", []], "25878": ["其他", "此段为《本经》代赭石条文，载其味苦甘寒无毒，主鬼疰、贼风、蛊毒、腹中毒邪气、女子赤沃漏下、带下百病、产难、胞衣不出、堕胎、养血气、除五脏血脉中热、血痹血瘀、惊气入腹及阴痿不起，并述产地、性状、畏忌。全段为药物主治记述，未及脉象，故脉象要素为空，归其他。", []], "25879": ["病机", "原文以代赭石质色帖切化源、味苦气寒去热立论，谓源清则流洁。肝为风木藏魂，热盛则发惊骇、生贼风，魂不安则幻见鬼疰精物；带下、产难、阴痿诸候皆在肝部，血痹血瘀为肝运量不灵。最要「除五脏血脉中热」一语，为彻始彻终功能。全段论药性病机，未及脉象。", []], "25880": ["其他", "此段以江河入海则咸、煮盐取往而不反之水为喻，论水变咸成盐之理，非论脉。原文虽标'脉大'，然通篇言水液咸淡、盐之生成，与脉象主病无关，故脉象要素仅取原文所标'大'字，实非脉诊内容，属其他类论述。", ["大"]], "25881": ["其他", "此段详述附子种植、采收及乌头、附子、鬲子、天雄、天锥、侧子、漏蓝子等品类形态鉴别，纯为药物产地形态之论，未涉及脉象。原文未识别出脉名，通篇无脉诊内容，故脉象要素为空，归入其他类。", []], "25882": ["病机", "此段列举四逆散、三黄汤、越婢汤、竹叶汤加附子诸证，重点在'风水，恶风，一身悉肿，脉浮'。脉浮主表、主风，风水相搏则一身悉肿；恶风、自汗、不渴，皆卫阳不固、水气外溢之象。原文强调附子'阳振而风寒自退'，说明脉浮在此示表阳不足、风寒水湿侵侮之病机。", ["浮"]], "25883": ["病机", "此段统计《伤寒论》用附子方二十首，辨析生附子六方中三证为表病误治所致，余为少阴自病，并据白通汤用葱白推知'外皆兼有表证'。原文未识别出脉名，通篇以方证推阐附子应用之表里寒热病机，未直接论脉，故脉象要素为空。", []], "25884": ["病机", "此段论伤寒寒水之气隶太阳，有阴阳寒热传变之异，非尽以附子治之。引'脉沉微'示阳虚阴盛、昼躁夜静之干姜附子汤证；又列'脉促''脉洪大''脉沉''脉浮虚而濇'等，说明附子之用须辨寒折阴长阳消之机，脉沉微为正虚阳衰之据，脉浮虚而濇示表阳虚兼湿。", ["沉", "微", "促", "洪"]], "25885": ["病机", "此段辨析呕、吐、干呕之有声无声、有物无物，论胃热阴伤与虚寒之别，说明附子虽用于呕渴诸证，然须辨虚实有无火。原文未识别出脉名，通篇以症状辨病机，未及脉象，故脉象要素为空，归入病机类。", []], "25886": ["病机", "此段论六气相兼有连比乖错之别，风寒湿三气相合而成痹，风动寒凝湿滞致切骨之痛。原文列'脉浮虚而濇''脉沉''脉弦紧''脉数''脉微欲绝'等，示痹证脉象随邪之偏胜而异：浮虚而濇为表阳虚挟湿，沉弦紧为寒湿凝滞，数为化热，微欲绝为阳衰，皆说明附子用于痹证之病机。", ["浮", "虚", "濇", "沉"]], "25887": ["病机", "此段由天雄散附于桂枝龙骨牡蛎汤后，推绎'男子平人，脉大为劳，极虚亦为劳'六节，论阴寒精自出、精气清冷无子、阴头寒等证。脉大在此非实热，乃劳伤精气外浮之象，与极虚并列为劳病两端；天雄温阳固精，正对阳衰精冷之机，故脉大示虚劳阳浮、精关不固之病机。", ["大"]], "25888": ["病机", "原文未出脉名，专论「心痛彻背，背痛彻心」之病机。沈明宗以「邪感心包，气应外俞」「邪袭背俞，气从内走」释之，指出俞藏相连、内外之气相引而痛，即寒气客于背俞之脉、其俞注于心。故用附子、乌头温藏之寒，兼外及俞之痛，说明此痛属阴寒内盛、经俞相引，非一般血脉瘀阻。", []], "25889": ["病机", "原文引尤在泾释寒疝脉：弦紧皆阴，弦之阴从内生，紧之阴从外得。弦则卫气不行而恶寒，紧则不欲食而痹胃阳，卫阳胃阳并衰，外寒内寒交盛，阴反无畏上冲、阳反不治下伏，故「邪正相搏，即为寒疝」。此以弦紧并见说明寒邪内外合攻、阳气受困之病机，与绕脐痛、自汗、手足厥冷、阴缩等症相应。", ["弦", "紧"]], "25890": ["病机", "原文论温经汤所主妇人下利、暮即发热、少腹里急、手掌烦热、唇口干燥，其因缘瘀血在少腹。气留不行则气有余，血壅不濡则血有余，气血有余皆生火；气分之火能消水耗阴，血分之火不能消水耗阴。脉数正反映瘀血化火、血分有热之病机，故虽渴烦而不呕，仍非半夏所宜，与单纯水气不同。", ["数"]], "25891": ["病机", "原文列举厚朴生姜甘草半夏人参汤、小半夏加茯苓汤、干姜人参半夏丸、半夏厚朴汤诸方，皆含小半夏汤，而所治病迥异。小半夏汤治「中宫气水相忤，欲逆于上」，水胜于气加茯苓，气虚水逆加人参，气水并盛则结。脉缓在此提示中宫气水相忤、胃气壅滞之病机，故同一方随气水偏胜而加减，妊娠呕吐亦同此理。", ["缓"]], "25892": ["病机", "原文借大黄论心之用，谓心主血脉，若「血脉之结，瘀闭宿留」，致成症瘕积聚，变生寒热胀满，皆心用不行。脉之结正应血脉瘀闭、心用不行之病机，故取大黄大苦大寒、承制生化，荡涤瘀结，使心用得彰。此以结脉说明瘀血内结、气机阻闭，与症瘕积聚、寒热胀满相应。", ["结"]], "25893": ["病机", "原文分已化之水气与未化之饮：火著于血液津溺涕唾则结而不行，大黄可去其实有之物之火；饮未与人身浃，犹在虚处，火去而饮仍留。脉沉弦正示饮邪内停、火郁于里之病机，故大陷胸汤丸、己椒苈黄丸、大黄甘遂汤皆藉甘遂、葶苈逐饮，非独大黄所能去，说明饮结与火结治法有别。", ["沉", "弦"]], "25894": ["病机", "原文论大陷胸汤先煎大黄、后入他物，因结胸热实、按之石鞕、脉沉紧、从心下至少腹鞕满痛不可近，是上下皆痹，恐峻剂暂通复閟，故使大黄善后。脉沉紧示热实结聚、上下痹阻之病机；又茵陈蒿汤证湿热不越、瘀热在里，脉浮示病势偏外，故内急外缓，用药次第不同。", ["沉", "紧", "浮"]], "25895": ["病机", "原文辨桔梗主喉痛仍是治肺非治肾，肾家邪热循经上攻，肺不任受而相争。所引「欬而胸满，振寒，脉数，咽干，不渴，时出浊唾腥臭，久久吐脓如米粥」，脉数示肺窍不利、气不宣泄，气停饮停，饮停即热生，气血为之溃腐。故以桔梗开肺窍、甘草泻火，说明数脉主热郁肺壅、腐化脓血之病机。", ["数"]], "25896": ["主病", "本段为旋覆花本草主治，未涉脉象。所述“主结气，胁下满，惊悸，除水，去五藏间寒热，补中，下气”及“消胸上痰结，唾如胶漆，心胁痰水，膀胱留饮”等，皆属痰饮结气、水气内停之病机。药性咸甘温微冷利，能通血脉、下气行水，故所主诸症与痰水结聚、气机壅滞相应，非凭脉断病。", []], "25897": ["病机", "本段论藜芦涌吐风痰，未及脉象。原文“手指臂肿动，其人身体𥆧𥆧”点明“肿则为湿，动则为风”，谓风与痰壅于肺部，流注手阳明、太阴经络，故见跃动昭彰。吐去风痰则肺安络通，诸动自除。此以症测机，非以脉定治，然风痰上壅、经络应动之病机贯穿全段。", []], "25898": ["误治", "原文“伤寒，脉浮，医以火迫劫之，亡阳，必惊狂，起卧不安”。脉浮本为邪在表，医反以火迫劫，致汗出亡阳，心神浮越，故惊狂不安。诸家释加蜀漆之义，或谓泄热、散火、通阳、吐瘀，作者独取“吐腐去结”为近理。此段脉浮为表证之常，火逆亡阳为误治之变，脉象与坏病并见。", ["浮"]], "25899": ["其他", "本段辨析白敛命名与药性，未涉脉象。原文谓“结气，不可敛而散也；热，不可敛而除也；带下赤白，不可敛而止也”，强调白敛所治非单纯收敛可解，当从肺朝百脉、秋令容平之义求之。全段以药论药，属本草理论阐发，不直接对应脉象病机。", []], "25900": ["其他", "本段解析薯蓣丸组方，未及脉象。原文“虚劳，诸不足”为君药所主，“风气百疾”以桂枝、大豆黄卷、防风、柴胡分走皮腠、肌肉、筋骨、肠胃，而“结于血脉间者，不能不用白敛”。白敛任最轻、职最下，故列方末。全段论虚劳兼风、结在血脉之病机与用药层次，非脉诊内容。", []], "25901": ["病机", "原文“欬而脉沉者，泽漆汤主之”，又对比“厚朴麻黄汤治欬而脉浮”。脉浮为水气偏表，仍从青龙加减以汗解；脉沉则水气内结，不得与五苓、十枣同科，故用泽漆为君，使水气还归于肾，先煎久煎以缓厚其力。此以脉之浮沉分水气表里，定欬病治法，脉象直接主病机层次。", ["沉", "浮"]], "25902": ["病机", "原文引《金匮》“少阴脉，滑而数，阴中蚀疮烂者，以此洗之”，并释“脉滑数而疮烂，自是湿热为病”。滑主湿浊，数主热，湿热下注前阴，腐蚀生疮，故见疮烂。狼牙味苦气寒，能化湿胜热，故取以洗治。此段以脉滑数直接点明湿热生虫、蚀疮腐烂之病机。", ["滑", "数"]], "25903": ["病机", "原文引《金匮》“温疟者，其脉如平，身无寒，但热，骨节疼烦，时呕”，又言“脉不平”“脉躁疾”。脉如平者，邪伏骨髓，未发时脉若常人；及其发也，阳热亢盛，脉转躁疾。此段辨温疟脉象之常与变，以脉如平说明伏邪未动，以躁疾说明热发之候，脉象与寒热骨节烦疼相应。", ["平", "躁", "疾"]], "25904": ["病机", "原文论连翘主治，言“热结在中”为寒热、鼠瘘、瘰疬之因，并谓“其本在脏，其末在颈腋间”，蛊毒“沉于脏”，瘿瘤痈肿“浮于脉”，皆因热结为形证。虽未出脉名，然“沉”“浮”提示病位深浅，热结在内则脉沉，热结外浮则脉浮，病机为热邪结聚，随部位不同而现沉浮之象。", []], "25905": ["病机", "原文以连翘形气论鼠瘘瘰疬、痈肿恶疮之病机，谓“溽暑之候，诸气懈弛，血脉偾涌”，懈弛者多颠踬，偾涌者易壅淤，气多于血之候生颈腋，血多于气之候生背腹，瘿瘤亦因气遭炎𭶟而颠踬壅淤。虽未言脉，然“血脉偾涌”暗示脉象涌盛，病机为气血壅淤、寒热结聚。", []], "25906": ["主病", "巴豆辛温大毒，主伤寒温疟寒热，破症瘕结聚坚积留饮痰癖，大腹水胀，荡练五脏六腑，开通闭塞，利水谷道。所主皆阴寒固结、闭塞不通之病，脉当见沉紧或沉实，以寒实内结故也。原文虽未出脉，然“破症瘕、结聚、坚积”提示脉象沉牢紧实，主寒实闭结之病机。", []], "25907": ["主病", "蜀椒辛温大热，主邪气欬逆，温中，逐骨节皮肤死肌，寒湿痹痛，下气，除六腑寒冷，伤寒温疟，心腹留饮宿食，肠澼下痢，散风邪瘕结水肿。所主皆寒湿阴邪为患，脉当见沉迟或紧，以寒湿内盛故也。原文虽未出脉，然“温中”“除六腑寒冷”提示脉象沉迟紧，主寒湿痹阻之病机。", []], "25908": ["病机", "原文论乌梅丸证“静而时烦，得食而呕”、大建中汤证“痛，呕不能饮食，腹中寒，上冲皮起，出见有头足”，析为寒与火交战于中，逆而上行。椒能就火致金，使火归下，返动为静。虽未言脉，然“上冲皮起”暗示脉象弦紧而动，病机为寒热错杂、火逆不降。", []], "25909": ["主病", "原文引《肘后》“伤寒及时气温病，头痛，壮热，脉大”，用生梓木白皮汤解散。脉大主热盛，壮热头痛为外热壅盛之象，故取梓皮苦寒助解表，变赤色为无色。脉大在此主热邪充斥内外，病机为热盛于表，与壮热、头痛相应。", ["大"]], "25910": ["病机", "原文论胆为木中之水，可泄火气之昌炽，定水气之凭陵，水火相济之源具于此。伤寒热渴者，土中之火昌獗；厥逆无脉，干呕烦者，水见溃决与火相背。虽未出脉名，然“厥逆无脉”提示脉伏不出，病机为水火不济、火达于水而水流更。", []], "25911": ["病机", "原文论阴吹证“谷气之实”，非脾胃之虚，用猪膏发煎。引“脉迟微烦”未见于本段，然迟微之脉主虚寒，微烦为虚阳上扰。谷气壅遏，脾胃传化失职，脉道不利故迟微，病机为谷气壅遏、脾胃气机不畅，与阴吹、烦相应。", ["迟", "微"]], "25912": ["其他", "本段虽标脉浮而迟，实为辨析猪肤药用之文，非论脉主病。原文列举方中行、喻嘉言、张隐庵诸家对猪肤之异说，或谓润燥、或谓除客热、或谓入肾滋阴，末以「清利肥甘之物，滋润或有之，通利或有之」作结。脉浮迟在此仅作段落标识，未与病机症候相联，故不可据以断证。", ["浮", "迟"]], "25913": ["病机", "原文以「脉道泣涩」言气血泣涩不畅，故蜣螂所主与承气有别。承气证见「汗出，小便自利，转失气」，为肠胃实滞；蜣螂所治则痓之胸满、口噤、脚挛急、𬹼齿，及小儿惊痫、瘛疭、腹胀、寒热，属久暂不同、正气盛衰有异。脉道泣涩正示气血痹阻、宿滞内结而正气已损，故不可与承气混称。", ["涩"]], "25914": ["病机", "引《甲乙经》「足厥阴脉动，喜怒不时，发颓疝，遗溺，癃」，说明气癃之成在于情志乍喜乍怒，致肝脉气壅、脉有所停，阻碍水道下行。足厥阴脉过阴器、抵少腹，气壅则水道不利。鼠妇生幽隐湿处，主气癃，正取其生气在秘闷中，能通地气以利水道，兼治妇人月闭、血瘕、痫痓、寒热。", ["动"]], "25915": ["病机", "原文未出脉名，以「浮假而痛，推移则动」状疝瘕之候。病在男子多寒湿间于气分；在妇人则波及血分，因经候来盛可乘势除邪，去者过多则环阴血道空虚，所袭之邪奠居为梗。女子多郁、经事不畅、火载血升，血去不及而环阴之血无从空虚，故疝瘕独标妇人。此段辨男女血气虚实之异。", []], "25916": ["其他", "本段辨杏桃仁之性，非论脉。卢子繇谓「杏为心果，心主脉」「桃为肺果，肺主毛」，作者以为果与仁终应有异，且《本经》主治、仲景用法皆不谓杏主脉、桃主毛。引《素问·五常政》《藏气法时论》「五谷为养，五果为助」，明果食乃为平人察藏气偏衰、裒多益寡而设，非为治病立论，故不可据以定脉证。", []], "25917": ["病机", "原文标脉微而沉，以桃仁所主血闭、瘕、邪气皆内证，脉微沉正合病在里。举仲景书及《千金》用桃仁九方，同用大黄、芒硝、蝱虫、水蛭者，可知附于里证；其外候有三：表证未罢、少腹有故、身中甲错。桃仁承气汤证「太阳病不解」、抵当汤证「表证仍在」，皆示瘀热内结而脉见微沉，故主内证血闭。", ["微", "沉"]], "25918": ["病机", "原文以「脉浮虽愈，枯樯难泽」言麻仁丸证若误用小承气汤，虽表脉浮已解，而津枯难复，延于下后。杏仁旁通直降兼备，合麻桂播其先声，协硝黄壮其后劲。大陷胸丸证猛于大陷胸汤证，麻仁丸证劣于小承气汤证，故大陷胸汤不必杏仁、葶苈而可通，小承气不必麻仁、杏仁、芍药乃能降，示用药须审证之轻重。", ["浮"]], "25919": ["病机", "本段未出脉名，论大黄䗪虫丸桃仁、杏仁并用之理。原文谓「仁，生气之钟于极内者也」，桃肉白骨赤、杏肉黄赤骨白，故桃仁入血分而通气，杏仁入气分而通血脉。干血之成，必气血并坚癖，若气煦血濡有一件足，则不致血干阻气、虚极羸瘦、腹满不能食。丸中泽血通血、搜血消血诸物，赖桃仁入阻血中而奏效。", []], "25920": ["其他", "本段纯述钟乳石之生成形态与品质鉴别，未涉脉象。原文以「石脉涌起处」喻乳状下垂，言其「滴且凝而成」，以色洁白微红、碎如爪甲、中如雁齿、光明者为善，属药物性状描述，与脉诊病机无关，故不主病机。", []], "25921": ["病机", "本段以乳与泉「得阴化阳」「得阳化阴」之性体差异，类比人身「似溺似津行阳道」「似液似精行阴道」，说明钟乳气温质黏、中空通明，故能「明目益精、通百节、利九窍、下乳汁」，并因「石属金而性下行」主欬逆上气。全段借药性推演人身精气输灌、五脏安和之理，非论脉象。", []], "25922": ["病机", "本段以兔之「狡狯窜疾」、阳伏于踵为喻，说明菟丝「为四月盛阳所迫，屈蠖之阴并从阳化」，如丝如缕宣布无方；至七月感初阴结为实，「稠黏丝缕屈曲蟠绕」，体现「阴者阳之种，遇阳辄化而宣布；阳者阴之用，遇阴辄屈而归根」，故能「联属浮越无根之气」，属药性病机推演，未及脉象。", []], "25923": ["病机", "本段以「火是气之灵，水是气之粹」立论，言「气乖则水拂于火为水气」，水气盛则精明衰，故益精明正以除水气。又谓茺蔚子「得水之余而会神聚精于火」，茎得木之条达，气盛则血顺流行，气衰则血违留滞于节而发瘾疹，去瘾疹正以行气血。全段阐药性气血水火之理，非脉诊。", []], "25924": ["病机", "本段论龙胆「至苦极寒」，却「不泄不降」而「自内达外」，主骨间寒热、惊痫、续绝伤、安五脏。其理在「苦本主发」，龙胆苦之至而兼濇，濇者至苦中有至酸，酸禀春之发育、苦禀夏之畅达，相联属则寒「非极泄而为极入」，味阴气阳，阳唱阴随，故畅发不能违深入。属药性病机，未涉脉象。", []], "25925": ["病机", "原文仅以「脉之数也」标目，借「阳极变阴，发转为敛」论天麻茎实之性：赤茎直上、支节不生，取义「往而不返」；竟其所至则「转阳为阴」，生六棱之实仍入茎中「归根复命」，是往而能返。全段以循环之数、水火相遭为喻，说明阴阳转化、敛藏归根之理，脉数仅作引端，非论数脉主病。", ["数"]], "25926": ["主病", "本段列述五劳七伤之候：阴衰、精清、精少、阴消、囊下湿、腰胁苦痛、膝厥痛冷、骨蒸、远视泪出、口干、腹中鸣、小便淋沥、茎中痛或精自出；又分志劳、思劳、心劳、忧劳、疲劳，及肝伤善梦、心伤善忘、脾伤善饮、肺伤善痿、肾伤善唾、骨伤善饥、脉伤善嗽。全段主论虚劳诸症病机，未及脉象。", []], "25927": ["病机", "本段辨续断与大蓟「根形相似」而治血有别：《别录》于续断所主之血曰「漏」，对断而言，是受伤而漏泄，属器；于大蓟所主之血曰「沃」，对不断而言，是沃于此而渗出，属土。欲土不易渗必使之厚，欲器不易伤必使之坚，甘以厚土、苦以坚里，故二物同工异调。属药性病机，未涉脉象。", []], "25928": ["病机", "原文以「心腹邪气」统摄「肠鸣幽幽如走水、寒热积聚、症瘕、烦满」，说明诸证皆由心腹邪气内结、气机壅滞所致。肠鸣如走水为气滞水停，寒热积聚、症瘕为邪气聚结成形，烦满为气逆于上。作者强调诸证须系于心腹邪气方可用丹薓，反证其病机核心在邪气内踞心腹，非泛泛养血所宜。", []], "25929": ["病机", "原文以「脉络结濇」言血脉壅滞，营气痹而不与卫谐，卫失营欢则捍御弛纵。外有寒湿风乘虚外据，内有湿热蕴结不得驱，遂成痹、疸。结濇示血行不畅、营卫失和，故桂枝附子汤等温通、茵陈五苓散等分利皆从气化枢机立法，补中须辨气化与血脉之异。", ["结", "涩"]], "25930": ["主病", "引《金匮》「诸浮数脉，应当发热，而反洒淅恶寒，若有痛处，当发其痈」。浮为邪在表，数为热盛，脉浮数而反恶寒、有痛处，是热毒壅聚营血、将发痈肿之候。原文辨寒热身肿非尽风胀，以痛肿互文见义，说明浮数脉主痈肿初起、热毒聚结之病机。", ["浮", "数"]], "25931": ["病机", "原文论枸杞「以金成木」主五内邪气，「从火制水」主热中消渴，又及周痹、风湿。周痹在血脉之中，随脉上下，由风寒湿客于分肉之间，迫切为沫，沫得寒聚而排分肉致痛。此段无脉名，主旨阐发药性所对病机：邪客血脉分肉、沫聚分裂致痹痛，属风寒湿杂至之病机。", []], "25932": ["病机", "引《素问·脉要精微论》「诊得心脉而急，此名心疝」，王注心为牡藏其气应阳，今脉反寒故为疝，是阴遏阳之病机。脉急主寒主痛，心脉急则寒邪内遏心阳，小肠为之使，故少腹有形。又引〈痿论〉肺热叶焦生痿躄，为阳劫阴。五加皮兼主阴遏阳、阳劫阴两端。", ["急"]], "25933": ["病机", "原文论筋骨间寒热而为湿痹拘挛，邪聚关节。蔓荆实柔条对节似经脉周行，开花成簇似关节屈伸泄泽，味苦气微寒，苦主发、寒主泄，故能行散关节间寒热湿邪。邪去则精神形质复常，目明齿坚。此段无脉名，主旨为湿痹拘挛邪聚关节、当行散之病机。", []], "25934": ["其他", "原文借沉香坚致沉水、筋节刚劲韧密，论岭表气候夜寒昼热、湿日相蒸，朽烂与坚韧「两不相及，亦两不相顾」。此段无脉象，亦不直接言病机，乃以物性喻天地气候之异，属药性物理论述，故归其他，不涉脉诊病机。", []], "25935": ["病机", "原文论麝食香草毒物而结香，香能散败生气，草不生、花萎谢、瓜果立枯，然麝形骸柴瘠而峻健自如。指出其香「能散附形酝酿之气，不能散呼吸氤氲之气」，附形之气为物所自赘，呼吸之气吐纳天地。此段无脉名，以物性阐发散气之界限，属药性病机之论。", []], "25936": ["病机", "原文以莲藕偶奇喻阴阳互根，提出“阴根于阳，阳源于阴”，并联系人身坎离水火，强调“取坎填离，以离济坎”使两端之用和谐，受益在中，故主“补中，养神”。虽未言脉，但所论阴阳升降、水土相交，实为脉象阴阳升降之基，病机在于阴阳不交、升降失司。", []], "25937": ["病机", "原文辨周痹与风湿，引《灵枢》“风寒湿气客于外分肉之间，迫切而为沫，沫得寒则聚，聚则排分肉而分裂”，说明周痹病机为风寒湿客于分肉，沫聚分裂，血脉不通。脉陷空者，提示邪客日久，气血虚陷，脉道不充，故主周痹肢节痛、不可持物、洗洗酸削。", ["空"]], "25938": ["病机", "原文论白芷入阳明、冲脉，行阳去秽，以水之流行喻气血运行，强调“性洁者，喜行清道”。脉之清和，指脉象清净和缓，无浊秽壅滞，反映阳明冲脉气血清纯、运行无阻。若秽浊芜翳，则脉失清和。故本段以清和之脉示气血洁净、升降有序之病机。", ["清", "和"]], "25939": ["病机", "原文以赤黑喻水火气血，谓“有色者，系火胎水中；无色者，乃水交于火”，强调火盛则血赤、火衰则血淡。脉浮紧数弦，为火盛气逆、水不交火之象：浮数主火，紧弦主水寒相搏。火盛血赤而气无色，故脉见浮紧数弦，主水火不交、气血失和之病机。", ["浮", "紧", "数", "弦"]], "25940": ["病机", "原文论百部治咳嗽上气，谓其根黄白似肺致脾气，能于肺朝百脉时引精气输于皮毛，使“毛脉合精，行气于府”，气归权衡而咳止。虽未言脉，但所论肺朝百脉、毛脉合精，实关脉之生成与运行。病机为久咳伤肺、脾精不输，脉道失养，故以百部引精输布。", []], "25941": ["病机", "原文论血结气违、血脱气濇，病在血而咎在血中之气与大气相混。清纯营气混于悍气则上溢下陷为吐衄便血；悍气混于清气则滞结为恶血积血、血淋尿血。虽未言脉，但血结气违则脉道不利，血脱气濇则脉涩不充。郁金行血中之气，故能治之。", []], "25942": ["病机", "原文以莎草根叶繁盛喻人身胸中，缕析之根喻萦洄脏腑之脉络，条秩之叶喻周浃一身之经脉。内行之气不缕析潆回、外行之气不条秩周浃，则胸中为热，充气于皮毛而热已。虽未言脉，但脉络经脉之气不达，则脉道壅滞，病机为气聚于内不达、气馁于外不继。", []], "25943": ["病机", "原文释霍为护、为盛长、为香土之臭，论藿香得火土发舒畅茂、敦厚化育，能消化恶毒阴厉，为宣导良剂，剿除乱略以扶危定倾。脉之霍乱，指脉象卒然混乱无序，如霍乱之病挥霍撩乱。其病机为恶毒阴厉乘虚内扰，气血逆乱，脉道失序，故主霍乱吐泻、挥霍撩乱之候。", ["霍", "乱"]], "25944": ["病机", "原文以「脉谐畅和调」为喻，论冲任二脉蓄溢之常。血海满则下出，赖肺朝诸脉、心摄诸脉以布政令、定约束；若朝而不能布政令，归而不能定约束，则冲失其容、任失其妊，血不上朝不归往，遂成「巵无当」之漏。此段借木耳止漏除症、琥珀利水消瘀之性，说明血行失常之病机在冲任失约，非单言脉象。", []], "25945": ["病机", "原文谓「脉气谐畅，经隧流通」，则所忆既端、所存胡妄，五脏遂气摄于液、志凝于精，如金城汤池不可攻，邪气不能干。此段以龙眼肉甘厚之性，论安志厌食之由在脉气谐畅、经隧流通；若脉气不畅，则志不安、谷气受抑，邪气乃干。主旨为病机，非具体脉象。", []], "25946": ["病机", "原文言「血脉不续而腰脊痛」「血脉留阻而少腹急痛」，皆因藏气不咸、无以蒸腾精血，或留热、或渗泄，致血行之路不通。鹿角性温，能引未败之血隶原统之经而上萦，通其流行之路，则留者行、陷者举，病可已。此段论血瘀留阻之病机及温通治法，脉象仅为症状描述。", []], "25947": ["病机", "原文借魏培之「犀角是倒大黄」之戏语，论升麻、犀角皆能举外寒内热或内外皆热之毒上行而散，犹大黄之下热毒。其理在金贯水中、水从木升，发越金气而归功于畅水；犀角黑质黄花、白星一线直透，象水从金达、土金相生。此段阐发药性升降之病机，非论脉象。", []], "25948": ["病机", "原文论木瓜气温味酸甘、质津润，假木火之盛燄行血液之柔滋，用阳摄阴使阴不得澌尽，以阴和阳令阳迫逐流亡。湿痹之成，由阳以阴痹而穷、阴以阳穷而痹，阴阳相胶相轧；惟摄阴从阳、宣阳布阴，则邪气化而湿痹开。此段主论湿痹阴阳相轧之病机与木瓜功用，非脉象。", []], "25949": ["病机", "原文比较黑大豆与穞豆：大豆箕鞕为梗，沉著行水道；穞豆苗柔成蔓，轻扬行血脉。阴气被于土、土气鼓夫阴，输肺行三焦致通降，虽借资于火而实忌火盛，火盛则耗阴碍其流；灌溉于心、盘旋经隧者最喜凉和，然宜阳有以煦之，无阳则如寒令之水消而停。此段论水血运行之病机。", []], "25950": ["病机", "原文引《灵枢·邪客》伯高论半夏汤「补其不足，泻其有余，调其虚实而去其邪，阴阳已通，其卧立至」。以两军相对为喻：邪客必乘其虚，气不能入必畏其实，欲战未能、欲和不果，高垒深沟、胜负未分；得通问相谕，则铲垒湮沟、通盟释嫌。半夏生于阳长之会、成于阴生之交，能使正气自阳入阴，此段论不寐之病机在阴阳不通。", []], "25951": ["病机", "原文以种韭「根性上跳」「内生不向外长」为喻，论韭根养发而茎叶除胃中热利、归心而安五脏、子止梦泄精溺白。然归心未必安五脏，止梦泄未必止溺白，以脏自脏、腑自腑，溺道精道各别。脉极虚芤迟者，虚为正气不足，芤为血虚失守，迟为阳运无力，正合精血下泄、脏气失养之病机。", ["虚", "芤", "迟"]], "25952": ["病机", "原文言瘰疬瘘病由寒暑不调、饮食乖节致气血壅结、毒流经脉，血脉结聚，寒热相交，久则成脓溃漏。脉结聚正应气血壅结、毒留脉中不去之机，故主瘰疬鼠瘘，症见颈腋皮间结核如梅李枣核、两两相连、时发寒热，本在脏而末出颈腋。", ["结"]], "25953": ["病机", "此段论霍乱与水肿通塞迥殊而同理，皆隶三焦水道。霍乱为水之溃决，水肿为水之停涨，水道不通则汪洋无制。引《经脉别论》水精四布、五经并行，说明脾肺膀胱与三焦共司水道。脉象原文未及，故不取脉，主旨在水道不通之病机而非脉诊。", []], "25954": ["病机", "原文借何首乌夜合昼疏之性，论气血结者以开为功、气血劣者以阖为功，开阖尽其神则气血生化不竭。所主瘰疬痈肿、头面风疮属经脉壅结，益气血黑髭鬓属形器损，病虽迥异而同归开阖之机。段中未言脉象，故脉要素为空。", []], "25955": ["病机", "原文辨析伤破在皮肉、伤断在筋脉、伤折在骨，伤既在骨则远望草木滋凝无益。惟骨碎补寸寸折之皆生、处处有汁，无藉根株之系，不致血液之漏，故主破血止血补伤折。全段论药性主治与伤损层次，未涉脉象，故脉要素为空。", []], "25956": ["病机", "原文以“节”论白附子之旨，节为阴阳之限、用阳布阴，其力在下者厚、愈上愈微，故主心痛血痹，兼行面上百病药势。血痹由尊荣人骨弱肌肤盛、疲劳汗出被微风，始病血脉渐应于心而痛，需白附子布散血脉中阴邪。段中未及脉象。", []], "25957": ["病机", "引《大奇论》心脉满大、肝脉小急皆主痫瘛筋挛，又肝脉骛暴主惊骇。盛满偏于一处则他处不足，弦急偏于一处则他处纵弛，故口眼相引、手足掣纵应弦急，背脊强直、颈项反折应盛满，皆气血忽被牵掣、他处不相流通之机，巢氏谓热实在内、心神不定发惊成痫。", ["满", "大", "小", "急"]], "25958": ["病机", "原文论五邪为五脏偏驳不调之气，骤遇不习见闻则惊啼，气并于肺而肺满，外因泣出而虚，故伤责于悲而实由于气并。鲮鲤甲能穿金之未纯者以治之。又及瘘由饮食之毒入腑脏、行于所主之脉、稽留脉内不去，壅溃成疮。段中未出脉象。", []], "25959": ["病机", "原文以瓠之湿干坚瓤为喻，言蔕蔓抽吮运量津气以成长成坚。在人之病，汤饮入而汪洋不流、滋腻入而黏著不化，致津气壅滞。脉沉正应津气内停、水饮不化之机，主汤饮滋腻停滞、津不流布之候，与汪洋不流、黏著不化相应。", ["沉"]], "25960": ["其他", "此段引班固《艺文志》分医经、经方二家，言医经「原人血脉经络骨髓阴阳表里，以起百病之本，死生之分」，乃泛论医经宗旨，非专论脉象。文中虽及「血脉」，然系指医经所原之总体，非具体脉诊。故脉象要素为空，主旨属医史源流之其他类。", []], "25961": ["病机", "此段论麻黄功用归著在「鼓发阳气，冲散阴邪」，能治束缚难伸之风、蔽锢盛热之寒等，而不能治筋骨懈弛之风、阳气漏泄之寒。末引「太阳病，项背强几几，汗出恶风」桂枝汤证，脉浮为太阳表证之象，示邪在肌表，营卫不和。全段以药性推病机，脉浮仅作引证，非专论脉。", ["浮"]], "25962": ["其他", "此段为菊花单味药的主治记载，言其「平。主四肢游风，利血脉」，属本草主治条文，未涉及脉象描述。文中「利血脉」指药效通利血脉，非脉诊之脉。故脉象要素为空，主旨归入其他类。", []], "25963": ["主病", "此段载白花蛇「温。主中风，湿痹不仁，筋脉拘急」。脉拘急即筋脉紧急之象，因风邪湿邪痹阻经络，气血不畅，筋脉失养而拘挛紧急。白花蛇性温，能祛风通络、除湿舒筋，故主此证。脉拘急与中风、湿痹、不仁相应，示邪阻筋脉之病机。", ["急"]], "25964": ["病机", "此段论头面风虽病位在上，其所以然却在下，引《灵枢》「十二经脉三百六十五络，其血气皆上于面而走空窍」，说明头面风之病机根于下焦气血上逆。文中未及具体脉象，故脉象要素为空。主旨阐发头面风在上之病机实源于下，归入病机类。", []], "25965": ["病机", "此段论中风脚弱之候，与头面风相对照。既曰「弱」，则筋弛而不束骨，似痿而非拘急挛缩。引《生气通天论》「湿热不攘，大筋緛短，小筋弛长」及《痿论》「心气热则下脉厥而上，上则下脉虚，虚则生脉痿」，脉虚为下脉虚衰之象，示湿热伤筋、气血不济之病机。", ["虚"]], "25966": ["病机", "此段辨析痹之训为冷疾、湿病，而风非冷湿所化。引《痹论》「风寒湿三气杂至，合而成痹」，说明痹病由三气兼受，以「杂至」言错杂而至，以「胜」言其气较盛。文中以缓急、淫淫周痹为风胜，拘挛、历节、偏痹为湿胜，痛为寒胜，未及具体脉象，故脉象要素为空，主旨归病机。", []], "25967": ["病机", "此段集仲景、巢氏论风瘙痒证。脉微示阳气不足，面反有热色为邪郁未解；脉迟而缓，迟则为寒，缓则为虚，营缓亡血，卫缓中风，邪中经则身痒瘾疹；脉浮而洪，浮为风，洪为气，风气相搏，风强则瘾疹身痒，气强则为水。诸脉共示营卫有邪、寒热相折之病机。", ["微", "迟", "缓", "浮"]], "25968": ["病机", "本段论中恶与贼风皆卒发之病，中恶由口鼻入胸腹而隔人气血，故见卒然心腹刺痛、闷乱欲死；其著于阴阳气血不同，或呕吐、或下痢、或腹胀霍乱。原文未出脉名，只言病机在阴阳偏驳、气血隔阻，治以苦辛温烈，间以推荡开其闭。脉象无从取，故脉素为空。", []], "25969": ["主病", "本段列举下利诸证，引《伤寒论》少阴病脉微下利、下利清谷里寒外热，及脉沉弦、脉大、脉微弱数、脉弱、脉数等。脉微主阳气衰微，沉弦主里寒水气，数主热或虚阳外越，大主邪盛。诸脉随证而异，示下利有寒热虚实之别，当据脉辨少阴、太阴、厥阴及合病之机。", ["微", "沉", "弦", "数"]], "25970": ["病机", "本段以《千金方》利属脾脏立论，谓利为水土之不胶黏，引《素问·经脉别论》食气入胃、饮入于胃、脾气散精、通调水道诸文，说明水谷精微输布失常则成利。原文未出脉象，主旨在水土不黏、脾失散精、水道不调之病机，非论脉，故脉素为空。", []], "25971": ["误治", "本段论下药不可浪投，举仲景不可下诸条：汗出多、小便多、不能食、脉缓弱、咽中闭塞、诸外实、脉浮大、病欲吐等皆不可下。脉缓弱为脾胃气虚，下之更伤中气；脉浮大为邪在表、气机上浮，下之则引邪入里。原文以脉缓弱、脉浮大戒下，正申误下之害。", ["缓", "弱", "浮", "大"]], "25972": ["病机", "本段辨淋之病机，巢氏谓肾虚膀胱热乃为淋，热则津液溲，便数且涩、淋沥不宣；又引膀胱气化则能出，与泰西肾热湿、膀胱冷燥之说相参。原文未出脉象，主旨在水道气化不利、肾虚膀胱热之病机，故脉素为空，不可强补脉名。", []], "25973": ["病机", "本段引《素问》《灵枢》人迎脉大四倍曰格、寸口脉大四倍曰关、并大曰关格，又引《难经》溢覆及阳脉不和、阴脉不和之说。脉大为阴阳偏盛、气血留滞之象，浮为气虚，伏而濇为气血郁滞。关格之脉羸不能极天地之精则死，示阴阳离决之危候。", ["大", "浮", "伏", "濇"]], "25974": ["病机", "本段辨溺血与血淋之别，血淋必溺濇，溺血必溺自如；引巢氏心主血、劳甚散失常经溢渗入胞成血淋，及《痿论》悲哀太过、胞络绝、阳气内动、心下崩、数溲血。原文未出脉象，主旨在以阳搏阴、热伤血络之病机，故脉素为空。", []], "25975": ["病机", "本段论消渴，谓石药、肥甘、酒、盐皆致消渴，非仅性热助火，更在盐得水则行不留、遇火则结不散，致水难制火；又引《难经》肾主五液布五脏，肾气不周于胸中则津润不足。原文未出脉象，主旨在水火失调、肾气不布之病机，故脉素为空。", []], "25976": ["病机", "原文以「寸口脉浮而迟」论消渴，浮为虚，迟为劳，虚则卫气不足，劳则营气竭，说明营卫失枢、阳气不营于外而直升直降于内，故内热炽盛藉水自救，外则水液直溜而下。脉浮而迟非外寒，乃阳气不营之象，主消渴病机，与营卫不足、水液代谢失常相应。", ["浮", "迟", "虚", "数"]], "25977": ["其他", "此段论黄疸治法，列举诸方，以茵陈蒿汤为正剂，并述黄疸主候与正因。原文仅提「脉迟」而未展开，结合上下文，迟脉在此非主病机，而是作为黄疸兼证之一提及，说明黄疸本于湿热客于脾胃，兼有他证时脉象可见迟，但段中主旨在于方证鉴别，非专论脉。", ["迟"]], "25978": ["病机", "原文引「阳明中风，脉弦浮大而短气」，腹都满，胁下及心痛，久按之气不通，鼻干不得汗，嗜卧，一身及面目悉黄，小便难，有潮热，时时哕，耳前后肿。脉弦浮大主阳明中风、湿热郁蒸、气机壅滞，故见黄疸、腹满、短气等症，说明黄证根于湿热抟聚脾胃，渗泄不畅而蒸郁成黄。", ["弦", "浮", "大"]], "25979": ["病机", "原文辨黄汗与历节同源异派，皆因「汗出入水中，如水伤心」，故黄汗脉自沉，历节脉沉弱。沉主水气内郁，弱主血脉不利，心火燔燎必著他物，汗沾衣如檗汁，说明黄汗病在血脉，与黄病属脾家肌肉者不同，脉沉弱反映水湿伤及心脉之病机。", ["沉", "弱"]], "25980": ["病机", "原文论上气欬嗽与肺痿、肺痈、肺胀、支饮、风水之辨析，提及「脉数虚者」与「脉动」，数虚主肺痿津伤虚热，动脉主气机躁动不安，说明上气欬嗽诸证须细究脉象以别病机，数虚为虚热灼肺，动为邪正相搏，皆与肺系病证相应。", ["数", "虚", "动"]], "25981": ["病机", "此段未识别脉名，纯论欬论之义，述肺痿、肺痈、支饮、肺胀、风水皆聚于胃关于肺，本于五脏之邪传六腑，初伤在气久乃涉血，甚则呕逆吐蚘、遗矢遗溺，再变而为膈噎胃反、下利洞泄、霍乱转筋。主旨阐发脏传腑之病机演变，非论脉象，故脉象要素为空。", []], "25982": ["病机", "原文辨吐与呕之阴阳虚实，谓「呕而脉弱」为虚寒自致之呕，「脉数」则属热实之呕。弱脉主虚寒，数脉主热实，说明呕证有虚实寒热之异，脉弱为虚寒呕逆，脉数为热实呕逆，吐属虚属阴，呕属实属阳，脉象为辨呕证虚实之关键。", ["弱", "数"]], "25983": ["病机", "此段未识别脉名，论干呕与停饮而吐相反对，干呕有火却系虚火，停饮有水全非实水，列举白通汤、通脉四逆汤、吴茱萸汤、半夏干姜散、橘皮汤、五苓散、猪苓汤等方证，说明干呕多因虚火或水饮上逆，病机在胃气上逆、水火失调，非论脉象，故脉象要素为空。", []], "25984": ["病机", "原文以脉紧弦论心腹冷痛，紧主寒，弦主痛，寒凝气机则痛。虽篇中列黄芩治胃中热、小腹绞痛，然此段重在辨析冷痛与热痛之异，指出寒热可错杂，脉紧弦为寒痛之象，与宿食腹胀满、胸痹痛相类，故主寒凝气滞之病机。", ["紧", "弦"]], "25985": ["病机", "寸口脉阴阳俱紧，紧为寒束，阴阳俱紧则表里皆寒；脉微而厥，微为阳衰，厥为阴阳气不相顺接。原文以烦为从阴出阳之候，兼躁则自阳入阴，故脉紧主寒闭，微主阳微，二者并见示阴阳相争、寒盛阳衰之病机，烦与躁之轻重即由此判。", ["紧", "微"]], "25986": ["病机", "原文论积聚症瘕，脉紧为邪气牢结之象。紧脉主寒主痛，亦主邪气固结，积聚由物之死气阻人生气，症瘕由气聚邪痼久结，脉紧正应其牢痼难解之机，故以紧脉示积聚症瘕之邪结深重、气血壅滞之病机。", ["紧"]], "25987": ["病机", "原文未出脉名，专论搐搦、振颤、惊三证之病机。搐搦病在筋脉，振颤病在肌肉，惊则病在神志而发自中，由恐迫致阳缩入阴、气乱。引《举痛论》「惊则心无所倚，神无所归」及《金匮真言论》「肝病，发惊骇」，明惊之病机在神志气乱、肝起御侮。", []], "25988": ["病机", "原文引「伤寒，脉浮，医以火迫劫之，亡阳，必惊狂」，脉浮为邪在表，误火迫劫则亡阳，阳浮于外而惊狂起卧不安。此段辨惊悸惊狂有阴迫阳、阳迫阴之别，水停为悸、火盛为狂，脉浮示阳浮火盛之机，因误治而阳亡，故主火盛阳浮、神志不宁之病机。", ["浮"]], "25989": ["病机", "原文辨癫与痫之别，引脉缓甚、脉满大、脉小急诸象。缓甚为脾虚痰盛，满大为邪实气壅，小急为筋脉挛急，皆与痫证口眼相引、手足掣纵相应。脉象大小缓急不一，正示痫病痰涎涌出、筋脉抽掣之病机，非专主一脉。", ["缓", "大", "小", "急"]], "25990": ["病机", "原文论狂有四端：阳郁、七情、火邪、瘀血。脉浮为阳郁于外，微而沉为阳郁于里或瘀血内结。引〈病能论〉「阳气者，因暴折而难决，故为怒狂」，及〈癫狂篇〉七情致狂诸候，示狂病脉象随病因不同而见浮、微沉之异，总属阳气郁遏、神志失守之病机。", ["浮", "微", "沉"]], "25991": ["病机", "原文未出具体脉象，引《脉要精微论》篇名，论惊痫癫狂与风之关系。孙真人、王焘皆加「风」字，并附《素问·厥论》。其义在阴阳互相维系乃生，两相背驰则死，癫痫阴阳相持可数年不愈，伤寒胜负十余日即决，示癫痫病机在阴阳久相拒而仍相维，非卒然离决。", []], "25992": ["病机", "原文以「脉搏大滑」与「脉小坚急」对举，说明癫狂惊痫虽同属阳化风、风煽阳，但脉象有大小滑坚之异。大滑为阳搏阴而难通，小坚急为阳绝阴而无制，皆阳穷化风之象。脉大滑主痰火壅盛、阳扰神明；脉小坚急主阴亏阳亢、风动痉急。二者脉势不同，反映病机深浅与阴阳偏倾之异，故治疗需分惊邪专条与狂走别故。", ["大", "滑", "小", "坚"]], "25993": ["病机", "原文引《病源》「忧恚则气结，气结则不宣流，使噎」，又言「阴阳不和，则三焦隔绝」，脉浮大提示气机郁结于上、津液不布。浮为气逆于外，大为壅塞不通，故食入窒塞而成噎。忧思伤肺，肺失输布，津液结濇，气道不泽，脉见浮大，主气结津枯、三焦隔绝之噎证。", ["浮", "大"]], "25994": ["病机", "原文论膈证由噎所致，引《素问》「一阳发病……其传为膈」，谓胆与三焦气机抑遏，窒塞难通。脉浮而涩，浮主气机上逆，涩主津液结濇、血行不畅。气机窒塞则脉浮，津血不流则脉涩，故膈证脉浮涩，主气结津枯、上传下传之病机，属病末传之大证死证。", ["浮", "涩"]], "25995": ["其他", "本段未识别脉名，专论齿痛与龂痛之辨。齿痛连骨主肾，龂痛属手足阳明。肾病有湿热生虫之外因，寒闭血液不能荣骨之内因；阳明病有风则肌肉肿、开阖不利，火则龂烂赤。虽无脉象，但以齿龂部位分经论治，提示齿痛可温可补、龂痛宜清宜泄，属辨证鉴别之论。", []], "25996": ["病机", "原文辨吐唾血与吐血之别，引《千金》廪邱之说，谓吐血有内衄、肺疽、伤胃三种，得之于劳倦饮食过常。脉紧而数，紧主寒凝或痛，数主热盛或血动。紧数相合，提示寒热错杂、血为热迫而妄行，或劳倦伤中、饮食过常致血聚胃中，满闷即吐。脉紧数主胃中积热、血溢上出之吐唾血。", ["紧", "数"]], "25997": ["病机", "原文引《脉要精微论》「肺脉搏坚而长，当病吐血」及《邪气藏府病形篇》「肺脉微急，为肺寒热，怠惰，欬唾血」，又引「心脉微涩，为血溢」。坚、长、急主实，定位于肺，说明血聚胃中、上逆于肺；微涩主虚，主血溢而阴伤。脉坚长急为实非虚、在上不在下；微涩为虚证血溢。数脉并见，示吐唾血有实有虚，当参部位与兼症。", ["坚", "长", "急", "涩"]], "25998": ["病机", "原文引《金匮要略》「尺脉浮，目睛晕黄，衄未止」，谓尺部为水所居，水中沉浊酿火随经上逆，故尺脉浮、瞳子不慧而晕黄。又言「脉沉弦者」「脉浮者」「脉浮紧」，沉弦主水饮内结、血中之水；浮紧主表邪或寒束，迫血上溢。诸脉并见，说明衄血由水浊酿火、随经上逆，治当泄本根之浊、除其道。", ["浮", "沉", "弦", "紧"]], "25999": ["病机", "原文申明「吐行浊道，衄行清道」之理，引《灵枢·经脉篇》六经循行，说明衄血自阴及阳、从清道上溢。脉急紧，急主拘急、紧主寒束，提示寒邪外束、经气紧张，血不得循常道而妄溢于清道。急紧相合，主寒凝气滞、血逆上窍之衄血，与六经循行部位相应。", ["急", "紧"]], "26000": ["病机", "本段论目肤瞖，分内外二因。外邪乘腑脏、风热干肝，致睛生瞖；内因则肝肾虚寒，目䀮䀮无所见。原文引《病源》「肝藏不足，为风热所干，晴亦生瞖」，又言「肝藏血气蕴积，冲发于眼，津液结聚，遂成珠管」，皆从脏腑虚实不调立论，非脉象所主，故脉象要素为空。", []], "26001": ["病机", "本段论面疱、面皯、面皶，皆外感风热、风邪客于皮肤，或饮酒热气冲面遇风冷相搏所致。原文强调「头面，固诸阳所共至，亦阳气停顿处」，手三阳终于面、足三阳始于面，分支多则力分行迟，故邪独留于面。全段以经络阳气分布释病机，未及脉象。", []], "26002": ["病机", "本段论秃发两端：一为虚人及病后发落，一为疮虫致秃。引巢氏「血气衰弱，经脉虚竭，不能荣润，故须发秃落」，脉虚竭正示血气衰少、经脉失充，不能上荣须发，故主发秃。此脉与虚劳、病后营血不足之证相应，非外邪实候。", ["虚", "竭"]], "26003": ["病机", "本段引《灵枢·二十五人篇》论须眉髯胫毛与血气盛衰相应：血气盛则美长，血少气多则短少，血气皆少则无毛或枯悴。全段以足阳明、足少阳上下血气多少释毛发生长之机，属经络气血盛衰病机，原文未涉脉象，故脉象要素为空。", []], "26004": ["预后", "本段论金刃所伤，引《圣济总录》「察微妙之脉」，以脉判生死。原文「胗其脉虚细小者，生。微细迟者，生。反此，为难治」，虚细、微细迟皆示气血虽伤而未败、胃气尚存，故主生；若脉反实大急疾，则邪盛正溃，预后不良。此以脉候疮疡吉凶。", ["虚", "细", "微", "迟"]], "26005": ["治法", "本段为干地黄药性条文，言其性寒，功能「逐血痹，破恶血，通血脉」。所主为瘀血痹阻、血脉不通之病机，以药之寒凉入血分，破恶血而通利血脉。原文纯属药物主治，未及脉象，故脉象要素为空，归入治法类。", []], "26006": ["治法", "本段为蜚蠊药性条文，言其性寒，「主瘀血，通利血脉」。所主病机为瘀血内停、血脉不利，取虫类药通利之性以化瘀行血。原文仅列药性与主治，未涉脉象与症候，故脉象要素为空，归入治法类。", []], "26007": ["治法", "本段为芍药药性条文，言其微寒，「主逐贼血。除血痹，通顺血脉，缓中，散恶血，逐贼血」。所主为瘀血痹阻、血脉不顺之病机，芍药能散恶血、逐贼血而通顺血脉，兼缓中焦。原文纯属药物功用，未及脉象，故脉象要素为空，归入治法类。", []], "26008": ["病机", "原文以脉微而沉、脉沉结、脉浮数、脉数不解、脉微大来迟论瘀血诸态。微沉主阳气不振、血行滞涩，故瘀留不行；沉结为血结于里、壅塞不通；浮数、数不解则瘀久化热，热与血搏。诸脉并见，说明瘀血有留、闭、老、恶、贼之别，病位有肠中、腹中、胸腹、心脾之异，总归气血壅瘀、经脉不通之病机。", ["微", "沉", "结", "数"]], "26009": ["病机", "原文未出脉名，而曰“气血壅瘀而致”“内无壅则邪气侵袭，仅生疾病；内有瘀则邪气依附，遂发痈疽”。其论痈疽由气血壅瘀、邪气依附而成，浅者血肉腐坏、泻脓可瘳，深者经脉败漏、伤藏以死。故所主病机为气血壅瘀、邪结深浅不同，治当血瘀则通、气壅则宣，外实开之、内虚托之。", []], "26010": ["病机", "原文未言脉，专论疖、疽、癣、疥皆恶疮。谓肺主皮毛、脾主肌肉，气虚腠疏则湿邪乘入，化为热毒，侵食肌肤、浸渍血脉，故或肿或腐、为痛为痒，日久生虫，浅则外淫、深则内薄。其病机为气虚腠疏、湿邪化热毒、侵食血脉肌肤，治宜化浊秽、洁脓腐，于宣逐中寓补隙。", []], "26011": ["病机", "原文以“脉消长”为说，论恶疮癣疥诸候。谓体虚受风热湿毒，与气血相搏则发恶疮，痒痛焮肿而多汗、身体壮热；癣者风湿邪气客于腠理，复值寒湿与血气相搏，则血气否涩、皮肉隐胗。脉消长者，示邪正相争、血气否涩而病势有进退，总主风湿热毒搏结气血、腠理壅滞之病机。", ["消", "长"]], "26012": ["病机", "原文未出脉名，论瘘疮之源有三：一为疡久不敛、陷脉为瘘，留连肉腠；二为情志拂郁、鼠瘘之本在藏；三为虫鸟之毒、浮于脉中未著肌肉而外为脓血。其病机或气血虚乏、腐去肉不长，或精血内沮、肝藏受损，或毒气内袭。故治有补虚塞漏、顺气开结、杀虫解毒之别。", []], "26013": ["病机", "原文未言脉，辨瘘、瘰疬、鼠瘘之异同。陷脉为瘘即漏，本在于藏、上出项腋者为瘰疬未溃，浮于脉中、外为脓血者为鼠瘘已溃。其病机总属毒邪结聚、气血壅滞，或痈疽虚损。故漏当求痈疽治虚之法，瘰疬当顺气开结，鼠瘘当杀虫解毒，示病位深浅与治法相应。", []], "26014": ["其他", "原文仅载“槲脉：平。烧作散，主痔。槲若，主痔止血”，未涉脉象病机，属药物主治条目。其言槲脉性平，烧散可主痔，槲若主痔止血，说明该药有止血疗痔之用。因无脉象与病机论述，故不作脉理分析，仅列为主治药物之其他类。", []], "26015": ["病机", "原文引“经脉横解，肠澼为痔”，谓醉饱合阴阳致血气劳扰、渗漏肠间，冲发为痔。泄而不畅则瘀滞变热而结肿，渗而不已则经脉滑溜而为澼。脉滑溜者，主血随注渗、经脉滑利失约，故为肠澼下血之机；肿久成痿、澼久脱肛，皆气血耗伤之变，治当化热、固脉、补益其气。", ["滑", "溜"]], "26016": ["其他", "本段引崔氏与《集验》对五痔的分类，如“牡痔”“酒痔”“肠癖”“血痔”“气痔”等，描述肛边生肉如鼠乳、肿痛生创、大便清血、大便难等症候，未涉及脉象，故无脉象要素可提取。主旨在于辨析痔病类型与治法方药，属其他类。", []], "26017": ["病机", "原文论蚘虫病机，谓“蚘，病在阴而阳不振，故主脉微而厥，肤冷，静复时病，须臾复止，得食而呕，又烦”。脉微为阳气不振，厥为阴阳气不相顺接，故脉微而厥主蚘厥，与肤冷、得食而呕、烦等症相应，揭示虫扰而阳郁之病机。", ["微", "厥"]], "26018": ["其他", "本段为《续断》药物条文，言其“微温”，功主“助气，调血脉，补五劳七伤”，纯属本草主治记载，未涉及脉象描述，故无脉象要素可提取。主旨属其他类。", []], "26019": ["病机", "原文辨析虚劳脉象，谓“仲景论虚劳，凡言劳者，必主脉大；云脉浮、脉浮弱而濇、脉虚弱细微、脉沉小迟，皆不谓劳”，又言“劳者，精伤而气鼓；虚者，气馁而精违”。脉大主劳，因精伤气鼓；脉浮弱而濇等主虚，因气馁精违，揭示虚劳与虚证脉象病机之异。", ["大", "浮", "弱", "濇"]], "26020": ["其他", "本段为《白马茎》药物条文，言其“平”，主“伤中脉绝，阴不起”，属本草主治记载，未涉及具体脉象描述，故无脉象要素可提取。主旨属其他类。", []], "26021": ["病机", "原文论痿与㿉，谓“痿者，疲垂不起”“㿉者，木肿不灵”，引《素问》阴阳别论“三阳为病，发寒热，下为痈肿及为痿厥腨㾓，其传为索泽，其传为㿉疝”，阐明肾气不给、寒水盛阳郁勃、血脉溃败之病机，未涉及脉象，故无脉象要素。", []], "26022": ["病机", "原文引《病源》腰痛五类，言“肾经虚损，风冷乘之”，又云“邪客于足少阴之络，令人腰痛引少腹，不可以仰息”。虽段中提及“散脉”，但未展开脉象与病机对应，主旨在于腰痛病因分类及肾虚风冷之病机，故脉象要素仅取“散”。", ["散"]], "26023": ["病机", "原文论崩中漏下，引《纲目》分崩、漏、沃、带，谓“体状一殊，情由立异，斯固宜循因索治”，并列举治崩、治漏方药。段中脉象“脉数无疮”“脉虚多寒”“脉阴阳虚实紧弦”提示崩漏病机有虚寒、紧弦等不同，脉数为热，虚为不足，紧弦主痛或寒，与崩漏虚实寒热相应。", ["数", "虚", "紧", "弦"]], "26024": ["主病", "原文仅载牡丹性寒微寒，主治女子经脉不通、血沥、腰痛，未及脉象。其病机为寒客胞脉、血行瘀滞，故经水不通而沥血；腰为肾之外府，瘀阻络脉则腰痛。药取牡丹辛寒以通经散瘀，寒温并用，示瘀热或寒瘀皆可致闭，非单凭脉断。", []], "26025": ["主病", "干漆气温，主血闭，为臣药，专治女人经脉不通。其病机属瘀血内结、冲任壅塞，血闭不行故经水断绝。干漆功擅破瘀消积，性温能行，与牡丹同列，示经闭有寒瘀、干血之异。原文未出脉，当以瘀血内阻为辨，脉多沉涩或牢。", []], "26026": ["病机", "原文标脉数，论妇人虚、积冷、结气致经水断绝，而中焦属热之治法。脉数为热，然此热由寒郁气结、传变所化，故曰寒少热多。所列药皆气平气寒，正合中病属热。脉数在此非纯实热，乃气机郁滞、郁而化热之象，故治取平寒，不取苦寒直折。", ["数"]], "26027": ["病机", "原文未出脉，论乳汁不下之由。谓人身气血流行全恃阴阳不偏著，偏著则气机停滞、血脉壅瘀，乳汁因而不下。举蛴螬主产后中寒下乳、葵子主嬭肿下乳为证，示病去则乳自下。其病机在气血壅滞、阴阳偏著，非独虚少，故治当去其所病。", []], "26028": ["其他", "原文未涉脉象，乃考辨蛊毒源流。引《周官》庶氏、剪氏除蛊之职及《本经》蛊毒之物，证古有以惑乱人为蛊者。所论属病名考据，非脉诊内容，故脉象要素为空，主旨归其他，不涉主病病机之脉。", []], "26029": ["病机", "原文言汗不出之由，谓寒因虚集、风为热留、气机不遂，虽驱风寒汗终不出。关键在“脉濇而不利”，濇主血少气滞、脉道不利，故肌肤痹而不宣、肤腠阖而不开，出汗之路不通。又心液不足、心血虚不给，化汗之源亦亏，故非独驱风寒可力。", ["濇"]], "26030": ["治法", "原文未出脉，论止汗之法在宁化源、濇道路，不在防肌腠。举麻黄根、故扇、粢粉、豆豉四物外扑，皆取宁化源、濇道路之意。引《阴阳应象大论》阳汗如雨、阳气如风，以风致雨、止雨亦以风为喻，示守在中之阳、堵必经之道，属治法范畴。", []], "26031": ["病机", "原文引“伤寒，脉结代，心动悸”，以证惊悸皆缘心气。结代脉主心气不足、脉道不利，气血不能接续，故心动悸而脉来歇止。原文列惊、悸、瘛疭、烦等症，皆心气不宁之支流，结代正示心之气阴亏虚、鼓动无力，为惊悸病机之脉征。", ["结", "代"]], "26032": ["病机", "原文以“脉数虚”“脉数实”对举，说明肺痿与肺痈虽同见数脉，但虚实不同。数而虚为肺痿，因热在上焦，津液枯燥，肺叶萎弱，故吐涎沫；数而实为肺痈，热毒壅聚，血肉腐败，故吐脓血。二者兼证均有咳，故治法仿咳。此段从脉之虚实辨病机之异，突出肺痿始终虚、肺痈属实热。", ["数", "虚", "实"]], "26033": ["病机", "原文未出脉名，专论痿证之源与治。引《素问·痿论》“五藏因肺热叶焦，发为痿躄”，说明痿之根本在于肺热叶焦，津液不布，筋骨失养；又引“治痿独取阳明”，指出治痿当责之胃。文中描述“软罢难振”“胫纵不任地”“筋急而挛”“肌肉不仁”“腰脊不举”等，皆痿之传变，揭示痿证由肺热及五脏、由轻转重的病机。", []], "26034": ["病机", "原文未涉脉象，以“创痈之脓，犹伤寒之汗”为喻，论疮痈溃脓的病机。汗为正气伸而邪解，脓为新血生而恶血化；邪气无形随解即散，恶血有形虽化未去。故溃脓后仍当蚀脓，屡脓方尽，否则脓水壅结，复有攻冲侵薄，久旷变生。此段强调疮痈脓成宜彻内彻外、剥蚀净尽，使腐退新生、血行肌满，属外科病机与治法之论。", []], "26035": ["主病", "原文未出脉象，述牡丹药性微寒，主女子经脉不通、血沥腰疼。经脉不通多因血瘀或血虚夹滞，牡丹能通经行血；血沥腰疼乃瘀血阻滞、血不归经所致，牡丹凉血散瘀，故主之。此段以药测证，提示女子经闭、漏下、腰痛等症与血分瘀热相关，属主病之论。", []], "26036": ["其他", "原文无论脉象，以匠氏绳墨为喻，论医家学术源流。谓《本经》为绳墨之创始，《大观》《证类》为规矩成则，濒湖《纲目》集大成而未达变通；能随机应用、不为绳墨所拘者，唯长沙一人。强调宗《本经》、本炎黄之道，端本澄源。此段属医论，非脉诊病机，故归其他。", []], "26037": ["主病", "原文未出脉象，论东壁土、白垩土、黄土等药性主治。脾土喜燥恶湿，东壁太阳所照之土能引真火生发之气，补土胜湿，故吐泻自止；白垩土苦温，主女子寒热症瘕、月闭积聚，取土间气祛妇人积滞；黄土甘平，治泄利赤白、腹内绞痛、下血。此段以土类药测证，示脾胃湿困、妇人癥瘕、泄利下血等病机。", []], "26038": ["主病", "原文未出脉象，述《本经》所载空青主治青盲、耳聋，能明目、利九窍、通血脉、养精神、益肝气，久服轻身延年。空青感铜之精气而结，专入肝经，肝开窍于目，故主目疾；通血脉、养精神、益肝气，则九窍不利、耳聋等症可除。此段以药效测病机，示肝血不足、血脉瘀滞、精神失养之目盲耳聋等证。", []], "26039": ["病机", "原文未出脉象，发明空青感铜之精气而结，专入肝明目。引《本经》主耳目九窍诸病，皆通血脉、养精神、益肝气之力。时珍谓东方甲乙生肝胆，其气清者为肝血，精英为胆汁，开窍于目；胆汁充则目明，减则目昏。空青之浆犹胆汁，故为治目神药，以类相感。此段阐发肝血胆汁与目窍病机，属病机之论。", []], "26040": ["病机", "原文言甘草“能和冲脉之逆，缓带脉之急”，又云“凡心火乘脾，腹中急痛，腹皮急缩者宜倍用之”。脉之急、结代，皆由心火乘脾、冲脉气逆、带脉拘急所致，故用甘草缓急和中，使阴阳升降调和，则急脉得缓，结代可通。", ["急", "结", "代"]], "26041": ["主病", "原文谓黄耆“治脉弦自汗，泻阴火”，又治“脉沉而口噤”。脉弦自汗乃卫虚阴火不敛，脉沉口噤为元气不足、经络壅滞。黄耆甘温补虚，入肺固表，入脾托疮，通调血脉，故主气虚自汗及卫虚邪凑之证。", ["弦", "沉"]], "26042": ["病机", "原文举仲景“汗后身热亡血，脉沉迟，下利，身凉，脉微血虚，并加人参”，又及“脉浮而芤濡虚大”等。沉迟微芤皆气血虚衰之象，血脱则气无所附，故用甘温人参急固无形之气以生有形之血，阳生阴长，此血脱益气之旨。", ["沉", "迟", "微", "芤"]], "26043": ["病机", "原文未出脉名，专论白术甘温味厚，入脾胃二经，生用除湿益燥、消痰利水，治风寒湿痹、死肌痉疸，制熟则和中补气、止汗除热。其病机总由风寒湿三气杂合，脾胃虚而湿热瘀滞，故以术祛湿健脾，湿去则诸证自除。", []], "26044": ["主病", "原文未出脉名，论巴戟天为肾经血分及冲脉药，性补元阳兼散邪，故主阴痿不起、强筋骨、安五脏，治大风邪气及脚气。其病机为元阳虚衰、邪气留连，真元得补则邪无所留。然阴虚相火炽盛者禁用，恐助火伤阴。", []], "26045": ["病机", "原文未出脉名，论丹参气平而降，为心与包络血分药，治心腹邪气、肠鸣幽幽如走水，皆瘀血内滞化水之候。瘀积去则烦满愈而正气复。其性长于行血，故能破宿血生新血、安生胎落死胎、止崩中带下，然妊娠无故勿服，大便不实者忌之。", []], "26046": ["误治", "原文言黄芩苦燥坚肠胃，为湿热黄瘅、肠澼泻痢必用之药，然“脉迟小弱皆不可用”。迟小弱为虚寒之象，黄芩苦寒，若胎寒下坠及食少便溏者误用，则更伤脾胃阳气，故特举脉以戒混用，此示辨脉用药之要。", ["迟", "小", "弱"]], "26047": ["主病", "原文谓防风浮而升，为治风去湿之仙药，治大风头眩痛、恶风、周身痹痛、四肢挛急，又言“脉浮弦者为宜”，脉来数者亦主风热。浮弦为风邪外袭之象，数则风热相搏，防风性上行而散，能于土中泻水，故主上盛风邪及太阳经证。", ["浮", "弦", "数"]], "26048": ["其他", "原文未涉及脉象，主论羌活之药性功用。羌活治足太阳风湿相搏，一身尽痛、头痛、肢节痛，乃“却乱反正之主帅”；督脉为病，脊强而厥者非此不能除。其能胜湿，故治水湿。内伤元气、血虚头痛及遍身肢节痛皆非所宜，提示药证相应之理。", []], "26049": ["病机", "原文言升麻“缓带脉之缩急”，带脉缩急为脉象表现，主元气下陷、带脉失缓之病机。升麻引清气右升，于阴中升阳，故能缓其缩急。胃虚伤冷郁遏阳气于脾土者，宜升麻、葛根升散火郁。若初病太阳便服升麻葛根汤，则发动其邪，反成其害。", ["缩", "急"]], "26050": ["主病", "引《经》曰“诊得心脉搏滑急，为心疝，少腹当有形也”。滑急之脉主心疝，因足厥阴之邪干手厥阴，热郁结于内，故少腹有形。贝母善解心胸郁结之气，清心肺郁热，故能治疝瘕、喉痹、乳难等郁热结聚之病，总取解散郁结之邪。", ["滑", "急"]], "26051": ["其他", "原文仅言“甘寒，无毒。与百脉根相类，百脉根出巴西，他处罕得”，未涉及脉象与病机，属本草产地及性味记载，故脉象要素为空，主旨归为其他。", []], "26052": ["其他", "原文论白茅根甘寒降伏热、利小便、止渴，治伤寒呃逆喘哕、吐衄便溺诸血、黄瘅水肿等，皆属药性主治，未及脉象。其言“呕吐衄亦有因于寒者，即非所宜”，提示甘寒之剂须辨寒热，非一概可投。", []], "26053": ["其他", "原文述草龙胆苦寒沉降，主肝经邪热、下焦湿热、酒瘅黄肿、目赤肿、小儿肝气等，全为药性功用，未涉脉象。其言“大苦大寒，过伤胃中生发之气，反助火邪”，又言胃气虚人服之必呕、脾虚人服之必泻，示苦寒伐胃之戒。", []], "26054": ["其他", "原文论细辛辛温上升，入手足厥阴、少阴血分，治督脉为病脊强而厥，及咳逆头痛、风湿痹痛、百节拘挛等，皆属药性主治，未及脉象。其言“辛能泄肺”“辛能补肝”“辛能润燥”，阐发辛温散结开窍、火郁发之之义。", []], "26055": ["主病", "原文引《金匮》“治咳嗽而脉沉者，用泽漆汤，以中有白前也”。脉沉主水气内停、肺气壅实，故咳嗽而脉沉，当降气逐水。白前长于降气，专搜肺窍中风水，故治肺气壅实有痰之咳嗽。若虚嗽常哽气者，则不可用，示虚实之辨。", ["沉"]], "26056": ["病机", "原文以脉细欲绝、脉大对举，说明当归所治血病有虚实两端：脉细欲绝为血虚脉道不充，脉大为血壅不流、恶血上冲。当归辛温润血，能破恶血、养新血，使气血各有所归，故主血受病及夜甚之证，产后恶血上冲亦用之，正合血壅则痛、血虚则细之机。", ["细", "大"]], "26057": ["病机", "本段未出脉名，专论芎䓖辛温上升，入肝行冲脉，为血中理气药。其治中风入脑头痛、少阳厥阴头痛及血虚头痛，皆取辛散血分诸邪、搜肝经之风。血痢已通而痛不止，乃阴亏气郁，加芎䓖气行血调则痛止，说明病机在血分气郁、清阳不升。", []], "26058": ["病机", "本段未出脉名，论藁本性升属阳，为足太阳寒郁经中、头项巅顶痛及大寒犯脑之专药。妇人疝瘕、腹中急、阴中寒，皆太阳经寒湿客邪内犯，故用藁本去风除湿。又明言头痛挟内热、春夏温病热病及产后血虚火炎头痛皆不可服，示寒湿与火热病机相反。", []], "26059": ["病机", "本段未出脉名，论白芍酸寒敛津液、护营血、收阴气而泻邪热，泻肝邪热所以补脾阴。仲景用为补营首药，入肝脾血分，治阳维寒热、带脉腹痛，能于土中泻水，为血痢必用之药，须兼桂以敛中寓散。建中汤专主太阴腹痛，说明病机在营血失护、肝脾不和。", []], "26060": ["病机", "本段未出脉名，论郁金辛香先升后降，入心及包络，治吐血衄血唾血、破恶血、血淋尿血、妇人经脉逆行、产后败血冲心及宿血心痛。其能化症瘕为水、泻膈下恶物，说明病机为恶血瘀阻心包络、血不循经而妄行，故以郁金入心去恶血为主。", []], "26061": ["病机", "本段未出脉名，论香附气平不寒、香而能窜，为足厥阴肝、手少阳三焦气分主药，兼入冲脉。其开郁气、行血气、止诸痛，治月候不调、胎产崩漏及两胁气妨，关键在“血不自行，随气而行，气逆而郁则血亦凝滞”，说明病机为气郁血滞，气顺则血和。", []], "26062": ["误治", "原文指出汗出如雨、吐泻脱元、四肢清冷、脉微欲脱者，当用大顺浆水散救之；若用香薷饮，是重虚其表，顷刻脱亡。脉微欲脱为元气虚脱之候，香薷辛温发散，误用于此则更耗阳气，故本段主旨在于辨明香薷饮之误治，警示虚脱者不可概用。", ["微"]], "26063": ["病机", "本段未出脉名，仅言爵床善通血脉，苏恭疗血胀下气、杖疮捣汁涂之立瘥，并归纳《本经》诸品不出活血舒筋之用。其病机在于血脉瘀滞不通，故以通血脉、下气行血为治，血胀、杖疮皆属瘀血壅阻之候，通之则气行血畅而愈。", []], "26064": ["其他", "原文仅言辛温无毒、叶紫者能散血脉之邪，未及脉象。所论为药性气味与归经功用，属本草药性范畴，非脉诊内容，故脉象要素为空，主旨归其他。", []], "26065": ["病机", "原文以菊花补水制火、益金平木立论，谓益金则肝木平而风自息，补水则心火制而热自除，清利血脉之邪而痹湿开泄。全段阐发头目风热、恶风湿痹之病机，未涉脉象，故脉象要素为空。", []], "26066": ["病机", "原文谓鹿衔除痹著血脉之风湿，走胃与肾肝血分，专理血中邪湿而无留滞，又温补冲督精血，治风湿痹、历节痛、惊痫悸气、吐咯诸血。所论为药入血分、理血中邪湿之病机，未及脉象。", []], "26067": ["病机", "原文谓夏枯草有补养厥阴血脉之功，辛能散结、苦能除热，故症结瘿气散；禀纯阳之气而散阴中结滞之热，解内热、缓肝火。所论为厥阴血脉结热之病机，未言脉象，故脉象要素为空。", []], "26068": ["病机", "原文谓青葙子为足厥阴经药，治风瘙身痒、皮肤中热，以能散厥阴经中血脉之风热，明目之功可推。所论为厥阴血脉风热之病机，全段未及脉象，故脉象要素为空。", []], "26069": ["病机", "原文谓血生于心包、藏于肝、属于冲任，红花汁与之同类，故能行男子血脉、通妇人经水、活血散赤肿；少则养血，多则行血，过用使人血行不止。所论为血分瘀滞与活血之机，未涉脉象。", []], "26070": ["病机", "原文谓续断入肝主续筋骨，为妇人胎产崩漏首药，又主带脉为病，久服益气力、利关节、暖子宫、散痈肿瘀血，总取和血通经之义。所论为和血通经、续筋骨之病机，未及脉象。", []], "26071": ["病机", "原文谓苍耳治头风脑痛、风湿周痹、四肢拘挛、恶肉死肌，善通顶门连脑、能走督脉，妇人血风攻脑则头旋闷绝。所论为风湿入督、上攻头脑之病机，全段未言脉象，故脉象要素为空。", []], "26072": ["病机", "原文虽仅言“脉沉”，然此段论麻黄、桂枝为荣卫药，麻黄治卫实，桂枝治卫虚。脉沉在此提示病位在里，与“过发则汗多亡阳”及“表虚之证用之则脱人元气”相参，说明脉沉非表实可汗之征，若妄用麻黄发汗，必致亡阳脱气，故脉沉当审荣卫虚实，不可径投峻汗。", ["沉"]], "26073": ["病机", "原文以“脉洪实者宜之”指生地黄治心热、手心热，洪实为心火亢盛、血分有热之象，故宜生地凉心血、益肾水；又言“若脉虚者，则宜熟地黄”，虚脉主肾中元气不足，故以熟地补肾填精。脉之洪实与虚，恰分生熟二地之主治，示人凭脉辨气血虚实。", ["洪", "实", "虚"]], "26074": ["病机", "原文引《金匮》泽漆汤“治咳而脉沉者”，并自注“咳属肺；脉沉则血分之病也”。咳本肺气上逆，脉沉不浮，说明病不在气分表浅，而深入血分，肺经血气郁滞，故紫菀以肺经血分药疏利血气、散结降气，使热从溲便去。脉沉在此定病位在血分。", ["沉"]], "26075": ["其他", "此段仅录《本经》麦门冬主治“心腹结气，伤中伤饱，胃络脉绝，羸瘦短气”，未出脉名。文中“胃络脉绝”指胃络气血阻绝，非脉象描述，故脉象要素为空。其主旨为陈述药性主治，属其他类，病机为胃络不通、中伤羸瘦短气。", []], "26076": ["病机", "原文言“肺中伏火，脉气欲绝者，加五味子、人参为生脉散，专补脉中元气不足”，又云“脉散补其天元真气”。脉散为元气耗散、脉中真气不足之象，故以生脉散甘温泻阴火、甘寒滋燥金、酸咸补庚金，共补天元真气。脉散在此主元气虚散之病机。", ["散"]], "26077": ["病机", "此段论防葵治疝瘕肠泄、膀胱热结，又疗五脏虚气、小腹支满，未出脉名。文中“中有火者不可久服”与“久服恐正气愈虚，不能制五志之火”相参，说明防葵走散，虚火者久服反令正气愈虚、痰湿上侮，故脉象要素为空，主旨为药性走散与虚实宜忌之病机。", []], "26078": ["病机", "此段论大戟苦寒下走肾阴、辛散上泻肺气，专治蛊毒十二水、腹满急痛，皆“浊阴填塞所致”，然“惟暴胀为宜”。未出脉名，而“暴胀”提示水湿浊阴暴盛、脉当沉实有力；若久病正虚，则非所宜。主旨为水湿浊阴填塞之病机与峻利攻逐之宜忌。", []], "26079": ["病机", "原文引《金匮》泽漆汤“治肺咳上气脉沉”，泽漆利水功类大戟，方中泽漆、半夏、紫参、白前等逐水降逆。咳而上气而脉沉，说明水饮内停、肺气上逆，病位在里，故以利水逐饮取效。脉沉在此主水饮内结、肺气不降之病机。", ["沉"]], "26080": ["病机", "原文以脉沉细或浮虚无力定附子所主之阴证：沉细为阳虚寒凝、脉道不充，浮虚无力为虚阳外浮而内真寒。故凡伤寒阴证厥逆、中寒夹阴虽身热而见此脉，非附子不治；甚则唇青囊缩，急须生附峻温。脉象与阴寒内盛、阳气欲败之病机相应。", ["沉", "细", "浮", "虚"]], "26081": ["主病", "本段未出脉名，专论乌头治风之响导作用：主中风恶风、半身不遂、风寒湿痹、心腹冷痛及阴疽久溃不敛，皆风邪寒湿痹阻血脉所致。小儿慢惊搐搦涎壅厥逆，亦取乌头通血脉、借茶清涌吐风痰。所述诸证以风痰寒湿闭阻为病机，非据脉立论。", []], "26082": ["病机", "原文以厥冷脉沉及伤寒阴毒为天雄主治之据：脉沉主里、主阴寒内盛，阳气衰微不能外达，故厥冷而脉沉。天雄禀纯阳之性，补命门三焦、壮阳精强肾气，正对元阳素虚、寒邪外入之病机。若上焦阳虚则当用参耆，非天雄下行所宜，示辨位用药。", ["沉"]], "26083": ["病机", "原文以筋脉拘缓为南星所主症候之一：拘缓者筋脉失养、弛纵不利，由水不归经、蕴积为湿热，风从内发，津液凝聚所致。南星为开涤风痰专药，故治筋痿拘缓、麻痹、口噤身强、口眼㖞斜。脉拘缓反映风痰湿热阻滞经络、筋脉失约之病机，非虚缓之平脉。", ["缓"]], "26084": ["兼症", "原文引仲景太阳病下之遂利不止、喘汗脉促者用葛根黄芩黄连汤：促脉为误下后表邪内陷、里热壅盛而正气受挫之象，故见喘汗下利。葛根升胃中清阳、解肌散热，配芩连清里。此段以脉促提示表里寒热轻重，属随证处方之兼症辨析，非专论促脉主病。", ["促"]], "26085": ["主病", "本段未出脉名，论防己辛寒纯阴、善走下行除湿，主下焦血分湿热：疗水肿、膀胱热、通腠理利九窍，为疗风水要药。汉防己去身半以下湿热，木防己治中风挛急风痹。诸方皆治痰饮湿热，总取通行经脉、泻血中湿热之力，病机在湿热水停、经络壅滞。", []], "26086": ["其他", "此段仅录《本经》文，未及脉象，述除脾胃寒热、通利九窍血脉关节、令人不忘、去恶虫之功效。其义在通利湿热、宣畅血脉关节，使窍利神清、湿散虫去。文句简略，属药性功效记述，未涉及脉诊与具体病机推断，故归其他。", []], "26087": ["病机", "本段未出脉名，论木通入手足太阳、少阴、厥阴，泻气分湿热。脾胃不和则水道不利，郁而为寒热、肿胀、淋秘、痹瘅，皆湿热壅滞、水行火降失职之病机。木通淡渗分利阴阳，则脾胃和而心肾平；然胃虚肾冷、表虚多汗者禁服，恐重伤津液。", []], "26088": ["其他", "本段论浮萍药性功效，未涉脉象。浮萍轻浮入肺达表，故能发汗疏风、下水气，主暴热身痒、疠风等。然其性发散，元气本虚及表虚自汗者用之转剧，提示虚证禁用。", []], "26089": ["其他", "本段述地朕（地锦）功效，未及脉象。其能通流血脉、散血止血、通利小便，故治崩中痢下及淋证。功专血分，以散血为用。", []], "26090": ["妇人", "本段论卷柏为足厥阴血分药，主女子经癸之病，属厥阴与冲脉之患。因其能寒子脏中血气，故妊妇禁用。全段围绕妇人经孕用药禁忌。", []], "26091": ["其他", "本段述大豆（黄、黑）性用，未涉脉象。黄大豆入脾泻而不补，黑大豆入肾泻中寓补。主解百药毒、涂痈肿、治风毒脚气筋脉拘挛等。黄大豆生泄利、熟壅气生痰，痘后余毒发痈可外敷。", []], "26092": ["病机", "本段论饴糖甘温入脾，仲景建中汤用治腹痛，取稼穑之甘以缓之。治伤寒肾虚尺脉不至，是实土以堤水，非伐肾也。说明尺脉不至因中土虚衰不能堤防肾水，故以饴糖补脾实土，体现补土制水之病机。", []], "26093": ["其他", "本段论酒性味功效及宜忌，未涉脉象。酒气悍性热升走，温中发热近于相火，能通血脉、行药势，然助火资痰湿。醉当风卧成恶风，醉浴冷水成痹痛等，皆示酒之偏性致病。", []], "26094": ["其他", "本段述韭及韭子功用宜忌，未及脉象。韭入厥阴散血积，治死血胃痛、经脉逆行、打扑损伤；然胃虚噎膈、痼冷者勿用。韭子辛温壮火，治梦泄尿血白带，惟肾气过劳不摄者宜，阴虚火旺误用则抱薪救火。", []], "26095": ["病机", "本段论葱白辛温发散通阳。少阴病下利清谷、里寒外热、厥逆脉微者，用白通汤内葱白，以辛温通阳气。脉微主阳气衰微，阴寒内盛，格阳于外，故见里寒外热、厥逆，葱白通阳以破阴回阳。", ["微"]], "26096": ["病机", "原文以干姜主治里寒，言\"脉濡者\"示阳气不足、湿滞中焦，濡为虚湿之象；\"脉反紧\"则寒邪内盛、收引凝滞。干姜辛热，炮则守中温脾，生则逐寒发表，正对虚寒里证之濡与寒凝之紧。脉气欲绝者，更以黑附子为引回阳，说明此段借脉象辨干姜生炮之用，主虚寒与寒凝病机。", ["濡", "紧"]], "26097": ["其他", "此段引《本经》述女子赤沃下血，养精保血脉益气，令人肥健嗜食，未出脉名，亦未言脉象。其旨在于药性功效与精血充养之关系，属本草主治范畴，非脉诊病机之论，故脉象要素为空，归入其他。", []], "26098": ["其他", "全段论丝瓜嫩者寒滑、老者通经脉支络，及烧灰治痘疮不快、藤灰治鼻流臭浊、叶汁解蛇毒等，皆属药性主治与用法，未涉及脉象。原文无脉名可录，主旨不在脉诊，故脉象要素为空，归入其他。", []], "26099": ["病机", "原文未出脉名，然论槟榔\"泄胸中至高之气使之下行\"，治冲脉为病、逆气里急、诸气壅腹胀后重，又明言气虚下陷及膈上稠痰结气者得之痞满昏塞愈甚。此从气机升降言病机：气壅实证宜下气消胀，气虚下陷者反忌，属病机与用药宜忌之辨。", []], "26100": ["病机", "原文以瓜蒂苦寒涌吐胸中寒邪痰涎，治面目浮肿、咳逆上气、皮肤水气、黄瘅湿热。特举\"尺脉虚，胃气弱，病后、产后，吐药皆宜戒慎\"，尺虚示下元不足、胃气弱则不耐涌吐，故吐法切禁。此段借尺脉虚说明吐法禁忌之病机，属因脉施治之戒。", ["虚"]], "26101": ["病机", "原文载一人腰痛痰喘、足冷如冰而\"六脉洪大，按之\"，洪大为有余之象，然足冷如冰示下元虚寒，此属虚阳外越、真寒假热之候，脉证相悖。川椒辛温下达命门、助心包命门之火，正针对火不归原之病机，故以洪大按之辨其虚实。", ["洪", "大"]], "26102": ["其他", "此段述猪椒根蔓气臭，能通经脉、去风毒湿痹，《千金》虎骨酒治肝虚劳损、关节骨疼、筋挛烦闷，又枝叶煎饴治通身水肿。全段为药性主治与方用记载，未出脉名脉象，故脉象要素为空，归入其他。", []], "26103": ["病机", "原文论吴茱萸气味俱厚、辛散燥热，入肝行脾，主温中下气止痛、除湿血痹、逐风邪开腠理，治厥气上逆、阴寒膈塞、气不得上下、冲脉为病逆气里急。虽未出脉名，然所论皆寒湿厥逆、浊阴不降之病机，故以苦热泄之，属病机范畴。", []], "26104": ["病机", "原文以脉弱、瞥瞥虚大无力、弦细或浮革、弦细数等脉象，说明肉桂所宜之证为下焦火不足、沉寒痼冷。脉弱虚大为阳气不足，弦细为寒凝肝脉，浮革为虚寒外浮。肉桂辛热下行，益火消阴，正对虚寒之机；若脉弦细数则属阴虚火旺，故切忌辛热。", ["弱", "虚", "弦", "细"]], "26105": ["病机", "本段未言脉象，专论桂心甘润温营之性。桂心去外层苦燥，独取中心甘润，故专温营分之里，治九种心痛、腹内冷痛、痃癖等里寒之病。其与肉桂之别在于不兼通经脉、和营卫、坚筋骨，故不主寒湿风痹等经络躯壳之病，病机重在营分里寒。", []], "26106": ["病机", "本段未及脉象，论牡桂辛胜于甘、微带苦而性偏温散上行。其治上气咳逆，是导下焦阴火逆上；治结气，取辛温开结；治喉痹吐吸，为同气相招引浮游之火下泄，然必兼苦寒降泄。补中益气则补助真元、阳生阴长。全段阐发牡桂辛散上行、开结引火之病机。", []], "26107": ["病机", "本段未言脉象，论筒桂辛而不热、薄而能宣，为诸药通使。其质薄性轻，无桂心、肉桂、牡桂雄烈之气，故专行胸胁，为胀满要药，治中焦寒邪拒闭、胃气不通、呕吐酸水、寒痰水饮。病机在于中焦寒闭、胸胁气滞，取筒桂轻宣通使之性以开提宣通。", []], "26108": ["病机", "原文引仲景太阳中风“阳浮阴弱”，阳浮者热自发，阴弱者汗自出，此为卫实营虚、营弱卫强之病机。桂枝汤证发热汗出，用桂枝与芍药调和营卫，使卫气自和、风邪无所容而汗解，非桂枝能发汗。故此处脉浮弱正是营卫不和、卫强营弱之象，桂枝汤调营卫以解肌。", ["浮", "弱"]], "26109": ["主病", "原文言干霍乱不吐不下、呕逆不止、厥冷而脉沉者，宜用丁香。脉沉主里主寒，厥冷脉沉为阴寒内盛、阳气不能外达之候。丁香辛温入太阴、少阴、阳明，温胃进食、止呕定泻，正对胃寒肝虚、虚冷下痢之机。若渴欲饮水、热哕呃逆则不可误投，示寒热之辨。", ["沉"]], "26110": ["误治", "原文论降真香色赤入血分而下降，内服行血破滞，外涂止血定痛，虚损吐红色瘀昧不鲜者宜加用之。然血热妄行、色紫浓厚、脉实便秘者禁用。脉实主邪热内盛，便秘为热结，血热妄行而脉实，若再用降真香行血下降，则助热伤正，故列为禁用之戒。", ["实"]], "26111": ["病机", "本段未言脉象，论龙脑香辛窜入骨，风病在骨髓者宜之；若风在血脉肌肉用之，反引风入骨髓。其味大辛善走，能散热、通利关格结气，治目痛喉痹下疳，取辛温散火郁、从治发散之法，使壅塞通利、经络条达而惊热自平。然辛烈耗真气，不可多用。", []], "26112": ["病机", "原文论芦荟入厥阴肝经及冲脉，主杀虫清热，治冲脉为病、逆气里急、经事不调、腹中结块上冲及小儿疳热积滞。其性大苦大寒，胃虚少食者服之入口即吐，致夺食泄泻而成羸瘦怯弱，甚则伤胃毙命。此非论脉，乃阐药性峻烈伤中之弊，示人虚寒胃弱当忌。", []], "26113": ["病机", "原文述海桐皮能行经络达病所，专去风湿，治风湿腰脚不遂、血脉顽痹、腿膝疼痛、赤白泻痢及风虫牙痛、疳蚀疥癣、目赤肤翳。其功在祛风除湿、通络杀虫，故无风湿者勿用，恐徒伤正气。此段明药性主治，非脉诊内容。", []], "26114": ["病机", "老妇久病溏泄，遍服调脾升提止涩药而泻反甚，脉沉而滑。沉主里、滑主积，此脾胃久伤、冷积凝滞所致，非虚寒当温，实为冷积内结，法当以热下之，寒去则利止。原文以脉沉滑断为冷积凝滞，示沉滑可主里实积滞，不可见泻即涩。", ["沉", "滑"]], "26115": ["病机", "原文引《本经》主伤中五劳六极、羸瘦、崩中绝脉、补虚益气。此述药性补虚之功，针对劳伤羸瘦、崩中脉绝等虚损之候，非论脉象。绝脉指崩中失血致脉微欲绝，属虚极之象，当以补虚益气为治。", []], "26116": ["病机", "原文发明酸枣仁甘润，熟则收敛津液疗胆虚不眠、烦渴虚汗，生则导虚热疗胆热好眠、神昏倦怠。其入厥阴少阳兼太阴脾经，能散肝胆二经之滞。肝虚阴伤不能藏魂故不眠，炒熟收敛肝脾津液；生用疏利肝脾血脉。此论药性归经与证治，非脉象。", []], "26117": ["病机", "原文述密蒙花入肝经血分，润肝燥，为搜风散结目疾专药，治青盲昏翳、赤肿多眵泪，消目中赤脉及小儿痘疮余毒、疳气攻眼。其功在润肝燥、散风结，故目疾属肝燥风结者宜之。此段论药性主治，非脉诊。", []], "26118": ["病机", "仲景治消渴脉浮、小便不利微热者，用猪苓散汗之。脉浮主表，消渴而见脉浮、小便不利、微热，为水热互结兼表，故以猪苓疏利经府、引水下行，兼解表邪。原文又诫久服损肾昏目，非泽泻之比，示利水峻剂不可轻投。", ["浮"]], "26119": ["病机", "原文述桑寄生得桑之余气，性专祛风逐湿、通调血脉，治妇人腰痛、小儿背强，血脉通调则肌肤眉发受荫，痈肿亦消。其寓形榕木，与子受母气无异，故为安胎圣药，去崩中产后余疾，亦去风除湿益血补阴之验。此论药性功用，非脉象。", []], "26120": ["治法", "此段论竹叶、竹茹、竹沥三药功用，非论脉。竹叶行肌表疗疮杀虫，竹茹清胃止呕除烦，竹沥透经络治筋脉拘挛、痰在皮里膜外。竹沥纯阴，须姜汁鼓动其势；入附桂剂中能开发湿痰寒饮。舒急与收缓并用，示痰湿阻络、筋脉失养之治法，非脉象所主。", []], "26121": ["其他", "此段述亭长大毒，善通淋及妇人经脉不通，研末服后脐腹急痛，以黑豆汤解之。亭长五六月生，七月为斑蝥，九月为地胆，随时变化，其毒可知。全段言药性毒性及通利血脉之效，未涉脉象，故脉象要素为空，主旨归其他。", []], "26122": ["病机", "此段引《本经》言某药逐瘀血、破血积坚痞症瘕寒热、通利血脉九窍。瘀血内结、血积坚痞症瘕，皆因血脉不通、瘀滞成形所致，故以通利血脉九窍为治。原文未出脉名，脉象要素为空，主旨明瘀血积结之病机。", []], "26123": ["病机", "原文以“涩可以去脱”立论，龙骨入肝敛魂，收敛浮越之气。其治咳逆泄痢脓血、女子漏下，取涩以固上下气血；性涩而能入肝破结，症瘕坚结皆肝经血积。涩脉主收摄固脱，故对应滑脱不禁、气血浮越之证，兼能破肝经血积，为收敛精气要药。", ["涩"]], "26124": ["病机", "此段论龙角禀东方木气，角为督脉所发，故治惊痫瘛疭、神魂不宁。龙火上逆则身热如火，邪魅不祥，深师五邪丸用之，《千金》治心病齿角同用。全段言龙角入督脉、平肝木、清龙火之病机，未出脉名，脉象要素为空。", []], "26125": ["治法", "此段论鱼鳔胶黏固之性，合沙苑蒺藜为聚精丸，为固精要药；一味炒研砂糖调服治痔，经久痔自枯落；烧灰治产后风搐、破伤风痉，取其滋荣经脉而虚风自息。全段述药治精滑、痔疾、虚风之效，未涉脉象，脉象要素为空。", []], "26126": ["病机", "此段论龟禀北方阴气，专行任脉，上通心气，下通肾经，故补阴治血治劳。龟板炙灰益大肠止泄泻，治漏下赤白；滋水坚骨治小儿囟不合；破症瘕痎疟五痔阴蚀湿痹。所主皆阴虚精弱、腰脚酸痿之病机，未出脉名，脉象要素为空。", []], "26127": ["病机", "此段论鳖色青入厥阴肝经及冲脉，为阴中之阳，取支肋为肝经响导。所主痎疟疟母、虚劳寒热、症瘕痞疾、经水阴疮，皆肝经血分之病；骨蒸劳热自汗用之，能滋肝经之火。然究竟是削肝之剂，非补肝药，妊妇忌用，肝虚无热禁之。未出脉名，脉象要素为空。", []], "26128": ["病机", "原文论口颊㖞僻为风中血脉，手足阳明经脉络口、太阳经脉络目，寒则筋急而僻、热则筋缓而纵，左中寒逼热于右、右中寒逼热于左，寒者急热者缓，急者皮肤顽痹、营卫凝滞，故治法急者缓之、缓者急之，用马膏熨急颊。此段无脉象，主述病机与治法。", []], "26129": ["病机", "原文论鹿茸专主伤中劳绝腰痛羸瘦，取其补火助阳、生精益髓、强筋健骨、固精摄便，下元虚人头旋眼黑皆宜。又谓漏下恶血是阳虚不能统阴，寒热惊痫皆肝肾精血不足所致。角乃督脉所发，督为肾脏外垣，外垣固则肾气内充、命门相火不致妄动，扶阳固阴非他草木可比。此段无脉象，主述药性病机。", []], "26130": ["病机", "原文论鹿角生用散热行血、消肿辟邪，熬胶益阳补肾、强精活血，总不出通督脉补命门之用，但胶力稍缓不如茸力峻。茸有交通阳维之功，胶有缘合冲任之用，非助桂通阳不能除寒热惊痫，非龟鹿二胶并用不能达任治羸瘦腰痛，非辅当归地黄不能引入冲脉治妇人血闭胎漏。此段无脉象，主述药性归经病机。", []], "26131": ["病机", "原文论猬为胃之兽，故肉治反胃、胃脘痛最捷，其皮除目中翳障。《本经》主五痔阴蚀，取其锐利破血；酒煮治阴肿痛引腰背，取筋脉能收纵；南方金蚕蛊用猬皮为末酒服探吐；猬脑猬肝治瘰疬狼漏。但不可食其骨，令人瘦劣。此段无脉象，主述药性所主病机与禁忌。", []], "26132": ["病机", "原文论人溺咸寒降泄，疗寒热头痛，客邪冲热以葱头汤服之汗出即止；童子小便性纯，一切热劳吐血、阴虚火动、骨蒸劳瘵用以降火最速；产后血晕温饮压下败血即苏。盖溲溺滋阴降火、消瘀血、止吐衄，须乘热服以接生阳之气，冷则生气散。多服久服损胃滑肠，食少便溏者禁用。此段无脉象，主述药性病机。", []], "26133": ["病机", "原文论脑为髓海、诸阳之会，阴阳乖戾则尸疰之气乘虚袭入，为瘵虫根气。若平昔阳衰，虫攻脊脉，脊中淫淫作痒隐痛、转侧不安、凛凛畏寒或翕翕发热、手足四末常轻，脉来弦细乏力，非天灵盖散不能疗；若素禀阴虚，虫蚀脏腑，嘈杂如饥、时咳时呕、善寐善忘、面时哄热，脉来弦劲搏指，属獭肝丸证。弦细乏力示阳衰，弦劲搏指示阴虚火动。", ["弦", "细"]], "26134": ["病机", "原文论多食咸则脉凝泣而变色，水能克火，故病在心之脉与色；多食苦则皮槁毛拔，火克金，病在肺之皮毛；多食辛则筋急爪枯，金克木，病在肝之筋爪；多食酸则肉胝䐢而唇揭，木克土，病在脾之肉与唇；多食甘则骨痛发落，土克水，病在肾之骨与发。脉凝泣即涩，示咸味太过致血脉凝滞，主心病。", ["涩"]], "26135": ["病机", "原文论人参甘温微苦，大补肺中元气，气旺则脏腑之气皆旺、精生形盛；泻火，烦劳则虚而生热，得甘温益元气而虚热自退；除烦生津止渴、开心益智、聪耳明目、安精神定魂魄、止惊悸、通血脉、破坚积、消痰水，气壮胃开、气和食化，治虚劳内伤。所举脉必浮缓、濡弱等，示虚劳内伤元气不足之脉，主气虚病机。", ["浮", "缓", "濡", "弱"]], "26136": ["病机", "原文载“舌短痰嗽，六脉洪数而滑”，洪数主热盛，滑主痰。脉象洪数而滑，说明痰热壅盛于胸中，气机被阻，故见舌短、痰嗽。以参芦汤涌吐顽痰后脉证得安，反证此脉所主为痰蓄胸中之实邪，非虚劳本脉。", ["洪", "数", "滑"]], "26137": ["其他", "本段未出脉象，专论黄芪甘温之性、生用固表发汗止汗、炙用补中益元气、生血生肌、排脓内托等功效。所主病机为阳气虚衰、表虚不固、脾胃虚弱、疮痈脓成不足及痘证阳虚不起，与脉象无直接关联，故脉象要素为空。", []], "26138": ["其他", "本段未涉脉象，述苍术苦温辛烈，燥胃强脾、发汗除湿、升发胃中阳气，止吐泻、逐痰水、消肿满、辟恶气，为治痿要药。所主病机为湿困脾胃、水饮内停、中气下陷及风寒湿痹，皆从药性功效推衍，原文无脉象描述。", []], "26139": ["其他", "本段未载脉象，论天麻辛温入肝经气分，通血脉、疏痰气，治诸风眩掉、头旋眼黑、语言不遂、风湿痹及小儿惊痫。所主病机为肝木失荣、风痰上扰、筋脉不利。原文特别指出“血液衰少及非真中风者忌用”，强调风药燥血之弊，与脉象无涉。", []], "26140": ["病机", "原文引经曰“痹在于骨则体重，在脉则血涩”，以脉涩言痹之病机。风寒湿三气杂至合而为痹，邪客于脉，血行不畅故涩。秦艽苦燥湿、辛散风，能去肠胃之热、疏肝胆之气、活血荣筋，正对痹证血脉涩滞之机，故脉涩为风湿痹阻、血行不畅之象。", ["涩"]], "26141": ["其他", "本段未出脉象，论柴胡苦微寒、味薄气升，主阳气下陷，能引清气上行，平少阳厥阴邪热，为足少阳胆经表药，治伤寒邪热、痰热结实、心下烦热、诸疟寒热。所主病机为少阳半表半里之邪及清阳不升，全从药性功效立论，无脉象可录。", []], "26142": ["其他", "本段未载脉象，述羌活辛苦性温、气雄而散，入足太阳理游风，兼入足少阴厥阴气分，泻肝气、搜肝风，治风湿相搏、本经头痛、督脉为病脊强而厥、刚痉柔痉、中风不语、头旋目赤。所主病机为风邪外袭、肝风内动、督脉不利，原文无脉象描述。", []], "26143": ["病机", "原文以“脉之缩急”言病机。缩急者，脉道拘紧短缩，主气滞不行、阳气郁遏。升麻甘辛微苦，能升散火郁、升阳气于至阴之下，引甘温之药上行以补卫气而实表。脉缩急反映气滞于中、清阳不升，故用升麻升提，使气上行而后得下降，此即“气升则”之理。", ["缩", "急"]], "26144": ["主病", "原文未出脉名，以丹参性味功效论女科主病。气平味苦色赤入心与包络，破宿血生新血，故主血虚血瘀之候；安生胎堕死胎、调经脉，点明妇人之病首重调经，经调则百病散。所治冷热劳、骨节痛、风痹不随、症瘕，皆由瘀阻血亏、营血不调所致，故以一味丹参功兼四物为女科要药。", []], "26145": ["病机", "原文未出脉名，述元参苦咸微寒入肺肾。其要在“泻无根浮游之火”“清肃而不浊”，故为枢机之剂，管领诸气上下。火热生风则头痛，肺热则鼻疮、利咽喉，火毒不散则心下懊𢙐、烦不得眠，皆浮游之火为病。下水气、通二便、散瘰疬，总由降火滋阴、清肺肾之热而取效。", []], "26146": ["病机", "原文未出脉名，论黄连大苦大寒入心泻火、镇肝凉血、燥湿开郁。所治热毒诸痢、痞满嘈杂、吞酸吐酸、腹痛心痛伏梁，皆湿热郁火为患。原文特言痢有虚实寒热、红白之分“须凭脉证而为凉泻温补”，强调不可拘红热白寒之说，须以脉证定泻火或温补，是本段辨证眼目。", []], "26147": ["病机", "原文未出脉名，论当归甘温和血、辛温散内寒、苦温助心散寒，入心肝脾为血中气药。血和则气降，故治咳逆上气；散寒和血，故治心腹肢节诸痛、跌打血凝。风痉无汗属刚痉，由血虚不能养筋，产后发痉亦然，宜十全大补。冲脉为病气逆里急、带脉为病，皆血虚寒凝、脉失所养之机。", []], "26148": ["病机", "原文未出脉名，论白芍苦酸微寒入肝脾血分，酸敛肝、以敛为泻，故泻肝火、收阴气、敛逆气。肝木不克土则脾安，土旺生金则肺安，腠理乃固。腹痛因营气不从、逆于肉里，白芍调营气、甘草缓中，故芍药甘草汤止痛。泻痢后重、血虚腹痛皆取调营和血，寒泻冷痛则忌用。", []], "26149": ["病机", "原文未出脉名，论川芎辛温升浮，为少阳引经、血中气药。气升则郁自降，故开诸郁、润肝燥而补肝虚；上行头目、下行血海，故搜风散瘀、止痛调经。诸种头痛由经气郁滞、风湿在头所致，须加引经药分经而治。腹痛胁风、气郁血郁、筋挛目泪，皆风木为病、肝郁血滞之候。", []], "26150": ["病机", "原文未出脉名，论丹皮辛苦微寒入心肾厥阴，泻血中伏火。血热则枯、凉则生，故和血凉血而生血；积瘀不去则新血不生，故破积血、通经脉。吐衄因相火所逼、血越上窍；惊痫瘛疭由阴虚血热、风火相搏、痰随火涌。退无汗之骨蒸，亦伏火内灼、阴血受耗之征。", []], "26151": ["病机", "原文未出脉名，论郁金辛苦微甘气寒、性轻扬，入心包兼肺，凉心热、散肝郁、破血下气。吐衄尿血及妇人经脉逆行，乃血不下行、逆而上溢，故用郁金加韭汁、姜汁、童便引血下行。血气诸痛、产后败血攻心、颠狂失心，皆瘀血痰浊塞于心窍所致，白金丸散恶血、化顽痰以开之。", []], "26152": ["主病", "原文未出脉名，以香附为血中气药，通行十二经八脉气分，主一切气。所论九气为病——怒上、恐下、喜缓、悲消、惊乱、思结、劳耗、寒收、热泄——皆气机失常之病机，故以香附为君随证加减。其治多怒多忧、痰饮积聚、痞满腹胀、霍乱吐泻及痈疽疮疡，均属气滞血凝、六郁不通所致，非凭脉断证。", []], "26153": ["病机", "原文未出脉名，述药性辛苦而温，为三焦气分之药，能升降诸气、泄肺气、疏肝气、和脾气。所论诸气𪱥郁皆属于肺、中气不运皆属于脾、大肠气滞则后重、膀胱气不化则癃闭、肝气郁则为痛，皆就气机郁滞立论，说明上中下三焦气滞之病机，故治一切气痛、呕逆反胃、霍乱泻痢后重。", []], "26154": ["主病", "原文未出脉名，言药辛热，流行三焦、温暖脾胃，为肺家本药，散滞气、消酒积、除寒燥湿、化食宽膨。所治脾虚疟疾、感寒腹痛、吐逆反胃、白睛翳膜、太阳经目眦红筋，皆寒湿滞气、肺滞不散之候；又明言火升作呕、因热腹痛及气虚诸证咸宜禁之，示其温燥只宜寒湿实证。", []], "26155": ["主病", "原文未出脉名，以色白味辛、性温气厚、芳香上达，归手阳明大肠、足阳明胃、手太阴肺三经，故主治不离三经。通窍发汗、除湿散风，治头目昏痛、眉棱骨痛、牙痛、鼻渊、目痒泪出，皆风热与痰湿上攻头面之病机；引阳明之脉萦于面、肺主鼻、脑渗为涕，说明药性走上焦头面。", []], "26156": ["主病", "原文未出脉名，述药辛温雄壮，为太阳经风药，寒郁本经、头痛连脑者必用之。治督脉为病脊强而厥、妇人疝瘕阴寒肿痛、腹中急痛，皆太阳经寒湿为患；又引胃风泄泻案，说明风客于胃。末言头痛挟内热及伤寒发于春夏阳证头痛不宜进，示其辛温只宜寒郁，不可概投。", []], "26157": ["病机", "原文未出脉名，言药辛苦而温、芳香而散，入肝经气分兼行血分，性升浮能发汗、散风湿、利咽喉、清头目。治伤寒头痛、中风口噤、身强项直、口面㖞斜，皆风邪袭经之候；又治吐衄肠风、崩中血痢、产风血晕，说明其能散血中之风，故为风病血病、疮家圣药，紧扣气血同病之机。", []], "26158": ["病机", "原文未出脉名，言药甘而微温，入足三阴经，滋肾水、封填骨髓、补益真阴、聪耳明目，又能补脾阴止久泻。所论久泻多属肾虚、下多亡阴自宜补肾，及阴亏发热、干咳痰嗽、气短喘促，皆真阴亏虚、相火上升之病机；引丹溪补血制相火、喻嘉言不补其下必气脱之说，申明虚损咳嗽当求其本。", []], "26159": ["主病", "原文出脉绝短气、脉散，言药甘微苦微寒，润肺清心、泻热除烦、化痰行水、生津止嗽。脉绝短气由心主脉、肺朝百脉，热伤元气则气充脉复，故同人参五味名生脉散，脉绝将死者服此能复生。又论午前嗽多属胃火、午后及夜重多属阴虚，痿躄由阳明湿热上蒸于肺、肺热叶焦，皆就肺胃阴虚有热立说。", ["散"]], "26160": ["病机", "原文虽以麻黄药性为主，但引“脉沉迟者、六脉不浮紧者”作为辨证要点。沉迟脉主里寒，提示寒邪内侵、阳气不足，与伤寒头痛、恶寒无汗相应。麻黄辛温发汗解表，去营中寒邪，正针对寒邪闭表、营卫不行之病机。脉不浮紧说明表寒不盛，故用麻黄需审慎。", ["沉", "迟"]], "26161": ["其他", "本段未识别脉名，主述益母草药性功效。其味辛微苦微寒，入手足厥阴，消水行血、去瘀生新、调经解毒，治血风血晕、血痛血淋、胎漏产难、崩中带下等。性辛散滑利，全无补益，瞳神散大者忌。全段以药论为主，未涉及脉象与病机分析。", []], "26162": ["其他", "本段未识别脉名，论述青蒿（推测）苦寒入少阳厥阴血分，治劳瘦骨蒸、蓐劳虚热、久疟久痢、虚烦盗汗、风毒热黄等。能除骨髓之热、阴分伏热，并及鬼气尸疰诸证。全段以药性功效为主，未涉及脉象与病机。", []], "26163": ["其他", "本段未识别脉名，述王不留行甘苦而平，性行而不住，走血分通血脉，为阳明冲任之药。除风去痹、止血定痛、利便通经、催生下乳，治金疮痈疮疔疮。失血后、崩漏家及孕妇忌之。全段以药论为主，未涉及脉象与病机。", []], "26164": ["其他", "本段未识别脉名，述旋覆花苦辛咸微温，下气行水、软坚通血脉，入肺大肠经。消痰结坚痞、唾如胶漆、噫气不除，治大腹水肿、风气湿痹。为走散之药，冷利大肠，虚人禁之。全段以药性功效为主，未涉及脉象与病机。", []], "26165": ["其他", "本段未识别脉名，述续断苦辛微温，补肝肾、通血脉、理筋骨。主劳伤，暖子宫、缩小便、止遗泄、破瘀血，治腰痛胎漏、崩带肠风血痢、痈痔肿毒、金疮折跌。女科外科需为上剂，补而不滞、行而不泄。全段以药论为主，未涉及脉象与病机。", []], "26166": ["病机", "原文引吴绶言附子为阴证要药，凡伤寒传变三阴、中寒夹阴，身虽大热而脉沉细，或厥冷腹痛、唇青囊缩，急须用之。脉沉细主里虚寒盛，脉七八至为虚阳外越之数，按之则散示阳气欲脱。此脉象揭示阴寒内盛、虚阳浮越之病机，与身大热、厥冷腹痛相应。", ["沉", "细", "数", "散"]], "26167": ["其他", "本段未识别脉名，述白附子辛甘大热纯阳，阳明经药，引药势上行，治面上百病、祛风痰、心痛血痹、诸风冷气、中风失音、阴下湿痒。为燥毒之品，似中风证虽有痰亦禁用，小儿慢惊勿服。全段以药性功效为主，未涉及脉象与病机。", []], "26168": ["病机", "原文言“弦脉主痰饮，故曰疟脉自弦”，指出弦脉为痰饮内伏之象。疟疾必有黄涎聚于胸中，痰饮积于少阳，气机不畅，故脉见弦。常山能引吐行水，祛老痰积饮，截疟取效，正因痰饮为疟之根。此段以弦脉明痰饮致疟之病机，非单纯主疟。", ["弦"]], "26169": ["病机", "原文未出脉名，然论水气为病，谓“胃为水谷之海，五脏六腑之源”，脾不散精，肺不通调，肾不司关，致积水浸淫。又言“脉有尺寸之殊，浮沉之别”，提示水病脉象随部位深浅而异，当辨病在何经何脏。此段重在阐发水湿内停、三焦失司之病机，非以某脉主病。", []], "26170": ["主病", "原文点明“六脉沉实者”，沉主里，实主邪盛，为燥结瘀热内蕴肠胃之征。大黄大苦大寒，性沉而不浮，走而不守，荡涤肠胃，下燥结除瘀热，正对脉沉实之里实证。伤寒发热谵语、下痢腹痛里急、黄疸水肿等，皆由实热燥结所致，故以沉实脉为凭。", ["沉", "实"]], "26171": ["其他", "原文未及脉象，专述甘辛温之药入足三阴，强阴益精，温而不燥，治五劳七伤、溺有余沥、寒精自出等。其“补卫气，助筋脉，益气力”之功，针对下元虚衰、卫气不固之证。末言“肾家多火，强阳不痿，大便燥结者忌之”，提示虚寒者宜、火旺者禁，属药性主治与禁忌之论。", []], "26172": ["病机", "原文未出脉名，论甘淡平之药祛湿热、利筋骨、利小便止泄泻。杨梅疮毒多属阳明厥阴，医用轻粉劫剂，致毒气窜入经络筋骨，血液枯槁，筋失所养，变为拘挛痈漏。此段揭示湿热蕴结、血燥筋枯之病机，土茯苓能制轻粉之毒，去阳明湿热，故治拘挛疮肿。", []], "26173": ["病机", "原文未出脉名，述辛甘淡平之药上通心包、降心火、清肺热、化津液，下通大小肠膀胱，导湿热由小便出。引东垣“肺受热邪，津液气化之源绝，则寒水断流；膀胱受湿热癃闭约束，则小便不通”，阐明上焦热壅、下焦湿闭、气化不行之病机，火退则小便自利。", []], "26174": ["其他", "原文未及脉象，论甘平之药入厥阴血分，生用性滑，行血消瘀，通经脉，利小便，祛心腹膀胱之热，疗扑损疮肿；炒黑性涩，止一切血、崩带泄精。所举舌胀满口案，以蒲黄掺之而愈，说明凉血活血之效。末言“无瘀者勿服”，提示血瘀者宜、无瘀者禁。", []], "26175": ["其他", "原文未出脉名，述辛平之药通流血脉，能散血止血，治金刃扑损出血、血痢、下血崩中、女子阴疝血结及痈肿恶疮。时珍称其专治血病，俗名血竭。末言“非血滞血瘀勿用”，强调此药以血瘀血滞为的，无瘀者不可妄投，属药性主治与禁忌之论。", []], "26176": ["治法", "原文述“大燥、补命门火、平肝通血脉、引火归元”，虽未出脉名，然其治法针对命火不足、肝风内动、虚火上浮之病机。补命门火以复蒸化，平肝则血脉通，引火归元使无根之火降纳，故脉当见沉细弱或浮大无根，症见痼冷、上热下寒。", []], "26177": ["病机", "原文言“补命门相火之不足”“益阳消阴”“引无根之火降而归元”，明示命火衰微、阴寒内盛、虚阳上浮之机。火衰则蒸化无力，故痼冷沉寒、下焦腹痛、奔豚疝瘕；虚阳上浮则上热下寒、格阳喉痹。脉当沉迟微弱，或浮大无力。", []], "26178": ["病机", "原文述桂枝“温经通脉、发汗解肌”“调和营卫”，其机在营弱卫强、风邪袭表。卫强则发热汗出，营弱则汗出而营阴不足，故以桂枝发汗调营，使卫气自和、邪从汗解。脉当浮缓，症见头痛、自汗、恶风。", []], "26179": ["病机", "原文言“助胃中清阳上行，通于头脑”“辛香走窜”，其机为胃中清阳不升、风热上扰清窍。清阳不升则九窍不利，风热客于脑则鼻渊鼻塞、头痛面䵟、目眩齿痛。脉当浮缓或浮数，虚人禁之，血虚火炽者服之转甚。", []], "26180": ["病机", "原文以“口噤脉伏，身温为中风，身冷为中气”辨中风与中气。脉伏乃气机逆乱、痰气壅塞、阳气不达所致。气顺则风散，故用乌药疏胸腹邪逆之气。若老人卒倒、无痰气阻滞而脉伏，则属气血颓败、阴阳脱离，当大补固脱。", ["伏"]], "26181": ["病机", "原文述冰片“通诸窍、散郁火”“风病在骨髓者宜之”，其机为诸窍闭塞、郁火内伏、风邪深入骨髓。辛香走窜能透骨通窍，散郁火而聪耳明目，治惊痫痰迷、喉痹齿痛。若风在血脉肌肉而辄用，反引风入骨；目不明属虚者不宜点。", []], "26182": ["病机", "原文以“尺脉洪大”示下焦相火亢盛。苦寒沉降之品泻膀胱相火，火退则肾固。相火妄动则骨蒸劳热、诸痿瘫痪、目赤耳鸣、消渴黄疸、水肿便闭。尺脉洪大正是相火不藏、湿热下注之征，故以二妙散清热利湿治痿。", ["洪", "大"]], "26183": ["病机", "原文述皂荚“性极尖利，搜风泄热”“通上下关窍而涌吐痰涎”，其机为风痰壅塞关窍。搐鼻作嚏则肺气尚通，无嚏为肺气已绝。中风口噤、胸痹喉痹皆痰涎闭阻，故取吐法宣壅导滞；然年老气虚者忌用，恐涌吐伤正。", []], "26184": ["其他", "本段述皂角刺辛温搜风杀虫、溃散痈疽之功，未及脉象。原文'锋锐直达病所'言其药性峻利，善走窜以攻毒；'脉风成为疠'引经说明疠风乃营气热而风寒客于脉中不去，血分受邪，故取此药入血搜风。所主为痈疽肿毒、妒乳、疠风、癣疮等外科血分壅滞之证，非论脉诊。", []], "26185": ["其他", "本段述榆白皮甘平滑利、通二便利诸窍之效，未涉脉象。'滑可去著'为十剂之义，言其滑利之性可去有形留著之物，故治五淋肿满、赤肿妒乳。'行经脉''渗湿热'点明治在湿热壅滞、经脉不利，与脉诊无直接关联，属药性主治之论。", []], "26186": ["病机", "原文'产后去血多、气随血去、脉微神倦、口鼻气冷、胸腹无滞而晕者'，脉微为气血大虚、阳气衰微之象，神倦气冷皆虚脱之候，故主败血乘虚入肺或血去气脱之晕，治宜独参汤固脱。此与败血上冲实证之胀满欲死相对，一虚一实，脉微正是辨虚脱之关键。", ["微"]], "26187": ["病机", "原文载一妇溏泻五载，投生冷即痛，服升涩药泻反甚，'脉沉而滑'。沉主里，滑主痰食积滞，沉滑相合说明积食凝滞于脾胃之久，非虚寒单纯可解，故法当以热下之，用蜡匮巴豆丸。此脉正是辨积滞内实、当攻之据，与升涩误治相对照。", ["沉", "滑"]], "26188": ["病机", "原文'治虚羸五缓'，自注'五脏筋脉缓纵'，脉缓纵即筋脉弛缓无力之象，由肝肾虚而风湿客之、精血不养筋骨所致。五加辛以顺气化痰、苦以坚骨益精、温以祛风胜湿，正对虚羸而筋脉缓纵之病机；若下部无风寒湿而肝肾有火者则忌，示此脉非火证。", ["缓"]], "26189": ["其他", "本段述蔓荆子类药苦辛平、轻浮升散搜风、通利九窍之功，未及脉象。原文'头痛目痛不因风邪而因血虚有火者忌之'，说明所主为风邪上攻头面之证，与血虚火旺者当别。属药性主治与禁忌之论，无脉象可录。", []], "26190": ["其他", "本段述密蒙花甘微寒、润肝燥、治目中赤脉青盲肤翳之效，未涉脉象。'润肝燥'点明所主为肝燥血热、目失濡养之目疾，故治赤脉赤肿羞明；小儿疳气攻眼亦属肝热上攻。全段为药性主治，无脉诊内容。", []], "26191": ["其他", "本段述桑寄生苦坚肾、甘益血，助筋骨固齿、止崩漏安胎、舒筋络除痹痛之效，未及脉象。原文'和血脉而除痹痛''胎动腹痛'示其所主为肝肾不足、血脉不和之痹与胎动，属药性主治范畴，无脉象可辨。", []], "26192": ["病机", "原文以“脉浮属气、脉沉属血”分气血之秘：浮脉应气分，气秘则昼便难，故用杏仁陈皮降肺利气；沉脉应血分，血秘则夜便难，故用桃仁陈皮润燥行血。肺与大肠相表里，贲门魄门为气之通道，脉之浮沉正辨便秘在气在血，非泛言虚实。", ["浮", "沉"]], "26193": ["病机", "本段未出脉名，以“苦以泄血滞，甘以缓肝气而生新血”立论。肝为血之源，血聚则肝气燥，故用桃仁通大肠血秘、治热入血室及血燥血痞。所主在血瘀血燥之病机，若“非血瘀而误用之，大伤阴气”，明示辨证关键在血瘀有无，非凭脉象。", []], "26194": ["病机", "原文未识脉名，以“酸涩、甘温生津”言药性。酸涩能收，甘温能生津，故治消渴泄精水痢，取收敛固涩、生津止渴之义；小儿闪癖瘰疬瘦弱，亦取酸收软坚。末言“多食发热，闭百脉”，指出过用酸涩则壅遏气机、闭阻百脉，是从反面说明其收涩之性。", []], "26195": ["病机", "本段无脉名，论胡桃“味甘性热，肉润皮涩”，通命门、利三焦、润肠胃、温肺补肾。所主在命门火衰、三焦不利、肺肾两虚之病机，故治痿强阴，佐补骨脂以木火相生大补下焦。原文以“命门为藏精系胞之物，三焦为出纳腐熟之司”阐其体用，非脉象所主。", []], "26196": ["病机", "原文未出脉名，以“辛大热，有毒”论椒性。入肺发汗散寒，入脾暖胃燥湿，入右肾命门补火，故主风寒咳嗽、心腹冷痛、痰饮水肿、阳衰泄精溲数等症。其“能下行，导火归元”点明病机在命门火衰、寒湿内盛；阴虚火旺者大忌，示寒热辨证之要。", []], "26197": ["病机", "本段无脉名，论吴茱“辛苦大热，疏肝燥脾，温中下气，除湿解郁”。所主在厥阴肝寒、脾胃湿郁之病机，故治厥阴头痛、阴毒腹痛、呕逆吞酸、奔豚症瘕。原文“冲脉为病，气逆里急，宜此主之”，点明冲脉气逆；又“性虽热而能引热下行”，示其降逆之功。", []], "26198": ["病机", "原文未识脉名，论葱白“辛散而平，发汗解肌，通上下阳气”。所主在阳气郁遏、上下不通之病机，故仲景白通汤、通脉四逆汤加之以通脉回阳，面赤格阳于上者尤须用之。原文“气通则血活，气为血帅”，说明通阳即所以行血，故治吐血衄血、折伤出血。", []], "26199": ["病机", "本段极简，仅言“燥、温经逐寒、宣、发表通脉”，未出脉名。所主在寒邪外束、经脉凝滞之病机：燥能胜湿，温经逐寒则寒凝可散，宣发表通脉则阳气外达。此以药性反推寒凝脉滞之证，非直接论脉，故脉象要素从缺。", []], "26200": ["治法", "原文未言脉，专述干姜辛热之性：逐寒邪、发表温经、燥脾湿、定呕消痰，开五脏六腑、通四肢关节、宣诸络脉，治冷痹寒痞、反胃下利、腹痛症瘕积胀。其病机核心为寒邪困阻、脾湿不运、络脉不通，故以辛热之品温散宣通，属治法类而非脉诊。", []], "26201": ["病机", "原文未出脉象，论炮姜辛苦大热，除胃冷而守中，去脏腑沉寒锢冷，使阳生阴长，故吐衄下血有阴无阳者宜之；又引血药入气分生血，治血虚发热、产后大热，乃阴虚阳无所附、热因热用从治之法。能回脉绝无阳，通心助阳补心气，所主在沉寒锢冷、阳虚血弱之病机。", []], "26202": ["主病", "原文未言脉，述茴香辛温暖丹田、补命门、开胃下食、调中止呕，疗小肠冷气、𤻊疝阴肿、腹痛霍乱、干湿脚气。疝属肝经病，因寒湿所致，亦有挟虚者，当加参术于温散药中。所主为下焦命门火衰、寒湿凝滞肝脉之疝痛霍乱，并戒阳道数举、得热则吐者。", []], "26203": ["其他", "原文仅一句「一名菠蔆。通脏腑血脉」，未及脉象与症候，属本草条目之简录。其主旨言菠菜能通脏腑血脉，为药性功用之记述，非脉诊病机之论，故归其他类，脉象要素无从取字。", []], "26204": ["其他", "原文未出脉象，述甘温滑微毒之品利五脏、通血脉、开胸膈、解酒毒、宣肠胃热、下气调中、止渴润燥，根尤良。所论为药性功用与主治，涉及血脉不通、胸膈壅塞、肠胃热结等，然全段无脉象描述，故脉象要素为空，主旨归其他。", []], "26205": ["其他", "原文未言脉，述苦寒之品利五脏、通经脉、开胸膈壅气、解热毒酒毒、止渴利肠，并附鱼脐疮以针刺破头、滴白苣汁之治法。全段为药性主治与外治方，虽涉经脉壅气、热毒，然无脉象可录，故脉象要素为空，主旨归其他。", []], "26206": ["其他", "原文极简，仅载丝瓜一名天罗、一名蛮瓜，通经脉、凉血解毒、除风化痰，未及脉象与具体症候。属本草药性功用之记述，主旨不在脉诊病机，故脉象要素为空，归其他类。", []], "26207": ["病机", "原文未出脉象，述老丝瓜甘冷，凉血解毒、除风化痰、通经络、行血脉，以其筋络贯串象人经脉，故借其气以引之；消浮肿、发痘疮、治肠风崩漏疝痔痈疽、滑肠下乳。所主为血热风痰阻络、经脉不通之病机，取象比类以通血脉。", []], "26208": ["病机", "原文未出脉名，以甘平滑利之药性论治阳明胃热汗多便难。汗多则精枯，肠失濡润而大便愈燥，故用麻仁之甘缓脾润燥。又言多食损血脉、滑精气、痿阳事，因其滑利下行、走而不守，肠滑者尤忌，提示津亏肠燥与滑泄之弊。", []], "26209": ["病机", "原文未出脉名，述大麦甘咸微寒，补虚劣、壮血脉、实五脏、益气调中、除热止泄、疗消渴。其性凉滑腻，能助胃气，故缠喉风食不能下者以稀糊咽之而平。所主在脾胃虚劣、血脉不充、热泄消渴之机，非脉象所主。", []], "26210": ["病机", "原文未出脉名，论肾之谷甘平，补五脏、暖肠胃、调中、助十二经脉。思邈谓肾病宜食，是取其入肾补虚、温暖肠胃以调中气。所主为五脏虚损、肠胃寒冷、经脉失养之机，全段为食治性味功用，不涉脉候。", []], "26211": ["病机", "原文未出脉名，述石膏甘辛而淡、体重而降，入足阳明胃经，为大寒之药，色白入肺兼入三焦。寒能清热降火，辛能发汗解肌，甘能缓脾生津。故治伤寒郁结无汗、阳明头痛、日晡潮热、阳狂壮热、大渴引饮、中暑自汗、舌焦牙痛，并为发斑疹要品，主阳明胃热与肺热之机。", []], "26212": ["病机", "原文未出脉名，论盐咸甘辛寒，咸润下故通大小便，咸走血而寒胜热故治目赤痈肿血热，咸补心故治心虚，咸入肾而主骨故坚筋骨、治骨病齿痛。引病笑不休用盐炒赤煎饮而瘳，取水制火、既济之义，所主为血热、心火、肾虚骨病之机。", []], "26213": ["病机", "原文未出脉名，论新汲井华水凉能清热、甘可助阴，宜煎补阴药及气血痰火药，解热闷烦渴。并辨水源高下，城市沟渠污水杂入成咸者须煎滚澄停方用。所主为热闷烦渴、阴亏火旺之机，属水类治病之性用，不涉脉象。", []], "26214": ["病机", "原文出「关上脉浮」，属心下痞、按之濡之候。浮主阳热郁于上焦气分，故仲景用大黄黄连泻心汤，以麻沸汤渍之，取其气薄而泄虚热。热汤助阳气、行经络，风冷气痹淋脚取汗，暴泻痢脐腹冷坐汤生阳，皆假阳气以行，与关上浮脉泄虚热之机相印。", ["浮"]], "26215": ["病机", "原文未出脉名，论阴阳水调中消食、治霍乱吐泻。时珍谓三焦通利、阴阳调和则脏腑畅达，一失其道则浊阴不降、清阳不升，发为霍乱呕吐，饮此汤分其阴阳使得其平。又戒仓卒脉候未审，慎勿轻投偏热偏寒之剂，服姜汤有立毙者，唯阴阳水最稳。", []], "26216": ["治法", "本段未言脉，专述灯心蘸麻油点灯淬络脉盛处治小儿惊风昏迷搐搦窜视，及头风胀痛。其理在“油能去风解毒，火能通经”，以火气通经、油解风毒，使络脉通而风止。又治小儿冒寒欲绝，用灯火燎脐下使暖气入腹、气回自苏，属外治通阳救急之法，非凭脉辨证。", []], "26217": ["治法", "本段未及脉象，论灸法用火之宜忌。主张灸诸风冷疾入石硫黄末少许更妙，艾火宜取阳燧火珠承日取太阳真火，次用槐火，急则麻油灯或蜡烛火点艾。强调金石钻燧之火不可用，并引火无体、因物为体之说，述松柏桑柘枣橘榆竹诸火各有伤损，全属灸治取火之法则。", []], "26218": ["病机", "本段未言脉，述黄土甘平治泄痢冷热赤白、腹内热毒绞结痛、下血及解诸药毒。引钱乙黄土汤愈皇子瘛疭，对曰“以土胜水，水得其平，则风自退尔”，点明土能制水、水平风息之病机；又载张锐用路行黄土温酒搅服下马蝗，示土能解毒杀虫，皆从五行制化立论。", []], "26219": ["病机", "本段未涉脉，论五灵脂甘温纯阴、气味俱厚，入肝经血分，通利血脉、散血和血，生用通血闭、炒用止经多，治血痹血积、血眼血痢、肠风崩中诸血病及心腹气血诸痛，除风杀虫化痰消积。引李仲南说崩中乃冲任经虚被风袭伤营血所致，五灵脂为去风之剂，与荆芥防风治崩义同，明血虚夹风之机。", []], "26220": ["病机", "本段未言脉，论猪肉咸寒，疗肾气虚竭、狂病久不愈，食之润肠胃、生精液、丰肌体、泽皮肤；其性阴寒，阳事弱者勿食，能生湿痰、易招风热，伤风寒及病初起尤为大忌。原注指出忌之者以其补肌固表、油腻缠黏，外邪不能解散；病初愈忌之者以肠胃久枯难受厚味，并辨生痰惟风痰湿痰寒痰忌之，燥痰干咳正宜滋润。", []], "26221": ["病机", "本段未及脉，论鹿角咸温，生用散热行血消肿，醋磨涂肿毒、酒服治折伤；引医余说臁疮赤肿久用凉药不愈者当用温药，阐阴阳暑寒往来之理。熬膏炼霜则专滋补，益肾生精血、强骨壮腰膝。时珍谓鹿纯阳多寿、能通督脉，头为诸阳之会、钟于茸角，示其温补通阳之性。", []], "26222": ["病机", "本段未言脉，述獭肝甘咸而温，止嗽杀虫，治传尸鬼疰有神功。引葛洪言尸疰鬼疰使人寒热、沉沉默默、不知病之所苦、积月累年传人乃至灭门，用獭肝阴干为末水服；鹤皋谓獭阴物昼伏夜出故治鬼疰。獭肉甘咸寒，治骨蒸热劳、血脉不行、营卫虚满、女子经络不通、血热秘结，不宜多食、消男子阳气。", []], "26223": ["病机", "本段未言脉，论鳝甘大温，补五脏、除风湿；尾血疗口眼㖞斜，左㖞涂右、右㖞涂左，滴耳治耳痛、滴鼻治鼻衄、点目治痘后生翳。时珍谓鳝善穿穴与蛇同性，故能走经络、疗风邪及诸窍之病，风中血脉用血主之、从其类也；头烧研塞耳治百虫入耳，皆取走窜通窍之性。", []], "26224": ["其他", "此段为乌贼骨别名与功效总述，未涉脉象。原文称其“宣、通血脉、祛寒湿”，是从药性角度说明其能宣通血脉、祛除寒湿之邪，故所主当为寒湿阻络、血脉不通之证，而非据脉断病。无脉象可析，故脉象要素为空。", []], "26225": ["病机", "此段论乌贼骨咸走血、温和血，入肝肾血分，通血脉、祛寒湿，主治血枯、吐衄、肠风崩漏、久虚泻痢、腹痛环脐、阴蚀肿痛等。其病机核心为寒湿伤血、血枯络阻，故以咸温入血之品通脉祛湿。原文引《内经》“血枯治之以乌鲗骨”，正说明血枯与寒湿闭阻相关，非脉象所主。", []], "26226": ["病机", "此段论龟甲咸寒至阴，属金与水，补心资智、益肾滋阴，治阴血不足、劳热骨蒸、腰脚酸痛、久泻久痢、久嗽痎疟、症瘕崩漏、五痔产难。其病机为阴虚血弱、虚热内生，故以滋阴清热之品治之。原文强调“虽肾虚而无热者勿用”，说明其主阴虚有热之证，非据脉象而言。", []], "26227": ["病机", "此段论紫河车甘咸温，本人之血气所生，故大补气血，治一切虚劳损极，包括五损六极、恍惚失志、癫痫由膀胱虚者。其病机为气血大亏、脏腑虚损，故取“以胞补胞”之义。原文列五损六极具体症候，说明所主为虚劳损极之候，非脉象所主，脉象要素为空。", []], "26228": ["病机", "此段引《用药法象》，以五行五气论药性升降收散，提出“气坚则壮故苦可以养气，脉䎡则和故咸可以养脉”，又言“坚之而后可以䎡，收之而后可以散”。其核心病机在于脉气坚急或弛缓失和，故以苦坚、咸软调之。原文“脉䎡则和”正说明脉软为和，坚则为病，属药性理论中的病机推演。", ["坚", "软"]], "26229": ["其他", "此段论《本经》三品分类及君臣佐使、七情合和之法，属药学总论，未涉脉象与具体病机。原文以上药养命应天、中药养性应人、下药治病应地，说明用药须斟酌有毒无毒、相须相使相恶相反。所主为药物配伍原则，非脉象所主病机，故脉象要素为空。", []], "26230": ["病机", "此段论丹砂主身体五脏百病，养精神、安魂魄、益气明目，通血脉、止烦满消渴、益精神、悦泽人面，除中恶腹痛、毒气疥瘘诸疮。其病机为心神不安、血脉不通、热毒内扰，故以丹砂安神通脉、清热解毒。原文“通血脉止烦满”点明血脉不畅与烦满相关，非据脉象而言。", []], "26231": ["病机", "此段论玉泉主五脏百病，柔筋强骨、安魂魄、长肌肉、益气，利血脉、疗妇人带下十二病、除气癃、明耳。其病机为脏腑失养、血脉不利、气机壅闭，故以玉泉柔筋益气、利脉通癃。原文“利血脉疗妇人带下”说明血脉不利与带下、气癃相关，属药效所主病机，非脉象所主。", []], "26232": ["其他", "本段为硝石的本经与名医所录，述其主五脏积热、胃胀闭、涤去蓄结饮食、推陈致新，并载疗百二十疾、暴伤寒、腹中大热等。原文无脉象描述，故脉象要素为空；主旨属药物主治与炮制鉴别，非脉学病机，列其他。", []], "26233": ["其他", "本段述芒硝主五脏积聚久热、胃闭、破留血、腹中痰实结搏、通经脉利大小便及月水，并载其性寒泄、味厚于气。原文未及脉象，故脉象要素为空；内容为药性主治与产地修治，不涉脉诊，列其他。", []], "26234": ["其他", "本段述石胆主明目目痛、金疮诸痫痉、女子阴蚀痛、石淋寒热、崩中下血，能化铁为铜。原文无脉象记载，脉象要素为空；主旨为药物主治与产地鉴别，非脉学病机分析，列其他。", []], "26235": ["其他", "本段述空青主青盲耳聋、明目利九窍、通血脉养精神，益肝气疗目赤痛、去肤翳止泪出、利水道下乳汁、破坚积。原文未述脉象，脉象要素为空；内容属药物主治与产地形状，不涉脉诊，列其他。", []], "26236": ["其他", "本段杂述晕石主石淋、流黄香去恶气除冷杀虫、白师子压伏白虎病、玄黄石主惊恐身热邪气镇心。原文无脉象描述，脉象要素为空；主旨为诸石诸香主治及厌伏之法，非脉学病机，列其他。", []], "26237": ["主病", "本段首标脉洪大口舌干燥头痛大渴，洪大为热盛之象，热灼津伤则口舌干燥、大渴引饮，热壅于上则头痛。石膏主中风寒热、心下逆气惊喘、口干舌焦不能息，正取辛寒清泄阳明气分大热，与洪大脉、大渴、头痛相应，故列主病。", ["洪", "大"]], "26238": ["其他", "本段述方解石主胸中留热结气、黄疸、通血脉、去蛊毒，并载其性大寒泄、味苦辛、恶巴豆、捣末水飞。原文无脉象记载，脉象要素为空；内容为药物主治、性味与修治，不涉脉诊，列其他。", []], "26239": ["其他", "本段述长石主身热四肢寒厥、利小便通血脉、明目去翳眇、下三虫杀蛊毒，又主胃中结气、止消渴下气。原文未载脉象，脉象要素为空；主旨为药物主治与长石、理石、石膏之鉴别，非脉学病机，列其他。", []], "26240": ["主病", "原文为理石药性记载，未涉脉象。其味辛甘、性大寒，主身热、利胃解烦、益精明目、破积聚、去三虫，又除营卫中去来大热结热、解烦毒、止消渴及中风痿痹。所主病机为热邪结聚、营卫不和、积块内生，故以寒凉之石药清热破结、通利胃气，非凭脉断病。", []], "26241": ["主病", "原文述金屑产地、真伪及药用，未及脉象。金屑主镇精神、坚骨髓、通利五脏、除邪毒气，其病机在神志浮越、骨髓不坚、五脏邪毒内扰。取金之重镇沉降以安神定志、坚骨通脏，属药性主病之论，非脉诊内容。", []], "26242": ["主病", "原文载灵砂升炼之法及主治，未涉脉象。灵砂主五脏百病、养神安魂魄、益气明目、通血脉、止烦满、益精神、杀精魅恶鬼气，其病机为五脏虚损、神魂魄不安、血脉不通、烦满内生。以二气砂镇养安神、通脉除烦，属药治主病。", []], "26243": ["主病", "原文食盐条中夹有“脉及大脉血出不止者、大脉”之语，脉象要素取大脉。大脉主邪盛或血出不止，此段以食盐主杀鬼蛊邪疰毒气、下部䘌疮、伤寒寒热、吐胸中痰癖、止心腹卒痛、坚肌骨，其病机在邪毒内盛、痰癖结聚，大脉示邪实，故取咸寒之盐以软坚解毒。", ["大"]], "26244": ["主病", "原文列鼠壤土、屋内壖下虫尘土、鬼屎、寡妇床头尘土、床四脚下土、瓦甑、甘土、柱下土等主治，未涉脉象。诸土所主为中风筋骨不随、冷痹骨节疼、手足拘急、偏枯死肌、恶疮久不瘥、反花疮、魇寐不寤、腹痛暴等，病机多属风冷痹阻、疮毒不敛、痰魇闭窍，属外治与药治主病。", []], "26245": ["主病", "原文述赤铜屑以醋和袋盛、先刺腋下脉去血封之攻腋臭，又熬热投酒服主贼风反折，未识别脉名。其病机为腋下血络郁毒、贼风入中致筋脉反折，故刺脉去血以泄郁毒，赤铜屑性利能焊入骨、主折伤，属外治与药治主病。", []], "26246": ["主病", "原文载代赭主鬼疰贼风蛊毒、杀精物恶鬼、腹中毒邪气、女子赤沃漏下、带下百病、产难胞衣不出、堕胎养血气、除五脏血脉中热、血痹血瘀、惊气入腹及阴痿不起，未涉脉象。病机为邪毒内结、血热瘀阻、血气不养，取代赭重镇凉血、破瘀下胎。", []], "26247": ["主病", "原文述菊花水出南阳郦县北潭，主除风补衰、久服不老、好颜色、肥健益阳道、温中去痼疾，未涉脉象。所举胡广患风羸、诸公患风痹眩冒皆饮此水得愈，病机属风邪久羁、气血衰少、痼疾内伏，以甘菊水除风补衰、温中益阳，属药治主病。", []], "26248": ["其他", "本段为井水、雨水、生熟汤等食疗方，非脉诊内容。原文虽标'屋漏'脉象写法，但正文无脉象描述，仅述霍乱烦闷、转筋、消渴反胃等症及饮水、灸脊骨治法，故脉象要素为空，主旨归其他。", []], "26249": ["其他", "本段为菊花本草条文，述其主风头眩肿痛、目欲脱泪出、皮肤死肌、恶风湿痹，及疗腰痛、除胸中烦热、利五脉调四肢。原文未识别出脉名，无脉象描述，主旨为药物主治而非脉诊病机，故归其他。", []], "26250": ["病机", "原文标'脉破坚积令人不忘、脉散夏月服之以救肺金生化之源'，以人参通血脉、破坚积，对应脉见破积之象；夏月脉散，为肺金生化之源不足，故用人参补五脏、安精神以救之。脉破主积，脉散主气耗，皆示人参补益通破之功。", ["破", "散"]], "26251": ["其他", "本段为甘草本草条文，述其主五脏六腑寒热邪气、坚筋骨、长肌肉、解毒、温中下气、止渴通经脉利血气、解百药毒等。原文未识别出脉名，无脉象描述，主旨为药物功用，故脉象要素为空，归其他。", []], "26252": ["其他", "本段为干熟地黄本草条文，述其主折跌绝筋、伤中逐血痹、填骨髓、长肌肉、除寒热积聚，及男子五劳七伤、女子伤中胞漏下血、破恶血等。原文未识别出脉名，无脉象描述，主旨为药物主治，故归其他。", []], "26253": ["其他", "本段为菟丝子本草条文，述其续绝伤、补不足、益气力、肥健、明目轻身，及养肌强阴、坚筋骨、主茎中寒精自出、溺有余沥、口苦燥渴等。原文未识别出脉名，无脉象描述，主旨为药物功用，故归其他。", []], "26254": ["病机", "原文标'脉病人虚羸加用之'，牛膝主寒湿痿痹、四肢拘挛、膝痛不可屈伸，逐血气、伤热火烂、堕胎，疗伤中少气、男子阴消、老人失溺、补中续绝填骨髓。脉病人虚羸，示气血亏虚、筋骨失养，故用牛膝补中续绝、填骨髓以治虚羸。", ["虚"]], "26255": ["病机", "原文标'脉绝羸瘦短气久服轻身不老不饥'，麦门冬主心腹结气、伤中伤饱、胃络脉绝、羸瘦短气。脉绝示胃络气血断绝，短气羸瘦为津气两伤，故用麦门冬强阴益精、消谷调中、保神定肺气以复胃络、补羸瘦。", ["绝", "短"]], "26256": ["其他", "本段为独活的本草记载，未涉及脉象。原文述其主\"风寒所击、金疮止痛、奔豚痫痓、女子疝瘕\"，又疗\"诸贼风百节痛风\"，皆属祛风胜湿、通痹止痛之效；文中\"得风不摇、无风自动\"是释名之语，非脉候，故无从论脉所主病机。", []], "26257": ["其他", "本段为羌活的本草记载，无脉象内容。原文称其\"主遍身百节疼痛、肌表八风贼邪\"，除新旧风湿、排腐肉疽疮，\"一身尽痛非此不能除\"，是言其发散风寒湿邪、通利关节之功；末辨羌独形色功用不同，亦属药性鉴别，与脉诊病机无关。", []], "26258": ["其他", "本段为薏苡仁的本草记载，未言脉。原文主\"筋急拘挛不可屈伸、风湿痹\"，又除筋骨邪气不仁、利肠胃、消水肿，是取其渗湿舒筋、健脾之效；所述苗叶花色、结实如珠，皆属药材形态产地，非脉象所主，故不能据以论病机。", []], "26259": ["其他", "本段为泽泻的本草记载，无脉象。原文主\"风寒湿痹、乳难、消水、养五脏\"，又逐膀胱三焦停水、止泄精消渴淋沥，是言其利水渗湿、泄热之功；扁鹊\"多服病人眼\"为用药禁忌，非脉候，故本段不涉脉所主病机。", []], "26260": ["其他", "本段为赤箭（天麻苗）的本草记载，未及脉象。原文主\"杀鬼精物蛊毒恶气\"，消痈肿、下肢满疝、下血，久服益气力长阴肥健；所述\"有风不动、无风自摇\"及根如芋魁、游子环列，均属释名与形态描述，与脉诊病机无涉。", []], "26261": ["其他", "本段为芎䓖的本草记载，无脉象内容。原文主\"中风入脑头痛、寒痹筋挛缓急\"，又除脑中冷动、面上游风去来、目泪出多涕唾、诸寒冷气心腹坚痛，是言其行气活血、祛风止痛之效；雀脑芎形块重实之说属药材鉴别，非脉候。", []], "26262": ["主病", "原文以\"脉沉口噤不语\"系于黄耆条下，沉脉主里主阴，口噤不语为风邪中脏、痰气闭塞清窍之候，脉证相合，示病位在里而非表浅。黄耆主痈疽久败疮、大风癞疾、五劳羸瘦，补虚益气，正取气虚邪陷、沉寒内闭之意，故以沉脉为辨。", ["沉"]], "26263": ["主病", "原文以\"脉虚羸除骨节间疼痛\"系于防风条下，虚脉主气血不足，羸瘦即形气衰少之象；骨节疼痛而脉虚，是正虚风邪乘袭、痹着关节，属虚实夹杂之候。防风主大风头眩痛、风行周身骨节疼痹，祛风而不伤正，故虚人痹痛用之，脉虚正是其辨证眼目。", ["虚"]], "26264": ["其他", "本段为蒲黄的本草记载，未涉及脉象。原文述其主心腹膀胱寒热、利小便、止血消瘀血，蒲萼涩肠止泄、止泻血及血痢，皆属药物主治范畴，非脉诊内容，故无从据脉论病机。", []], "26265": ["其他", "本段为续断的本草记载，未言脉象。原文载其主伤寒补不足、金疮痈伤折跌续筋骨、妇人乳难，又治崩中漏血、金疮血内漏、止痛生肌肉、踠伤恶血腰痛、关节缓急，均属药效主治，与脉象病机无关。", []], "26266": ["其他", "本段为漏芦的本草记载，无脉象描述。原文称其主皮肤热、恶疮疽痔湿痹、下乳汁，又止遗溺、热气疮痒如麻豆、可作浴汤，皆属药物功用，未涉及脉诊，故不能据脉析其病机。", []], "26267": ["其他", "本段为丹参的本草记载，未载脉象。原文述其主心腹邪气、肠鸣幽幽如走水、寒热积聚、破症除瘕、止烦满益气，又养血、去心腹痼疾结气、腰脊强脚痹、除风邪留热，均系药效主治，非脉象所主。", []], "26268": ["其他", "本段为飞廉的本草记载，无脉象内容。原文言其主骨节热、胫重酸疼，又治头眩顶重、皮间邪风如蜂螫针刺、鱼子细起、热疮痈疽痔湿痹、止风邪咳嗽、下乳汁，皆属药物主治，与脉象病机无涉。", []], "26269": ["其他", "本段为五味子的本草记载，未述脉象。原文载其主益气、咳逆上气、劳伤羸瘦、补不足、强阴益男子精，又养五脏、除热、生阴中肌，均属药效功用，非脉诊内容，故不能据脉论其病机。", []], "26270": ["其他", "本段为忍冬的本草记载，无脉象描述。原文称其主寒热身肿、久服轻身长年益寿，又述其治诸恶疮多效、功胜红内消，皆属药物主治与功用，未涉及脉象，故无从据脉分析病机。", []], "26271": ["其他", "本段为王不留行的本草记载，未言脉象。原文载其主金疮止血、逐痛出刺、除风痹内寒，又止心烦鼻衄、痈疽恶疮瘘乳、妇人难产，均属药物主治范畴，非脉诊内容，故不能据脉析其病机。", []], "26272": ["其他", "本段为地不容药材的产地、性味、功用记载，未涉及脉象。原文述其味苦性大寒泄，气薄味厚阴也，主辟瘴气、治咽喉闭塞、解蛊毒，属本草药性内容，与脉诊病机无关，故无从据脉论病机。", []], "26273": ["其他", "本段为麻黄的本经主治与苗、地、时、收、用等本草记载，未出现脉象描述。原文主中风伤寒头痛、发表出汗、去邪热气、止咳逆上气等，皆属药性功用，非脉象所主，故不能据脉析病机。", []], "26274": ["其他", "本段记木通之主治与苗、地、名等，未载脉象。原文主去恶虫、除脾胃寒热、通利九窍血脉关节、疗脾疸常欲眠、心烦哕、耳聋、散痈肿诸结不消等，均属本草功用，无脉可凭，故不作脉象病机分析。", []], "26275": ["其他", "本段为芍药的本经主治及苗、地、时、收等记载，未识别出脉名，原文亦无脉象描述。主邪气腹痛、除血痹、破坚积寒热疝瘕、止痛利小便益气等，皆药性主治，非脉诊内容，故不能据脉论病机。", []], "26276": ["病机", "本段虽以赤芍药本草为主，然标题明载脉散，原文有散恶血消痈肿之语。脉散者，气血耗散不敛，血行失摄，故恶血留滞而痈肿由生；赤芍药色赤入血，泻肝行经、通顺血脉，正以散脉所主之血瘀气散为治，体现脉散与血痹痈肿相应之病机。", ["散"]], "26277": ["其他", "本段为蠡实的本经主治与苗、地、时、收、用等记载，未识别出脉名，原文无脉象描述。主皮肤寒热、胃中热气、风寒湿痹、坚筋骨、令人嗜食，花叶去白虫等，均属药性功用，与脉诊病机无涉，故不作脉象分析。", []], "26278": ["其他", "本段记秦艽的主治、苗、地、时、收、用等，未出现脉象。原文主寒热邪气、寒湿风痹、肢节痛、下水利小便、疗风无问久新、通身挛急，皆属本草药性主治，非脉象所主，故不能据脉析其病机。", []], "26279": ["其他", "本段为贝母的本经主治及苗、名、地等记载，未识别出脉名，原文亦无脉象。主伤寒烦热、淋沥邪气、疝瘕、喉痹、乳难、金疮风痉，疗腹中结实、心下满、咳嗽上气等，均属药性功用，与脉诊无关，故不作脉象病机分析。", []], "26280": ["其他", "原文以“根凹凸茏苁如羊角而细强者”描述狗脊根形，非论脉。借“细强”言其根体细而坚韧，与狗脊主腰背强、关机缓急、周痹寒湿膝痛相合，示药力能坚脊利俯仰、利老人，非脉象主病之文。", ["细", "强"]], "26281": ["其他", "全段为茅根本草，未识别脉名，亦无脉象描述。原文“主劳伤虚羸补中益气除瘀血血闭寒热利小便”乃药效主治，非脉诊内容，故脉象要素为空，不能据以推病机。", []], "26282": ["其他", "段述白藓主治头风黄疸咳逆淋沥、女子阴中肿痛湿痹死肌等，皆本草功用，未出现脉象词语。原文“不可屈伸起止行步”言湿痹症候，非脉，故不列脉象，亦不作脉机分析。", []], "26283": ["其他", "艾叶条主灸百病、止下痢吐血、妇人漏血、利阴气生肌肉辟风寒，全为药性与主治，无脉名脉形。原文“使人有子”“止崩血”属药效，非脉候，故脉象要素空，不能附会为脉主病机。", []], "26284": ["其他", "鼠黏子条述明目补中除风伤，根茎疗伤寒寒热汗出中风面肿消渴热中逐水，均属本草主治，未识别脉名，也无脉象描述。原文“久服轻身耐老”为药效语，非脉诊，故不列脉象。", []], "26285": ["其他", "王瓜条主消渴内痹瘀血月闭寒热酸疼、益气愈聋，疗诸邪气热结鼠瘘痈肿留血、妇人带下不通等，皆药效主治。原文无脉名脉形，不能以“热结”“留血”反推脉象，故脉象要素为空。", []], "26286": ["其他", "泽兰条主乳妇内衄、中风余疾、大腹水肿、身面四肢浮肿、骨节中水、金疮痈肿疮脓，为药效主治。原文“大腹水肿”“骨节中水”是水气病候，非脉象，段中未识别脉名，故不列脉。", []], "26287": ["其他", "天麻条主诸风湿痹、四肢拘挛、小儿风痫惊气、利腰膝强筋力，全属本草功用。原文“诸风湿痹”“四肢拘挛”为症候，非脉象；段中未识别脉名，故脉象要素空，不作脉机推断。", []], "26288": ["其他", "原文仅存“百脉根”药名，无脉象描述，亦无论证文字，故不能据以推断病机。本条属本草条目残文，与脉学无关，脉象要素无从提取，主病、兼症、预后等均无着落，只能归入其他类，不作病机发挥。", []], "26289": ["其他", "此段为百脉根的性味功用记录，言其“主下气止渴去热除虚劳补不足”，属本草主治，非脉诊内容。原文无任何脉象描写，故不能以脉论病机；其“气之薄者阳中之阴”是药性气味之说，与脉象主病无涉，只可归其他。", []], "26290": ["其他", "本段述地笋“利九窍通血脉排脓治血止鼻洪吐血产后心腹痛一切血病”，全为药效主治，未涉脉象。虽言“通血脉”，指药物功用而非脉诊所见，不能据此推断脉主何病，故脉象要素为空，归入其他类，不作病机分析。", []], "26291": ["病机", "原文脉象写作“脉微发躁不止”，微为阳气衰微之象，躁而不止是阴寒内盛、虚阳外越之候，故列于附子条下。附子主“风寒咳逆邪气”“心腹冷痛霍乱转筋”，正合脉微肢冷、阳气欲脱之病机；微脉主虚主寒，躁不止则示阳浮欲脱，二者相参，说明此段意在阐发虚寒阳衰、阴阳离决之病机。", ["微"]], "26292": ["其他", "此段为天雄的本经主治与产地形态记载，言其“主大风寒湿痹历节痛拘挛缓急破积聚邪气”等，全属药效，未出现脉象描述。虽所主多为风寒湿痹、关节重痛之证，但原文无脉可凭，不能以脉论病机，故脉象要素为空，归入其他类。", []], "26293": ["其他", "本段记大黄“主下瘀血血闭寒热破症瘕积聚留饮宿食荡涤肠胃推陈致新”，为药物主治功用，通篇无脉象文字。其“下瘀血”“破症瘕”虽涉血瘀积滞之病，然系从药效立论，非脉诊所得，故不能据以言脉主何病，脉象要素空，归其他。", []], "26294": ["其他", "此段述桔梗“主胸膈痛如刀刺腹满肠鸣幽幽惊恐悸气”，并及利五脏肠胃、补血气、疗咽喉痛等，皆属本草主治，原文未载脉象。胸膈痛如刀刺虽提示气滞血瘀之候，但无脉可参，不能推断脉象病机，故脉象要素为空，归入其他类。", []], "26295": ["其他", "本段为旋覆花的主治记载，言其“主结气胁下满惊悸除水去五脏间寒热补中下气”，又消胸上痰结、心胁痰水、膀胱留饮等，全系药效，未涉脉象。痰饮结气虽为病机所属，然原文无脉可据，不能以脉论主病，故脉象要素为空，归其他类。", []], "26296": ["主病", "本段为大戟《本经》主治条文，无脉象描述。原文列“主蛊毒十二水腹满急痛积聚中风皮肤疼痛吐逆”，又“利大小肠”，皆言大戟苦寒峻下、逐水破积之效。水气内停则腹满急痛，水饮上逆则吐逆，外溢肌肤则疼痛浮肿，故所主病机为水毒壅盛、积聚类病，非凭脉断证。", []], "26297": ["主病", "原文仅见“脉沉者愈”一句，沉脉主里，水气内停、阳气不达于外故脉沉。泽漆主“大腹水气四肢面目浮肿”，乃水湿泛滥之候；脉沉说明病位在里、水饮内结，若脉应沉则邪有出路，故曰愈。此以脉沉测水气在里之病机与转归，非泛论平脉。", ["沉"]], "26298": ["主病", "本段为威灵仙主治，无脉象记载。原文“主诸风宣通五脏去腹内冷滞心膈痰水久积症瘕痃癖气块”，说明其病机为风邪外袭、痰水冷滞内结、气血壅阻成积。威灵仙辛温走窜，能宣通五脏、破积消癖，故所主为风痰水积、症瘕痃癖一类壅滞之病，与脉象无涉。", []], "26299": ["主病", "本段述甘蕉根“主痈肿结热”，无脉象内容。痈肿结热乃热毒壅聚、气血瘀阻所致，甘蕉根甘寒能清热解毒、散结消肿，故其所主病机为热毒结聚成痈。原文重点在苗叶花实之形态鉴别，未及脉诊，故不能以脉象要素附会。", []], "26300": ["主病", "本段为刘寄奴草主治，无脉象描述。原文“主破血下胀”，又“主心腹痛通经脉”，说明其病机为瘀血内阻、气血不通，故见胀满疼痛。刘寄奴苦温，善破血行瘀、通经止痛，所主为血瘀气滞之证。全段重在苗叶花实形态与炮制，未言脉候，故脉象要素从缺。", []], "26301": ["主病", "本段为连翘《本经》主治，无脉象记载。原文“主寒热鼠瘘瘰疬痈肿恶疮瘿瘤结热蛊毒”，皆属热毒结聚、痰火郁滞之病机。连翘苦寒，能清热解毒、散结消肿，故鼠瘘瘰疬、痈肿恶疮皆其所主。段中详辨大翘小翘形态，未涉脉诊，脉象要素不录。", []], "26302": ["主病", "本段为夏枯草《本经》主治，无脉象描述。原文“主寒热瘰疬鼠瘘头疮破症散瘿结气脚肿湿痹”，说明其病机为痰火郁结、肝郁化火，结于颈腋则为瘰疬瘿瘤，流注下焦则为湿痹脚肿。夏枯草苦辛寒，能清肝散结，故所主为痰火结聚之证，非凭脉断病。", []], "26303": ["主病", "本段为地锦草主治，无脉象记载。原文“主通流血脉亦可用治气”，又“调气和血”，说明其病机为气血瘀滞、血脉不通。地锦草辛温能散，故通流血脉、调气和血，治脏毒赤白亦取行血散滞之意。全段述苗叶产地及合治方，未及脉候，脉象要素从缺。", []], "26304": ["其他", "本段为桂（丹桂、姜桂）的性味功用记载，未涉脉象。原文称桂\"主温中利肝肺气\"\"通血脉\"\"坚骨节\"，并引《素问》辛甘发散为阳，说明仲景桂枝汤取辛甘发散之意。所论为药性主治，非脉诊内容，故无脉象要素可录，病机分析亦无从凭脉立论。", []], "26305": ["其他", "本段记牡桂（木桂）之产地、苗叶、采时及主治，如\"主上气咳逆结气喉痹\"\"利关节补中益气\"\"温筋通脉\"。全段为药物本草内容，未出现脉象描述，故脉象要素为空。其\"温筋通脉\"虽涉血脉，仍属药效说明，不能据以推断病机脉理。", []], "26306": ["其他", "本段述槐胶的来源与主治，谓其\"主一切风化涎\"，治\"肝脏风筋脉抽掣\"\"急风口噤\"\"四肢不收顽痹\"\"破伤风口眼偏斜腰脊强硬\"。文中\"筋脉抽掣\"指症状而非脉象，全段无脉诊记载，故脉象要素为空，主旨属药物主治范围。", []], "26307": ["其他", "本段载榆皮主治\"大小便不通利水道除邪气\"，及\"肠胃邪热气消肿性滑利\"，花主\"小儿痫小便不利伤热\"。文中言\"性滑利\"\"孕妇滑胎方中多用之\"，均属药性功用，未及脉象。故脉象要素为空，不能据以立脉诊病机。", []], "26308": ["其他", "本段记干漆主治\"绝伤补中续筋骨填髓脑安五脏\"\"风寒湿痹\"，生漆\"去长虫\"，又疗\"咳嗽消瘀血痞结腰痛女子疝瘕\"。全段为药物本草内容，无脉象描述，\"五缓六急\"指证候而非脉，故脉象要素为空，主旨归其他。", []], "26309": ["其他", "本段述辛夷主治\"五脏身体寒热风头脑痛面䵟\"，能\"温中解肌利九窍通鼻塞涕出\"，治\"面肿引齿痛眩冒身兀兀如在车船之上\"。所论皆药物功用与证候，未出现脉象，故脉象要素为空，不作脉机分析。", []], "26310": ["其他", "本段载桑上寄生主治\"腰痛小儿背强痈肿安胎充肌肤坚发齿\"，又主\"金疮去痹女子崩中内伤不足产后余疾下乳汁\"。全段为药物本草及产地辨别，无脉象记载，故脉象要素为空，主旨属其他，不能凭脉立论。", []], "26311": ["主病", "原文桑根白皮\"主伤中五劳六极羸瘦崩中脉绝补虚益气\"，\"脉绝\"指脉气断绝、气血虚极之象，与五劳六极羸瘦、崩中失血相应，故以补虚益气为治。此脉绝属虚损危候之脉，非平脉，反映气血耗败、脉道不充之病机，列为主病。", ["绝"]], "26312": ["其他", "本段为五木耳（桑耳等）的性味主治记载，非脉诊内容。原文述其「益气不饥轻身强志」「利五脏」，桑耳「治女子崩中带下月闭血凝产后血凝男子痃癖兼疗伏血下」，属本草药性主治，与脉象病机无关，故脉象要素为空。", []], "26313": ["其他", "本段为紫葳（凌霄花）的本草记载，述其「主妇人产乳余疾崩中症瘕血闭寒热羸瘦养胎」，茎叶「主痿蹶益气」，并辨其蔓生依木之性。全段论药性主治与名实考订，未涉脉象，故不列脉象要素。", []], "26314": ["其他", "本段为海桐皮的本草记载，述其「主霍乱中恶赤白久痢除甘䘌疥癣牙齿虫痛」「利腰膝祛湿痹」，日华子云「治血脉麻痹疼痛」，海药云「腰脚不遂顽痹腿膝疼痛」。全段论药性与主治症候，无脉象描述，脉象要素为空。", []], "26315": ["其他", "本段为虎杖根的本草记载，述其「主通利月水破留血症结」，并载其苗叶形态、暑月与甘草同煎解暑毒等。全段属药性主治与形态考订，未言脉象，故脉象要素为空，主旨归其他。", []], "26316": ["其他", "本段为五倍子的本草记载，述其「主齿宣疳䘌肺脏风毒流溢皮肤作风湿癣疮瘙痒脓水五痔下血不止小儿面鼻疳疮」，并释其「禀露气之精华钟木之脉液而成」。全段论药性主治与生成之理，无脉诊内容，脉象要素为空。", []], "26317": ["其他", "本段为密蒙花的本草记载，述其「主青盲肤翳赤涩多眵泪消目中赤脉小儿麸豆及疳气攻眼」。文中「小儿麸豆及疳气攻眼」为所主症候，非脉象写法，全段论药性主治目疾，未涉脉诊，故脉象要素为空。", []], "26318": ["其他", "本段为牡丹的本草记载，述其「主寒热中风瘛疭痉惊痫邪气除症坚瘀血留舍肠胃安五脏疗痈疮」，并辨山牡丹与圃人移接者「根性殊失本真此品绝无力」。全段论药性主治与品种鉴别，无脉象内容，脉象要素为空。", []], "26319": ["其他", "本段为巴豆的本草记载，述其「主伤寒温疟寒热破症瘕结聚坚积留饮痰癖大腹水胀荡涤五脏六腑开通闭塞利水谷道」，兼疗女子月闭烂胎等。全段论药性峻猛攻逐之主病，未涉脉象，故脉象要素为空，主旨归其他。", []], "26320": ["其他", "本段为蜀椒本草条文，未涉脉象。原文述其主邪气咳逆、温中、逐骨节皮肤死肌、寒湿痹痛下气，又除六腑寒冷、伤寒温疟、心腹留饮宿食、肠癖下痢、泄精、女子字乳余疾，散风邪瘕结水肿黄疸，开腠理通血脉。所主皆寒湿、气滞、血瘀、虫毒之病机，非脉诊内容，故脉象要素为空。", []], "26321": ["其他", "本段为椿木叶本草条文，未涉脉象。原文主洗疮疥风疽，皮主疳䘌，又主女子血崩、小儿疳痢。所述为外洗疮疥风疽及内服治疳痢血崩，属湿热虫毒、血热妄行之病机，全段无脉象描述，故脉象要素为空，主旨归其他。", []], "26322": ["其他", "本段为栾荆本草条文，未涉脉象。原文主大风头面手足诸风、癫痫狂痉、湿痹寒冷疼痛。所述为风邪、寒湿、痰火诸病机，属本草主治范围，无脉象记载，故脉象要素为空，主旨归其他。", []], "26323": ["其他", "本段为芫花本草条文，未涉脉象。原文主咳逆上气、喉鸣喘、咽肿短气、虫毒鬼疟、疝瘕痈肿，消胸中痰水、喜唾、水肿五水在五脏皮肤及腰痛，下寒毒肉毒。所主为痰饮、水气、寒毒壅滞之病机，全段无脉象，故脉象要素为空。", []], "26324": ["其他", "本段为牛角䚡等牛类药本草条文，未涉脉象。原文主下闭血瘀血疼痛、女人带下血，髓补中填骨髓，胆疗时气寒热头痛，溺主水肿腹胀脚满利小便。所述为瘀血、带下、水气、虚损诸病机，无脉象描述，故脉象要素为空。", []], "26325": ["其他", "本段为乳腐本草条文，未涉脉象。原文润五脏、利大小便、益十二经脉、微动气，治赤白痢，小儿服之弥佳。所述为润养五脏、通利二便之效，属食疗本草内容，无脉象记载，故脉象要素为空，主旨归其他。", []], "26326": ["其他", "本段为阿胶本草条文，未涉脉象。原文主心腹内崩、劳极洒洒如疟状、腰腹痛、四肢酸疼、女子下血安胎，丈夫小腹痛、虚劳羸瘦、阴气不足、脚酸不能久立、养肝气。所述为虚劳、血虚、崩漏、胎动之病机，全段无脉象，故脉象要素为空。", []], "26327": ["其他", "本段为白马茎等马类药本草条文，未涉脉象。原文主伤中脉绝、阴不起、强志益气长肌肉，眼主惊痫腹满疟疾，悬蹄主惊邪瘛疭乳难，白马蹄疗妇人瘘下白崩，齿主小儿惊痫。所述为虚损、惊痫、崩漏诸病机，无脉象描述，故脉象要素为空。", []], "26328": ["其他", "本段为鹿茸、鹿角、鹿髓等药物的主治记载，非脉诊内容。文中「伤中绝脉筋急痛咳逆」之「绝脉」指血脉虚绝之病证，非脉象描述；鹿髓主伤中绝脉，是因精血亏虚、血脉不续，故以甘温补髓充脉，与脉学所言之脉象无关。", []], "26329": ["其他", "本段为羖羊角及羊髓、羊胆、羊肺等药的主治记录，未涉及脉象。文中「利血脉益经气」指羊髓能补阴血、通利血脉，属药效论述；「止寒泄」「惊悸」等为症候，非脉象，故不能据以推断病机脉理。", []], "26330": ["其他", "本段记兔头骨、兔骨、兔脑、兔肝、兔肉的主治与产地，无脉象内容。「主头眩痛癫疾」「主热中消渴」为药物所主症候，非脉诊；「妊娠禁食之」属禁忌，与脉象病机无关，故脉象要素为空。", []], "26331": ["主病", "原文「脉滑肌肤去寒热」言猪肤甘寒入肾，能解少阴客热；脉滑主痰热内蕴或邪热未清，肌肤寒热乃少阴客热外蒸所致。猪肤汤证以脉滑、肌肤寒热并见，说明热在少阴而津伤，故以猪肤清润解热，非泛言滑脉主病。", ["滑"]], "26332": ["其他", "本段述獭肝、獭肉的主治及獭的产地形态，未载脉象。「主鬼疰蛊毒」「止久嗽」为药物主治症候；「疗疫气温病」亦属药效，无脉诊内容，故脉象要素为空，不能附会脉理。", []], "26333": ["其他", "本段记鼹鼠主治痈疽瘘蚀恶疮及产地别名，无脉象描述。「主痈疽诸瘘蚀恶疮阴䘌烂疮」为药物所主外科病证，属外治内服之效，与脉象病机无涉，故脉象要素为空。", []], "26334": ["其他", "本段述野驼脂主治顽痹风瘙恶疮及驼的产地习性，未涉及脉象。「主顽痹风瘙恶疮毒肿死肌筋皮挛缩」为药物外摩主治，属痹证疮疡范畴，非脉诊内容，故脉象要素为空。", []], "26335": ["其他", "本段为鹬、鷃、阳乌鹳、凤凰台等药的主治考注，无脉象记载。「主劳损积血利血脉安神」及「惊邪癫痫鸡痫发热狂走」为凤凰台所主症候，属药物功效，非脉象描述，故脉象要素为空。", []], "26336": ["其他", "本段为雀卵、雀脑、雀血、雄雀屎的药用记载，未涉及脉象。原文称雀\"性属阳\"\"凡动属火\"，故其卵能\"助阴道而益阳\"，主\"男子阴痿不起\"\"多精有子\"，雀脑主耳聋，雀血主雀盲，雄雀屎疗目痛、决痈疖、女子带下溺不利、除疝瘕，皆从阳火温通之性推衍，非脉诊内容。", []], "26337": ["其他", "本段述秦龟产地、形态及药用，未言脉。原文主\"除湿痹气身重四肢关节不可动摇\"，是取龟类阴湿之性以治湿痹身重、关节不利；又辨𪓛龟（陵龟）肉寒有毒、呷蛇龟能疗蛇毒、蟕蠵可卜，均属药物产地形性考录，与脉象病机无涉。", []], "26338": ["其他", "本段记玳瑁产地、形色及解毒功用，未涉脉象。原文主\"解岭南百药毒\"，俚人刺血饮以解诸药毒；又述生玳瑁带之可辟蛊毒、遇毒则自摇动，死甲及煮拍为器者则不神。全段为药性产地考，无脉象可辨，故脉象要素为空。", []], "26339": ["其他", "本段述露蜂房产地、形态与药用，未及脉诊。原文主\"惊痫瘛疭寒热邪气癫疾鬼精蛊毒肠痔\"，又疗风毒毒肿，取蜂房有毒攻散之性以治惊痫、蛊毒、疮肿；并辨木上大黄蜂窠与屋间小窠力有强弱。属药物形性主治记录，无脉象内容。", []], "26340": ["其他", "本段载蟹的产地、种类与主治，未言脉。原文主\"胸中邪气热结痛㖞僻面肿\"，解结散血、愈漆疮、养筋益气，蟹爪主破胞堕胎；又诫六足、四足者有大毒不可食，多食动风气。皆属药性宜忌，无脉象可录，故脉象要素为空。", []], "26341": ["其他", "本段记蜚虻产地、形色与主治，未涉脉象。原文主\"逐瘀血破下血积坚痞症瘕寒热通利血脉及九窍\"，疗女子月水不通、积聚、贼血在胸腹五脏及喉痹结塞；衍义谓其\"惟食牛马等血故治瘀血血闭\"，是以血食之虫破血通脉，属药性推衍而非脉诊。", []], "26342": ["其他", "本段述蜚蠊（负盘、滑虫）产地、形气与主治，未言脉。原文主\"血瘀症坚寒热破积聚喉咽痹内寒无子\"，又能通利血脉；因其味辛辣而臭、形似虻虫，故取破血通瘀之功。全段为药物考录，无脉象要素，亦不涉脉所主病机。", []], "26343": ["其他", "本段载䗪虫（地鳖）产地、形色性味与主治，未及脉象。原文主\"心腹寒热洗洗血积症瘕破坚下血闭生子大良\"，衍义称其\"有破坚积下血之功\"，张仲景大黄䗪虫丸、大鳖甲丸及治妇人药并用之。属药性主治记录，无脉象可辨，故脉象要素为空。", []], "26344": ["其他", "本段为白鱼药材条目，非脉学内容。原文述其味甘性平缓，气薄为阳中之阴，主胃气、开胃下食、去水气，兼调五脏、助脾气、消食、理十二经脉。所论为药性功用与禁忌，如患疮疖人不可食、多食泥人心、经宿者令人腹冷，全无脉象可言，故脉象要素为空，主旨归入其他。", []], "26345": ["其他", "本段为水蛭药材条目，述其主逐恶血瘀血、月闭、破血瘕积聚、无子、利水道、堕胎，并辨水中马蟥、石蛭、草蛭、泥蛭诸种。原文全论药性主治、产地形态与误用石蛭令人目中生烟之害，未涉及任何脉象描述，故脉象要素为空，主旨属其他。", []], "26346": ["其他", "本段为白花蛇药材条目，主中风湿痹不仁、筋脉拘急、口面㖞斜、半身不遂、骨节疼痛、大风疥癞及暴风瘙痒、脚弱不能久立。原文详述产地、形态、毒性及采收炮制，如头尾各一尺尤甚不可用、眼不陷者为真，通篇无脉象记载，故脉象要素为空，主旨归其他。", []], "26347": ["其他", "本段为五灵脂药材条目，主疗心腹冷气、小儿五疳、辟疫、治肠风、通利气脉、女子月闭。原文引衍义论其行经血有功而不能生血，以眼中翳往来不定属血病、肝受血则能视阐发入肝之理，并述修治去砂石之法，全无脉象，故脉象要素为空，主旨属其他。", []], "26348": ["其他", "本段为藕实茎药材条目，主补中养神、益气力、除百疾，久服轻身耐老、不饥延年。原文释荷之茎叶花实诸名，述其生于水而水不能没、居淤泥而泥不能淤、体中空故令人心悦，皆论药性形质与补养之功，未及脉象，故脉象要素为空，主旨归其他。", []], "26349": ["其他", "本段为梅实药材条目，主下气、除热烦满、安心、肢体痛、偏枯不仁、死肌、去青黑志恶疾，止下痢、好唾口干。原文述其苗、地、时、收、质、色、味酸性平收，及乌梅、白梅制法，通篇为药性主治与炮制，无脉象内容，故脉象要素为空，主旨属其他。", []], "26350": ["其他", "本段为木瓜实药材条目，主湿痹邪气、霍乱大吐下、转筋不止，其枝亦可煮用。原文述其苗、地、名楙，辨木瓜与榠楂蒂间重蒂如乳之别，并载大枝作杖利筋脉、截木作桶濯足尤益及默呼木瓜名疗转筋之俗，全无脉象，故脉象要素为空，主旨归其他。", []], "26351": ["其他", "本段为柿药材条目，主通鼻耳气、肠澼不足。原文列牛奶柿、红柿、朱柿、乌柿、白柿等诸名，述其苗、地及黄柿、红柿、朱柿、椑柿、软枣之种类，辨火干乌柿性温、晒干白柿入药微冷，并载柿有七绝之说，通篇论药性种类，无脉象，故脉象要素为空，主旨属其他。", []], "26352": ["病机", "原文言林檎多食令人发热涩气、好睡、发冷痰生疮疖，终致“脉闭不行”。此非论脉象本身，而是讲过食酸温收涩之果，气机壅滞、痰热内生，营卫受阻故脉道闭而不行，属食伤致病的病机推断。", []], "26353": ["其他", "本段述胡桃肥健润肌、黑发、利小便、去五痔等功用，兼及“多食利小便能脱人眉动风”之弊，全无脉象描述。其主旨为食疗药性及宜忌，非论脉诊，故脉象要素为空，归入其他。", []], "26354": ["其他", "庵罗果条言其止渴生津、调妇人经脉不通、丈夫营卫中血脉不行，并载天行病后及饱食后不可食之禁。原文未出现脉象描写，“血脉不行”系指营卫气血不畅之证，非脉象，故脉要素为空。", []], "26355": ["其他", "榅桲主温中下气、消食、除心间醋水，疗霍乱转筋、去醋痰。全段为果实药性主治记载，无脉象内容，故脉象要素为空；其“下气消食”反映中焦气滞食积之机，但非脉诊论述。", []], "26356": ["病机", "原文标“脉滑精气痿阳气妇人发带疾”。滑脉主痰湿食积，亦见于精气虚而阳气不振之时；精气痿弱、阳气不足，湿浊内蕴则脉见滑，妇人带下多由湿浊下注，故滑脉与带疾相应，示虚中夹湿之机。", ["滑"]], "26357": ["其他", "白油麻条述其滑肠胃、行风气、通血脉、润肌、杀五黄下三焦热毒等，并载生寒炒热之性。原文无脉象描述，主旨为药性功用与宜忌，故脉象要素为空，归入其他。", []], "26358": ["其他", "生大豆条载涂痈肿、逐水胀、除胃热痹、下瘀血、散五脏结积内寒等，并言久服令人身重、炒热煮凉之异。全段论药性主治，未涉脉象，故脉要素为空，主旨属其他。", []], "26359": ["其他", "赤小豆条主下水、排痈肿脓血，疗寒热热中消渴、止泄利小便、吐逆卒澼下胀满，并言驴食脚轻人食体重。原文无脉象记载，主旨为药物主治与食性，故脉象要素为空，归入其他。", []], "26360": ["其他", "本段论酒之性味功用，非脉诊内容。原文言酒\"主行药势杀百邪恶毒气\"，又谓\"辛者能散苦者能下甘者居中而缓\"，说明酒性辛散走窜，能助药力通行；然\"多饮未有不作疾者\"，指出损益兼行，须斟酌使用。全段无脉象描述，故脉象要素为空，主旨属药物论述，归入其他。", []], "26361": ["其他", "本段述粳米之性用，非脉学内容。原文称粳米\"主益气止烦止泄\"，又引汤液云\"益脾胃\"，并释白虎汤用粳米入肺、桃花汤用此\"甘以补正气\"，皆从色白味甘寒论其归经补益之功。全段未涉脉象，故脉象要素为空，主旨为药物主治，归入其他。", []], "26362": ["其他", "本段论黍米之性味主治，非脉诊段落。原文谓黍米\"主益气补中\"，又言\"多热令人烦\"，并称\"黍米乃肺之谷盖补肺气也\"，从味甘性温、气厚属阳说明其补中益气而偏于温热之性。全段无脉象记载，脉象要素为空，主旨属药物论述，归入其他。", []], "26363": ["其他", "本段述小麦及面、曲、麸、苗等功用，非脉学内容。原文言小麦\"主除热止燥渴咽干利小便养肝气止漏血唾血\"，又谓\"作面则味甘温而有毒\"\"作曲则平胃止痢\"，从性寒与制用不同论其功效差异。全段未及脉象，脉象要素为空，主旨为药物主治，归入其他。", []], "26364": ["其他", "本段论大麦之性用，非脉诊段落。原文称大麦\"主消渴除热益气调中\"，又云\"令人多热为五谷长\"，并述其\"作糵则味甘无毒以为开胃消食之要药\"，从味咸性温微寒说明益气调中、消食开胃之功。全段无脉象描述，脉象要素为空，主旨属药物论述，归入其他。", []], "26365": ["其他", "本段述绿豆及稙豆之主治，非脉学内容。原文言绿豆\"主丹毒烦热风疹药石发动热气奔豚\"，生研绞汁服可\"消肿下气压热解石\"，又强调\"用之勿去皮令人小壅\"，从皮寒肉平论其清热消肿之功。全段未涉脉象，脉象要素为空，主旨为药物主治，归入其他。", []], "26366": ["其他", "本段论白豆（豇豆）之性用，非脉诊段落。原文称白豆\"补五脏益中助十二经脉调中暖肠胃\"，叶\"利五脏下气\"，从味甘性平、气厚于味说明其补中暖胃之功，并述其苗叶形态及食用之法。全段无脉象记载，脉象要素为空，主旨属药物论述，归入其他。", []], "26367": ["其他", "本段述陈廪米之性用，非脉学内容。原文言陈廪米\"主下气除烦渴调胃止泄\"，又引衍义谓\"粳粟二米陈者性皆冷，频食之令人自利\"，从陈久性冷论其下气调胃止泄之功，并辨粳粟之别。全段未及脉象，脉象要素为空，主旨为药物主治，归入其他。", []], "26368": ["其他", "本段为胡荽的食疗本草记载，未涉及脉象。原文述其“消谷”“补不足”“利大小肠”“通小腹气”“拔四肢热”“止头痛”，并治沙疹豌豆疮不出，皆从辛温香窜、发散通窍之性立论；子主小儿秃疮、蛊毒痔血，亦属外敷或煮汁服法，与脉诊病机无关，故脉象要素为空。", []], "26369": ["其他", "本段记邪蒿“主胸膈中臭烂恶邪气，利肠胃，通血脉，续不足气”，作羹食良；合治又治“五脏邪气厌谷”“肠澼大渴热中暴疾恶疮”。全段为药物主治与服食宜忌，未出现任何脉象描述，故不能据脉论病机，脉象要素从空。", []], "26370": ["其他", "本段述胡瓜叶治小儿闪癖、根敷毒肿，实甘寒有毒，“不可多食”，多食则“动寒热多疟病积瘀热发疰气”“令人虚热上逆少气”“损阴血脉气”“发脚气”，小儿切忌“滑中生疳虫”。此为食物宜忌与致病之由，非脉象主病，故脉象要素为空。", []], "26371": ["其他", "本段记荏子“主咳逆下气，温中补体”，叶性温“主调中去臭气”；后引陶隐居、唐本注、萧炳诸说，辨荏之形色、作油及食用优劣。通篇为药物性味功用与产地考订，未及脉诊，故脉象要素为空，不能附会病机。", []], "26372": ["其他", "本段述苦苣“除面目及舌下黄，强力不睡”，茎中白汁敷疔肿出根、滴痈立溃，根主赤白痢及骨蒸；又云“久食轻身少睡，调十二经脉，利五脏”，霍乱后胃气逆烦可捣汁饮。皆药食主治，未言脉象，故脉象要素为空。", []], "26373": ["其他", "本段记罗勒“调中消食，去恶气，消水气”，宜生食，疗齿根烂疮；然“不可过多食”，过食则“壅关节，涩营卫，令血脉不行，又动风发气”。此从辛温香散太过立论，说明食忌致病之理，原文无脉象描述，故脉象要素为空。", []], "26374": ["其他", "本段述干姜“主胸满咳逆上气，温中止血出汗，逐风湿痹，肠澼下痢”，又治“寒冷腹痛中恶霍乱胀满风邪诸毒皮肤间结气止唾血”。全为神农本经与名医所录的主治条文，兼载炮制产地，未涉脉象，故脉象要素为空，不作脉机分析。", []], "26375": ["其他", "本段记荆芥“主寒热鼠瘘瘰疬生疮，破结聚气，下瘀血，除湿痹”，又“祛风发汗”，疗头风虚劳疮疥妇人血风，去邪出汗除冷风。所述为药物主治与制用，通篇无脉象文字，故脉象要素为空，不能以脉论病机。", []], "26376": ["其他", "本段为白蘘荷的药材著录，述其名、苗、地、时、收、用、味、性、气、臭、主、制，全无脉象内容。所谓主中蛊及疟、恶疮喉痹，是药性主治，非脉诊病机。故脉象要素为空，不可据药效反推脉象，亦不得以辛甘微温之性附会为脉。", []], "26377": ["其他", "本段述薄荷之名的由来、苗叶形态、产地及发汗解劳之功，通篇为药物产地与功用记载，未及脉诊。虽言主贼风伤寒发汗、心腹胀满霍乱宿食不消，皆属药治范围，与脉象无关。故脉象要素为空，不可因发汗之说而虚拟浮脉。", []], "26378": ["其他", "本段记葫葱温中消谷下气杀虫之性，并述久食伤神损性、损目明、发痼疾、狐臭人不可食等禁忌，属药物宜忌内容，无脉象描述。消谷、利五脏不足气为药效而非脉候，故脉象要素为空，不得以辛温之性推作脉象。", []], "26379": ["其他", "本段述水斳即水芹的苗、地、时、用、色、味、性、气、臭及主治，末言芹花主脉溢，此「脉溢」为病名而非脉象描述，且属药治范围。全段无脉诊内容，故脉象要素为空，不可将「脉溢」二字误作脉象要素录入。", []], "26380": ["其他", "本段为白苣的著录，述其补筋骨、利五脏、开胸膈壅气、通经脉、止脾气等功用，并辨白苣、莴苣、苦苣之异同，属药物与食疗内容。文中「通经脉」指药效通利经脉，非脉象，故脉象要素为空，不得据以立脉。", []], "26381": ["其他", "本段记百乳草又名百蕊草，述其苗叶形态、产地、采收、药用部位及色，主下乳、通顺血脉、调气。通顺血脉为药效表述，非脉象记录，全段无脉诊内容，故脉象要素为空，不可因「血脉」二字而附会脉象。", []], "26382": ["主病", "原文标脉象写法为「脉急痛」，烈节主肢节风冷、筋脉急痛。风冷之邪客于肢节筋脉，寒性收引，故筋脉拘急而痛，脉应之而急。此「急」指脉势紧急，与寒凝收引之病机相应，主肢节风冷痹痛之证，非虚非数，乃邪实拘急之候。", ["急"]], "26383": ["其他", "本段合述薰草与姑活两药。薰草主明目止泪、疗泄精、去臭恶气、伤寒头痛上气腰痛；姑活主大风邪气、湿痹寒痛。皆属药物主治与产地考辨，通篇未涉脉诊，故脉象要素为空，不可据「湿痹寒痛」虚拟紧脉。", []], "26384": ["其他", "本段仅为《脉诀四言举要》的标题性文字，未出现具体脉象描述，故无从论其病机。原文标明“脉诀四言举要附以注释上呈”，属书籍体例说明，非诊脉条文，不能据以推断主病或症候，脉象要素亦无从摘取。", []], "26385": ["其他", "此段为序言，述崔嘉彦著四言脉诀、李言闻补注，叹其“意旨拘于声韵”“求显愈迷茫”，意在说明注解之必要，非论具体脉象。文中无浮沉迟数等脉形描述，故不能归入主病或病机，只属医书编纂缘起之交代。", []], "26386": ["其他", "本段论砭石主治“百病及痈肿”、通血脉理气滞，并述其产地、质地与以石为针之沿革，末附石砮。全段言治法工具与出处，未及脉象，故无脉可辨，病机分析无从紧扣脉形，只能判为治法类以外的本草器物记述。", []], "26387": ["妇人", "本段主铁斧治妇人产难横逆、胞衣不出及产后血瘕腰腹痛，又载“转女为男”置斧床底之法，论“血脉未流，象形而变”。内容属妇人胎产，然通篇无脉象描述，不能以脉论病机，只就原文所主产难、血瘕诸症归入妇人门。", []], "26388": ["病机", "本段记黄土汤愈皇子瘛疭，钱乙对曰“以土胜水，水得其平则风自退尔”，点明泄痢、热毒绞结痛下血及风动之由在水气偏胜。原文无脉象字句，故脉素为空；其主旨以五行生克释病机，非凭脉断症，分析紧扣“土胜水”“风自退”之语。", []], "26389": ["治法", "本段论艾火灸百病及诸风冷疾，述取火之法、艾火性温热、为“阴中之阳”，并列松柏桑柘枣橘榆竹诸火之忌，如“柘火伤气脉”“竹火伤筋损目”。全属灸法宜忌，未涉脉形，故不能以脉象推病机，只归治法。", []], "26390": ["小儿", "本段主灯火治小儿惊风昏迷、搐搦窜视，及初生冒风寒气将绝者燎脐回气，又淬太阳络脉治头风、淬红点治搅肠沙。原文以症述治，未出脉象，故脉素为空；其主旨在小儿惊风急救外治，紧扣“气回自苏”“络脉盛处”等语。", []], "26391": ["其他", "本段述锁阳“大补阴气，益精血，利大便”，虚人大便结燥者可代苁蓉，不燥结者勿用，又润燥养筋治痿弱，并载其产地形质“筋脉连络，绝类男阳”。全为药物性用记载，无脉象描述，不能据脉论病机，只归本草其他类。", []], "26392": ["病机", "原文论泪为肝之液，五脏六腑津液上渗于目，悲哀笑咳则火激于心，心系急而脏腑摇，宗脉感而液道开，津上溢故涕泣出。此段无脉象，所论为泪液生成与情志致泣之病机，非脉诊内容，故脉象要素为空。", []], "26393": ["妇人", "原文引易理及褚澄、东垣、圣济、丹溪诸说，论男女构精、精血先后、月水日数奇偶与子宫左右之系，辨成男成女及骈胎品胎之兆。全段无脉象，主旨属妇人胎孕男女之辨，故归妇人，脉象要素为空。", []], "26394": ["其他", "原文述野马肉主马痫、筋脉不能自收、周痹肌肉不仁，阴茎主男子阴痿缩少精，并载其名、地、时、用、质、色、味、性、制、治。全段为药物主治与炮制内容，无脉象描述，故脉象要素为空，主旨归其他。", []], "26395": ["其他", "原文述木狗皮主除脚痹风湿气、活血脉、暖腰膝，载其产地、形状、颜色及为衣褥运动血气之用，并附元豹皮之暖。全段为药物形态与功用记载，无脉象，故脉象要素为空，主旨归其他。", []], "26396": ["其他", "原文述鳟鱼肉主暖胃和中，载其名、地、时、用、质、色、味、性及禁宜，言其状似𩽼而小、赤脉贯瞳、好食螺蚌、善遁网，不宜多食动风热发疮癣。全段为食疗药物内容，无脉象，故脉象要素为空。", []], "26397": ["其他", "原文述绿毛龟主通任脉、助阳道、补阴血、益精气、治痿弱，载其名、地、用、质、色、味、性、制。虽言通任脉、治痿弱，然全段为药物功用记载，无脉象描述，故脉象要素为空，主旨归其他。", []], "26398": ["其他", "原文仅为《续集脉诀四言举要卷上》篇题，无具体脉象与病机论述，故脉象要素为空，主旨归其他，不作病机推断。", []], "26399": ["其他", "原文仅为「血脉隧道第一」篇题，无脉象描述与病机内容，故脉象要素为空，主旨归其他，不编造病机分析。", []], "26400": ["病机", "原文以“脉乃血沠”立论，强调脉为气血之先兆，“脉实血实，脉虚血虚”，说明脉象可反映气血盛衰。脉道通利则气血运行，故脉之虚实直接对应血之虚实，此段主旨在于阐发脉与气血的生理关系及脉诊原理，非论具体病脉。", []], "26401": ["病机", "原文言“其象法地，血之府也，心之合也，皮之部也”，从脉与地、血、心、皮的配属关系说明脉的生理基础。脉为血府，与心相合，充遍人身应夏火之气，故脉象可反映心血与皮部状况，此段重在论脉之归属与生成。", []], "26402": ["病机", "原文提出“资始于肾，资生于胃”，说明脉之根本在肾，化源在胃；又言“阳中之阴，本乎营卫”，营行脉中，卫行脉外。脉之流行依赖营卫气血升降，故脉象可察肾胃先后天及营卫强弱，此段论脉之资生与营卫关系。", []], "26403": ["病机", "原文标题“气动脉应”，指出动脉的形成与气机鼓动密切相关。脉不自行，随气而至，气动则脉应，故动脉主气机变动之病机，反映气血失和、阴阳相搏之候，此段为动脉总纲。", ["动"]], "26404": ["病机", "原文详论“脉不自行，随气而至，气动脉应”，以橐龠、波澜为喻，说明脉动由宗气推动，气行则血行，气动则脉动。动脉反映气血阴阳相互为用、循环无端之机，若气机失调则脉动异常，此段阐动脉之生理与病机。", ["动"]], "26405": ["其他", "原文论述十二经皆有动脉而取寸口，详述寸关尺定位、脏腑分属及男女脉异，提出“人无二脉病死不愈”。此段为脉诊部位与脏腑配属的总论，涉及平脉与病脉判断基础，非专论某病机。", []], "26406": ["病机", "原文提出七诊九候之法，以浮中沉上下左右消息求寻，并述五脏平脉：心浮大而散，肺浮涩而短，肝沉而弦长，肾沉实而濡，脾胃和缓。又引“独小者病，独大者病，独疾者病，独迟者病”，说明脉象偏独即为病机所在，此段论诊法及五脏脉象主病。", ["浮", "沉", "大", "散"]], "26407": ["平脉", "原文言“春弦夏洪秋毛冬石，四季和缓，是为平脉”，指出四时正脉以胃气为本、脉贵有神。若“太过实强病生于外，不及虚微病生于内”，则非平脉。此段论四时平脉及太过不及之病机，强调脉以和缓有神为要。", ["弦", "洪", "毛", "石"]], "26408": ["平脉", "原文以呼吸定息辨脉，四至五至为平和之则，三至为迟主冷，六至为数主热。迟数既明寒热乃定，又当别浮沉以分表里。此段总言诊脉纲领，以迟数辨寒热，以浮沉辨表里，为脉诊之基础。", ["迟", "数"]], "26409": ["病机", "原文统言浮沉迟数四者为脉之纲领，以分内外所感之因。外因于天，六淫之邪，在表则浮，在里则沉；内因于人，七情所伤，迟则为冷，数则为热。浮数表热，沉数里热，浮迟表虚，沉迟冷结，脉证参别，引申触类。", ["浮", "沉", "迟", "数"]], "26410": ["其他", "此段仅为浮脉篇目，原文无具体脉象描述与病机分析，故脉象要素取浮字，主旨归为其他，不作病机推断。", ["浮"]], "26411": ["病机", "原文言浮脉法天，轻手可得，如水漂木。有力洪大来盛去悠为浮大之脉；无力虚大迟而且柔为虚大之脉；虚甚则散，涣漫不收，有边无中为芤，浮小为濡，濡甚则微。此段详析浮脉兼诸脉之形，以辨有力无力及兼夹之象。", ["浮", "洪", "虚", "散"]], "26412": ["其他", "此段仅为沉脉篇目，原文无具体脉象描述与病机分析，故脉象要素取沉字，主旨归为其他，不作病机推断。", ["沉"]], "26413": ["病机", "原文言沉脉法地，近于筋骨，重按乃得。沉极为伏，有力为牢，实大弦长，牢甚则实愊愊而强；无力为弱，柔小如绵，弱甚则细如蛛丝。此段详析沉脉兼诸脉之形，以辨沉伏牢弱之异。", ["沉", "伏", "牢", "弱"]], "26414": ["其他", "此段仅为迟脉篇目，原文无具体脉象描述与病机分析，故脉象要素取迟字，主旨归为其他，不作病机推断。", ["迟"]], "26415": ["病机", "原文言迟脉属阴，一息三至，气不振发。迟而浮大或虚散或芤革，迟而浮小为濡为微，迟而沉小为细为弱，迟细为涩，往来极难，易散一止，止而复还为结，止不能回为代。此段详析迟脉兼诸脉之形及主病。", ["迟", "涩", "结", "代"]], "26416": ["主病", "原文以“数脉第十三”为题，专论数脉之形与主病。数脉一息六至，属阳，气行疾速逾于常度，故主阳热之病。文中详述数脉兼浮大、沉大、流利、有力等不同形态，分别对应洪、实、滑、紧等脉，说明数脉主病广泛，总由阳热亢盛、气行加速所致。", ["数"]], "26417": ["病机", "原文详析数脉之形及兼脉意义：“一息六至是为数脉气行疾速逾于常度故曰属阳”，七至为疾，八至九至则阳热已极、元神散脱。数而浮大曰洪，沉大曰实，往来流利曰滑，有力曰紧。数中时见一止为促，因“脉流数疾偶不相继故一止”。数见关中为动，厥厥动摇。全段阐明数脉及其兼脉的病机。", ["数", "疾", "促", "动"]], "26418": ["主病", "原文以“长脉第十四”为题，专论长脉之形与主病。长脉过于本位，透出寸关尺三部，乃气之充畅所致，故曰“长则气治”。若长而端直应指，则为弦脉。段中明确指出长脉主气治，与弦脉相鉴别，说明长脉反映气机调畅、气血充盈的生理状态，亦可见于气机郁滞等病理情况。", ["长"]], "26419": ["病机", "原文指出“长则气治过于本位”，长脉透出本位，非气之充畅不能有此，故主气治。又言“长而端直弦脉应指”，即长而端直应于指下者为弦脉。此段阐明长脉与弦脉的形态区别及病机：长脉主气机充畅，弦脉主气机紧张或郁滞，二者虽均见脉体较长，但端直与否是鉴别关键。", ["长", "弦"]], "26420": ["主病", "原文以“短脉第十五”为题，专论短脉之形与主病。短脉不能满部，不见于关，惟尺寸候之，乃气不充畅所致，故曰“短则气病”。段中强调短脉主气病，气机不畅、气血不足则脉道短缩，不能满部，反映正气虚衰或气机郁滞的病机。", ["短"]], "26421": ["病机", "原文言“短则气病不能满部不见于关惟尺寸候”，短脉因气不充畅，无论在寸在尺俱不能满部，故主气病。若短脉见于关而不能满部，则与尺寸不相接。又指出“脉数形兼见而病亦数种兼成”，说明脉象兼见则病机复杂，数种病证兼成，强调脉症合参、综合分析的重要性。", ["短", "数"]], "26422": ["主病", "原文以“浮脉主病第十六”为题，专论浮脉主病。浮脉主表，与皮毛相得，表气应之故里不足。浮而有力为风热壅盛，无力则浮而虚，血弱不能谐气故反浮，亦属里不足。此段总括浮脉主表、里必不足的病机，并提示浮脉兼脉主病之多样性。", ["浮"]], "26423": ["主病", "原文详述浮脉兼诸脉主病：“浮脉主表里必不足有力风热无力血弱”。浮迟为风虚，因鼓动不及；浮数为风热，因鼓动太过；浮紧为风寒，紧则收敛，寒之性也；浮缓为风湿，缓则行慢，湿之性也。又浮虚伤暑、浮芤失血、浮洪虚火、浮微劳极、浮濡阴虚、浮散虚剧、浮弦痰饮、浮滑痰热，全段阐明浮脉兼脉的广泛病机。", ["浮", "迟", "数", "紧"]], "26424": ["主病", "原文标目「沉脉主病第十七」，直接以沉脉为纲统摄诸病。沉为阴脉，其象按之至骨乃见，故主里证；寒邪、积滞皆阴类，故沉脉主寒主积。有力者邪实，无力者正虚，为下段兼脉主病张本。", ["沉"]], "26425": ["病机", "原文以「脉按之至骨曰沉」释沉主里，寒、积皆阴邪内着。沉而有力为痰食实邪，无力为气郁不伸；沉迟虚寒，沉数热伏，沉紧冷痛，沉缓水蓄，沉牢痼冷，沉实热极，沉弱阴虚，沉细痹湿，沉弦饮痛，沉滑宿食，沉伏吐利阴毒。诸兼脉各因邪性不同而主病异。", ["沉", "迟", "数", "紧"]], "26426": ["主病", "原文标目「迟脉主病第十八」，以迟脉为纲。迟为阴脉，一息三至，主脏主寒。下段申明「有力为痛，无力虚寒」，此段总提迟脉主病之范围，为辨迟脉兼有力无力定虚实之总则。", ["迟"]], "26427": ["病机", "原文引《难经》《伤寒论》「迟者脏也」「迟则为寒」，明迟为阳气伏潜、不能健行所致。迟而有力，壅实不通，故痛；迟而无力，阳伏且虚，故为虚寒。以有力无力分痛与虚寒，紧扣「阳气伏潜」之机。", ["迟"]], "26428": ["主病", "原文标目「数脉主病第十九」，以数脉为纲。数为阳脉，一息六至，主腑主热。下段申明「有力为热，无力为疮」，此段总提数脉主病之范围，为辨数脉兼有力无力分实热虚热之总则。", ["数"]], "26429": ["病机", "原文引《难经》「数者腑也」「数则为热」，以迟数分阴阳配脏腑。数主吐者，胃气逆乱；主狂者，重阳神昏。数而有力，聚热所鼓；数而无力，热而虚散，散于外则发疮。以有力无力分热聚与虚散热散。", ["数"]], "26430": ["主病", "原文标目「滑脉主病第二十」，以滑脉为纲。滑为流利之脉，近于水象，主痰、伤食、蓄血、吐逆。下段申明「下为畜血，上为吐逆」，此段总提滑脉主病之范围，为辨滑脉所见部位定病之总则。", ["滑"]], "26431": ["病机", "原文谓「滑脉近于水象」，痰乃水饮所结，食积不化亦如之，皆有物之脉。见于尺则蓄血，见于寸则吐逆；所吐非痰即食。设无痰食而为呕逆，则脉当见涩，以涩主虚滞，与滑之主实邪相对，点明滑涩辨痰食有无之要。", ["滑", "涩"]], "26432": ["主病", "原文以「涩脉主病」立题，涩为血少、脉道不充之象，故主血虚。涩滞不利，反映营血亏少、脉道失濡，或寒湿痹阻、气机不畅。此段为涩脉主病总纲，提示涩脉可因血少、寒湿、反胃、自汗、厥逆等而见，病机关键在血少与气滞。", ["涩"]], "26433": ["病机", "原文言「脉必见涩滞矣」，因血少则枯涩，寒湿袭人则气道不通而滞涩，反胃则胃无余液、大便秘结而脉涩，自汗则血耗、卫气散失、四肢厥寒而亡阳，阳亡血耗故脉涩滞。涩脉在此反映血少、寒湿痹阻、津亏、亡阳等病机，主反胃、自汗、厥逆等症。", ["涩"]], "26434": ["主病", "原文以「弦脉主病」立题，弦为气机敛束、脉道紧张之象，主饮、主痛、主肝胆病。此段为弦脉主病总纲，提示弦脉可因饮邪停留、寒凝气滞、肝胆气郁而见，病机关键在阳气不布、水饮内停与气机不畅。", ["弦"]], "26435": ["病机", "原文言「弦脉主饮，病属胆肝」，因阳气力薄不能游溢输布，水饮停留而见弦阴敛束之脉。弦数多热，弦迟多寒，浮弦为支饮在上，沉弦为悬痛在下，阳弦头痛、阴弦腹痛。弦脉主饮又主痛，因弦寒敛束、气不舒畅，故见头痛、腹痛等症。", ["弦", "数", "迟", "浮"]], "26436": ["主病", "原文以「紧脉主病」立题，紧脉如转索，为寒邪收引、脉道拘急之象，主寒、主诸痛。此段为紧脉主病总纲，提示紧脉可因外寒束表或里寒凝滞而见，病机关键在寒邪收引、阳气被困、气血不畅。", ["紧"]], "26437": ["病机", "原文言「紧脉主寒，又主诸痛」，紧与弦相似，如转索者是也，阳为寒束故紧。浮紧为表寒，沉紧为里痛，里为阴分，寒袭阴分则阳困阴凝故痛。紧脉在此反映寒邪收引、阳气被困、气血凝滞之病机，主表寒与里寒疼痛。", ["紧", "浮", "沉"]], "26438": ["主病", "原文以「长短细大脉主病」立题，长脉气畅为平，短脉气促为病，细为正不足而气少，大为邪有余而病进。此段为长短细大四脉主病总纲，提示脉之长短细大反映气机畅促与正邪盛衰，病机关键在气之通塞与正邪之强弱。", ["长", "短", "细", "大"]], "26439": ["病机", "原文言「长脉气平，短脉气病，细则气少，大则病进」，长脉气畅故曰平，短脉气促故曰病，细为正不足故气少，大为邪有余故病进。此段以长短细大论气机与正邪，长主气畅为平，短主气促为病，细主正虚气少，大主邪盛病进。", ["长", "短", "细", "大"]], "26440": ["主病", "原文以浮长风痫、沉短宿食对举，浮为风木偏胜，风动而痫证作；沉主里，兼短则中气不运、宿食停留。又言脉虚者血虚、气实者脉实，明长短虚实各有所主，脉之虚实由气血之行使然，故本段总论长短虚实之为病。", ["浮", "长", "沉", "短"]], "26441": ["病机", "原文谓洪脉为热、其阴则虚，细脉为湿、其血则虚。洪为阳盛之象，阳有余而阴不足，故热而兼阴虚；细为阴脉，细小不振为阴湿之候，又因脉以血为体，细而血虚。二脉对举，说明热盛伤阴与湿盛血少之不同病机。", ["洪", "细", "虚"]], "26442": ["其他", "此段仅为「缓脉主病第二十七」之篇题，未出具体脉症与病机文字，故只标缓脉，归为其他。缓脉主病之实义当于后文缓大、缓细、缓涩、缓滑诸条中求之，本条不作病机推断，以免空泛。", ["缓"]], "26443": ["病机", "原文以缓脉兼诸脉言病：空疏缓大为风所至，缓慢濡细为湿所侵，缓而涩滞则血必少，缓而滑疾则内有热。同一缓脉，兼大兼细兼涩兼滑而主风、湿、血少、内热各异，说明缓脉须合兼象方能定其病机。", ["缓", "大", "细", "涩"]], "26444": ["其他", "此段仅存「濡脉主病第二十八」篇题，未载具体脉象描述与所主症候，故只取濡脉，归为其他。濡脉主病之详当参下条濡小、弱小之论，本条无原文可据，不作病机发挥。", ["濡"]], "26445": ["病机", "原文谓濡小阴虚、弱小阳竭。濡小如帛浮水面、有上无下，为阴虚之候；弱小脉体不充鼓，为阳竭之候。阳竭则阴乘阳故恶寒，阴虚则阳乘阴故发热，说明濡弱小脉所主乃阴阳偏竭、寒热由生之病机。", ["濡", "小", "弱"]], "26446": ["其他", "此段仅为「微脉主病第二十九」篇题，未出脉形与症候文字，故只标微脉，归为其他。微脉主病之实义见于下条阳微阴微之论，本条无具体原文可引，不作病机推断。", ["微"]], "26447": ["主病", "原文谓微脉按之如欲绝、若有若无，言其虚极。寸微则阳虚而阴气上入阳中故恶寒，尺微则阴虚而阳气下陷阴中故发热；男得之为虚损，女得之为泻血。说明微脉总主虚极，随寸尺部位与男女而见恶寒、发热、虚损、泻血之异。", ["微"]], "26448": ["主病", "本段为「动脉主病」总纲，点明动脉所主病证。动脉形如豆大、厥厥动摇，乃阴阳相搏之象，故主汗出、发热、痛、惊、崩中失血等症。原文以「动脉主病」立题，示动脉非平脉，其病机在于阴阳失和、气血乖乱，故列此诸症为动脉所主。", ["动"]], "26449": ["病机", "原文谓「动乃数脉见于关上下无头尾如豆大厥厥动摇」，指出动脉形数而摇。阳动则外卫不密而汗出，阴动则内守不宁而发热；阴阳不和、卫守失职，则为痛为惊，甚则崩中失血。此段以动脉释汗出、发热、痛惊、失血之病机，强调「阴阳不和」为关键。", ["动", "数"]], "26450": ["主病", "本段为「革脉主病」总纲，标举革脉所主之病。革脉外急中空，如按鼓皮，主虚寒相搏之证。原文以「革脉主病」立题，示革脉为亡血失精、半产漏下等中空之候的脉象，其病机在于虚寒相搏、外强中空。", ["革"]], "26451": ["病机", "原文谓「脉弦而芤此名为革，弦则为寒，芤则为虚」，阐明革脉由虚寒相搏而成。既虚且寒，则「徒革于外而中则空」，故男为亡血失精，女为半产漏下。此段以弦芤合革释中空之病机，强调「中空之验」为革脉主病之要。", ["革", "弦", "芤"]], "26452": ["病机", "原文谓「数脉时见一止名曰促」，促为阳盛，主上焦热聚成毒或肺痈，因脉气流行为热所碍而时一止；「缓脉时见一止名曰结」，结为阴盛，主疝瘕积郁，因脉气为积所碍故止。此段以促结二脉释阳盛阴盛之病机，并示「审止歇之多寡而断病之轻重」。", ["促", "结", "数", "缓"]], "26453": ["主病", "本段为「代脉主病」总纲，标举代脉所主之病。代脉止有常数、止而不还，主气衰、泄脓血、伤寒心悸、女胎三月等证。原文以「代脉主病」立题，示代脉为元气衰微、气血不续之候，其病机在于脏气衰败、脉道不继。", ["代"]], "26454": ["病机", "原文谓「代则气衰」，指出代脉止而不还、有常数如更代，非元气衰微之甚不至此。泄脓血者荣血耗竭，故见欲脱不续之状；伤寒心悸乃中气下陷、汗后里虚；女胎三月心包络用事，胎赖血养，分气及胎则「脉必虚代矣」。此段以代脉释气衰、血竭、里虚之病机。", ["代", "虚"]], "26455": ["预后", "本段为「脉病顺逆」总纲，专论脉症相应与否以判顺逆。原文未出具体脉名，纯以篇题标示主旨，示脉病之顺逆当据脉象与病证是否相合而断，顺则易愈，逆则难治，属脉学预后判断之总则。", []], "26456": ["病机", "原文未出具体脉名，只论“脉之主病有宜不宜，阴阳顺逆凶吉可推”。其要在“有是病则有是脉，如影之随形”，故以脉病相宜为顺、不相宜为逆；表病见阳脉、里病见阴脉为顺，反此则逆。此段讲脉证相应之理，非专主一病，故归病机。", []], "26457": ["其他", "此段仅为“中风脉证第三十五”篇题，无脉象描述与病机论述，故脉象要素为空。篇题标示下文将论中风之脉证宜忌，本身不主病机，归其他。", []], "26458": ["主病", "原文以“中风浮缓”为脉证相宜，若“急强而实”则主病重故忌；浮滑为“中痰”，沉迟为“中气”，尸厥则“沉滑”而卒不知人。入脏身冷、入腑身温，示邪从阴从阳之别。诸脉各主中风、中痰、中气、尸厥之不同病机与症候。", ["浮", "缓", "急", "实"]], "26459": ["其他", "此段仅为“风寒脉证第三十六”篇题，无脉象描述与病机分析，故脉象要素为空。篇题标示下文论风寒之脉证，本身不主病机，归其他。", []], "26460": ["病机", "原文以“风伤于卫，浮缓有汗；寒伤于荣，浮紧无汗”对举。风邪伤卫，卫气受伤则腠理疏泄，故脉浮缓而有汗；寒邪伤荣，荣血受伤则腠理固密，故脉浮紧而无汗。浮为邪在表，缓紧分风寒，汗之有无应卫荣受邪之别。", ["浮", "缓", "紧"]], "26461": ["其他", "此段仅为“暑湿脉证第三十七”篇题，无脉象描述与病机论述，故脉象要素为空。篇题标示下文论暑湿之脉证，本身不主病机，归其他。", []], "26462": ["病机", "原文谓“暑伤于气，脉虚身热；湿伤于血，脉缓细涩”。暑为阳邪，性热而散，耗伤元气，故脉虚而身热；湿为水湿，与血相近，伤血分则脉缓细涩。虚示气耗，缓细涩示湿滞血分，脉症相应。", ["虚", "缓", "细", "涩"]], "26463": ["其他", "此段仅为“伤寒脉证第三十八”篇题，无脉象描述与病机分析，故脉象要素为空。篇题标示下文论伤寒之脉证，本身不主病机，归其他。", []], "26464": ["预后", "伤寒热病为火邪有余，故脉喜浮洪，脉症相应则吉；若见沉微涩小，是阳病见阴脉，正不胜邪故凶。汗后脉静身凉为邪解正复；汗后脉躁热甚则正气已衰，必难。上不至关阴气绝、下不至关阳气竭，代脉止歇为脏绝，散脉无根则形损难医，皆言脉症顺逆之预后。", ["浮", "洪", "沉", "微"]], "26465": ["病机", "饮食自倍肠胃乃伤，食滞于中，气口脉紧急而带滑，滑主宿食、急主气争；劳倦伤脾，右关脾脉大而弱，大为脾虚气浮、弱为力乏。二脉分主饮食与劳倦内伤，皆内伤脾胃之病机，非外感所致。", ["急", "滑", "大", "弱"]], "26466": ["其他", "此段仅为「气病脉证第四十」篇题，无脉象描述与病机论述，故脉象要素为空。篇题标示该篇专论气病之脉证，属篇章分类，不涉具体脉理，不能据以推断病机，故归其他。", []], "26467": ["病机", "七气为内因，病在里，故脉沉；沉之极按至骨犹不显露是为伏，示气机郁闭深重；涩为往来不利，弱为无力衰微，皆七气内伤日久、气血不畅之象。原文以沉、伏、涩、弱递进，说明气郁由浅入深、由实转虚的病机层次。", ["沉", "伏", "涩", "弱"]], "26468": ["其他", "此段仅为「六郁脉证第四十一」篇题，无脉象写法与病机文字，故脉象要素为空。篇题标示该篇专论六郁之脉证，属篇章分类，不涉具体脉理与症候，不能据以分析病机，故归其他。", []], "26469": ["病机", "六郁为内因，故脉多沉。沉而滑为停痰之郁，沉而紧为食积之郁，沉而涩为气虚不舒之郁，沉而芤为血虚不濡，沉而数为火伏，沉而细为湿著。原文以沉为基，兼脉各主一郁，示六郁相因为病、气血怫郁之病机。", ["沉", "滑", "紧", "涩"]], "26470": ["其他", "此段仅为「痰病脉证第四十二」篇题，无脉象描述及病机文字，故脉象要素为空。篇题标示该篇专论痰病之脉证，属篇章分类，不涉具体脉理与症候，不能据以推断病机，故归其他。", []], "26471": ["病机", "滑脉往来流利如珠应指，故主多痰；弦为木盛脾受制，故主留饮。内有热则滑数，里有寒则弦紧；浮滑兼风，沉滑兼气，食伤则短疾，湿留则濡细。原文以滑脉为主，兼脉各有所主，示痰饮寒热虚实兼夹之病机。", ["滑", "弦", "数", "紧"]], "26472": ["主病", "本段以「疾脉」论疟疾脉证。疾脉主热盛，疟邪伏于少阳，寒热交作，热势鸱张则脉行急疾。原文以疾脉统言疟证之脉，提示疟发时阳热亢盛、邪正交争之急象，与壮热、烦渴、寒热往来等症相应，为辨疟属热盛之脉据。", ["疾"]], "26473": ["病机", "原文「疟脉自弦」，因疟系少阳胆经之邪，胆属甲木，故脉自弦；「弦数者热」为邪郁化热，「弦迟者寒」为寒邪偏胜；「代散者折」指脉代止而散，乃正气虚脱、邪盛正衰，故主凶折。此段以弦为纲，兼数、迟、散以辨寒热与预后。", ["弦", "数", "迟", "散"]], "26474": ["其他", "本段仅为「泄泻脉证第四十四」之篇题，未出具体脉象与脉理文字，无可据以分析之脉。篇题提示下文当论泄泻诸脉，然本段本身无脉象描述，故脉象要素为空，主旨归为其他，不作病机推断。", []], "26475": ["预后", "原文谓「泄泻下痢沉小滑弱则吉，实大浮洪则恶」。沉小滑弱为脉证相合、正气尚支之象；实大与虚相反、浮洪与里相反，乃邪盛正衰，再加发热便是恶候。此段以脉之沉小滑弱与实大浮洪对举，辨泻痢之吉凶预后，非单论病机。", ["沉", "小", "滑", "弱"]], "26476": ["其他", "本段仅为「呕吐反胃脉证第四十五」之篇题，未载具体脉象及脉理。篇题示下文当论呕吐反胃之脉证宜忌，而本段自身无脉象可析，故脉象要素为空，主旨列为其他，不臆测病机。", []], "26477": ["预后", "原文「呕吐反胃浮滑者昌」，浮滑示胃气尚存故昌；「弦数紧涩结肠者亡」，弦为木克土、数为邪火、紧为寒邪、涩为血少，加之大肠秘结则阴液枯竭、水谷之海枯槁，故主亡。此段以浮滑与弦数紧涩对举，辨呕吐反胃之吉凶。", ["浮", "滑", "弦", "数"]], "26478": ["主病", "本段以「脉代」论霍乱之候。霍乱卒吐暴下，阴阳乖离，元气骤伤，故脉或代止；原文谓「脉代勿讶」，示此代脉乃暴伤所致而非脏气衰败之常代，与吐利交作、挥霍撩乱之症相应，为霍乱主病之脉象。", ["代"]], "26479": ["预后", "原文「霍乱之候脉代勿讶」，因卒吐暴下元气骤伤，代止不足惊；「厥逆迟微是则可怕」，手足厥逆过肘至膝而脉又迟微，系阳气大衰、元气将脱，故主多凶。此段以代脉与迟微对举，辨霍乱之可治与危候。", ["代", "迟", "微"]], "26480": ["其他", "本段为咳嗽脉证总论标题，未出具体脉象，故脉素从缺。原文以“咳嗽脉证第四十七”标目，提示后文将分述咳嗽之脉与证，属篇章提纲，非主病、病机或预后之具体论断，故归“其他”。", []], "26481": ["病机", "原文谓“咳嗽多浮”，因风寒伤皮毛、痰饮停胸胃，肺气上逆故脉浮；又言“沉紧小危”，沉则邪入里，紧则寒不散，小则正气衰，三者并见主病危；若“浮濡”则邪在表，故云易治。此段以脉之浮沉紧小辨咳嗽之表里寒热及正气盛衰。", ["浮", "沉", "紧", "小"]], "26482": ["其他", "本段为“喘急脉证第四十八”标题，仅见“急脉”二字，未展开具体脉象与病机分析，属篇章标目，故归“其他”。", ["急"]], "26483": ["预后", "原文以“浮滑者顺”言喘急息肩，浮为阳为表为风，滑为阳为痰为食，外邪闭遏胸膈痞塞，散邪则痞通故顺；“沉涩肢寒散脉逆证”，沉为阴为里，涩为阴为虚，元气不能接续而四肢寒，更见散脉则真元将随喘而散，故为逆证。此段以脉判喘急之顺逆预后。", ["浮", "滑", "沉", "涩"]], "26484": ["其他", "本段为“火病脉证第四十九”标题，未出具体脉象与病机论述，属篇章提纲，故归“其他”。", []], "26485": ["病机", "原文言“病热有火洪数可医”，火热为病，脉应洪数，脉证相宜故可治；若“沉微无火无根者危”，沉微为阴脉，是无火之象，知为无根阳虚而见热象，故主危殆。此段以洪数与沉微辨火热病之真火与无根假热。", ["洪", "数", "沉", "微"]], "26486": ["其他", "本段为“骨蒸脉证第五十”标题，未出具体脉象与病机分析，属篇章标目，故归“其他”。", []], "26487": ["预后", "原文谓“骨蒸发热脉数而虚”，内伤虚劳之热，脉数而虚是其本然；若“热而涩小必殒其躯”，涩则精血少，小则元气衰，真阴日损，故必至殒躯。此段以数虚与涩小辨骨蒸发热之常与危，主预后不良。", ["数", "虚", "涩", "小"]], "26488": ["其他", "本段仅为篇题「劳极脉证第五十一」，未载具体脉象与证治内容，故无从分析其病机。原文无脉象描述，亦无相关症候，仅提示该篇讨论劳极的脉证，具体内容缺失，不能强解。", []], "26489": ["病机", "原文谓「劳极诸虚浮软微弱」，浮软微弱皆虚损之象，主劳极诸虚。又言「土败双弦火炎急数」，双弦为土败木贼，急数为火炎于内。劳极者五劳六极，气血日耗，形体渐衰，故脉随病呈虚象，与五脏劳伤及六极虚损症候相应。", ["浮", "软", "微", "弱"]], "26490": ["其他", "本段仅为篇题「失血脉证第五十二」，未载具体脉象与证治内容，故无从分析其病机。原文无脉象描述，亦无相关症候，仅提示该篇讨论失血的脉证，具体内容缺失，不能强解。", []], "26491": ["预后", "原文谓「诸病失血脉必见芤缓小可喜数大可忧」。失血后脉芤为常，缓小不足与病相宜，故可喜；若脉数而大，则邪盛正衰，火烁真阴，诚可忧。此以脉象判断失血证之预后吉凶，芤缓小主正虚尚能相应，数大主火盛阴伤，病进。", ["芤", "缓", "小", "数"]], "26492": ["其他", "本段仅为篇题「瘀血脉证第五十三」，未载具体脉象与证治内容，故无从分析其病机。原文无脉象描述，亦无相关症候，仅提示该篇讨论瘀血的脉证，具体内容缺失，不能强解。", []], "26493": ["病机", "原文谓「瘀血内蓄却宜牢大沉小涩微反成其害」。血蓄于内，瘀滞不行，脉宜牢大，因病呈象，逐之使去则致新不难；设脉沉小涩微，是病有余而脉不足，正虚不能运化，反成其害。此论瘀血脉象与病机顺逆，牢大主瘀实可攻，沉小涩微主正虚病进。", ["牢", "大", "沉", "小"]], "26494": ["其他", "本段仅为篇题「精浊脉证第五十四」，未载具体脉象与证治内容，故无从分析其病机。原文无脉象描述，亦无相关症候，仅提示该篇讨论精浊的脉证，具体内容缺失，不能强解。", []], "26495": ["病机", "原文谓「遗精白浊微涩而弱火盛阴虚芤濡洪数」。肾虚不能藏摄，精浊下泄，故脉微涩而弱，主肾虚不固；若见芤濡洪数，芤濡为阴虚，洪数为火盛，主火盛阴虚。此辨精浊虚实两途：微涩弱属虚寒不藏，芤濡洪数属阴虚火旺，与遗精白浊症候相应。", ["微", "涩", "弱", "芤"]], "26496": ["其他", "本段仅为「三消脉证第五十五」的篇题，未载具体脉象与病机内容，故无从分析脉象所主病机。原文无脉象描述，亦无论述文字，仅标示篇章范围，属篇目提示，不涉及具体脉证关系。", []], "26497": ["预后", "原文以「浮大者生」与「细小微涩形脱可惊」对举，论三消预后。浮大示津液未枯、气血尚和，故生；细小微涩则气血虚衰枯槁，形气两败，故可惊。脉象直接反映津液气血之存亡，而非单主某证，重点在判断疾病转归吉凶。", ["浮", "大", "细", "微"]], "26498": ["其他", "本段仅为「小便淋閟脉证第五十六」的篇题，未载具体脉象与病机内容，故无从分析脉象所主病机。原文无脉象描述，亦无论述文字，仅标示篇章范围，属篇目提示，不涉及具体脉证关系。", []], "26499": ["主病", "原文言淋閟「鼻头色黄涩小无血数大何妨」，涩小为正衰无血，数大为火象，火证见之无妨。淋由肾虚膀胱热，劳动火盛搏气而成，脉涩小示血少正衰，数大示火盛，故脉象主淋閟之病机，并判轻重。", ["涩", "小", "数", "大"]], "26500": ["其他", "本段仅为「大便燥结脉证第五十七」的篇题，虽标注脉象写法「结脉、脉」，但原文未展开论述，无具体脉象与病机分析，故无从紧扣原文分析所主病机。仅标示篇章范围，属篇目提示。", ["结"]], "26501": ["病机", "原文「阳数而实阴迟而涩」以脉分气血阴阳。燥结由血液少火气盛，火盛属阳，脉见数实为有余；血少属阴，脉见迟涩为不足。脉象直接反映燥结之气血属性，故主病机在辨阴阳虚实，指导辨证用药。", ["数", "实", "迟", "涩"]], "26502": ["其他", "本段仅为「癫狂脉证第五十八」的篇题，未载具体脉象与病机内容，故无从分析脉象所主病机。原文无脉象描述，亦无论述文字，仅标示篇章范围，属篇目提示，不涉及具体脉证关系。", []], "26503": ["预后", "原文「浮洪吉兆沉急凶殃」论癫狂预后。癫为重阳，狂为重阳，浮洪为阳脉，阳病得阳脉，与证相宜，故吉；沉急则入阴迫里，强急不柔，是无胃气，故凶。脉象反映阴阳顺逆与胃气存亡，主判断吉凶。", ["浮", "洪", "沉", "急"]], "26504": ["其他", "此段仅为痫病脉证篇题，未出具体脉象文字，故脉象要素为空。篇题标示该篇专论痫病之脉与证，属总纲性标目，提示后文将辨痫病虚实阴阳。因原文无脉象描述，不能推演病机，仅可定为其他类。", []], "26505": ["病机", "原文提出痫脉宜虚不宜实，实而急为无胃气之恶候；又谓浮则痫发于阳，沉则痫发于阴，滑则多痰，数则多热。其病机为惊动脏气不平，郁而生痰涎，闭塞诸经。故脉虚为正气尚存，实急为邪盛胃气败；浮沉分病位阴阳，滑数示痰热之偏，皆因脉以知病。", ["虚", "实", "急", "浮"]], "26506": ["其他", "此段为喉痹脉证篇题，原文未载具体脉象，故脉象要素为空。篇题标明该篇专论喉痹之脉与证，属标目性文字，提示后文将辨喉痹寒热及缠喉、走马等危候。因无脉象描述，不能分析具体病机，仅归其他类。", []], "26507": ["病机", "原文谓喉痹脉多数为热，火盛气结、痰涎壅塞致喉肿难通；间有脉迟者，为外寒袭入经脉、经气郁滞，当温散。缠喉风、走马喉痹乃火中挟风、风火交煽，发病凶暴，脉应浮大洪数；若反见微伏，是邪盛正衰，故曰难治。脉数与迟分寒热，微伏示正衰。", ["数", "迟", "微", "伏"]], "26508": ["其他", "此段为眩晕脉证篇题，原文未出具体脉象，故脉象要素为空。篇题标示该篇专论眩晕之脉证，属总纲标目，提示后文将辨眩晕属风、火、痰、死血、虚等不同病机。因无脉象文字，不能作具体脉机分析，仅列其他类。", []], "26509": ["病机", "原文谓眩晕有火、有痰、有死血、有虚。左脉涩为死血，因血死则脉凝泣滞涩不流利，血不上荣而眩晕时作；右手大而无力为气虚，右主肺脾气及命门真火，大而无力则气虚眩晕。火性上炎冲巅、痰浊随气上升，皆致旋转昏冒，故脉象以涩、大无力辨死血与气虚。", ["涩", "大"]], "26510": ["其他", "此段为头痛脉证篇题，原文未载具体脉象，故脉象要素为空。篇题标明该篇专论头痛之脉与证，属标目性文字，提示后文将按浮、紧、洪、细、缓滑、弦软、微涩、弦坚、短涩等脉辨头痛之因。因无脉象描述，不能分析病机，仅归其他类。", []], "26511": ["病机", "原文谓头痛多弦，因邪束于外、阳郁于中；浮属风、紧属寒、洪属热、细属湿、缓滑属痰、弦软属气虚、微涩属血虚、弦坚属肾虚肾气厥逆，甚则真头痛；短涩则阳脱于上、阴衰于下，手足厥寒至节者不治。诸脉各主一因，须合兼症辨脏腑寒热虚实。", ["弦", "浮", "紧", "洪"]], "26512": ["其他", "原文仅存篇题「心腹痛脉证第六十三」，未载具体脉象文字，故无从分析脉象所主病机。此段为篇目提示，内容指向心腹疼痛的脉证辨识，但缺乏脉象描述与证候对应，不能推断具体病机。", []], "26513": ["预后", "原文以「细迟从吉，浮大延久」为纲，细迟示气减舒徐、厥邪衰退，故主吉；浮大则邪方盛，心腹里证反见表脉，非所宜，故难愈。九类心腹痛（饮、食、风、寒、热、悸、虫、忤、疰）皆可据此脉判预后，脉证相合则安，脉证相违则迁延。", ["细", "迟", "浮", "大"]], "26514": ["其他", "原文仅存篇题「疝气脉证第六十四」，未载具体脉象文字，故无从分析脉象所主病机。此段为篇目提示，内容指向疝气的脉证辨识，但缺乏脉象描述与证候对应，不能推断具体病机。", []], "26515": ["预后", "疝气由寒湿积郁于里，气聚敛束，故脉弦急。弦急而牢，示积聚有根、元本壮实，脉症相宜，故主生；若但急而弱，急为邪盛，弱为正衰，积聚在里而正不胜邪，故主死。此以牢弱分根气之盛衰，判疝气之吉凶。", ["弦", "急", "牢", "弱"]], "26516": ["其他", "原文仅存篇题「腰痛脉证第六十五」，未载具体脉象文字，故无从分析脉象所主病机。此段为篇目提示，内容指向腰痛的脉证辨识，但缺乏脉象描述与证候对应，不能推断具体病机。", []], "26517": ["病机", "腰痛脉多沉弦，沉为在里，弦则为痛，故诸经腰痛多见此。兼浮者风，风虚外浮；兼紧者寒，寒性敛束；兼滑者痰饮，滑利流注；兼濡细者肾著，湿渗著滞；兼大者肾虚，虚大不敛；兼沉实者闪肭，瘀血气滞凝滞。各脉分主风、寒、痰饮、肾著、肾虚、闪肭之病机。", ["沉", "弦", "浮", "紧"]], "26518": ["其他", "原文仅存篇题「脚气脉证第六十六」，未载具体脉象文字，故无从分析脉象所主病机。此段为篇目提示，内容指向脚气的脉证辨识，但缺乏脉象描述与证候对应，不能推断具体病机。", []], "26519": ["病机", "脚气成于寒湿者多，脉迟为寒，数则为热，浮滑者风，濡细者湿，总不出寒热风湿四者。发于三阳者轻，脉多浮；发于三阴者重，脉多沉。迟数分寒热，浮滑濡细辨风湿，脉象与三阴三阳之轻重相应，示脚气病机之大概。", ["迟", "数", "浮", "滑"]], "26520": ["其他", "本段仅为痿病脉证篇题，未载具体脉象与病机内容，故无从分析所主病机。原文无脉象描述，亦无相关症候论述，仅标示篇章范围。", []], "26521": ["病机", "原文谓痿病肺虚脉多微缓或涩或紧或细或濡，以微应皮毛、缓应肌肉、涩应血脉、紧应筋膜、细濡应骨髓，说明痿病由肺叶热焦、皮毛虚弱急薄所致，脉象随所应组织而异，主肺虚及五脏荣俞失调，治当察脉盛衰以调虚实。", ["微", "缓", "涩", "紧"]], "26522": ["其他", "本段仅为痹病脉证篇题，未载具体脉象与病机内容，故无从分析所主病机。原文无脉象描述，亦无相关症候论述，仅标示篇章范围。", []], "26523": ["病机", "原文谓风寒湿三气杂至合而为痹，脉浮涩而紧三脉乃备，浮为风、涩为湿、紧为寒，一脉中见此三种始为三邪杂合。若邪有偏胜，又当审脉之浮多涩多紧多以别行痹、痛痹、著痹，说明痹病由三邪杂合、偏胜致痹的病机。", ["浮", "涩", "紧"]], "26524": ["其他", "本段仅为五疸脉证篇题，未载具体脉象与病机内容，故无从分析所主病机。原文无脉象描述，亦无相关症候论述，仅标示篇章范围。", []], "26525": ["病机", "原文谓五疸实热脉必洪数，涩微属虚，切忌发渴。疸由脾胃湿热郁蒸，外不得通内不得泄而成，实热则脉洪数，虚则脉涩微。渴为里热，疸为表蒸，表里热亢阴伤，故最忌发渴多饮，说明五疸以湿热为根、虚实分脉的病机。", ["洪", "数", "涩", "微"]], "26526": ["其他", "本段仅为水病脉证篇题，未载具体脉象与病机内容，故无从分析所主病机。原文无脉象描述，亦无相关症候论述，仅标示篇章范围。", []], "26527": ["病机", "原文谓脉得诸沉责其有水，浮气与风，沉实或里，沉数为阳，沉迟为阴，浮大出厄，虚小可惊。水气四类虽异，脉皆兼沉，以沉下水之性；沉数主阳水热多，沉迟主阴水寒多；浮大示水气涣散将愈，虚小则正衰邪存可惊，说明水病脉象与阴阳虚实病机。", ["沉", "浮", "数", "迟"]], "26528": ["其他", "本段仅存篇题「胀满脉证第七十一」，未录具体脉象文字，故无从据脉析机。篇题标明所论为胀满病之脉证，提示下文当以脉辨胀满之虚实寒热，然原文脉名未识别，不能臆断其脉为何、主何病机，仅可定为胀满脉证总纲之目。", []], "26529": ["病机", "原文以「胀满脉弦土制于木」立论，弦为木脉，见于胀满知木来侮土，故不吉；「湿热数洪」言数洪主湿热郁蒸；「阴寒迟弱」言迟弱主阴寒凝滞；又「浮为虚满，紧则中实」，浮则气散中虚，紧则气敛中实。诸脉皆统于脾胃，说明胀满实少虚多、热少寒多之病机。", ["弦", "数", "洪", "迟"]], "26530": ["其他", "本段仅存篇题「积聚脉证第七十二」，未录脉象原文，脉名亦未识别，故不能据脉论机。篇题示所论为积聚之脉证，积聚分五脏六腑，其脉当有沉伏浮动之别，然本段无文可征，只能定为积聚脉证之目，不作病机推断。", []], "26531": ["预后", "原文以「实强者生，沉细者死」判积聚生死。实强为阳脉，既征邪正相搏，又征元本壮实，从腑从阳故生；沉细为阴脉，既征邪气深入，又征元本衰微，故死。并以阴沉而伏属脏、阳浮而动属腑，说明积聚脉之沉伏留止与浮动聚散，关乎脏腑阴阳与吉凶。", ["实", "强", "沉", "细"]], "26532": ["其他", "本段仅存篇题「中恶脉证第七十三」，未录具体脉象，脉名未识别，故无从析其病机。篇题示所论为中恶之脉证，中恶乃卒中外邪之暴病，其脉当有紧细浮大之辨，然本段无原文可据，仅能定为中恶脉证之目，不作臆测。", []], "26533": ["预后", "原文言「中恶腹胀紧细者生」，紧细为正气尚能收敛充实之象，药力一助则紧者仍舒、细者仍充，故知生；「脉若浮大邪气已深」，浮大则正气散越，邪必深入，故难治。说明中恶卒中外邪、气机敛实致腹胀，脉之紧细与浮大关乎正邪胜负与预后。", ["紧", "细", "浮", "大"]], "26534": ["其他", "本段仅存篇题「痈疽脉证第七十四」，未录脉象文字，脉名未识别，故不能据脉论机。篇题示所论为痈疽之脉证，痈疽乃营卫壅塞、郁热成脓所致，其脉当有浮数洪大之辨，然本段无文可征，仅定为痈疽脉证之目。", []], "26535": ["病机", "原文「痈疽浮数」言血泣气从、邪正相郁化热故数，在表在阳故浮，正邪相搏故恶寒发热；「脉数发热而痛者阳」，「不数不热不疼」为阴疮；未溃不怕洪大，已溃洪大可怕。说明痈疽脉浮数主阳毒化热成脓，洪大之吉凶随溃与未溃而异，关涉毒从外泄或内陷。", ["浮", "数", "洪", "大"]], "26536": ["其他", "本段仅标目「肺痈脉证第七十五」，未载具体脉象文字，故无从分析脉象所主病机。原文未出现脉象描述，亦未涉及症候与脉之对应关系，仅提示该篇专论肺痈之脉证，属篇章标题，非脉诊内容。", []], "26537": ["病机", "原文以「寸数而实」主肺痈已成，数实为上焦郁热壅盛、腐化为脓；「数而无力」主肺痿，数为热而无力为虚，乃津枯气馁。肺痈「脉宜短涩」者，短涩应肺之常，色脉相符；「不宜浮大」，浮大为火上炎，火克金则唾糊呕血，脏伤故危。全段以脉之虚实辨痈痿，以浮大判逆。", ["数", "实", "虚", "浮"]], "26538": ["其他", "本段仅标目「肠痈脉证第七十六」，未载具体脉象文字，故无从分析脉象所主病机。原文未出现脉象描述，亦未涉及症候与脉之对应关系，仅提示该篇专论肠痈之脉证，属篇章标题，非脉诊内容。", []], "26539": ["病机", "原文谓肠痈「实热滑数可知」，滑数主实热壅结、久郁腐脓；「数而不热关脉芤虚」者，数而无力为虚，芤主血虚，示痈未成脓而正气已伤；「微涩而紧」为脓未成、可下之征，紧数则脓已成，切不可下，下则夺生新之气。全段以脉之滑数、芤虚、紧数辨脓成未成及可下不可下。", ["滑", "数", "芤", "紧"]], "26540": ["其他", "本段仅标目「胎产脉证第七十七」，未载具体脉象文字，故无从分析脉象所主病机。原文未出现脉象描述，亦未涉及症候与脉之对应关系，仅提示该篇专论妇人胎产之脉证，属篇章标题，非脉诊内容。", []], "26541": ["妇人", "原文以「少阴动甚谓之有子」，少阴属肾，动甚为阴搏阳、血聚成胎；「尺脉滑利」主妊娠，滑为血敛结之象；「滑疾不散」应胎三月，「但疾不散」应五月，疾而不散示胎渐实；「左疾为男右疾为女」以左右分阴阳；「新产脉缓滑为吉」，缓滑示气血和畅，「实大弦牢」则逆，为邪实正伤之候。", ["动", "滑", "疾", "牢"]], "26542": ["其他", "本段仅标目「小儿脉证第七十八」，未载具体脉象文字，故无从分析脉象所主病机。原文未出现脉象描述，亦未涉及症候与脉之对应关系，仅提示该篇专论小儿之脉证，属篇章标题，非脉诊内容。", []], "26543": ["小儿", "原文谓「小儿之脉七至为平」，七至即一息七至，为小儿气血未定之常脉，故以七至为平和之准。然小儿脉不足据，须「更察色证与虎口纹」，三岁以下视虎口三关纹色：紫主内热、红主伤寒、青主惊风、白主疳、黑主危证，淡黄淡白则无病。此段以平脉为纲，强调脉证合参。", ["平"]], "26544": ["其他", "本段仅为「奇经八脉脉证第七十九」的篇题，未载具体脉象与证候文字，故无从据脉论病机。篇题提示下文将论奇经八脉的脉形与所主病证，属总纲性标目，非具体脉证条文，不能凭空推演病机，只可视为奇经脉证论述的引端。", []], "26545": ["病机", "原文以「直上直下」之脉分诊奇经：浮则为督，牢则为冲，紧则为任，寸关尺左右弹指分属跷、带、维脉。脉直上直下而浮，主督脉为病脊强癫痫；牢主冲脉逆气里急；紧主任脉七疝瘕坚；左右弹指主动，主跷脉阴缓阳急、带脉带下脐痛。此以脉形定八脉病机，脉证相应。", ["浮", "牢", "紧", "动"]], "26546": ["其他", "本段仅为「反关脉第八十」的篇题，未出具体脉象与证候，故不能据脉论病机。篇题标示下文将述反关脉的诊法及部位异常，属标目性文字，非脉证条文，不可臆测其主病，只可视为反关脉专论的引端。", []], "26547": ["平脉", "原文言「平人无脉」非真无脉，乃寸口不应指而脉从尺旁斜出列缺、阳谿之外络，谓之反关脉。其三部九候浅深与常人无异，故仍属平脉变异，非病脉。所谓「兄位弟乘」只是部位反常，千百中仅一二，主在说明诊脉须知变通，不可因寸口无脉即断为病。", []], "26548": ["其他", "本段仅为「真脏脉第八十一」的篇题，未载具体脉形与证候，故不能据以分析病机。篇题提示下文将论真脏脉，属标目性文字，非脉证条文，不可凭空推断主病，只可视为真脏脉专论的引端。", []], "26549": ["死脉", "原文列真脏绝脉：肝绝「循刀责责」劲急无和缓，心绝「转豆躁疾」厥厥动摇，脾绝雀啄、屋漏、流水、杯覆，肺绝如毛无根萧索，肾绝如弹石去如解索，命绝虾游鱼翔。皆胃气已无、真脏独见之象，故主死。脉失冲和胃气，脏真外露，即「真脉既形，胃已无气」。", ["弦", "疾", "毛", "弹石"]], "26550": ["其他", "本段仅为「续集脉诀四言举要卷下」的篇题，未载具体脉象与证候文字，故无从据脉论病机。篇题标示此为四言举要续集之下卷，属标目性文字，非脉证条文，不可臆测其主病，只可视为该卷论述的引端。", []], "26551": ["预后", "原文以脉与五色合参辨新久：脉小色不夺为新病，脉不夺色夺为久病，脉色俱夺为久病，脉色俱不夺为新病。脉小示邪浅病新，色夺示正气已衰，故脉色俱夺者病久正伤；脉色俱不夺则正未大伤而病尚新。此以脉色相应与否判断病之新久及预后。", ["小"]], "26552": ["平脉", "此段论色脉相合，以五色之泽夭辨生死。原文强调「能合色脉可以万全」，色如帛裹朱、鹅羽、苍璧之泽者为生，如赭、如盐、如蓝者为死。气由脏发，色随气华，色之润泽反映脏气充盛，故虽未出脉名，实以色诊合脉诊判断平脉与预后，属平脉范畴。", []], "26553": ["病机", "此段论五脏五色与寸口尺肤相应。色青脉当弦急，色赤脉浮大而散，色黄脉中缓而大，色白脉浮涩而短，色黑脉沉濡而滑。又以色脉相胜相生言病机：色青得浮涩而短为金克木，得大而缓为木克土，是相胜；得浮大而散为木生火，得小而滑为水生木，是相生。脉与色相应则顺，相胜则病。", ["弦", "急", "浮", "大"]], "26554": ["预后", "此段论治病当察形气色泽脉之盛衰。形气相得、色泽以浮、脉从四时、脉弱以滑有胃气者，皆谓之可治易已；形气相失、色夭不泽、脉实以坚、脉逆四时者，则难治或不治。脉弱以滑为有胃气之象，脉实以坚为邪盛正衰、病益甚之征，故以脉之胃气有无判预后。", ["弱", "滑", "实", "坚"]], "26555": ["其他", "此段论色味与五脏相配：白当肺辛、赤当心苦、青当肝酸、黄当脾甘、黑当肾咸，又白当皮、赤当脉、青当筋、黄当肉、黑当骨。原文以五色五味五体分属五脏，说明色味与脏腑组织相应之理，未及脉象，故属色诊与脏象相配的基础理论，非主病病机之论。", []], "26556": ["病机", "此段论五色分部以察病。原文「沉浊为内，浮泽为外」，以浮沉别脏腑浅深；「黄赤为风，青黑为痛，白为寒」，以色主病；又察浮沉知浅深、泽夭观成败、散搏知远近、上下知病处。沉浊主内主脏，浮泽主外主腑，色之浮沉反映病位深浅，故属病机分析。", ["沉", "浮"]], "26557": ["主病", "此段言病人面无血色、无寒热，而脉沉弦者主衄血。面无血色为血虚，无寒热排除外感，脉沉主病在里，弦主肝、主痛、主血病。沉弦并见，示肝经郁滞、血不循经而妄行，故主衄血。原文以「脉沉弦者衄也」直断其病，属主病之论。", ["沉", "弦"]], "26558": ["主病", "此段论目睛黄淡主脾伤泄痢，黄而浊兼面如熏为湿盛黄疸，黄如橘子明者为热多。末言「脉芤是瘀血，胸中两胁必有块」，芤脉中空如按葱管，主血虚失血，亦主瘀血内阻、血不循常道。瘀血结于胸胁，故必有块。原文以脉芤断瘀血，属主病。", ["芤"]], "26559": ["预后", "此段论目黄诸候与脉象预后。目黄大烦而脉大为病进，大脉主邪盛病进；目黄心烦而脉和者为病将愈，脉和示胃气渐复。又目睛晕黄主衄未止，平人见黑气起口鼻耳目者凶，目睛黄为酒疸，面眼胞肿为谷疸。原文以脉大与脉和对比，判病进与将愈，属预后判断。", ["大"]], "26560": ["预后", "原文以瘰疬患者目中出现赤脉贯瞳为凶候，并以赤脉条数推断死期（一脉一岁死、二脉二岁死、三脉三岁死）。赤脉贯瞳反映毒邪深入血络、上攻目窍，正气已败，故属危恶之兆；条数愈多示邪毒愈盛、预后愈差。此段无脉名可录，主旨在于凭目络形色判断瘰疬之死生。", []], "26561": ["病机", "原文以目间青脉起者主掣痛，归为少阳胆经之滞，青脉为络脉瘀滞之象，胆经循目外眦，经气不利则牵引作痛；又言瞳子高大者属太阳不足，瞳神属肾而太阳主表，瞳子高大示阳气虚浮不敛。此段从目部络脉与瞳神形态推求病机，非论寸口脉。", []], "26562": ["其他", "原文仅存「血脉」二字，为络脉之总称，前后文已佚，无从据以推断具体脉象与病机。按《灵枢》诊血脉之法，血脉指肌表可见之络脉，其色泽变化可辨寒热痛痹。此段文字过简，只能视为论述络脉的残文，不能强解为某病某脉。", []], "26563": ["病机", "原文引《论疾诊尺篇》论诊血脉（即络脉）：多赤多热、多青多痛、多黑为久痹，三色皆见者主寒热。络脉色泽反映邪之性质与浅深，赤为热盛、青为血脉凝滞作痛、黑为久病痹阻，色杂则寒热错杂。肌皮嫩薄者络脉外显易察，故可视而诊之。", []], "26564": ["病机", "原文引《素问·平人气象论》言臂多青脉主脱血，并自注「络中血脱故不红而多青」。血脱则络脉空虚，不能充盈而现赤色，反见青色，是血虚络滞之象。此以臂部络脉颜色推断失血病机，青为血少不荣，与一般青主寒痛不同，须结合脱血证候理解。", []], "26565": ["死脉", "原文举形脉相反之死候：形盛而脉细、少气不足以息者死，是形体虽丰而脉气衰微、宗气败竭；形瘦而脉大、胸中多气者死，是形消而脉反洪大、气浮无根。形与脉当相称，今形盛脉细、形瘦脉大皆阴阳离决之象，故断为死。", ["细", "大"]], "26566": ["死脉", "原文历举形脉相反之凶候：形涩脉滑、形大脉小、形小脉大、形长脉短、形短脉长、形滑脉涩，皆形与脉不相得；又肥人脉细小轻虚如丝、羸人脉躁，亦为逆。形脉相失示气血与形体不相应，正气不能充脉，故俱凶。此段以形脉逆从判断生死，非单论一脉主病。", ["涩", "滑", "小", "大"]], "26567": ["平脉", "原文言持脉时病人呵欠者无病，引经「阳引而上、阴引而下则欠」，谓阴阳相引、上下相交故欠，是阴阳调和之象，故云无病，且病亦将愈。此以呵欠这一动作判断阴阳升降如常，属平脉无病之候，非据脉象本身立论。", []], "26568": ["死脉", "原文列尸臭舌卷囊缩为肝绝，口不合为脾绝，肌肉不滑唇反为胃绝，发直齿枯遗尿为肾绝，毛焦面黑直视目瞑不见为阴气绝，目眶陷目系倾汗出如珠为阳绝系，病后喘泻为脾脉将绝，目正圆手撒戴眼为太阳绝。诸症皆脏腑精气败绝之外候，故属死脉范畴，非论具体脉象。", []], "26569": ["死脉", "脉浮而洪，身汗如油，喘而不休，此肺绝之候。浮洪为真气外散之象，汗腻不流、喘不休，说明气随汗脱，肺气将绝，故脉洪而喘不休真气外散，属死脉。", ["浮", "洪"]], "26570": ["死脉", "原文述六腑气绝足冷脚缩，五脏气绝便利不禁手足不仁；手太阴气绝则皮毛焦，津液去而皮节伤，毛折者毛先死；手少阴气绝则脉不通，血不流而色泽去，面黑如黧，血先死。皆脏腑气绝之外候，故属死脉。", []], "26571": ["死脉", "足太阴气绝则脉不荣口唇，口唇为肌肉之本，脉不荣则肌肉不滑泽，肉满唇反，肉先死。原文以唇反、肉满为脾绝之外候，说明脾气败绝，肌肉失养，故属死脉。", []], "26572": ["死脉", "足少阴气绝则骨枯，骨髓不温则肉不著骨，齿长而垢，发无润泽，骨先死；足厥阴气绝则筋缩，引卵与舌，舌卷囊缩，筋先死。原文以骨枯、舌卷囊缩为肝肾气绝之外候，故属死脉。", []], "26573": ["其他", "原文描述向壁卧、闻师到不惊起、目盼视、言三止、咽唾者，此诈病也。若脉和平，则非真病，当以针灸吐下吓其诈。脉和平为无病之象，故本条主旨为辨诈病，属其他。", ["和平"]], "26574": ["兼症", "原文“脉之呻者痛也”，谓诊脉时患者有呻吟之声，为疼痛之兼症。呻吟因痛而发，非脉象本身，故本条主旨为兼症，说明痛证可伴呻吟。", []], "26575": ["病机", "原文论伤寒舌胎，以白黄黑辨表里寒热虚实，黑胎多凶，全黑热极难治；又述中焙舌、全干等里证，当诊脉之虚实及中气何如，实者润而下之，虚人当生津固中气。脉虚实为辨治关键，故属病机。", ["虚", "实"]], "26576": ["病机", "原文谓白胎属寒，外证烦躁欲坐卧泥水中，乃阴寒逼其无根失守之火而然。脉大不鼓，大而无力，正合阴寒内盛、虚阳外浮之机，故当从阴证治；若不大躁呕吐，则从食阴治。脉大不鼓是辨阴寒逼火与食阴的关键，非实热之洪大。", ["大"]], "26577": ["其他", "此段强调视舌虽有成见，必细审兼证及脉之虚实，否则有毫厘千里之谬。原文未出具体脉象，只言“脉之虚实”，故脉象要素为空。主旨在于告诫舌色可因酸甜咸物染黑，须结合脉之虚实辨证，不可单凭舌色断病，属诊法审慎之论。", []], "26578": ["其他", "此段仅题“脉诀考证”，为篇目名称，无脉象描述，亦无病机症候可析。原文未涉及具体脉形、主病或治法，故脉象要素为空，归入其他类，不作病机推断，以免编造原文所无内容。", []], "26579": ["其他", "此段仅言“脉诀非叔和书”，属考证性论断，指出世传《脉诀》非王叔和所作。原文无脉象描写，无病机、主病或症候内容，故脉象要素为空，归入其他类，仅就文献真伪立论，不涉诊脉病机。", []], "26580": ["其他", "此段引朱子之言，谓古人察脉非一道，今世惟守寸关尺之法，而俗传《脉诀》词最鄙浅，非叔和本书，然其直指高骨为关之说可取。原文论脉法源流与《脉诀》真伪，未出具体脉象，故脉象要素为空，归入其他类。", []], "26581": ["其他", "此段引柳贯之说，考《脉诀》非叔和所作，乃宋之中世人伪托以便习肄，并辨朱子取高骨为关之说正出《脉经》。原文属脉学文献考证，无脉象形态及病机症候，故脉象要素为空，归入其他类，不妄作病机分析。", []], "26582": ["其他", "此段引谢缙翁之说，考《脉诀》起于何时，谓熙宁以后人作，陈无择言高阳生剽窃作歌诀，刘元宾从而和之，又讥陈氏自著七表八里九道之名。原文虽提及“和脉”“脉”，实为书名脉诀之论，非脉象描述，故脉象要素为空，归其他类。", []], "26583": ["其他", "此段引王世相之言，谓诊候之法不易精，轩岐、越人、叔和之书犹未尽泄其奥，高阳生《脉诀》假叔和之名，语多抵牾，辞语鄙俚，俗学妄注，世医家传户诵而茫然无所下手。原文论脉学传承与《脉诀》流弊，未出具体脉象，故脉象要素为空，归其他类。", []], "26584": ["其他", "此段述王叔和《脉经》之言可守不可变，而托名叔和之《脉诀》行世致医经之理渐微。原文谓世人因信重叔和而假其名以行，医道日浅或由此误。全段论脉书真伪与流传之弊，非论具体脉象，故无脉象要素可录，主旨属脉学源流之其他类。", []], "26585": ["病机", "戴起宗反对以表里定脉名，谓轩岐越人叔和皆不言表里，《脉诀》窃名立七表八里九道为世大惑。原文强调脉之变化从阴阳生，只可阴阳对待而言，因浮而见者为表、因沉而见者为里，不必拘于七八九之名。刘立之以浮沉迟数为纲教学，虽似捷径，仍须博学反约方入脉妙。", ["浮", "沉", "迟", "数"]], "26586": ["病机", "滑寿以阴阳表里对待为脉名之象，斥高阳生七表八里九道为凿凿附会。原文举芤脉中央空两边实，本属阴，而《脉诀》以芤为七表属阳；又引仲景脉法浮大数动滑为阳、沉涩弱弦微为阴，而《脉诀》以动为阴、以弦为阳，背误颇多，故推知《脉诀》非叔和书。此段辨脉之阴阳归属。", ["芤", "浮", "大", "数"]], "26587": ["病机", "吴澄辨俗误以《脉诀》为《脉经》，并指脉书混牢革为一。原文谓牢为寒实、革为虚寒，安可混乎；又举洪散俱大而洪有力、微细俱小而微无力，芤类浮而边有中无、伏类沉而边无中有，豆粒摇摇不定者为动，鼓皮如如不动者为革，皆对待之脉。促疾结缓可为对，代则无对，总二十七脉不止七表八里九道二十四脉。", ["牢", "革", "洪", "散"]], "26588": ["其他", "李时珍谓《脉经》论脉止二十四种，无长短二脉，《脉诀》歌脉亦二十四，增长短而去数散皆非。原文指出素难仲景论脉只别阴阳，初无定数，如素问之鼓搏喘横、仲景之惵平荣章纲损纵横逆顺之类；后世脉之精微失传，无所依准，因立名归著。学者按图索骥犹若望洋，草庐公说独得要领。", ["长", "短", "数", "散"]], "26589": ["妇人", "此段仅标目「男女脉位」，原文无具体脉象描述与病机论述，故脉象要素为空。其主旨在于讨论男女诊脉部位之异同，属妇人脉法范畴。因原文过简，仅存标题，无法据以分析具体脉象所主病机，只能就其归类为妇人脉位之辨。", []], "26590": ["妇人", "储泳论《脉诀》以女人尺脉盛弱与男子相反为背看之说。原文谓男女形体绝异、阴阳殊涂，男生而覆女生而仰，男左旋女右转，男主施女主受，男之至命在肾处脏腑极下，女之至命在乳处脏腑极上，形气既异，脉行于形气之间岂不少异，故褚氏之说为有理。此段辨男女脉位差异。", ["尺"]], "26591": ["妇人", "戴起宗驳《脉诀》因男子左肾右命、女子左命右肾之别遂言反此背看，诸家以尺脉盛弱解之，褚氏又以女人心肺诊于尺倒装五脏，其谬又甚。原文强调男女形气精血虽异，而十二经脉所行始终、五脏之定位则一，安可以女人脉位为反。此段主论男女脉位相同，纠妇人尺脉反看之误。", ["尺"]], "26592": ["平脉", "本段以律管候气、气口候脉立论，强调气口之数合于黄钟九分，脉动阳九阴一，故男子寸盛尺弱、女子尺盛寸弱，皆肖天地阴阳。此非具体病脉，而是平脉之根本：气口为脉之要会，能知人命死生。文中斥俗医诵高阳生妄作，正因不明此天人相应之平脉原理，故列平脉。", []], "26593": ["平脉", "叶氏承丹溪之说，以脉为天地元性，男女尺寸盛弱肖乎天地，肯定丹溪推本律法、混合天人而辟越人男生于寅女生于申之谬。全段主旨仍在阐明正常脉象的天地阴阳依据，属平脉理论，非论具体病脉，故脉象要素为空。", []], "26594": ["病机", "王宗正主张诊脉当从心肺俱浮、肝肾俱沉、脾在中州之说，反对叔和独守寸关尺分部位测五脏。此处浮沉非指具体病脉，而是以浮沉分脏腑上下阴阳之病机定位：心肺居上属阳故浮，肝肾居下属阴故沉，脾居中州。其意在说明脉位与脏腑气机升降的对应关系。", ["浮", "沉"]], "26595": ["病机", "赵继宗以心肺居上为阳为浮、肝肾居下为阴为沉、脾居中州半阴半阳半浮半沉立论，反对左心小肠肝胆肾、右肺大肠脾胃命的分配。文中浮沉是脏腑阴阳升降之机，非病脉；并辨肝为阴不宜居半浮半沉之左关，命门即肾不宜右尺。主旨为脉位与脏腑病机定位之辨。", ["浮", "沉"]], "26596": ["病机", "吴草庐指出两手寸关尺皆手太阴肺经之一脉，非五脏六腑各居其所，只是分部位以候他脏之气。脉行始于肺、终于肝、复会于肺，肺为气所出门户，故名气口，为脉之大会以占一身。此段讲气口候五脏之气的机理，属病机层面的脉理阐发，非具体脉象。", []], "26597": ["病机", "李时珍强调两手六部皆肺之经脉，特取以候五脏六腑之气，非脏腑所居之处。诊察以肺心脾肝肾各候一动，五十动不止则五脏皆足，内有一止则知一脏之脉不至。此以脉动至数与歇止推脏腑气之盛衰，属病机判断，非具体脉象描述，故脉象要素为空。", []], "26598": ["其他", "本段为学术辨正：肯定赵氏所云本于王宗正难经图解，指出脉分两手出于素问脉要精微论，越人推明关脉及一脉十变于难经，非始于叔和；若如赵说则一脉十变无从推之。又辨命门即肾为越人之误，自著命门考等。主旨属脉法源流与命门学说的考辨，归其他。", []], "26599": ["其他", "本段仅题「脉诀四言举要」，为篇目名称，无具体脉象描述与病机论述，无法据以分析所主病机。按体例归入其他，脉象要素为空，不作无据推演。", []], "26600": ["病机", "原文以“脉乃血沠”立论，谓脉为气血之先、血之隧道，气息应焉；又言其象法地、为血之府、心之合、皮之部。此段不涉具体脉形，而在阐明脉与气血、心、营卫的整体关系：脉行血气，内合于心，外应于皮，故察脉可测气血盛衰与心气通塞，为脉学总纲而非主一病。", []], "26601": ["病机", "原文提出“资始于肾，资生于胃”，脉气根本在肾、化源于胃；又谓阳中之阴本乎营卫，营行脉中、卫行脉外。说明脉之搏动依赖肾中元气与胃中水谷，营血充脉、卫气鼓动，二者协调则脉和。若肾胃亏虚或营卫失和，脉必随之而变，此段重在论脉之生化本源。", []], "26602": ["病机", "原文言“脉不自行，随气而至，气动脉应”，以橐龠喻气、波澜喻血，说明脉动由气所帅，气至则血行，血脉气息上下循环。动脉之应正是气机鼓动之象，故脉之动非血自跳，乃气为之主；气机失调则脉动失常，此段揭示脉动与气血循环的根本机理。", ["动"]], "26603": ["病机", "原文指出十二经皆有动脉，而独取手太阴寸口，因该经属肺、上系吭嗌，为“脉之大会、息之出入”之处。肺主气、朝百脉，呼吸之气与血脉大会于此，故寸口能反映全身气血。此段说明独取寸口的原理，动脉之动在此为脉气大会之征，非病脉。", ["动"]], "26604": ["平脉", "原文以呼吸定息：一呼一吸四至为息，昼夜一万三千五百息，脉行六寸，日夜共八百十丈为准。此以息数计脉行，说明平人脉动与呼吸相应、昼夜循行有度。四至为息即平脉之常，若息数失常则脉行失度，此段为以呼吸衡量脉象迟数的基准，属平脉常度之论。", []], "26605": ["其他", "原文讲持脉方法：令患者仰掌，掌后高骨为关，关前为阳（寸）、关后为阴（尺），先定寸关尺部位，再推寻先后。此段专论诊脉取位与阴阳分属，说明寸口三部分候阴阳的定位原则，为切脉操作规范，非论某病之脉，故归其他。", []], "26606": ["病机", "原文言神门决断在关后，人无二脉则病死不愈；男女脉同，惟尺部有异，阳弱阴盛为常，反此则病至。指出尺脉候肾与命门，男子尺部相对偏弱、女子偏盛属生理之常；若阳弱阴盛之度反常，即阴阳失衡，故曰“反此病至”，此段以尺脉强弱辨阴阳盛衰。", ["弱"]], "26607": ["其他", "原文述脉有七诊：浮、中、沉、上、下、左、右，消息求寻；又有九候，举按轻重，三部浮沉各候五动。此段讲诊脉须从浮中沉、上下左右多方位消息，并以举按轻重、五动为候，说明脉诊须全面反复体察，属诊法要领，非主一病。", ["浮", "沉"]], "26608": ["病机", "原文以寸关尺分候胸上、膈下、脐下至跟踝，并以左右脉分候左右，提出“病随所在，不病者否”。此段未言具体脉象，而论脉位与病位相应之理：脉之所在即病之所在，病在何部则脉应于何部，无病之部脉亦无异常。故其主旨为脉位分候病机的定位法则，非主某病，亦非平脉死脉。", []], "26609": ["病机", "原文以浮沉分属心肺与肾肝，脾胃居中州、居浮沉之间。心脉之浮“浮大而散”，肺脉之浮“浮涩而短”，是即浮脉中辨脏腑之象：浮大而散应心之阳气外达，浮涩而短应肺之宣降收敛。此段借浮沉之位与兼象说明脏腑常脉所在，属脉象与脏腑相应的病机定位，非专主一病。", ["浮", "大", "散", "涩"]], "26610": ["病机", "原文言肝脉之沉“沉而弦长”，肾脉之沉“沉实而濡”，脾胃属土“脉宜和缓”，命门相火左寸同断。沉而弦长应肝之条达藏血，沉实而濡应肾之封藏精气，和缓应脾胃冲和之气。此段以沉位兼弦长、实濡、和缓分述脏腑常脉，说明脉象须合脏腑本性，属平脉与病机相应之论。", ["沉", "弦", "长", "濡"]], "26611": ["平脉", "原文以“春弦夏洪秋毛冬石，四季和缓”为平脉，又言“太过实强病生于外，不及虚微病生于内”。四时各有应时之脉，和缓为四季常气；太过则实强而病生于外，不及则虚微而病生于内。此段以四时脉象为准，辨平脉与太过不及之病机，说明脉应四时、以和缓为贵，太过不及皆能为病。", ["弦", "洪", "缓"]], "26612": ["预后", "原文言“春得秋脉死在金日”，以春见秋脉为逆四时，故主危候，五脏依此类推。又强调“四时百病，胃气为本，脉贵有神”。脉失胃气、无神而逆时令，则预后不良；有胃气有神则虽病可生。此段主旨在于据脉之逆时与胃气神气判断预后，非泛论病机。", []], "26613": ["其他", "原文提出表里阴阳、风气冷热以辨内外因，须“脉证参别”，又言“脉理浩繁，总括于四”，既得提纲则可引申触类。此段未列具体脉象，旨在说明脉理虽繁，当以表里阴阳为纲，脉与证合参而辨内外病因，属脉学纲领与方法论，非主一病一脉。", []], "26614": ["病机", "原文以“浮脉法天，轻手可得，泛泛在上如水漂木”状浮脉之位，又分有力无力：有力洪大、来盛去悠，为浮而洪大之实；无力虚大、迟而且柔，为浮而虚大之不足。浮主表，洪大有力应邪盛于外，虚大迟柔应正气不足。此段以浮脉统实虚两象，说明浮脉主表及虚实之别。", ["浮", "洪", "大", "虚"]], "26615": ["病机", "原文以“沉脉法地，近于筋骨，深深在下”状沉脉之位，沉极为伏；又言有力为牢、实大弦长，牢甚则实、愊愊而强。沉主里，沉而有力实大弦长应邪实内结、牢坚之象，沉极为伏则病深。此段以沉脉统伏、牢、实诸象，说明沉脉主里及实邪内伏之病机。", ["沉", "伏", "牢", "实"]], "26616": ["病机", "原文以“无力为弱柔小如绵”释弱脉，甚则“细如蛛丝”，言弱脉体柔无力、细甚如丝，主气血不足、阳气衰微；又谓“迟脉属阴一息三至”，迟脉主寒、主阳虚。弱、细、迟并见，说明阳气虚衰、气血不足，鼓动无力，脉道不充，故主虚寒之病机。", ["弱", "细", "迟"]], "26617": ["预后", "原文言“二损一败病不可治，两息夺精脉已无气”，又列“浮大虚散或见芤革，浮小濡微沉小细弱”，皆属精气衰败、胃气将绝之脉。浮大虚散为阳气外越、阴不内守；芤革示中空失血；濡微细弱为气血俱衰。诸脉并见，说明脏气败绝，故主病不可治之预后。", ["浮", "大", "虚", "散"]], "26618": ["病机", "原文以“数脉属阳六至一息，七疾八极九至为脱”，说明数、疾、极、脱皆阳气亢盛或外越之象；又谓“浮大者洪，沉大牢实”，洪为浮大有力，牢为沉大实强。数疾洪牢并见，反映阳热亢盛、邪实内结，甚则阳气外脱，故主阳热实盛之病机。", ["数", "疾", "洪", "牢"]], "26619": ["病机", "原文以“有力为紧弹如转索”释紧脉，主寒主痛；又谓“数见寸口有止为促”，促脉主阳盛热结或气滞血瘀；更言“动脉可候厥厥动摇状如小豆”，动脉主惊主痛。紧、促、动并见，说明寒凝气滞、阳热内结、惊痛交作之病机。", ["紧", "促", "动"]], "26620": ["平脉", "原文谓“长则气治，过于本位”，言长脉为气血调和之平脉，但太过则病；又谓“长而端直弦脉应指”，说明弦脉端直以长，主肝病、痛证、痰饮；更言“短则气病，不能满部”，短脉主气损。长、弦、短对举，说明脉形长短与气机盛衰相关，本段主旨在辨平脉与病脉之形态。", ["长", "弦", "短"]], "26621": ["主病", "原文谓“一脉一形各有主病，数脉相兼则见诸证”，说明数脉兼见他脉则主病各异；又言“浮脉主表，里必不足，有力风热，无力血弱”，指出浮脉主表证，有力为风热袭表，无力为血虚气弱。本段以浮脉为例，说明脉象主病须结合有力无力以辨虚实。", ["数", "浮"]], "26622": ["主病", "原文列“浮濡阴虚，浮散虚剧，浮弦痰饮，浮滑痰热”，说明浮脉兼见他脉主病不同：浮濡主阴虚，浮散主虚极，浮弦主痰饮，浮滑主痰热；又言“沉脉主里，主寒主积，有力痰食，无力气郁”，指出沉脉主里证，有力为痰食积滞，无力为气郁。本段主论浮沉兼脉之主病。", ["浮", "濡", "散", "弦"]], "26623": ["主病", "原文谓“沉弦饮痛，沉滑宿食，沉伏吐利阴毒聚积”，说明沉脉兼弦主痰饮疼痛，兼滑主宿食内积，兼伏主吐利或阴毒聚积；又言“迟脉主脏，阳气伏潜，有力为痛，无力虚寒”，指出迟脉主脏病，有力为寒痛，无力为虚寒。本段主论沉、迟兼脉之主病。", ["沉", "弦", "滑", "伏"]], "26624": ["主病", "数脉主腑病，有力为实热，无力为疮疡，并主吐、狂；滑脉主痰饮、伤食，下焦为蓄血，上焦为吐逆。数而有力示热盛于腑，滑则痰食内滞、气血壅盛，故见吐逆狂乱、蓄血诸症，皆由实邪内扰所致。", ["数", "滑"]], "26625": ["主病", "涩脉主营血少、寒湿内中，故反胃、结肠、自汗、厥逆；弦脉主饮，病属肝胆，弦数多热、弦迟多寒。涩为血少气滞，弦为饮邪内停，数迟分寒热，故见呕逆、厥冷、痰饮之候。", ["涩", "弦", "数", "迟"]], "26626": ["主病", "浮弦主支饮，沉弦主悬饮疼痛，阳弦头痛、阴弦腹痛；紧脉主寒、主诸痛，浮紧为表寒，沉紧为里痛。弦紧相合示寒饮内盛、经脉拘急，故痛证、饮证由寒邪凝滞、阳气不通而作。", ["浮", "弦", "沉", "紧"]], "26627": ["病机", "长脉气平为常，短脉主气病，细脉主气少，大脉主病进；浮长风痫，沉短宿食，血虚则脉虚，气实则脉实。此段以脉之长短细大测气血盛衰与病势进退，虚实证候由脉之虚实相应而判。", ["长", "短", "细", "大"]], "26628": ["病机", "洪脉为热，热盛则阴液虚；细脉为湿，湿困则血虚；缓大者风，缓细者湿，缓涩为血少，缓滑为内热。诸脉示热、湿、风、血虚之机，缓脉兼见他脉以辨风、湿、血少、内热之异。", ["洪", "细", "缓", "涩"]], "26629": ["预后", "脉之主病有宜有不宜，阴阳顺逆可推吉凶。中风宜浮缓，急实则忌；浮滑为中痰，沉迟为中气。示脉证相合为顺、相反为逆，浮缓示风邪在表，急实、沉迟则示病深气滞，故为逆候。", ["浮", "缓", "实", "滑"]], "26630": ["预后", "暑伤气则脉虚身热，湿伤血则脉缓细涩；伤寒热病脉喜洪浮，若沉微涩小则证反必凶。示暑湿伤寒之脉宜与证相应，洪浮为热病顺脉，沉微涩小为阳病见阴脉，故主凶危。", ["虚", "洪", "浮", "缓"]], "26631": ["预后", "汗后脉静身凉则安，汗后脉躁热甚必难；阳病见阴脉必危殆，阴病见阳脉虽困无害。此以脉之静躁、阴阳相见证候吉凶，汗后脉躁示邪热未退，阳病见阴脉为逆，故预后不良。", ["静", "躁"]], "26632": ["死脉", "原文以「上不至关阴气已绝，下不至关阳气已竭」言关部上下脉气不相接续，阴阳离决；「代脉止歇」为脏气衰败、脉气不能接续之象，故主「脏绝倾危」；「散脉无根」则阳气浮散、根本已脱，形损难医。此段以散、代两脉并见，说明阴阳气血俱竭、脏真之气外越，属危候死脉。", ["散", "代"]], "26633": ["病机", "原文先以「气口急滑」主饮食内伤，以「脾脉大弱」主劳倦内伤；继言「欲知是气，下手脉沉」，指出气病脉多沉。沉极则伏，为气机郁滞深伏；涩弱久深，示气血不足而运行艰涩。此段以沉、伏、涩、弱说明内伤气分、脾运不健、气血郁滞之病机，与饮食劳倦所伤相应。", ["沉", "伏", "涩", "弱"]], "26634": ["主病", "原文以「浮滑兼风，沉滑兼气」言滑脉兼浮主风、兼沉主气；「食伤短疾」示食积脉短而疾；「湿留濡细」示湿邪脉濡细；「疟脉自弦，弦数者热，弦迟者寒」以弦为疟之主脉，数则热、迟则寒；「代散者折」则言代散为正气折损之危象。此段以浮、滑、沉、弦等脉辨风、气、食、湿、疟诸病及其寒热属性。", ["浮", "滑", "沉", "弦"]], "26635": ["预后", "原文言「霍乱之后，脉代勿讶」，因吐利后气血暂未复，脉代未必危；「厥逆迟微是则可怕」，厥逆而脉迟微，示阳气衰微，故可怕。咳嗽「多浮聚肺关胃」，浮为肺气上逆；「沉紧小危，浮濡易治」，沉紧小示邪闭正伤故危，浮濡示邪浅正未大伤故易治。此段以代、迟、微、浮辨霍乱后与咳嗽之预后吉凶。", ["代", "迟", "微", "浮"]], "26636": ["预后", "原文以喘急息肩「浮滑者顺」，浮滑示邪在表、正气尚能抗邪，故顺；「沉涩肢寒，散脉逆证」，沉涩肢寒为阳虚寒凝，散脉为元气浮散，故属逆证。病热有火「洪数可医」，洪数应热，脉证相符；「沉微无火，无根者危」，沉微无火而脉无根，示阳气衰败，故危。此段以浮、滑、沉、涩辨喘与病热之顺逆。", ["浮", "滑", "沉", "涩"]], "26637": ["预后", "原文言骨蒸发热「脉数而虚」，数主热、虚主阴亏；「热而涩小，必殒其躯」，涩小示阴血枯竭、脉道不利，故预后凶。劳极诸虚「浮耎微弱」为脉证相符之常；「土败双弦」示脾土衰败而肝木乘之，双弦为木克土之象；「火炎急数」示虚火亢盛、脉急数，亦属危候。此段以数、虚、涩、弦辨骨蒸劳极之预后。", ["数", "虚", "涩", "弦"]], "26638": ["预后", "原文言「诸病失血，脉必见芤」，芤为失血之常脉；「缓小可喜」示脉缓和小，气血虽伤而胃气尚存，故可喜；「数大可忧」示失血后脉数大，为邪热炽盛、阴血耗伤，故可忧。瘀血内蓄「却宜牢大」，牢大示瘀血内结、脉道壅实；「沉小涩微，反成其害」，沉小涩微示正气已衰而瘀未去，故反为害。此段以芤、缓、数、牢辨失血与瘀血之预后。", ["芤", "缓", "数", "牢"]], "26639": ["预后", "原文言遗精白浊「微涩而弱」，微涩弱示肾气不固、精浊下泄而气血不足；「火盛阴虚，芤濡洪数」，芤濡洪数示阴虚火旺、脉道不充而热盛。三消之脉「浮大者生」，浮大示阳气尚能外达；「细小微涩，形脱可惊」，细小微涩示阴精枯竭、形肉脱削，故可惊。此段以微、涩、弱、芤辨遗精白浊与三消之预后。", ["微", "涩", "弱", "芤"]], "26640": ["预后", "原文以浮洪为癫狂吉兆、沉急为凶殃，浮洪示阳热外达、气血未衰，故吉；沉急则阳郁于里、邪气闭阻，故凶。痫脉宜虚，虚则痰火未炽；实急者恶，实急示痰火壅盛、肝风内动。浮阳沉阴、滑痰数热，以脉象分阴阳痰热之属，皆紧扣癫狂痫病机。", ["浮", "洪", "沉", "急"]], "26641": ["主病", "喉痹脉数主热、迟主寒，以迟数辨寒热之性。缠喉走马为急症，脉微伏则正气衰微、邪毒内陷，故曰难治。诸风眩晕有火有痰，左涩主死血内停，右大主虚，以左右脉位分气血痰火之因，涩为血瘀、大为正虚，皆从脉象推求眩晕病机。", ["数", "迟", "微", "伏"]], "26642": ["主病", "腰痛脉多沉弦，沉主里、弦主痛，为腰府气血郁滞之常脉。兼浮者风邪外袭，兼紧者寒凝经脉，弦滑为痰饮流注，濡细为肾著湿着，大乃肾虚精气不充，沉实为闪挫瘀血内阻。以兼脉辨风、寒、痰、湿、虚、瘀诸因，紧扣腰痛病机。", ["沉", "弦", "浮", "紧"]], "26643": ["主病", "脚气脉迟主寒、数主热，浮滑为风，濡细为湿，以脉辨寒热风湿之因。痿病由肺虚而来，脉多微缓，微为气衰、缓为湿滞，或涩或紧或细或濡，皆示气血不足、经脉失养。原文以脚气与痿病并列，从脉象分述其虚实寒湿之异。", ["微", "缓", "涩", "紧"]], "26644": ["主病", "风寒湿三气合而为痹，浮涩而紧三脉乃备：浮为风、涩为湿滞、紧为寒凝，三脉并见正合痹证风寒湿杂至之机。五疸实热脉必洪数，洪数为湿热壅盛；涩微属虚，示正气已衰。原文以脉辨痹证与疸病之实热虚损，并戒发渴伤津。", ["浮", "涩", "紧", "洪"]], "26645": ["病机", "脉得诸沉责其有水，沉主里、水气内停；浮为气与风，风邪外袭、气机浮越；沉石或里，示水饮坚结于里；沉数为阳、沉迟为阴，以迟数分水病之寒热。浮大出厄示正能抗邪、预后尚可，虚小可惊示正气衰微、水邪独盛，从脉象判水气病之阴阳虚实。", ["沉", "浮", "大", "小"]], "26646": ["病机", "胀满脉弦，土制于木，弦为肝木乘脾、气机壅滞。湿热数洪，数为热、洪为湿热蒸腾；阴寒迟弱，迟弱示阳气虚衰、寒凝气滞。浮为虚满，正气外浮而中空；紧则中实，寒实内结。浮大可治示正未大伤，虚小危极示正气衰败，以脉判胀满之虚实寒热及预后。", ["弦", "数", "洪", "迟"]], "26647": ["预后", "五脏为积、六腑为聚，实强者生，示正气尚充、能抗积聚；沉细者死，示气血衰微、邪结日深。中恶腹胀紧细者生，紧为邪实、细为脉道未绝；脉若浮大则邪气已深，浮大示正气外浮、邪盛于里，故为危候。原文以脉之强弱浮沉判积聚中恶之吉凶。", ["实", "沉", "细", "浮"]], "26648": ["主病", "原文以“痈疽浮数”辨痈疽阴阳：脉浮为邪在表，数为热盛，若见恶寒发热、痛处固定，乃阳证痈疽之征；若脉不数、身不热、不痛，则属阴疮。浮数脉在此反映阳热壅聚、正邪交争之病机，故主阳证痈疽，与恶寒发热、局部疼痛相应。", ["浮", "数"]], "26649": ["主病", "原文辨肺痈与肠痈脉象：肺痈色白，脉宜短涩，因肺主气、热伤血络，短涩为邪热未深、血滞不甚之象；若见浮大，则热盛气浮，与唾糊呕血相应。肠痈实热，脉滑数可知；若数而不热，关脉芤虚，则示热未成实而血已伤，故关脉芤虚主肠痈脓血内损。", ["短", "涩", "浮", "大"]], "26650": ["病机", "原文以“微涩而紧”论痈脓未成，微涩示气血滞涩，紧主邪结，故未脓当下；若“紧数”则邪热已盛、脓已成，切不可下，下之反伤正气。后文“妇人之脉以血为本，血旺易胎，气旺难孕”指出妇人以血为用，血旺则胎易成，气偏旺则难孕，脉象当以血充为顺。", ["微", "涩", "紧", "数"]], "26651": ["妇人", "原文以“少阴动甚”为有子之征，少阴属心肾，动甚乃血聚养胎、脉气鼓动之象；尺脉滑利亦主妊娠，因尺候胞宫，滑利为血旺胎成。若滑疾不散，胎必三月；但疾不散，则五月可别。脉动、滑、疾、散在此反映胎元初结、气血壅盛之机，故主妊娠及胎月渐长。", ["动", "滑", "疾", "散"]], "26652": ["妇人", "原文以“左疾为男，右疾为女”辨胎性别，左属阳、右属阴，疾脉为气血充盛搏动之象，故左疾多男、右疾多女；又“女腹如箕，男腹如釜”以腹形别男女。欲产之脉“其至离经”，谓脉离常度、散乱无根，乃临产气血骤变之候，水下乃产，未下勿惊，示离经脉主将产。", ["疾"]], "26653": ["妇人", "原文论新产脉：缓滑为吉，因产后血虚气弱，缓滑示胃气尚和、血行未滞；若实大弦牢，则邪实气逆，故“有证则逆”，主产后病逆。又小儿之脉“七至为平”，小儿气血未充、脉数偏快，七至为常，更察色证与虎口纹以辨病。缓滑主吉，实大弦牢主逆，七至为小儿平脉。", ["缓", "滑", "实", "大"]], "26654": ["病机", "原文论奇经八脉诊法有别于常脉：直上直下之脉，浮则为督脉，牢则为冲脉，紧则为任脉。督脉行背，浮主阳经气浮；冲脉为血海，牢主深结；任脉行腹，紧主寒凝。寸左右弹为阳跷可决，弹指脉气搏动，示阳跷为病。此段以浮、牢、紧分属督、冲、任，明奇经病机。", ["浮", "牢", "紧"]], "26655": ["病机", "原文以“左右弹”辨奇经：尺左右弹为阴跷可别，关左右弹为带脉当诀，示弹指脉气搏动于尺、关不同部位，分主阴跷、带脉为病。又尺外斜上至寸为阴维，尺内斜上至寸为阳维，以脉气斜行路径别维脉。此段纯以脉位与动态辨奇经病机，未出具体脉名，故脉象要素从略。", []], "26656": ["病机", "原文列督、任、冲、带四脉为病：督脉病脊强癫痫，任脉病七疝瘕坚，冲脉病逆气里急，带脉病带下脐痛精失。此以奇经八脉各自所过部位与所系脏腑言病机，非以脉象言，故无脉名可识。四者皆属奇经为病，各有所主症候，与正经病机相参。", []], "26657": ["病机", "承上文言癫痫瘛疭寒热恍惚诸症，归于八脉脉证各有所属；又言平人无病脉而病移于外络，如兄位弟乘，取阳谿、列缺等络穴。此段主旨在明奇经八脉病证各有归属，非论脉形，故脉象要素为空。其病机为八脉失和、络脉受邪。", []], "26658": ["死脉", "原文以“循刀责责”状肝绝之脉，如循刀刃坚劲无胃气；以“转豆躁疾”状心绝之脉，如豆旋转急促躁动。二者皆真脏脉见、胃气已竭之象，故属死脉。坚劲与躁疾并见，说明脏气败绝、脉失柔和，主肝心两脏真气将绝，预后凶险。", ["坚", "疾"]], "26659": ["死脉", "原文以“弹石”状肾脉将绝，来坚如弹石、去散如解索；又以“虾游”“鱼翔”“涌泉”状命脉将绝，皆真脏脉败露之象。弹石言其坚劲无胃，解索言其散乱无根，虾游鱼翔言其乍浮乍沉、去来无定，主肾与命门真气将绝，绝在膀胱，属死脉。", ["坚", "散"]], "26660": ["预后", "原文承真脏脉既形而言“胃已无气”，又须参察色证以断吉凶，故曰“断之以臆”。此段主旨不在脉形，而在强调真脉既见则胃气已绝，当合色证综合判断预后。脉象要素为空，其病机为胃气败绝、真脏外露，属危候。", []], "26661": ["其他", "此段为石胆药材产地、形色、真伪鉴别之文，末言伪品“浑浑无脉理”，乃指石质纹理不清，非论人身脉象。全段属本草药物考订，与脉学病机无关，故脉象要素为空，主旨归其他，不涉主病兼症。", []], "26662": ["其他", "此段考订石膏与方解石之产地、形色及鉴别，言方解石“破之皆作方棱”、石膏“明莹如玉石”，皆论药石性状，非言脉诊。全段属本草药物辨识，与脉象病机无涉，故脉象要素为空，主旨归其他。", []], "26663": ["其他", "此段述赤箭（天麻）之产地、苗叶花实及根形，言其根“无心脉”，乃指药材断面无中心纹理，非论人身脉象。全段为本草形态采收考订，与脉学病机无关，故脉象要素为空，主旨归其他。", []], "26664": ["其他", "本段为独活、羌活的产地、形态与鉴别记载，未涉脉诊。文中'土脉中生'指土壤脉络，非诊脉之脉；'得风不摇，无风自动'述独摇草性状，与病机无关。故不取脉象，亦不主病。", []], "26665": ["主病", "柳太后感风不能言，脉沉而口噤。沉脉主里，风邪内中，痰气闭塞机窍，故口噤不能言；沉而不浮，说明邪已入里，非表证。许裔宗据此以药熏之取汗而愈，正是从沉脉辨里闭、以通窍发汗为治，脉症相应。", ["沉"]], "26666": ["其他", "本段述黄连产地、苗叶、采根时节及治痢诸方，未及脉象。'根紧始堪采'之紧指根条坚实，非脉紧；九盏汤主下痢不问冷热赤白，属方药主治，与脉诊无涉，故脉象从缺。", []], "26667": ["其他", "本段专论漏芦产地、茎叶花实形态及各地所出差异，末言采茎苗、采根时日，通篇无脉诊内容，亦不涉病机主病，故脉象为空，归入其他。", []], "26668": ["其他", "本段记秦艽产地、根形、花期及采根阴干，并载疗黄、发背诸方。文中'心烦热，口干，皮肉皆黄'为症状描述，未言脉象；秦艽牛乳煎取快利为治法，非脉诊病机，故脉象从缺。", []], "26669": ["其他", "本段述芍药产地、形态、赤白二种及采根，兼引崔豹《古今注》芍药名何离、赠别之义，末及张仲景治伤寒多用芍药。全段无脉象记载，亦未以脉论病机，故脉象为空。", []], "26670": ["病机", "膈间支满、喘满、心下痞坚、面黧黑，而脉沉紧。沉主里、主水，紧主寒主痛，水寒之气结于膈间，阳气不布，故喘满痞坚而面黑；得之数十日，吐下后邪未尽，木防己汤通阳利水，正合沉紧之脉。", ["沉", "紧"]], "26671": ["主病", "大黄条虽以产地形态为主，然所标脉洪而实，洪为阳盛，实为邪结，主里热壅盛、积滞内结之证。大黄苦寒攻下，正对洪实之脉，示热结阳明、腑实当下之病机，脉症与方药相应。", ["洪", "实"]], "26672": ["其他", "此段为桔梗药材形态与采收的记述，末引《古今录验》治卒中蛊下血如鸡肝、昼夜出血石余、四脏皆损惟心未毁，用桔梗捣屑酒服。原文虽标脉数，实未以脉数论桔梗病机，脉数当指蛊毒下血、脏损血脱之候，非桔梗主脉，故本条主旨属药材主治记述，脉数仅作兼见之症，不可径作病机推断。", ["数"]], "26673": ["主病", "原文引张仲景治肺咳上气、脉沉者，以泽漆汤主之。脉沉主水气内停、饮邪犯肺，肺失宣降则咳逆上气；沉为在里，说明病位在肺与里水，非表邪所致。泽漆逐水，配半夏、紫参、白前、桂、芩、参、草，正是攻逐水饮兼扶正之意，故脉沉在此标示水饮内结、肺气上逆之病机。", ["沉"]], "26674": ["主病", "原文述大戟形态，并引李绛方疗水病无问年月深浅，虽复脉恶亦主之。此处未出具体脉名，只言脉恶，指水病日久、正气已伤而脉象败坏，仍以大戟、当归、橘皮逐水。脉恶提示水邪壅盛、正气受损，故用药以逐水为主兼养血和营，服后利水二三斗，说明脉恶非绝对禁下，关键在水病实邪内结。", []], "26675": ["其他", "此段专述连翘产地、大翘小翘二种形态及花叶果实特征，并辨旱莲草与连翘名实混淆，全段未涉及脉象与病机。原文无脉名可识，主旨为药材名实考订，故归其他类，不作病机推断，以免附会。", []], "26676": ["其他", "此段记地锦草产地、性味及主治，言其味辛无毒，主通流血脉，亦治气，苗叶细弱作蔓，茎赤叶青赤，六月开红花结实。全段未出脉象，主旨为药材形性与功用记述，虽言通流血脉，但无脉症对应，故不作病机分析，归其他类。", []], "26677": ["主病", "原文引张仲景厚朴三物汤主腹胀脉数，又厚朴七物汤主腹痛胀满。脉数在此非主热，乃气机壅滞、腹满不通、郁而化热之象；厚朴、枳实、大黄行气除满、通腑泄热，服后腹中转动更服，不动勿服，说明脉数所主为实滞内结、腑气不通之腹胀，数脉反映郁滞化热之势。", ["数"]], "26678": ["主病", "原文引张仲景治消渴脉浮、小便不利、微热者，以猪苓散发其汗；又水逆、冬时寒剽如疟状亦与猪苓散。脉浮主表、主水气在表，消渴而小便不利、微热，为水停气化不利兼表邪未解，故用猪苓、茯苓、泽泻、滑石、阿胶利水兼解表，脉浮正是水气在表、当发其汗之凭据。", ["浮"]], "26679": ["其他", "此段考辨紫葳即陵霄花，引陶隐居、苏恭、《尔雅》郭注及陆机、孔颖达疏义，辨陵时与陵霄名实之误，指出陵霄非草类。全段为药材名实考证，未出脉象，亦无病机症候可论，故归其他类，不作脉学推断。", []], "26680": ["其他", "本段为《本草图经》豚卵条，述猪之别名、食用宜忌及心、肺、肝等脏器主治，通篇未言脉象。所谓“食之多暴肥，盖风虚所致”乃论猪肉致病之由，非脉诊内容；肝“主冷泄，久滑赤白”亦属脏腑药治，与脉无关。故本条无脉象要素可录，主旨归入其他。", []], "26681": ["其他", "本段述鼹鼠产地、形类及肉之主病，如“主风热久积，血脉不行，结成疮疽”“杀蛔虫”等，皆属本草主治，未涉及诊脉。文中“血脉不行”指病机之血瘀，非脉象描述，不可误作涩、弦等脉。全段无脉名可识，故脉象要素为空，类别归其他。", []], "26682": ["其他", "本段为獭条，载其两种形类、入药取“取鱼祭天者”，并述肉性寒主骨蒸热劳、血脉不行、营卫虚满、女子经络不通等，肝温主传尸劳极、产劳。通篇论药性主治，未及脉诊；“血脉不行”“营卫虚满”是病机语，非脉象，故不取脉，类别属其他。", []], "26683": ["病机", "原文引《素问》鼓胀“心腹满，旦食则不能暮食”，注文虽言鸡矢利小便微寒，而段首标“脉上下行微弦”。微弦者，弦为肝木乘脾、气机壅滞之象，微则中阳不足，升降失司，故见心腹满而旦食不能暮食，正合鼓胀之病机，脉症相参以明其候。", ["微", "弦"]], "26684": ["其他", "本段述木瓜产地、宣城为佳、与榠楂之辨，及“大枝可作杖，策之云利筋脉”“根叶煮汤淋足胫，可以已蹶”等。所谓“利筋脉”乃言杖策之效，非脉象；全段为药物形态与功用记载，未涉诊脉，故脉象要素为空，类别归其他。", []], "26685": ["病机", "段首标“脉洪起一”，下文论大豆黄卷及生大豆修治不同而效异，如“煮汁甚凉，压丹石毒”“炒食则热”“作豉极冷”。洪脉主热盛气壅，与豆汁清凉解毒、紫汤破血去风相参，示热毒壅盛之病机，脉洪为热象之应，故列病机。", ["洪"]], "26686": ["其他", "本段为百乳草条，仅载产地、根色形叶、采时及“下乳，亦通顺血脉，调气甚佳”之功效。通篇无脉象描述，“通顺血脉”指药效调血，非脉诊所得，不可据以取涩、弦等脉。故脉象要素为空，类别归其他。", []], "26687": ["病机", "原文标“脉急痛”，药条言烈节“主肢节风冷，筋脉急痛”。急脉主筋脉拘挛、寒邪收引，风冷客于肢节，筋脉失养而挛急，故脉见急、症见痛，脉症相应。此段以药测证，明风冷伤筋之病机，故归病机类，脉取急字。", ["急"]], "26688": ["其他", "原文强调“脉候不真，则虚实莫辨、攻补妄施”，指出切脉不精则无法辨别虚实，导致误治伤人。虽未列具体脉象，但以“脉候不真”为说，说明脉诊在辨虚实、定攻补中的关键作用，属脉诊重要性的论述，非主病或病机专论。", []], "26689": ["其他", "此段为作者自序，言医药之书“能起人沉疴，益人神智”，虽“无关道脉”而“有助刚大之形躯”，并未涉及具体脉象或病机，仅泛论医药著作的价值，故无脉象要素可录。", []], "26690": ["其他", "原文述著书目的，针对“脉候欠审，用药乖方”之弊，提供简便方书以备缓急。虽提及“脉候欠审”，但非论具体脉象主病，而是强调脉诊审察不精的危害，属医书编纂宗旨的说明。", []], "26691": ["病机", "原文“多食咸，则脉凝泣（涩同）而变色”，以“脉凝泣”言过食咸味致血脉凝涩不畅，因咸入肾属水，水克心火，心合脉，故脉涩而色变。此段论五味偏伤五脏之病机，脉涩为血行凝滞之象，与“多食咸”相应。", ["涩"]], "26692": ["其他", "此段述黄芪甘温之性，生用固表、炙用补中，益元气、温三焦、壮脾胃，为疮痈圣药。全段论药性功用，未涉及脉象，故无脉象要素可录，主旨属本草药性论述。", []], "26693": ["病机", "原文以“脉散用之者”言人参之用，脉散为元气耗散之象，人参大补肺中元气，使“肺气旺，则四脏之气皆旺”，故脉散属气虚欲散之病机，用人参补气以固脱。此段论药性主治，脉散为应用指征之一。", ["散"]], "26694": ["病机", "原文以“脉虚、脉芤洪者”论治虚劳内伤，虚脉主不足，芤洪主虚劳内伤、阴血亏虚而阳浮。文中辨内伤与外感，谓“内伤则气口脉盛，多属不足”，气口脉盛而虚芤洪，为内伤虚损之象，故宜温补和养。", ["虚", "芤", "洪"]], "26695": ["其他", "此段述丹参性味功用，气平而降、味苦色赤入心与包络，破宿血、生新血、安生胎、调经脉，为女科要药。全段论药性主治，未涉及具体脉象，故无脉象要素可录。", []], "26696": ["主病", "原文未出脉名，列丹参主治冷热劳、骨节痛、风痹不随、肠鸣腹痛、崩带症瘕及血虚血瘀之候。其要在于“血病”二字：症有块可征、瘕则假物聚散无常，皆血行失和所致；手足缓散不随，亦由血不荣筋。故本段所主病机为血虚血瘀、脉络不和，兼见目赤、疝痛、疮疥肿毒等血分壅滞之候。", []], "26697": ["病机", "原文未出脉名，而借肾脉贯肝膈、入肺中、循喉咙、系舌本立论，指出肾虚则相火上炎，遂生喉痹咽痛、咳嗽吐血、潮热骨蒸。骨蒸传尸、阳毒发斑、懊𢙐烦渴、温疟洒洒，皆相火内炽、壮水不能制火之候；瘰疬结核、痈疽鼠瘘则火郁痰凝。故本段主肾虚火炎、水不制火之病机。", []], "26698": ["病机", "原文未出脉名，述苍术甘温辛烈，燥胃强脾、发汗除湿、升发胃中阳气，止吐泻、逐痰水、消肿满。许叔微治水饮澼囊，丹溪谓实脾土、燥脾湿为治痰之本，皆点明湿困脾土、痰水内停之机。故本段所主为脾虚湿盛、痰水不化，阳气不升而吐泻肿满由生。", []], "26699": ["主病", "原文未出脉名，列葳蕤治风淫湿毒、目痛眦烂、寒热痁疟、中风暴热不能动摇、头痛腰痛、茎寒自汗，总属“一切不足之证”。其药温润甘平，用代参、耆而不寒不燥，说明所主为阴液不足、风湿外袭、筋脉失养之候；头痛腰痛亦分虚实，挟虚挟风湿者正宜此润养。", []], "26700": ["误治", "原文标“脉数有实火者忌用”，五味子性温、酸咸为多，专收敛肺气而滋肾水，益气生津、涩精敛汗。脉数而属实火者，邪热正炽，若投酸收温涩之品，则闭门留寇，火郁不散。故本段以脉数辨实火为禁忌之据，示人敛涩之药不可误用于实热之证，属误治警戒。", ["数"]], "26701": ["病机", "原文出“脉绝短气、脉散”，以生脉散治之。心主脉、肺朝百脉，补肺清心则气充而脉复；脉绝短气正是气阴两伤、脉道不续之象，脉散则气耗不收。故本段所主为心肺气阴两虚、脉气欲绝之病机，兼客热虚劳、肺痿吐脓、血热妄行、经枯乳闭等症，皆由燥金受灼、津液不充所致。", ["绝", "短", "散"]], "26702": ["主病", "原文未出脉名，述旋覆花咸能软坚、苦辛下气行水、温通血脉，入肺与大肠，消痰结坚痞、唾如胶漆、噫气不除，兼治大肠水肿、去头目风。其机在痰结气滞、水饮不化，噫气属胸中气不畅；然走散冷利，虚者慎用，示痰实气壅者方为的对。", []], "26703": ["病机", "原文未出脉名，述夏枯草治瘿疬湿痹、目珠夜痛。楼全善以目系连目本，夜与寒皆属阴，夏枯气禀纯阳、补厥阴血脉，以阳和阴故效；白珠昼痛属阳、黑珠夜痛属阴，点苦寒反剧。故本段所主为厥阴血脉不足、阴寒凝滞之病机，瘿疬湿痹亦由血脉不通、痰湿结聚而致。", []], "26704": ["病机", "原文论风湿相搏致本经头痛、督脉脊强而厥、刚痉柔痉等，虽未出脉名，然风湿相搏、督脉为病，脉当见浮弦或沉紧。风邪外袭，湿阻经络，故头痛、脊强；刚痉无汗脉浮紧，柔痉有汗脉浮缓。血虚发痉者脉细涩。此段重在阐明风、湿、血虚致痉之病机，非专论脉。", []], "26705": ["主病", "原文述藁本辛温雄壮，为太阳经风药，主寒郁本经头痛连脑、督脉脊强而厥、妇人疝瘕阴寒肿痛、腹中急痛、胃风泄泻等。虽未言脉，然寒郁太阳，脉必浮紧；疝瘕急痛属寒湿，脉多沉弦或紧。此段以药测证，示寒湿客于太阳、督脉之病机，脉当与证相应。", []], "26706": ["病机", "原文载升麻治时气毒疠、头痛寒热、肺痿吐脓、下痢后重、久泄脱肛、崩中带下，能缓带脉之缩急。脉之缩急，主气滞寒凝、带脉拘急。气滞于中，升降失司，故后重、久泄；带脉缩急，则崩中带下。升麻升清降浊，缓其缩急，脉象当随证减。", ["缩", "急"]], "26707": ["主病", "原文述白芷辛散风、温除湿、芳香通窍，入手足阳明，治阳明头目昏痛、眉棱骨痛、牙痛、鼻渊、目痒泪出等。虽未出脉，然阳明风热或寒湿，脉多浮数或浮紧；头面诸疾，脉常应于寸部。此段以药测证，示阳明经风、湿、热邪为病之脉应。", []], "26708": ["主病", "原文论柴胡治伤寒邪热、痰热结实、虚劳肌热、呕吐心烦、诸疟寒热。虽未言脉，然邪在半表半里，脉多弦；痰热结实，脉滑数；虚劳肌热，脉细数或虚数。此段以药测证，示少阳枢机不利、痰热内结、劳热伤阴之病机与脉应。", []], "26709": ["病机", "原文述麻黄辛温微苦，入足太阳，兼走手少阴、阳明，为肺家专药，能发汗解肌，去营中寒邪、卫中风热，调血脉，通九窍，开毛孔。虽未出脉，然寒邪束表，脉必浮紧；风热犯卫，脉多浮数。此段示麻黄发表祛邪之性，脉当随邪解而和。", []], "26710": ["兼症", "原文载麻黄治中风伤寒、头痛温疟、咳逆上气、痰哮气喘、斑毒、风疹痹、水肿风肿，并明言“脉沉迟者加人参”。沉迟之脉，主里虚寒，正气不足。麻黄虽能发表，然沉迟脉见，不可单恃攻邪，故加人参以扶正。此段示脉症相参、攻补兼施之旨。", ["沉", "迟"]], "26711": ["病机", "原文述荆芥气温散，助脾消食，通利血脉，治吐衄肠风、崩中血痢、产风血运、瘰疬疮肿，清热散瘀，破结解毒，为风病、血病、疮家圣药。虽未出脉，然风入血分，脉多浮弦或细涩；血热妄行，脉数。此段示荆芥入风木藏血之地，散血中风热之病机。", []], "26712": ["病机", "原文述药物辛温入肝经气分，能益气强阴、通血脉、强筋力、疏痰气，虽未直接言脉，但“通血脉”提示脉道涩滞可因气滞痰阻所致，故其病机为肝经气分不足兼痰气阻滞，血脉不畅，治当益气疏痰以通脉。", []], "26713": ["病机", "原文引“痹在于骨则体重，在脉则血涩”，明确指出风寒湿三气杂至合而为痹，邪客于脉则血行涩滞，故脉见涩象。此涩脉主痹证，因寒湿凝滞血脉，血不荣筋则通身挛急，甚则虚劳骨蒸，皆由痹阻日久、气血不畅所致。", ["涩"]], "26714": ["病机", "原文述当归甘温和血、辛温散内、苦温助心散寒，为血中之气药，入心肝脾。虽未言脉，但“诸血属心，凡通脉者，必先补心”提示血脉不畅可因心血不足、寒凝气滞，故其病机为血虚寒凝、心脉不畅，治当温补心血以通脉。", []], "26715": ["兼症", "原文列当归所治虚劳寒热、咳逆上气、风痉无汗、痿痹症瘕等症，并释“血和则气降”“脱血无以养筋”致痉，说明诸症皆由血虚寒凝、气血失和所致。虽未直接言脉，但脉象当见虚细或弦紧，主血虚寒凝、筋脉失养之病机。", []], "26716": ["病机", "原文述川芎辛温升浮，为血中气药，能助清阳而开诸郁、润肝燥而补肝虚、搜风散瘀。虽未言脉，但“气升则郁自降”提示气郁血滞可致脉道不畅，其病机为肝郁血滞、清阳不升，治当辛散升浮以行气开郁、活血通脉。", []], "26717": ["病机", "原文论痈疽疮疡由阴阳相滞而成，寒湿搏之则血行迟为不及，火热搏之则血行速为太过，气郁血郁致生恶毒。虽未言脉，但脉象当随寒热见迟数涩滑，其病机为气血壅滞、阴阳不相顺接，治当芎归和血行气以通阴阳。", []], "26718": ["病机", "原文述白芍苦酸微寒，能泻肝火、安脾肺、固腠理、和血脉、收阴气、敛逆气。虽未言脉，但“酸主收敛”“敛阴生津”提示其病机为肝火偏旺、阴气不敛，致血脉不和、腠理不固，治当酸敛以和血脉、收阴气。", []], "26719": ["兼症", "原文列白芍所治泻痢后重、脾虚腹痛、心痞胁痛、肺胀喘噫等症，并释“腹痛因营气不从，逆于肉里”“痛为肝木克脾土”，说明诸症由营气逆滞、肝木克土所致。虽未言脉，但脉当见弦细，主肝郁脾虚、营气不和之病机。", []], "26720": ["治法", "尺脉弱为肾阳不足、火衰之象，故于六味丸中加桂、附以“益火之原，以消阴翳”；尺脉旺则阴火偏亢，加知、柏“壮水之主，以制阳光”。原文以尺脉强弱定加减，体现脉象指导温补或清滋的治法选择，非泛论病机。", ["弱"]], "26721": ["病机", "原文未出脉名，以丹皮“泻血中伏火”立论，指出伏火即阴火、相火，血热则枯、凉则生，故能和血凉血生血；积瘀不去则新血不生，故破积血、通经脉。全段从药性推阐血分伏火与瘀热互结之病机，非凭脉断证。", []], "26722": ["病机", "原文未出脉名，以“血属阴本静，因相火所逼，故越出上窍”释吐衄，又谓中风、惊痫瘛疭“皆阴虚血热，风火相搏，痰随火涌所致”。全段紧扣阴虚血热、相火妄动、风火痰涌之病机，说明丹皮凉血散瘀、除烦退骨蒸之所以然。", []], "26723": ["病机", "原文未出脉名，以药性苦温补肾、辛温补肝，能宣通血脉而理筋骨，主伤中、补不足、暖子宫、缩小便、破瘀血。所论重在肝肾虚寒兼瘀之病机，故以温补宣通为治，非据脉象立论，亦未涉及具体症候与脉相应。", []], "26724": ["兼症", "原文未出脉名，列血风血晕、血痛血淋、胎痛产难、崩中带下等经产诸症，并释带脉横于腰间、赤属血白属气，气虚补中益气兼升降，血虚养血滋阴兼调气。末言辛散之药瞳子散大者忌服，属兼症与用药禁忌，非脉诊主病。", []], "26725": ["病机", "原文未出脉名，言蒲黄甘平为厥阴血分药，生用性滑，行血消瘀、通经脉、利小便，祛心腹膀胱寒热，同五灵脂治心腹血气痛名失笑散。所主在瘀血阻滞、寒热错杂之病机，以药测证，未及脉象与症候相应。", []], "26726": ["兼症", "原文未出脉名，述郁金治吐衄尿血、妇人经脉逆行，谓经不下行、上为吐衄；又治血气诸痛、产后败血攻心、癫狂失心，释癫属不足、狂属有余，多因惊忧瘀血塞心窍。全段以瘀血阻窍、血热上逆为病机，兼列诸症及白金丸方。", []], "26727": ["主病", "原文引《机要》论痢：“脉弦宜去风，风邪内结宜汗”，以弦脉主风邪内结，故治痢当先解表去风；又列后重宜下、腹痛宜和、身重宜除湿、身冷自汗宜温、脓血稠黏宜重剂竭之。弦脉在此标示风邪为痢疾兼夹之因，与表证、下痢诸候相应。", ["弦"]], "26728": ["其他", "本段为药性主治记载，未涉脉象。原文列骨蒸劳热、五心烦热、三消、五痔、温疟泻痢、女人胎蒸、小儿惊疳等症，皆属湿热火郁、阴亏内蒸之候；末言性味功用同黄连，提示其清泄湿热、泻火解毒之力，故所主诸症多从热郁湿蒸立论，非据脉断病。", []], "26729": ["病机", "原文论十二种水、大腹肿满，引王好古“脉有尺寸之殊，浮沉之别”，以浮沉分水病表里上下。水气浸淫由脾不散精、肺不通调、肾失司关，致积水无所底止；脉浮主病在表分皮肤，沉主病在里属脏腑筋骨，故不可轻泻，当辨何经何脏而治。", ["浮", "沉"]], "26730": ["病机", "本段述甘淡轻虚之性，上通心包降心火、清肺热，化津液而通水道，下通大小肠膀胱，导湿热由小便出。所论重在肺为水源、心火降则肺热清、津液化则水道通之机转，并及木通兼通大便、利九窍血脉关节，全从药性气机升降立说，未及脉象。", []], "26731": ["主病", "原文以脉沉细辨三阴伤寒、中寒夹阴，虽身大热而脉沉细，主阴寒内盛、阳气衰微，故急用附子；又引东垣阴盛格阳案，面赤目赤烦渴而脉七八至、按之则散，数而散为虚阳外越、按之无根，主假热真寒。脉伏则属阳盛格阴之热厥，误投温药立毙，须承气、白虎。", ["沉", "细", "数", "散"]], "26732": ["其他", "本段载白附子辛甘有毒、大热纯阳，为阳明经药，引药势上行治面上百病，去头面游风、消斑疵，并补肝虚、祛风痰、治心痛血痹、诸风冷气、中风失音、阴下湿痒。所主皆风痰冷气上攻及阳明头面之疾，全凭药性性味归经推演，原文未出脉象。", []], "26733": ["其他", "本段述菟丝子甘辛和平，凝正阳之气入足三阴，强阴益精、温而不燥、不助相火，治五劳七伤、精寒淋沥、口苦燥渴，祛风明目、补卫气、助筋脉。所主为肝肾虚损、阴精不足兼内热之候，末附过服作疽之戒，说明补益亦须有节，原文未及脉象。", []], "26734": ["其他", "本段记药治脾虚疟疾、感寒腹痛、吐逆反胃，并注肺胃火盛及气虚者禁用；又治白睛翳膜、太阳经目眦红筋，以白睛属肺能散肺滞、太阳脉起目眦为据。所论重在脾肺虚寒与肺滞目疾，凭脏腑经络归经用药，原文未出脉象，故脉象要素为空。", []], "26735": ["病机", "本段论香附性平气香，辛散苦降甘和，为血中气药，通行十二经八脉气分，主一切气。原文引经列怒则气上、恐则气下、喜则气缓、悲则气消、惊则气乱、思则气结、劳则气耗七情之气，及寒则气收、热则气泄为九气，说明气机失常则病，故以香附为君随证升降消补，利三焦解六郁止诸痛。", []], "26736": ["主病", "原文未出脉名，以木香治九种心痛、呕逆反胃、霍乱泻痢后重、癃闭、痰壅气结、痃癖症块、冲脉为病气逆里急等，皆属气机壅滞、升降失司之病机。木香辛升通壅导气，故主气痛、气结、后重诸症；又言气逆则胎不安，点明胎动亦由气逆，过服则损真气，示辛散不可过用。", []], "26737": ["主病", "原文未出脉名，述疗小肠冷气、𤻊疝阴肿、干湿脚气。疝分七种而归于肝经，因厥阴肝脉络阴器，多由寒湿所致，亦有挟虚者，故当于温散药中加参、术。此段以寒湿客于肝经、气机凝滞为病机，与阴肿、脚气相应，非肾经本病，明辨病位在肝。", []], "26738": ["病机", "原文未出脉名，言药性甘苦而平，行而不住，能走血分、通血脉，为阳明、冲、任之药。其主旨不在脉，而在阐明血分药性之行散通利，与阳明多气多血、冲任主血海之生理相应，故凡血脉瘀滞、营卫不通之病机，可借此通血脉以调之。", []], "26739": ["病机", "原文未出脉名，述药性甘寒淡滑，润燥利窍，通营卫，滋气脉，行津液，利二便，消水肿，通关格，下乳滑胎。所主病机为津液枯燥、窍道不利、营卫壅滞，故见水肿、关格、二便不利、乳汁不通等症，皆以滑利通窍、行津润燥为治，非脉象所主。", []], "26740": ["病机", "原文未出脉名，言药辛甘大热，气厚纯阳，入肝肾血分，补命门相火不足，益阳消阴。所主病机为命门真火衰微、痼冷沉寒内结，故见腹中冷痛、咳逆结气、表虚自汗等；火衰则无以蒸糟粕化精微，脾胃衰败气尽而亡，强调真阳为生化之本，桂能引火归元。", []], "26741": ["病机", "原文未出脉名，述药辛甘而温，气薄升浮，入太阴肺、太阳膀胱经，温经通脉，发汗解肌，能利肺气。所主病机为风寒外束、肺气不宣、经脉凝滞，故以辛甘发散为阳，取温经通脉、发汗解肌之功，使表邪从汗而解，肺气得以宣利。", []], "26742": ["主病", "原文标尺脉弱者禁用，述疗下焦虚、骨蒸劳热、诸痿瘫痪、目赤耳鸣、消渴便闭、黄疸水肿。尺脉弱示下焦肾虚，阴虚生内热则骨蒸，热伤血、湿伤筋则痿躄拘弛；王善夫便闭腹坚案，东垣断为膏粱积热损伤肾水、膀胱干涸，即无阴则阳无以化，故尺弱当慎苦寒。", ["弱"]], "26743": ["主病", "原文未出脉名，述药辛苦微寒、轻浮升散，入膀胱、胃、肝经，搜风凉血，通利九窍。所主病机为阳明风热上攻、太阳风邪循经上扰，故见湿痹拘挛、头痛脑鸣、目赤齿痛、头面风虚之证；齿龈分属手足阳明，风热攻龈则动摇肿痛，故能明目固齿。", []], "26744": ["病机", "原文未出脉名，以“肺主鼻”“胆移热于脑”“风寒客于脑”立论，说明鼻渊鼻塞由胆热上移、风寒外客、清阳不升所致，症见浊涕如泉、头痛面䵟、目眩齿痛，属九窍风热之病；并指出气虚火盛者忌服，提示病机有虚实两端。", []], "26745": ["病机", "原文以“脉伏”辨中气、中风：厥逆痰壅口噤而脉伏，身温为中风、身冷为中气，说明气机逆乱、痰闭清窍则脉道潜伏不显。治以顺气散风，故云“气顺则风散”，强调暴怒暴喜、忧愁不已致气多厥逆，不可概作中风治。", ["伏"]], "26746": ["主病", "原文以“五脏筋脉缓纵”释“五缓虚羸”，脉缓纵即筋脉弛缓无力，主五脏虚羸、阴痿囊湿、女子阴痒、小儿脚弱等症。缓纵由虚而来，故用五加治五劳，酿酒尤良；并引风病饮酒生痰火之说，示虚证宜补不宜辛散。", ["缓"]], "26747": ["病机", "原文未出脉名，以“甘滑下降”“滑可去著”言药性，说明榆白皮入大、小肠、膀胱，行经脉、利诸窍、渗湿热，下有形留著之物，故治五淋肿满、喘咳不眠、疥癣秃疮、妒乳赤肿；滑胎产、下死胎亦取其滑利下行之性。", []], "26748": ["病机", "原文未出脉名，言药“甘而微寒，入肝经气血分，润肝燥”，说明目中赤脉、青盲肤翳、赤肿眵泪及小儿疳气攻眼，皆由肝燥血分失润所致；以润肝之品治之，体现肝开窍于目、治目先润肝燥的病机思路。", []], "26749": ["治法", "原文未出脉名，述皂角末吹鼻取嚏以辨肺气绝否：有嚏者生，无嚏者肺气已绝则死；并以稀涎散吐痰、探喉令微吐稀涎，说明中风口噤、胸痹喉痹由痰涎壅塞所致，故取除湿去垢、消痰破坚之法，年老气虚者忌用。", []], "26750": ["病机", "原文未出脉名，引经“脉风成为疠”，言风寒客于脉而不去、营气热附则成疠，说明皂角刺辛温锋锐，能直达患处溃散痈疽，治痈毒妒乳、风厉恶疮、胎衣不下；并戒痈疽已溃及孕妇禁用，示其攻散之性有伤正之弊。", []], "26751": ["病机", "原文未出脉名，以“冲脉为病，气逆里急”立论，说明厥阴头痛、阴毒腹痛、呕逆吞酸、痞满噎膈、食积泻痢、血痹阴疝、脚气水肿等，皆由浊阴不降、厥气上逆所致；吴茱萸性热而能引热下行，故取降逆下气以复冲脉之常。", []], "26752": ["其他", "本段述冰片辛温香窜，善走能散，先入肺传心脾而透骨通窍散郁火，主治惊痫痰迷、目赤肤翳、耳聋鼻息、喉痹舌出、骨痛齿痛、痘陷产难等。东垣谓风病在骨髓者宜之，在血脉肌肉反引风入骨；王节斋辨世人误以为寒，实为辛热发散火郁，从治之法。全段论药性功用与禁忌，未及脉象，故脉象要素为空。", []], "26753": ["病机", "原文以脉沉而滑论巴豆所主。沉为病在里，滑为痰涎壅盛、积滞内结，故其辛热大毒可升可降，能开窍宣滞、去脏腑沉寒，破痰癖血瘕、气痞食积、生冷硬物所伤，治大腹水肿、泻痢惊痫、口㖞耳聋、牙痛喉痹。脉沉滑正合沉寒痼冷与痰积内实之机，峻用劫病，微用和中。", ["沉", "滑"]], "26754": ["其他", "本段论桃仁主治热入血室、血燥血痞、损伤积血、血痢经闭、咳逆上气、皮肤血热燥痒、蓄血发热如狂，引仲景桃仁承气汤、抵当汤以水蛭虻虫通肝经聚血。末言血不足者禁用，行血连皮尖生用，润燥去皮尖炒用。全段言血分病机与用药法度，未载脉象，故脉象要素为空。", []], "26755": ["病机", "原文以脉浮属气、脉沉属血分气血论治。浮主阳气在表，故昼便难属阳气，用杏仁、陈皮降气行痰、通大肠气秘；沉主阴血在里，故夜便难属阴血，用桃仁、陈皮疗狂治血。杏仁泻肺解肌、除风散寒、降气行痰，治时行头痛、上焦风燥、咳逆上气、烦热喘促；肺虚而咳者禁用，正合浮沉分气血之旨。", ["浮", "沉"]], "26756": ["平脉", "原文以脉息和平立论，言梨甘微酸寒，润肺凉心、消痰降火、止渴解酒、利大小肠，治伤寒发热、热嗽痰喘、中风失音，切片贴汤火伤。脉息和平示气血未伤、脏气安和，故可食梨清润；若脾虚泄泻及乳妇血虚人则忌之。生者清六腑之热，熟者滋五脏之阴，实火宜生，虚火宜熟，皆以脉息和平为用药之准。", ["和平"]], "26757": ["病机", "本段论枳椇甘平，止渴除烦、润五脏、解酒毒。引杨颖臣病消渴，张肱诊其脾脉极热、肾脉不衰，断为酒果过度、积热在脾，以麝香当门子酒濡作丸，枳椇子煎汤吞之而愈。又赵以得治酒毒房劳病热，知气血虚不禁葛根之散，必得枳椇。全段以脾热肾不衰论消渴病机，未出具体脉名，故脉象要素为空。", []], "26758": ["病机", "本段论胡桃味甘气热，皮涩肉润，皮汁青黑属水入肾，通命门、利三焦、温肺润肠、补气养血。佐补骨脂，一木一火，大补下焦，有木火相生之妙。引时珍言三焦为元气之别使，命门为三焦之本原，一体一用。全段阐命门三焦与肺肾相关之病机及胡桃补益之功，未及脉象，故脉象要素为空。", []], "26759": ["病机", "本段论莲子甘温而涩，为脾之果，脾者黄宫，故能交水火而媾心肾，安靖上下君相火邪。益十二经脉血气，涩精气，厚肠胃，除寒热，治脾泄久痢、白浊梦遗、女人崩带及诸血病；大便燥者勿服。全段以甘温涩之性阐心肾不交、脾虚失固之病机，未载脉象，故脉象要素为空。", []], "26760": ["其他", "本段论葱白之性用，非论脉。原文言其“生辛散，熟甘温”，外实中空，为肺之菜，肺主皮毛，其合阳明，故能发汗解肌、通上下阳气，并引仲景白通汤、通脉四逆汤加之“以通脉回阳”。所主在肺与阳明，气通则血活，故治吐血衄血、便血痢血及折伤血出、乳痈风痹、通乳安胎，皆从辛散温通、宣通阳气立论。", []], "26761": ["其他", "此段仅列“燥，回阳，宣，通脉”六字，为药性提纲，非脉象描述。其意承前条葱白而言，辛温之品能燥、能宣、能回阳，故可通脉。所谓“通脉”，指阳气复则脉道通利，非以脉形定病。全段无脉象要素可录，主旨属药性功用，故归其他。", []], "26762": ["其他", "本段论干姜生用炮用之异：生用辛温逐寒发表，炮则辛苦大热，除胃冷而守中，去脏腑沉寒痼冷。原文“能回脉绝无阳”，引仲景四逆、白通、姜附汤皆用之，是借辛热回阳以通脉，非据脉形辨证。又言吐衄下血“有阴无阳者宜之”，及血虚发热、产后大热属阴虚内热者宜之，皆从药性归经立论。", []], "26763": ["其他", "本段述某药甘平凉血解毒、除风化痰、通经络、行血脉之效。原文以“老者筋络贯穿，象人经络，故可借其气以引之”取类比象，说明其能通经络、行血脉，故消浮肿、稀痘疮，治肠风崩漏、疝痔痈疽，并滑肠下乳。全段为药性功用，未涉脉象，故脉象要素为空，主旨归其他。", []], "26764": ["其他", "本段论石膏体重泻火、轻可解肌，为足阳明大寒之药，色白入肺兼入三焦。原文“寒能清热降火，辛能发汗解肌，甘能缓脾益气”，故治伤寒郁结无汗、阳明头痛、肌肉壮热、大渴引饮，又为发斑发疹要品。所论皆药性归经与主治，未及脉象，故脉象要素为空，主旨属其他。", []], "26765": ["其他", "本段辨井华水、无根水、新汲水之别名与用法，言其解热闷烦渴，煎补阴之药宜之，并论水源有地脉山泉、江湖渗来、城市沟渠污秽之别，入药当择。全段为水类药用及择水之法，未涉脉象与病机判断，故脉象要素为空，主旨归其他。", []], "26766": ["治法", "本段论阴阳水治霍乱吐泻。原文“阴阳不和而交争，故上吐下泻”，饮此“分其阴阳，使和平也”。又强调霍乱有寒热二证，“仓卒患此，脉候未审，慎勿轻投偏热、寒之剂”，并斥服姜汤立毙之误，唯饮阴阳水最稳；干霍乱则用盐熬热、童便调饮。全段以脉候未审为戒，主在治法择用。", []], "26767": ["其他", "本段论五灵脂甘温纯阴，入肝经血分，通利血脉、散血和血，生用通血闭、炒用止经多，治血痹血积、肠风崩中一切血病。原文引李仲南谓其治崩中“非正治之药，乃去风之剂”，因冲任经虚被风袭伤营血而崩，与荆芥、防风治崩义同。全段为药性归经与方义辨析，未涉脉象。", []], "26768": ["治法", "原文以胆汁苦寒滑润立法，苦入心通脉、寒补肝和阴，故治厥逆无脉之证。成无已指出阳气大虚、阴气内胜，纯用阳药恐阴气格拒，加猪胆汁苦寒引阳入阴，即热因寒用。此段论治法而非脉诊，脉象仅作辨证背景，说明无脉属阳虚阴盛、格拒不通之机。", []], "26769": ["其他", "原文引《别录》谓猪肉闭血脉、弱筋骨、虚人肌，久食令人少子、发宿病。所谓闭血脉，指猪肉滋腻碍脾，气血运行不畅，非指某一脉象。全段论猪肉宜忌及配伍禁忌，属食忌内容，未涉及具体脉诊，故脉象要素为空。", []], "26770": ["治法", "原文论倒仓法用牛肉液补中，借补为泻，使肉液充满流行、无处不到，如洪水泛涨，一切凝滞顺流而去。此法治积聚久留肠胃曲折之处，非铢两丸散所能及。全段言治法机理，未及脉象，故脉象要素为空，主旨属治法范畴。", []], "26771": ["病机", "原文论牛黄甘凉，清心解热、利痰凉惊，治中风入脏、惊痫口噤。其病机为心热生火、肝热生风，风火相搏，胶痰上壅，遂致中风不语。东垣分中脏、中腑、中经络轻重，中脏宜牛黄，中腑及血脉者用之反引风入骨。全段以病机与用药宜忌为主，未出脉象。", []], "26772": ["主病", "原文明确“惟脉沉细、相火衰者宜之”，沉细为阳气不足、相火衰微之象，故鹿茸甘温纯阳，生精补髓、养血助阳，主治腰肾虚冷、四肢酸痛、头眩眼黑、崩带遗精一切虚损劳伤。脉沉细与虚冷劳伤相应，说明此脉主肾阳亏虚、精血不足之病机。", ["沉", "细"]], "26773": ["病机", "原文论鹿角咸温，生用散热行血、消肿辟邪，治梦与鬼交，能逐阴中邪气恶血；炼霜熬膏则专于滋补。时珍谓鹿纯阳多寿，能通督脉，故用鹿茸与胶霜补玉堂门下穴。全段阐发药性归经与病机，未涉及脉象，故脉象要素为空。", []], "26774": ["病机", "原文论鳝尾血疗口眼㖞斜，左㖞涂右、右㖞涂左。时珍谓鳝善穿穴，与蛇同性，能走经络、疗风邪及诸窍之病；风中血脉，用血主之，从其类也。此段以风邪中血脉为病机，取鳝血走窜通络以治，未言脉象，故脉象要素为空。", []], "26775": ["其他", "原文仅“宣，通血脉”四字，言某药或某法之性能在于宣通血脉，属药性主治范畴，未涉及具体脉象与病机推论。因原文过简，只能判定其主旨为通血脉之宣发作用，脉象要素无从提取，故为空数组。", []], "26776": ["其他", "本段为乌鲗骨（海螵蛸）药性主治，非脉诊内容。原文言其“咸走血、温和血，入肝、肾血分”，故通血脉、祛寒湿，治血枯、血瘕、血崩血闭及阴蚀肿痛，皆取咸温入血分、燥脓收水之功。所主为厥阴、少阴经病，与脉象无关，故脉象要素为空。", []], "26777": ["其他", "本段述龟甲药性，非论脉。原文谓“甘平至阴，属金与水，补心益肾，滋阴资智”，故治阴血不足、劳热骨蒸、腰脚酸痛、久泻久痢、久嗽痎疟、症瘕崩漏、五痔产难等阴虚血弱之症。其“通任脉”之说，是取龟首藏腹之象以补精血养阴，非脉象主病，故脉象要素为空。", []], "26778": ["其他", "本段论紫河车（胞衣）药性，非脉诊。原文称其“本人之血气所生，故能大补气血”，治一切虚劳损极、恍惚失志癫痫。所举五损六极，皆气血虚衰之候，取胞衣大补气血以复虚损。全段未涉脉象，故脉象要素为空，主旨归为其他。", []], "26779": ["其他", "本段述《本经》三品分类及五运六气之理，非论脉。上品养命延年，中品通调血气、却邪治病，下品除寒热邪气、破积聚症瘕。原文以“六气”“五行”辨草木金石之性，是本草学总纲，与脉象主病无涉，故脉象要素为空。", []], "26780": ["病机", "本段论黄耆主治，虽标“脉调和”，实以“脉”指经脉而非脉象。原文谓黄耆“助三焦出气，以温肌肉”，故治肌肉之痈、经脉之疽及久败疮；又补气助阳，阳气化血排脓而止痛。大风癞疾、五痔、鼠瘘皆邪在经脉而证见于肌，取黄耆补气通脉、温肌肉以托邪。脉象要素仅取“和”字，示经脉调和之旨。", ["和"]], "26781": ["病机", "本段论白术药性，非脉诊。原文称其“气味甘温，质多脂液，乃调和脾土之药”，故治风寒湿痹，因土气运行则肌肉之气外通皮肤、内通经脉；又补脾以治死肌、痉、疸，止汗除热消食，皆取补脾土、胜湿转运之功。全段未及脉象，故脉象要素为空，主旨归为病机。", []], "26782": ["病机", "本段论石斛药性，非脉诊。原文谓其“禀水石之专精而补肾”“夺中土之气化而补脾”，治伤中则中气调和而邪气自下，除痹则补五脏虚劳羸瘦，故曰强阴益精。久服土气运行、水精四布而厚肠胃。全段以脾肾气化立论，未涉脉象，故脉象要素为空。", []], "26783": ["病机", "本段阐发《本经》上品“除痹”之义，非脉诊。原文指出“不曰风寒湿，而但曰痹者，乃五脏外合之痹”，以皮脉肉筋骨分属五脏，故除痹即治五脏虚劳羸瘦，是攻邪中有补益之妙；治伤中即所以下气，是补益中有攻邪之神理。全段未及脉象，故脉象要素为空。", []], "26784": ["病机", "原文论地黄主治伤中、血痹，谓其\"横纹似络脉，通周身之经络\"，故能逐血痹。血痹犹脉痹，乃络脉不通之病机；地黄味甘质润补中焦精汁，得少阴寒水之精填骨髓、太阴中土之精长肌肉，作汤则上行外达除寒热积聚。全段以药性推病机，非论脉象，故脉象要素为空。", []], "26785": ["病机", "原文列麦门冬主治\"心腹结气，伤中，伤饱，胃络脉绝，羸瘦短气\"。胃络脉绝即胃之大络不通于脉，络脉失养则羸瘦；中气内虚、肾不纳气则短气。此段以药测证，示络脉不通、中虚气弱之病机，未及脉象描述，故脉象要素为空。", []], "26786": ["病机", "原文释麦门冬命名与形质，谓其\"一本横生，根颗连络\"，有十二至十五枚，合手足三阴三阳之络加任督及脾之大络之数，故\"用麦冬以通络脉\"。全段借物性说明络脉贯通之理，纠正去心之误，属药性病机推演，未涉脉象，故脉象要素为空。", []], "26787": ["病机", "原文以\"经脉不和，中气内虚\"释伤中，以\"胃气壅滞\"释伤饱，以\"胃络不通于脉\"释胃络脉绝。脉不和即络脉失于通贯、中气内虚之象；胃虚则羸瘦，肾虚则短气。麦冬颗分心贯、横生连而不断，正合通络助胃补肾之用，故治上述诸候。", ["不和"]], "26788": ["病机", "原文论枸杞根苗主治五内邪气、热中、消渴，谓\"五脏正气不足，邪气内生\"而为热中消渴；又主周痹风湿，引岐伯\"周痹者，在于血脉之中，随脉以上下\"，示邪在血脉、君火之神不能出于脉中之病机。全段以药性推证，未及脉象，故脉象要素为空。", []], "26789": ["病机", "原文引黄帝问\"诊得心脉而急，此为何病\"，岐伯答\"病名心疝，少腹当有形\"。心脉急者，心气收引拘急，故少腹有形而痛，即心腹疝气之病机；又腹痛属脾病，益气属肺虚，躄属肝筋虚，五岁不能行属肾骨虚，五加皮色备五行，能兼益五脏而治之。", ["急"]], "26790": ["病机", "原文论蛇床子苦辛温热，得少阴君火之气，主治男子阴痿湿痒、妇人阴中肿痛，乃\"禀火气而下济其阴寒\"；除痹利关节，乃火气外通经脉。又谓心气虚而寒邪盛则癫痫，心气虚而热邪盛则恶疮，蛇床助心气故治之。全段以药性推病机，未涉脉象，故脉象要素为空。", []], "26791": ["病机", "原文论细辛禀少阴水阴上交太阳，水气行于皮毛内合于肺，循行失职则咳逆上气；太阳脉从巅络脑，失职则头痛脑动；少阴之气不合太阳则百节拘挛，风湿相侵伤肌腠而为死肌。全段以经络气化推病机，说明细辛通彻上下表里之用，未及脉象，故脉象要素为空。", []], "26792": ["其他", "此段为药物性味功用记载，非脉诊内容。原文述其'气味辛平，无毒'，主'宽中行气，消饮食，化痰涎'，治噎膈反胃、心腹痛，'通十二经关窍脉络'。所主病机为气滞痰阻、中焦不运，故以行气化痰、通络宽中为治，与脉象无涉，故脉象要素为空。", []], "26793": ["病机", "此段以橘皮形色论药性归经，非论脉。原文谓橘皮'筋膜似络脉，皮形若肌肉'，能'达胃络之气，出于肌腠'，故治'胸中瘕热逆气'及'利水谷'。其病机为浊气留聚胃上郛郭、假气成形而为瘕热逆气，橘皮辛开苦降，通脾络以散精、下肺气以通神，属药性病机分析，无脉象可录。", []], "26794": ["其他", "此段为作者按语，辨橘皮去白之误，非脉诊。原文引《经》'五脏六腑皆令人咳，非独肺也'，列肝气上逆、胃气壅滞、肾气奔迫、心火上炎、皮毛闭拒、脾肺不和诸咳，强调橘皮'从络脉而外达于肌肉毛孔'，去白则但辛行皮毛，虚劳咳嗽不宜。全段论药性与咳嗽病机，未涉脉象。", []], "26795": ["病机", "此段论辛夷禀阳明土金之气化，非脉诊。原文谓'阳明者土也，五脏之所归'，故治五脏不和之寒热；'金能制风'，故治风淫头脑之痛；气有余则面生光。其病机为阳明土金之气失调，风邪上淫头脑，故以辛夷宣通阳明、制风下气，久服则土气和平、金水相生而明目轻身，无脉象可录。", []], "26796": ["病机", "原文点明'经脉虚而寒邪侵入'，脉虚为经脉不足之象，虚而受寒，故成伤寒外因之证。续断气味苦温，禀少阴阳明火土之气，能补经脉不足、续折跌筋骨，兼治金疮痈疡、妇人乳难，皆围绕'经脉虚'这一核心病机。脉虚主里虚不足，与寒邪外侵相合，提示虚实夹杂、经脉三因之证。", ["虚"]], "26797": ["病机", "此段为桑寄生主治记载，非脉诊。原文主'伤中，五劳六极，羸瘦崩中，绝脉，补虚，益气'。'绝脉'指脉络不通或脉气衰绝，病机为劳极损伤、气血亏虚、脉络失续，故以甘寒之品补虚益气、续绝脉。所论为药物主治与虚损病机，未出具体脉象，脉象要素从缺。", []], "26798": ["病机", "此段释桑白皮主治，非脉诊。原文谓桑'得阳明金精之气'，主'伤中，续经脉'；列五劳、六极、羸瘦、崩中，并释'脉绝者，脉络不通'。病机为劳极损伤、气血肌肉亏耗、脉络不通，桑皮禀土金生长之气最盛，故能补续经脉。全段以药性推病机，未载脉象。", []], "26799": ["病机", "此段论松脂药性，非脉诊。原文谓松脂'禀木质而有火土金水之用'，得火气故治肌肉之痈、经脉之疽及阴寒恶疮；裕金气故治头疡白秃、疥瘙风气；备土气故安五脏。病机为火气不足、金气不裕、土气不备所致痈疽疮疡与五脏不安，属药性归经分析，无脉象可录。", []], "26800": ["病机", "原文以槐实苦寒、备五运之全精立论，逐脏说明邪气热之病机：肺气不能四布水精则涎唾上涌，肝血不能渗灌经脉则经脉绝伤，心火内盛则火疮，脾土不和则乳瘕，肾气内逆则子脏急痛。全段无脉象描述，所论为药性归经与五脏邪热病机，非脉诊内容。", []], "26801": ["病机", "原文述药气味苦寒、无毒，主治一切风化涎痰，清肝脏风，筋脉抽掣及急风口噤。其病机为肝风内动、风痰上扰，致筋脉失养而抽掣、口噤不开。全段为药性主治之论，未涉及脉象，故脉象要素为空。", []], "26802": ["病机", "原文以漆汁日曝反润、阴湿易干比喻胃府津液奉心化赤为血、入肾凝结为精，论干漆辛温禀阳明金精，上奉心资经脉、下交肾凝精髓，故治绝伤、补中、续筋骨、填髓脑、安五脏。末言驰纵曰缓、拘掣曰急，五缓六急乃风寒湿之痹，属痹证病机，无脉象。", []], "26803": ["病机", "原文论黄连苦寒禀少阴水阴之精，主治热气，因水滋火、阴济阳。火热上炎则目痛眦伤泣出；热淫于内薄为肠澼，乃热伤阴分；风寒暑湿伤经脉不能外达，下行肠胃则腹痛下痢；心火协相火交炽则妇人阴中肿痛。全段阐发药性所对病机，未及脉象。", []], "26804": ["病机", "原文以香蒲禀水土专精、调和气血立论：通调水道则心腹膀胱寒热从小便出而气机调和，生肝木则止新血、消瘀血而血脉调和。文中'脉调和矣'指血脉调和之结果，非具体脉象要素，故仅取'和平'以应调和之义，主旨为药性调气血之病机。", ["和平"]], "26805": ["妇人", "李时珍论茺蔚子为治妇女经脉不调、胎产及一切血气诸病之妙品。根茎花叶实并皆入药：治手足厥阴血分风热、明目益精、调女人经脉则单用子为良；治肿毒疮疡、消水行血、妇人胎产诸病则宜并用。因根茎花叶专于行，子则行中有补。全段属妇人用药之论，无脉象。", []], "26806": ["病机", "原文论石钟乳为石之津液融结，甘温滋中焦之汁上输于肺，故治咳逆上气；中焦取汁奉心化赤为血故明目；流溢于中为精故益精；精气盛则五脏和，血气盛则百节和，津液濡空窍则九窍利，滋经脉则乳汁下。全段阐发甘温滋液、资血气之病机，未涉脉象。", []], "26807": ["病机", "原文述药气味甘酸寒、无毒，主治青盲、耳聋，明目，利九窍，通血脉，养精神，益肝气，久服轻身延年。其病机为肝气不足、血脉不通、九窍不利，故以甘酸寒之品益肝气、通血脉、养精神。全段为药性主治之论，未出现脉象描述，脉象要素为空。", []], "26808": ["其他", "此段论鹿茸生成之速与补益之功，非论脉。原文谓鹿\"卧则口鼻对尾闾，以通督脉\"，说明鹿茸通督脉、补骨血、益精髓之由；又谓\"头者，诸阳之会，上钟于茸\"，故能助阳。全段以鹿之生理推药性，强调用须鹿茸、麋鹿当别，属药物辨识，与脉象病机无涉。", []], "26809": ["病机", "此段以鹿茸\"禀火气而温土，从阴出阳\"立论，释其主治漏下恶血、寒热惊痫、益气强志、生齿不老之机。原文谓\"土气虚寒，则恶血下漏\"，鹿茸温土举陷则恶血不漏；\"阳虚则寒热\"\"神虚则惊痫\"，茸能充心神而除之。全段由药性推病机，非据脉辨证。", []], "26810": ["病机", "此段比较鹿茸甘温与鹿角胶甘平之异，论鹿胶主治伤中劳绝、腰痛羸瘦、妇人血闭无子、止痛安胎之理。原文谓\"鹿运督脉，则腰痛可治\"\"胶能益髓，则羸瘦可治\"，又谓\"启生阳，行瘀积，和经脉而孕子\"。全段以药性推病机，属方药理论，未及脉象。", []], "26811": ["误治", "此段辨中风入脏与中腑中经脉用药之误。李东垣主张风中于腑及经脉者早用牛黄，反引风邪入骨髓，\"如油入面，不能出\"；作者驳之，谓风入脏本属死证，牛黄主治心家风热狂烦，配脑麝辛窜透发，反使\"脏气益虚而真气外泄\"。全段论误治之害，非脉诊内容。", []], "26812": ["病机", "此段论阿胶滋补心肺之功，释其治心腹内崩、劳极洒洒如疟状、腰腹痛、四肢酸痛、女子下血、安胎之理。原文谓\"心包之血，不散经脉，下入于腹而崩堕\"，阿胶益心主之血故治之；\"劳极气虚，皮毛洒洒如疟状之先寒\"，阿胶益肺主之气故治之。全段由药性推病机。", []], "26813": ["病机", "此段论牡蛎禀寒水之精、具坚刚之质，释其主治伤寒寒热、温疟洒洒、惊恚怒气、四肢拘缓、鼠瘘、带下赤白、强骨节之理。原文谓\"太阳之气，行于肌表\"故治温疟洒洒；\"厥阴肝木受病\"故治惊恚怒气；\"胞中湿热下注\"故除带下赤白。全段以药性推病机，未涉脉象。", []], "26814": ["病机", "此段论螳螂生于五月，禀太阳之气，得桑之金气，气味咸甘，释其主治伤中、疝瘕、男子阴痿、女子血闭腰痛、五淋小便不利之理。原文谓\"禀刚锐而疏通经脉\"故治疝瘕，\"具生长迅发之机\"故治阴痿益精，\"升已而降\"故通五淋。全段由物性推药效病机，非脉诊。", []], "26815": ["其他", "此段为《金匮》泽漆汤方用紫参之考据。原文引\"咳而脉沉者，泽漆汤主之\"，脉沉主水饮内停、肺气不降之咳，故以泽漆汤逐水通阳。然本段主旨在于辨析紫参、牡蒙、王孙之名实，存方以备参，非专论脉沉病机，故归其他。", ["沉"]], "26816": ["主病", "原文引张仲景治咳而脉浮者用泽漆汤，脉浮提示病位偏表或肺气壅实。白前长于降气，肺气壅实有痰者宜之，故脉浮主咳逆上气属肺实之证。然虚而长哽气者不可用，说明脉浮需结合虚实，此处脉浮与肺气壅实、痰浊上逆相应。", ["浮"]], "26817": ["病机", "原文未出脉象，以当归主治咳逆上气、温疟寒热、妇人漏下绝子等，阐发其禀少阴水火之气，使心肾上下相交、各有所归。咳逆上气乃心肾不交、气逆于上；温疟寒热洗洗在皮肤中乃血虚外邪不解；漏下绝子乃肾精不交于心包。全段从药性推病机，非论脉。", []], "26818": ["病机", "原文未出脉象，以芍药禀厥阴木气治肝、少阴火气治心，阐述腹痛、血痹、坚积、疝瘕等病机。风木之邪伤中土，脾络不能外行则腹痛；血痹则身发寒热；坚积则或疝或瘕。芍药调血中气、疏通经脉，故诸证可治。全段以药测证，说明血行不畅、经脉不通之病机。", []], "26819": ["病机", "原文未出脉象，论牡丹皮禀金水相生之气化，主治寒热中风、瘛疭惊痫、症坚瘀血留舍肠胃。邪风伤血脉则身发寒热、手足瘛疭、面目惊痫；经脉之血不渗灌络脉则留舍肠胃为症坚瘀血。丹皮辛散寒清，治血脉之风、除瘀血，说明血分风热与瘀滞互结之病机。", []], "26820": ["病机", "原文虽标脉虚，实论泽兰主治三因之证：金疮为不内外因，痈肿为外因，疮脓为内因。疮脓乃心火盛而血脉虚，脉虚正合血脉空虚、心火亢盛之机。泽兰禀五运之气，苦温根萼紫黑，入少阴水火，故能治血脉虚而火盛之疮脓，脉虚与血虚火盛相应。", ["虚"]], "26821": ["病机", "原文未出脉象，论防己辛平，禀金水相生之气化，主治风寒温疟热气、诸痫除邪、利大小便。风寒藏于肾脏，发为先热后寒之温疟，热气有余；心包受邪发为诸痫；土得木而达则二便通利。全段以药性推病机，说明水精不输、经脉不通、土气壅滞之证。", []], "26822": ["主病", "原文引《金匮》膈间支饮，喘满痞坚，面色黧黑，其脉沉紧，得之数十日，医吐下之不愈，木防己汤主之；又风水脉浮身重，汗出恶风，防己黄耆汤主之。脉沉紧主水饮内结、气机壅滞；脉浮主风水在表、卫表不固。防己启水精、通经脉，故两证皆主之。", ["沉", "紧", "浮"]], "26823": ["主病", "原文未出脉象，述某药辛平无毒，主除脾胃寒热，通利九窍血脉关节，令人不忘，去恶虫。其主旨在于概括药物主治：脾胃寒热、九窍血脉关节不通、健忘、虫积。虽未言脉，然从“通利九窍血脉关节”可知所主病机为气血壅滞、关窍不利，属主病范畴。", []], "26824": ["病机", "原文未直接论脉，但以木通“藤蔓空通”之性，类比其能通利九窍、血脉、关节。血脉通利则关窍不塞，故令人不忘；禀土气除脾胃寒热，禀金气去恶虫。此段借药性说明气血通畅则神志清明、邪虫可去的病机，非论脉象。", []], "26825": ["病机", "原文以葛根“宣达阳明中土之气，而外合于太阳经脉”说明其调和肌表之气、和阳明胃气之功。脉“调和肌表之气”指脉之正气能散邪，使经脉和畅，故大热除、呕吐止、诸痹愈。若太阳初病未入阳明而早用升麻、葛根，则反引邪入阳明，为引贼破家。", ["和"]], "26826": ["病机", "原文未直接论脉，以白芷“禀阳明燥金之气下行”解释其治妇人漏下赤白、血闭阴肿，因阳明胃脉主阖，气下行则血有所统；又禀阳明中土之气上达，故治寒热头风侵目泪出。土主肌肉、金主皮肤，故长肌肤、润泽颜色。", []], "26827": ["病机", "原文明言“经脉空虚，故曰瘘”，指出寒热鼠瘘内因在于水脏之毒上出于脉，而脉空虚不能固护，故为寒为热。荆芥味辛性温，肃清经脉，故能治内因之鼠瘘及外因寒邪客脉、血气留滞之瘰疬生疮。脉空虚正是经脉不充、邪毒留结之病机。", ["虚", "空"]], "26828": ["病机", "原文未直接论脉，以贝母“根形象肺，色白味辛”说明其清补肺金。肺气通于皮毛，故能治淋沥邪气；金能平木，故治疝瘕；通肺气则喉痹可解；禀阳明秋金之气，内开郁结、外达皮肤，故乳难、金疮风痓皆治。此段以药性推演肺金郁结、气机不通之病机。", []], "26829": ["病机", "原文指出“周痹，则周身血脉不和”，苍耳子禀阳明燥金之气，金能制风、燥能胜湿，故治风头寒痛、风湿周痹、四肢拘挛痛。血脉不和则痹痛拘挛，久服风湿外散、经脉流通，故益气。脉不和正是风湿伤血脉、气血痹阻之病机所在。", ["不", "和"]], "26830": ["病机", "原文未直接论脉，以瓜蒌根“入土最深，外黄内白”说明其得地水精气而上达，能启在下之水精上滋以治消渴身热；其实“从上而下”，降在上之火热下泄以治烦满大热。水火上下交济则补虚安中，藤蔓之药资经脉故续绝伤。此段阐发水火不交、津伤热结之病机。", []], "26831": ["病机", "原文明言“经脉外内之坚结”及“经脉不和而病结于外”“经脉不和而病结于内”，指出瘿瘤结气、颈下硬核痛、痈肿为外结，症瘕坚气、腹中上下雷鸣为内结，皆因经脉不和、坚结不通。海藻苦咸性寒，咸能软坚、润下，形如乱发主通经脉，故能治十二经水肿，使经脉流通而结散肿消。", ["坚", "不", "和"]], "26832": ["病机", "原文以萆薢“骨胜藤蔓”论药性，未及脉象。其“主肾”因根荄坚硬骨胜，肾主骨；“走经脉”因有刺藤蔓，通利经脉。所主腰脊痛强、骨节风寒，乃肾虚骨节失养兼风寒痹阻；湿痹、周痹因湿邪滞络；苦能清热治恶疮热气。全段以药性推导病机，非脉诊内容。", []], "26833": ["其他", "此段为狗脊产地、形态及名物考证，未涉脉象。述其茎节如竹有刺、叶有赤脉、根形如狗脊骨，故《本经》名百枚以形名，《别录》名强膂、扶筋以功名。赤脉对生、根坚似骨，暗合入血通脉、强筋骨之功，然全段主旨为药物基原与命名，非病机脉理。", []], "26834": ["病机", "原文“脉不和”即血脉不和，取涩象以应滞涩不畅。狗脊根坚似骨、叶有赤脉，故利骨节通经脉。血脉不和则周痹，因寒因湿皆能痹阻经脉，故治周痹寒湿；机关缓急则膝痛，老人精血虚而机关不利，故颇利老人。脉涩主血行不畅、经脉痹阻，与腰背强、膝痛、周痹相应。", ["涩"]], "26835": ["病机", "原文未及脉象，以紫葳延引藤蔓主通经脉，气味酸寒主清血热，故《本经》主治如此。近用为通经下胎之药，仲景鳖甲煎丸用之以消症瘕，必非安胎之品，养胎当是堕胎之讹。全段论药性通经消症、清血热之病机，非脉诊内容。", []], "26836": ["病机", "原文“皮肌经脉虚寒”点明金疮疮败之病机为虚寒。薤用在下之根，辛温从下而上，助生阳上升，从内达外。胸痹三方皆取自下而上、从阴出阳之义。脉虚寒主阳气不足、经脉失温，故金疮疮败、胸痹等症相应，薤白辛温通阳散寒治之。", ["虚", "寒"]], "26837": ["病机", "原文未及脉象，以藁本生崇山、禀太阳标本之精，论其下治妇人疝瘕、阴中寒肿痛，中治腹中拘急，上除头风痛。盖太阳之脉本于下而上额交巅，出入中上，故一药贯通上下。太阳阳气有余则长肌肤、悦颜色。全段以药性推演太阳经气上下出入之病机。", []], "26838": ["病机", "原文未及脉象，以白薇号春生，启水天精气随春升。味苦咸，禀太阳寒水在下、标阳在上，根黄白得秋金合肺气于皮毛。故主治暴中风、身热肢满，风淫四末则肢满，行头目则忽忽不知人，淫血分涉心包则狂惑，淫肌腠经脉则寒热酸痛。全段论风邪变证之病机。", []], "26839": ["病机", "原文两言“脉络不和”，取涩象应脉络滞涩。竹茹为竹之脉络，人身脉络不和则吐逆而热，或寒或热；充肤热肉淡渗皮毛之血不循脉络，则上吐血下崩中。以竹之脉络通人之脉络，故诸病皆治。脉涩主脉络不和、血不循经，与吐逆寒热、吐衄崩中相应。", ["涩"]], "26840": ["病机", "原文论慈石治周痹，谓'在于血脉之中，真气不能周也'，指明病机为血脉痹阻、真气不周；又风湿伤于肢节致'不可持物，洗洗酸消'，乃风湿之邪阻滞肢节。慈石禀金水之精，通调血脉、散其风湿，故所主为血脉不通与风湿痹痛之证，非以脉象立论。", []], "26841": ["病机", "原文以硫黄禀'火土相生之气化'立论，'禀火气而温经脉'故治妇人阴蚀、疽痔恶血，是寒凝血瘀、经脉不通之病机；'禀土石之精，故坚筋骨'，阳气长则毛发生，主头秃，皆阳气不足、筋骨不坚之候。全段言药性所对之病机，未及脉象。", []], "26842": ["病机", "原文举大黄䗪虫丸、鳖甲煎丸、下瘀血汤并用虻虫，明言其为'攻坚破积，行血散疟之剂'。虻虫主'逐瘀血，破血积坚痞，症瘕寒热，通利血脉'，所对病机为瘀血内结、症瘕坚痞、血脉不通，故以飞动吮血之虫入血分攻破，属瘀积实证之治法与病机。", []], "26843": ["病机", "原文谓虻虫'吮血之虫，性又飞动'，故主逐瘀血积血、通利血脉九窍；引《伤寒论》太阳表不解、随经瘀热在里用抵当汤，说明病机为瘀热互结下焦、血脉壅滞。近时儿医加牛虻治痘不起发，亦取活血透达之意。全段论瘀血病机与方治，未涉脉象。", []], "26844": ["误治", "原文针砭世医'不识病机'，必待'脉脱厥冷，神去魄存'方用附子，指出火气内衰、阳气外驰当及早温助火原，使神机上行环行而不外脱。脉脱厥冷即阳气衰败、脉气将绝之候，此时用药已晚。段旨在于批评延误病机之误治，非论平脉。", []], "26845": ["病机", "原文论大黄之用，因西北土气敦厚、阳气伏藏与东南土气虚浮、阳气外泄而异，又须察禀气厚实、积热留中与素禀虚寒之别。三承气汤皆用大黄，大承气与芒硝同用承在上之火热，小承气但用大黄行肠胃燥结，所对为燥结内实、火热上承之病机，强调因人因证斟酌。", []], "26846": ["病机", "原文以半夏禀阳明燥金之气化立论：辛以散伤寒寒热；胃络不通于心则心下坚，金气不和于肺则胸胀咳逆；金能制风故治头眩咽痛，燥能胜湿故治肠鸣下气止汗。所主病机为阳明燥金之气不宣、胃络不通、金气不和于肺，兼风与湿之候，全段未言脉。", []], "26847": ["病机", "原文以连翘形象心肾、禀少阴之气化，论鼠瘘起于肾脏之毒、留于心主血脉，瘰疬因天气之寒伤人身经脉；'痈肿恶疮，肌肉不和；瘿瘤结热，经脉不和'，点明肌肉、经脉不和之病机。连翘苦寒芳香，通经脉而利肌肉，故治之。'脉不和'在此指经脉不和，非脉象要素。", ["不和"]], "26848": ["病机", "原文未出脉名，而论鼠瘘寒热之毒气留于脉而不去，本在水脏，上通心主之脉，故颈腋溃烂。其寒热起于血脉，与伤寒中风起于皮肤者迥异。指出病机在血脉水毒，非表邪寒热，故不可概用连翘治风寒寒热，强调营卫血气出入脏腑经脉交合贯通为医家根本。", []], "26849": ["病机", "原文无脉象，专论大戟禀金水木相生之气化，水能生木则木气运行，故治蛊毒；金能生水则水气运行，故治十二水。腹满急痛、积聚属土气不和，中风皮肤疼痛属肌表不通，皆致吐逆。全段以五行气化说明水气不行而肿及蛊毒积聚之病机。", []], "26850": ["病机", "原文引《金匮》泽漆汤证：咳而脉浮者，厚朴麻黄汤主之；咳而脉沉者，泽漆汤主之。脉浮为病偏于表、饮邪上逆，故用厚朴麻黄宣散；脉沉为水饮内结、病在里，故以泽漆汤逐水通阳。同是咳逆上气，凭脉浮沉辨表里浅深，示水气病机之异。", ["浮", "沉"]], "26851": ["误治", "原文举伤寒脉浮，医以火迫劫之，致亡阳惊狂、起卧不安，用桂枝去芍药加蜀漆牡蛎龙骨救逆汤。脉浮本为表邪，误以火攻劫汗，阳随汗亡，心神浮越故惊狂。蜀漆通金水之气以救火逆，启太阳之阳以接亡阳，属从阴出阳之药，示误治后救逆之法。", ["浮"]], "26852": ["病机", "原文无脉象，论荛花气味苦寒，禀太阳本寒而合标阳，故治伤寒、温疟。膀胱水气藉太阳阳热运行周身，外濡皮毛内通经脉；水气不行则为十二经脉之水。荛花合太阳之阳，故下十二水、破阴凝积聚症瘕，荡涤胸中留澼痰饮，利水道，全在阳热运水之机。", []], "26853": ["预后", "原文引《金匮》浸淫疮从口流向四肢者可治，从四肢流来入口者不可治。口为脾窍，脾主四肢，故以流向辨顺逆。萹蓄禀火气温土，治脾湿浸淫；禀东方木气，通利三焦，从经脉达肌腠皮肤，故兼治疥瘙、疽痔、三虫。全段以疮之流向定预后吉凶。", []], "26854": ["病机", "原文引《辨脉篇》唇口反青、四肢漐习者为肝绝。青葙花黄白、结黑子于深秋，得金水相生之化以养肝木，故子治唇口青。此以五行生化说明肝木失养、色现唇口之病机，肝气得其生化则目明，故今又用以明目，属以药性推病机。", []], "26855": ["病机", "原文无脉象，论蛇含草禀土金水之气化：金能制风，故治惊痫寒热；寒能清热，故除邪热；土能生肌，故治金疮。其气和在下之经脉则治疽痔，和在上之经脉则治鼠瘘恶疮头疡。全段以气味归经说明风热、肌伤及上下经脉疮疡之病机。", []], "26856": ["病机", "原文引《金匮》「少阴脉滑而数者，阴中即生疮」，滑主湿浊内蕴，数主热邪炽盛，少阴脉位候前阴，湿热下注腐蚀阴中，故生疮蚀烂。狼牙汤苦寒纯阴，正对少阳火热疮烂之机，以苦泄热、以寒胜火，说明此脉所主为下焦湿热火毒之证。", ["滑", "数"]], "26857": ["其他", "本段未言脉，专论羊踯躅花色黄、气味辛温，禀火土金相生之化，以「金主皮毛，土主肤肉，火主血脉」立论，主治贼风在皮肤中淫淫痛、温疟恶毒及皮脉肉诸痹，乃以毒攻毒之法。所涉为药性归经与主治，非脉象病机，故脉象要素为空。", []], "26858": ["其他", "本段未及脉象，述莨菪子苦寒生于海滨，得太阳寒水之气，故治齿痛、出虫、温肌腠、治肉痹拘急；又禀太阳少阴标本之精而助𫏋脉，故轻身健行、强志益力。全段为药性气味与所主病证之论，属本草主治范畴，无脉可录。", []], "26859": ["其他", "本段未言脉，论巴豆辛温大热有毒，其性剽悍，辛以散伤寒温疟寒热从经脉外出肌表，温以行症瘕结聚、坚积留饮而从中土下泄肠胃；「气合阳明」故除鬼毒蛊疰、杀虫鱼。所论为药性峻猛与攻邪之理，非脉诊病机，故脉象要素从缺。", []], "26860": ["妇人", "本段未载脉象，论衣鱼色白禀金气、气味咸温禀水气，水能生木故治妇人疝瘕（肝木病），金能生水故治小便不利；又小儿经脉未充，中风日久项强背起属督脉为病，以衣鱼摩之。涉及妇人疝瘕与小儿中风，主在妇人、小儿用药，故归妇人。", []], "26861": ["其他", "本段为《别录》人参主治条文，味甘微温，疗肠胃中冷、心腹鼓痛、胸膈逆满、霍乱吐逆，调中止消渴、通血脉、破坚积、令人不忘。全段述药性与主治，未涉脉象，故脉象要素为空，主旨属本草主治而非脉诊病机。", []], "26862": ["病机", "本段论高丽参禀东方发生之气，温养生发，用于脾胃虚寒、真阴衰弱、中气不振诸证。原文指出「肠胃中冷、心腹鼓痛者，皆中气虚寒、真阳不宣之候」，「胸胁逆满，亦阳衰阴盛之病」，且明言非痰湿凝滞之逆满，故宜温补。所析为中气虚寒、阳衰阴盛之病机。", []], "26863": ["病机", "原文举仲景「汗后身热、亡血、脉沉迟者」与「下利身凉、脉微、血虚者」并加人参。沉迟为阳气不足、血行迟滞，微为阳气衰微、血虚不充，二者皆气血两亏之候。东垣谓人参甘温补肺中元气，正合「血脱益气，阳生而阴自长」之理，说明此脉主气虚血脱之病机。", ["沉", "迟", "微"]], "26864": ["病机", "原文引仲景用人参于汗后吐后，见脉微、脉沉迟，此乃阴血亏虚、阳气不振之象。脉微为气血不足，沉迟为阴寒内盛，故人参滋阴养血，阴充则气旺。寿颐强调高丽参含温养性质，具春升之气，能升提元气，非单纯补气，更非回阳救逆之品。", ["微", "沉", "迟"]], "26865": ["病机", "李月池辨人参可用与不可用，以脉症分虚实。脉浮而芤濡虚大、迟缓无力，沉而迟涩细弱、结代无力，皆虚而不足，可用人参；弦长紧实、滑数有力，则火郁内实，不可用。此以脉之有力无力判虚实，虚寒者宜补，实热者宜泻，示人凭脉用药之准则。", ["浮", "芤", "濡", "虚"]], "26866": ["其他", "寿颐评李氏辨脉症明晰，但所举尽属虚寒证治，专指高丽参温补而言。原文未出具体脉象，仅承前段虚寒脉症而论，强调李氏所论适用范围有限，非通治一切人参证。", []], "26867": ["治法", "景岳论药之主清肺凉肝、滋养血脉、散风热痒瘙、头面肿痛。原文未涉脉象，纯述药效与治法，以清凉滋养散风为用，针对肺肝热盛、血脉失养、风热上攻之头面肿痛痒瘙等症。", []], "26868": ["病机", "原文论桔梗辛温通利之效，利五脏肠胃即宣通之功，补血气因辛温能活血行气、通行百脉。除寒热者鼓舞阳气，风痹乃气血凝滞，通而行之则痹已。温中消谷为宣通阳气余义，疗咽痛取辛温通少阴结气，下蛊毒取宣泄之力。全段未出脉象，专阐药性病机。", []], "26869": ["病机", "论白术苦甘而温，禀坤土中和之性，专主脾胃，补土胜湿。温胜寒，燥驱湿，芳香通脉络走肌肉，故主风寒湿痹、死肌。风湿著关节则痉强直，脾家湿热郁蒸发黄疸，术能胜湿宣络故主痉疸。自汗亦脾湿，燥湿则汗止；除热除脾虚发热；消食湿除脾运健。全段未出脉象。", []], "26870": ["病机", "灵胎论白术气香性温、味苦而甘，皆属于上，故宜补脾土；其气甚烈，芳香四达，又能达于经脉肌肤，不专于补中。原文未出脉象，专述药性升降走守，明白术补脾之外兼能外达经脉肌肤。", []], "26871": ["病机", "论黄芪《别录》主妇人子脏风邪气，乃中气不振，补益中气则邪自除；气行血行，温养运行则恶血自去。补虚损五劳羸瘦皆益气温养之功；甘益津液，温和润泽，升举助脾胃津液则口渴止；腹痛泄利乃中气不举、清阳下陷，甘温益气则痛利自已。茎叶疗渴、治筋挛、消痈肿，与外行旁达之性有关。全段未出脉象。", []], "26872": ["病机", "原文未出脉名，专论天麻主治之分歧：一主诸风湿痹、四肢拘挛、瘫痪不随，属邪实宜攻；一主风虚眩晕头痛、语言不遂，属正虚宜补。作者点明二者“一属邪实，一属正虚，实者宜攻，虚者宜补，大是相反”，揭示同一药所对之病机虚实迥异，须辨明风邪外袭与虚风内动之不同。", []], "26873": ["病机", "原文辨天麻非辛温宣散之品，以“厚重坚实，明净光润，富于脂液”说明其能“平静镇定，养液以息内风”。故风寒湿邪痹著瘫痪非其所长，而虚风眩晕头痛、眼黑头旋、风虚内作者，正取其养液息风、潜阳镇定之功。所论在明药性所主之病机虚实，非脉象也。", []], "26874": ["病机", "原文论丹参专入血分，功在活血行血，内化瘀滞则积聚消、症瘕破，外通脉络则腰膝健、痹著行。其能运行者赖温和之气鼓荡振动，故主心腹邪气、肠鸣痼疾。又谓“走窜有余，必非补养之品”，《本经》益气、《别录》养血皆“以通为补”，苦味泄降故所主各病皆有下行为顺之意，全在阐发活血通滞之病机。", []], "26875": ["其他", "原文为考据辨误，非论脉。作者指《日华本草》所录丹参主治最杂，如头痛赤眼与陶弘景久服眼赤之说背道而驰，冷热劳、安生胎、落死胎、止血崩带下等语“杂乱无章，全是凭空虚构”，并责景岳、士材、石顽采录不加辨正。旨在纠本草主治之滥，不涉病机脉理。", []], "26876": ["病机", "原文论知母寒润止治实火，举热病在阳明“烦渴大汗，脉洪里热”者，佐石膏以扫炎熇。脉洪为阳明实热蒸腾、正气未衰之象，与烦渴大汗相应，故可寒凉直折。若正气不充、脾土不振，则视之如鸩毒。全段以“实热有余”四字统括知母主治范围，脉洪正是实热之凭。", ["洪"]], "26877": ["兼症", "原文辨白痢不可概作虚冷，须“以舌苔脉证参之”。湿热蕴积未及血分，滞下不必红色，若见“脉实舌腻腹痛”及舌心黄腻、尖边红者，脉实主邪实热结，与舌腻腹痛相合，芩连均是要药。惟病久元虚则非实邪可比。所论在凭脉实与舌腻合参以定湿热实邪，非虚寒白痢。", ["实"]], "26878": ["病机", "原文论黄芩治发背，古时多由膏粱药石而发，本属邪热，故大剂凉解为正治。而今之背疽则“皆寒入督脉太阳之络，非温经升散不为功”，古今证治相反，误与寒凉即致内陷不治。全段辨背疽寒热两途之病机，告诫不可拘守古人而不辨寒热，未及脉象。", []], "26879": ["病机", "原文论白鲜为苦寒胜湿之药，能通行经隧脉络。头风为风湿热之在上，黄疸咳逆为湿热之在中，湿痹死肌、不可屈伸起止行步为湿热痹于关节肌肉。其气味甚烈，故能彻上彻下、通利关节、胜湿除热。全段以湿热壅滞、痹阻脉络为病机，未出脉象。", []], "26880": ["其他", "此段为《日华子本草》对某药功用的记述，言其通关节、利九窍、通血脉，主天行头痛眼赤。原文未及脉象，故无从论脉。所主之天行头痛眼赤，属外感时邪、热郁上焦之候，与通血脉、利九窍之功相应，非脉诊所能推演，列于其他。", []], "26881": ["病机", "此段论白薇苦寒清热之功。原文以暴中风身热为热盛风动，支满为邪热搘拄胸中、气逆满闷，忽忽不知人及狂惑为热盛火升、扰及脑神。全段从药性推病机，未涉脉象，故脉象要素为空。其主旨在于阐发苦寒泄降以解热结之机理，归入病机。", []], "26882": ["妇人", "此段引《日华子本草》言某药主妇人月经不匀、血脉淋沥。原文未载脉象，故脉象要素为空。所论月事不调、淋沥不尽，属妇人经血之候，故归妇人一类。其病机当从血热或血脉不畅理解，然原文仅列主治，未及脉症，不可强补。", []], "26883": ["其他", "此段为寿颐按语，辨《日华本草》以经脉、血脉指称妇人月事之不当，属名实之辨，非论脉诊病机。原文无脉象描述，故脉象要素为空。其主旨在于纠正本草名词之混用，强调名不正则言不顺，与脉学病机无直接关联，归入其他。", []], "26884": ["病机", "此段论柴胡轻清升腾，能宣发气机，使清阳敷布而积滞自化。原文所言心腹肠胃结气、饮食积聚、寒热邪气、痰热结实、水胀等，皆因气机窒滞而痰食水气阻结。全段从药性升发推阐病机，未及脉象，故脉象要素为空。其要在气机窒滞、清阳不布，归入病机。", []], "26885": ["病机", "原文以脉见虚软、脉来濡弱为据，说明中气无权、不能宣布，致饮食痰水停滞积聚。虚软濡弱皆主中气不足、清阳不升，故积聚由中气无力斡旋而生。柴胡禀春升之气，能振举清阳，使大气斡旋而积滞自化，正合虚软濡弱之脉所主之中气不振病机。", ["虚", "软", "濡", "弱"]], "26886": ["病机", "此段论独活气味雄烈、芳香四溢，能宣通百脉、调和经络，凡风寒湿邪痹于肌肉、著于关节者，非此不能直达经脉骨节。原文未及脉象，故脉象要素为空。所主风痹痿软诸证，病机在风寒湿邪痹阻经脉骨节，气血不通，归入病机。", []], "26887": ["病机", "此段辨羌活、独活气味浓淡及升降之别，言羌活气雄，能直上顶颠、横行支臂，搜风通痹；独活味厚，通行胸腹腰膝。原文引洁古治督脉脊强而厥、海藏治足太阴风湿相搏，皆从药性升降推病机，未涉脉象，故脉象要素为空。主旨为风湿痹阻、经脉不利之病机。", []], "26888": ["病机", "原文虽未出脉名，然言秦艽「善行百脉」「通达百脉」，其主寒热邪气、肢节痛、通身挛急，皆因风寒湿邪客于肌肉筋络骨节，致百脉流行不畅。脉象当见涩滞不利，或弦紧而涩，反映邪阻脉络、气血痹着之机。秦艽能行百脉、驱湿下行，故治痹着之肢节痛与挛急，非虚损之脉所宜。", []], "26889": ["病机", "原文未出脉名，而言狗脊「温养肝肾，驱除风寒湿三气」，主腰背强、膝痛脚弱、机关缓急、周痹寒湿。此皆肝肾不足、寒湿痹着、经脉不利之病机。脉当见沉细而弦，或濡缓无力，反映肝肾虚而湿邪留着。老人肝肾已衰、机关窒滞者，脉多沉弱，故以温养流利为养老要药。", []], "26890": ["病机", "原文未出脉名，强调狗脊「温养肝肾，通调百脉，强腰膝，坚脊骨，利关节」，治痹着痿废、女子经带淋露。其病机为肝肾虚衰、督任不固、百脉失于温通。脉当见沉细弱，或弦缓无力，尺部尤甚，反映下元虚寒、冲带不摄。温而不燥、走而不泄，正合虚寒痹着之脉。", []], "26891": ["病机", "原文未出脉名，述山慈姑「散坚消结，化痰解毒」，治痈肿疮瘘、瘰疬结核、胸腹攻痛窒塞。其病机为痰毒凝结、气血壅滞不通。脉当见滑数而实，或弦紧有力，反映痰热结聚、毒邪壅盛。紫金锭合通利迅疾之品，取效眉睫，正对脉实邪盛之证；若脉虚细弱者，则非所宜。", []], "26892": ["病机", "原文列「脉小不劲」「脉则虚弦软数」「脉虚弦缓大」「左寸关弦大以数」「脉来小数虚弦」诸象，皆阴虚劳怯、咳嗽失血之脉。脉小不劲为阴亏而阳不亢；虚弦软数乃虚火内扰、肺肾阴伤；左寸关弦大以数，心肝火旺而阴不制。冬虫夏草甘平保肺益肾，补精髓，正对虚劳脉虚弦数之病机。", ["小", "弦", "软", "数"]], "26893": ["病机", "原文未出脉名，论牛膝「疏利泄降，所主皆气血壅滞之病」，治湿流关节之痿痹、四肢拘挛、膝痛不可屈伸。其病机分湿阻与血衰两层：湿阻者脉多沉涩或濡缓，血衰者脉多细弱。牛膝曲而能达，逐邪养正皆可辅佐，故痿弱痹着、骨痛筋挛诸证不可一日无此，非气血枯竭之拘急不遂可比。", []], "26894": ["病机", "原文未出脉名，辨川牛膝与怀牛膝之异：川产细而微黑，质空疏，力能旁行上达，宣通关节，宜于肝肾阴虚而机关不利者。其病机为阴血不足、脉络骨节失于流利。脉当见细弦或沉涩，反映阴虚而络脉不畅。质空疏则旁行上达，与怀膝坚实直下者功用有别，故肩背手臂疏通脉络其效颇著。", []], "26895": ["病机", "原文未出脉名，言此物性寒凉、气猛烈、长于走窜开泄，治热烦痈毒、吐痰疟；九次蜜酒蒸晒后气味已驯，通利机关、和调血脉，治风寒湿热诸痹。其病机为邪热痰浊壅滞、脉络痹阻。生用脉多滑数实大，制后脉多弦涩不利。走窜开泄以逐邪，蒸晒和蜜以驯性，故为微贱药中之良品。", []], "26896": ["病机", "原文论续断通调经脉，谓其主伤寒、补不足，极言通调经脉之功；活血通络故治金疮痈疡、折跌恶血、腰痛关节缓急，产后崩漏亦以行血和血取效。虽未出脉名，所主病机为血脉瘀滞、络脉不通，与伤损、痈肿、产后诸证相应。", []], "26897": ["病机", "甄权称续断宣通血脉，点明其功在通利血行。原文未及脉象，所主病机为血脉壅滞不畅，故以宣通为治，与瘀阻络脉、关节不利等证相应，属药性病机之论。", []], "26898": ["病机", "景岳称续断味涩，能止吐血、衄血、崩淋、胎漏、便血，调血痢，止带浊。涩味主收摄，故主血不循经、滑脱不禁之病机，与出血、崩漏、带浊、血痢等症相应；佐以甘药如甘草、地黄，是缓其苦泄而护中。", ["涩"]], "26899": ["病机", "石顽谓续断入肝经，主续筋骨，为妇科胎产崩漏主药，又主带脉为病，疗腰痛、利关节、暖子宫。所主病机为肝血不足、带脉失约、筋骨损伤，与胎产崩漏、腰痛、金疮折伤、痈肿瘀血相应。", []], "26900": ["病机", "原文谓续断气温和、味苦辛微甘，气味俱厚，兼入气血，宣行百脉、通利关节，凡经络筋骨血脉诸病无不主之，通痹起痿尤有特长；苦涩能行能止，故疗崩漏带下、血痢淋浊及女科奇经诸病。所主病机为气血壅滞、络脉不利与血滑不摄并存。", []], "26901": ["病机", "《本经》言麦冬味甘平，主心腹结气、伤中伤饱、胃络脉绝、羸瘦短气。所主病机为胃络失养、津液不充而气结不利，故见羸瘦短气；甘平之味养胃生津，使络脉得续，与中虚液少之证相应。", []], "26902": ["病机", "正义谓麦冬富有脂液，清润甘凉，为养胃生津专品；《本经》心腹结气乃燥热津枯而气结不利，伤中伤饱、胃络脉绝、羸瘦短气皆胃液不充、食少中虚之证。故所主病机为燥热津枯、胃络失养，非痰湿郁窒之结气、食积之伤饱所宜。", []], "26903": ["病机", "原文辨《别录》心下支满属燥热津枯、心胸不舒，方合麦冬寒润；而身重目黄为湿热蕴积，心下支满又属痰湿互结，麦冬黏腻大非所宜。其治虚劳客热、口干燥渴则滋虚退热、解渴生津；止呕吐须舌质乾红之燥火，挟痰浊则审慎；愈痿蹶取阳明燥热灼津、筋枯骨萎之义。", []], "26904": ["治法", "原文未直接描述脉象，但以“复脉通心”点明治法目标。所论心肺虚热及虚劳，脉当见虚数或细数，治以地黄、阿胶、麻仁、五味子、枸杞子等润经益血之品，使阴血得复，脉道充盈，虚热自退，故曰复脉通心。", []], "26905": ["病机", "原文以“脉弛缓而不收”论麦冬之用。脉弛缓不收，乃脾胃虚寒、清阳不振之象，阴柔膏腻之品反碍转输，故非所宜；而热炽液枯者，脉必数而细，麦冬寒润补阴解渴，正为恰当。此段从脉象弛缓辨明麦冬适用与禁忌之病机。", ["缓"]], "26906": ["病机", "原文未直接言脉，而辨麦冬专主胃阴而非补肺。肺痿属虚，脉多虚数无力；肺痈属实，脉多滑数有力。麦冬润腻，可治火烁之痿，不可治痰塞之痈，从虚实病机分判，强调肺痈痰浊气火交结，万无投滋腻之理。", []], "26907": ["病机", "原文引《金匮》泽漆汤治“咳而脉沉者”，明言“脉沉血分之病也”。咳为肺病，脉沉则病不在气分而在血分，血行不畅，水气内停。泽漆汤辛润通利，疏利肺家血气，止咳定喘，通调水道，故脉沉为血分病机之关键。", ["沉"]], "26908": ["病机", "原文论百合病为伤寒后余热未清之证，神志恍惚，百脉一宗，悉致其病。虽未明言脉象，然余热蕴结，脉多微数或细数。百合甘寒滑润，清热泄降，开结通利，邪热去则正气自旺，非径以甘寒为补益。", []], "26909": ["病机", "原文未直接论脉，而辨牛蒡子辛泄苦降下行之力多，能疏散风热、透达斑疹、通大便。热盛或脾气不坚者投之辄泄泻，说明其性偏降泄。风热外袭，脉多浮数；斑疹不透，脉多浮紧。牛蒡子宣散四达，通行经络，使邪去而正自安。", []], "26910": ["病机", "原文未言脉，而论苍耳为疏风散寒、驱湿逐痹、疏利关节、通调脉络之良药，主治风寒湿痹。风寒湿三气杂至，脉多沉紧或弦缓。苍耳温和疏达，通调脉络，使痹著得除，溪毒湿邪亦解。", []], "26911": ["病机", "原文未直接描述脉象，而谓苍耳子温和疏达，流利关节，宣通脉络，主治风寒湿三气痹著，又上达颠顶，为头风要药。风寒湿痹脉多沉紧弦缓，头风脉多浮弦。其性驯良，不偏燥烈，无辛香走窜耗散正气之虑，但和缓有余，奏功较缓。", []], "26912": ["其他", "原文为《斗门方》记载妇人血风攻脑、头旋猝倒之方药，未涉脉象。其言苍耳草嫩心通顶门、达脑、走督脉，是就药性升散立论，非脉诊内容，故无从据脉析病机，仅属方药杂录。", []], "26913": ["病机", "寿颐按语指出头旋猝倒、不省人事乃气血上升、激动脑经之病，属内动之风，风阳陡动则猝然眩晕倾仆。治法当潜阳息风、抑之下降，使气火平而风息。原文力斥苍耳疏散升腾及助酒为害，谓通顶门、达脑、走督脉皆升散外风之法，于此病在禁例，论病是而用药非。", []], "26914": ["其他", "此段为《别录》所载药物主治，述其味甘微温，消胸上痰结、唾中胶漆、心胁痰水、膀胱留饮，及风气湿痹、皮间死肉、通血脉等。全属药性功用记录，未及脉象，故不能据脉论病机，只可视为痰饮湿痹诸证之药治资料。", []], "26915": ["病机", "正义阐发旋覆花轻扬之性而具降逆破结之功：味咸润下软坚，性温宣通散结，故能破结气、除胁下满；惊悸为痰饮凌心，寒热为停痰积饮之气结。其消痰逐水、利大肠、通血脉、治湿痹，皆由轻疏泄化、外通脉络而来，非以破泄为补。", []], "26916": ["病机", "发明强调旋覆花体质轻扬、飞扬疏散，主治当以泄散风寒、疏通脉络为专主，故治风寒喘嗽、寒饮渍肺最是正法。原文辨其飞扬之性本能上升，非止下降，且《本经》谓温、寇氏谓辛，疏散寒邪正其专职；而开结泄水、下气降逆则属沉重下达之义，与轻扬本性不甚符合。", []], "26917": ["病机", "发明论夏枯草苦辛温，苦能泄降、辛能疏化、温能流通，善宣散肝胆火之郁窒，利气血运行，凡凝痰结气、风寒痹著皆其专职。原文辨其夏至自枯、禀纯阳之气，不当有寒凉作用，故主瘰疬、破症散结、脚肿湿痹，皆以宣通泄化见长。", []], "26918": ["其他", "此段为《别录》所载药物主治，述其主男子五劳七伤、女子伤中胞漏下血，利大小肠，去胃中宿食，补五脏内伤不足，通血脉，益气力，利耳目。纯属药性功用记录，未涉脉象，无从据脉析病机，仅可作补虚通血脉之药治资料。", []], "26919": ["病机", "正义论地黄味甘色黄、最合土德，能补养中土，为滋养上品。其主折跌绝筋即补血补伤，主伤中即补阴补血；逐血痹者，因血不足而痹著不行，补养充足则自然流动而痹行。填骨髓、长肌肉、通血脉、益气力、利耳目，皆补益引申之义；作汤则流动活泼，积聚痹著皆除。", []], "26920": ["病机", "原文以「脉洪神旺之时」与「脉象已虚」对举，说明鲜生地大寒直折，仅宜于气火升腾、挟血上逆而脉洪神旺之实火证；若去血已多、火焰已减，脉象已虚，则气营两惫，不可恣用大寒。脉洪为气火有余之征，脉虚为气血耗伤之候，故同一血证，脉洪神旺者宜清降，脉虚者当固摄，不可一概而论。", ["洪", "虚"]], "26921": ["主病", "原文谓「脉洪实者宜之」，洪实为实热内盛之象。海藏以地黄主阴虚五心烦热、肾虚痿厥、足下热痛，而必脉洪实者方宜，说明所治乃阴虚而兼实火之证。洪为热盛，实为邪结，热邪灼阴故烦热足痛，借地黄益肾水、凉心血以清之；若脉不洪实，则非所宜，可见脉象为用药之凭据。", ["洪", "实"]], "26922": ["病机", "本段未出脉名，专论干地黄与鲜地黄功力之别：干者补血益阴，鲜者凉血清火。原文强调「究属寒凉之品，惟虚而有热者为宜」，若「真阴不充，而无热证」，则干地阴柔黏腻，反不利于虚弱之脾胃。其辨在虚而有热与无热之间，虽未言脉，实以证候之寒热虚实为用药准绳，与脉之虚实寒热相参。", []], "26923": ["病机", "原文指出鲜生地止吐血衄血，乃治「气火升腾，血热上涌」，「脉大洪实之时」相火鸱张，故藉大寒清热以减炎炎之势。脉大洪实为实火亢盛之征，火降则气降血平。若「邪焰少衰」即当改弦易辙，不可专恃鲜地。又辨逐血痹、破恶血皆血气旺而痹著自通，非甘寒黏腻能宣通逐瘀，脉证合参之意甚明。", ["大", "洪", "实"]], "26924": ["病机", "本段未出脉名，论大黄气味俱厚、沉降纯阴，直入血分导瘀滞、通利胃肠逐宿垢。原文以「川流不舍昼夜」为喻，说明肠胃以通为补，苟有宿垢留滞则秽浊不去、新血易瘀。其主下瘀血、破症瘕积聚，皆借推陈致新之力，使中气和调、食不碍化。虽未言脉，实示瘀滞内结者当以通为用，与脉之沉实涩滞相应。", []], "26925": ["病机", "本段未出脉名，论连翘味苦清热，形圆中空似心，故专清心家之热；质轻空松，故能开泄宣通、散结泄络脉之热。原文引「诸痛痒疮，皆属于热」，说明瘰疬痈肿疮疡瘿瘤皆热结所致，连翘清热兼散结滞。又辨六朝以降清心通小肠、导小水之说为附会不可信，体现作者审证求因、不盲从旧说之态度。", []], "26926": ["病机", "本段未出脉名，论王不留行通利迅疾、味苦泄降，惟热结者为宜。原文谓其主金疮止血、逐痛刺、止心烦鼻衄、痈疽恶疮，皆清火活血之用；除风痹乃风热壅于经络，风寒寒湿非其所治。又治产难通乳汁、通经滞不调，皆取其流利下行之性。文中对「内寒」二字存疑不强解，示读书当阙疑，用药须辨寒热。", []], "26927": ["病机", "本段未出脉名，论漏芦滑利泄热，寒苦直泄甚于王不留行，故「苟非实热，不可轻用」，不独耗阴，尤损正气。原文谓通小肠、治溺血肠风乳痈、通经脉，皆惟实热之证可以暂用；古治痈疡以漏芦汤为主，服之必泻则热从下出，气虚者非宜，妊妇尤为切禁。全段以实热可暂用、虚者禁之立论，示寒苦攻泄之品须辨虚实。", []], "26928": ["病机", "此段述芍药功用，未及脉象。原文谓其「通顺血脉，缓中，散恶血，逐贼血，去水气」，说明芍药能行血中之滞、散瘀逐水，故所主病机为血脉瘀滞、水气内停，症见痈肿、时行寒热、中恶腹痛、腰痛，皆由血行不畅、水湿不化所致，与脉象无直接对应。", []], "26929": ["病机", "此段辨析赤白芍药功用，未言脉象。白者「益太阴之脾阴，而收涣散之大气」「柔驯肝气之横逆」，故主肝脾阴亏、逆气上扰之病机，症见邪气腹痛、寒热疝瘕；赤者「行滞破血，直达下焦」，主血痹坚积、瘀血阻滞，症见痈肿、中恶腹痛，皆从药性推知病机。", []], "26930": ["病机", "此段引洁古论白芍，未涉脉象。原文谓其「泻肝，安脾肺，收胃气」「和血脉，收阴气，敛逆气」，说明白芍所主为肝气横逆、脾肺失和、阴气耗散之病机，故能止泻利、固腠理，且为下利必用之药，因泻利属太阴病，脾虚气陷、阴气不收为其本。", []], "26931": ["兼症", "此段引海藏论白芍主治，未言脉象。原文列「脾虚中满，心下痞，胁下痛，善噫，肺急胀逆喘咳，目涩，肝血不足，阳维病苦寒热，带脉病苦腹痛满」，皆属肝脾不和、阴血不足、气机郁滞之兼症，说明白芍所主病机为肝阴亏虚、脾运不健、络脉失养。", []], "26932": ["病机", "此段引石顽论白芍，未及脉象。原文谓其「敛津液而护营血，收阴气而散邪热」「能于土中泻木，为血痢必用之药」，说明所主病机为营血耗散、肝木犯土、阴气不敛，故主邪气腹痛、益气，治阳维寒热、带脉腹痛，皆由肝脾血分失调、木郁克土所致。", []], "26933": ["误治", "原文引仲景「太阴为病，脉弱，其人续自便利」，脉弱主胃气虚弱，故当行大黄、芍药者须减之，恐其「动」而伤中。此段主旨为太阴虚证用药禁忌，说明脉弱提示中气不足，芍药虽治太阴气滞腹痛，然虚寒者非一味所能治，属误治警示。", ["弱"]], "26934": ["预后", "原文述香薷治霍乱，然「如果肢厥脉伏，目陷面青，唇舌淡白如纸，则是真寒直中之阴证」，脉伏主阳气衰微、寒邪直中，非香薷轻清所能胜任，须大剂姜附挽救。此段以脉伏辨真寒阴证之危候，说明脉伏在此示阳气欲绝、病势深重之预后。", ["伏"]], "26935": ["预后", "原文谓霍乱「汗出如雨，吐泻脱元，四肢清冷，脉微欲脱者」，脉微欲脱主元气耗散、阳气将竭，故宜大顺散、浆水散救之；若误用香薷「重虚其表，顷刻脱矣」。此段以脉微欲脱判断脱元危候，说明脉微示正气溃败、预后凶险，属死候之辨。", ["微"]], "26936": ["其他", "此段论蓖麻子性味功用，非脉诊内容。原文辨其性清凉、善走善散，能消散外疡红肿焮热，如千捶膏治发颐、瘰疬、乳痈可十消八九，明为消散之功而非提毒外出；又用其走窜入络通痹治偏风不举。全段无脉象描述，故脉象要素为空，主旨属药物功用辨析，归入其他。", []], "26937": ["病机", "原文言霍乱转筋、心腹痛皆寒湿交互、汩没真阳所致，重证则见脉伏色青、大痛吐泻、转筋冷汗，乃寒湿直中三阴、真阳被遏、阳气不能鼓动血脉，故脉伏而色青。菖蒲芳冽能胜寒湿行气定痛，但温中力薄，此类大剂姜附连萸之证非其独当，脉伏正示阳衰寒盛之危。", ["伏"]], "26938": ["其他", "此段引《别录》述药之主治安肠胃、利五脉、调四肢，属药物功效记载，非论脉。文中虽出现利五脉、调四肢之语，乃言药能通利血脉、调和四肢，非脉象要素描述，故脉象取空，主旨归其他。", []], "26939": ["病机", "此段论菊花秉秋令肃降之气，能平肝火、息内风、抑木气横逆。原文指出风头眩乃阴虚阳浮、气火升腾、肝风上扰所致，非外来风邪；头风作痛皆内火内风震撼不息，甚则目如欲脱。全段以药性推病机，无脉象描述，故脉象为空，主旨属病机阐发。", []], "26940": ["病机", "此段述菊花治头目风热、风旋倒地、脑骨疼痛及身上游风。原文谓风旋倒地乃血冲脑经、失其知觉运动，游风为血热生风之病，当苦泄清理而风自息，并斥羌防芎芷疏散之误。全段论药性与病机，未及脉象，故脉象要素为空，归病机。", []], "26941": ["治法", "此段论艾叶纯阳，可回垂绝元阳，灸法大用。止吐血宜生用取其辛开疏经络之壅，然温升之性于上溢之证不合，故四生丸以清肃下降为主而反佐艾叶辛温，同气相求；治下利则取辛温升举，治䘌疮则苦温燥湿杀虫。全段言用药治法，无脉象，脉象为空。", []], "26942": ["病机", "此段引海藏言带脉为病，腰溶溶如坐水中，原文自注为肾气虚寒、浊阴泛溢之病，艾叶温肾且逐水气。腰溶溶如坐水中正是寒湿浊阴下注带脉之象，病机在肾阳不足、水气不化。全段未涉脉象描述，故脉象要素为空，主旨归病机。", []], "26943": ["病机", "此段论细辛辛温阳升，善开结气、宣泄郁滞，上达巅顶通利耳目，旁达百骸。原文辨咳逆为寒饮作咳，头痛脑动为真寒犯脑，即真头痛手足清冷至节、朝发夕死，乃寒水暴溢、汩没微阳，与肝胆阳邪上攻之头痛冰炭殊途；百节拘挛为风寒痹著。全段无脉象，脉象为空，归病机。", []], "26944": ["病机", "原文述润肝燥治督脉为病，脊强反折。未出脉象，然病机在肝燥血虚，督脉失养，故脊强反折。肝主筋，督脉贯脊，精血亏耗则筋脉拘急，此以润肝燥为治，示津血不足、络脉失濡之机。", []], "26945": ["病机", "寿颐按督脉为病由精血大衰、络脉失养致脊强反折，谓肝燥未可厚非，然先天肾阴几于耗竭，大补肝肾真阴恐难速效。细辛之温稍稍引经通阳，若竟以辛润肝肾为此证主药，其弊甚大。此段辨病机在肾阴耗竭、络脉失养，非单纯辛温可解。", []], "26946": ["病机", "原文以脉结滞言中气虚寒、络脉结滞，辛温补虚宣通血气为宜。归尾辛温善行，辅行瘀之品为疏逐恶血主将。又辨中风痓即角弓反张之风痉，古人不知气血冲脑，多主温升驱外风，势必利少害多。脉结滞示气血瘀滞不通，络脉结滞之病机。", ["结"]], "26947": ["病机", "海藏主痿癖、足下热而痛、带脉为病腹痛腰溶溶如坐水中、冲脉为病逆气里急。足下热痛为肾阴亏损、龙火游溢，宜大剂滋填，辛温非主；带脉病为虚寒之人肾水阴寒泛滥，温养为宜；冲脉病虽虚象，气逆上冲非一味温辛可独任。", []], "26948": ["病机", "原文言温煦专长中虚中寒，然木火横逆肝气搘撑为胀为痛则背道而驰。仲景治阳邪陷阴，手足厥寒，脉细欲绝，用当归四逆汤于桂枝汤中加当归、细辛、通草以通血脉。脉细欲绝示阳邪陷阴、血脉不通，故手足厥寒，治以通脉散寒。", ["细"]], "26949": ["病机", "芎䓖味辛气温，升发猛，上达头目透顶巅，旁行肢节贯通脉络。主中风入脑头痛为风寒疠气伤诸阳之会；寒痹筋挛缓急为阴寒袭筋肉血络；妇人血闭无子为虚寒阳和不司；金疮为破伤失血后卫阳不足。皆以温和敷布助宣化。风热肝阳上攻头痛非温升辛散所宜。", []], "26950": ["病机", "海藏谓治督脉为病，脊强而厥，亦阴盛无阳之真寒厥逆也。原文直指阴盛无阳，真寒厥逆，故脊强而厥。督脉总督诸阳，阴寒内盛，阳气式微，不能温煦筋脉，则脊强；阳衰不能达于四末，则厥逆。此脉当见沉微细弱之属。", []], "26951": ["病机", "海藏治冲脉为病逆气里急，谓肾气不摄、冲激逆上为患，必非所宜。丹溪谓木香辛能上升，气郁不达宜之，若阴火冲上则反助火邪，当用黄檗、知母少佐木香。此段辨冲脉逆气里急由肾气不摄、冲激逆上，非升散所宜，阴火冲上者更忌辛温。", []], "26952": ["其他", "原文未出脉名，仅论甄权用此药治产后腹痛、频产血气衰冷成劳瘦羸、妇人沥血腰痛。作者指出其苦温行瘀、温和利血脉，然通利之品能走未必能守，当以意逆之，非虚证久服之药。病机在血气衰冷兼瘀滞，故以温行血脉为治，非脉象所主。", []], "26953": ["兼症", "原文未出脉名，论藿香清芬微温，善理中州湿浊痰涎，醒脾快胃、振动清阳，故治风水肿毒、去恶气、霍乱心腹痛，为暑湿时令要药。然性极和平力缓，仅治霍乱轻证；若猝然大痛、吐泻并作、肢冷脉绝，则非大剂四逆汤不为功，明言脉绝属重证。", []], "26954": ["病机", "原文言霍乱中气大寒暴作，胸腹绞痛、上吐下泻、四肢冰冷、面唇舌淡白如纸、脉伏不见、冷汗如油、大肉陡削，由盛暑乘凉饮冷汩没真阳，致中气暴绝。脉伏不见正因真阳被遏、阳气不能外达，故主中宫真寒重证，须大剂姜附吴萸良姜荜茇挽回垂绝元阳。", ["伏"]], "26955": ["其他", "原文未出脉名，论甘松甘温芳香，助阳和之气、通血脉润泽颜色，为外治面脂之药；又辛香醒胃、入阳明行滞气，治风疳齿蚀；其根繁密长于下行，故理元气、去气郁、开脾郁，治恶气卒心腹痛下气。全在芳香舒郁行滞，非以脉象立论。", []], "26956": ["其他", "原文未出脉名，属兰草、蕙草名实考证，引《本经》《别录》《离骚》《广雅》诸家所述形状，辨兰与蕙、薰草之同异，言其有枝有叶、有茎有节，藏之书中辟蠹，佩之可以已疠。全段为药物名物考订，不涉脉象与病机。", []], "26957": ["其他", "原文未出脉名，论兔丝子柔细坚韧、子多脂，为养阴通络上品；味微辛则阴中有阳、守而能走，与滋阴腻滞者绝异。引缪仲淳辛以润之之说，谓《本经》续绝伤、补不足、益气力、肥健，皆寓宣通百脉、温运阳和之意，久服阴液足而目明、阳气长而身轻。", []], "26958": ["病机", "原文论黄昏阴盛之时虚焰发动而作嗽，即阴火上冲、激肺之嗽，属阴虚火浮，治宜收摄肺肾。然必脉虚、舌红、无痰者乃合；若舌腻有痰，则知所顾忌。脉虚正应阴虚火浮、肺肾不摄之机，故以脉虚舌红无痰为辨证眼目，示人不可妄投。", ["虚"]], "26959": ["其他", "原文未出脉名，述濒湖谓此药通经脉，宜于血热瘀结者；又治骨节风痛，亦惟血热痹著者宜之，即《本经》治风痹、《别录》主踒跌之义。全段以活血行血、血热瘀结为用，未及脉象，故脉象要素为空。", []], "26960": ["病机", "原文论络石功效，未及脉象。其“通经活血”“苦寒泻降”以药测证，示热邪壅滞、经脉不通之病机，主风热死肌、痈肿喉舌肿等热证，与脉之数实相应。", []], "26961": ["病机", "原文述木莲“通脉之捷”“通中有守”，未言脉。其消肿散毒、利水通乳，示水湿瘀滞、络脉不通之机，主痈肿、乳汁不通等，脉当见涩滞或滑实。", []], "26962": ["病机", "原文论栝楼根“润枯燥而通行津液”，未及脉。其治消渴、身热烦满，示燥热耗津、气机枯涩之机，脉当见数而细涩或洪大。", []], "26963": ["病机", "原文谓葛谷“升脾胃陷下之气”，未言脉。其治久利、滞下，示中气下陷之机，脉当见虚软或沉弱。", []], "26964": ["误治", "原文载葛粉“升提气火”致神瞀脉坏，未明脉象。误用升散，助热伤阴，脉坏示胃气败绝，主热病误治之危候。", []], "26965": ["主病", "原文“血脉关结”指血行瘀滞、关窍结塞，脉结主气血瘀阻，与通草“通利九窍”相应，主湿热瘀结之证。", ["结"]], "26966": ["病机", "原文“血脉关结”指血热积瘀、关闭结塞，脉结主瘀热互结，与木通苦泄通利相应，主湿热蕴结、九窍不利。", ["结"]], "26967": ["治法", "原文论通乳“行血之中，隐寓养阴”，未及脉。其示乳汁不通多因血液不充、络脉不利，脉当见细弱，治宜养血通络。", []], "26968": ["病机", "原文论萆薢药性，未及脉象。其“性能流通脉络而利筋骨”“清热理湿”针对肾有湿热、浊气不去之腰背痛，病机为湿热浊邪阻滞下焦，气血不畅，故痛；非肾虚无湿之痛。湿浊去则正气自强，非补益之力。", []], "26969": ["病机", "原文论附子辛温走窜，为温经逐寒、宣通气血之利器，未涉脉象。所主“风寒咳逆邪气”乃寒邪作咳，病机为寒邪外袭、肺气失宣；六淫皆属外感邪气，非人身正气，故以邪气名之。", []], "26970": ["病机", "脉微欲绝见于“群阴用事，汩没真阳”之暴病，肢冷肤清、上吐下泻、澄澈清冷，乃真阳衰微、阴寒内盛、阳气欲脱之危候。附子辛温大热，通行十二经，生用能破阴回阳，故非生用不为功。", ["微"]], "26971": ["其他", "原文仅引王海藏“附子治督脉为病，脊强反折”之说，未及脉象。此为纠谬之引子，下文将辨痉病非皆寒邪。本条主旨为引述旧说，故归其他。", []], "26972": ["病机", "原文列脉细无神、脉沉、脉沉细等，属痉病脉象举例。寿颐按语指出猝暴发痉、腰背反张多由“气火上冲，震动脑神经”，内热生风，木火上恣，非寒邪；脉沉细无神反映正气内虚或热郁于里，故治宜清热抑降、潜镇重坠。", ["细", "沉"]], "26973": ["误治", "脉沉见于“热传三阴”而厥，乃“厥深热深”之阳厥，先发热多日而后厥，大便闭，热伏于里。若误认寒厥而用附子，则“不旋踵而变”，故本条列禁忌，强调脉沉须辨热深厥深，不可妄投温燥。", ["沉"]], "26974": ["病机", "脉沉微欲绝见于“直中真寒证”，一起即四体厥冷、唇舌淡白无华，为寒厥，非四逆、姜、附不为功。若先发热后厥者，热闭于里，外反无阳，脉亦可沉微，但属热深厥深，误投四逆则顷刻变生，故须辨寒热真假。", ["沉", "微"]], "26975": ["病机", "原文论乌头为附子之母，体质空松，能散外邪，主温经散寒、祛除外风外寒，治风痹血痹、半身不遂、寒湿行经等。其病机为外寒风湿痹阻经络，气血不通；乌头性散，故为向导，非脉象所主。", []], "26976": ["病机", "原文以半夏辛泄滑降立论，谓心下坚满、咽喉肿痛、头眩咳逆皆'气逆上冲，多升少降使然'，滑而善降故主之；止汗因'气火上逆'，非肌腠空疏之虚汗。全段未及脉象，所论为药性升降与病机逆上，故脉象要素为空。", []], "26977": ["病机", "甘遂苦寒攻水破血，主腹满浮肿、留饮、症坚积聚，所主疝瘕'以湿热壅结者言之'，寒气凝滞非其所宜；又申'热气肿满'，明泄水肿皆湿热实证，脾肾虚寒误用为鸩毒。段中未出脉名，所辨在湿热壅结与虚寒之病机。", []], "26978": ["病机", "甄权谓治心腹胀满、去水气、涕唾如胶，皆以'湿痰浊垢'言之，故通利血脉、治恶疮风痹湿；又治毒风四肢挛急不能行步，乃'水湿之邪，痹其络脉关节'。全段无脉象，所论为湿痰水气痹阻络脉之病机。", []], "26979": ["病机", "寿颐谓此药治疟，惟'岚瘴湿热毒疠之气，吸入口鼻，浸淫络脉'，因而往来寒热，泄导秽浊使从二便去；外虚实诸疟皆非其治。段中未及脉象，所辨为瘴毒湿热浸淫络脉之病机，非泛论疟疾。", []], "26980": ["病机", "浮萍体轻而浮，故开肌腠；主暴热身痒为清凉解肌，下水气、解酒酲因'开毛窍而宣肺气'，溺道上流从回血管入肺通汗腺而后归肾；长须发因毛窍通利血脉荣养，止消渴为清热利水胃火自平。无脉象，论药性宣肺利水之机。", []], "26981": ["病机", "骨碎补性温而通，入血和血、通调脉络，入肝肾温养下元，能引升浮之热藏于下焦，故治'上热下冷'；治骨槽风因寒痰凝滞、牙关不利。段中未出脉象，所论为温养下元、引火归藏及寒痰凝滞之病机。", []], "26982": ["其他", "此段述《药性论》作者甄权生平仕历及著《脉经》《明堂人形图》各一卷，属本草书目与人物考据，未涉脉象与病机，故脉象要素为空，主旨归入其他。", []], "26983": ["其他", "此段述李杲《用药法象》一卷及《辨惑论》《脾胃论》《医学发明》《兰室秘藏》等著作，辨内伤外感、元气阴火、饮食劳倦、有余不足，辨析经络脉法。属书目与学术源流考据，未出具体脉象，故归其他。", []], "26984": ["其他", "原文未识别出脉名，仅标为王叔和《脉经》段落，无具体脉象描述，故无法分析所主病机。", []], "26985": ["其他", "原文未识别出脉名，仅标为戴起宗《脉诀刊误》段落，无具体脉象描述，故无法分析所主病机。", []], "26986": ["其他", "原文为李时珍论述本草分类沿革，未涉及脉象，故无病机可析。", []], "26987": ["其他", "原文为元素论药根梢升降及取象，未涉及脉象，故无病机可析。", []], "26988": ["主病", "原文载“其脉动中有止，时自还，乃结脉也”，结脉主阴寒内盛、气血凝滞。患者中气本弱，伤寒热甚，误下冷伤脾胃，致四肢逆冷、昏愦、心下悸动、吃噫不止、面色青黄，脉证相合，故用复脉汤加参、桂扶正。", ["结"]], "26989": ["病机", "原文“血脉未乱”指脉象平和未乱，为病机未深之征。强调疗病先察源候病机，五脏未虚、六腑未竭、血脉未乱、精神未散者，服药必活，说明脉未乱提示正气尚存，病可治。", []], "26990": ["其他", "原文强调明医听声、察色、诊脉以知未病，未涉及具体脉象，故无病机可析。", []], "26991": ["其他", "原文论病有六失八要，强调四诊合参，若脉病不相应则难治，未出具体脉象，故无病机可析。", []], "26992": ["治法", "此段专论药性气味厚薄、性用躁静及治则，如“用热远热，用寒远寒”“木郁达之，火郁发之”等，强调因势利导、以偏纠偏。虽未言脉，然“气之胜也，微者随之，甚者制之”暗含凭脉辨气之胜复，以定抑举折补，故归治法。", []], "26993": ["其他", "弘景述药之所主但举病名，而病变形状不可一概，须“配证以合药”；又评张仲景“善诊脉、明气候以意消息之”，指出诊脉须参合气候以消息病机。全段重在药证相应与脉证合参，非专论脉象主病，故归其他。", []], "26994": ["病机", "此段论“形乐志苦”者衣食足而外实、思虑多而内虚，故“病生于脉”，与贫下异；又言少壮老气血盛壮衰三等，“少火生气，壮火散气”。虽未出脉象，然“病生于脉”点明脉象反映形志苦乐、气血盛衰之病机，治当因人分等。", []], "26995": ["其他", "此案疟月余，误吐下致气弱，辨为夏伤暑、秋伤风，先与柴胡汤安；后饮食不节，寒热复作、吐逆不食、胁下急痛，名痰疟，以十枣汤下痰水，理中散收功。全段叙脉病相参、因证施治，未明脉象，故归其他。", []], "26996": ["预后", "妇人吐逆、二便不通、烦乱肢冷，“渐无脉”一日半，此关格危候，脉绝示阴阳将离、胃气衰败，故“极难治”。与大承气汤通腑，便通而“脉渐生”，脉复为生机之兆。全段以脉之有无判预后，紧扣“渐无脉”“脉渐生”。", []], "26997": ["病机", "风痰头痛、颤掉吐逆，误温误下后厥逆、谵言、循衣摸床、手足冷而“脉伏”。脉伏非虚寒，乃胃中结热，阳气不能布于外、阴气不持于内，热深厥深，故脉沉伏不出。与大承气汤下结热，一剂乃愈，正合“脉伏”主热结于里之病机。", ["伏"]], "26998": ["病机", "妇人病温十二日，“脉六七至而涩，寸稍大，尺稍小”，数主热，涩主血滞，寸大尺小示热入血室、少阳枢机不利；经水适行，发寒热、颊赤口干耳聋，故断为少阳热入血室。后脐下急痛、燥屎内结，脉证相参，层层转治，皆以脉为凭。", ["数", "涩", "大", "小"]], "26999": ["病机", "年五十四，素羸多中寒，脉“左上二部、右下二部弦紧有力”。弦紧主寒主痛，左寸关候心肝、右尺候肾，弦紧有力示寒邪凝滞、筋脉拘急，故右手足筋急拘挛、言语稍迟。治以小续命汤加减温通，去寒凉之芩芍，加薏苡仁治筋急，遂安。", ["弦", "紧"]], "27000": ["治法", "原文论复方，非论脉。所谓「伤寒见风脉，伤风得寒脉，为脉证不相应」，指脉与证不符，故以复方治之。脉证不应是辨证难点，复方即数方相合或本方加药，以兼顾错杂之证，属治法范畴，非主病脉象。", []], "27001": ["平脉", "原文「脉软则和，故咸可以养脉」，以脉软为和顺之象，属平脉。软即柔和，与咸味软坚相配，说明脉贵柔和，不贵刚劲。此段借五味养形论脉之常，非言病脉，故列平脉。", ["软"]], "27002": ["病机", "原文「味过于咸……脉凝涩而变色」，咸味太过伤血，血行不畅则脉凝涩，涩主血滞。此段论五味偏胜致病，脉涩为咸伤血脉之征，与短肌、心气抑并见，属病机分析。", ["涩"]], "27003": ["治法", "原文「脉浮在表，汗之；脉沉在里，下之」，以浮沉辨表里，定汗下之法。浮主邪在表，沉主邪在里，故破伤中风依脉之浮沉分治。此段主旨为凭脉施治，属治法。", ["浮", "沉"]], "27004": ["病机", "原文「惟脉脱下虚、无邪无积之人，始可议补尔」，脉脱而虚示正气虚衰，且无邪积，方可言补。虚脉主正虚，若有邪而补则实实之误。此段以脉虚为可补之据，论虚实攻补之理，属病机。", ["虚"]], "27005": ["其他", "此段为风热湿热药类汇编，列举甘草、黄芩、黄连等治风热湿热之品，未涉脉象。原文「利九窍百脉」「平肝胆三焦包络相火」皆言药效，非论脉，故脉象要素为空，归其他。", []], "27006": ["其他", "此段为血滞风病用药汇编，如当归、芎䓖「破恶血，养新血」，丹参「破宿血，生新血」，皆言药治血滞，未及脉象。原文「治风在骨节间」「理血中之气」均属药效，故无脉象可录，归其他。", []], "27007": ["病机", "原文论痓病属太阳、督脉二经，证见发热口噤、身体强直、角弓反张，分柔痓、刚痓，并及破伤风湿发痉。此段述痉病证候与分类，未出脉象，主旨为病机与证候辨识，故归病机。", []], "27008": ["主病", "本段列麻黄、桂枝、羌活、荆芥、防风、天南星等，皆主风寒风湿所致痉证，如金疮中风、产后口噤、角弓反张、牙关紧急。原文未出脉，所述病机为风寒湿邪外袭，壅滞经络，筋脉失养而拘急成痉，故以祛风散寒除湿为治，非据脉断证。", []], "27009": ["病机", "原文言伤寒厥逆发躁而脉沉，夹阴伤寒小腹痛、呕吐厥逆而脉伏。脉沉主里、脉伏主邪闭阳郁，说明阴寒内盛、阳气不能外达，故见厥逆躁烦；用参、姜、附温阳破阴，使脉复即苏，正合脉伏为阳回之验。", ["沉", "伏"]], "27010": ["治法", "本段以甘草、黄耆、人参、麦门冬、五味子等组方，主泻阴火、补元气、除肌热躁热，标举甘温除大热之法。原文未出脉，所论为虚热内扰、元气不足之病机，故以益气泻火、清金滋水为治，非凭脉象立论。", []], "27011": ["兼症", "原文载当归治血虚发热、困渴引饮、目赤面红、日夜不退，脉洪如白虎证者。脉洪本主热盛，然此属血虚阳浮之假热，与白虎实热不同，故以当归配黄耆养血益气，使浮阳归位，说明脉洪须结合症候辨虚实。", ["洪"]], "27012": ["病机", "本段列香附、苍术、抚芎、木香等，总解一切气郁，行十二经气分。原文未出脉，所论为气机郁滞、升降失司之病机，故见心腹膀胱连胁下气妨、常日忧愁，治以行气解郁、有补有泻、有升有降，非据脉象而言。", []], "27013": ["病机", "原文释呃为气自脐下冲上、作呃呃声，断为冲脉之病，并辨其有寒有热、有虚有实，又纠正朱肱、王履以哕、咳嗽为咳逆之误。全段未出脉，主旨在于阐明呃逆属冲脉气逆上冲的病机，须分寒热虚实论治。", []], "27014": ["主病", "原文列人参、黄耆、升麻、柴胡等主虚泄风泄、阳气下陷作泄，又载五味子治五更肾泄。脉微主阳气虚衰，说明中气不足、清阳下陷，故见泄泻；治以补中升阳、温肾固肠，脉微正为虚寒泄泻之凭据。", ["微"]], "27015": ["主病", "本段列甘草、芍药、人参、当归、白术、附子等治久痢、冷痢、噤口痢、休息痢，主补脾散血、温阳止痢。原文未出脉，所论为虚寒久痢、脾胃阳衰、气血两伤之病机，故见腹痛后重、厥逆，治以温补固涩，非据脉断证。", []], "27016": ["病机", "原文以“湿热”立题，脉数示热邪内扰。所列黄连、黄芩去中焦湿热，大黄主肠结热，牵牛除气分湿热、三焦壅结，皆因湿热壅滞、气机不畅而致胀满、小便不利、足胫微肿。脉数为热，湿热相合则脉数而兼濡，故治以清热利湿、宣畅气血，使湿去热清则胀满自消。", ["数"]], "27017": ["病机", "原文辨水肿脉浮与脉沉：脉浮者属风，风水相搏，一身面目浮肿、小便不利，故用麻黄、甘草取汗开鬼门；脉沉者属水，虚肿者为气，皆非水也，以麻黄、甘草、附子温阳化气。浮沉二脉分判风与水、气之异，浮为邪在表，沉为病在里，故治法有发汗与温化之别。", ["浮", "沉"]], "27018": ["其他", "本段为霍乱转筋的内治方药汇录，未出脉象。所列木瓜利筋脉、主转筋筋挛，吴茱萸炒煎酒服得利安，松节、桂、沉香皆治转筋挛急，说明转筋由寒湿霍乱、筋脉失养所致。因原文纯为方药主治，无脉可辨，故脉象要素从缺，主旨归为其他。", []], "27019": ["其他", "本段为精虚证的内治药物汇编，未载脉象。肉苁蓉、锁阳、菟丝子、覆盆子等皆主五劳七伤、益精补阳、强阴益髓，石钟乳、阳起石、磁石并补益精气。精虚则五劳七伤诸症丛生，故以填精补髓为治。原文无脉象描述，脉素从缺，主旨属其他。", []], "27020": ["病机", "原文指出“即肌衄，又名脉溢，血自毛孔出”，并明言“心主血，又主汗，极虚有火也”。血从毛孔外溢，因心之极虚而虚火妄动，迫血离经从汗孔而出，故称脉溢。此段以病机立论，说明肌衄之因在虚火，非实热迫血，脉象原文未及，故脉素从缺。", []], "27021": ["病机", "本段承肌衄、脉溢而列内治诸药。人参治气散血虚、红汗污衣，葎草治产妇大喜汗出赤色，生姜汁治毛窍节次血出、皮胀如鼓名脉溢，黄犊脐中屎治暴怒所致九窍四肢血出。可见血汗由气虚不摄、大喜气散或暴怒动血所致，原文未出脉象，脉素从缺。", []], "27022": ["病机", "本段以“痰热”立题论健忘。黄连降心火令人不忘，麦门冬、牡丹皮、柴胡、木通通利诸经脉壅及寒热之气令人不忘，商陆花治心昏塞多忘，牛黄除痰热健忘。说明健忘由痰热蒙蔽心窍、经脉壅滞所致，故治以清化痰热、通利心脉。原文未载脉象，脉素从缺。", []], "27023": ["病机", "原文列清镇安神诸药，甘草条明言“伤寒心悸脉代，煎服”。脉代主心气不足、脉行断续，故见惊悸、恍惚健忘、妄言妄见，皆神不守舍之候。黄连泻心肝火，麦冬、远志、丹参定心安魂魄，天南星治心胆被惊、神不守舍。脉代示心气虚弱，治以清镇安神、补益心气。", ["代"]], "27024": ["病机", "原文附子条下明言「转脬虚闭，两脉沉伏」。转脬即膀胱气化不行、小便不通，沉伏之脉示阳气虚陷、气机闭阻于下，故以盐水浸炮附子温肾助阳、同泽泻通利小便。沉伏非实邪壅盛，乃虚闭之象，与「虚闭」二字相应，主小便不通之病机。", ["沉", "伏"]], "27025": ["治法", "本段列人参、黄耆、熟地黄、肉苁蓉、锁阳等「虚弱」门药物，主益肺肾元气、滋肾水益真阴、壮阳益精。原文未出脉名，然所治为元气虚弱、阴精亏乏之证，故以补虚为法，与「益肺肾元气」「益精强志」诸语相合，属虚损调补之治法。", []], "27026": ["治法", "本段「虚损」门收补骨脂、附子、狗脊、牛膝、肉苁蓉等，主骨髓伤败、肾虚腰痛、带脉为病腰溶溶如坐水中。原文未标脉象，所述皆下焦阳虚、肾精亏虚之候，故以温补下焦、补肾益精为治，属虚损腰痛之治法。", []], "27027": ["病机", "原文乌头条明言「寒疝厥逆，脉弦紧」。弦主痛、主寒，紧主寒邪收引，寒凝厥阴、气机拘急，故脉见弦紧，症见寒疝厥逆、少腹冷痛。以乌头煎水入蜜服，取温散沉寒、缓急止痛之意，脉症相合，主寒疝之病机。", ["弦", "紧"]], "27028": ["治法", "本段「风寒风湿」门列麻黄、羌活、防风、苍术等，主风寒风湿痹痛、一身尽痛、周身骨节尽痛。原文未出脉名，所述为风湿相搏、痹阻经络之证，故以发汗散风、除湿通痹为法，与「非此不除」「治风去湿仙药」诸语相应，属痹证治法。", []], "27029": ["治法", "本段「赤肿」门收黄连、黄芩、龙胆、芍药等，主目赤肿痛、出泪羞明、赤肿瘀肉高起。原文未标脉象，所述为肝胆心火上炎、风热壅目之候，故以泻火消肿、清肝明目为治，与「泻肝胆心火」「除肝胆邪热」相合，属目赤肿之治法。", []], "27030": ["治法", "本段「昏盲」门列人参、黄精、苍术、玄参、地黄等，主益气明目、补肝明目、补肾明目，治目䀮䀮无所见、青盲雀目、内虚目暗。原文未出脉名，所述为气血阴精亏虚、目失所养之候，故以补益为法，属昏盲之治法。", []], "27031": ["治法", "本段「翳膜」门收白菊花、谷精草、淫羊藿、黄芩等，主病后生翳、痘后目障、疳眼生翳、肝热生翳。原文未标脉象，所述为热邪或痘毒上攻、目生翳膜之候，故以退翳明目、清肝解毒为治，与「去翳」「肝热生翳」相应，属翳膜之治法。", []], "27032": ["治法", "本段为香附、当归等药的主治配伍，未涉脉象。原文以香附为“气病之总司，为女科之仙药”，随炮制与配伍不同而分走气血、解郁降火、消胀化食，说明气滞血瘀、郁结胀满诸证当以调气行血为治，非凭脉断病，故无脉象要素可录。", []], "27033": ["兼症", "本段列苍术、艾叶、白芷、韭子等治带下之药，原段仅标“脉数”而未申明所主。带下赤白、白淫、漏下多因湿热下注或冲任虚损，脉数常示热象，故以燥湿清热、固涩止带之品应之；然原文重在方药兼症，脉数只是兼见之象，不可径断为专主某病。", ["数"]], "27034": ["妇人", "本段为安胎诸药，标“脉虚”。胎动不安、腹痛下血多因气血亏虚、冲任不固，脉虚正合其候，故用黄芩、白术清热健脾以安胎，续断、杜仲固肾防堕，砂仁行气止痛。原文“三月孕，防胎堕”“胎气伤动，痛不可忍”皆承虚脉而设，示胎前以固摄气血为要。", ["虚"]], "27035": ["其他", "本段专集下乳汁之品，如母猪蹄、通草、贝母、栝蒌根等，通篇未及脉象。乳汁不下多由气血不足或乳络壅滞，故取血肉有情之品补益，佐通草、丝瓜之类通络下乳。原文属方药汇录，无脉可辨，故脉象要素为空。", []], "27036": ["小儿", "本段列黄耆、人参、桔梗治小儿阴证，原文“补脉泻心”“胃虚而成慢惊”，指明慢惊由脾胃虚而生风，故以参、耆、甘草益土平木、泻火补金。虽未出脉名，然“补脉”之意在于脉虚当补，示小儿胃虚慢惊之机，非以脉象立论。", []], "27037": ["其他", "本段为李时珍论水之总叙，以坎象言水，辨九州水土与人之美恶寿夭，提出“饮食者，人之命脉也，而营卫赖之”“水去则营竭，谷去则卫亡”。此以水谷喻营卫根本，非论脉象，故无脉可录，主旨属药食水类之总纲。", []], "27038": ["其他", "本段集解井水，辨井华水之功与井水优劣，强调远从地脉来者为上、近沟渠污水者成碱须澄。原文“疗病利人”“不堪入药、食、茶、酒”皆论水质选用，未涉脉诊，故脉象要素为空，主旨归入其他。", []], "27039": ["其他", "本段以井泉地脉喻人之经血，谓“须取其土厚水深，源远而质洁者”，又引《淮南子》土地类生人之说，论山川水土与禀赋寿夭相关。原文重在人与地气流通之理，非切脉断病，故无脉象可录，主旨属其他。", []], "27040": ["病机", "原文言“心下痞，按之濡，关上脉浮”，脉浮主邪热痞塞于上焦，按之濡说明无形邪热结聚，非实滞。关上候中焦，浮为阳热之象，故用大黄黄连泻心汤以麻沸汤煎，取气薄泄虚热。此脉浮与心下痞、按之濡相应，揭示热痞病机。", ["浮"]], "27041": ["其他", "原文“水中有赤脉，不可断之。井水沸溢，不可饮”，此非论脉，乃指水中赤色脉络及井水异常沸腾之象，属禁忌范畴。未涉及具体脉象，故脉象要素为空。所述为水源异常不可断、不可饮，与病机无关，属其他类。", []], "27042": ["治法", "原文详述灸艾火的选择，强调宜用阳燧、火珠取太阳真火，或钻槐取火，忌用金石之火及八木之火，因“金石之火，烈于草木之火”，且各木火伤及不同脏腑。此段论灸法用火之宜忌，属治法范畴，未涉及脉象，故脉象要素为空。", []], "27043": ["治法", "原文主治小儿惊风、昏迷、搐搦、窜视，以及头风胀痛、外痔肿痛等，用灯心蘸麻油点灯淬之，取其“油能去风解毒，火能通经”。又治小儿初生冒寒欲绝，用灯炷燎脐下。此段论灯火灸治法，未涉及脉象，故脉象要素为空。", []], "27044": ["病机", "原文“土气久触，令人面黄。掘土犯地脉，令人上气身肿。掘土犯神杀，令人生肿毒”，论述触犯土气、地脉、神杀所致病证，面黄、上气身肿、肿毒等，属病机范畴。未涉及脉象，故脉象要素为空。", []], "27045": ["主病", "原文“赤白带下，日久黄瘁，六脉微涩”，脉微主气血亏虚，涩主血行滞涩，带下日久耗伤气血，故脉见微涩，伴面色黄瘁。此脉象揭示冲任虚损、湿浊下注之病机，主赤白带下日久虚损之证，与黄瘁相应。", ["微", "涩"]], "27046": ["主病", "原文“尸厥不醒，脉动如故”，尸厥为突然昏倒、不省人事，脉动如故说明气血未绝，生机尚存，故可治。脉动如常，与尸厥之昏不知人形成对比，揭示气机一时闭阻而脉未败绝之病机，主尸厥可救之候。", ["动"]], "27047": ["其他", "原文主治贼风反折，用熬热投酒服，又治腋臭以醋和袋盛，先刺腋下脉去血，封之。还说明目、治风眼、接骨焊齿、疗女人血气及心痛。此段论药物主治及刺脉放血治法，未涉及具体脉象，故脉象要素为空。", []], "27048": ["其他", "本段为自然铜的产地、性状与鉴别记载，'中含铜脉'指矿石中铜质纹理，非诊脉之脉象。全文无病机、主病内容，属金石药物考据，故脉象要素为空，主旨归入其他，不可误作脉诊条文。", []], "27049": ["其他", "本段述铅矿开采及铅之种类鉴别，'随矿脉上下曲折斫取之'之'矿脉'指矿层走向，非人身脉象。文中'皮肤痿黄，腹胀不能食'系铅气中毒之候，非凭脉所断，故不取脉象，主旨属药物考据。", []], "27050": ["主病", "'时气温病，头痛壮热脉大'，温邪外袭，阳气奋起抗邪，故脉大；邪正交争于表，故头痛壮热。脉大在此为邪盛之应，始得一日邪尚在表，故以煮汁服之。此段以脉大标识时气温病初起之病机与主病。", ["大"]], "27051": ["病机", "原文'巨阳、少阳不动而动大疾'，言二经之动脉本不当动，今动而大疾，是阳气怫郁、相火挟阴火上冲，故善怒如狂，病名阳缺。动大疾示阳亢火盛之机，夺食以断胃火，生铁落金制木，木平火降，故曰下气疾。", ["动", "大", "疾"]], "27052": ["妇人", "本段论转女为男之法，'怀妊三月，血脉未流'指胎元初结、血脉未充盛，非脉象描述。全篇以气类相感解释胎化，属妊娠调摄之说，故脉象要素为空，主旨归妇人门，不涉具体脉诊。", []], "27053": ["治法", "本段列药物主治，'利血脉''疗妇人带下十二病''治血块'皆言药效所达，非脉象。其益气柔筋、安魂魄、利血脉之功，示该药调气血、通血脉以疗诸病，属主治治法范畴，故脉象为空。", []], "27054": ["其他", "本段述纪朋观色知病、不待诊脉，及云母汤治验。'不待诊脉'明言未凭脉断病，病由饱食努力、顿仆致气机逆乱而笑歌啼号、足不能履。全文属医案杂录，无脉象可录，主旨归其他。", []], "27055": ["治法", "本段为服白石英之法，'经脉通达，腰肾坚强'言药力温养致气血通畅之效，非脉象描述。'石常在小腹内温暖，则气息调和'示温阳通脉之治法机理，属服食调养门，故脉象要素为空，主旨归治法。", []], "27056": ["其他", "本段为丹砂产地与品质鉴别，未涉及脉象。文中“色紫不染纸者，为旧坑砂，为上品”等语，皆论药材形色，与病机无关。", []], "27057": ["其他", "本段列丹砂主治功效，如“养精神，安魂魄，益气明目”，属药性论述，未及脉象与病机。", []], "27058": ["误治", "本段载服丹砂致疽案例，疡医老祝“诊脉曰：此乃极阴证”，强调“辨其阴阳脉证，不以先入为主”，指出误认热毒而妄用解毒之误，属误治讨论。", []], "27059": ["主病", "原文“头痛壮热脉盛”，脉盛为邪气盛实之象，主伤寒时气温疫初起，邪正交争，故见头痛壮热，治以真丹发汗。", ["盛"]], "27060": ["病机", "本段述灵砂主治“上盛下虚，痰涎壅盛，头旋吐逆”，其病机为阴阳升降失常、水火不济，故以镇坠之品“升降阴阳，既济水火”。", []], "27061": ["病机", "原文“九窍出血，因暴惊而得，其脉虚者”，脉虚主正气不足，惊则气乱，气不摄血，故九窍出血；不可错认血得热则流而妄用凉药。", ["虚"]], "27062": ["主病", "原文“伤寒阴盛自汗，唇青脉沉”，脉沉主阴寒内盛，阳气衰微，故见唇青、自汗、四肢厥冷等症，属阴盛阳衰之病机。", ["沉"]], "27063": ["其他", "本段考辨石膏与方解石、理石等药材形色，如“破之皆作方棱者，为方解石”，属药材鉴别，未涉脉象病机。", []], "27064": ["治法", "原文以“脉数不退者，宜用之”点出石膏主治。脉数主热盛，热邪不退则身热、目痛、鼻干、不得卧等阳明经证随之。石膏辛寒，入阳明清肺气，故脉数属热盛者宜；然“胃弱者不可用”，提示脉数而胃气弱者当慎，免寒凉伤中。", ["数"]], "27065": ["其他", "此段辨石膏真伪，以“石脉”喻石夹两石间如脉理，非诊脉之脉。原文述皮黄赤、肉白、斜理纹，与寒水石、礜石相混，市人刮皮代售。全段无脉象主病内容，故脉象要素为空，主旨属药材鉴别之其他类。", []], "27066": ["主病", "此段列主治，言身热、胃中结气、四肢寒厥、利小便、通血脉、明目去翳、下三虫、杀蛊毒，久服不饥；又止消渴、下气、除胁肋肺间邪气。全段未及脉象，所述为药治热结、虫毒、消渴等病，故归主病，脉象要素从缺。", []], "27067": ["主病", "原文仅列主治：胸中留热结气、黄疸、通血脉、去蛊毒。所言“结气”“留热”为病机所在，黄疸因湿热郁结，蛊毒属虫毒内结。段中无脉象描述，故脉象要素为空，主旨为药所主之病，归主病类。", []], "27068": ["妇人", "段首言“妇人产后损液，血虚阴虚热甚，催生下乳”，又治吹乳乳痈、牙疮齿疳，后述白滑石配粉甘草养脾肾、通九窍六腑、去留结、益精气。全段以妇人产后及乳病为主，兼及通利补益，未涉脉象，故归妇人，脉象要素从缺。", []], "27069": ["其他", "此段引范成大《桂海志》述钟乳石生成形态：石脉涌起处有乳床，白如玉雪，下垂如冰柱，滴沥凝结，以竹管仰承取精者。文中“石脉”指石中纹理，非诊脉，全段为药材产地形态之记述，故归其他，脉象要素为空。", []], "27070": ["病机", "时珍论石钟乳为阳明经气分药，其气慓疾，令阳气暴充；昧者恃此纵欲，致精气暗损、石气独存、孤阳愈炽，久则营卫不从，发为淋渴、变为痈疽。原文以“阳明气衰”与“孤阳愈炽”对举，说明误用石药耗精助火之病机，故归病机。", []], "27071": ["病机", "原文明言“气少血衰，脉涩不行，故乳少也”。脉涩主血少气滞、运行不畅，乳汁由气血所化，气血衰少则脉道涩滞，乳汁因而不通。以钟乳粉配漏芦汤或通草末调服，正取补气养血、通脉下乳之意，脉涩在此为气血衰少之征。", ["涩"]], "27072": ["其他", "此段述石油产地、性状与用途，全无脉诊内容。原文“肥如肉汁”“黑色颇似淳漆”等皆言石漆、猛火油之形色，非论脉象，故不能附会病机。归为其他，示本条属本草异物考据，与脉学无关。", []], "27073": ["其他", "此段罗列药物主治，如“鬼疰贼风蛊毒”“女子赤沃漏下”“安胎健脾”等，未涉脉象。所主病机为邪毒内侵、血瘀血热、胎动不安及下焦不固，然原文无脉象描述，不能以脉推病，故脉象要素为空。", []], "27074": ["其他", "原文述药物“明目，利九窍，通血脉，养精神，益肝气”，主青盲耳聋等症，属补益肝气、通利血脉之主治。全段无脉象记载，病机为肝气不足、血脉不利、九窍失养，然无脉可凭，脉象要素从缺。", []], "27075": ["治法", "时珍引“痰在上宜吐之，在下宜利之”，强调“观人之虚实强弱而察其脉，乃可投之”，此段主旨为吐利治法须察脉辨虚实。原文虽提“察其脉”，但未出具体脉象，故脉象要素为空，病机重在虚实强弱之辨。", []], "27076": ["其他", "此段考石胆产地、形色与伪制，如“击之纵横解皆成叠纹”“块大色浅，浑浑无脉理”，其中“脉理”指石之纹理，非人身脉象。全段属本草鉴别，与脉诊无关，故脉象要素为空，归其他。", []], "27077": ["其他", "原文述白沙主治“石淋”“绞肠痧痛”“风湿顽痹不仁，筋骨挛缩，冷风瘫痪，血脉断绝”，并载热砂外敷取汗法。病机为湿热砂石阻络、寒湿痹阻、血脉不通，然段中无脉象，脉象要素从缺。", []], "27078": ["其他", "此段述海盐、井盐、池盐、碱盐、崖盐五种食盐之产地与制法，末言“亦忌浊水淤淀盐脉也”，此处“盐脉”指盐池卤水脉络，非人身脉象。全段属本草产地考，与脉学无关，脉象要素为空。", []], "27079": ["病机", "时珍引“咸走血，血病无多食咸，多食则脉凝泣而变色”，又言喘嗽水肿消渴“盐为大忌”，或“泣血脉，或助水邪”。咸味过食致血脉凝涩，故取涩脉应之；其病机为咸助水邪、血行凝泣，主喘嗽水肿消渴等症，与“脉凝泣”相应。", ["涩"]], "27080": ["主病", "脉沉细而疾，沉主里、细主虚、疾主热，合观为阴寒内盛、虚阳外越之象。原文列指甲面色青黑、心下胀满结硬、四肢逆冷，皆阴寒固结；而烦渴、虚汗不止、时狂言，乃阴盛格阳、虚火上浮。脉证合参，属阴证伤寒，故宜佐他药温阳破阴，非单纯清热可解。", ["沉", "细", "疾"]], "27081": ["其他", "本段为玄精石治目生赤脉及重舌涎出的方药记载，未言脉象。目赤脉、重舌皆属火热上攻，故用玄精石咸寒清热、牛黄朱砂龙脑开窍消肿，佐铍针去血以泄热。全段主旨为方药主治与用法，不涉脉诊，故脉象要素为空。", []], "27082": ["其他", "本段述药物主治，谓其能治五脏积聚、久热胃闭、破留血、通经脉、利大小便及月水，兼下瘰疬黄疸、散恶血、堕胎。全段为药性功用记录，未及脉象，主旨属方药主治范畴，故归其他，脉象要素从缺。", []], "27083": ["其他", "本段言药疗五脏十二经脉中百二十疾，治暴伤寒、腹中大热、烦满消渴，兼破积散坚、治腹胀破血、下瘰疬、喉闭、霍乱吐利诸症。虽首句提及经脉百二十疾，然通篇为药物主治罗列，未出脉象，故脉象要素为空，主旨归其他。", []], "27084": ["病机", "本段为李时珍辨析硝石与朴硝药性异同。朴硝属水味咸气寒，性下走，故荡涤肠胃积滞、折三焦邪火；硝石属火味辛带苦微咸气大温，性上升，为水中之火，故破积散坚、升散三焦火郁。以升降阴阳论药性，属药性病机之辨，未涉脉象。", []], "27085": ["主病", "脉微为阳气衰微之象。原文治男子腰肾久冷、心腹积聚、失精遗尿、形羸力劣，皆肾阳亏虚；又治伤寒身冷脉微，或吐或利、自汗不止、小便不禁，乃阴寒内盛、阳气欲脱。脉微与身冷、吐利、自汗并见，主阳衰欲脱，故用硫黄丸温补下元，得身热脉出为向愈。", ["微"]], "27086": ["其他", "本段载王方平通灵玉粉散，以硫黄经桑柴灰汁煮煅制丸，治腰膝冷、暖水脏、益颜色，兼治风毒脚气痹弱。全段为方药炮制与服法记录，未言脉象，主旨属方药主治，故脉象要素为空，归其他类。", []], "27087": ["其他", "本段列药物主治，谓治五脏六腑寒热邪气、坚筋骨、长肌肉、温中下气、通经脉利血气、解百药毒，又主腹中冷痛、惊痫、妇人血沥腰痛，生用泻火热、熟用散表寒。通篇为药性功用，未及脉象，故脉象要素为空，主旨归其他。", []], "27088": ["主病", "伤寒心悸而见脉结代，结代脉主气血虚衰、脉气不相接续。心主血脉，气血亏虚则心失所养，故悸动不安；脉来缓而时一止复来为结，止有定数为代，皆提示心气不足、血行不畅。炙甘草汤类方以甘草为主，通经脉、利血气，正针对此虚衰之机。", ["结", "代"]], "27089": ["其他", "原文未出脉象，仅述痘疮烦渴用炙甘草、栝蒌根。痘疮热毒伤津则烦渴，甘草能通血脉、发疮痘，栝蒌根生津止渴，二药合用清解痘毒、滋养津液。此段属方药主治，非脉诊病机，故脉象要素为空。", []], "27090": ["其他", "原文为黄芪主治荟萃，未涉脉象。所述痈疽久败疮、大风癞疾、五痔鼠瘘、虚损羸瘦、崩带诸病，皆从气虚毒陷、血行不畅立论。黄芪补虚托毒、排脓止痛、活血生血，故能内补外托，为疮家圣药。此段属药物主治，非脉象病机。", []], "27091": ["病机", "脉弦自汗，弦为肝脉，主气机郁滞或虚风内动。元素谓黄芪补五脏诸虚，治脉弦自汗，泻阴火、去虚热。此因中气不足，阴火乘虚上冲，肝木失养而脉弦，卫外不固则自汗。黄芪甘温纯阳，补虚益元气，使阴火降、虚热除，汗出自止。", ["弦"]], "27092": ["病机", "原文未出脉象，然述黄芪治气虚盗汗、自汗及肤痛，为皮表之药；治咯血、柔脾胃，为中州之药；治伤寒尺脉不至，补肾脏元气，为里药。尺脉不至乃肾元虚衰、脉道不充之象，黄芪补三焦元气，故能上中下内外兼治。此段重在阐发药性病机。", []], "27093": ["病机", "原文未出脉象，引《灵枢》卫气功能，论黄芪补三焦、实卫气，与桂同功而甘平不辛热。脾胃一虚则肺气先绝，卫外不固而汗出，黄芪温分肉、益皮毛、实腠理，使汗止而元气复。此段从卫气与脾胃关系阐发黄芪益气固表之病机。", []], "27094": ["主病", "柳太后病风不能言，脉沉而口噤。沉脉主里，风邪中脏，痰气闭塞机窍，故口噤不语；脉沉提示病位在里，气血内困。许胤宗以黄芪防风汤气蒸，药入腠理，宣通阳气、祛风开窍，使沉困之邪从表而解，故夕便得语。", ["沉"]], "27095": ["病机", "内伤脾胃，发热恶寒，吐泄怠卧，胀满痞塞，神短脉微。微脉主阳气衰微、气血俱虚。脾胃虚则中气不足，故神短脉微；气虚及表则恶寒发热，升降失司则吐泄痞塞。嘉谟以人参为君补中，黄芪为臣实表，正针对中虚表弱之病机。", ["微"]], "27096": ["其他", "本段讲人参配伍引经，未涉脉象。原文强调人参得升麻引补上焦元气、泻肺火，得茯苓引补下焦元气、泻肾火，得麦冬生脉，得干姜补气。此论药性配伍与病机靶向，非脉诊内容，故脉象要素为空。", []], "27097": ["其他", "本段为《本经》《别录》等载人参主治，未言脉象。原文述其补五脏、安精神、定魂魄、止惊悸、除邪气、通血脉、破坚积，治虚损痰弱、肺痿痫疾、冷气逆上等，皆属药效主治范畴，非凭脉辨证，故脉象要素为空。", []], "27098": ["病机", "原文引张仲景：汗后身热、亡血而脉沉迟者，下痢身凉、血虚而脉微者，并加人参。沉迟为阳气不足、血行无力；脉微为阳衰血虚之象。此示血脱者益气，阳生则阴长，故以人参补气生血，脉象反映气血虚衰病机。", ["沉", "迟", "微"]], "27099": ["病机", "原文论人参生熟异用，提及土虚火旺宜生参泻火补土，脾虚肺怯宜熟参补土生金；又引东垣相火乘脾，身热而烦、气高而喘，脉洪而大者。洪大为火热亢盛、气分热炽之象，脉散则示气耗不敛，均属火旺或气泄病机。", ["洪", "大", "散"]], "27100": ["病机", "原文辨人参补阳泻阴，引脉散、脉之浮而芤、脉弦而数、脉虚者，说明不同脉象所主病机：散为气耗，芤为失血，弦数为热或木火，虚为不足。诸脉并见，示人参能养正破坚积、补元阳生阴血而泻阴火，非独肺寒可用。", ["散", "芤", "弦", "数"]], "27101": ["预后", "原文载郑兄患痢犯房，昏晕手撒目暗、自汗如雨、痰鸣曳锯、小便遗失，脉大无伦，断为阴亏阳绝之证。脉大无伦为元气涣散、阴阳离决之危候，故急煎人参膏并灸气海，后脉证渐复而安，示脉象关乎预后判断。", ["大", "数"]], "27102": ["主病", "原文列四君子汤治脾胃气虚、不思饮食，诸病气虚者以此为主；又述胃寒气满、脾胃虚弱等证，涉及脉虚无力、六脉沉细、脉沉伏、六脉沉细微弱、脉涩、脉紧而涩。诸脉皆主气虚阳弱、寒凝气滞，故以人参补气健脾为治。", ["虚", "沉", "细", "涩"]], "27103": ["病机", "原文载一人作劳发疟，服疟药变为热病，舌短痰嗽，六脉洪数而滑，断为痰蓄胸中，非吐不愈，以参芦汤加竹沥涌吐胶痰。洪数滑为痰热壅盛、气分热炽之象，脉证合参，故用吐法因势利导，属痰热病机。", ["洪", "数", "滑"]], "27104": ["主病", "原文述肺痈咳嗽，见“脉数咽干，不渴，时出浊唾腥臭”，脉数主热，热壅肺络，腐肉成脓，故咳唾腥臭浊痰；热伤津则咽干，然热在肺而不在胃，故不渴。此脉数与此症相应，示肺痈已成，热毒内蕴之病机。", ["数"]], "27105": ["病机", "原文言“营气不清，久风入脉，因而成癞”，指出大风癞疮由营气不清、风邪久客血脉所致，故见鼻坏色败、皮肤痒溃。虽未明言脉象，然“久风入脉”即示血脉受病之机，非以脉断，而以病因病理论。", []], "27106": ["其他", "原文为服食葳蕤法，称其“导气脉，强筋骨，治中风湿毒”，乃药后导引气脉、祛风除湿之效，非论脉象。所主在风湿毒邪留滞筋脉，致筋骨不强，故以葳蕤久服调养，非凭脉辨证。", []], "27107": ["其他", "此段为锁阳集解，述其产地、形态“筋脉连络，绝类男阳”，并疑遗精所生之说。全段考订药物形性，未涉脉诊，故无脉象可录，亦不主病机，属本草考证内容。", []], "27108": ["其他", "此段述赤箭（天麻）之形态、采收，言其根“惟无心脉尔”，乃指植物组织无心脉，非诊脉之脉。全段为药物形态与采制考证，不涉病机脉象，故无脉可辨。", []], "27109": ["主病", "此段列天麻主治，如“诸风湿痹，四肢拘挛，小儿风痫惊气”“冷气𤸷痹，摊缓不随”等，皆属风邪、湿痹、惊痫之病。虽未言脉，然所主病机为风动筋挛、湿阻络脉，与脉象之弦紧滑等可相应，此以药测证。", []], "27110": ["主病", "此段列术（白术）主治，如“风寒湿痹，死肌痉疸”“大风在身面，风眩头痛”“消痰水，逐皮间风水结肿”等，主风寒湿邪、痰水内停之病。虽无脉象，然所主病机为湿胜水停、风邪外袭，脉多沉弦或濡缓。", []], "27111": ["主病", "原文述好食生米症，因食生熟物留滞肠胃，湿聚生虫，久则憔悴萎黄。虽段中未明言脉，然标题脉象写法为“脉弦头微痛”，弦主湿滞、虫积，气机不畅则头微痛。苍术去湿暖胃消谷，正对湿滞肠胃之病机。", ["弦"]], "27112": ["其他", "本段为狗脊药材集解，述产地、采收及根茎形态，如“根凸凹巃嵸如羊角强细者”“似狗之脊骨”，纯属本草形态鉴别，未涉脉诊，故无脉象要素可录，亦不主病机。", []], "27113": ["其他", "本段仅存“百脉根”药名，无脉诊内容，亦无病机症候可析，属本草条目残文，故脉象要素为空，主旨归其他。", []], "27114": ["其他", "本段述“柏脉根”名称沿革及贡赋、方书用况，时珍疑名称不同，全属本草名物考证，未言脉象与病机，故无脉象要素。", []], "27115": ["治法", "“赤脉贯瞳”指目睛赤脉贯入瞳神之症，非脉诊之脉；玄参末蘸猪肝食疗为治法。原文以赤脉描述目络瘀滞之象，未涉寸口脉象，故脉象要素为空。", []], "27116": ["主病", "本段为丹参主治，列“心腹邪气，肠鸣幽幽如走水，寒热积聚，破症除瘕”及“通利关脉”“调妇人经脉不匀”等，皆属病机与主治范畴；文中“关脉”“经脉”指经络血脉，非脉象，故不取脉象要素。", []], "27117": ["病机", "时珍发明丹参“色赤味苦，气平而降，阴中之阳”，入少阴、厥阴血分，能“破宿血，补新血，安生胎，落死胎，止崩中带下，调经脉”，阐明其功在血分瘀滞与不足，属药性病机分析，未及脉象。", []], "27118": ["妇人", "丹参散治“妇人经脉不调，或前或后，或多或少，产前胎不安，产后恶血不下”，兼冷热劳、腰脊痛，主妇人经产诸疾，属妇人门；原文“经脉”指经水，非脉诊，故脉象要素为空。", []], "27119": ["病机", "原文谓“眼目之病，皆是血脉凝滞使然，故以行血药合黄连治之。血得热则行，故乘热洗也”，以血脉凝滞释目疾病机，属病机论述；文中“血脉”非寸口脉象，故脉象要素为空。", []], "27120": ["主病", "脉弦数，弦主痛、主肝，数主热。肠胃积热，或酒毒蕴结，灼伤血络，迫血妄行，故下血；热壅气滞则腹痛；热耗津液故口渴。脉症合参，此下血由积热所致，非虚寒也。聚金丸用黄连、黄芩苦寒清热，防风散火，正对脉弦数之积热病机。", ["弦", "数"]], "27121": ["病机", "六脉浮洪，浮主表、洪主热盛。洁古言黄芩泻肺火、治脾湿，成无己谓其入手少阴阳明，泻心火、泄痞热。浮洪之脉示热邪充斥表里，故黄芩所治为肺胃实热、上中二焦火盛之证。然肺虚者不宜，苦寒伤脾损母，此又示脉浮洪而按之虚者当慎。", ["浮", "洪"]], "27122": ["其他", "原文未出脉名，专述五种黄疸及秦艽诸方。伤酒发黄、误食鼠粪作黄、因劳发黄，皆湿热内蕴或劳伤脾土所致；目有赤脉、面赤恶心，为湿热上蒸。秦艽苦辛微寒，能利湿退黄，故诸方用之。暴泻引饮、伤寒烦渴亦用秦艽，取其清热利湿之功，非据脉辨证。", []], "27123": ["其他", "原文未出脉名，列秦艽主治大风、头眩痛、风邪目盲、骨节疼痹等。风邪外袭，经络壅滞，故周身骨节疼痹；风热上攻则头眩目赤。秦艽能搜肝气、散风邪、通利五脏关脉，故主三十六般风及劳劣羸损。所治以风邪、湿热、络脉不利为病机，非凭脉断证。", []], "27124": ["主病", "脉虚羸，虚为不足，羸示形体衰弱。经脉空虚，气血不充，筋脉失养，故四肢拘急、行履不得；骨节间痛、心腹痛，亦由虚而络脉不荣、气机不畅所致。甄权所主，正是虚人经脉失养、拘急疼痛之证，治当补益气血、温通经脉。", ["虚"]], "27125": ["其他", "原文未出脉名，辨羌活、独活产地、形色、气味及土脉所生。陶隐居言独活色微白、形虚大，与羌活相似；颂谓叶青者土脉中所生，叶黄者夹石上所生。所论重在药材鉴别与效用异同，非论病脉，故无脉象可录。", []], "27126": ["病机", "原文未出脉名，论羌活、独活治风胜湿之性。刘完素谓独活不摇风而治风，浮萍不沉水而利水，因其所胜为制；元素谓风能胜湿，羌活治水湿。羌活气雄，治足太阳风湿相搏、头痛肢节痛；独活气细，治足少阴伏风、两足湿痹。所论为风邪、湿邪留着经络之病机。", []], "27127": ["病机", "脉之缩急，缩主收引，急主拘挛。带脉环腰，约束诸经，缩急则腰腹拘急不舒。升麻能升胃中清气、引甘温药上升，以补卫气之散而实其表，故元气不足者用之阴中升阳，又缓带脉之缩急。此示脉缩急由中气不足、带脉失约而拘急，治当升阳举陷。", ["缩", "急"]], "27128": ["病机", "原文无脉名，论苦参揩齿致腰重之因。震亨谓苦参气降不升，非伤肾；时珍以子午少阴君火对化，苦寒补肾，取苦燥湿寒除热。指出肾水弱而相火胜者用之相宜，若火衰精冷、真元不足及年高者不可用，实为药性升降与肾火盛衰之辨。", []], "27129": ["主病", "原文无脉象，列贝母主治：头风黄疸、咳逆淋沥、女子阴中肿痛、湿痹死肌、不可屈伸起止行步，及小儿惊痫、妇人产后余痛、一切热毒风、风疮疥癣赤烂等。皆属风热痰湿壅结、血脉不通之候，故以贝母散结清热、通利血脉为主。", []], "27130": ["其他", "原文无脉象，述贝母产地、形态及品种鉴别。言贝母中有独颗团不作两片无皱者，号丹龙精，不入药用，误服令人筋脉永不收，惟以黄精、小蓝汁服之立解。此属药物鉴别与误服之害，非论脉诊病机，故归其他。", []], "27131": ["主病", "原文无脉象，列某药主治：劳伤虚羸、补中益气、除瘀血血闭寒热、利小便、下五淋、除客热在肠胃、止渴坚筋、妇人崩中、月经不匀、通血脉淋沥、止吐衄诸血、伤寒哕逆、肺热喘急、水肿黄疸。总属虚损兼瘀热、血不循经之候，故以补虚化瘀、清热利水为主。", []], "27132": ["主病", "原文无脉象，列某药主治：咳逆上气、头痛脑动、百节拘挛、风湿痹痛死肌，及喉痹齆鼻、风痫癫疾、下乳结、汗不出、血不行，润肝燥、治督脉为病脊强而厥。皆属风痰湿阻、气血不畅、督脉不利之候，故以祛风通窍、破痰利水、通精活血为主。", []], "27133": ["病机", "原文引张仲景治嗽而脉沉，泽漆汤中用白前。时珍谓白前色白味辛甘，手太阴药，长于降气，肺气壅实而有痰者宜之；若虚而长哽气者不可用。脉沉主水气内停、肺气壅实，故以白前降气化痰，佐温药以散水寒，虚者则非所宜。", ["沉"]], "27134": ["其他", "原文无脉象，论药物根身头尾功效各异。时珍以物之根身半以上气脉上行法乎天，身半以下气脉下行法乎地，人身法象天地，故治上用头、治中用身、治下用尾、通治全用。此属用药部位与气机升降相应之理，非脉诊病机，故归其他。", []], "27135": ["主病", "原文无脉象，列某药主治：咳逆上气、温疟寒热洗洗在皮肤中、妇人漏下绝子、诸恶疮疡金疮，及中风痓汗不出、湿痹中恶、客气虚冷、补五脏生肌肉、破恶血养新血、症癖肠胃冷，并冲脉为病气逆里急、带脉为病腹痛腰溶溶如坐水中。总属血虚寒凝、冲带失养之候。", []], "27136": ["病机", "原文引成无己“脉者血之府，诸血皆属心”，张仲景治“手足厥寒、脉细欲绝者”用当归助心血。脉细欲绝是血虚寒凝、心脉失充之象，血少不能充盈脉道，故脉细而欲绝；血虚寒厥则手足厥寒。当归苦温补心益血以通脉，正针对血虚寒凝之病机，非单纯血瘀。", ["细"]], "27137": ["病机", "原文言“其脉洪大而虚，重按全无力，此血虚之候也”，得于饥困劳役，证象白虎而“脉不长实为异”。脉洪大而虚是血虚阳浮、阴不敛阳之象，外似实热而内实不足，重按无力即虚证之凭。若误作白虎实热服之即死，故以当归补血汤补血益气，使浮阳归敛。", ["洪", "大", "虚"]], "27138": ["其他", "本段为药物主治罗列，未识别出脉名，亦无脉象描述，故脉象要素为空。文中“调众脉”“补五劳”“破症结宿血”等语，言该药能通调血脉、消瘀生新，属药性功用记载，非论脉诊病机，故归其他，不作脉象主病分析。", []], "27139": ["其他", "本段为药物主治条文，未识别出脉名，无脉象描述，脉象要素为空。文中“督脉为病，脊强而厥”引督脉病候，言该药可治督脉为病之脊强厥逆，属药效主治范围，非据脉断病，故列其他，不强行归入脉象病机。", []], "27140": ["其他", "本段述芍药产地、形态、采根时节及金芍药、木芍药之别，纯为药物性状鉴别，未识别出脉名，亦无脉象描述，脉象要素为空。文中“色紫瘦多脉”指木芍药根上纹理多，非诊脉之脉，不可误作脉象，故归其他。", []], "27141": ["其他", "本段为芍药主治汇集，未识别出脉名，无脉象描述，脉象要素为空。文中“通顺血脉”“和血脉”“除血痹”等言其调和血脉、散恶血、去水气之功，属药物主治功用，非据脉辨证，故列其他，不附会脉象病机。", []], "27142": ["其他", "本段述芍药补散之别及六般功用，未识别出脉名，无脉象描述，脉象要素为空。文中“和血脉”“固腠理”“止泻痢”皆言药效与配伍，如得炙甘草治腹中痛，属方药运用经验，非脉诊内容，故归其他。", []], "27143": ["病机", "原文震亨曰“凡腹痛多是血脉凝涩，亦必酒炒用”，又言芍药“止能治血虚腹痛”。脉凝涩即血脉凝滞不畅之象，血行涩滞则腹痛，故以酒炒芍药和血行滞。然其性酸寒收敛，无温散之功，只宜血虚腹痛，产后慎用，恐伐生发之气，此段兼论药性与禁忌。", ["涩"]], "27144": ["其他", "原文为芍药服食法，述金芍药色白多脂肉、木芍药色紫瘦多脉，此处“多脉”指根体纤维脉络粗韧，非诊脉之脉象。全段讲采制、蒸晒、服食之法，与病机无关，故脉象要素为空，主旨归其他。", []], "27145": ["主病", "原文列芍药主治寒热、中风瘛疭、惊痫邪气、症坚瘀血留舍肠胃、痈疮、女子经脉不通、血沥腰痛、衄血吐血等，末言和血生血凉血、治血中伏火。全段以主治病证为主，未涉脉象，故脉象要素为空，主旨归主病。", []], "27146": ["主病", "原文述邪气、辟毒疫温鬼、温疟蛊毒、心腹一切气、膀胱冷痛、呕逆反胃、霍乱泄泻痢疾、痃癖症块胀痛、女人血气刺心，末言治冲脉为病、逆气里急。全段罗列主治病证，未及脉象，故脉象要素为空，主旨归主病。", []], "27147": ["病机", "原文“暴泄身冷自汗，甚则欲呕，小便清，脉微弱”，脉微弱为阳气虚衰、阴寒内盛之象；身冷自汗、小便清、欲呕皆寒邪伤中、脾肾阳微所致，故脉微弱主虚寒暴泄，宜已寒丸温中散寒。脉象要素取微、弱。", ["微", "弱"]], "27148": ["主病", "原文论肾虚腰痛，述肾气虚弱、风冷乘之、血气相搏、劳役伤肾、卑湿伤腰、坠堕损伤、风寒客搏、气滞不散皆令腰痛，或腰间如物重坠。全段以腰痛病因与方治为主，未出脉象，故脉象要素为空，主旨归主病。", []], "27149": ["病机", "原文述郁金性轻扬上行，治吐血衄血唾血、经脉逆行，宜郁金末加韭汁、姜汁、童尿同服，痰中带血加竹沥，鼻血上行加四物汤。全段阐发郁金凉血降逆、引血下行之理，属病机与治法，未涉脉象，脉象要素为空。", []], "27150": ["主病", "原文列老癖症瘕、积聚结块、产后恶血血结、通月水、堕胎、气胀、破积气、消扑损瘀血、妇人血脉不调、心腹痛、产后腹痛血运、心膈痛、饮食不消、通肝经积血、疮肿坚硬、下乳汁。全段以主治病证为主，未及脉象，脉象要素为空。", []], "27151": ["其他", "原文述药性辛微苦甘平，为足厥阴、手少阳药，能兼行十二经、入脉气分，得童子小便、醋、芎䓖、苍术良。此“入脉气分”指药力入血脉气分，非脉象描述；全段讲归经与配伍，故脉象要素为空，主旨归其他。", []], "27152": ["其他", "原文为药物主治条目，未涉及脉象。所述“利九窍，通血脉，排脓治血”及“止鼻洪吐血，产后心腹痛”等，属该药活血止血、通窍排脓之功，非脉诊病机分析，故无脉象要素可提取。", []], "27153": ["病机", "原文虽未直接论脉，但“脉沉而大”提示暑病夹湿、阳气被遏。沉主里，大主热盛或气虚。文中“阳气为阴邪所遏”致头痛恶寒、烦躁口渴，或吐或泻，正合沉大之脉：沉为湿遏，大为热蒸。若劳倦内伤、汗泄如雨，脉亦可见大而虚，故告诫不可概用香薷重虚其表。", ["沉", "大"]], "27154": ["其他", "原文为药物主治，未涉及脉象。所述“寒热鼠瘘，瘰疬生疮，破结聚气，下瘀血，除湿痹”及“通利血脉，传送五脏不足气”等，皆属该药功效，非脉诊病机，故无脉象要素可提取。", []], "27155": ["其他", "原文为食物主治，未涉及脉象。所述“咳逆，下气，温中补体”“止渴润肺”“补中益气，通血脉，填精髓”等，属该品补益润肺之功，非脉诊病机分析，故无脉象要素可提取。", []], "27156": ["其他", "原文为菊花主治，未涉及脉象。所述“诸风头眩肿痛，目欲脱，泪出”“皮肤死肌，恶风湿痹”“利血脉”“养目血，去翳膜”“主肝气不足”等，皆属该药清肝明目、祛风通脉之功，非脉诊病机，故无脉象要素可提取。", []], "27157": ["其他", "原文论述艾叶炮制方法，未涉及脉象。文中“若生艾灸火，则伤人肌脉”虽提及“脉”，但指肌脉受伤，非脉象诊断；余述熟艾制作及入丸散用法，属炮制与用药注意，故无脉象要素可提取。", []], "27158": ["其他", "原文为艾叶主治，未涉及脉象。所述“灸百病”“止吐血下痢”“妇人漏血”“止崩血、肠痔血”“安胎”“治带脉为病，腹胀满，腰溶溶如坐水中”等，皆属该药温经止血、安胎除湿之功，非脉诊病机，故无脉象要素可提取。", []], "27159": ["主病", "原文“伤寒时气，温病头痛，壮热脉盛”，脉盛即脉来充盛有力，主邪热亢盛。温病壮热、头痛，为热邪充斥内外，故脉盛相应。后附妊娠伤寒、中风等灸熨诸法，皆从“脉盛”之热证或卒中闭证延伸，示艾叶可随证外用内服。", ["盛"]], "27160": ["其他", "此段为药物主治记载，未涉脉象。原文言不可久服，因\"血脉满盛\"，提示该药有活血充脉之力，久服则血分壅盛，反致偏颇。所治阴肿，亦从血分水气立论，与脉诊无直接关联，故脉象要素为空。", []], "27161": ["其他", "全段列述药物功效主治，无脉象描述。文中\"疗血逆大热\"\"通血脉\"\"调女人经脉\"诸语，皆从血分着眼，提示该药善理血中逆乱、通调经脉，为后文妇科诸病之用张本，非论脉也。", []], "27162": ["病机", "时珍论茺蔚子辛温主散，瞳子散大者禁用，因血不足也。此从药性推病机：目得血而能视，血虚则瞳神散大，辛散之品更耗其血，故禁。血滞病目则宜，以其行血甚捷。全段以血之虚实滞行为枢，非言脉象。", []], "27163": ["病机", "时珍分述益母草根茎花叶与茺蔚子之用：前者专于行，后者行中有补。治厥阴血分风热、调经脉用子，治肿毒疮疡、消水行血、胎产诸病则并用。全段以血分风热、水血互结为病机纲目，未及脉诊。", []], "27164": ["妇人", "此段载济阴返魂丹方，专治妇人胎前产后诸疾危证，属妇人门。文中详述益母草采收、炮制、服法，以病愈为度，未涉脉象。其\"随证嚼服\"\"以病愈为度\"示因人因证施量，非凭脉定治。", []], "27165": ["病机", "丹溪言夏枯草治瘰疬、散结气，有补养厥阴血脉之功。虚者可使，实者佐行散之药。此从虚实立论：瘰疬结气多因厥阴血虚气结，故取夏枯草补血散结，虚补实散，层次分明，未言脉象。", []], "27166": ["病机", "时珍引黎居士、楼全善说，论夏枯草治目珠疼至夜甚、点苦寒反甚者。目系属厥阴，夜与寒皆阴，故以纯阳之夏枯草补厥阴血脉，以阳治阴。此从阴阳寒热、经络归属析病机，非脉诊。", []], "27167": ["兼症", "此方治肝虚目睛痛、冷泪不止、筋脉痛、羞明怕日，皆肝虚血少、筋脉失养之兼症。夏枯草配香附，补肝血、疏肝气，腊茶调下清上。全段列症以明方证，未及脉象，故脉象要素为空。", []], "27168": ["主病", "此段为破血下胀药的主治记载，原文未出脉象。所述“通妇人经脉症结”“水胀血气”“产后余疾”等，皆属瘀血内结、气机壅滞之病机；药能破血下胀，故多服令人下痢，示其攻逐之力偏峻，适用于血瘀实证而非虚人。", []], "27169": ["主病", "原文未言脉，所列“胸上痰结，唾如胶漆”“心胁痰水，膀胱留饮”“水肿，逐大腹”等，均属痰饮内停、水气不化之病机。药能行痰水、消坚软痞，故所主皆痰水结聚为患，与湿痹、噫气等症相应，示饮邪流溢三焦之候。", []], "27170": ["病机", "时珍明言旋覆花为手太阴肺、手阳明大肠药，功在“行水、下气、通血脉”。此三语即其病机核心：水停则气逆，气逆则血滞，故治诸病皆从宣肺降气、通利血脉着眼。原文未及脉象，所论重在药性归经与病机，非脉诊之文。", []], "27171": ["病机", "原文“半产漏下，虚寒相抟，其脉弦芤”，弦主虚寒相搏、气机拘急，芤主阴血骤失、脉道中空。半产漏下则血去而寒乘，虚寒相抟故脉弦芤并见。此脉示血虚寒凝、冲任不固之病机，与漏下不止相应，故用旋覆花汤通脉散寒。", ["弦", "芤"]], "27172": ["其他", "此段为鸡冠花集解，详述苗叶茎花形态、花色与穗状，属本草性状描述，未涉脉象与病机。原文“梢有赤脉”“有筋起”乃言植物茎叶纹理，非诊脉之脉，故脉象要素为空，主旨归其他。", []], "27173": ["病机", "时珍谓“血生于心包，藏于肝，属于冲任”，红花汁同类，故行男子血脉、通女子经水。所举产晕已死、胸膈微热案，断为“血闷”，即瘀血闭阻、气机不通之病机。原文未出脉，全篇以血之生成与瘀阻论药效，非脉诊内容。", []], "27174": ["主病", "原文未言脉，所列“崩中漏血”“症结瘀血”“胎漏”“金疮血内漏”等，皆属血瘀血虚、脉络损伤之病机；又主“关节缓急”“面黄虚肿”，示气血不足兼瘀滞。药能续筋骨、通宣血脉、破症结，故所主以血分病证为核心。", []], "27175": ["主病", "原文未出脉象，所述“皮肤热毒，恶疮疽痔”“热气疮痒如麻豆”“小儿壮热”属热毒壅遏之病机；“通经脉”“下乳汁”“续筋骨”则示其能通利血脉、解毒排脓。诸症皆围绕热毒与血脉壅滞，故归主病。", []], "27176": ["其他", "原文为漏芦治乳汁不下、历节风痛之方药记载，未涉脉象。其言'气脉壅塞''经络凝滞'，指乳汁不下由气机壅滞、脉络不通所致，乳内胀痛成痈亦因邪蓄络脉。方以漏芦、蛇蜕、栝蒌通络散结，取'以通为度'，正合壅塞之病机，非凭脉断证。", []], "27177": ["其他", "此段为漏芦药材形态鉴别，述山冈所生者'中有黑脉'，乃指根肉内黑色纹理，非诊脉之脉。文中辨马蓟似苦芺者非漏芦，属本草名实考订，与病机脉象无关，故脉象要素为空，主旨归入其他。", []], "27178": ["其他", "全段罗列漏芦主治诸症，如皮肤寒热、胃中热气、风寒湿痹、痈肿、崩中带下、鼻衄吐血等，皆属药效记载，未言及脉。其病机涉及热郁、湿痹、血热妄行、疮毒壅结等，然原文无脉象描述，不能据脉析理，故列其他。", []], "27179": ["其他", "此段述某药主治伤寒寒热汗出、中风面肿、消渴热中、逐水及牙齿痛、劳疟、痈疽、咳嗽伤肺等，为药效汇总。文中'逐水''肺壅''冷气积血'提示水气、肺气壅滞、血积等病机，但通篇未载脉象，无从以脉论证，故脉象要素空。", []], "27180": ["其他", "原文记生食止渴润肺、通血脉填骨髓、破血解酒毒、除小儿客热等，属食疗药效。'通血脉''破血'示其功在行血，'解肌热烦渴'示清解肌热，然全段无脉象记载，病机分析无脉可依，故归其他。", []], "27181": ["主病", "原文言'伤寒时气，温病初得，头痛壮热，脉盛者'，以生蘘荷根叶捣汁服。脉盛为邪气方盛、正邪交争之象，温病初得邪在表分，阳气奋起抗邪故脉盛，与头痛壮热相应。此为凭脉辨温病初起邪盛之证，主病明确，故归主病。", ["盛"]], "27182": ["其他", "此段列某药主治中风伤寒头痛、温疟、发表出汗、止咳逆上气、破症坚积聚，及去营中寒邪、泄卫中风热等。虽涉营卫、寒热、积聚病机，然全为药效陈述，未出脉象，不能以脉析证，故脉象要素为空，主旨归其他。", []], "27183": ["病机", "时珍论麻黄治肺，析寒伤营则营血内涩、卫气闭固而无汗，风伤卫则卫气外泄、营虚不固而有汗。文中举'脉沉迟者加人参''脉浮而缓'，沉迟示里虚寒、正气不足，浮缓示风伤卫、营弱卫强，正合有汗恶风之机。以脉印证营卫虚实，故归病机。", ["沉", "迟", "浮", "缓"]], "27184": ["病机", "原文以“脉沉”辨里水黄肿，沉主水气在里、少阴受困，故一身面目黄肿而小便不利，用甘草麻黄汤发汗；又举“脉浮者为风”与虚胀为气作鉴别，说明浮脉主风邪在表，非水病本脉。沉与浮对举，正是从脉位浅深分水气与风邪，提示水肿辨脉须先别表里。", ["沉", "浮"]], "27185": ["其他", "本段为地黄主治汇集，未出脉象，故脉要素为空。文中“逐血痹”“通血脉”“补肾水真阴”“凉血生血”诸语，说明地黄功在补血滋阴、行血通痹，所主为伤中、五劳七伤、吐血崩中等血虚阴亏之证，非据脉立论，属药性主治类条文。", []], "27186": ["其他", "此段亦为地黄主治，无脉象可录。“填骨髓，长肌肉，生精血，补五脏内伤不足”点明其补益精血之功，“通血脉，利耳目，黑须发”及女子经候胎产百病，皆从精血亏虚立说，属药性主治，不涉脉诊，故脉要素从缺。", []], "27187": ["病机", "原文以“脉洪实者宜之”用生地黄，洪实为心热炽盛、血分有火之象，故取生地凉心血、益肾水；又言“若脉虚者，则宜熟地黄”，虚脉主肾中元气不足，故用熟地假火力蒸晒以补肾元。一洪实一虚，正好从脉之虚实分生地、熟地之取舍。", ["洪", "实", "虚"]], "27188": ["兼症", "“心热吐衄，脉洪数者”一句，洪数为心火亢盛、热迫血行之脉，故吐血不止而舌上出血。原文以生地汁配大黄末为丸，取凉血泻火之意，说明洪数脉在此标示热盛动血之兼症，而非单主吐衄本病，故归兼症。", ["洪", "数"]], "27189": ["妇人", "“妊妇冲任脉虚”是胎寒腹痛之根，虚脉示冲任气血不足、温养无力，故胎寒而痛。原文主张“惟宜抑阳助阴”，用熟地黄、当归蜜丸温酒下，正是从冲任脉虚立治。此段专论妊娠，脉虚为辨证眼目，故归妇人。", ["虚"]], "27190": ["妇人", "本段无脉象，述妊娠胎动用生地汁煎鸡子白，及产后血痛有块用黑神散。前者取生地凉血安胎，后者以熟地、生姜温通化瘀，皆属妇人胎产经行诸证之方治，未及脉诊，故脉要素为空，主旨归妇人。", []], "27191": ["其他", "此段为地黄（或相关药）主治汇集，通篇无脉象。“寒湿痿痹，四肢拘挛”“补肾，助十二经脉，逐恶血”“产后心腹痛并血晕”等，皆述药功所主之证，从寒湿、肾虚、血结立说，不凭脉断病，故脉要素缺，归其他。", []], "27192": ["主病", "本段为麦门冬主治诸症，未出脉象。原文列“心腹结气”“胃络脉绝”“羸瘦短气”“肺痿吐脓”“面目肢节浮肿”等，皆从脏腑津亏、虚热内扰立论，故所主在肺胃阴伤、伏火妄行，非以脉断病，脉象要素无从取。", []], "27193": ["病机", "宗奭论麦门冬“专泄而不专收”，治“心肺虚热及虚劳”，与地黄、阿胶、麻仁为“复脉通心之剂”，与五味子、枸杞为“生脉之剂”。全段以药测机，指心肺阴血不足、虚热内扰致脉道不充，未直接描述脉形，故脉象要素为空。", []], "27194": ["病机", "原文“治肺中伏火、脉气欲绝者”，以生脉散补肺中元气不足。脉气欲绝即脉散不收、按之无力，为肺中伏火耗伤元气、气不敛脉之象，故取“散”字。此脉主肺元气虚衰，与骨乏无力、气短相应。", ["散"]], "27195": ["病机", "杲引孙真人以生脉散“补其天元真气”，明言“脉者，人之元气也”。湿热方旺而病骨乏无力、身重气短、痿软，是元气为热所耗、脉气涣散不收，故脉散。人参泻热火益元气，麦冬滋燥金清水源，五味子补庚金，皆针对元气散越之机。", ["散"]], "27196": ["病机", "时珍论葵“利窍通乳，消肿滑胎”，引《妇人良方》“乳妇气脉壅塞，乳汁不行，经络凝滞，奶房胀痛”。此处“气脉壅塞”指气机与血脉壅滞不通，非具体脉形，故脉象要素为空；所主为营卫津液不行、乳络壅滞之病机。", []], "27197": ["主病", "本段列王不留行主治“金疮止血，逐痛出刺，除风痹内寒”“通血脉”“下乳汁”“利小便”等，皆从行血通络、下乳滑窍立论。原文未出脉象，只言“通血脉”，指血脉瘀滞可致风痹、经不匀、难产，脉象要素无从取。", []], "27198": ["病机", "元素言王不留行“下乳引导用之，取其利血脉也”。全段以“利血脉”三字点明病机：乳汁不下由血脉不利、乳络壅滞所致，药取行血通络以引乳下行。原文未描述脉形，故脉象要素为空，主旨归病机。", []], "27199": ["其他", "本段为苏颂对连翘产地、大翘小翘形态及南方医家所说两种连翘的考述，属药物品种鉴别，未涉脉象与病机。原文“壳小坚而外完”“剖之则中解”皆状药材形质，非脉，故脉象要素为空，类别归其他。", []], "27200": ["其他", "本段为药物（冷饮子）的炮制与主治记载，未涉脉象。原文称其'破女子经脉不通'，指药性通行血脉、解散瘀滞，故孕妇忌服，恐动胎元。此属本草主治范畴，非脉诊病机，故脉象要素为空。", []], "27201": ["其他", "本段述留军待之性味主治，'主肢节风痛，筋脉不遂，折伤瘀血，五缓挛痛'，皆属风邪痹阻、瘀血阻滞之证，药性辛温能通经散邪。原文未及脉象，故无从据脉论病机，仅录其主治症候。", []], "27202": ["其他", "本段为药物（大黄）主治汇总，'下瘀血血闭''破症瘕积聚''荡涤肠胃''通女子经候'等，皆言其攻下逐瘀、泄实热之功。原文纯列主治，未涉脉象，故不能据脉析病机，脉象要素为空。", []], "27203": ["病机", "原文'脉洪而实，此有宿妨'，洪为热盛，实为邪结，洪实并见说明宿食积滞、实热内结于肠胃，故非用大黄攻下无瘥理。此脉主实热积滞之病机，与心腹疾、宿妨相应，非虚寒可轻下。", ["洪", "实"]], "27204": ["主病", "原文'肺咳上气脉沉者，泽漆汤主之'，沉脉主里主水，肺咳上气而脉沉，说明水饮内停、肺气不降，病位在里。故以泽漆汤逐水通阳、降逆止咳，脉沉正是里饮之征，与咳逆上气症候相应。", ["沉"]], "27205": ["病机", "原文'心下留饮，坚满脉伏，其人欲自利反快'，伏脉主邪气深结、阳气被遏，饮邪留于心下坚满，阻遏脉道故脉伏。欲自利反快为饮有下行之势，故用甘遂半夏汤攻逐留饮，脉伏正示饮结之深。", ["伏"]], "27206": ["预后", "原文述病妇食憨葱苗（藜芦）后吐涎斗余，'三日后遂轻健，病去食进，百脉皆和'。百脉皆和指脉象平和调匀，为风痰痼疾去后气血复常之象，属疾病向愈的预后判断，非主病之脉。", ["和"]], "27207": ["其他", "本段考辨乌头、附子之产地与命名，述彰明出附子、春采乌头冬采附子等，纯属药物名实考证，未涉脉象与病机，故脉象要素为空，归入其他类。", []], "27208": ["治法", "此段论附子配伍法度，非诊脉之文。熟附配麻黄，取「发中有补」，如麻黄附子细辛汤、麻黄附子甘草汤，温经助阳以散寒；生附配干姜，取「补中有发」，如干姜附子汤、通脉四逆汤，回阳之中兼散阴寒。虽未言脉，然所主皆少阴阳虚、阴寒内盛之证，脉当沉微，故列治法。", []], "27209": ["主病", "此段述附子主治，未及脉象。所举「风寒咳逆邪气」「寒湿踒躄」「心腹冷痛」「下痢赤白」「三阳厥逆」「督脉为病，脊强而厥」诸症，皆属阳虚寒盛、沉寒痼冷之病机。附子辛热，温中散寒、补下焦阳虚，故凡脏腑沉寒、脉沉迟微细者所宜，此以症测脉也。", []], "27210": ["治法", "此段论乌附选用及服法，非脉诊之文。宗奭谓「补虚寒须用附子，风家即多用天雄」，时珍分附子「性重滞，温脾逐寒」、川乌「性轻疏，温脾去风」，寒疾用附子、风疾用川乌。又「热因寒用」，热药冷饮，治阴寒在下、虚阳上浮之格拒，此反治之妙，脉当沉细而兼浮阳。", []], "27211": ["病机", "此段以脉沉、脉沉细为阴证眼目。伤寒传变三阴及中寒夹阴，「虽身大热而脉沉者」必用附子，此热为假象、沉为里寒之真；「厥冷腹痛，脉沉细，甚则唇青囊缩」，沉细主阳气衰微、阴寒内盛。故急用人参健脉益原、附子温经散寒，有退阴回阳之功，舍此则阴极阳竭。", ["沉", "细"]], "27212": ["主病", "此段引少阴伤寒「脉微细，但欲寐，小便色白」，微为阳虚，细为阴盛，脉微细与但欲寐并见，正是少阴阳气衰微、阴寒内盛之提纲证。小便色白更证里无热。故用麻黄附子甘草汤微发其汗，温经助阳以散表寒，取微汗而不伤阳，此脉证相应之治法。", ["微", "细"]], "27213": ["病机", "此段两案皆少阴病脉。始得反发热而「脉沉」，沉主在里，发热为少阴兼表，故麻黄附子细辛汤温经发汗；下利清谷、里寒外热、手足厥逆而「脉微欲绝」，微为阳微，欲绝为阳气将脱，面赤乃虚阳上浮，故通脉四逆汤回阳救逆，「其脉即出者愈」，以脉复为生机。", ["沉", "微"]], "27214": ["主病", "此段论阴毒伤寒，症见少腹疼痛、头疼腰重、手足厥逆、呃逆，而「脉息沉细」。沉细主阴寒内盛、阳气不振，与厥逆并见，正是阴毒内结、寒凝血脉之候。故用退阴散、玉女散、回阳散等辛热之剂，温散阴毒、回阳救逆，得汗则解，以脉沉细为阴毒之凭。", ["沉", "细"]], "27215": ["病机", "此段述阴毒伤寒烦躁迷闷及中风气厥痰壅、昏不知人而「六脉沉伏」。沉伏主阳气闭阻、痰浊内壅，气血不能外达，故脉道潜伏不见；与昏不知人、口眼㖞斜并见，属痰厥气闭、阳郁不伸。故用三生饮、生附子南星辈，辛温开通，以复阳气之运行。", ["沉", "伏"]], "27216": ["主病", "寒疝腹痛绕脐、手足厥冷、自汗出，脉弦紧。弦主痛、主寒，紧主寒主收引，寒邪内结，阳气被遏，故腹痛绕脐、厥冷；阳虚不固则自汗。脉证相合，属阴寒内盛之寒疝，故用大乌头煎温阳散寒止痛。", ["弦", "紧"]], "27217": ["病机", "小便虚闭而两尺脉沉，用利小水药不效，知非湿热壅闭，乃下焦虚寒、气化不行。尺脉候肾，沉主里主寒，肾阳不足则膀胱气化无力，故小便不通。方用附子温肾、泽泻利水，灯心通窍，属虚寒癃闭之治。", ["沉"]], "27218": ["病机", "下痢咳逆而脉沉阴寒，沉主里、主阴寒内盛。下痢伤中，阴寒上逆犯肺则咳逆，脉沉示病在里、阳气不振。此为阴寒内盛、上下同病之候，故用退阴散温散阴寒，使阳复寒退则痢咳可止。", ["沉"]], "27219": ["其他", "此段为天雄主治功用之汇集，述其治大风寒湿痹、历节痛、拘挛、破积聚邪气、强筋骨等，未及脉象。天雄性大热，助阳散寒、祛风除湿，故所主皆阳虚寒湿、风邪痹阻之证，属药性主治记述，非脉诊病机之论。", []], "27220": ["病机", "元阳素虚，寒邪外攻，手足厥冷，二便滑数，小便白浑，六脉沉微。沉主里、微主阳虚，六脉沉微示阳气衰微、阴寒内盛，不能温煦四末故厥冷，不能固摄故二便滑数。此为阴毒伤寒、元阳欲脱之候，故用三建汤扶元阳、除固冷。", ["沉", "微"]], "27221": ["主病", "风痰头晕、呕逆目眩、面色青黄而脉弦。弦主风、主痰饮、主肝胆，风痰上扰清窍则头晕目眩，痰阻中焦则呕逆，面色青黄为风痰内郁之征。脉弦与风痰之证相应，故用水煮金花丸化痰熄风，兼治风痰咳嗽、头痛。", ["弦"]], "27222": ["主病", "热痰咳嗽、烦热面赤、口燥心痛而脉洪数。洪主热盛，数主热，洪数相合为痰热内蕴、火热上炎之象。热灼津液则为痰，痰热扰心则心痛烦热，上蒸则面赤口燥。脉证相符，故用小黄丸以黄芩清热、半夏南星化痰。", ["洪", "数"]], "27223": ["主病", "湿痰咳嗽、面黄体重、嗜卧、食不消而脉缓。缓主湿、主脾虚，脾失健运则湿痰内生，湿性重浊故体重嗜卧，脾不运化故食不消，面黄为脾湿之征。脉缓与湿痰脾困相应，故用白术丸健脾燥湿化痰，标本兼顾。", ["缓"]], "27224": ["病机", "气痰咳嗽而见面白气促、洒淅恶寒、愁忧不乐，脉涩者，涩主气机不畅、痰阻肺络，营卫运行滞涩。气痰内阻则肺失宣降，故咳而气促；卫阳不布则恶寒；情志不舒则愁忧。涩脉正示痰气交阻、气血不流之机，故用玉粉丸化痰行气。", ["涩"]], "27225": ["主病", "小结胸痛正在心下、按之则痛，脉浮滑者，浮示邪偏于上焦胸脘，滑主痰热内结。痰热互结于心下，故按之痛；脉浮滑正是痰热结聚未深之象，故以小陷胸汤清热化痰开结，与脉证相应。", ["浮", "滑"]], "27226": ["其他", "此段言金刃入骨脉中不出之外治方，半夏、白蔹为末酒服，取消散拔毒之意。原文未及脉象，亦不以脉断病机，故脉象要素为空。所论为异物入骨之证治，与脉学病机无直接关联，仅录方药用法。", []], "27227": ["预后", "黑黄急病面黑黄、身如土色而能食，脉沉者，沉主里、主阴寒湿浊内郁。若青脉入口则死，是肝木乘脾、脏气败绝之危候。脉沉示病在里，青脉入口示胃气已败，故原文以脉之变化判预后吉凶，宜烙口中黑脉等穴以救之。", ["沉"]], "27228": ["其他", "此段为药物主治汇集，述咳逆上气、喉鸣喘、水肿、五水在五脏皮肤及痰饮胁痛等，皆水饮痰湿为患。原文未出脉象，故脉象要素为空。所论重在药性功用与所主症候，非以脉断病机，属本草主治内容。", []], "27229": ["病机", "好古论水病由肺、肾、脾三经所主，分五脏六腑十二经部分，脉有尺寸之殊、浮沉之别，不可轻泻。浮沉二字示水饮停聚有表里浅深之异，当据脉辨病在何经何脏方可攻逐。误投则害深，强调脉诊定位对逐水治法之指导。", ["浮", "沉"]], "27230": ["其他", "此段为菟丝子之发明，言其禀中和凝正阳气，偏补人卫气、助人筋脉。原文未涉脉象，故脉象要素为空。所论为药性补益卫气筋脉之理，非脉诊病机内容，属本草发明之类。", []], "27231": ["病机", "胸痹痛引背、喘息咳唾短气，寸脉沉迟、关上紧数。寸沉迟示上焦阳微、胸阳不振，关紧数示痰浊寒饮内结、气机痹阻。阳微阴弦，痰饮上乘，故胸痛彻背、气不得通。脉证合参，主胸痹痰浊闭阻之机，用栝蒌薤白白酒汤通阳散结。", ["沉", "迟", "紧", "数"]], "27232": ["主病", "天行时气初觉头痛、内热而脉洪，洪为阳盛之象，热邪充斥阳明气分，故脉来洪大。原文以脉洪者点明内热已盛，与头痛并见，属外感时气化热入里之候，故取葛根兼治，捣生根汁尤佳，正取其解肌退热之力。", ["洪"]], "27233": ["病机", "原文未出脉名，而言营卫枯涸，宜以湿剂润之，二门冬、人参、五味、枸杞同为生脉之剂，此上焦独取寸口之意。营卫枯涸则脉道失充，故以生脉为治，取寸口以候上焦心肺之气，润养营卫使脉复生，属虚损病机而非具体脉象。", []], "27234": ["其他", "此段论生脉之剂配伍君臣佐使，未及脉象。谓生地黄、贝母为天门冬之使，地黄、车前为麦门冬之使，茯苓为人参之使，若有君无使则独行无功。以张三丰长生不老方为例，说明君臣相配之理，属方药配伍之论，非脉诊内容。", []], "27235": ["病机", "原文未出脉名，而论杨梅毒疮之病机：始由毒气干于阳明而发，加以轻粉燥烈，久而水衰，肝挟相火来凌脾土，湿热郁蓄肌腠，发为痈肿拘挛。引《内经》湿气害人皮肉筋骨，说明土萆薢甘淡去脾湿，湿去则营卫从而筋脉柔，属湿热伤筋之病机。", []], "27236": ["其他", "此段为威灵仙传，述其去众风、通十二经脉，疏宣五脏冷脓宿水，治手足不遂、中风不语、口眼㖞斜、筋骨节风等。原文未及脉象，重在记载药效与治验，属本草主治与验案内容，非脉诊病机之论。", []], "27237": ["其他", "震亨论威灵仙属木，为治痛风之要药，上下皆宜，其性好走，可横行，故能去众风、通十二经脉。原文以闻流水声知其性走，不闻水声者乃佳，全论药性走窜通经之理，未涉脉象，属本草药性论述。", []], "27238": ["其他", "此段罗列主治：寒湿风痹、黄疸、补中、止血内崩下血、膀胱不足、踒跌蛊毒，又治六极伤心肺、吐血泻血、鼻洪尿血、产后血晕、月经不止、带下、扑损淤血、泄精、痔瘘疮疖排脓，通经脉治骨节风痛、活血行血。全为药物主治，未出脉象。", []], "27239": ["主病", "风水恶风、汗出身重而脉浮，浮为风邪在表之象，风与水相搏，卫表不固故汗出，水湿泛溢故身重。脉浮主病在表，与恶风汗出相应，故以防己黄耆汤实表祛湿。后段风湿相搏、关节沉痛微肿恶风，方同上，亦属表虚风湿之候。", ["浮"]], "27240": ["病机", "脉沉紧为水饮内结之征。饮邪停于膈间，支饮阻遏气机，故喘满、心下痞坚；沉主里、主水，紧主寒、主痛，饮寒凝结故脉沉紧。面黧黑为水气上泛。吐下不愈，说明饮结深痼，非一般攻逐可解，故以木防己汤行水散结，虚者即愈，实者复发。", ["沉", "紧"]], "27241": ["其他", "此段为药物主治记载，未涉及脉象。原文述其除脾胃寒热、通利九窍血脉关节、令人不忘、去恶虫，重点在药效而非脉诊，故脉象要素为空，主旨归入其他，不作病机推断。", []], "27242": ["其他", "此段罗列诸家药效主治，如利经脉寒热不通之气、理风热、通经利窍、导小肠火等，通篇无脉象描述。所论为药物功用与相应症候，非脉学病机分析，故脉象要素为空，归入其他。", []], "27243": ["其他", "此段言药物主治，谓厚肠胃、令人能食、下三焦恶气、续五脏断绝气、通十二经脉，全为药效叙述，未出现任何脉象。无脉可析，故脉象要素为空，主旨不属脉学病机，归入其他。", []], "27244": ["其他", "此段详述五种尸注的症候特点，如飞尸游走皮肤、遁尸附骨入肉、沉尸缠结脏腑等，并出忍冬煎服方。原文未载脉象，所论为病证与治法，非脉诊内容，故脉象要素为空，归入其他。", []], "27245": ["妇人", "此段论妊娠水肿，始自两足渐至喘闷、足趾出水，谓之子气，因妇人素有风气或冲任血风所致，不可作水妄投汤药，宜天仙藤散。原文未言脉象，主旨属妇人妊娠病证，故脉象要素为空，归入妇人。", []], "27246": ["病机", "原文言主肢节风冷、筋脉急痛，脉急痛之“急”指筋脉拘急挛痛之象。风冷客于肢节，寒性收引，筋脉失养而拘急，故见急痛。辛温之品作汤浴，以温散风冷、舒缓筋脉，脉急与风冷筋脉拘急之病机相应。", ["急"]], "27247": ["其他", "此段为药物主治记载，述其治大风、乳汁不出、产难、强阴气，久服轻身，壮水脏、通血脉。通篇无脉象描述，所论为药效与主治症候，非脉学病机分析，故脉象要素为空，归入其他。", []], "27248": ["其他", "本段为菖蒲服食法及功效记载，未涉脉象。文中言菖蒲气温味辛，为手少阴、足厥阴之药，心气不足者用之，取虚则补其母、肝苦急以辛补之之义，属药性归经与补益理论，非脉诊内容，故无脉象要素可析。", []], "27249": ["病机", "原文辨尸厥，谓卒死而脉犹动，听耳中如微语声、股间暖者即是。脉犹动说明生机未绝、气血尚存，故可救；若脉绝不动则属真死。此以脉动与否判断尸厥与真死，脉动为病机关键，主卒死可苏之候，与耳中微语、股间温暖相应。", ["动"]], "27250": ["其他", "本段列菖蒲主治，言去五脏心下邪气、口中烂臭、坚齿明目聪耳，久服轻身耐老，并治妊妇劳热烦躁、胎动下血。全段为药物功用记载，未及脉象，故无脉象要素，主旨属主治范围，不涉脉诊病机。", []], "27251": ["其他", "本段述某药主治心腹膀胱寒热、利小便、止血消瘀血，治痢血鼻衄吐血尿血、女子崩中带下、月候不匀、妊妇下血坠胎、儿枕急痛、颠扑血闷等。全为药物主治血证与妇科病候，未提脉象，故无脉象要素可录。", []], "27252": ["其他", "本段为菰根集解，述其生水中，叶如蔗荻，根盘而厚，夏月生菌名菰菜，三年中心生白苔如藕状、似小儿臂而白软、中有黑脉名菰首。文中黑脉指植物内部纹理，非诊脉之脉，全段属药物形态描述，无脉象要素。", []], "27253": ["其他", "本段列地朕、地锦主治，言地朕主心气、女子阴疝血结；地锦通流血脉、治气，主痈肿恶疮、金刃扑损出血、血痢下血崩中，能散血止血、利小便。全为药物功用，未涉脉象，故无脉象要素，主旨属主治记载。", []], "27254": ["其他", "本段述某药茎叶俱青如松叶、无花、三月生苗、四月长五六寸、四时采根晒用，其功下乳汁、顺血脉、调气甚佳。文中顺血脉、调气为药效表述，非脉象，全段属药物形态与主治，无脉象要素可析。", []], "27255": ["其他", "本段述某药主治虚劳，滑肠胃、行风气、通血脉、去头上浮风、润肌肉，食后生啖，又与乳母服之使孩子不生病，客热可作饮汁，生嚼敷小儿头疮。通血脉为药效语，非脉象，全段属主治与服食法，无脉象要素。", []], "27256": ["病机", "原文未出脉名，而论“多食损血脉，滑精气，痿阳气”，指出过食肥甘可损伤血脉、耗散精气、痿弱阳气。血脉受损则脉道不充，精气滑泄则脉失根本，阳气痿弱则鼓动无力，故虽无脉形描述，实寓脉道虚损之机。妇人“多食即发带疾”，亦由精气滑泄、阳气不固，带脉失约所致，与脉之虚滑无力相应。", []], "27257": ["治法", "本段为药物主治，未及脉象。文中“逐水气，利小便，破积血，复血脉”“通乳汁”“利女人经脉”等，皆示此药能调血脉、通经隧。水气去则脉道通利，积血破则脉行无阻，乳汁通、经脉利则气血和畅。所主诸症多与血脉壅滞或不足相关，故其取效之由在复血脉、利经隧，非据脉立论。", []], "27258": ["治法", "原文未出脉象，专述药之主治安“益气脉，和五脏，调经络”。益气脉者，补脉中气血之不足；和五脏、调经络者，使脏腑之气归于和平、经络之运行复其常度。脉为血之府，气充则脉盈，五脏和则脉气有根，经络调则脉道通利。此从药效反推，示虚损脉弱、经络不和者可用，非直接论脉。", []], "27259": ["治法", "本段未言脉象，而列药之主治安“壮血脉，益颜色，实五脏，化谷食，止泄”“宽胸下气，凉血，消积进食”。壮血脉、凉血，示其能充养脉道、清血中燥热；实五脏、化谷食，则气血生化有源，脉得所养。所治消渴、泄满等症，多由脾胃虚弱、血脉不充或血热所致，故药效在壮血脉以复脉之充盈。", []], "27260": ["治法", "原文未出脉名，主治中“通血脉，和五脏，好颜色”为关键。通血脉则脉道无壅滞，和五脏则脉气有根本，好颜色则血充于脉而外荣。又“益气，止烦止渴止泄”“补中，壮筋骨，益肠胃”，皆示补益中气、资生气血之功。气血充则脉自和，故所主诸症多属中气不足、血脉不和之候，药能通脉和脏以复其常。", []], "27261": ["病机", "原文未出脉象，而言其“性寒，有小毒，发故疾。久食昏五脏，令人好睡，缓人筋骨，绝血脉”。绝血脉者，言久食此物耗伤血脉，使脉道空虚或痹阻不通；缓人筋骨、昏五脏，则阳气不振、脏腑气机壅滞。血脉既绝，脉当见细弱或涩滞。小儿多食“令久不能行”，亦由血脉筋骨失养，与脉道虚损之机相合。", []], "27262": ["病机", "原文引小续命汤注“中风筋急拘挛，语迟脉弦者，加薏苡仁”，并释为“扶脾抑肝之义”。脉弦主肝木偏旺、筋脉拘急，中风筋急拘挛正是肝风内动、筋脉失柔之象；语迟则脾虚痰滞。薏苡仁属土入阳明，健脾以抑肝木，土旺则木有所制，弦脉可缓。故弦脉在此示肝强脾弱、筋脉拘急之病机。", ["弦"]], "27263": ["治法", "本段为薏苡仁粥方，未出脉象，主治“久风湿痹，补正气，利肠胃，消水肿，除胸中邪气，治筋脉拘挛”。久风湿痹、筋脉拘挛，其脉多弦紧或濡缓，示风湿痹阻、筋脉失养；补正气、利肠胃，则针对正虚湿滞。粥食日日服之，扶正祛湿并行，使正气复、湿邪去，则筋脉拘挛得舒，脉之弦紧可渐和。", []], "27264": ["其他", "本段为药物主治记载，未涉及脉象。所述“通关脉”“治风痹瘫缓”等，提示该药有通利血脉、祛风解毒之功，然无脉象可析，故病机分析从略。", []], "27265": ["其他", "本段为方剂主治，未言脉象。周痹在血脉之中，随脉上下，故治以大豆蘖散，益气出毒，通利血脉。无脉象可据，病机分析从略。", []], "27266": ["病机", "本段论赤小豆药性，未及脉象。其性下行，通小肠，入阴分，治有形之病，故能行津液、利小便、消胀除肿。久服则降令太过，津血渗泄，令人肌瘦身重，此即药过伤正之病机。", []], "27267": ["主病", "狐惑病脉数，无热微烦，默默欲卧，汗出，此湿热内蕴，邪正交争，故脉数；湿热蒸腐，酿脓于内，故目赤如鸠眼，四眦黄黑。脉数主热，此热非表热，乃内腐成脓之热，故以赤豆当归散渗湿排脓。", ["数"]], "27268": ["其他", "本段为绿豆主治记载，未涉及脉象。所述消肿下气、压热解毒、利小便胀满等，皆从药性推论，无脉象可据，故病机分析从略。", []], "27269": ["病机", "本段论绿豆药性，未及脉象。绿豆色绿属木，通厥阴、阳明，性平，消肿治痘同赤豆而压热解毒力过之，且益气厚肠，通经脉，无久服枯人之忌。其病机在清解阳明热毒，通利经脉。", []], "27270": ["其他", "本段为粟主治记载，未涉及脉象。补五脏、调中、助十二经脉、暖肠胃，皆言其补益之功，无脉象可析，故病机分析从略。", []], "27271": ["主病", "伤寒初觉头痛身热，脉洪，一、二日，此邪在表，正气奋起抗邪，故脉洪；洪为阳脉，主热盛，然邪尚在表，故以葱豉汤发汗解表。脉洪在此示表热壅盛，非里实之洪大，故取轻宣透邪之法。", ["洪"]], "27272": ["其他", "本段为谷类（饭）的主治记载，非脉学内容。原文述其\"补五脏，涩肠胃\"\"通血脉\"\"暖五脏六腑之气\"，皆言食疗功用，未涉脉象。所主病机为脾胃虚寒、肠胃不固及血脉不畅，故以补中益气、涩肠止泄、通血脉为治，与脉诊无关。", []], "27273": ["其他", "本段述酒的主治，非脉学原文。\"通血脉，厚肠胃，润皮肤，散湿气\"\"养脾气，扶肝，除风下气\"，指酒能行药势、温通血脉、散寒湿。所主病机为气血瘀滞、湿气内阻、脾虚肝郁，借酒之辛温以行药力，非据脉象辨证。", []], "27274": ["其他", "本段为药酒方的主治与制法，非脉学内容。\"润五脏，和血脉\"\"除五劳七伤\"，言久服可补虚损、调血脉。所主病机为五脏虚损、血脉不和，属补益调理之法，原文未及脉象，故不能以脉学病机论之。", []], "27275": ["其他", "本段为地黄酒方的主治，非脉学原文。\"补虚弱，壮筋骨，通血脉，治腹痛\"，指地黄酒能补虚通脉。所主病机为虚弱、筋骨不健、血脉瘀滞而腹痛，属补虚通脉之剂，原文无脉象描述，不涉脉诊辨证。", []], "27276": ["其他", "本段为当归酒方的主治，非脉学内容。\"和血脉，坚筋骨，止诸痛，调经水\"，言当归酒能和血止痛、调经。所主病机为血虚血滞、经脉不利、经水不调，属养血活血之法，原文未提脉象，故非脉学病机分析。", []], "27277": ["其他", "本段为石菖蒲酒方的主治，非脉学原文。\"治三十六风，一十二痹，通血脉，治骨痿\"，指石菖蒲酒能祛风通痹、通血脉。所主病机为风邪痹阻、血脉不通、骨痿不用，属祛风通络之剂，原文无脉象，不涉脉诊。", []], "27278": ["其他", "本段为通草子酒方的主治，非脉学内容。\"续五脏气，通十二经脉，利三焦\"，言通草子酒能通利经脉三焦。所主病机为五脏气机不畅、十二经脉阻滞、三焦不利，属通利之剂，原文未及脉象，不能作脉学病机解。", []], "27279": ["其他", "本段为菜类（如薤）的主治记载，非脉学原文。\"温中下气，补虚益阳，调和脏腑\"\"归肾壮阳，止泄精\"\"治胸痹骨痛\"，所主病机为脏腑虚寒、阳气不足、胸痹气滞，属食疗温补通阳之法，原文无脉象描述，不涉脉诊辨证。", []], "27280": ["病机", "右脉甚涩、关脉沉，涩主血行滞涩，沉主病在里。原文谓食后屈曲下膈、硬涩微痛，乃污血在胃脘之口，气因郁而成痰，隘塞食道。血瘀于胃口则脉涩，气郁痰阻于中焦则关脉沉，故涩沉并见，主瘀血痰气交阻之噎膈痛证。", ["涩", "沉"]], "27281": ["其他", "此段释葱名物，兼释芤字芤脉之名源，谓芤者草中有孔，故字从孔，芤脉象之。原文以葱之外直中空比类芤脉中空之象，非论病机主病，仅借物形以明脉形，故列其他，脉素取芤字。", ["芤"]], "27282": ["病机", "少阴病下利清谷、里寒外热、厥逆脉微，微为阳气衰微之象。成无己谓肾恶燥，急食辛以润之，葱白辛温通阳。脉微正示阴寒内盛、阳气不能外达，故用白通汤内用葱白以通上下阳气，脉微在此标示阳虚寒盛之病机。", ["微"]], "27283": ["预后", "阴毒腹痛、厥逆唇青卵缩、六脉欲绝，乃阴寒极盛、阳气欲绝之危候。原文以葱熨脐上，视手足温有汗为瘥，熨而手足不温则不可治。六脉欲绝示生机将息，故本段主旨在于凭脉症判断预后吉凶，非泛论主病。", []], "27284": ["其他", "此段述久食薰物伤神损性、令人多忘、损目明、绝血脉、发痼疾，并言患胡臭䘌齿者食之转甚。原文未出具体脉象，只言绝血脉，指久食耗伤血脉，非脉诊主病之论，故列其他，脉素从缺。", []], "27285": ["主病", "胸痹痛彻心背、喘息咳唾短气，寸脉沉迟、关脉弦数。寸沉迟示上焦阳微、胸阳不振，关弦数示中焦气郁化热、痰气交阻。阳微阴弦，痰浊痹阻胸阳，故主胸痹刺痛，原文谓不治杀人，明其证重。", ["沉", "迟", "弦", "数"]], "27286": ["主病", "时气温病初得，头痛壮热而脉大。脉大示邪热亢盛于外，正气尚能抗邪，故初起即见壮热头痛。原文以小蒜杵汁顿服取效，脉大在此标示温病初起热势鸱张之病机，属主病脉象。", ["大"]], "27287": ["其他", "此段载产后肉线垂出及脉溢怪症两则。脉溢者毛窍血出不止、皮胀如鼓、目鼻口被气胀合，原文未出脉象，只以脉溢名症，谓气胀血溢之怪病，非脉诊主病之常论，故列其他，脉素从缺。", []], "27288": ["主病", "本段为《别录》等诸家对某药主治的汇集，未及脉象。所述寒冷腹痛、中恶霍乱胀满、风邪诸毒、腰肾冷疼、转筋吐泻、心下寒痞等，皆属寒邪内盛、阳气不布、气血凝滞之病机；通四肢关节、宣诸络脉、破血去风，则示寒凝可致络脉壅滞。诸症以寒、冷、痛、胀、吐泻为纲，与沉寒痼冷、气机逆乱相应。", []], "27289": ["病机", "原文虽未明言脉名，然“肾中无阳，脉气欲绝”正是脉象描述，指脉来微弱欲绝，主肾阳衰败、阴寒内盛。干姜辛温，通心助阳、去脏腑沉寒痼冷、发诸经寒气，故姜附汤、四逆汤、理中汤用之回阳。脉气欲绝与手足厥冷、下利清谷等症相应，皆因阳衰不能鼓动血脉、温煦四末。", []], "27290": ["病机", "原文言“血脱色白而夭不泽脉濡者，此大寒也”。血脱则色白不泽，脉当细弱，今见濡脉，濡为浮细而软，主气血不足兼湿，然朱氏断为“大寒”，是着眼于寒伤阳气、血不得温而脉道软弱无力。故用干姜辛温益血、大热温经，使寒去阳复、血得温养，脉濡自复。此以脉濡辨大寒，属凭脉断病机。", ["濡"]], "27291": ["主病", "斑豆服凉药过多，损伤阳气，致手足厥冷而脉微。微脉极细极软、按之欲绝，主阳衰气微、无力鼓动血脉。凉药过服伤中阳，阳不达于四末则厥逆，阳不运于脉道则脉微。故用炮干姜温中回阳、炙甘草益气和中，即甘草干姜汤意，以复其阳。脉微与厥冷并见，正是阳虚内寒之确证。", ["微"]], "27292": ["主病", "本段述某药主治胸膈中臭烂恶邪气，利肠胃、通血脉、续不足气，未涉脉象。其病机在于秽浊恶邪壅阻胸膈，肠胃不利、血脉不通、正气不足。药能辟秽化浊、通利血脉、补益不足之气，故所主为秽浊内阻兼正气亏虚之证，与胸膈满闷、肠胃不和、血脉瘀滞诸候相应。", []], "27293": ["主病", "本段汇集诸家主治，未言脉象。消谷、治五脏、补不足、利大小肠、通小腹气、拔四肢热、止头痛、疗沙疹豌豆疮不出，示其病机涉及脾胃不和、热郁肌表、疹毒不透、肠风下血等。作酒喷之立出，是借酒性辛散以透疹；辟飞尸鬼疰蛊毒，则取其芳香辟秽。诸症与气机壅滞、热毒郁表相应。", []], "27294": ["主病", "本段述某药主治女子赤沃、止血养精、保血脉、益气，又去伏热、杀石药毒、去小儿暴热及酒后热、鼻塞身热、头中风热。未及脉象。其病机一为血分伏热、迫血妄行而致赤沃出血，二为热郁上焦而鼻塞身热、头中风热。药能凉血止血、养精保脉，兼清伏热，故与血热出血及上焦郁热诸症相应。", []], "27295": ["主病", "原文仅“脉溢”二字，出苏恭《新修本草》，为某药主治之一。脉溢指脉道充盈太过、血溢于外之病机，多因热盛迫血或气逆血壅所致。此段极简，未言具体症候，然“脉溢”本身即示血热妄行、脉络胀满之候，药能治之，当有清热凉血、收敛血脉之功，与出血、脉胀等症相应。", []], "27296": ["病机", "原文未出脉名，而言兰香多食则“壅关节，涩营卫，令人血脉不行，又动风，发脚气”。涩营卫即营卫运行滞涩，血脉不行为气血痹阻之机；壅关节则湿浊留著，动风发脚气乃辛温偏胜、走窜为患。此段从过食致病立论，说明血脉不行与脚气之由，非脉象主病。", []], "27297": ["病机", "时珍引罗天益“兰香味辛气温，能和血润燥”，又质疑掌禹锡“多食涩营卫，血脉不行”。全段辨兰香辛温能通能润，与过食致涩相对，重点在营卫血脉之通涩，非论脉。所谓涩营卫，即营卫不利、血脉不畅之病机，故列病机。", []], "27298": ["治法", "原文述某药“通血脉，开胸膈，下气调中，止渴润燥”，根尤良。通血脉、开胸膈即宣通气血壅滞，下气调中即理气机，止渴润燥即润津亏。全段为药物主治功用，属治法范畴，未涉脉象，故脉象要素为空。", []], "27299": ["治法", "原文主治“通经脉，下气，开胸膈”，出自《正要》。通经脉即畅达血脉，下气、开胸膈即降逆宽胸，针对经脉不通、气机壅塞胸膈之证。此为药物功用记载，属治法，非脉诊病机，故脉象要素为空。", []], "27300": ["治法", "原文列某药主治“五脏邪气，厌谷胃痹”，久服安心益气、调十二经脉，又治霍乱后胃气烦逆、肠澼渴热、疔肿痈疡、血淋痔瘘等。调十二经脉即和畅经脉气血，厌谷胃痹即胃气痹阻。全段为药物主治，属治法，未出脉象。", []], "27301": ["治法", "原文为单方：“血脉不调：苦荬菜晒干，为末。每服二钱，温酒下。”血脉不调即气血失和、经脉不畅之病机，以苦荬菜末温酒调服治之。此属治法条目，非脉象主病，故脉象要素为空，主旨归治法。", []], "27302": ["治法", "原文主治“补筋骨，利五脏，开胸膈壅气，通经脉，止脾气”，又解热毒、酒毒，止消渴，利大小肠。通经脉、开胸膈壅气即宣通气血壅滞，利五脏、补筋骨即调补脏腑。全段为药物功用，属治法，未涉脉象。", []], "27303": ["治法", "原文主治“利五脏，通经脉，开胸膈，功同白苣”。通经脉即畅血脉，开胸膈即宽胸降气，利五脏即调脏腑。此段为药物主治功用，属治法范畴，原文未出脉名，脉象要素为空。", []], "27304": ["治法", "本段为丝瓜主治条目，未涉脉象。原文述丝瓜烧存性可治痘疮不快，煮食除热利肠，老者去风化痰、凉血解毒、杀虫通经络、行血脉、下乳汁，治二便下血、痔漏崩中、疝痛卵肿、痈疽疮肿、痘疹胎毒，并暖胃补阳固气和胎。其病机核心在热毒壅滞、血瘀络阻，故以凉血解毒、通络行血为治，非凭脉辨证。", []], "27305": ["病机", "时珍以丝瓜老者筋络贯串、房隔联属之形，类比人身脉络脏腑，故谓其能通人脉络脏腑而去风解毒、消肿化痰、祛痛杀虫及治诸血病。此段借物形推论药性，所主病机为风毒痰瘀阻于脉络、血行不畅，属以络通络之思路，原文未及脉象，故脉素从缺。", []], "27306": ["治法", "本段为经脉不通之方治，干丝瓜为末，白鸽血调饼，空心酒下，先服四物汤三服。经脉不通主血虚而瘀、冲任不畅，先服四物汤养血活血以固其本，继用丝瓜通络、鸽血行血、酒性温通以开其闭。原文未载脉象，全从病症立方，属通经活血之治法。", []], "27307": ["病机", "本段治水蛊腹胀，取老丝瓜象人脉络，借其气以引药入络；巴豆逐水，陈仓米收胃气，三药合用逐水而不伤中。水蛊腹胀病机为水湿壅盛、隧道不通，故以逐水通络为法。原文以“丝瓜象人脉络”说明引经之理，未言脉象，脉素从缺。", []], "27308": ["病机", "本段言野田菌子有毒杀人，食之发冷气、腹中微痛、发五脏风、拥经脉、动痔病，令人昏昏多睡、背膊四肢无力。其病机为毒菌之气壅遏经脉、风冷内动、阳气不振，故见嗜睡乏力、腹痛痔动。原文未及脉象，所述为食毒致病之机，非脉诊内容。", []], "27309": ["病机", "原文以“脉浮者属气，脉沉者属血”分便秘之气血。浮主气分，故昼便难属阳气不行，用杏仁、陈皮降气润燥；沉主血分，故夜便难属阴血不运，用桃仁、陈皮活血润肠。手阳明与手太阴表里，贲门主往来、魄门主收闭，共为气之通道，故均佐陈皮。此以浮沉定气血病位，虚人便闭不可过泄。", ["浮", "沉"]], "27310": ["主病", "原文治咳嗽寒热、旦夕加重、少喜多嗔、面色不润、忽进忽退、积渐少食而“脉弦紧者”。弦主气机郁滞、饮邪内结，紧主寒邪束表、痛与寒盛，弦紧并见说明寒饮郁肺、气逆不降，故咳而寒热起伏、纳少面悴。方用杏仁宣降肺气，童便浸制以润降，酒下助行，妇人室女尤宜，示其病机偏于气血郁滞。", ["弦", "紧"]], "27311": ["治法", "本段治目中赤脉痒痛、时见黑花，用初生杏子仁合古五铢钱密封埋门限下化水点眼。赤脉痒痛属肝经风热上攻目络，黑花时见为目络不畅、精明被扰。取杏仁润降、钱币重镇，埋化取水以点目，属外治点眼之法。原文未载脉象，脉素从缺。", []], "27312": ["其他", "本段为药物主治汇录，未涉脉象。原文列“下气，除热烦满，安心，止肢体痛，偏枯不仁，死肌”等，皆属药效所治之症，非据脉辨证。所主病机为热烦满、气血壅滞致偏枯不仁、死肌，及肺肠不固之久嗽泻痢。无脉象可析，故脉象要素为空，主旨归其他。", []], "27313": ["主病", "原文“治伤中筋脉急，上气咳嗽”，脉急与筋脉拘急相应。急脉主筋脉挛急、气机上逆，故见上气咳嗽；伤中则中气受损，筋脉失养而拘急。方用枣肉酥煎含咽，润养筋脉、缓急止咳，正对脉急所主之筋脉紧急、肺气上逆病机。", ["急"]], "27314": ["其他", "本段述中蛊腹痛、面目青黄、淋露骨立之主治，未载脉象。所主病机为蛊毒内结、气血耗伤，故面目青黄、骨立；煎服取吐以排毒，通经脉以行气血。无脉象原文，脉象要素从空，主旨属其他（药物主治），不归主病或病机。", []], "27315": ["病机", "原文“脉息和平”指脉象调和无病。杨吉老诊士人“热症已极，气血消铄”，虽脉息和平，实为热极伤阴、气血暗耗之候，故预言“三年当以疽死”。此段借平脉反衬热毒内伏、气血消铄之病机，说明脉和平未必无病，须合症参辨。", ["和平"]], "27316": ["其他", "本段为药物主治，述煮汁止霍乱吐下转筋、疗脚气，枝利筋脉，根叶淋足已蹶。未出脉象。所主病机为霍乱吐下伤津、筋脉失养而转筋，及湿浊下注之脚气。无脉可辨，脉象要素为空，主旨归其他。", []], "27317": ["病机", "原文“发毒热，秘大小肠，聚胸中痰，壅涩血脉”，未载脉象。所主病机为毒热内发、二便闭塞、痰聚胸中、血脉壅涩，属热毒痰壅、气血不畅之实证，故“不宜多食”。无脉象原文，脉象要素从空，主旨归病机。", []], "27318": ["主病", "原文“主妇人经脉不通，丈夫营卫中血脉不行”，未出脉象。所主病机为血脉瘀滞、营卫不行，故妇人经闭、男子营卫壅阻。食之止渴、久食不饥，亦示其能通利血脉、充养营卫。无脉象可录，脉象要素为空，主旨归主病。", []], "27319": ["病机", "原文“多食令人百脉弱”，脉弱为气血不足、脉道不充之象。酸苦平涩之品过食，耗伤气血，致百脉失养而弱，故脉弱主气血虚衰、脉道不充之病机。此段以脉弱说明过食伤正、百脉虚弱，非外邪所致。", ["弱"]], "27320": ["病机", "原文言多食发热及冷痰涩气，致人好唾、生疮疖、闭百脉。此非论脉，而言饮食失节、冷热错杂，痰气壅滞，百脉闭塞之病机。'闭百脉'点明气血壅遏不通，故生疮疖；'冷痰涩气'示寒痰凝滞、气机涩滞，令人好唾。其子食之令人烦心，亦由气机壅滞、郁热扰心所致。", []], "27321": ["其他", "原文列主治：通耳鼻气、治肠澼不足、解酒毒、压胃间热、止口干、续经脉气。此非论脉，而言药食之功。'续经脉气'指其能续接、调畅经脉之气，针对经脉气弱或断续之病机；'压胃间热'示清降胃热；'治肠澼不足'示固肠止利。诸症皆由气机失调、经脉失续所致。", []], "27322": ["病机", "原文辨咳逆为气自脐下冲脉直上咽膈，作呃忒蹇逆之声。分两类：一为伤寒吐下后及久病产后、老人虚人，阴气大亏、阳气暴逆，自下焦逆上焦而不能出；一为伤寒失下及平人痰气抑遏。'阴气大亏''阳气暴逆''痰气抑遏'点明虚实阴阳之异，故治当视虚实或温补或泄热降气。", []], "27323": ["其他", "原文辨橘、柚、柑三者相类而不同，详其果实大小、瓣味、皮色厚薄及树形叶花。'脉瓣隔皮可数'系描述橘瓣纹理可隔皮指数，非论脉象。全段旨在物类鉴别，纠苏颂以青橘为柚之误，与医理病机无涉，故归其他。", []], "27324": ["其他", "原文辨橘皮、柑皮、柚皮之纹色厚薄及性味温冷，言橘皮性温，柑、柚皮性冷。'内多筋脉'指橘皮内筋络纹理，非脉象。又述橘皮入和中理胃药留白、入下气消痰药去白之法。全段为药材鉴别与炮制，非论病机脉象，故归其他。", []], "27325": ["其他", "原文辨柑与橘之异：柑皮色黄稍厚、理粗味不苦，橘可久留、柑易腐败，柑树畏冰雪。'脉不黏瓣'描述乳柑瓣膜不粘连，非脉象。全段述柑之产地、形态、品质，属果类物产鉴别，与医理病机无关，故归其他。", []], "27326": ["其他", "原文列主治：食之令人肥健、润肌、黑须发，利小便、去五痔，通润血脉、骨肉细腻，补气养血、润燥化痰、益命门、利三焦、温肺润肠，治虚寒喘嗽、腰脚重痛、心腹疝痛、血痢肠风等。'通润血脉'指其能润养通利血脉，针对血脉枯涩之机；诸效皆由补气养血、温润下焦所致。", []], "27327": ["病机", "原文论三焦为元气之别使、命门为三焦之本原，一原一委、一体一用。言命门藏精系胞，三焦出纳腐熟，其体白膜裹之，在七节之旁、两肾之间，下通二肾、上通心肺贯脑，为生命之原、相火之主。并斥《难经》以右肾为命门、高阳生《脉诀》承谬误人。全段阐命门三焦体用病机。", []], "27328": ["其他", "此段为服胡桃法及青娥丸方，未涉脉象。原文言常服令人能食、骨肉细腻光润、须发黑泽、血脉通润，养一切老痔，属食疗补养之论，非脉诊病机内容，故脉象要素为空，主旨归其他。", []], "27329": ["主病", "此段述药物主治，未及脉象。原文列除一切风、下一切气、通关节、利九窍、补五劳七伤、健脾调中、破症结，又主贲豚膀胱诸气、五膈气、风冷气、脚气、宿食不消，并治冲脉为病、气逆里急，皆属气血壅滞、冲脉上逆之病机，非脉象所主。", []], "27330": ["病机", "此段记消渴案，未出脉名，然言脾脉极热而肾气不衰。张肱断为果实酒物过度、积热在脾，故食多饮水、溺多，非真消渴。脾脉极热示中焦积热，肾气不衰则下元未败，土不制水之说出此，脉虽未详而病机在脾热。", []], "27331": ["其他", "此段仅言久食令人失明、伤血脉，未涉脉象。属饮食久服伤及血脉之戒，非脉诊内容，故脉象要素为空，主旨归其他，不可附会脉机。", []], "27332": ["主病", "此段为药物主治，未及脉象。原文列邪气咳逆、温中、逐骨节皮肤死肌、寒湿痹痛、下气，又除六腑寒冷、心腹留饮宿食、肠澼下痢、散风邪瘕结、水肿黄疸，久服开腠理、通血脉，皆属寒湿风邪壅阻、气血不通之病机，非脉象所主。", []], "27333": ["病机", "此段引好古论冲脉为病，逆气里急，宜此主之，未出脉象。冲脉起于胞中，上逆则气逆里急，故以吴茱萸汤、当归四逆汤温脾胃、治厥阴。原文以冲脉病机立论，非凭脉断病，脉象要素为空。", []], "27334": ["其他", "此段为肝劳生虫、眼中赤脉之方，未涉脉象。原文以吴茱萸根为末，合粳米、鸡子白、化蜡为丸，米汤下取虫，属虫病治法方药，非脉诊病机，故脉象为空，主旨归其他。", []], "27335": ["治法", "此段引张机论吐法诸证：寸脉微浮主胸中有寒，脉微弱主夏月伤冷水、水行皮中，脉紧不大主膈上有痰，寸口脉微弦主胸上诸实。微浮、微弱示邪浅正伤，紧不大示痰结，微弦示气逆，皆邪在上焦可吐之征，故并宜瓜蒂散，惟亡血虚家禁之。", ["微", "浮", "紧", "弦"]], "27336": ["病机", "原文以“上部有脉，下部无脉”言饮食填塞胸中、食伤太阴，风木生发之气伏于下，故主吐法以达木郁；又戒“尺脉绝者不宜用此”，恐损真元、胃气不复。脉象虽未明写，实以寸尺上下之有无论气机升降与胃气存亡，属病机与治法禁忌之辨。", []], "27337": ["病机", "太阳中暍见身热头痛而“脉微弱”，非表实热盛，乃夏月伤冷水、水行皮中所致。水湿郁遏阳气，脉道不充，故微弱；身热头痛为暑湿郁于表。脉弱正提示里气不足、水气偏渗，故用瓜蒂取吐以去水湿，非峻汗伤正。", ["微", "弱"]], "27338": ["其他", "此段为药物主治，言补中养神、益气力、除百疾，主五脏不足、伤中气绝、益十二经脉血气。未及脉象，主旨不在诊脉辨证，而在药性功用与补益经脉血气之效，故归其他，不可强附脉象病机。", []], "27339": ["其他", "时珍述藕之形态与生生之性，言“以续生生之脉”，此“脉”指植物续生之脉络，非诊候之脉。所主皆心脾血分之疾，与莲功稍异。全段论药性归经，未涉病脉，故不取脉象要素，归其他。", []], "27340": ["其他", "此段以血淋、冷痢二案发明藕节功用：藕汁调发灰止血淋，藕节捣烂热酒调治食蟹冷痢。严防御诊脉断“此冷痢也”，然原文未载具体脉象，主旨为药效验证与藕消瘀血、解热开胃、解蟹毒，故归其他。", []], "27341": ["其他", "此段列桂之主治：利肝肺气、通血脉、补下焦不足、治沉寒痼冷、益火消阴等，并及桂心修制与伪充之辨。全段论药性功用与禁忌，未言脉象，主旨不在脉诊病机，故归其他，脉象要素从缺。", []], "27342": ["其他", "此段续列桂之主治：心痛胁痛胁风、温筋通脉、止烦出汗、去冷风疼痛、开腠理解表发汗、去皮肤风湿、散下焦血、利肺气、横行手臂治痛风。皆言药效与所治症候，未及脉象，故归其他。", []], "27343": ["病机", "原文举仲景桂枝汤治伤寒表虚，涉及“脉浮紧”“脉浮缓”“脉弱”等。浮紧为伤寒表实无汗，浮缓为太阳中风表虚汗出，弱为阴弱汗自出。桂辛甘发散，调其血而汗自出；无汗不得服桂枝，汗多者用桂枝甘草汤闭汗，一药二用，皆随脉证虚实而异。", ["浮", "紧", "缓", "弱"]], "27344": ["其他", "此段为辛夷等药的主治记载，未涉脉象。原文述其“温中解肌，利九窍，通鼻塞涕出”，治“面肿引齿痛，眩冒身兀兀如在车船之上”，皆因鼻气不通、阳明经气壅滞所致；又“通关脉”一语，指药能宣通鼻窍脉络，非论脉诊。故本条主旨为药物主治，非脉象病机。", []], "27345": ["病机", "时珍引“鼻气通于天”，以头、肺应天，阐明鼻窍与肺气相通；“肺开窍于鼻”点明鼻病根在肺；“阳明胃脉环鼻而上行”说明鼻部又赖胃经气血濡养。此段从脏腑经络立论，解释鼻塞、鼻渊等症之病机，非言脉象，故脉象要素为空。", []], "27346": ["其他", "藏器辨沉香与煎香之别，以“枝节不朽，沉水者为沉香”为正品，“肌理有黑脉，浮者为煎香”为次品。文中“黑脉”指木肌纹理，非脉诊之脉；鸡骨、马蹄皆属煎香，“止可薰衣去臭”，无药用之功。全段为药材鉴别，与病机脉象无关。", []], "27347": ["其他", "此段述沉香产地及分类，文中“脉凝结自朽出者”“脉结聚者”之“脉”指木心纹理结聚，非诊脉之脉象。颂引《南越志》辨沉香、鸡骨、青桂、栈香、黄熟、马蹄六物同出一树，以坚黑沉水、半浮半沉、细枝紧实等形质分精粗，属药材鉴别，非论病机。", ["结", "聚"]], "27348": ["治法", "此条为口目㖞斜的外治法，用乳香烧烟熏患处，“以顺其血脉”。㖞斜多因风邪中络、血脉痹阻，气血不能上荣面部而致；熏法借药气直达病所，温通局部血脉，使气血复顺。原文未言脉象，故脉象要素为空，主旨属治法。", []], "27349": ["误治", "杲论龙脑之用，谓“风病在骨髓者宜用之”，因龙脑入骨能搜风；若“风在血脉肌肉”而辄用脑、麝，则药力引风深入骨髓，“如油入面，莫之能出”。此段辨病位浅深与用药宜忌，指出病浅药深反致引邪内陷，属误治之戒，未涉脉象。", []], "27350": ["其他", "此段汇集诸家对黄柏的主治论述，未及脉象。原文“五脏肠胃中结热”为诸症总纲，黄疸、肠痔、泄痢、漏下赤白皆由湿热结聚所致；元素谓“泻膀胱相火，补肾水不足”，李杲谓“泻伏火，救肾水，治冲脉气逆”，皆从清热泻火、坚阴补肾立论，属药物主治。", []], "27351": ["病机", "厚朴煎丸条引孙兆“补肾不如补脾”，以脾胃气壮则能饮食、益营卫、养精血、滋骨髓，申《素问》“精不足者补之以味，形不足者补之以气”之义。方用厚朴、生姜、干姜、甘草温中降气、化痰进食，治冷饮呕吐泄泻。原文脉象仅标“脉数”二字，然通篇重在脾胃虚损之病机与补脾之法，脉数当为虚损兼热之象。", ["数"]], "27352": ["其他", "此段论椿芽多食之害，非诊脉之文。原文谓多食\"动风\"，熏十二经脉、五脏六腑，致\"神昏血气微\"，乃风动而气血受扰之象；和猪肉热面频食则\"中满\"，因\"壅经络\"、气机不通。所主在饮食偏嗜致经络壅滞、血气失调，与脉象无涉，故脉象要素为空。", []], "27353": ["其他", "此段为干漆主治，非论脉。原文言其\"消瘀血痞结\"、\"削年深坚结之积滞，破日久凝结之瘀血\"，主女子疝瘕、经脉不通，皆属瘀血坚结之病机；又疗咳嗽、传尸劳、杀三虫，是取漆之破积杀虫。全段重在药性攻破瘀滞，未及脉候，故脉象要素为空。", []], "27354": ["其他", "此段列药之主治病症，非脉诊内容。原文主霍乱中恶、赤白久痢、疳䘌疥癣、牙齿虫痛，又主\"腰脚不遂，血脉顽痹，腿膝疼痛\"，其病机在湿浊虫毒内蕴、血脉痹阻不通。所治皆邪实壅滞之候，未言及脉，故脉象要素为空。", []], "27355": ["其他", "此段述药之主风化痰功用，非论脉。原文主\"一切风，化涎，肝脏风，筋脉抽掣\"，及急风口噤、四肢不收顽痹、毒风周身如虫行、破伤风口眼偏斜、腰脊强硬，皆风邪痰涎壅阻经络、筋脉失养之病机。全段以风痰立论，未涉脉象，故脉象要素为空。", []], "27356": ["病机", "此段论疠风病机，非直接言脉而寓脉理。原文谓\"疠风乃营气热，风寒客于脉而不去\"，营热内蕴、风寒外客，邪留血脉，故当见脉浮数或弦紧之象；治以桦皮散、泻青丸\"缓疏泄血中之风热\"，佐二圣散下虫，正是针对邪客血脉、血热生虫之机。戒房室三年，示其病深根固。", []], "27357": ["其他", "此段为药之主治，非脉诊。原文言\"疗肠胃邪热气，消肿，治小儿头疮痂疕\"，又\"通经脉\"，其病机在邪热壅于肠胃、经脉不通，故以药清泄邪热、通利经脉。所述皆邪热壅滞之候，未及脉象，故脉象要素为空。", []], "27358": ["病机", "此段论榆皮滑利下降之性，非直接言脉而含脉理。原文谓其治\"小便不通，五淋肿满，喘嗽不眠，经脉胎产诸症\"，取\"滑可去著\"、\"利窍渗湿热，消留著有形之物\"，是湿热留著、气壅有形之病机，脉当见滑实；又戒\"胃寒而虚者\"久服泄真气，示虚寒者脉必弱，不可妄渗。", []], "27359": ["其他", "此段列药之主治，非论脉。原文疗女子月闭烂胎、金疮脓血，治十种水肿、痿痹，又\"通宣一切病，泄壅滞，除风补劳，健脾开胃，消痰破血，排脓消肿毒\"，其病机在壅滞不通、痰瘀水湿互结。所主皆邪实壅滞之候，未言脉象，故脉象要素为空。", []], "27360": ["病机", "脉沉而滑，沉主里、主寒积内凝，滑主积滞痰实。老妇溏泄五年，肉食生冷即痛，服调脾升提止涩反甚，正是脾胃久伤、冷积凝滞于里，非虚寒滑脱。沉滑示积滞内实，故王太仆谓大寒凝内、久利溏泄愈而复发，法当以热下之，寒去则利止。", ["沉", "滑"]], "27361": ["预后", "泻痢见脉浮洪者，浮为邪盛于外、洪为热盛气张，正虚不甚而邪势方炽，故多日难已；脉微小者，小为邪退、微为气和，正能胜邪，故服之立止。此以脉之浮洪与微小对举，辨泻痢之难已与易止，属预后判断，非言具体病机。", ["浮", "洪", "微", "小"]], "27362": ["其他", "本段纯列主治功用，未及脉象。所言伤中、五劳六极、羸瘦、崩中绝脉，皆虚损之候；去肺中水气、水肿腹满胪胀，则水气壅盛；唾血热渴、肺气喘满，为肺热络伤。诸证或虚或实，皆统于补虚益气、利水道、泻肺降气之功，非凭脉断病。", []], "27363": ["主病", "带下而脉数，数主热。带下本属湿浊下注，脉数则示湿郁化热、热扰冲任，故以枸杞根、生地黄酒煮常服，取清热凉血、滋阴制火之意。原文只言脉数，未及兼症，然数脉在此为带下之热象，是辨其属热而非属寒之据。", ["数"]], "27364": ["其他", "本段列主治大风、头面手足诸风、癫痫狂痉、湿痹寒冷疼痛，及四肢不遂，皆风邪为患、血脉不通之候。通血脉、明目益精光，则示其能行血祛风。原文未出脉象，故无从以脉论病机，仅就所主诸风冷痹痛言其功用。", []], "27365": ["其他", "本段专言主治青盲肤翳、赤涩多眵泪、目中赤脉，及小儿麸豆疳气攻眼，皆目疾之属热属风者。消目中赤脉一语，点明其能清目络之热。原文未及脉象，故不能以脉推病机，只就所治眼病言其清热明目之功。", []], "27366": ["病机", "脉虚而弱、脉迟，虚弱为气阳不足，迟为阳运无力。茯苓淡渗利水，气薄升浮，能利小便、开腠理、生津除虚热止泻；然小便利或数者多服损目，汗多人服之损元气，正因虚弱迟之体本已阳衰津少，再渗则愈伤，故戒之。", ["虚", "弱", "迟"]], "27367": ["病机", "消渴而脉浮、小便不利、微热，浮为邪在表、水气不行于外，非里热消烁之消渴。仲景以猪苓散发其汗，多饮暖水，汗出即愈，是知此脉浮示水停太阳之表、气化不利，故治从汗解，与五苓散利水通阳同旨。", ["浮"]], "27368": ["其他", "此段为药物主治条文，未言脉象。原文列腰痛、小儿背强、痈肿、崩中、产后余疾、下乳汁、金疮、痹等，皆属桑寄生所主之症，非由脉象推得。所主病机为肝肾不足、血脉不充、胎元不固，故能助筋骨、益血脉、安胎、令胎牢固。无脉可析，归入其他。", []], "27369": ["主病", "原文言毒痢脓血而“六脉微小，并无寒热”。毒痢本多脉数实，今反微小且无寒热，说明毒邪虽留而正气已衰，气血不足鼓动无力，脉道不充。微小脉主虚，故以桑寄生、防风、川芎、甘草扶正兼疏邪，属正虚邪恋之毒痢，非实热壅盛之候。", ["微", "小"]], "27370": ["其他", "此段为附方，记肥脉瘾疹以帛拭之而愈，未载脉象。肥脉瘾疹指疹发成片、脉络浮显之皮肤病，属风热郁于肌表。原文仅述外治取效，无脉可据，故脉象要素为空，主旨归其他，不作病机推断。", []], "27371": ["其他", "此段为药物主治汇录，未言脉象。所列惊痫瘛疭、寒热邪气、癫疾、蛊毒、肠痔、恶疽附骨痈、疔肿恶脉、赤白痢、遗尿失禁、阴痿、瘰疬成瘘、风虫牙痛、乳痈恶疮等，皆属该药所疗之症，非凭脉断病。无脉象可析，归入其他。", []], "27372": ["预后", "原文言中蛊药毒“虽面青脉绝，腹胀吐血者，服之即活”。脉绝指脉气一时闭阻不至，非真脏气竭，故面青、腹胀、吐血虽危，尚可救治。此以脉绝判断毒盛气闭之危候，并示服药后可活，属预后判断，非平脉主病之论。", ["绝"]], "27373": ["其他", "此段为方药主治，未载脉象。经脉不通、症块胀满、腹有鬼胎，属瘀血内结、冲任阻滞；肺风白癞属风毒蕴肤。原文以葛上亭长破血攻毒，服后脐腹急痛为药力攻通之应。无脉可析，归其他。", []], "27374": ["兼症", "原文述蜘蛛咬伤后“有二赤脉绕项下至心前，头面肿如数斗”。赤脉绕项下至心前，是毒邪循脉络上攻、血脉壅盛外显之象，非诊脉所得，然其脉数可知。头面肿如数斗为毒盛之兼症，故归兼症，示毒邪走窜血脉、症情险恶。", ["数"]], "27375": ["其他", "此段为衣鱼化脉望之异说，李时珍辨其谬妄。文中“脉望”乃物名，非脉象；所述发卷两端滴水、夜持向天坠星求丹，皆志怪之言。无脉可析，主旨为辨正异说，归入其他，不作病机推断。", []], "27376": ["其他", "原文为药物主治，未及脉象。所述“心腹寒热洗洗”“血积症瘕”“月水不通”“破留血积聚”等，皆属瘀血内结、寒热错杂之病机；药能破坚下血闭、通乳脉、行产后血积，故所主在瘀滞实证，与症瘕积聚、经闭、产后瘀阻及小儿腹痛夜啼相应。", []], "27377": ["其他", "原文未载脉象，专述药之主病。所谓“瘀血症坚寒热，破积聚、喉咽闭，内寒无子”，指明瘀血坚结、寒热交争、气机闭阻之病机；通利血脉、食之下气，则针对血脉瘀滞与气逆不降，故主症瘕积聚、咽闭及内寒无子等证。", []], "27378": ["其他", "此段亦无脉象，言药效主治。“逐瘀血，破血积，坚痞症瘕，寒热，通利血脉及九窍”，核心病机为瘀血内结、痞坚成瘕，兼寒热错杂、血脉九窍不利。药以破血逐瘀为能，故所主与血积、坚痞、症瘕及九窍闭塞之候相应。", []], "27379": ["兼症", "原文以“筋脉拘急”为小儿慢惊风兼症，脉象写作拘急。慢惊由胃虚虫动、虚风内扰，心神闷乱而烦懊不安，筋脉失养故拘急反折、啼叫。脉拘急正反映虚风内动、筋脉挛急之病机，与惊风闷乱、反折啼叫等症相应，非独主一病。", ["急"]], "27380": ["病机", "时珍引“涩可去脱”，以龙骨收敛浮越之正气、固大肠而镇惊，又主带脉为病。涩脉主收摄固脱，此处借药性说明正气浮越、滑脱不禁之病机，如惊悸、大肠滑泄及带脉失约诸候；脉涩与固涩治法相合，属以脉药互证病机之论。", ["涩"]], "27381": ["其他", "原文未出脉象，列药之主病。所治“五邪，惊啼悲伤”“鬼魅悲泣”“痰疟寒热，风痹强直疼痛”及“通经脉，下乳汁，消痈肿，排脓血”，涉及惊邪神乱、痰疟寒热、风痹经隧不利、痈肿脓血壅滞等病机，故主症广泛，与惊啼悲泣、疟疾寒热、痹痛强直、乳汁不通相应。", []], "27382": ["兼症", "原文以“筋脉拘急”为中风湿痹不仁之兼症，脉象写作拘急。风中经络，气血痹阻，筋脉失濡，故拘急而口面㖞斜、半身不遂、骨节疼痛、脚弱不能久立。脉拘急反映风邪中络、筋脉挛急之病机，与风痹不仁、㖞斜不遂等症相应。", ["急"]], "27383": ["兼症", "原文于风瘫疠风诸症中列“筋脉挛急”，脉象写作挛急。诸风无新久，手足缓弱、口眼㖞斜、语言謇涩，皆风邪入络、气血痹阻所致；筋脉挛急正是风动筋急之象，与肌肉顽痹、皮肤燥痒、骨节疼痛同属风瘫疠风兼症，故脉挛急主风邪痹阻筋脉之病机。", ["急"]], "27384": ["其他", "此段为赤眼肿痛的外治方，鲤鱼胆配腻粉或黄连末点眼、贴目眦，原文未及脉象。所治在目，赤眼肿痛、飞血赤脉属肝经风热上攻、血热壅滞之候，故取胆苦寒清热、黄连泻火，外点以清局部郁热，非凭脉辨证之文。", []], "27385": ["其他", "此段为鱼类集解，述其形色生态，\"赤脉贯瞳\"乃状鱼体赤色纹理，非言人脉。原文无脉象可辨，亦不涉病机，仅作药物基原考订，故列其他，不可强解为脉诊内容。", []], "27386": ["病机", "此段主治言\"去水气\"\"治肝气不足，补肝明目，助血脉\"，虽无脉象，然所主病机在肝虚水气不化、血脉不畅。肝开窍于目，肝气不足则目暗，水气内停则需开胃下食以运之；\"灸疮不发\"者气血不充，食鲙助血脉以透发，皆从肝与水气立论。", []], "27387": ["其他", "此段为鳗鲡集解，述其形状、脂膏及\"背有黄脉者\"名金丝鳗鲡，\"黄脉\"指鱼背黄色纹路，非人身脉象。原文纯属药物基原与生态描述，无病机可析，故归其他，不作脉象推断。", []], "27388": ["病机", "时珍以鳝\"善穿穴，无足而窜，与蛇同性\"，故能\"走经脉疗十二风邪\"。风中血脉则口眼㖞斜，取鳝血主之，是\"从其类\"以通经隧。此段论药性入经脉、治风邪中络之病机，非论脉，然\"走经脉\"\"风中血脉\"点明病位在血络。", []], "27389": ["其他", "此段为龟之集解，述龟形象、甲文、任脉及灵寿之性，\"能运任脉\"言龟首藏腹通任脉之理，非诊人之脉。原文属药物基原与物性阐发，无脉象、无主病，故列其他。", []], "27390": ["病机", "时珍以龟首藏腹\"能通任脉\"、鹿鼻反尾\"能通督脉\"，分论龟甲补心肾血以养阴、鹿角补命精氣以养阳。末言\"龟甲所主诸病，皆属阴虚血弱\"，点明其病机在阴血亏虚，任脉失养，故取甲养阴，非凭脉断证。", []], "27391": ["病机", "此段主治诸风毒、邪热、胸膈风痰，行气血、镇心神、通妇人经脉。所主病机为风毒邪热内扰、痰阻胸膈、气血不畅、心神不宁及妇人经脉不通。原文未出脉象，然\"行气血\"\"通经脉\"点明气血壅滞、经脉不利为其要，故归病机。", []], "27392": ["其他", "此段为药物主治条文，未涉脉象。原文述其通任脉、助阳道、补阴血、益精气、治痿弱，并禁邪疟、辟蠹虫。所主病机为任脉不通、阳气不足、阴血精气亏虚致痿弱，及邪疟、蠹虫为患。因无脉象可凭，不能作脉学病机分析，仅录其主治功用备参。", []], "27393": ["其他", "此段为药物主治，未言脉象。原文载生研涂扑损筋脉伤，生捣罯蛇伤，以其食蛇也。所主病机为跌扑损伤致筋脉瘀滞，及蛇毒内侵。因无脉象描述，不能据脉析机，仅存其外治损伤、蛇伤之用，属本草主治内容，非脉学条文。", []], "27394": ["其他", "此段为药物主治汇集，未涉脉象。原文列心腹症瘕、坚积寒热、痞疾息肉、血瘕腰痛、症块痃癖、冷瘕劳瘦、骨节劳热、结实壅塞、妇人漏下、瘀血、症结恶血、疟母、阴毒腹痛、小儿惊痫、经脉不通、难产等。所主病机为瘀血痰积、症瘕结聚、寒热错杂、气血壅塞，因无脉象，不作脉学分析。", []], "27395": ["其他", "此段为药物主治，未载脉象。原文述涂脱肛，治风中血脉、口眼㖞僻、小儿疳劳潮热。所主病机为风邪入中血脉致口眼歪斜，中气下陷致脱肛，及小儿疳积劳热。因无脉象可据，不能作脉学病机推断，仅录其主治风入血脉、脱肛、疳劳潮热之用。", []], "27396": ["病机", "此段为发明药理，未直接言脉。原文引《千金方》云目𥆧唇动口㖞，皆风入血脉，急以小续命汤服之；又谓鳖血性急缩走血，故治口㖞、脱肛。所主病机为风邪入中血脉，筋脉失养而瞤动歪斜；血走急缩以敛脱肛。虽无脉象，然明言风入血脉之机，故归病机。", []], "27397": ["其他", "此段为药物主治，未涉脉象。原文载胸中邪气、热结痛、㖞僻面肿，解结散血、愈漆疮、养筋益气、散诸热、理经脉、消食、利肢节、去五脏烦闷，及产后肚痛血不下、筋骨折伤、续断绝筋骨、小儿解颅不合。所主病机为热结血瘀、筋脉损伤、经脉不利，因无脉象，不作脉学分析。", []], "27398": ["其他", "此段述鹤之形态习性，未涉脉象与病机。原文言鹤大于鹄、丹顶赤目、夜半鸣声唳云霄、啖蛇虺、闻降真香烟则降、其粪能化石，并引《相鹤经》述其阳鸟游阴、羽翮变化、胎化之异。全属物类相感记载，无脉象可析，亦无病机可论，仅归其他。", []], "27399": ["病机", "此段为发明药理，未直接言脉。原文引雷氏序云体寒腹大，全赖鸬鹚；时珍谓诸腹鼓大皆属于热，卫气并循于血脉则体寒，此水鸟气寒冷而利水，寒能胜热，利水去湿。所主病机为热与水湿互结致腹大如鼓，卫气循血脉而体寒，属水湿内停、寒热错杂之候，故归病机。", []], "27400": ["病机", "此段论鸡冠血治风，非论脉。原文“风中血脉则口僻㖞”，指出风邪入于血脉，致口眼歪斜，属血分受风之病机；鸡冠血咸而走血透肌，故能入血搜风。丹者阳中之阳辟邪，乌者阳中之阴治产乳，皆从药性推病机，与脉象无涉。", []], "27401": ["主病", "原文“其脉沉实而滑”，沉主里，实主邪盛，滑主水谷壅积。段中言“脾虚不能制水，水反胜土，水谷不运，气不宣流，故令中满”，正合沉实而滑之脉，主鼓胀中满、小便短涩，为水湿内盛、气机壅滞之实证。", ["沉", "实", "滑"]], "27402": ["病机", "原文“其脉上下行，微弦”，转筋入腹而臂脚直，乃筋脉拘急之象。微弦者，弦主筋急、主痛，微则病势尚轻；脉上下行，形容脉气攻冲不定，与转筋挛急相应，示寒湿伤筋、筋脉失养之病机。", ["弦", "微"]], "27403": ["其他", "此段专列主治病症，未及脉象。原文述疗目痛、决痈疖、女子带下、溺不利、除疝瘕，又治症瘕久痼冷病、痃癖诸块伏梁，能消积除胀、通咽塞口噤。所主皆积冷、瘀滞、疮疡之病机，从药效反推，非凭脉断证。", []], "27404": ["其他", "此段为药物主治条文，无脉象可辨。原文“心腹冷气，小儿五疳，辟疫，治肠风，通利气脉，女子血闭”，点明所治为冷气内积、气脉不通、血闭不行之病机，故能通利气脉、辟疫疳，属寒凝气滞血瘀之候。", []], "27405": ["治法", "此段为方治，未言脉。原文“经脉不通，积血不散”，明示病机为瘀血内积、经脉阻闭。方用乌鸦散，以水蛭、芫青、蒲黄、延胡索破血逐瘀，当归养血，好墨止血，酒下以行药势，属瘀阻经闭之治法。", []], "27406": ["其他", "此段述药之主旨，无脉象。原文“劳损积血，利血脉，安神。治惊邪，癫痫鸡痫，发热狂走”，指出所治为劳损致瘀、瘀阻血脉、神不安舍之病机，故能利血脉而安神，治惊痫狂走之候。", []], "27407": ["病机", "此段论猪肉之害，非论脉。原文“凡猪肉能闭血脉，弱筋骨，虚人肌，不可久食”，指出猪肉滋腻，久食则闭阻血脉、耗弱筋骨、虚人肌肉，病人金疮者尤甚，属食伤致血脉壅闭、正气受损之病机。", []], "27408": ["其他", "本段为药物主治汇录，未涉脉象。原文以“利血脉，散风热，润肺”“破冷结，散宿血”言药效，提示所治在血脉瘀滞、风热壅肺、冷结宿血之病机，故能通小便、除五疸水肿、治痈疽恶疮。诸家所述皆从药性推导主治，非据脉辨证，故无脉象要素可录。", []], "27409": ["其他", "全段列药之主治病症，无脉象描述。原文“补中益气止渴，断暴痢虚弱”“主骨蒸热劳，血脉不行，补羸助气”点明其治在中气不足、虚劳羸瘦、血脉不行及症瘕积聚。所主皆从补虚杀虫、消积之功推出，属本草主治范畴，未及诊脉，故脉象要素为空。", []], "27410": ["病机", "原文两言“脉微欲绝”，成无己释为“阳气太虚，阴气独胜”。脉微欲绝乃阳衰不能鼓动血脉之象，故见厥逆无脉、下利不止、干呕而烦。纯用阳药恐阴气格拒，故加猪胆汁苦寒通脉和阴，使药气相从。此段借脉微欲绝阐明白通汤、通脉四逆汤加猪胆汁之制方深意，主在阳虚阴盛、格拒之病机。", ["微"]], "27411": ["治法", "本段为白通汤加猪胆汁方证与服法，原文虽言“厥逆无脉”，然未以脉名立论，重点在“少阴下利不止”而设温阳通脉、苦寒反佐之法。葱白、干姜、附子温通阳气，人尿、猪胆汁咸苦从阴引阳，治阴盛格阳之厥逆干呕烦。属治法条文，脉象仅作症状描述，故不取脉素。", []], "27412": ["其他", "此段专录猪蹄煮汁之外治主治，无脉象内容。原文“通乳脉，托痈疽”“洗痈疽，渍热毒，消毒气，去恶肉”表明其用在于通乳脉、托毒排脓、清解热毒，故主乳汁不通、痈疽热毒壅滞之证。所论皆外洗、煮羹之法，从药效推主治，未涉及切脉辨证，脉象要素从缺。", []], "27413": ["其他", "全段为犬肉主治，未言脉象。原文“安五脏，补绝伤”“补胃气，壮阳道，暖腰膝”“补五劳七伤，益阳事，补血脉，厚肠胃，实下焦，填精髓”皆示其功在温补下焦、填补精髓、强壮阳气，故所主为虚劳损怯、阳事不举、腰膝冷弱之病机。属本草补益主治，非脉诊条文。", []], "27414": ["其他", "本段录药之主治，无脉象。原文“利血脉，益经气”“补血，主女人血虚风闷”“润肺气，泽皮毛”点明其治在血脉不利、阴血不足、肺虚毛悴。诸家从补血润肺、和酒行药之功推出所主，属本草主治范畴，未据脉立论，故脉象要素为空。", []], "27415": ["其他", "此段列药主治眼疾及疮毒，未涉脉象。原文“青盲，明目”“点赤障、白翳、风泪眼”“治诸疮，能生人身血脉”说明其用在于明目退翳、解毒生肌、通利血脉，故主目睛障翳、疮疡热毒之病机。全属本草外点内服主治，无脉诊内容，脉象要素从缺。", []], "27416": ["治法", "原文仅言「补肾虚，通督脉，治腰痛下痢」，未出脉名。其治在补肾通督，督脉贯脊属肾，肾虚则腰痛，下痢亦由肾关不固。虽无脉象可凭，然从「补肾虚、通督脉」可知病机属肾督亏虚、下元不固，故以补通为法，脉当见虚细弱之类，原文未及。", []], "27417": ["其他", "原文论黄牛、黑牛不可多杀，自死之牛「血脉已绝，骨髓已竭」不可食。此「血脉已绝」非诊脉之脉，乃言牛死血枯髓竭，肉不可食。全段属饮食禁忌，非论病机脉象，故脉象要素为空，主旨归其他，不可强解为脉候。", []], "27418": ["治法", "原文列牛髓主治：补中填骨髓、安五脏平三焦、续绝伤、益气力、止泄利、去消渴、平胃气通十二经脉、润肺补肾泽肌悦面。全段为药效主治，未涉脉象。其病机指向精髓亏虚、脏腑失养、经脉不通，故以填髓通脉为治，脉当虚细，原文未出。", []], "27419": ["病机", "原文论口颊㖞僻「乃风中血脉也」，手足阳明之筋络口，寒则筋急而僻，热则筋缓而纵，「急者皮肤顽痹，荣卫凝滞」。此以寒热分筋急筋缓，指出风中血脉、荣卫凝滞之机，治以马膏摩急、桂末涂缓，急者缓之缓者急之。虽无脉名，然病机在血脉凝滞、寒热偏胜。", []], "27420": ["主病", "原文列主治「伤中，脉绝阴不起」，强志益气、长肌肉肥健、生子，又主小儿惊痫、男子阴痿。其「脉绝阴不起」指阴器不起、脉道衰绝，属伤中精亏、阳气不振之病机。药能益阴气、强志生子，故主虚损阴痿，脉当见虚细弱，原文未出具体脉象。", []], "27421": ["其他", "原文「脉风候」及「水脉风候」皆指骆驼能知泉源伏流与流沙热风将至，非诊人之脉。全段述驼之形性、负重行远、知水脉风候之能，属博物杂录，与医理脉象无关，故脉象要素为空，主旨归其他，不可附会为脉诊内容。", []], "27422": ["治法", "原文列主治补五脏、利大小肠、治口疮、除胸中客热益心肺、除心热肺痿、止渴止嗽止吐血、润毛发、益虚劳润脏腑泽肌肤和血脉止急痛治诸疮。全为药效，未出脉象。病机属脏腑虚损、客热伤肺、血脉不和，故以润补和血为治。", []], "27423": ["主病", "原文主治「润五脏，利大小便，益十二经脉。微动气」，又治赤白痢，小儿服之弥良。「微动气」言药力微动气机，非脉之动。其病机在五脏失润、经脉不利、气机微滞，故以润利通脉为治，赤白痢亦取通利之意。原文未出脉象，脉素为空。", []], "27424": ["病机", "此段论牛黄治风之理，非论脉。李杲谓牛黄入肝治筋病，中风入脏者用牛、雄、脑、麝引风出；若风中腑及血脉者用之，恐引风邪流入骨髓，如油入面。时珍以牛黄为牛病所结，病在心及肝胆之间，故能治心及肝胆之病，取同类相治之意。", []], "27425": ["病机", "此段集解狗宝，非论脉。时珍述狗宝生癞狗腹中，状如白石，剖之心已化似石非石，而包膜络之如寒灰，观其脉理犹是心。又举人患石淋有石块、龙髓虎光成石等，说明万物变化不可一概断，狗宝亦物病而人以为宝。", []], "27426": ["主病", "此段主治人病马痫，症见筋脉不能自收、周痹肌肉不仁，属筋脉失养、痹阻不通之病机。以马肉一斤，豉汁煮熟，入五味、葱白，作腌腊及羹粥频食，白煮亦可，取马肉补益以缓筋脉、通痹着，为食治之方，非脉诊之论。", []], "27427": ["兼症", "此段附方治中风痹疾，症见心肺风热、手足风痹不随、筋脉五缓、恍惚烦躁，以熊肉合豉汁、葱姜椒盐作腌腊空腹食之；又治脚气风痹、五缓筋急。脉五缓指筋脉弛缓无力，由风热痹阻、气血不荣筋脉所致，故用熊肉食治以缓其急。", ["缓"]], "27428": ["病机", "此段发明羚羊角入厥阴肝经之理。肝主风，在合为筋，其发病则小儿惊痫、妇人子痫、大人中风搐搦及筋脉挛急、历节掣痛，羚角能舒之。脉挛急即筋脉拘急之象，由肝风内动、筋脉失养所致，故以羚角平肝舒筋，同气相求。", ["急"]], "27429": ["其他", "此段集解鹿之形态习性，非论脉。述鹿马身羊尾、牡者有角夏至则解、牝者无角，性淫聚麀，喜食龟能别良草，卧则口朝尾闾以通督脉。又引殷仲堪云鹿以白色为正，《述异记》言鹿千岁为苍、五百岁为白为玄，玄鹿骨黑可脯食长生。", []], "27430": ["治法", "此段述鹿肉功用，非论脉。华佗云中风口偏者以生肉同生椒捣贴，正即除之；孟诜谓补虚羸瘦弱、调血脉；时珍谓养血生容、治产后风虚邪僻，《外台》有鹿肉汤。诸说皆以鹿肉补虚养血、调血脉，为食治之法，非脉象主病之论。", []], "27431": ["其他", "此段时珍评鹿之益人，非论脉。邵氏言鹿之一身皆益人，或煮或蒸或脯，同酒食之良。时珍谓鹿乃仙兽，纯阳多寿之物，能通督脉，又食良草，故其肉、角有益无损，并斥陶说为妄。全段论鹿之药性补益，与脉象病机无涉。", []], "27432": ["治法", "原文以“伤中绝脉”为主治，指中焦损伤、血脉虚绝之证，故用酒和药以通血脉、蜜煮以润养，并治筋急痛、咳逆。诸法皆从补阴强阳、生精益髓立法，使血脉得充、筋脉得养，则绝脉可复。脉象未明，然“绝脉”示虚极欲绝之候。", []], "27433": ["治法", "本条明言“治肺痿咳嗽，伤中脉绝”，以鹿髓、地黄汁、酥蜜等润养肺金、填补精髓，杏仁桃仁兼降肺气。脉绝由伤中津枯、肺叶焦痿所致，故用膏煎含咽，徐徐润下，使肺得濡养、脉道复通。脉象未载，主旨在治法。", []], "27434": ["治法", "原文主治风痹、虚劳，强调“添精益髓，益血脉，暖腰膝”，又“滋阴养血，功与茸同”。风痹日久必耗血脉，虚劳则精血亏虚，故以麋角酒服补虚通痹。所治偏于丈夫冷气、筋骨疼痛，皆精血不足、风寒痹阻之候，脉象未明，属治法范畴。", []], "27435": ["治法", "麋角丸治五痿，症见“血脉枯槁，肌肤薄著，筋骨羸弱，爪枯发落”，皆精血亏耗、血脉不荣之象。方以麋角、熟地、附子温补精血、通利血脉，使痿弱得振。原文未及脉象，主旨为五痿之治法，脉当见虚细无力之候。", []], "27436": ["治法", "本条主治“脚痹风湿气”，以“活血脉，暖腰膝”为功。脚痹多因风湿阻络、血脉不通，腰膝失温，故用此药活血通痹、温养下元。原文未载脉象，然风湿痹阻之脉多沉弦或濡缓，此属治法条目，示以活血温通为要。", []], "27437": ["其他", "藏器论兔肉禁忌，言久食“绝人血脉，损元气、阳事，令人痿黄”，并诫妊妇忌食。血脉绝、元气损则脉当见虚细无力或涩滞，痿黄亦为气血衰败之征。此条重在饮食禁忌与久食伤正之害，非论脉，故归其他。", []], "27438": ["主病", "原文主“水气胀满，热毒风，骨蒸热劳，血脉不行，荣卫虚满，女子经络不通”，皆由热毒壅滞、血脉不行、荣卫虚满所致。血脉不行则脉多涩滞，荣卫虚满则脉见虚大或弦急。又言“消男子阳气，不宜多食”，示其性偏寒利，久食伤阳。", []], "27439": ["病机", "原文言“风热久积，血脉不行，结成痈疽”，指出风热蕴结日久，血行壅滞，聚而成痈疽。血脉不行则脉多弦数或涩，热积则数。食之可消，示其能散风热、通血脉。又主疮疥痔瘘、杀蛔虫，皆风热湿毒为患，脉象未明而病机清晰。", []], "27440": ["其他", "本段论人尿（童便）药性及服法宜忌，非脉诊内容。原文提出'气血虚无热者，尤不宜多服'，又载震亨'阴虚火动，热蒸如燎，服药无益者，非小便不能除'，时珍则谓'小便性温不寒'。诸家争议在寒温与宜忌，全段无脉象描述，故脉象要素为空，主旨属药性讨论，归入其他。", []], "27441": ["病机", "本段论泪为肝之液，'五脏六腑津液皆上渗于目'。悲哀笑咳则'火激于中，心系急而脏腑皆摇'，摇则'宗脉感而液道开，津上溢'，故涕泣出，喻如'甑上水滴'。所论为情志动火、宗脉感而液道开之病机，非脉象，故脉象要素为空，归病机。", []], "27442": ["治法", "本段为天灵盖散附方，主'追取劳虫'，治传尸劳瘵。方以天灵盖、槟榔、阿魏、麝香、甘遂等为末，用童便及葱白、薤白、青蒿、桃柳桑枝等煎汤调服，五更进药，'取下虫物'，并据虫'觜青赤黄色可治，黑白色难治'判断预后。全段言治法与服药法，无脉象，脉象要素为空。", []], "27443": ["妇人", "本段为河车丸、大造丸附方，治'妇人瘵疾劳嗽，虚损骨蒸'。紫河车'得先天之气'，补真元以疗虚损。原文脉象写作'脉散'，散脉主气血耗散、虚损劳瘵，与骨蒸劳嗽之虚象相应。然段中主体为妇人瘵疾用方，故归妇人，脉散示虚损耗散之机。", ["散"]], "27444": ["妇人", "本段引《易》'一阴一阳之谓道'，论男女构精、成男成女之理，列举褚澄精血先后、道藏经月水日数、东垣血海始净、圣济经左右气血诸说。原文脉象写作'脉之左右浮沉'，以左右浮沉分阴阳气血之动，辨胎孕男女。全段主旨属妇人胎孕之说，脉象要素取浮、沉。", ["浮", "沉"]], "27445": ["妇人", "本段载唐山民妇孕而'儿从胁生'异闻，又论'阳生阴长，孤阳不生，独阴不长'为常理，而'思士不妻而感，思女不夫而孕'、妇女生须、丈夫出湩、男子产儿等，归为'气脉时有变易'。所论为妇人异常胎孕及气脉变易之机，无具体脉象，脉象要素为空，归妇人。", []], "27446": ["其他", "本段为敏按语，论土为万物之母，'凡物得土之精者，均入脾胃而能扶正气'，正气足则百病自除。又谓水'乃川脉得先天之气，借地力宣泄'，有厚胃除疾之功，出七日即涸'并具来复之机'，并及鹤庆温泉浴愈痞疾。全段言物理药性，无脉象，脉象要素为空，归其他。", []], "27447": ["其他", "本段引单杜可语，述蛟初起时'水如箭，清如泉脉'，渐涌而高，合天雨则势大飞腾，穴口泛水名'发洪'；并载灌河水、塞月经秽布止蛟，及服蛟水作胀用千里长流河水煎服可解。所论为蛟水成因与解法，'泉脉'乃比喻水势，非诊脉，脉象要素为空，归其他。", []], "27448": ["其他", "本段讲四时变火以救时疾，榆柳火利肝胆调筋脉，枣杏火养心血通神明，柞楢火利肺滋本源，槐檀火补肾益阴血，桑柘火补脾胃壮真元。虽言'调筋脉''和血脉'，但非论脉象，而是以火政配五脏，属养生却病之法，故脉象要素为空，主旨归其他。", []], "27449": ["其他", "本段为神效干丹方，药性坚阳益肾、强筋力、和血脉、种子如神，列举天雄、雄精、鸦片、蟾酥、人参等配制研擦之法。全段言方药组成与功效，未涉及脉象诊法，'和血脉'仅指药效，非脉象描述，故脉象要素为空，主旨属其他。", []], "27450": ["其他", "本段辨野术产地与形质，述鹤山产者鹤颈鹤头、皮细带黄、切开有朱砂点，于术野生者内点似朱砂猩红如洒血，冬月采取形味方全。全段论药材鉴别，未及脉诊，'龙脉'指地脉而非脉象，故脉象要素为空，主旨归其他。", []], "27451": ["治法", "本段芎归饮治失血涌吐，因饱食用力或持重努伤脉络，用当归酒浸、抚芎微炒，水煎酒煎，取其引血归经；并治跌扑坠打伤脉络大吐者，有瘀血加大黄、桃仁、红花、郁金等审症酌加。全段为治法方药，未述脉象，故脉象要素为空，主旨属治法。", []], "27452": ["其他", "本段引四川通志，言雪山石块上所出之物有雌雄二种，出必双出，能补元气、益髓脉，功同人参。'益髓脉'指补益精髓血脉之药效，非脉象描述，全段为药物产地与功用记载，故脉象要素为空，主旨归其他。", []], "27453": ["主病", "本段辨痢之初起实热实积，外候身热烦躁、唇焦口渴、肚疼窘迫、里急后重、舌上黄胎，六脉洪数。洪为邪盛，数为热炽，脉症相合，故主实热实积之痢，治宜疏利或寒下，积去而和。与虚人冷积致痢之外无烦热、内无急痛、小便清长形成对照，洪数正是实热可下之凭。", ["洪", "数"]], "27454": ["其他", "本段仅言药性温，行血脉，治风痹、跌扑损伤、双单蛾痛风。'行血脉'指药效行血通脉，非脉象描述，全段为药物功用主治，未涉及诊脉，故脉象要素为空，主旨归其他。", []], "27455": ["其他", "本段描述草药形态：形如兔耳，贴地生叶，上面淡绿下面微白，有筋脉，缘边黄毛茸茸作金色，初生叶稍卷如兔耳形，沙土山上最多。'筋脉'指叶上脉络，非脉象，全段为药材形色产地记述，故脉象要素为空，主旨归其他。", []], "27456": ["其他", "原文为滇南草药「蟢儿草」的产地与形态考述，仅言「能通血脉」，未涉及具体脉象。所谓通血脉，指此草有活血通络之功，非论脉之浮沉迟数。全段主旨在于辨识药物基原，与脉诊病机无关，故脉象要素为空，不可强附。", []], "27457": ["其他", "原文述某药味苦微辛，功能「去风疏经活血，健筋骨，通络脉」，主治损伤痹症、麻木皮风。全段为药性功效记载，未出现任何脉象描述。其「通络脉」指药物通利经络之效，非脉象要素，故不能据以推断病机脉证，脉象要素从缺。", []], "27458": ["病机", "原文述豨桐丸治风湿内湿外邪「传于四肢，脉络壅塞不舒」，致两足软酸疼痛、不能步履，或两手牵绊不能仰举，状似风瘫。此论风湿痹阻、脉络壅塞之病机，虽未言脉，然「脉络壅塞」即气血痹阻之由，与痹症脉多弦涩相应，属病机范畴。", []], "27459": ["其他", "原文记粤东藤类药「微细如发，直起数丈」，其花与子入药，「浸酒服，补筋骨，祛风解毒，能循脉络，无微不到」。全段为药物形态与功效描述，「循脉络」指药力走窜通络之性，非脉象。无脉可辨，故脉象要素为空，主旨归其他。", []], "27460": ["其他", "原文考述雪莲产地、形态与药性，言其「性热」，土人用作助阳要药，又引「阴极而阳生」之说，并警示「其祸乃同砒鸩」。全段论药性寒热与功用利弊，未涉脉象。所谓性热助阳，是从药性言，非从脉言，故脉象要素缺如。", []], "27461": ["其他", "原文为保真丸方药组成与制法，述其「通经络、和百脉、壮腰肾、健脾胃」，用玫瑰花、补骨脂、菟丝子等。全段属方剂记载，「和百脉」指调和气血百脉之效，非脉象描述。无脉可析，脉象要素为空，主旨归其他。", []], "27462": ["其他", "原文极简，言某根「治跌打损伤，又治咳嗽，暖筋骨，疗痛风，性能追风活血，兼通血脉，消结毒」。全段为药物主治与功效，「通血脉」指活血通络之功，非论脉。既无脉象，亦未展开病机，故脉象要素从缺，主旨归其他。", []], "27463": ["病机", "原文述某药「下气消痰，通和血脉，能返魂」，治魂神不安、惊越失魂、神不守舍等症，天王补心丹治怔忡用之。此论痰气上扰、血脉不和致心神不守之病机，虽未言脉，然「通和血脉」点出气血失和之由，与怔忡脉多细弱或结代相应，属病机范畴。", []], "27464": ["其他", "此段述化州仙橘之产地、形色、采摘与真伪，全无脉象可言。原文强调「其实非橘，皮厚肉酸，不中食」，其皮「厘为五片七片，不可成双」，重在辨真伪与贵重，非论病机脉候，故不涉主病。", []], "27465": ["其他", "此段辨化州橘红与乳柑皮、柚子皮、甜橘红之真伪，以「皮色筋味」为据。末言真化橘红「味苦辛，入口芳香」，然「其性酸削，能伐生气，消痰虽捷，破气损人，不宜轻用」，属药性利弊之论，非脉象主病之文。", []], "27466": ["病机", "原文言橘丝「专能宣通经络滞气」，用以治「卫气逆于肺之脉胀」有效。其病机在卫气逆乱、经络滞气，气壅于肺而致脉胀，故以宣通为治。此段论药效所主之病机，非直接描述脉象，故脉象要素为空。", []], "27467": ["病机", "此段极简，言其功在「通经络滞气脉胀，驱皮里膜外积痰，活血」。病机为经络气滞、痰积膜外、血行不畅，故见脉胀等症。原文未及脉象形态，只述所主病机与功效，脉象要素无从取字。", []], "27468": ["病机", "原文述其味「甘、微带苦，性平」，功能「开膈，补腰肾，和血脉，散一切瘀血，生一切新血」，故「产后及吐血者食之尤佳」。病机着眼瘀血内阻、新血不生、血脉不和，以甘平之品和血散瘀生新，非论脉候。", []], "27469": ["病机", "此段言其「通百脉，强筋骨，和中益气，润肌肤，好颜色」。病机在百脉不通、筋骨不强、中气不足，故以甘平之品通脉强筋、和中益气。原文只述功用所主，未及脉象形态，脉象要素为空。", []], "27470": ["病机", "原文主「治吐逆不食，关格闭拒不通，脾虚下陷，肛门坠脱不收」，又「清热，凉大肠，去积血，利百脉，通调水脏」。病机涉及脾胃虚陷、关格不通、大肠积血、水脏失调，以甘平之品升清降浊、凉血通脉，非脉象之论。", []], "27471": ["病机", "原文主「宁心志，养血脉，解暑渴，利水道，生津液，止逆气喘急」，又治「骨蒸劳热、四肢瘦削如枯柴」。病机为血脉失养、津液不足、虚热内蒸、肺气上逆，故以甘平之品滋养清润。全段论药效所主病机，未涉脉象。", []], "27472": ["治法", "原文言味甘生津、滋润血脉、调营卫、利水，全从药性立论，未及脉象。其滋润血脉即养脉中之营，调营卫即使脉道和畅，利水则通脉中水气之壅。此段以甘味生津为枢，津充则脉得濡养，营卫调则脉行有序，属以药性调脉之治法，非凭脉断病。", []], "27473": ["治法", "原文称味甘辛窜达、捷通百脉、益元生气，少饮理怯如神。辛能窜达，故通百脉之滞；甘能益元，故生气有源。脉道赖气以行，气怯则脉弱不行，此药通脉益气，使脉复其常。全段论药性通脉之功，属治法范畴，未涉具体脉形。", []], "27474": ["治法", "原文谓味甘辛性温，佐药发痘浆、行血、益髓脉、生津液。辛温行血则脉道通利，甘润益髓则脉得充养，生津则脉不燥涩。痘浆之行赖血与津，脉为血之府，故益髓脉即所以助痘透发。此段以药性说明通脉行血之理，属治法，非脉诊之文。", []], "27475": ["其他", "原文考黑大豆入肾益水、活血利水除胀，并及穞豆治产后血风冷痛。肾主水，水足则脉有所养；活血利水则脉中血滞水壅可去。歌云调中下气、追风活血，皆从药性言血脉通利。全段为药性考据，未言脉象，故归其他，不涉具体脉形与主病。", []], "27476": ["其他", "原文以脉散缓与沙土同形容甘薯质地，非诊脉之象。散缓本指脉来涣散迟缓，此借以状薯肉松软如沙土，属比喻之辞。甘薯补虚乏、益气力、健脾胃、强肾阴，脾肾充则脉有所本，散缓之喻正见其质松而性平补。此段主在录甘薯功用，脉散缓为借喻，故归其他。", ["散", "缓"]], "27477": ["其他", "原文述石耳产地形态、采撷烹食之法，言其味甘腴、性平无毒、润肌童颜，在木耳地耳之上。全段为本草形态与食用记载，未及脉象，亦无病机脉理可析。虽言润肌童颜，属药性滋养之功，非脉诊内容，故列其他，脉象要素为空。", []], "27478": ["治法", "原文言毛笋味甘性平，利九窍、通血脉、化痰涎、消食胀。通血脉即通脉中壅滞，痰涎消则脉道不为痰阻，食胀去则气机畅而脉行利。此以笋之通利说明血脉壅滞可借药食以通，属治法范畴，未言具体脉形，故脉象要素为空。", []], "27479": ["治法", "原文谓味甘温，利九窍、通血脉，治吐血衄血及产后心腹痛一切血症，消痰滑肠、透毒发痘疹。通血脉而治血症，是血行则脉和；产后心腹痛属血滞，血滞去则脉通。又言小儿脾虚多食难化，示通利之品有宜忌。全段以药性论治血通脉，属治法，未涉脉形。", []], "27480": ["其他", "原文为疮毒外治方，仅言\"用番打马\"等药及\"以指研开\"，脉象写法\"动脉、脉\"系误标，实非论脉。文中\"疮毒盛而人壮健能食者\"以体质强弱分药量，未涉脉诊，故不能据\"动\"字推演病机，只属方药用法记载。", ["动"]], "27481": ["其他", "原文述某药味咸甘性平，陈芝山云\"和中益肾，养胃气，补虚劳\"，陆瑶云\"生津，益血脉，固骨髓，壮阳\"等，全为药性功效，未及脉象。\"益血脉\"指药效而非脉形，故脉象要素为空，主旨属药性记载而非脉学病机。", []], "27482": ["其他", "原文论龙涎功效，如\"活血，益精髓，助阳道，通利血脉\"，又载廖永言\"利水通淋散症结\"及倭夷制丸等事，皆属药性杂记。\"通利血脉\"为药效描述，非脉象，故不取脉字，亦不能据此论病机。", []], "27483": ["其他", "原文述某食物\"性温味甘，食之生胃津，益肺气，补血脉，增髓去热\"，\"止嗽定喘，功同燕窝、蛤蚧\"，纯为食疗功效。\"补血脉\"指补益血脉之效，非脉形，故脉象要素空，主旨属药性而非脉诊病机。", []], "27484": ["其他", "原文辨虾春性味，言\"鲜者味甘，腌者味咸甘，皆性温助阳，通血脉\"，又引敏按辨虾春非虾子。\"通血脉\"为药性功效语，非脉象，故不取脉字；主旨为食物考辨，非论脉主病。", []], "27485": ["其他", "原文前半述某物\"补肾经，益精髓，消痰涎，摄小便，壮阳疗痿\"，后半载盛天然治妇人眼鼻口耳发根皆出血案，因受惊兼燥烈之气致\"血溢奔腾\"。全段无脉象描述，\"生百脉血\"亦药效语，故脉空，主旨属杂记医案。", []], "27486": ["其他", "原文考蝇虎名物，引古今注、潜确居类书等，言其\"性频动而不静，取以调血脉，治跌打\"。\"调血脉\"为药效语，非脉形；全段属名物考证，未论脉诊，故脉象要素为空，主旨归其他。", []], "27487": ["其他", "原文叙先君子艰嗣、行利济事得子，及筑塘御潮、捐俸疗疫等事，末言\"一子业儒，一子业医\"，课以灵素、难经、伤寒论。全段为家世记事，无脉象描述，故脉空，主旨属其他而非脉学病机。", []], "27488": ["病机", "原文强调“先候病机”，以“五脏未虚，六腑未竭，血脉未乱，精神未散”为可治之机。脉未乱即血脉未乱，提示邪未深入、正气尚存，故“食药必活”；若病已成则半愈，病势已过则难全，说明脉象之乱与不乱关乎病机浅深及预后。", []], "27489": ["病机", "此段未言具体脉象，而论“病之所由来虽多，而皆关于邪”，邪包括风寒暑湿、饥饱劳佚等不正之因。邪伤经络，传入脏腑，随其虚实冷热结以成病，故诊脉当察邪正虚实，以知病机所在。", []], "27490": ["治法", "原文按病位分服药先后：胸膈以上先食后药，心腹以下先药后食，四肢血脉宜空腹旦服，骨髓宜饱满夜服。虽未涉脉象，但示服药须因部位而异，以顺病机、助药力。", []], "27491": ["其他", "此段述医史源流，赞张仲景“善诊脉，明气候，以意消息之”，强调诊脉须参合气候、药性以消息病机。未出具体脉象，主旨不在主病，而在说明脉诊与用药相合之理。", []], "27492": ["其他", "此段为药物主治，言味甘平无毒，治五脏百病、柔筋强骨、利血脉、治妇人带下等。虽“利血脉”一语涉及血脉，但非论脉象，故不取脉素；主旨属药性主治，非脉学病机。", []], "27493": ["其他", "此段述药物主治，味甘微寒，养精神、安魂魄、通血脉、止烦满消渴等。文中“通血脉”指药效，非脉象描述；全段为药性功用，不涉诊脉病机。", []], "27494": ["其他", "此段为药物主治，味甘酸寒，治青盲耳聋、利九窍、通血脉、益肝气、利水道等。“通血脉”亦属药效，非脉象；主旨为药性功用，不归脉学病机。", []], "27495": ["其他", "原文“治五脏十二经脉中百二十疾”指药治范围，非脉象；味苦辛大寒，主五脏积热、胃胀闭、涤去蓄结饮食、推陈致新等。全段为药性主治，不涉具体脉象与病机分析。", []], "27496": ["其他", "此段为硝石（朴硝）药性主治，非脉学内容。原文述其味辛苦大寒，主治五脏积聚、久热胃闭，除邪气、破留血、腹中痰实结搏，通经脉、利大小便及月水。全段无脉象描述，故脉象要素为空，主旨属本草主治范畴，列其他。", []], "27497": ["其他", "此段述方石（直石）药性，味辛苦寒无毒，主治身热、胃中结气、四肢寒厥，利小便、通血脉，明目去翳、去三虫、杀蛊毒、止消渴、下气、除胁肋肺间邪气。原文纯为药物主治，未涉脉象，故脉象要素为空，归其他类。", []], "27498": ["其他", "此段述黄石药性，味苦辛大寒无毒，主治胸中留热、结气、黄疸，通血脉、去蛊毒，并记恶巴豆。全段为药物主治与配伍禁忌，无脉象描述，脉象要素为空，主旨不属脉学诸类，列其他。", []], "27499": ["其他", "此段述代赭（须丸、血师）药性，味苦甘寒无毒，主治鬼疰、贼风、蛊毒，杀精物恶鬼，治腹中毒邪气、女子赤沃漏下、带下百病、产难胞衣不出、堕胎，养血气、除五脏血脉中热及血痹血瘀、惊气入腹、阴痿不起。纯属本草主治，无脉象，列其他。", []]});